window.__SUMMARY_PARTS__=window.__SUMMARY_PARTS__||[];window.__SUMMARY_PARTS__.push([{"i":2000,"as":"工信部印发《“人工智能+信息通信”创新发展实施意见（2026—2028年）》，部署17项重点任务以推动行业智能化升级。目标到2028年初步形成融合互促的格局，信息通信网络实现高等级自智，打造30个以上高价值典型场景，并使城域算力1毫秒时延圈覆盖率达到75%以上，进一步强化算网基础设施对AI的支撑。","scd":null,"kp":[]},{"i":2001,"as":"雷普索尔（Repsol）宣布将其在西班牙总装机容量为705兆瓦的可再生能源项目的股份出售给马斯达尔（Masdar）。这笔交易标志着两家能源企业在西班牙可再生能源资产领域的所有权转移与战略合作。","scd":null,"kp":["交易规模[雷普索尔出售股份]: 705 MW"]},{"i":2002,"as":"GreenGo成功获得意大利南部一项12兆瓦风电项目的建设批准。该项目获批将进一步扩大GreenGo在意大利本土的风电装机规模，推进地区可再生能源设施的部署与清洁能源的供应。","scd":null,"kp":["项目容量[意大利南部风电项目]: 12 MW"]},{"i":2003,"as":"光伏产业链上游价格跌幅收窄，组件与电池片进入底部磨合期。地面电站TOPCon组件价格降至0.72-0.73元/瓦，HJT组件降至0.76元/瓦。当前国内集中式电站开工率小幅回暖至45%，分布式市场询价活跃。硅料价格持续下行，N型复投料均价降至3.39万元/吨，总库存约52万吨，硅片库存攀升至27.5吉瓦创历史新高。","scd":null,"kp":["组件价格[地面电站TOPCon210双面]: 0.730元/W","组件价格[TOPCon矩形双面]: 0.720元/W","组件价格[HJT矩形双面]: 0.760元/W","集中式电站开工率[6月上旬国内]: 约45%","组件排产规模[6月份]: 38-39 GW"]},{"i":2004,"as":"南网能源发布公告，拟在北京产权交易所公开挂牌转让旗下24个智慧绿电项目资产及3个相关项目公司股权，涉及光伏项目总装机规模达444.77兆瓦，资产总额13.44亿元。其中342.08兆瓦的项目资产评估增值5.53%，另外102.69兆瓦的项目股权评估减值11.83%。","scd":null,"kp":["装机容量[拟转让24个智慧绿电项目]: 约342.08MW","评估增值率[24个智慧绿电项目资产]: 5.53%","装机容量[拟转让3个智慧绿电项目公司股权]: 约102.69MW","评估减值率[3个智慧绿电项目资产]: 11.83%","涉及光伏项目总规模[南网能源拟转让资产]: 444.77MW"]},{"i":2005,"as":"异质结光伏企业江苏宝馨科技面临重大诉讼，原告鄂托克旗诚园绿能请求法院判令被告支付9930余万元股权回购款及相关利息。起因是双方原定合作建设2GW光伏异质结电池及组件项目，但在合作期间，被告被指控未经合规程序挪用项目公司资金逾2.54亿元，此前法院一审判决已认定其存在抽逃出资行为。","scd":null,"kp":["规划产能[鄂托克旗光伏异质结及切片生产基地]: 2GW光伏异质结电池+2GW光伏异质结组件+2GW薄片化切片","股权回购款[纠纷案诉讼请求一]: 9930.943万元","计息年利率[股权回购款]: 6%"]},{"i":2006,"as":"《海南藏族自治州促进清洁能源产业发展条例》获青海省人大常委会批准，将于2026年9月1日起施行。该条例优先支持沙戈荒大基地及光伏治沙项目落地，通过立法破除项目合规用地与审批制度障碍。同时，条例明确推进水电、光热等调节电源建设，规范配套电网布局，并拓宽绿电跨省送出与交易消纳渠道。","scd":null,"kp":["[《海南藏族自治州促进清洁能源产业发展条例》]: 2026年9月1日起施行，明确沙戈荒大基地及光伏治沙生态修复项目优先落地"]},{"i":2007,"as":"永珈光能近日完成由普朗克创投投资的A轮融资。该公司专注于单结及全钙钛矿叠层电池开发，已建成兆瓦级初试线，实现30cm×30cm及以下尺寸产品量产，单结与叠层电池实验室转换效率分别达27.5%和32%。企业计划未来三到五年内筹建大尺寸GW级产线，全面覆盖集中式分布式电站等应用场景。","scd":null,"kp":["[永珈光能生产线]: 建成兆瓦级初试线","产品尺寸[定制化钙钛矿量产产品]: 30cm×30cm及以下","[研发方向]: 单结钙钛矿电池、全钙钛矿叠层电池及柔性钙钛矿光伏器件"]},{"i":2008,"as":"中国烟草总公司下属湖南中烟宣布中止永安科技园1.817兆瓦光伏发电合作项目。原中选供应商安徽幂能科技因被查实存在影响采购公正的违法违规行为，致使采购活动中止并将重新招标。该供应商此前曾以0.54的超低折扣率中标，但未符合招投标关于合规性与业绩资质的严格规范。","scd":null,"kp":["折扣率[永安科技园光伏发电项目中选]: 0.54","装机规模[永安科技园光伏发电合作项目]: 1.81713MW","业绩容量要求[光伏项目报价人]: 同类项目累计已备案或已竣工投产总容量不低于18MW"]},{"i":2009,"as":"内蒙古自治区能源局发布公告，公开征集《内蒙古自治区电力条例》立法建议。该《条例》已列入自治区人大常委会2026年立法项目调研计划。意见征集截止时间为2026年7月15日，有关单位和个人可通过信函或电话等方式向自治区能源局法规处反馈意见。立法建议需围绕电力行业实际，解决客观问题并促进行业高质量发展。","scd":null,"kp":["[《内蒙古自治区电力条例》]: 列入2026年立法项目调研计划，于7月15日前征集立法建议"]},{"i":2010,"as":"苹果公司公布一项全新电化学铝回收专利申请。该技术采用基于氯化铝的熔融电解质盐结合电化学精炼方法，在125℃至200℃的低温环境下，从废弃铝合金（如CNC加工碎屑）中提取高纯度铝。过程中废铝合金作为阳极，纯铝作为阴极，通电后铝离子在阴极沉积，杂质保留在阳极。该工艺降低了能耗和设备成本，且电解过程可根据能源供应情况灵活暂停或重启。","scd":null,"kp":["工作温度[废旧合金提纯铝电化学工艺]: 低于200℃（部分方案可低至125℃）","电解质盐[低温铝回收工艺]: 基于氯化铝的熔融电解质盐","[电极设置]: 废铝合金作为阳极、纯铝作为阴极"]},{"i":2011,"as":"千里科技控股子公司千里智驾以2590.8万元收购宁波市融感科技有限公司100%股权。融感科技成立于2023年，主营视觉与毫米波雷达融合传感器，基于AI算法提供点云输出。此次收购旨在构建覆盖L2至L4级别的全栈式智能驾驶解决方案。此外，吉利中央研究院辅助驾驶团队近期将被整合入千里智驾与极氪的合资公司。","scd":null,"kp":["收购金额[千里智驾收购融感科技100%股权]: 2590.8万元","[融感科技核心技术]: 基于AI算法的视觉加毫米波雷达融合传感器","[收购战略目的]: 构建覆盖L2至L4级别的全栈式智能驾驶解决方案"]},{"i":2012,"as":"小米汽车公布YU7 GT续航测试及YU7标准版安全配置信息。YU7 GT在续航测试中行驶503.7公里后剩余23%电量，平均电耗14.9kWh/100km，满电表显归零预计总续航约663.7km，CLTC续航达成率94.1%。车辆前电机搭载智能脱开机构，经济模式下可与半轴解耦以减少拖拽损耗。YU7全系配备三重冗余车门把手，极端场景下支持中控解锁及机械开门。","scd":null,"kp":["平均电耗[小米YU7 GT综合续航测试]: 14.9kWh/100km","续航达成率[对比CLTC 705km标称续航]: 94.1%（满电表显归零总计可行驶约663.7km）","平均电耗[环湖+城市路段]: 11.4kWh/100km","车门把手[YU7全系配置]: 三重冗余（极端场景支持中控解锁与机械开门）"]},{"i":2013,"as":"","scd":null,"kp":[]},{"i":2014,"as":"","scd":null,"kp":[]},{"i":2015,"as":"华为开发者大会2026将于6月12日至14日举行。官方议程显示，大会将于6月13日的智慧出行生态峰会上正式发布全新的HUAWEI HiCar 7.0手车互联解决方案。HiCar是华为推出的手机与汽车互联产品，用户可通过车机使用手机导航、音乐及语音交互等功能。本届大会还将发布AI核心能力及生态成果。","scd":null,"kp":["[HUAWEI HiCar 7.0]: 6月13日发布的手车互联智慧出行解决方案"]},{"i":2016,"as":"","scd":null,"kp":[]},{"i":2017,"as":"","scd":null,"kp":[]},{"i":2018,"as":"美国加州河滨县交通委员会启动“智能高速公路”试点项目，通过算法控制入口匝道信号灯以缓解拥堵。该项目覆盖15号州际公路北向约8英里路段，系统基于道路传感器实时监测交通并动态调节放行时间。项目总耗资3300万美元，试运行两年。相比扩建车道，该软件方案成本更低，旨在创造持续稳定的车流。类似技术此前已在澳大利亚和科罗拉多州投入使用。","scd":null,"kp":["试点项目覆盖里程[首期]: 约12.9公里","匝道等待时间[算法控制系统]: 可能达4分钟或更长","项目总耗资[智能高速公路试点]: 3300万美元","试运行周期[智能高速公路]: 两年","匝道信号灯控制方式[智能高速公路]: 交由基于实时路况的算法控制"]},{"i":2019,"as":"华为针对MatePad Edge和MatePad Pro Max平板推送HarmonyOS 6.1.0.125版本系统更新。新版本解决了设备在切换电脑模式或桌面时导致应用关闭的痛点。升级后，部分支持应用在切换模式后可继续运行使用。MatePad Edge需升级至6.1.0.125SP52及以上，MatePad Pro Max需升级至6.1.0.125及以上版本。","scd":null,"kp":["系统版本要求[HUAWEI MatePad Edge]: HarmonyOS 6.1.0.125SP52及以上版本","系统版本要求[HUAWEI MatePad Pro Max]: HarmonyOS 6.1.0.125及以上版本","应用状态[平板切换模式/桌面时]: 支持部分应用在切换后可继续使用"]},{"i":2020,"as":"亚马逊创始人贝索斯表示，AI不会造成大规模失业，反而会提高生产力并创造十倍以上的机会，最终导致经济出现劳动力短缺。他当前联合创办的AI公司Prometheus估值超2780亿元人民币，致力于打造“通用AI工程师”以提升设计和制造复杂实体产品的效率。贝索斯认为，AI让发明变得更便宜、更快，推动多个领域进入黄金时代。","scd":null,"kp":["AI模型定位[Prometheus]: 打造“通用AI工程师”以设计和制造喷气发动机等复杂实体产品","融资金额[Prometheus]: 120亿美元","团队规模[Prometheus]: 约150人","生产力赋能目标[Prometheus]: 使更小的团队能在更短周期内完成规模大得多的事情"]},{"i":2021,"as":"开源OpenHarmony 7.0首个测试版已提交平台。该版本实现更精细的应用控制，支持获取Ability退出原因及锁屏通知控制等；界面交互新增动态布局和组件复用；窗口管理引入标准悬浮窗；ArkWeb内核升级至Chromium 144，支持URL白名单控制；音视频方面支持HDR效果与多屏幕录制。此外，系统还新增了应用间内容嵌入协同编辑服务，并丰富了图像、音频、相机等专业处理能力。","scd":null,"kp":["方舟Web内核版本[OpenHarmony 7.0 Beta1]: Chromium 144","应用程序控制能力[OpenHarmony 7.0 Beta1]: 更精细化，支持获取Ability退出原因及通知自定义铃声等","窗口管理能力[OpenHarmony 7.0 Beta1]: 新增标准悬浮窗、按需销毁窗口页面内容","音视频处理能力[OpenHarmony 7.0 Beta1]: 支持HDR效果、多屏幕录制、Cinepak编解码","服务能力[OpenHarmony 7.0 Beta1]: 新增Content Embed内容嵌入服务支持应用间文档协同编辑"]},{"i":2022,"as":"宝马M部门预告将于明日发布一款疑似基于全新i3打造的纯电性能轿车。新车在勒芒耐力赛前夕现身，采用更激进的设计语言，配备激光大灯及天然纤维复合材料车身面板。该车采用了源自耐力赛车灵感的灯光设计与外扩后视镜，并取消传统门把手。报道推测该车并非量产版纯电M3，因为纯电M3预计2027年晚些时候才上市。","scd":null,"kp":["车身面板材料[疑似基于全新i3开发的纯电性能轿车]: 有望使用天然纤维复合材料","量产应用前景[天然纤维复合材料]: 已具备量产条件，未来可取代碳纤维并显著降低生产环节排放","量产上市预期[纯电版本宝马M3(ZA0)]: 预计2027年晚些时候"]},{"i":2023,"as":"AMD CEO苏姿丰在麻省理工学院毕业典礼上指出，尽管AI能力不断增强，但它无法替代人类判断哪些问题值得解决，也无法在缺乏数据时作出艰难判断或承担结果责任。她强调这些核心责任在于人类。此外，针对AI取代人类工作的担忧，她与微软、Replit等公司的案例均表明，在关键节点上人类的监督与把关依然不可或缺。","scd":null,"kp":["AI能力边界[生成式AI发展]: 无法替代人类判断哪些问题值得解决及承担最终责任","AI发展瓶颈原因[生成式AI]: 高质量训练内容的缺乏导致更先进模型难以问世"]},{"i":2024,"as":"东风奕派EP7纯电轿车现身工信部新产品公示，这是东风奕派与华为乾崑联合打造的第二款车型，将搭载华为乾崑智能汽车技术。该车长4910mm，轴距2920mm，整备质量2058kg，配备双电机及宁德时代磷酸铁锂电池，峰值功率分别为175kW和230kW。东风奕派与华为乾崑计划年内推出三款合作车型，首款合作车型M8 SUV已于5月首发。","scd":null,"kp":["长[东风奕派EP7纯电轿车]: 4910mm","宽[东风奕派EP7纯电轿车]: 1930mm","高[东风奕派EP7纯电轿车]: 1478mm","轴距[东风奕派EP7纯电轿车]: 2920mm","总质量[东风奕派EP7纯电轿车]: 2458kg"]},{"i":2025,"as":"面对AI研究社区的强烈反对，Anthropic调整了针对Claude Fable 5模型的隐蔽“降智”措施。此前，Anthropic曾秘密限制竞争对手使用该模型开发竞争性AI。调整后，安全防护措施对用户可见，若系统怀疑用户试图构建高能力AI，将明确拒绝请求或转移至能力较弱的模型。Anthropic为此前未拿捏好平衡公开致歉。","scd":null,"kp":["风险防范机制[Claude Fable 5]: 加入额外护栏防止滥用并降低网络攻击或生物武器制造风险","隐蔽干预行为[面向前沿AI开发的研究人员]: 原计划在不知情情况下对试图训练竞争AI模型的研究人员进行隐蔽降智干预","防护措施可见性[Claude Fable 5前沿模型开发]: 调整安全防护措施使其对用户可见"]},{"i":2026,"as":"","scd":null,"kp":[]},{"i":2027,"as":"通用汽车正在调整其电动汽车电池战略，考虑放弃引入磷酸铁锂（LFP）电池的计划，转而重点推进锂锰富余（LMR）电池技术。通用汽车此前专注于镍基NMCA电池，并曾计划改造工厂生产LFP电池。电池负责人Kurt Kelty透露了这一新的技术路线转移，LMR电池将成为其未来电池策略的核心。","scd":null,"kp":["电池技术战略调整[通用汽车未来电动汽车]: 重新考虑引入LFP电芯的计划，可能转而聚焦富锰锂电池(LMR)技术","电池封装格式[LMR电池]: 软包形式"]},{"i":2028,"as":"工程服务商IAV与半导体制造商Nexperia正合作开发名为“ONE Inverter”的新一代高压架构，以提升电动汽车电池效率。双方开发了软件控制架构，实现对每个电池单元的独立动态管理。该系统打破了传统电池性能受最弱电芯限制的瓶颈，通过动态控制使每个电芯发挥最大效能，从而在不单纯增加电池容量的前提下提高功率输出。","scd":null,"kp":["高压架构开发目标[ONE Inverter项目]: 提高可从每个电池单体提取的功率，而非单纯依赖增加电池容量","牵引电池性能瓶颈[传统电动汽车电池]: 常常由最弱的电池单体决定其整体性能"]},{"i":2029,"as":"Stellantis已将合作伙伴Factorial Energy的固态电池电芯集成到道奇Charger Daytona测试车中，并启动实车道路测试计划以评估电芯的性能、安全性和可靠性。这是Stellantis首次将固态电池集成到车辆中。测试重点为Factorial的FEST技术，该技术结合了锂金属负极和聚合物隔膜。此前，Stellantis已于去年完成了对该电池电芯的初步验证。","scd":null,"kp":["[道奇Charger Daytona开发车辆]: 配备Factorial Energy固态电池并启动实车道路测试"]},{"i":2030,"as":"","scd":null,"kp":[]},{"i":2031,"as":"","scd":null,"kp":[]},{"i":2032,"as":"","scd":null,"kp":[]},{"i":2033,"as":"","scd":null,"kp":[]},{"i":2034,"as":"","scd":null,"kp":[]},{"i":2035,"as":"宝马在勒芒24小时耐力赛上首次展示了M Concept Neue Klasse概念车，提前展示了即将推出的全电动四电机i3 M EV。该概念车采用了比标准i3更具侵略性的外观设计，前端将新大灯与双肾格栅融为一体并增加M专属套件。这一设计语言代表了Neue Klasse的先锋理念。宝马纯电动M3将于2027年首次亮相，正式将M系列性能车带入电动化时代。","scd":null,"kp":["驱动系统[宝马i3 M EV概念车]: 纯电动四电机驱动"]},{"i":2036,"as":"小米发布了一款家用机械臂充电桩，可自主为电动汽车插拔充电，实现了特斯拉十多年前提出但未量产的构想。该设备宽度仅152毫米，专为狭窄的家庭车库设计，并支持接入小米智能家居生态系统进行手机控制。2015年特斯拉曾展示过类似蛇形机械臂自动对接充电口的原型机，但小米此次将其成功商业化落地。","scd":null,"kp":["设备宽度[小米家用机械臂充电桩]: 152 mm"]},{"i":2037,"as":"","scd":null,"kp":[]},{"i":2038,"as":"天合光能面向北美市场推出Vertex N Shield光伏组件，扩展其n型产品矩阵。该组件功率达620 W，主要针对工商业及公用事业级太阳能项目。产品采用n型TOPCon技术，重点强化了机械耐久性，具备抗冰雹、抗强风和不均匀积雪高载荷能力。设计旨在应对日益频繁的极端天气风险，从而降低工程限制、保险费用并提高项目的长期融资能力。","scd":null,"kp":["功率[天合光能Vertex N Shield TOPCon组件]: 620 W","组件特性[北美市场抗冰雹光伏面板]: N型技术及增强型机械耐用性"]},{"i":2039,"as":"瓦锡兰成功展示了全球首个纯运行100%氢气的大型发动机，并向西班牙Bermeo的国家电网供电。这标志着大型发动机纯氢燃料发电技术的重大突破，超越了仅具备“氢燃料准备”的系统阶段。该技术验证成功推进了灵活低碳发电技术，利用纯氢燃料实现了向电网的持续稳定供电，证明了大型氢能源内燃机在商业化发电中的技术可行性。","scd":null,"kp":["燃料比例[瓦锡兰大型内燃机]: 100%氢气","[西班牙国家电网]: 成功演示全球首个100%氢气大规模发动机并网供电"]},{"i":2040,"as":"标普全球可再生能源副总监Josefin Berg在Women in Solar+活动中指出，光伏和储能等快速发展的行业高度依赖多元化敏捷团队。她强调，女性在行业讨论中常遭遇被“日食”打断或忽视的现象。这需要包容性领导力保持警惕，积极恢复并放大被忽视的声音，确保多元化技术团队避免陷入同质化群体的固化模式。","scd":null,"kp":[]},{"i":2041,"as":"安泰太阳能公司在SNEC 2026展会上推出了升级版TAI-Universal 2P多驱动太阳能跟踪器。该系统采用加强型主结构和关键节点设计，最大跨距可达80米，抗风能力高达60米/秒。延长跨距和提高结构强度可大幅减少桩基数量，有效降低项目的度电成本（LCOE）。该跟踪器专为大型地面光伏电站设计，尤其适用于沙漠等干旱地区的特殊地基要求。","scd":null,"kp":["最大跨度[安泰TAI-Universal 2P多驱动太阳能跟踪器]: 80 m","抗风速[安泰TAI-Universal 2P多驱动太阳能跟踪器]: 60 m/s"]},{"i":2042,"as":"芬兰LUT大学的一项研究表明，在配备备用电源和需求侧灵活性的前提下，数据中心利用风能和太阳能等间歇性可再生能源提供连续基荷电力在技术和经济上完全可行。然而，为了在无风无光时保障持续供电，系统需要将光伏和风电设施的超建规模扩大至七倍，并伴随大量能源弃用。此外，还需进行极其谨慎的选址规划，才能保持成本竞争力。","scd":null,"kp":["超建倍数[风光可再生能源供电数据中心实现连续供电]: 约7倍"]},{"i":2043,"as":"瓦伦西亚港正在防波堤上部署垂直光伏系统，作为欧盟资助的Renewport项目的一部分，旨在推动地中海港口向清洁能源转型。该项目合同已授予Pavener Servicios Energéticos，投资金额超16.9万欧元。该试点系统的主要目的是在实际海洋环境中，验证大规模垂直光伏发电系统在技术、经济和环境三个维度的可行性。","scd":null,"kp":["[瓦伦西亚港防波堤]: 部署垂直光伏发电系统以验证技术及经济可行性"]},{"i":2044,"as":"印度Aarupadai Veedu理工学院设计了一套结合光伏发电、热电制冷和潜热蓄能的家用冷却面板，并使用废弃食用油作为生物相变材料。研究团队通过多种模型对该系统进行了模拟优化。结果表明，该系统不仅有效吸收热量，单块面板每日可提供约6至15千瓦时的制冷量。该技术为家庭建筑集成制冷和废油资源化利用提供了创新方案。","scd":null,"kp":["制冷量[光伏驱动废弃食用油潜热蓄冷系统]: 6–15 kWh/day"]},{"i":2045,"as":"Differ Power将在2026年慕尼黑Intersolar Europe展会上推出D1系列热泵，定位为家庭能源管理中心。这是全球首款九合一集成太阳能储能空气源热泵系统，将空间供暖、制冷、生活热水、光伏逆变、电池管理、PCS、备用电源、家庭能源网关控制集中于单一平台。设备采用低全球变暖潜能值（GWP）的R290环保制冷剂，专为欧洲住宅市场设计。","scd":null,"kp":["系统集成度[热泵系统]: 全球首款九合一","系统定位[D1 Series热泵]: 住宅能源/功率管理枢纽"]},{"i":2046,"as":"大全能源宣布其子公司将在昆山投资60亿元人民币（约8.35亿美元）建设智能制造基地，发力新能源业务转型。该基地将聚焦于AI数据中心应用所需的先进电力设备和储能解决方案的研发与制造。此举标志着大全在超大多晶硅制造商身份之外，正式跨界进入智能电网系统及高端电力储能装备的制造领域。","scd":null,"kp":["投资金额[大全能源智能制造基地]: 60亿人民币","投资重点[大全能源]: 面向AI数据中心的先进电力设备及储能"]},{"i":2047,"as":"国防科技公司Saronic和Castelion计划将高超声速武器与自主军舰相结合，并于2027年进行首次海上试射。根据协议，Castelion公司的“黑胡子”高超声速系统将从Saronic公司的Marauder中型无人水面艇上发射。这是人类历史上首次尝试在无人水面舰艇上部署高超声速打击武器，将彻底改变美军无人化远程打击战术的计算模式。","scd":null,"kp":["测试时间[无人舰艇发射高超音速导弹]: 2027年","平台与载荷[无人水面舰艇]: Saronic Marauder中型USV发射Castelion Blackbeard高超音速系统"]},{"i":2048,"as":"一项新研究支持将熔盐反应堆（MSR）物理和操作集成到大型汽车运输船上的概念设计。劳氏船级社（LR）正与现代重工、KSOE等合作，探索在纯汽车及卡车运输船（PCTC）上安装先进的小型模块化反应堆（SMR）。最新研究重点评估了反应堆系统的内部布置、屏蔽要求、对甲板载货容量及车辆分布的影响，以及反应堆重量和重心位置对船舶稳性带来的技术影响。","scd":null,"kp":["反应堆类型[大型车辆运输船核动力系统]: 熔盐反应堆(MSR)与先进小型模块化反应堆(SMR)","技术状态[核动力运输船设计]: 获得设计批准并完成物理与运营集成概念研究"]},{"i":2049,"as":"HII的制造合作伙伴Bayou Metals在路易斯安那州为Romulus无人水面艇(USV)建立了专用生产线。该生产线专为该艇的金属加工和结构组件配置，采用单一产品线架构，减少了换线时间，使工程师能够优化夹具、焊接顺序和质量控制，旨在缩短交付周期并提高美国海军无人海上项目的产量。","scd":null,"kp":["生产线特征[Romulus无人水面艇]: 专用且可扩展的生产线","核心目的[Romulus USV生产]: 压缩交付周期并提高产量"]},{"i":2050,"as":"约翰斯·霍普金斯医学中心的研究人员利用患者自身细胞培育出微型大脑模型。这些类器官能够捕捉阿尔茨海默病的关键生物学特征，解释不同患者对抑郁、焦虑等药物反应的差异。此外，研究人员还从类器官释放的微小颗粒中识别出生物学线索，为个性化治疗提供了新依据。","scd":null,"kp":[]},{"i":2051,"as":"","scd":null,"kp":[]},{"i":2052,"as":"","scd":null,"kp":[]},{"i":2053,"as":"澳大利亚北领地地质调查局存放了数十亿年前的泥岩岩心，其中包含覆盖澳大利亚北部的古代内陆海海底微小生物化石。这些距今超过15亿年的化石表明，最早的真核生物依赖于氧气。这一发现为氧气促成了复杂生命的进化提供了新证据，有望改写复杂生命起源的历史。","scd":null,"kp":[]},{"i":2054,"as":"","scd":null,"kp":[]},{"i":2055,"as":"","scd":null,"kp":[]},{"i":2056,"as":"澳大利亚弗林德斯大学和堪培拉大学的研究表明，随着年龄增长，人体的行走策略会发生改变，优先考虑平衡与安全而非效率。这种“安全第一”的行走模式虽然短期内提高了站立稳定性，但也导致行走速度变慢、更容易疲劳，并可能增加跌倒的风险。研究解释了老龄化导致步态变慢和疲劳的生物力学机制。","scd":null,"kp":[]},{"i":2057,"as":"研究人员发现严重睡眠剥夺会在人类唾液中留下明显的生物学特征。发表于《蛋白质组学研究杂志》的研究表明，24小时不睡觉会显著改变唾液的化学成分和分子模式。这一发现证明了通过简单的唾液样本即可检测极度疲劳迹象，使未来开发客观的路边疲劳测试仪器成为可能。","scd":null,"kp":[]},{"i":2058,"as":"加州大学圣塔芭芭拉分校、耶鲁大学等机构的研究人员利用新冠疫情期间的动物追踪数据和美国手机定位信息，分析了37个物种对人类活动的反应。研究发现，野生动物不仅对改变的栖息地做出反应，也对人类的直接存在做出反应，且不同物种及周边栖息地条件的不同会导致差异巨大的行为模式。","scd":null,"kp":[]},{"i":2059,"as":"布朗大学和密歇根大学工程学院的研究人员利用精心设计的纳米颗粒作为基本构件，成功稳定了一种此前仅存在于理论模型中的物质状态。该新材料结构锁定了金属中两种最常见的晶体排列之间转瞬即逝的中间态，不仅揭示了材料内部结构的变化机制，还展现出可用于量子计算等量子信息技术的光学特性。","scd":null,"kp":["技术路径[捕获物质隐藏相]: 以工程纳米颗粒为构建基块锁定中间态"]},{"i":2060,"as":"法兰克福歌德大学和维也纳工业大学的物理学家取得数学突破，利用不寻常的数学方法推导出了首个描述“临界坍缩”过程的精确公式。临界坍缩处于普通时空与黑洞之间的边界，该公式描述了微观黑洞在时空临界状态下是如何从爱因斯坦相对论所允许的极端条件中诞生的。","scd":null,"kp":["物理机制[微观黑洞形成]: 时空晶体的临界态转变"]},{"i":2061,"as":"在ASM Microbe 2026会议上公布的研究指出，肠道微生物及其改变胆汁酸的方式在保护睡眠呼吸暂停引起的心血管和代谢损伤方面发挥重要作用。睡眠呼吸暂停会导致缺氧和二氧化碳积累，引发一系列生物级联反应。这一发现揭示了肠道与心脏之间的联系，为减少该疾病引发的心血管风险确定了潜在的治疗新靶点。","scd":null,"kp":[]},{"i":2062,"as":"北京大学周欢萍、严纯华院士团队在《Nature》发表论文，开发出“原位纳米晶限域”策略。该策略通过原位聚合网络在晶体生长时施加空间限制，成功制备出光致发光量子产率高达83%的天蓝光钙钛矿纳米晶薄膜，解决了高结晶度与小尺寸难以兼得的瓶颈。制备的蓝光钙钛矿LED在491nm处外量子效率达6.5%，工作寿命提升两个数量级。","scd":null,"kp":["外量子效率[天蓝光钙钛矿LED]: 6.5%","技术策略[钙钛矿纳米晶薄膜]: 原位纳米晶限域策略实现尺寸约束与高度结晶协同优化","工作寿命[天蓝光钙钛矿LED]: 提升两个数量级"]},{"i":2063,"as":"宇电AI-8系列温控器入选《工业控制装备原理及应用》高校教材，成为唯一入选的国产数字控制器品牌。宇电AI-888控制器测量精度达0.1级，搭载新型APID自整定算法，支持串级控制、50段程序控制等功能。产品获清华大学等权威机构评定为“国际先进水平”，技术指标全面领先进口同类产品，已广泛应用于半导体、光伏等高端制造领域。","scd":null,"kp":["行业地位[宇电温控器]: 行业唯一入选《工业控制装备原理及应用》十四五规划教材的数字控制器品牌","技术评价[AI-8系列数字控制器]: 实现进口替代且技术指标全面领先进口同类产品"]},{"i":2064,"as":"广东地区因拥有超400万辆新能源车、全国第一的峰谷电价差及历史低位的储能系统价格，成为投资光储充停车场的最佳时机。报告测算两类场景：小型园区总投资配置快充桩与光储系统，年净收益约15.3万元，回收期约2.5年；物流园重卡场景总投资约126万元，年净收益约46.9万元，回收期约2.7年。收益主要来自充电服务、光伏降本、峰谷套利及V2G调峰。","scd":null,"kp":["峰谷电价差[广东珠三角五市目录电价]: 1.1577元/kWh","系统价格[储能系统]: 0.973元/Wh","投资回收期[小型园区光储充停车场]: 约2.5年","内部收益率(IRR)[小型园区光储充停车场]: 约20%~25%","年净收益[小型园区光储充停车场]: 约15.3万元"]},{"i":2065,"as":"英伟达（Nvidia）正在向中国客户推销其Vera CPU产品，旨在拓展其在华处理器业务。","scd":null,"kp":[]},{"i":2066,"as":"人工智能公司Anthropic推出了与其自身客户相竞争的应用程序，引发了客户的担忧。","scd":null,"kp":[]},{"i":2067,"as":"","scd":null,"kp":[]},{"i":2068,"as":"","scd":null,"kp":[]},{"i":2069,"as":"KKR、英伟达及其他公司联合投资100亿美元成立一家新的数据中心企业。该情报仅披露了投资金额、主要出资方及公司业务方向，未提供更多技术或运营细节。","scd":null,"kp":["[投资规模]: 100亿美元成立数据中心公司"]},{"i":2070,"as":"","scd":null,"kp":[]},{"i":2071,"as":"专注于逆转衰老相关疾病的生物技术公司Life Biosciences为首位志愿者完成了实验性治疗的给药。该治疗直接注射入一名青光眼患者的眼球，旨在通过“重新编程”细胞至更年轻的状态来再生眼部健康神经以治疗疾病。公司联合主席David Sinclair指出，该策略旨在探索通过细胞重编程技术逆转青光眼及其他衰老疾病的可能性。","scd":null,"kp":[]},{"i":2072,"as":"大脑处于颅骨的黑暗环境中，却能感知心跳加速、肠胃紧缩等生理状态，并预测视觉信息。人类的感官系统以每秒约1100万比特的惊人速率从皮肤、眼睛和耳朵等器官接收海量信息输入，协助大脑理解周围环境并做出安全响应。这种处理过程通常在无意识状态下进行。","scd":null,"kp":[]},{"i":2073,"as":"Airengy与Hagag Europe投资约5500万欧元在罗马尼亚建设压缩空气储能（CAES）工厂。项目使用Airengy专有的盐穴长时储能“AirBattery”技术，分两期建设。最终项目放电容量达25兆瓦，储能总容量达5吉瓦时。两家公司各持股40%，Airengy负责项目的规划、设计、建设和运营。一期工程将增加约200兆瓦时储能容量，建设成本约450万欧元。","scd":null,"kp":["投资额[压缩空气储能项目]: 约5500万欧元(6360万美元)","放电功率[罗马尼亚压缩空气储能项目]: 25 MW","储能容量[罗马尼亚压缩空气储能项目]: 5 GWh","储能技术[压缩空气储能]: 盐穴长时‘AirBattery’技术"]},{"i":2074,"as":"Entrix为Suntec在德国开发的光伏加储能项目提供基于人工智能的市场优化和交易服务。该项目包含5.8兆瓦光伏电站和6.35兆瓦电池储能系统（BESS），共用电网连接点。电池作为“灰色”资产运行，可从光伏电站和电网充电，光伏优先并网，电池利用剩余容量。运行模式为在光伏发电量高且电价低时充电，在可再生能源输出下降且市场价格上涨时放电。","scd":null,"kp":["装机容量[德国光伏电站]: 5.8 MW","装机容量[配套电池储能系统]: 6.35 MW","储能运行模式[光伏加电池]: 允许从光伏和电网充电的“灰色”储能资产","优化手段[光伏加电池]: AI驱动的交易和市场优化服务"]},{"i":2075,"as":"葡萄牙Greenvolt集团波兰分公司在匈牙利东北部启用了Buj电池储能系统。该系统于2024年开建，2026年6月全面投运，储能时长约2.9小时，取代了此前40兆瓦/80兆瓦时的设施，成为匈牙利目前最大的在运储能资产。项目将为输电系统运营商MAVIR提供频率和电压调节及电网灵活性服务。该项目的融资由UniCredit Bank Hungary提供，贷款金额为5890万欧元，期限超过10年。","scd":null,"kp":["装机容量[匈牙利Buj电池储能系统]: 取代40 MW/80 MWh成为该国最大","储能时长[匈牙利Buj电池储能系统]: 约2.9小时","应用场景[电池储能系统]: 调频、调压及电网灵活性"]},{"i":2076,"as":"波兰气候与环境部确认，将不再推进此前由发展与技术部起草的限制建筑内部电池储能部署的条款。原草案提议禁止在公寓和多户型建筑阳台安装储能设备，并将非专用建筑每个防火区的总储能容量限制在600千瓦时，超出此限需建立独立防火分区，这将产生数万兹罗提的额外成本。该撤回决定排除了住宅及商业建筑电池储能发展的行业阻碍。","scd":null,"kp":[]},{"i":2077,"as":"HyCavern项目致力于在欧洲建设衬砌岩石洞穴，专门用于大规模氢气储存。","scd":null,"kp":[]},{"i":2078,"as":"中国中化旗下北化机正式发布自主研发的3000Nm³/h常压碱性水电解制氢装置。单台氢气产能最高达3000Nm³/h，成套装置最高达20000Nm³/h，最高电流密度为12kA/㎡。该装置能根据风光发电变化在10%至120%范围内动态调整产能，具备高智能化、高安全性和低能耗特点。首批装置将用于中石化新星公司的工业化示范项目测试。结合熔盐储能技术，可构建“绿电-绿氢-绿热”多能互补系统，为源网荷储一体化等提供全链条解决方案。","scd":null,"kp":["单台氢气产能[常压碱性水电解制氢装置]: 最高3000Nm³/h","成套装置产能[常压碱性水电解制氢装置]: 最高20000Nm³/h","电流密度[常压碱性水电解制氢装置]: 最高12kA/㎡","功率调节范围[常压碱性水电解制氢装置]: 10%—120%动态调整"]},{"i":2079,"as":"中国汽车工业协会数据显示，今年5月我国新能源汽车新车销量占比攀升至56.9%，渗透率持续走高。5月新能源汽车产销分别完成155.4万辆和149.6万辆，同比增长22.4%和14.4%。其增长得益于成本优化、技术迭代及消费观念转变。相较于燃油车，新能源汽车通勤电费成本大幅降低。此外，国产AI大模型加速上车，智能座舱、智能驾驶及情感感知交互体验成为吸引消费者、推动市场增长的关键技术变量。","scd":null,"kp":["新车渗透率[2025年5月]: 56.9%","产销增长率[5月新能源车产量]: 同比增长22.4%","销量增长率[5月新能源车销量]: 同比增长14.4%","出行通勤成本对比[油转电]: 月费用从超1200元降至不到200元"]},{"i":2080,"as":"山东省煤田地质局物探测量队自主研发的高精度震源反向同步触发装置顺利完成现场试验，攻克了地震勘探特殊震源同步触发技术难题。针对传统正向触发技术在气爆、重锤等特殊场景适配性差的问题，团队采用数字电路同步技术实现创新。经验证，该装置触发延时稳定控制在0毫秒至0.03毫秒，达到行业最高标准。该技术提升了触发精准度与稳定性，适配场景更广，有效缩短野外数据采集周期，降低勘探成本。","scd":null,"kp":["触发技术路线[气爆/重锤等特殊震源]: 震源信号反向触发技术","同步触发模式[特殊震源勘探]: 从传统模拟电路同步向高精度数字电路同步升级"]},{"i":2081,"as":"“数据要素×”三年行动计划实施以来，累计发布417个典型案例及760个典型场景指引。2025年全国活跃数据总量达1.67泽字节（ZB），同比增长28.46%；企业数据产品和服务数量同比增长29.29%，交易额同比增长39.8%。住建部正搭建国家房屋建筑信息基础库以支撑AI等新业态；中科院正加快国家人工智能应用中试基地和科研语料库建设，以应对AI for Science对科学数据的需求，提升科技创新支撑能力。","scd":null,"kp":["活跃数据总量[2025年全国]: 1.67泽字节（ZB）","活跃数据增长率[2025年全国]: 同比增长28.46%","增长率[企业数据产品和服务数量]: 同比增长29.29%","增长率[数据交易额]: 同比增长39.8%"]},{"i":2082,"as":"“十五五”期间，中国电网总投资规模预计突破5万亿元，新型电网建设迈入年均投资近万亿元的超级周期。期间将投产15条特高压直流工程线路，西电东送能力将达4.2亿千瓦以上。电网建设正转向“主配微协同”发展，微电网与虚拟电厂进入市场化阶段。高比例新能源并网凸显了电力供需时空错配问题，储能产业作为支撑电网安全稳定运行的关键环节，将迎来更大规模和更高质量的发展阶段。","scd":null,"kp":["投资规模[十五五时期电网总投资]: 预计突破5万亿元","特高压直流工程[十五五时期投产]: 15条线路","输电能力[十五五时期西电东送]: 达到4.2亿千瓦以上","电压等级[甘肃-浙江特高压直流工程]: ±800千伏"]},{"i":2083,"as":"工信部与国资委联合印发通知，开展2026年度人形机器人与具身智能实景实训专项行动，推动产业从“表演模式”转向“作业模式”。2025年被视为人形机器人量产元年，全球具身智能市场规模预计为195.25亿元，中国市场占比近半。常态化作业要求机器人具备稳定性、耐久性和成本合理性。集中打造统一规范的实训场地，通过真实场景打磨，构建“训练—迭代—应用—再优化”的产业闭环，以补齐模型算法与真机数据短板，加速规模化应用落地。","scd":null,"kp":["全球市场规模[2025年具身智能]: 预计为195.25亿元"]},{"i":2084,"as":"国家市场监管总局与国家发改委联合印发《人工智能计量体系和能力建设指引（2026版）》，旨在解决AI行业“测不准”与“数据荒”痛点。部署了AI内部状态监测等关键技术，建立AI可靠、安全、可信的计量标准。支持构建国家级计量技术研发应用中心，研制AI计量标准装置，形成覆盖算法模型、算力效率、数据质量全链条的计量能力。该指引推动计量技术融入智能制造、智慧医疗等14个重点领域，并建立高质量数据集与共享机制。","scd":null,"kp":["重点赋能领域[人工智能计量体系]: 智能制造、智慧医疗、智慧交通等14个","技术攻关目标[AI系统内部状态]: 监测与表征关键技术"]},{"i":2085,"as":"工信部与国资委启动2026年度人形机器人与具身智能实景实训专项行动，旨在真实生产生活环境中常态化部署应用该技术。任务包括建设实训空间、培育创新联合体及攻关作业技能。目标到2026年底，重点产品在代表性场景中完成验证并开启“作业模式”，凝练百个以上高价值场景，形成万台级规模落地能力。我国该产业链关键环节基本成型，已进入规模化落地的关键窗口期，专项行动将在十省市推进落地。","scd":null,"kp":["落地能力[2026年底人形机器人重点产品]: 万台级规模","应用场景目标[2026年底高价值应用场景]: 百个以上"]},{"i":2086,"as":"工信部印发《“人工智能+信息通信”创新发展实施意见（2026—2028年）》。目标到2028年，信息通信网络初步实现高等级自智，形成30个以上高价值典型场景，城域算力1毫秒时延圈覆盖率不低于75%。部署了17项任务，聚焦5G-A/6G、光网络等与AI融合，推进网络设备智能化。在核心网、路由器等网络设备部署智能算力，并在边缘设备部署推理算力，为交通、低空经济等应用提供通感算智一体的边缘计算服务。到2030年实现关键核心技术突破与完备的产业生态体系。","scd":null,"kp":["覆盖率[2028年城域算力1毫秒时延圈]: 不低于75%","高价值典型场景[2028年信息通信网络]: 30个以上"]},{"i":2087,"as":"Visual Fan公司为欧洲能源公司在罗马尼亚的120兆瓦时（MWh）电池储能系统（BESS）完成通电。该项情报属于储能项目进展报道，正文截断，未提供项目具体采用的技术细节或并网参数。","scd":null,"kp":["储能项目规模[罗马尼亚BESS项目]: 120兆瓦时"]},{"i":2088,"as":"Fox ESS与澳大利亚分销商签署了总量达10吉瓦时（GWh）的储能协议。该情报仅提供了合作双方、所在地区（亚太）及储能协议的总规模，正文内容被截断，未披露具体的交付时间表或产品技术参数。","scd":null,"kp":["储能协议规模[Fox ESS与澳大利亚分销商]: 10 GWh"]},{"i":2089,"as":"智利启动电力拍卖，计划根据15年的购电协议（PPA）每年签订2.8太瓦时（TWh）的合同。该情报属于拉美地区可再生能源与电力市场动态，正文内容截断，未提供具体的发电类型或招标技术要求。","scd":null,"kp":["[智利电力拍卖]: 每年签订2.8太瓦时合同，购电协议期限为15年"]},{"i":2090,"as":"本周光伏产业链材料价格波动。EVA粒子价格不变，但在新产能释放与需求偏弱预期下，预计下周价格震荡。背板PET受成本驱动价格上涨1.3%，铝价下降0.7%，铜价下降0.2%。光伏玻璃价格降幅0.4%，供应增加且需求下降导致弱势下行。此外，部分光伏玻璃因窑炉冷修缓和供应压力，厂家亏损下积极推涨报价，双方博弈加剧，预计库存缓降，交投重心小幅上移。","scd":null,"kp":["价格涨幅[光伏背板PET本周]: 1.3%","价格降幅[铝材本周]: 0.7%","价格降幅[现货铜本周]: 0.2%","价格降幅[未指明品类本周]: 0.4%","[光伏玻璃]: 近期部分窑炉冷修，供应减少"]},{"i":2091,"as":"全国规模最大的江苏如东“光氢储一体化”项目全面建成，开启“源网荷储氢”协同运行模式。该项目包含40万千瓦光伏、60兆瓦/120兆瓦时储能站及1500标方/小时制氢装置。年发电量达4.68亿千瓦时，减排二氧化碳超30万吨；配套储能平抑电网波动；制氢装置年产绿氢482吨，实现零碳闭环并向长三角供应。目前全系统已完成联合调试，各项性能达标。","scd":null,"kp":["装机容量[如东光氢储一体化项目光伏]: 40万千瓦(400MW)","装机容量[配套储能站]: 60兆瓦/120兆瓦时","制氢规模[绿电制氢装置]: 1500标方/小时","年发电量[如东光氢储一体化项目]: 4.68亿千瓦时","年产量[高纯绿氢]: 482吨"]},{"i":2092,"as":"金刚光伏股份有限公司发布公告，宣布撤销退市风险警示及其他风险警示。公司股票将于2026年6月11日停牌一天，并于6月12日复牌。复牌后，公司股票简称由“*ST金刚”变更为“金刚光伏”，证券代码保持不变，正式摘帽。","scd":null,"kp":["[金刚光伏]: 撤销退市风险警示及其他风险警示"]},{"i":2093,"as":"2026年5月广东省新增备案光伏项目5385个，总投资超50.22亿元，总容量达1210.14MW。其中工商业光伏备案容量排名前三的城市为东莞、佛山和中山。投资额最高的单体项目为英德海螺棚顶5.95MW发电项目，投资0.23亿元。本月共有978家企业参与工商业光伏备案，天津华能杨柳青热电以0.85亿元居投资额首位，惠东县交投汇能以24个项目居数量首位。","scd":null,"kp":["备案数量[2026年5月广东光伏项目]: 5385个","投资总额[2026年5月广东光伏项目]: 超50.22亿元","备案容量[2026年5月广东光伏项目]: 1210.14MW","建设容量[东莞工商业光伏]: 105.53MW","建设容量[佛山工商业光伏]: 80.12MW"]},{"i":2094,"as":"据欧洲Sun.store数据，5月欧洲光伏组件价格大幅上涨，采购经理人指数攀升至70，创年内新高。双面TOPCon组件大涨7%，BC组件价格创0.134欧元/瓦新高。逆变器价格整体维稳，大功率机型微降。品牌方面，Deye稳居逆变器首位，Huawei位列组件逆变器前列。市场转向大功率组件及夏季需求回暖带动了价格上涨，计划减少采购的商户比例降至最低，整体氛围乐观。","scd":null,"kp":["指数值[5月欧洲光伏采购经理人指数(PV PMI)]: 70","价格涨幅[双面TOPCon组件5月欧洲市场]: 7%","价格[BC组件5月欧洲市场]: 0.134欧元/瓦","[欧洲市场逆变器5月价格]: 整体维稳，大功率机型小幅回落，大功率商用机型微涨"]},{"i":2095,"as":"河北晋州市公共机构屋顶光伏发电25年使用权将于2026年6月17日公开网络拍卖，起拍价为1.72亿元，竞买保证金500万元。竞买人须为中国境内注册的独立企业，未被列入失信名单，且不接受联合体报名。符合条件的企业需在6月16日前完成平台注册、办理CA数字证书并提交营业执照等资料完成报名手续。","scd":null,"kp":["起拍价[晋州市屋顶光伏发电使用权]: 17217.29万元","标的使用期限[晋州市屋顶光伏发电使用权]: 25年","竞买保证金[晋州市屋顶光伏发电使用权]: 500万元"]},{"i":2096,"as":"南通市发改委公布分布式光伏接入电网可开放容量。该数据基于2026年第2季度动态测算，全面评估了全市电网承载能力。投资主体可通过供电营业厅或电话咨询查询各地区110、35千伏及10（20）千伏公用变压器和配电线电源的可开放容量信息。","scd":null,"kp":["[南通市分布式光伏接入电网]: 公布可开放容量评估结果(数据截至2026年第2季度)"]},{"i":2097,"as":"北京公开征集2026年第一批市政府固定资产投资支持光伏项目。支持范围包括建筑光伏一体化项目及采用钙钛矿、碲化镉等新型电池组件的项目，最高给予建设投资30%的资金支持。申报项目规模原则上不小于500千瓦，需于2026年7月底前开工并于12月31日前并网。已获其他市级补贴或竣工项目不予支持。","scd":null,"kp":["支持比例[BIPV等光伏项目市政府固定资产投资]: 不高于30%","项目规模下限[申报支持光伏项目]: 不小于500千瓦","[技术路线支持范围]: 采用钙钛矿、碲化镉等新型电池组件及建筑光伏一体化项目"]},{"i":2098,"as":"呼伦贝尔市启动2026年第二批次分布式风电、光伏项目竞争性配置申报。分散式风电项目仅限额尔古纳市、莫旗的电网末端保供型试点。一般工商业及大型工商业分布式光伏申报规模，需结合当地2026年二季度可开放容量并核减驭风行动项目规模后统筹。企业申报材料需在6月23日前汇总上报。","scd":null,"kp":["[呼伦贝尔市分布式风电]: 开展电网末端保供型分散式风电试点项目竞争性配置"]},{"i":2099,"as":"苹果发布Core Image RAW 9处理管线及API，这是自2017年以来的首次重大更新。该版本利用新的CoreML模型，将去马赛克与降噪过程同步进行，显著提升了RAW图像的色彩还原、锐度及细节表现，并修复了富士X-Trans传感器的伪色问题。API支持784款相机，借助苹果神经网络引擎优化性能，并提供精细的图像参数编辑与处理控制。","scd":null,"kp":["处理管线[Core Image RAW]: Core Image RAW 9","[去马赛克与降噪]: 在新的CoreML模型中同步进行","支持范围[RAW文件解析]: 784款相机","[富士X-Trans CMOS传感器]: 解决旧算法常见的伪色和细节丢失问题"]},{"i":2100,"as":"SpaceX正式登陆纳斯达克，IPO发行价135美元，募资750亿美元，超越沙特阿美创下全球最大IPO纪录。开盘后股价涨超24.44%至168美元，市值突破2.15万亿美元，位列美股第七。创始人马斯克保留超82%投票控制权，其个人净资产随之突破1.2万亿美元，成为全球首位财富超万亿美元的富豪。","scd":null,"kp":[]},{"i":2101,"as":"据路透社报道，SK海力士计划赴美上市并选择纳斯达克，以凸显其科技属性并吸引AI概念投资者。此次IPO最早将于8月进行，最高融资可能达140亿美元。SK海力士认为纳斯达克能提供更高估值，并帮助扩大被动型全球投资基金的投资者基础。美国证券交易委员会预计将在6月22日当周批准其上市申请。","scd":null,"kp":[]},{"i":2102,"as":"东风日产宣布其N序列新能源车第10万台正式下线。自启动以来仅用时14个月，刷新了央企合资品牌新能源10万台销量最快纪录。该序列涵盖11.99万起售的N7纯电轿车、N6插混轿车以及15.99万起售的NX8增程SUV。同时，官方为N6/N7/NX8全系车主推出了“三无忧”服务。","scd":null,"kp":["[新能源产量]: 10万台","达产时间[N序列新能源]: 14个月","[销量纪录]: 刷新央企合资品牌新能源10万台销量最快纪录"]},{"i":2103,"as":"字节跳动旗下豆包应用正式上线“任务模式”，原有的“思考模式”升级为“专家模式”。任务模式具备智能体能力，支持零代码网页生成、PPT制作、数据可视化分析及定时后台自动执行任务。专家模式调用豆包大模型2.0 Pro，专注深度推理。结合面向简单问答的快速模式，豆包实现了从即时问答到复杂任务交付的结构性功能调整。","scd":null,"kp":["[任务模式]: 具备智能体能力，支持任务拆解、步骤规划、工具调用到结果交付的全链路执行","[思考模式]: 升级为专家模式","[零代码网页生成]: 几分钟内可生成作品集或落地页","[数据可视化分析]: 支持上传Excel自动生成柱状图、折线图、漏斗图等"]},{"i":2104,"as":"Meta CEO扎克伯格表示，推动AI领域的突破无需千人规模的庞大团队，十余名尖端人才组成的强大团队即可取得显著进展。他在谈及非营利医学研究组织Biohub时指出，AI研究人员需求极高，但Biohub结合前沿生物学与AI的独特工作具备稀缺性优势。他还指出，算力是全球各AI实验室面临的正常约束，而AI的进步将助力Biohub更早实现治愈疾病的目标。","scd":null,"kp":[]},{"i":2105,"as":"苹果在WWDC 26上发布的全新Siri AI功能仅限较新设备使用。iPhone端需iPhone 15 Pro及以上机型；iPad需搭载M1或A17 Pro及以上芯片；Mac全线需搭载Apple Silicon芯片。Apple Watch需Series 9及以上且配合兼容的iPhone使用。此外，部分端侧高阶AI模型功能对硬件门槛要求更高。","scd":null,"kp":["[Siri AI完整功能要求]: iPhone 15 Pro及更新机型","[Siri AI完整功能要求]: 配备M1或更新芯片的iPad型号","[Siri AI完整功能要求]: 搭载A17 Pro芯片的iPad","[Siri AI完整功能要求]: 搭载M1芯片及更新版本的Apple silicon Mac机型"]},{"i":2106,"as":"在华为开发者大会2026上，余承东宣布鸿蒙HarmonyOS已成为中国第二大智能手机操作系统，并发布新一代HarmonyOS 7。目前搭载鸿蒙系统的终端设备超6600万台，注册开发者超1100万，应用市场服务超40万款，日均下载量超2亿次。同时，开源鸿蒙已发布超100个商用版本，代码行数超1.4亿，生态伙伴突破3200家。","scd":null,"kp":["终端设备数量[搭载鸿蒙HarmonyOS 6]: 突破6600万台","[鸿蒙生态]: 注册开发者超1100万","应用与服务数量[华为应用市场]: 超40万款","应用日均下载量[华为应用市场]: 超2亿次","[开源鸿蒙]: 发布超100个商用版本"]},{"i":2107,"as":"三星捷克官网上架Galaxy A27 5G手机，搭载骁龙6 Gen 3芯片，出厂预装One UI 8.5系统。该机配备6.7英寸FHD+ Super AMOLED显示屏，覆盖大猩猩Victus+玻璃，支持IP64防尘防水。硬件方面内置5000mAh电池，支持25W充电，前置1200万像素，后置5000万像素主摄、500万超广角及200万微距三摄，提供四种配色，暂未公布售价。","scd":null,"kp":["芯片[Galaxy A27 5G]: 骁龙6 Gen 3","内存与存储配置[Galaxy A27 5G]: 6GB+128GB或8GB+256GB","电池容量[Galaxy A27 5G]: 5000mAh","充电功率[Galaxy A27 5G]: 25W","机身厚度[Galaxy A27 5G]: 7.8mm"]},{"i":2108,"as":"Retroid Pocket 6复古掌机重新推出12GB内存版本，但存储容量由256GB缩减至128GB，售价保持279美元不变，支持microSD卡扩展。该掌机搭载高通骁龙8 Gen 2芯片，采用5.5英寸1080P 120Hz AMOLED屏，最高可流畅模拟运行任天堂Switch与PS2游戏。新版仅提供左摇杆上置布局及黑、银、16-bit三种配色选择。","scd":null,"kp":["内存与存储配置[Retroid Pocket 6]: 12GB+128GB","售价[Retroid Pocket 6]: 279美元","[模拟器支持]: 流畅运行任天堂Switch与PS2平台游戏","芯片[Retroid Pocket 6]: 高通骁龙8 Gen 2"]},{"i":2109,"as":"英伟达未发布的图灵架构旗舰显卡RTX 2080 Ti SUPER工程样品在eBay曝光。该原型卡搭载完整的TU102核心，拥有4608个CUDA核心，配备12GB GDDR6显存及384-bit位宽，规格直逼Titan RTX，曾被内部称为“Titan 杀手”。由于显卡从未公开发售，常规系统及驱动无法直接识别，用户需在Windows 10测试模式下手动修改驱动INF文件并添加硬件ID才能正常安装使用。","scd":null,"kp":["CUDA核心数量[RTX 2080 Ti SUPER工程样品]: 4608个","显存容量[RTX 2080 Ti SUPER工程样品]: 12GB GDDR6","显存位宽[RTX 2080 Ti SUPER工程样品]: 384-bit","GPU核心[RTX 2080 Ti SUPER工程样品]: 完整的TU102图灵"]},{"i":2110,"as":"华为在HDC 2026上发布HarmonyOS开发套件26.0.0 Beta1版本，调整了版本号格式。新版本采用语义化版本格式，统一了HarmonyOS开发套件及其底座OpenHarmony的版本号体系。版本号分为主版本、次版本和修订版本三个字段，分别对应重大不兼容变更、向后兼容的新功能以及问题修复。新套件包含大量新功能与重要变更，提升了沉浸光感效果及游戏应用启动体验。","scd":null,"kp":["版本号格式[HarmonyOS开发套件及OpenHarmony]: 统一采用语义化版本格式","API版本[HarmonyOS开发套件]: 26.0.0 Beta1"]},{"i":2111,"as":"","scd":null,"kp":[]},{"i":2112,"as":"宁德时代董事长曾毓群指出，行业内存在挖角和窃取技术的现象，导致产品性能仅有宁德时代的60-70%，但通过低价进行恶性竞争。他批评这种现象源于浮躁的短期利益追求，电池质量问题往往在使用三五年后才显现。宁德时代2026年一季度财报显示，营收1291.31亿元，同比增长52.45%，归母净利润207.38亿元。","scd":null,"kp":["价格水平[行业竞争对手模仿产品]: 比宁德时代低百分之十几、二十","产品性能[行业竞争对手模仿产品]: 不到宁德时代的百分之六七十"]},{"i":2113,"as":"SpaceX正式上市，开盘高开29%跻身全球第6大上市公司，募资750亿美元创下全球最大IPO纪录，马斯克成为首位万亿美元富豪。高盛集团总裁沃尔德伦表示，此次创纪录IPO表明投资者正积极为AI和太空基础设施建设提供资金。预计市场还将迎来一波大规模IPO浪潮，Anthropic和OpenAI等AI公司也有望今年上市。全球并购交易规模同比增长35.2%至3.1万亿美元。","scd":null,"kp":["募资规模[SpaceX IPO]: 750亿美元","首日涨幅[SpaceX上市首日]: 高开29%"]},{"i":2114,"as":"","scd":null,"kp":[]},{"i":2115,"as":"北京越野BJ30高光版上市，定位轻越野SUV。新车包含燃油版与混动版，置换价8.29万至10.99万元。车身长宽高为4730/1910/1790mm，轴距2820mm。混动版搭载三擎四驱六模HEV架构，最大功率301kW，最大扭矩685Nm，百公里加速6.59秒，WLTC综合油耗6.45L/100km。燃油版搭载1.5T+7DCT动力系统。此外，后电机功率提升至70kW。","scd":null,"kp":["超级置换价[燃油高光版]: 8.29万元","超级置换价[混动高光版]: 10.99万元","后电机功率[高光版混动车型]: 70kW","车身长宽高[BJ30高光版]: 4730/1910/1790mm","轴距[BJ30高光版]: 2820mm"]},{"i":2116,"as":"SpaceX正式登陆纳斯达克，CEO马斯克在远程敲钟仪式前向员工发表讲话。他表示，最初认为SpaceX成功的概率不到10%，对如今成为史上最大IPO感到难以置信。马斯克强调，SpaceX的愿景是带领普通人前往月球、火星甚至太阳系以外的地方，而不仅仅是少数宇航员。","scd":null,"kp":["成功概率预期[SpaceX初创时期]: 不到10%"]},{"i":2117,"as":"","scd":null,"kp":[]},{"i":2118,"as":"华为乾崑｜启境首款大五座SUV启境GX7实车预告图亮相，整体采用曲线设计语言，配备车顶激光雷达、大尺寸尾翼和半隐藏式门把手。新车计划于今年秋季上市，寓意“伟大的探索”，旨在进一步拓展车内空间，适配家庭出行需求。同家族的猎跑车型GT7已于5月开启预售，首发τ定律数字底盘赤兔平台及ADS 5智驾，预售价21.99万至30.99万元。","scd":null,"kp":["预售价区间[启境GT7]: 21.99万元至30.99万元","智能驾驶[启境GT7]: 首批搭载ADS 5","底盘平台[启境GT7]: τ定律数字底盘赤兔平台"]},{"i":2119,"as":"Anthony Price于2010年创办了国际液流电池论坛（IFBF），最初只是一场针对储能边缘技术专家的临时性小型聚会。如今，该会议已发展为全球液流电池领域的首要国际交流平台，吸引了全球数百名代表参会，深刻影响着长时储能技术的未来发展。","scd":null,"kp":[]},{"i":2120,"as":"MKS的Spectra-Physics正利用先进的突发模式激光加工技术改变锂离子电池的电极结构制造。该技术具备极高的精度和效率，能制造出复杂的电极设计，优化离子在充放电过程中的扩散路径，抑制快充时的锂枝晶形成。这些创新不仅提升了电池的性能、能量密度和可靠性，还推动了电池制造的规模化升级。","scd":null,"kp":[]},{"i":2121,"as":"施耐德电气全球供应链人力资源高级副总裁Laure Collin指出，工业4.0不仅是技术挑战，更是文化挑战，人才是供应链的未来。在她的主导下，施耐德电气一家顶级智能工厂进行了全面的人才与文化整顿，成功将关键员工流失率降低至仅6%。她致力于确保人才、技能和文化成为供应链实现性能、韧性、数字化和可持续性的关键赋能因素。","scd":null,"kp":["关键员工流失率[施耐德电气顶级智能工厂]: 6%"]},{"i":2122,"as":"标致全新E-208 GTi电动拉力赛车在勒芒24小时耐力赛上首次公开亮相。新车具备量产条件，拥有280马力及345牛·米的扭矩，性能表现介于雷诺5与Lancia Y HF之间。该车复兴了80和90年代经典的法国燃油小钢炮名称，采用了保留复古元素的现代设计风格，致力于以现代纯电技术提供原汁原味的性能体验。","scd":null,"kp":["马力[标致 E-208 GTi]: 280 hp"]},{"i":2123,"as":"瑞典Ljungby成功部署了一辆Kalmar Ottawa T2 EV电动终端拖拉机，该车辆通过Elonroad开发的路面嵌入式充电系统实现不间断连续作业，无需插入电源充电。该系统通过轨道物理接触向车辆供电，结合动能回收制动技术，能够提供充足的能量维持卡车持续运行。其目标是为客户提供拥有无限车载能源的免充电解决方案。","scd":null,"kp":["充电方式[Kalmar Ottawa T2 EV电动终端牵引车]: 基于道路内嵌电气充电轨道的系统进行物理接触充电（无需插入电源）"]},{"i":2124,"as":"Bellevue Gold金矿实现连续155小时完全使用100%可再生能源运行。该矿配备了一座90兆瓦混合动力发电站，整合了27兆瓦太阳能电池阵列、24兆瓦风力涡轮机以及15兆瓦（33兆瓦时）电池储能系统。此举证明了在适宜条件下该系统可超越原定80%的供能目标，助力该金矿在2026年实现净零碳排放黄金生产。","scd":null,"kp":["100%可再生能源运行时间[Bellevue Gold矿井连续运行]: 155小时","混合电站总装机容量[Bellevue Gold矿井]: 90 MW","光伏阵列装机容量[矿井混合电站]: 27 MW","风力发电机装机容量[矿井混合电站]: 24 MW","电池储能系统[矿井混合电站]: 15 MW (33 MWh)"]},{"i":2125,"as":"越南电动汽车制造商VinFast宣布其第100万辆电动摩托车正式下线，这是一台在 海防制造厂生产的红色Feliz II电动踏板车。这一里程碑凸显了亚洲电动出行市场的庞大规模。该车型采用可拆卸电池系统，支持在家充电或电池更换服务。VinFast不仅是进军国际的电动汽车制造商，在电动两轮车领域同样具备产业巨头地位。","scd":null,"kp":["累计产量[VinFast电动摩托车下线]: 100万辆"]},{"i":2126,"as":"在特朗普政府实施了全面的新出口限制后，AI巨头Anthropic被迫暂停美国以外用户访问其最先进的人工智能模型。美国商务部长在信中通知Anthropic，其新发布的Fable 5和Mythos 5模型已列入出口管制清单。Anthropic随后切断了外国政府、企业、研究人员及在美外国公民的相关模型访问权限，反映出美国政府对前沿AI技术安全的严格管控。","scd":null,"kp":["高级AI模型访问权限[美国出口管制限制]: 暂停非美国用户及在美外籍人士访问"]},{"i":2127,"as":"","scd":null,"kp":[]},{"i":2128,"as":"欧洲电池初创公司SOLiTHOR成功生产出首款10安时固态电池演示电芯，实现了技术从实验室到商业化量产规模的跨越。该软包电池在堆叠层面实现了465 Wh/kg和1400 Wh/L的能量密度。工程师在专有的固体复合电解质中引入了面容量为8mAh/cm2的高负载阴极。该化学工艺采用溶胶-凝胶法，无需传统锂离子系统中的某些特定材料即可运行。","scd":null,"kp":["电芯容量[SOLiTHOR固态电池首件演示电芯]: 10 Ah","能量密度[固态电池软包电芯堆叠层面]: 465 Wh/kg","体积能量密度[固态电池软包电芯堆叠层面]: 1400 Wh/L"]},{"i":2129,"as":"中国研究人员成功开发出新型“三通道”光纤系统，无需更换或重新铺设线缆即可大幅扩展现有网络的数据传输容量，特别是针对人工智能网络。该系统能够将光纤数据流量增加5倍，同时使每根光纤芯的传输容量提升近50%。这项创新通过在现有光纤中更高效地复用多波长激光，极大提升了网络的数据传输效率。","scd":null,"kp":["数据传输容量提升[三通道光纤系统]: 5倍","光纤通信结构[创新技术路线]: 三通道（three-lane）光纤系统"]},{"i":2130,"as":"中国小米展示了一款用于家庭电动汽车自动充电的机械臂系统。该系统无需驾驶员干预即可自动将车辆连接至充电器，计划于2026年第四季度商业化发布。充电机械臂将与智能泊车功能协同工作，实现车辆自动停放和开启充电的闭环体验。此外，小米强调随公告发布的演示视频是在真实环境中拍摄的，而非受控的概念演示。","scd":null,"kp":["自动充电机械臂[小米家庭自动充电系统]: 自动连接车辆与充电桩","商业化发布时间[小米自动充电机械臂]: 2026年第四季度"]},{"i":2131,"as":"据相关报道，中国军方规划人员制定了一项在远距离打击美国航空母舰的战略。该策略发表在《战术导弹技术》期刊上，提出结合卫星、人工智能和导弹，使航母战斗群在超过1620海里（约3000公里）的距离下变得不堪一击。这一计划揭示了远程精确打击资产的技术结合方式，目前美国海军正通过分散部署舰船等模式来降低面临的威胁。","scd":null,"kp":["超远程打击距离[卫星/AI/导弹协同反航母策略]: 超过1620海里（3000公里）"]},{"i":2132,"as":"中国和欧洲的两个独立研究团队成功研制出世界上首批可运行的核钟。这些核钟基于稀有同位素的原子核制造。相比使用电子的原子钟，由于原子核受到的环境干扰屏蔽更好，核钟有望成为极其精确的计时工具。这项突破不仅代表着新一代计时技术的诞生，还将有助于改进导航系统、引力传感技术以及对基础物理定律的测试。","scd":null,"kp":["核心技术特征[首个工作核钟]: 基于特殊同位素原子核构建并已成功演示运行"]},{"i":2133,"as":"","scd":null,"kp":[]},{"i":2134,"as":"","scd":null,"kp":[]},{"i":2135,"as":"","scd":null,"kp":[]},{"i":2136,"as":"","scd":null,"kp":[]},{"i":2137,"as":"","scd":null,"kp":[]},{"i":2138,"as":"加州大学圣地亚哥分校的工程师开发了一款柔性可穿戴超声波贴片，能够对胎儿健康进行实时、免提的长期连续监测。即使在怀孕期间胎儿和脐带移动的情况下，该设备也能在数小时内保持可靠的性能。在临床测试中，该贴片成功检测到一例异常延长的胎儿信号，促使医生提前进行剖腹产，挽救了婴儿生命。这项技术还有望改善医疗资源匮乏地区的产前护理条件。","scd":null,"kp":["设备形态[新型可穿戴超声波贴片]: 柔性可穿戴贴片","监测性能[胎儿健康及血流实时追踪]: 连续数小时实时监测且不受胎儿及脐带移动影响"]},{"i":2139,"as":"","scd":null,"kp":[]},{"i":2140,"as":"","scd":null,"kp":[]},{"i":2141,"as":"","scd":null,"kp":[]},{"i":2142,"as":"","scd":null,"kp":[]},{"i":2143,"as":"据The Information报道，在收到政府命令后，Anthropic公司暂停了客户对其最新人工智能模型的访问权限。","scd":null,"kp":[]},{"i":2144,"as":"据The Information报道，OpenAI正在接受各州总检察长关于其用户交互问题的调查。","scd":null,"kp":[]},{"i":2145,"as":"","scd":null,"kp":[]},{"i":2146,"as":"据The Information报道，由于出现资金短缺，加密货币交易所Binance和Bybit取消了SpaceX的IPO股份分配。","scd":null,"kp":[]},{"i":2147,"as":"据The Information报道，SpaceX的股价在首个交易日中大幅上涨了19%。","scd":null,"kp":["股价涨幅[SpaceX首日交易]: 19%"]},{"i":2148,"as":"科技行业领袖正在修正此前“AI将引发就业末日”的预测。OpenAI CEO萨姆·奥尔特曼称，AI并未如预期般淘汰入门级白领工作，他通过让AI代写邮件等测试意识到工作的人性化部分不可或缺。微软AI CEO穆斯塔法·苏莱曼也澄清，未来12至18个月内被自动化的主要是发送邮件等子任务，而非整个职业消失。微软总裁布拉德·史密斯坦言AI确实会取代部分工作，但也认识到公众对AI发展速度的担忧。","scd":null,"kp":["预测周期[白领工作被AI完全自动化]: 未来 12 到 18 个月内"]},{"i":2149,"as":"","scd":null,"kp":[]},{"i":2150,"as":"全球首条百万片级体全息光波导自动化产线在天津滨海高新区正式投产，年产能达100万片。该产线由尼卡光学设计建设，拥有1500平方米千级洁净车间及精密环控系统，全线采用独家定制的全息光刻设备及工艺平台。体全息光栅波导技术具有不漏光、轻薄、高通透等特性。该产线的投产实现了消费级AR核心显示技术的规模化量产，目前相关方案已应用于AR眼镜及车载AR-HUD等领域。","scd":null,"kp":["产线规模[体全息光波导自动化产线]: 年产能达 100 万片","洁净度[产线车间]: 1500 平方米千级洁净车间","物理特性[体全息光栅波导(VHG)]: 不泄露显示信息、接近普通镜片、超高通透性、结构轻薄"]},{"i":2151,"as":"中国科学院等机构的研究团队在囚禁离子实验平台中，首次实现了非厄米体系中纠缠生成的加速，成功超越传统厄米量子速度极限。实验利用两枚40Ca+离子构建系统，通过引入可调耗散通道将系统参数调至例外点附近提供演化“捷径”。在固定耦合强度下，纠缠制备时间从200微秒成功缩短至132微秒，速度提升约1.52倍。实验表明纠缠加速会增加布居泄漏概率从而降低成功率，团队选取了兼顾效率与成功概率的工作点验证了高保真度。相关成果已发表于《物理评论快报》。","scd":null,"kp":["离子物种[囚禁离子实验平台]: 40Ca+ 离子","激光波长[驱动量子比特相干跃迁]: 729 nm","激光波长[引入可调耗散通道]: 854 nm","耦合强度[仅有相干相互作用]: J = 2π×625 Hz","门时间[Bell态制备(传统厄米系统)]: 200 微秒"]},{"i":2152,"as":"毕马威此前发布的《总体体验：在智能体AI时代重新定义卓越》报告被证实充斥AI幻觉与虚假信息。GPTZero调查发现，报告内45条引文中仅有5条准确对应真实来源，约一半的主张存在虚假或来源归属错误，如错误描述了阿联酋航空、瑞银及瑞士联邦铁路的AI应用。这些问题被指源于AI研究工具的幻觉。目前，毕马威已撤下该报告并开始进行内部审查。","scd":null,"kp":["引文准确性[毕马威AI报告真实来源]: 45条引文中仅5条准确","主张缺陷率[毕马威AI报告内容]: 约一半主张存在虚假或归属错误"]},{"i":2153,"as":"智谱AI发布编程工具ZCode 3.0版本，全面切换至自研ZCode Agent内核，并深度适配最新开源模型GLM-5.2。GLM-5.2支持1M上下文，ZCode 3.0对其长程推理、工具调用和大型工程执行链路进行了优化。Coding Plan用户应用内专享150%配额。此外，ZCode 3.0新增了分组式任务工作区、Zread智能项目知识库、可视化Git分支图谱、可定制聊天交互体验、全方位状态监控看板以及多类型附件智能适配等功能。","scd":null,"kp":["上下文长度[GLM-5.2开源模型]: 1M","配额加成[GLM Coding Plan订阅用户]: 专享 150% 配额","内核架构[ZCode 3.0]: 全面切换自研 ZCode Agent 内核"]},{"i":2154,"as":"英特尔持续收缩开源版图，已将其AI加速开源项目BigDL列入终止清单，最终归档日期定为2026年6月30日。BigDL是一个专注于在英特尔全系XPU上低延迟运行AI大语言模型的开源框架，集成了TensorFlow、PyTorch等主流框架。尽管当前市场对AI及大语言模型需求旺盛且该项目仍在定期提交代码，英特尔仍因开源策略转向、企业重组和成本削减终止了该项目的维护，仅给现有用户留出半个月的迁移时间。","scd":null,"kp":["归档日期[BigDL开源项目]: 2026 年 6 月 30 日"]},{"i":2155,"as":"俄罗斯联合航空制造公司CEO瓦季姆·巴杰哈证实，俄罗斯正在茹科夫斯基研究中心研制超音速客机原型机，相关工作已进入硬件制造阶段。该设计方案已于今年4月申请专利，旨在实现超音速飞行的同时降低音爆响度并减少机场周边噪声。研制方计划打造一款具备商业可行性且符合现代安全与环保标准的客机，主要面向高端客运市场的商务舱与头等舱旅客。目前已有航空公司对此表达兴趣，但尚未公布具体的商业部署时间表。","scd":null,"kp":["研发阶段[俄罗斯超音速客机原型机]: 进入硬件制造阶段","技术特征[未来超音速客机设计]: 降低音爆响度并减少机场周边噪声水平"]},{"i":2156,"as":"美国国家公路交通安全管理局文件确认，2027款林肯冒险家将在中国生产并返销美国市场，提供Premiere和Reserve两种配置。美规版车型预计将搭载以2.0升涡轮增压发动机为核心的混动系统，系统综合功率或为213千瓦。同时，返销美国的中国版冒险家将拥有比此前美版更豪华的配置，配备12.3英寸数字仪表盘、27英寸中控及副驾全景显示屏、24向电动调节半苯胺真皮前排座椅、后排座椅加热以及14扬声器Revel音响系统。","scd":null,"kp":["动力系统[2027款美规林肯冒险家]: 搭载2.0升涡轮增压发动机混动系统（预计与航海家混动版共享）","系统综合功率[混动系统(航海家)]: 213千瓦","发动机功率[中国版冒险家]: 190千瓦(2.0升涡轮增压)","内饰配置[中国版冒险家]: 12.3英寸数字仪表盘和27英寸全景显示屏","座椅配置[中国版冒险家]: 24向电动调节半苯胺真皮"]},{"i":2157,"as":"受我国汽车出口快速增长影响，汽车运输船需求持续攀升，带动高端船用钢材市场量价齐升。这类高端船型大量使用超薄板材以控制船舶重心。南京某钢铁企业今年船用钢材预计总量超200万吨。下游需求推动高端船板市场均价从每吨4100元涨至4300元左右。国内钢铁企业研发的船用钢材在稳定性、均匀性和厚度公差等质量指标上已达到国际领先水平，且造船企业采用锁价模式依然保持了可观的利润空间。","scd":null,"kp":["材料特性[汽车运输船用钢材]: 需使用超薄板材严格控制船舶重心","产能预期[南京某钢铁企业]: 今年船用钢材总量预计超过200万吨","市场均价[高端船板]: 从每吨4100元涨到4300元左右","质量指标[国产船用钢材]: 稳定性、均匀性、厚度公差均达到国际领先水平"]},{"i":2158,"as":"北汽集团与中国长安汽车集团正式达成战略合作。双方将聚焦前瞻技术与新兴产业、绿色低碳发展、产业链与供应链以及海外市场等关键领域开展合作协同。双方希望通过此次合作共同推动民族汽车产业的转型升级，构建中国汽车产业的新发展格局。","scd":null,"kp":["[北汽集团与中国长安汽车]: 双方将在前瞻技术与新兴产业、绿色低碳发展、产业链、供应链、海外市场等关键领域开展合作协同"]},{"i":2159,"as":"三星预计于2026下半年推出的首款“阔折叠”智能手机将采用厚度为60μm的UTG玻璃盖板。此前三星在2024年及2025年的折叠屏产品中，UTG玻璃厚度分别为30μm至50μm不等。虽然更厚的UTG玻璃会增加折叠时破裂的风险，但其核心优势是能使屏幕折痕变得更浅。消息称，今年即将发布的Galaxy Z Fold8标准版“大折叠”UTG厚度将维持45μm不变。","scd":null,"kp":["屏幕盖板厚度[三星首款“阔折叠”手机]: UTG玻璃盖板从此前尝试的30μm上调至60μm","屏幕盖板厚度[Galaxy Fold6标准版]: 30μm","屏幕盖板厚度[Galaxy Fold6 FE版]: 45μm","屏幕盖板厚度[Galaxy Fold7]: 45μm","屏幕盖板厚度[Galaxy Flip7]: 50μm"]},{"i":2160,"as":"受全球显存供应紧张及AI需求持续增长影响，英伟达悄然上调了RTX PRO 6000 Blackwell专业显卡的官方售价。目前公版标价达13250美元，较一年前发布时的8565美元上涨约55%。该系列涵盖面向专业工作站、Max-Q及服务器版本的型号，广泛应用于AI、渲染和科学计算等场景。同时，PNY等品牌的非公版产品以及零售渠道价格也出现同步上涨，但不同销售渠道间仍存在一定价格差异。","scd":null,"kp":["官方售价[RTX PRO 6000 Blackwell系列]: 13250美元（较首发价8565美元上涨约55%）","产品矩阵[RTX PRO 6000 Blackwell]: 包含Workstation Edition、Max-Q Workstation Edition和Server Edition"]},{"i":2161,"as":"因大容量电池等配置导致新能源车重持续攀升，引发关于道路损耗和“养路费”的争议。目前相关部门正研究包括“养路费”在内的汽车产业相关税费改革，以适配新的产业格局。中国汽车工业协会总工程师叶盛基表示，现行汽车税费标准难以适配产业发展实际，且此前的税费减免优惠已逐步退坡。此外，今年1月1日起实施的电动汽车能耗限值国家标准，以及2026年将对超重纯电车型实施更严格的购置税减半技术标准，均旨在抑制车企无限制增重。","scd":null,"kp":["车身重量[主流新能源车]: 2至3吨成主流，部分车重近4吨","政策动向[新能源车税费体系]: 相关部门正在研究相关政策，涉及汽车产业相关的税费体制改革","标准实施[《电动汽车能量消耗量限值第1部分：乘用车》]: 已于今年1月1日起实施，以限制能耗水平"]},{"i":2162,"as":"理想汽车全新L8车型正式从六座改为五座设计。官方表示，此举旨在为五座用户打造一台体验不妥协的旗舰SUV，新车从研发之初完全围绕“旗舰级两排五座”方向独立设计，而非基于六座车型改造。原生五座架构带来了更充分的二排空间与更完整的后备厢空间。配置上，全新L8标配72.7kWh 5C超充大电池、第三代双腔双阀空气悬架、后轮转向及马赫智能辅助驾驶，并搭载首创的联排双零重力座椅。新车将于6月23日正式上市，提供Ultra和Livis两个版本。","scd":null,"kp":["座椅布局[全新理想L8]: 原生五座SUV设计","电池配置[全新理想L8]: 72.7kWh 5C超充大电池","底盘悬架[全新理想L8]: 第三代双腔双阀空气悬架","核心系统[全新理想L8]: 标配线控转向、后轮转向、旗舰影音和马赫智能辅助驾驶"]},{"i":2163,"as":"绿联推出DXP6800 Ultra和DXP8800 Ultra两款高定位NAS新品。两款产品均采用一体成型金属机身，内置250W电源，预装8GB DDR5内存和128GB SSD系统盘，提供双10GbE RJ45网口、双雷电4接口及PCIe Gen4 ×4插槽。DXP6800 Ultra采用6+2盘位设计，搭载英特尔酷睿5 120U处理器，售价7599元；DXP8800 Ultra采用8+2盘位设计，搭载英特尔酷睿7 150U处理器，售价10999元。","scd":null,"kp":["网络接口[NAS新品DXP Ultra系列]: 双10GbE RJ45","扩展接口[NAS新品DXP Ultra系列]: PCIe Gen4 ×4插槽","硬件配置[NAS新品DXP Ultra系列]: 预装8GB DDR5 SO-DIMM内存和128GB SSD系统盘","盘位设计[DXP6800 Ultra]: 6+2盘位","处理器[DXP6800 Ultra]: 英特尔酷睿5 120U"]},{"i":2164,"as":"英特尔计划在2027年上半年推出代号“Raptor Lake Next”的新一代处理器，继续使用LGA 1700平台并重返DDR4市场，这也是该系列的第三次更新。主板厂商因DDR4需求上升，正计划增加LGA 1700平台的DDR4主板产量。此前英特尔已推出采用纯P核设计且物理兼容LGA 1700的Bartlett Lake处理器。同时，AMD也通过重新推出R7 5800X3D十周年纪念版处理器，重新回归DDR4市场。","scd":null,"kp":["发布计划[英特尔Raptor Lake Next]: 计划2027年上半年推出","平台及内存支持[Raptor Lake Next]: 继续使用LGA 1700平台并重返DDR4市场","架构设计[嵌入式Bartlett Lake处理器]: 纯P核设计，采用LGA 1700插槽"]},{"i":2165,"as":"张雪机车董事长张雪在会议上指出，国产中大排量高端摩托车与国际一线水平的核心差距体现在底盘车架开发、整车调校经验和工况数据积累上，由于起步较晚仍需时间沉淀。但他同时强调，在制造工艺和零部件供应链方面，国产摩托车已基本追平国际一线品牌。成熟且强大的本土供应链将成为促成中国高端摩托车技术快速成熟的关键性优势。","scd":null,"kp":["核心差距[国产中大排量摩托车]: 体现在整车调校经验、工况数据积累上，起步晚仍需时间打磨","技术状态[国产摩托车制造工艺]: 已基本追平国际一线品牌"]},{"i":2166,"as":"众泰汽车发布公告称，近日与重庆两山建设投资集团有限公司等债权人达成和解并签订协议。经初步估算，和解总债务约为1.7亿元，其中约1.14亿元债务将通过等额分期7年的方式偿付。此次债务和解有助于众泰汽车恢复信用体系，并取回此前被法院强制拆除的总装生产线及设备，这将直接促进其永康基地的复工复产。此外，相关和解款项的分期偿付将缓解公司短期资金压力，预计对公司本期净利润和净资产产生积极影响。","scd":null,"kp":["债务和解金额[众泰汽车与重庆两山相关公司]: 约1.7亿元","分期偿付债务[等额分期7年偿付]: 约1.14亿元"]},{"i":2167,"as":"","scd":null,"kp":[]},{"i":2168,"as":"欧洲经济区国家和瑞士已承诺向电动汽车生态系统投资近2000亿欧元。据New Automotive数据，其中1090亿欧元专门用于电池供应链，600亿欧元用于汽车制造，460亿欧元用于公共充电网络建设。尽管欧洲投入巨资发展本土供应链，但目前全球电池供应链仍由中国制造商主导。国际能源署数据显示，中国企业生产了全球近70%的电动汽车电池，并为超过80%的电动汽车供应电池电芯。","scd":null,"kp":["投资总额[欧洲经济区和瑞士EV生态系统]: 近2000亿欧元/2327亿美元","定向投资[电池供应链]: 1090亿欧元/1270亿美元","资金分配[公共领域]: 高达460亿欧元/535亿美元"]},{"i":2169,"as":"美国政府问责局（GAO）发布警告，指出美国由于后勤补给问题可能难以在远离本土的印太地区维持长期冲突。问题核心在于美军空中加油机队面临严重的老化以及备件短缺。报告显示，能够执行任务且具备作战能力的空中加油机比例已低于空军的战备标准。一旦台海等地缘紧张局势升级，老化的加油机和备件问题将使美国在该地区的军事行动面临严峻挑战，难以有效为庞大的机队提供加油和补给保障。","scd":null,"kp":["[美军印太地区后勤保障]: 缺乏足够的远距离加油和补给能力以维持长期冲突"]},{"i":2170,"as":"","scd":null,"kp":[]},{"i":2171,"as":"技术集团瓦锡兰在西班牙贝尔梅奥成功完成全球首台大型100%纯氢发动机并网测试。测试采用瓦锡兰31H2型号发动机，这是目前全球最大的纯氢发动机。测试证实了联网发电机可以在完全不依赖任何化石燃料输入的情况下运行，打破了以往发电厂需将氢气与天然气混合使用的限制。","scd":null,"kp":["燃料纯度[Wärtsilä 31H大型发动机并网测试]: 100%纯氢","[技术状态]: 世界首台在真实电网条件下完全使用纯氢运行的大型动力发动机"]},{"i":2172,"as":"德国防务技术公司Helsing在柏林国际航空航天展上展出了CA-1无人机的电子战变型CA-1EA。该机型基于CA-1 Europa架构，原动能攻击型被命名为CA-1KA。CA-1无人机重4吨级，采用单引擎低可探测设计，机身长11米，翼展10米。其自主飞行能力由Helsing的半人马AI飞行员系统和先进任务系统提供核心支持，新推出的电子攻击型号旨在提供非动能作战效果。","scd":null,"kp":["起飞重量级[CA-1 Europa无人机]: 4吨级","机身长度[CA-1 Europa无人机]: 11米","翼展[CA-1 Europa无人机]: 10米","设计特征[CA-1 Europa无人机]: 采用低可探测性（隐身）设计","核心系统[CA-1自主性]: 采用Helsing Centour AI飞行员栈和先进电子战架构"]},{"i":2173,"as":"比亚迪的一项全新人工智能专利系统能够识别车辆底部的生物。该系统通过在车辆熄火稳定时拍摄并存储底盘图像作为视觉参考基准。当车辆准备移动或进行安全检查时，系统会拍摄实时图像并与基准图像对比。软件仅对检测到变化的区域进行隔离和详细分析，从而降低计算需求并快速识别底盘下的异常物体。","scd":null,"kp":["检测原理[车底生物识别]: 车辆熄火静止时建立底盘视觉基准图像，启动时实时图像与基准对比"]},{"i":2174,"as":"土耳其国防部成功测试了首枚国产重型鱼雷AKYA。测试中，AKYA鱼雷从普雷维泽级潜艇TCG Sakarya上发射，成功捕获、追踪并击中目标，将目标船只击断为两截。此次实弹击沉演习（SINKEX）属于本月在地中海东部举行的Denizkurdu II演习的一部分，被击沉的靶船为退役训练舰TCG Sokullu Mehmet Paşa。实际沉没演习为评估鱼雷的结构破坏、进水和冲击等实战性能提供了重要数据。","scd":null,"kp":["武器类型[土耳其国产AKYA鱼雷]: 首款国产重型鱼雷","发射平台[AKYA鱼雷测试]: Preveze级潜艇TCG Sakarya","毁伤效果[AKYA鱼雷实弹打靶]: 成功捕获并追踪目标，将目标船只击断成两截"]},{"i":2175,"as":"一项新研究提出了一个有效恢复传统数学工具使用的理论框架，用于解决非互惠相互作用问题。传统物理学基于牛顿第三定律假设作用力与反作用力平衡，但现实中的许多集体系统（如鸟群、细胞和细菌）往往表现出单向关注的非互惠互动行为。新框架在不改变基础物理学的前提下，使得研究鸟群等单向集体动物行为变得更加容易。","scd":null,"kp":["物理机制[非互惠相互作用系统]: 突破牛顿第三定律，系统内个体仅对部分特定邻居（如前方个体）产生单向响应"]},{"i":2176,"as":"耶路撒冷希伯来大学的科学家发现了一种隐藏的大脑信号，能够预测个体的社交行为。研究发现，大脑在个体做出社交动作的几秒钟前就开始准备社交连接。这种独特的大脑活动模式在社交互动开始前出现，其神经活动的强度直接反映了该个体进行社交的动机强弱。研究证实，大脑在人类采取行动前就已经为社交接触做好了准备。","scd":null,"kp":["响应时间[大脑社交准备]: 发生实际社交动作前几秒钟"]},{"i":2177,"as":"阿尔托大学的研究人员开发出一种名为超晶体（metacrystals）的无源3D打印结构，用于提升6G网络性能并解决信号死区问题。未来6G网络将使用携带海量数据的高频无线电波，但这些电波穿透墙壁和人群的能力极差。与增加有源天线设备不同，这种新型无源3D打印结构无需额外供电，即可重新定向和操控无线信号。","scd":null,"kp":["信号特性[6G网络高频无线电波]: 能够承载海量数据，但穿透墙壁等障碍物的能力极弱"]},{"i":2178,"as":"一个联合研究团队发现了一种名为氧氯化钼（MoOCl）的层状晶体具备独特的光学操控特性。这种破纪录的晶体能够在类似镜面和类似玻璃的状态之间进行转换。该发现突破了依赖传统笨重组件的限制，实现了在原子尺度上对光线的操控。这种奇特的光线弯曲特性为制造微型光学芯片、增强现实（AR）显示器以及智能隐形眼镜等隐形可穿戴技术铺平了道路。","scd":null,"kp":["光学晶体特性[光操纵能力]: 可在镜面与玻璃形态间转换，能在原子尺度上操纵光线","应用前景[微型光学芯片/AR显示/智能隐形眼镜]: 助力开发真正“隐形”的可穿戴技术"]},{"i":2179,"as":"一项针对斯特鲁普任务（Stroop task）的经典心理学测试表明，先进的大型语言模型在注意力保持方面存在明显弱点。研究发现，尽管GPT-5、Claude和Gemini等AI系统能处理复杂任务，但在面对相互竞争的信息并需长时间保持专注时表现挣扎。这表明AI处理注意力的机制与人类注意力存在巨大差异。","scd":null,"kp":["AI认知注意力[经典心理学Stroop测试]: 暴露出先进大语言模型在保持专注度上存在显著缺陷，其注意力机制与人类存在差异"]},{"i":2180,"as":"NASA宣布了阿尔忒弥斯三号任务的机组人员，该任务定于2027年发射，是人类重返月球前最复杂的太空任务之一。任务将由太空发射系统（SLS）火箭从佛罗里达州肯尼迪航天中心发射，使用猎户座飞船将宇航员送入低地球轨道，完成系统检查后，将与商业测试版进行首次交会对接演示。这些地球轨道测试对计划于2028年首次登陆月球南极的阿尔忒弥斯四号任务至关重要。","scd":null,"kp":["发射时间[阿耳忒弥斯三号任务]: 2027年","任务节点[首次载人登月南极(阿耳忒弥斯四号)]: 2028年"]},{"i":2181,"as":"科学家开发出一种全新的基于探测器的方法，用于测量膨胀宇宙中的引力波。引力波是时空的微小扭曲，自2015年首次直接探测以来，研究人员已熟练解读穿过相对平静区域的合并黑洞信号。然而，在不断膨胀演化的宇宙背景下测量引力波极为困难。新方法澄清了在不断演化的宇宙中应该如何准确测量引力波信号。","scd":null,"kp":["探测方法[膨胀宇宙中的引力波测量]: 开发出一种基于探测器的新方法以阐明演化宇宙中的引力波测量"]},{"i":2182,"as":"麻省理工学院（MIT）研究人员正在测试一种新型双模式火箭推进系统，旨在将微型卫星用于深空探索。该系统在单一包装内结合了化学和电推进两种不同形式。其核心设计在于使用单一推进剂同时为化学和电推进器提供动力，免除了传统系统需要独立燃料源增加的复杂性与空间占用，使微型卫星能够同时执行快速机动和高效的远距离飞行。","scd":null,"kp":["推进系统[微型卫星双模式火箭]: 将化学推进与电推进结合，使用单一推进剂，兼具快速机动与高效长途飞行能力"]},{"i":2183,"as":"冷泉港实验室（CSHL）的科学家发现了一种作为身体发育计时器的新型遗传生物钟。这种生物钟负责协调生长所需的基因活性爆发。当此时钟发生故障时，机体的发育进程会完全停止。这一发现证实了该发育计时器在协调正常生长和成熟方面起着决定性作用。","scd":null,"kp":[]},{"i":2184,"as":"科学家偶然发现脱离的海参组织在天然海水中存活、愈合并持续生长了三年以上，挑战了分离的动物组织最终会死亡的生物学基本假设。这是首次有记录表明废弃组织能在非无菌、非严格控制的实验室环境外存活并继续发育如此长时间。该发现为细胞寿命和再生极限研究提供了全新模型，对生物医学研究具有重要意义。","scd":null,"kp":[]},{"i":2185,"as":"一项由美国国立卫生研究院（NIH）资助的研究表明，在清醒状态下通过触发特定大脑区域的睡眠相关过程，即可实现部分大脑功能的恢复。研究在清醒小鼠的特定脑区中重现了关键的类睡眠大脑模式，成功逆转了睡眠剥夺带来的部分认知影响，并维持了记忆与学习能力。该发现证实大脑无需进入完全睡眠状态，即可在局部目标区域执行神经修复功能。","scd":null,"kp":[]},{"i":2186,"as":"美国相关报道指出，美国政府不太可能将针对Anthropic实施的人为出口管制措施扩大到其他人工智能公司。","scd":null,"kp":["出口管制政策[针对其他AI公司]: 美国政府不太可能将类似Anthropic的出口管制范围扩大"]},{"i":2187,"as":"","scd":null,"kp":[]},{"i":2188,"as":"广汽本田计划在2027年推出覆盖燃油、混动和新能源三大领域的三款全新车型。其中包括全新一代雅阁、搭载第五代i-MMD混动技术的车型，以及基于中国新能源平台打造的自研车型。自2027年起，广汽本田将全面导入第五代i-MMD混动系统，该系统进一步提升了操控稳定性与轻量化，燃油效率较现款提升10%以上。首款搭载该系统的车型计划于明年第一季度发布。此外，广汽本田今年累计销量为54219辆，同比下降56.50%。","scd":null,"kp":["新车型规划[广汽本田(至2027年)]: 2027年推出覆盖燃油、混动、新能源三大领域的三款全新车型","技术导入[第五代i-MMD混动系统]: 2027年起全面导入，进一步提升操控稳定性与轻量化水平","燃油使用效率[第五代i-MMD混动系统]: 较现款提升 10% 以上"]},{"i":2189,"as":"","scd":null,"kp":[]},{"i":2190,"as":"近期Anthropic因出口管制暂停模型供应并非首例。早在1999年，苹果初代Power Mac G4因算力达0.8至3.2 GFLOPS达到当时“超级计算机”标准，被美国政府限制向约50个国家或地区出口。时任CEO史蒂夫·乔布斯借此机会投放电视广告进行营销。2000年1月，美国政府将超级计算机出口管制门槛提升至6.5 GFLOPS，Power Mac G4随之解除管制，恢复自由出口。","scd":null,"kp":["出口管制措施[Anthropic部分大模型]: 因美国出口管制禁令紧急暂停供应 Mythos 5/Fable 5 模型","算力指标[Power Mac G4(1999年)]: 每秒超 10 亿次计算能力，达到超级计算机出口管制标准"]},{"i":2191,"as":"近期制冷剂价格创近10年同期新高。截至6月12日，常用制冷剂R134a市场均价达到每吨62500元，同比涨幅超30%。新能源车热管理系统对制冷剂用量明显高于传统燃油车，同时冷链物流仓储容量的持续扩张释放了增量需求。供需偏紧的局面直接推动了制冷剂市场价格上行。","scd":null,"kp":["价格[制冷剂R134a(截至6月12日)]: 市场均价达 62500 元/吨（另一常用制冷剂为 59727 元/吨）","价格同比涨幅[常用制冷剂R134a等]: 涨幅分别达 34.13% 和 30.77%（创近10年同期新高）","冷链物流需求总量[2025年中国市场预测]: 3.814 亿吨（同比增长 4.5%）","冷库总容量[2025年中国市场预测]: 2.67 亿立方米（同比增长 5.53%）"]},{"i":2192,"as":"因后悬架部件存在失效隐患，美国本田汽车公司召回超过88万辆汽车，涉及2016-2022款Pilot、2017-2023款Ridgeline、2019-2023款Passport及2014-2020款讴歌MDX。车辆后控制臂可能出现断裂，导致车辆失控。经销商将免费检查后副车架并安装加固套件。本田预估缺陷车辆比例为1%，目前暂未收到相关保修索赔或伤亡报告。","scd":null,"kp":["召回数量[本田在美汽车(后悬架隐患)]: 超过 88 万辆","缺陷概率[涉事车辆后悬架组件]: 预估存在缺陷(如后控制臂断裂)的车辆占比约 1%","解决方案[后悬架部件隐患召回]: 免费检查后副车架并安装后副车架加固套件"]},{"i":2193,"as":"","scd":null,"kp":[]},{"i":2194,"as":"小米米家扫拖机器人6于2026年4月发售，提供28000Pa吸力与40mm越障高度。机身厚度为90mm，采用双摄像头定位系统，配备双重防缠设计，支持地毯识别并智能抬升拖布。京东618大促期间，在国补、晒单返豆及以旧换新等优惠叠加下，水箱版最低至1543元，上下水版最低至1887元。","scd":null,"kp":["吸力[米家扫拖机器人6]: 28000Pa","越障高度[米家扫拖机器人6]: 40mm","机身厚度[米家扫拖机器人6]: 90mm","定位系统[米家扫拖机器人6]: 双摄像头定位系统","防缠设计[米家扫拖机器人6]: 内置双重防缠设计"]},{"i":2195,"as":"小米米家净水器2 Pro双出水1200G官方定价2899元，京东以旧换新补贴后降至1206元。该净水器过滤精度达0.0001微米，可滤除145种污染物及99.9%重金属铅。配备8年寿命的进口高脱盐RO膜，通量达1200G/1600G。采用专利“双龙头、双水路”设计，上龙头出母婴级纯净水，下龙头出深滤生活水。支持小米澎湃互联App查看水质和自定义出水模式。","scd":null,"kp":["过滤精度[净水器2 Pro]: 0.0001微米","过滤能力[净水器2 Pro]: 可滤除145种污染物","去除率[重金属铅]: 99.9%","去除率[PFAS&PFOA]: 99%","RO滤芯寿命[净水器2 Pro]: 8年"]},{"i":2196,"as":"微软CEO纳德拉表示，AI可能导致部分岗位被取代，但构建全经济体系共享的AI生态系统至关重要，否则经济无法实现实质性增长。他强调自己是“Token最大化者”，但Token的边际成本必须匹配实际价值，前沿模型不应用于解决非前沿问题。关于AGI，他认为编程等闭环任务进展显著，但AI并非人类的最后一项技术发明。","scd":null,"kp":["Token经济学[前沿模型应用]: 边际成本必须匹配其实际价值，不应用于解决非前沿问题"]},{"i":2197,"as":"","scd":null,"kp":[]},{"i":2198,"as":"韩国政府启动“超级创新经济项目”，计划投资5000亿韩元（约22.3亿元人民币）攻关下一代功率半导体。功率半导体能提供稳定供电、提高能效并降低损耗，广泛应用于AI数据中心、能源系统、电动汽车及航空航天等领域。研发重点包括耐高温、低能耗、高转换效率的碳化硅（SiC）等先进材料。韩国政府已要求所有相关企业参与，旨在构建完整的产业生态体系。","scd":null,"kp":["研发投资[下一代功率半导体]: 5000亿韩元(约22.3亿元人民币)","材料特性[碳化硅(SiC)等先进功率半导体]: 相比传统硅基半导体耐高温能力更高、能耗更低、转换效率更高"]},{"i":2199,"as":"央视曝光地下工厂将新能源汽车废旧动力电池违规改装后流入市场。数据显示，电动自行车火灾中约33%由非法改装电池引发，其中约80%的电芯来自新能源车废旧电池。深圳众投新能源有限公司在隐蔽山坳设立拆解厂，将废旧电池拆解打包成电动自行车违规超标锂电池售卖。此行为违反我国现行管理办法中禁止将废旧动力电池加工用于电动自行车的明确规定。","scd":null,"kp":["起火原因[全品类电动自行车火灾]: 约33%由非法改装电池引发","电芯来源[起火改装电池]: 约80%来自新能源车废旧动力电池","回收禁令[新能源汽车废旧动力电池]: 明确规定不得直接或加工后用于电动自行车"]},{"i":2200,"as":"安克创新科技股份有限公司已通过港交所IPO聆讯，并更新聆讯后资料集。该公司于6月3日提交上市申请书，由中金公司、高盛和摩根大通担任联席保荐人。通过聆讯是港股IPO流程中耗时最长的步骤，安克创新预计将在两到三天内开始上市路演。","scd":null,"kp":[]},{"i":2201,"as":"日本东京电力公司宣布，福岛第一核电站5号和6号机组的乏燃料池冷却系统因故障于13日停运。经检查未发现设备异常，系统在约一个半小时后恢复运行，期间水温与周边辐射水平未出现变化。近期日本其他核电站也频发故障：福岛第二核电站因水泵故障冷却系统停运，美滨核电站发生蒸汽泄漏停堆，女川核电站检测到微量放射性蒸汽。","scd":null,"kp":["停运时长[福岛第一核电站5/6号机组乏燃料池冷却系统故障]: 约1.5小时","环境监测[乏燃料池冷却系统故障期间]: 水温及周边辐射水平均未出现变化","温度缓冲[福岛第二核电站1号机组燃料池冷却停止时]: 停运时水温26.5℃，距65℃上限约8天缓冲时间","事件定性[美滨核电站3号机组蒸汽泄漏]: 属于二次系统蒸汽泄漏，无放射性影响"]},{"i":2202,"as":"AKKO发布5075 V5系列磁轴键盘，售价99元起，于6月17日全平台开售。该键盘采用75%配列和Gasket结构，三模版本内置10000mAh电池。TMR版本搭载TMR传感器，具备高灵敏度和超低磁滞特点，支持双8KHz回报率和128K扫描采样率，兼容五脚机械轴混轴。提供凯华极光、棱镜和白泽三种磁轴选项，初始压力25-30gf，触底压力48-55gf。","scd":null,"kp":["电池容量[5075 V5三模键盘]: 10000mAh","回报率[5075 V5键盘]: 双8KHz","扫描采样率[5075 V5键盘]: 128K","传感器特性[TMR版本(对比霍尔效应)]: 拥有更高灵敏度、超低磁滞特点","初始压力[凯华极光磁轴]: 30±10gf"]},{"i":2203,"as":"华为终端平板与PC产品线总裁朱懂东宣布，华为鸿蒙商用台式机将于9月正式登场，7至8月份进行送测和试商用。目前华为已推出擎云HM740和HM940商用办公设备。商用鸿蒙电脑操作系统与消费级系统不同，专门进行了接口改造并加入了安全芯片。","scd":null,"kp":[]},{"i":2204,"as":"","scd":null,"kp":[]},{"i":2205,"as":"","scd":null,"kp":[]},{"i":2206,"as":"","scd":null,"kp":[]},{"i":2207,"as":"宁德时代（CATL）CEO曾毓群表示，纯固态电池在电动汽车中的大规模普及仍需数年时间，2030年前实现大规模商业化可能性极低。固态电池的商业化仍需技术突破和解决多项制造参数问题，初期将仅应用于售价超过25万元人民币的高端汽车平台。据悉，宁德时代的全固态电池技术目前处于九级评估体系中的第四级。","scd":null,"kp":["商业预期[纯固态电池]: 距离大规模普及仍有数年之遥，需技术突破及制造参数优化","应用定位[固态电池初期商业化]: 仅限于高端汽车平台"]},{"i":2208,"as":"","scd":null,"kp":[]},{"i":2209,"as":"全球供应链的复杂性促使企业应用人工智能技术来提升生产力、降低成本并构建弹性。地缘政治波动暴露了传统依赖电子表格和邮件的治理流程的局限性。GEP的2026年展望报告指出，75%的受访者认为AI已经显现出传统供应链管理方法的不足。AI创新正驱动全球供应链体系向更具适应性和更快的运营模式转型。","scd":null,"kp":[]},{"i":2210,"as":"哈根达斯法国阿拉斯工厂正致力于实现冰淇淋供应链脱碳。该工厂投资可再生能源，并协助农户适应气候变化，重点支持再生农业的发展，以增强农户的运营韧性。多年来，该工厂获得了数百万欧元的资金用于现代化升级和可持续发展项目。","scd":null,"kp":[]},{"i":2211,"as":"起亚在成功推出PV5电动货车后，即将推出尺寸更大的PV7电动货车。PV5于去年上市，2026年第一季度在欧洲轻型电动商用车市场占据了9%的份额。该系列车型基于E-GMP.S灵活平台打造，集成了现代汽车集团的软件定义汽车技术和先进的电池、动力总成。","scd":null,"kp":["车型定位[Kia PBV车型]: 中型纯电动厢式货车PV5及即将推出的更大尺寸PV7","市场占比[2026年第一季度欧洲轻型商用车]: 9%"]},{"i":2212,"as":"Ariel Rider Kepler被评价为一款出色的胖胎通勤电动自行车。该自行车重达53.5公斤，配备24×4.0英寸的胖胎，提供了舒适的直立骑行姿势和极具信心的操控感，非常适合城市通勤，填补了胖胎通勤车细分市场的空白。","scd":null,"kp":["整车重量[Ariel Rider Kepler胖胎通勤电动自行车]: 53.5 kg (118磅)","轮胎规格[Ariel Rider Kepler]: 24×4.0英寸胖胎"]},{"i":2213,"as":"特斯拉向瑞典和荷兰的监管机构提供了自行发布且夸大的“全自动驾驶”（FSD）安全数据，以寻求欧洲市场的批准。其声称FSD能挽救3.2万人的生命，但独立研究人员指出，该数据基于将美国所有车辆（包括卡车和摩托车）替换为特斯拉FSD车辆的不合理假设，存在严重的误导性。","scd":null,"kp":["安全宣称为全自动驾驶]: 可挽救32,000条生命"]},{"i":2214,"as":"西班牙拉科鲁尼亚大学的研究显示，西班牙海岸线具有发展海上漂浮光伏的巨大潜力。根据海洋空间规划标准，预计可容纳4.45吉瓦至6.48吉瓦的装机容量，足以满足该国高达9%的电力需求。潜力区域主要集中在直布罗陀海峡-阿尔沃兰海和加那利群岛等地。","scd":null,"kp":["装机容量潜力[西班牙海上光伏发电]: 4.45–6.48 GW","需求满足[西班牙国家电力需求]: 最高覆盖9%"]},{"i":2215,"as":"奥地利经济事务部启动了2026年第二轮光伏和储能补贴，总预算为1200万欧元，重点激励电池储能和欧洲制造的组件。针对不同功率等级的系统（10千瓦以下、10-20千瓦、20千瓦以上）分配了200万至400万欧元不等的预算。第一轮补贴显示约90%的申请包含了电池储能系统。","scd":null,"kp":["补贴预算[奥地利2026年第二轮太阳能加储能资金]: 1200万欧元","系统配置偏好[奥地利第一轮补贴申请]: 约90%的光储系统申请包含电池"]},{"i":2216,"as":"利比里亚首座公用事业规模的光伏电站——20兆瓦的Mount Coffee太阳能园区正式投入运营。该电站位于原有的88兆瓦水电站旧址内，于2024年10月开始建设。利比里亚政府已与世界银行签署融资协议，计划将该光伏电站的产能进一步扩建10兆瓦。","scd":null,"kp":["装机容量[利比里亚Mount Coffee首座公用事业规模太阳能电厂]: 20 MW","扩建规划[Mount Coffee太阳能园区]: 10 MW"]},{"i":2217,"as":"HVR Solar计划在印度北方邦阿姆罗哈建设一座产能为1.2吉瓦的TOPCon太阳能电池制造工厂。该公司已与多家中国和印度企业签署了技术和设备合作谅解备忘录，其中包括深圳汉斯光伏设备有限公司、Gentech Technology和IndyGreen Technologies，以支持该项目的实施。","scd":null,"kp":["产能规划[HVR Solar位于印度阿姆罗哈的工厂]: 1.2 GW","技术路线[电池工厂]: TOPCon太阳能电池"]},{"i":2218,"as":"中车株洲院将在2026年欧洲智慧能源展上首次向欧洲市场展出其6.X液冷储能系统。该系统实现了能量密度提升25%和占地面积减少20%的技术升级。目前，该公司的储能业务已覆盖超过25个国家和地区，其建设的保加利亚200兆瓦时储能项目已于2026年4月实现全容量并网。","scd":null,"kp":["系统能量密度[6.X液冷储能系统]: 相对提高25%","占地面积[6.X液冷储能系统]: 减少20%"]},{"i":2219,"as":"中国研究团队提出了一种新型界面缓冲策略，成功研发出效率高达20.21%的伪平面异质结有机太阳能电池，创下该结构的世界纪录。该策略有效克服了供体的溶剂诱导膨胀和侵蚀问题，提升了器件的稳定性和制造可靠性。伪平面结构结合了平面和体异质结的优势，被广泛应用于高性能有机太阳能电池。","scd":null,"kp":["光电转换效率[伪平面异质结有机太阳能电池]: 20.21% (世界纪录)","界面工程策略[克服溶剂诱导溶胀和侵蚀]: 新型界面缓冲策略"]},{"i":2220,"as":"华东理工大学的科学家深入研究了异质结太阳能电池中低银电极的降解机制。研究发现，在镀银铜电极的热老化过程中，银铜互扩散现象会显著增加接触电阻，导致电池电性能退化。微观结构的演变使得导电机制从烧结增强转变为缺陷驱动的网络崩溃，该发现为提升金属化可靠性提供了设计指导。","scd":null,"kp":["降解机理[低银异质结太阳能电池铜镀银电极热老化]: 银铜相互扩散显著增加接触电阻","性能退化机制[微观结构演变]: 从烧结增强导电性转变为缺陷驱动的网络击穿"]},{"i":2221,"as":"2026年前五个月，塞浦路斯削减了162吉瓦时的太阳能发电量，占该国潜在光伏发电量的65%以上。电网限制和必须运行的传统发电机组是限制可再生能源输出的主要原因。目前，限电措施已开始影响住宅光伏系统，引发了项目可行性和缺乏补偿机制的担忧。","scd":null,"kp":["弃电量[2026年前五个月]: 162 GWh","弃光率[潜在太阳能发电量]: 65%"]},{"i":2222,"as":"国家能源集团在江苏建成了全球最大的太阳能储氢一体化项目——国华如东项目。该项目总装机容量为400兆瓦，集成了沿海光伏、60兆瓦/120兆瓦时电池储能以及年产量482吨的绿氢生产设施。项目预计在2026年8月完成氢能调试后全面投入运营。","scd":null,"kp":["项目规模[太阳能储氢一体化]: 400 MW","储能配置[电池储能系统]: 60 MW/120 MWh","绿氢产能[制氢设施]: 482吨/年"]},{"i":2223,"as":"大阪都市大学的研究人员开发出一种无需电池的自调节人工光合作用系统。该系统通过在电解槽中直接加入自调节化学成分，去除了昂贵的电池控制系统，能够更稳定地利用阳光将水和二氧化碳转化为甲酸等可用燃料，为清洁能源储存提供了一种更简单、低成本的路径。","scd":null,"kp":["[人工光合作用系统]: 无需电池控制即可更稳定地生产太阳能燃料","[系统设计]: 将自调节化学成分直接集成到电解槽中"]},{"i":2224,"as":"","scd":null,"kp":[]},{"i":2225,"as":"斯克里普斯研究所的研究团队联合开发了一个全新的纳米圆盘研究平台。该平台能够更真实地呈现病毒表面蛋白质，包含通常在人工简化版本中被忽略的膜嵌入部分。这一突破使科学家能够直观地观察抗体如何有效识别并中和真实病毒，为未来开发更高效的疫苗提供了关键的隐藏线索。","scd":null,"kp":[]},{"i":2226,"as":"","scd":null,"kp":[]},{"i":2227,"as":"","scd":null,"kp":[]},{"i":2228,"as":"","scd":null,"kp":[]},{"i":2229,"as":"《宇宙学与天体粒子物理学杂志》发表的新研究指出，人工智能能够以更低成本和更快速度寻找新物理定律。然而，AI也存在过度依赖已有训练数据的局限性，导致其在面对无法用现有标准宇宙学模型（ΛCDM）解释的新物理现象时，难以识别出近在眼前的真实新现象。","scd":null,"kp":[]},{"i":2230,"as":"由哈佛大学和普林斯顿大学领导的国际研究团队成功绘制了成年果蝇中枢神经系统的完整连线图。这是首个完整的从大脑到身体的神经连接图。该发现为科学家提供了研究大脑与身体协同产生复杂行为的新途径，揭示了复杂行为源于分布式的神经协同工作，而非由中央控制器主导。","scd":null,"kp":["[神经系统连接图谱]: 绘制成年果蝇中枢神经系统的首套完整全脑至全身接线图"]},{"i":2231,"as":"","scd":null,"kp":[]},{"i":2232,"as":"据The Information报道，Salesforce已决定斥资36亿美元收购客户AI智能体Fin。","scd":null,"kp":["收购金额[Salesforce收购Customer AI Agent Fin]: 36亿美元"]},{"i":2233,"as":"","scd":null,"kp":[]},{"i":2234,"as":"据The Information报道，一家专注于英伟达（Nvidia）服务器市场的初创公司以8亿美元的估值筹集了1亿美元资金。","scd":null,"kp":["融资金额[Nvidia服务器市场初创公司]: 1亿美元","公司估值[Nvidia服务器市场初创公司]: 8亿美元"]},{"i":2235,"as":"据The Information报道，腾讯投资支持了一位前阿里巴巴研究员新建的人工智能实验室。","scd":null,"kp":[]},{"i":2236,"as":"","scd":null,"kp":[]},{"i":2237,"as":"患有肌萎缩侧索硬化症（ALS）的Casey Harrell成为大脑植入物的“首位超级用户”。他的大脑中植入电极已近三年，自2023年起借助脑机接口（BCI）成功实现“说话”功能。目前他已独立使用该设备数千小时，不仅用于日常沟通，还用于上网和完成工作，生活质量得到革命性改善。","scd":null,"kp":["植入物使用时间[ALS患者脑机接口电极阵列]: 近三年（数千小时）"]},{"i":2238,"as":"传统空调目前占全球电力使用的7%和温室气体排放的3%。为应对气候变暖，科学家和初创企业正致力于推进固态冷却技术。该技术目前已小规模应用于迷你冰箱、电动汽车电池和高端游戏电脑。固态空调旨在提供更环保的制冷替代方案，应对全球空调设备数量预计到2050年将增加两倍带来的环境挑战。","scd":null,"kp":["空调数量[2050年全球预测]: 三倍于当前数量","电力占比[全球空调使用]: 7%","温室气体排放占比[全球空调使用]: 3%"]},{"i":2239,"as":"","scd":null,"kp":[]},{"i":2240,"as":"","scd":null,"kp":[]},{"i":2241,"as":"加拿大安大略省通过长期容量窗口1（LT2）采购计划，成功采购了640兆瓦的8小时电池储能项目。三个中选项目均包含50%的原住民股权。安大略省的公用事业规模电池储能总采购量已达到约3.6吉瓦，以满足加速电气化和工业负荷增长带来的巨大电力需求。","scd":null,"kp":["储能规模[加拿大安大略省采购]: 640 MW","储能时长[电池存储项目]: 8小时","项目数量[采购中标]: 3个","股权结构[中标项目特征]: 50%原住民股权"]},{"i":2242,"as":"2026年第一季度，中国新增新型储能装机容量达10.5吉瓦/27.1吉瓦时，同比增长分别达60%和76%。数据显示中国储能市场结构发生显著变化，独立储能项目主导了新增装机，而可再生能源配储和用户侧储能均出现下降。电网侧和发电侧新增新型储能达9.9吉瓦。","scd":null,"kp":["新增功率/容量[2026年一季度中国新型储能]: 10.5 GW / 27.1 GWh","并网增速[2026年一季度储能项目]: 同比增长41%","功率/容量增速[新型储能环比]: 功率上升60%，能量容量上升76%"]},{"i":2243,"as":"国家能源集团投资的国华如东光储氢一体化项目在江苏建成，成为目前中国最大的同类集成项目。该设施包含400兆瓦沿海光伏电站、60兆瓦/120兆瓦时电池储能系统、产能为1500 Nm³/h的绿氢生产设施以及220千伏陆上变电站，并配备了加氢站，实现了光伏发电、电池储能与绿氢生产的深度融合。","scd":null,"kp":["项目状态[国华如东光储氢一体化项目]: 建成投产","项目地位[中国光储氢项目]: 全球最大"]},{"i":2244,"as":"据《中国可再生能源发展报告2025年度》预计，2026年中国风电与光伏新增装机规模约3亿千瓦（风电1亿千瓦，太阳能2亿千瓦）。2025年中国可再生能源新增装机达4.52亿千瓦，风光总装机历史性超火电，年发电量近4万亿千瓦时。全球范围内，2025年新增可再生能源装机中，中国贡献率高达63.6%，是推动全球增长的核心引擎。","scd":null,"kp":["新增装机[2026年中国风光预计]: 约3亿千瓦","新增装机[2026年中国风电]: 约1亿千瓦","新增装机[2026年中国光伏]: 约2亿千瓦","新增装机[2025年中国可再生能源]: 4.52亿千瓦","总装机占比[2025年中国可再生能源]: 占总装机比重60.1%"]},{"i":2245,"as":"氢能产业正走出低迷期并进入爬坡发展阶段。车用燃料电池系统技术日益成熟，成本可控且基础设施不断完善。专家预计，绿色氢能将在2030年迎来爆发期，长周期绿氢储能潜力巨大。随着技术突破与成本下降，我国调峰火电厂未来将逐步走向纯氢发电，预计2060年约需6500万吨绿氢以支撑长时储能需求。","scd":null,"kp":["[氢能与燃料电池汽车产业]: 走出低迷期，进入规模化应用爬坡期","[燃料电池汽车技术及运营]: 技术日趋成熟，成本下行，运营稳定可靠","[氢能产业发展阶段]: 已突破临界点"]},{"i":2246,"as":"算力网络建设正在全面加速，促使光通信、云服务及服务器等全产业链步入高景气周期。截至3月底，中国智能算力规模达1882 EFLOPS，围绕国家枢纽节点已建成超70条算力大通道。算力网定位为国家级基础设施，年建设投入规模有望突破万亿元，正推动AI基础设施实现从单点建设向跨区域联网调度体系的全面升级。","scd":null,"kp":["算力规模[2026年3月底中国智能算力]: 1882 EFLOPS","算力大通道[国家算力枢纽节点]: 已建成超70条","硬件规模[国家超算互联网平台]: 超300万CPU核和超20万GPU卡","硬件规模[国家超算互联网核心节点]: 超过6万张国产AI加速卡"]},{"i":2247,"as":"企业AI落地面临两大堵点：一是数据虽互联但无法被AI准确理解并应用于业务决策；二是项目仅停留在可视化与辅助问答层面，未能切入核心业务，缺乏量化价值评估。为此，企业应摒弃重资产搭建平台的惯性思维，采取“轻量切入、快速见效”的策略，从具体决策场景切入，以真实运营数据为样本推动AI落地。","scd":null,"kp":["[AI企业落地痛点]: 数据可见不可用，缺乏现场数据与业务规则的翻译层","[AI应用停滞原因]: 仅停留于数据可视化与辅助问答，未嵌入核心决策环节"]},{"i":2248,"as":"数据工程师正作为人工智能的“营养师”，负责数据标定、传感器数据采集和高精地图制作等工作。以吉林微思智能科技为例，工程师们对路测数据进行精细加工，为自动驾驶模型提供高质量的训练数据“食材”，从而保障智能驾驶模型可靠落地，为汽车及相关产业的智能化升级筑牢数据“底座”。","scd":null,"kp":[]},{"i":2249,"as":"智能戒指正凭借其简约的设计和不断升级的健康与运动数据监测功能悄然崛起，其全天候监测能力已比肩智能手表。当前智能穿戴行业的主流趋势并非用智能戒指完全取代智能手表，而是形成搭配使用模式：利用智能戒指进行全天候持续监测，依靠智能手表处理运动需求与消息通知。","scd":null,"kp":["[智能戒指核心优势]: 监测能力比肩智能手表且省去屏幕设计","[可穿戴设备应用趋势]: 戒指与手表搭配使用以实现全天候监测与消息处理"]},{"i":2250,"as":"德国博世集团在柏林举办互联世界大会，探讨AI向物理世界规模化应用，制造业成为重要落地场景。博世指出人形机器人产业快速发展，工厂因高标准化将率先成为关键落地场景。具身智能机器人需融合视觉、触觉等微机电系统传感器实现环境感知，硬件与AI深度耦合。中国拥有完整制造业体系与丰富的真实应用场景，在推动AI与实体经济融合及全球机器人产业发展中发挥日益突出的作用，今年博世已在中国成立机器人中心。","scd":null,"kp":["[人形机器人规模化应用]: 取决于场景成熟度，工厂环境将率先成为关键落地场景","[具身智能感知能力]: 需融合视觉、触觉等多维感知，微机电系统传感器是实现对物理世界整体感知的核心","[未来具身智能机器人]: 硬件系统与AI深度耦合的高度融合系统"]},{"i":2251,"as":"今年1至5月，国家铁路累计发送货物16.7亿吨，同比增长1.8%，日均装车18.63万车。期间铁水联运量达758万标箱，出口商品车发送82.4万台。铁路部门大力发展物流总包与全程物流服务，累计签订合同运量11.5亿吨。同时，重点保障农资与电煤运输，粮食发送4880.6万吨，煤炭8.7亿吨。国际班列稳步增长，中欧（亚）班列开行15506列。铁路物流金融服务累计融资突破100亿元。","scd":null,"kp":["货物发送量[国家铁路1至5月]: 16.7亿吨","同比增长[国家铁路1至5月货物发送量]: 1.8%","日均装车[国家铁路1至5月]: 18.63万车","单日装车历史新高[5月2日]: 20.24万车","铁水联运量[国家铁路1至5月]: 758万标箱"]},{"i":2252,"as":"","scd":null,"kp":[]},{"i":2253,"as":"华为云提出搭建本土化智能体能力底座，从实践、技术、生态三大维度脱离对外部算力的依赖。该能力底座以价值导向为核心，强调提升每个词元背后的生产力。在智慧医疗领域，瑞金医院联合华为打造国内首个临床级病理大模型RuiPath，覆盖90%的常见癌种。该方案采用端云协同混合计算架构，基层医院仅需小样本数据即可构建专属模型，且普通消费级PC即可完成推理部署，大幅降低医疗AI落地门槛。","scd":null,"kp":["[国产AI能力底座]: 从实践、技术、生态三大维度搭建本土化智能体能力底座，脱离“万国牌”算力依赖"]},{"i":2254,"as":"词元调用量的指数级爆发正推动AI从云端走向终端。我国日均词元调用量已突破140万亿，建成超10万个高质量数据集。为解决高成本与隐私隐患，端侧智能体技术取得突破。荣耀发布YOYO Claw技术，通过智能路由实现简单任务100%端侧执行，达成词元零消耗。商汤绝影推出Sage Box设备，在车端实现复杂智能体能力，单台车日均节省约30元云端费用。中国移动也构建了高速数据网以保障数据安全流通。","scd":null,"kp":["日均词元调用量[截至3月]: 140万亿","日均词元调用量[较2024年初增长]: 超千倍","高质量数据集[截至2025年底]: 超10万个","总体量[高质量数据集]: 890PB","[端侧智能体任务调度]: 依托智能路由算法，简单高频任务100%端侧执行实现词元零消耗，复杂任务按需调用云端"]},{"i":2255,"as":"工信部与国务院国资委启动2026年度人形机器人实景实训专项行动，目标到2026年底实现万台级规模落地能力，凝练百个高价值应用场景。行动聚焦工业、服务、特种三大领域部署9个具体场景，通过集约化建设实训空间解决真机数据积累不足和实景需求脱节的痛点，降低企业试错成本。人形机器人产业将呈现三大发展趋势，其中工业场景因结构化程度高将率先实现规模突破。","scd":null,"kp":["[人形机器人实景实训专项行动启动年度]: 2026年度","[重点产品应用验证及常态部署时间]: 2026年底","[凝练形成高价值应用场景目标]: 百个以上","[带动形成规模落地能力目标]: 万台级","[实景实训专项行动聚焦领域]: 工业、服务、特种三大领域"]},{"i":2256,"as":"“AI中转站”作为整合多家大模型API的代理平台迅速走红，但也引发隐私泄露与数据倒卖等安全问题。市场将其分为三类：一是云厂商合规聚合型平台，具备合规资质，为主流商用选择；二是正规API代理，合规批量采购分销，风险较低；三是灰黑产中转站，通过破解网页端口提供服务，存在侵权、数据窃取、服务骤停等严重隐患，不适合商业及涉密业务使用。","scd":null,"kp":["[AI中转站]: 介于用户和AI模型厂商官方服务之间的代理层","[官方正规MaaS服务]: 依托头部云厂商算力底座与合规资质的云厂商合规聚合型中转站"]},{"i":2257,"as":"挪威国有可再生能源企业Statkraft已正式批准在挪威建设一个抽水蓄能水电项目。该决定旨在进一步扩大可再生能源储能布局，提升电力系统的调节能力。","scd":null,"kp":["[Statkraft挪威项目]: 批准抽水蓄能水电项目"]},{"i":2258,"as":"Energy Dome公司与SRP（盐河项目）达成合作，计划在美国亚利桑那州共同开发一个装机容量为19兆瓦的二氧化碳电池储能项目。该项目将采用二氧化碳电池技术进行电能存储。","scd":null,"kp":["开发规模[亚利桑那州二氧化碳电池]: 19兆瓦"]},{"i":2259,"as":"爱尔兰公司NZE提议建设一个规模达600兆瓦的基于氢能的储能项目。该项目旨在利用氢能技术实现大规模电能的长期存储与调节，进一步推动可再生能源的发展。","scd":null,"kp":["提议项目规模[NZE爱尔兰氢存储项目]: 600兆瓦"]},{"i":2260,"as":"工信部已完成《光伏产品分级分类 第1部分：光伏组件》等6项电子行业标准的编制工作，并于2026年6月13日至7月12日进行报批意见公示。社会各界可在公示期内通过电话或书面形式向相关标准化技术组织反馈意见。","scd":null,"kp":["公示时间[《光伏产品分级分类 第1部分：光伏组件》]: 2026年6月13日－2026年7月12日"]},{"i":2261,"as":"三峡清洁能源封闭式基础设施证券投资基金正式获中国证监会批复，成为三峡集团首单及东北地区首单能源公募REITs。该基金底层资产为辽宁庄河Ⅲ海上风电场，装机容量29.88万千瓦。本次发行回收资金将用于东北地区新增新能源项目建设，有助于盘活存量资产，促进增量投资，增强三峡能源持续投资能力，推动区域绿色低碳转型。","scd":null,"kp":["装机容量[辽宁庄河Ⅲ海上风电场]: 29.88万千瓦","[全容量并网]: 2020年11月"]},{"i":2262,"as":"近期国家能源监管机构连续开出重磅罚单，多家发电企业因违反电力市场规则接连被罚。山东区域华能山东、大唐山东因涉嫌不正当竞争、串通报价被罚55万元；贵州5家企业因违反运行规则被罚46万元。此前，湖南能源监管办对华能、大唐、华电等15家头部发电企业开出690万元罚单，违规事由均为不遵守电力市场运行规则。","scd":null,"kp":[]},{"i":2263,"as":"华润新能源启动深交所主板IPO计划，拟募资245亿元用于建设超7GW的风光项目。公司主营风电与光伏电站开发，截至报告期末控股并网装机容量达4158.99万千瓦。财务数据显示，2023至2025年营业收入稳定在205亿元以上，但2026年一季度营收与净利润出现下滑。本次发行申购日定为2026年6月22日，投资者申购时无需预先缴付资金。","scd":null,"kp":["拟建项目装机容量[风力发电、太阳能发电项目]: 7GW以上","募资金额[华润新能源IPO]: 245亿元","控股发电项目并网装机容量[报告期末]: 4158.99万千瓦","并网装机容量[风力发电项目]: 2763.07万千瓦","市场份额[风力发电]: 4.32%"]},{"i":2264,"as":"陕建新能源发布新疆玛纳斯100万千瓦“草光互补”光伏项目一期组件采购资格预审公告。该项目建设规模为1000MW，直流侧规划装机容量1069.36128MWp。一期采购划分为两个标段，各采购30万块单晶硅双面双玻N型组件，要求组件功率在720Wp及以上。招标范围包含光伏组件及其配套接插件与附属设备。","scd":null,"kp":["建设规模[新疆玛纳斯草光互补光伏项目]: 1000MW","直流侧规划装机容量[光伏项目]: 1069.36128MWp","组件功率[单晶硅双面双玻N型组件]: 720Wp及以上","采购数量[一标段]: 300000块","采购数量[二标段]: 300000块"]},{"i":2265,"as":"美国联邦法官撤销了国税局取消“5%安全港”条款的通知，恢复了1.5MW以上光伏和风电项目的税收抵免资格路径。法院认定原通知武断且反复无常，存在未充分说明理由、技术歧视及未考虑投资者信赖利益等问题。恢复5%安全港规则意味着项目方仅需投入项目价值5%即可证明开工建设，从而在抵免到期前获取30%的48E投资税收抵免和45Y生产税收抵免，为美国可再生能源开发带来重大利好。","scd":null,"kp":["税收抵免比例[5%安全港条款规则]: 投入项目价值5%","项目规模门槛[1.5MW以上美国光伏和风电项目]: 1.5MW以上","投资税收抵免率[48E投资税收抵免]: 30%","[条款到期日]: 2026年7月4日"]},{"i":2266,"as":"陕西省发改委发布通知推动绿电直连项目开发，规定年自发自用电量占总可用发电量比例不低于60%。项目新能源弃电不计入利用率统计，年上网电量原则上不超过总可用发电量的20%。通知支持新增负荷、存量压减出力负荷及外向型企业配套建设新能源电源，鼓励开展单用户或多用户绿电直连。此外，允许因消纳受限无法并网的存量新能源项目转为直连配套，分布式光伏可通过集中汇流开展多用户直连。","scd":null,"kp":["发电量占比[绿电直连自发自用电量占总可用发电量]: 不低于60%","用电量占比[绿电直连自发自用电量占总用电量]: 不低于30%（2030年前不低于35%）","上网电量限制[并网型项目年上网电量占可用发电量]: 原则上不超过20%"]},{"i":2267,"as":"内蒙古阿拉善盟公布2026年度光伏治沙实验项目竞争性配置优选结果，中广核、电建、华能、华电等企业成功中选。项目优选严格依据国家及自治区新能源发电项目竞争性配置管理办法及光伏治沙要求，经第三方机构评审得出。公示期为2026年6月14日至16日，接受社会各界书面异议反馈。","scd":null,"kp":["[阿拉善盟2026年光伏治沙项目]: 中广核、电建、华能、华电中选"]},{"i":2268,"as":"广东省四部门联合印发《公共机构合同能源管理办法(试行)》，规定年能耗超500吨标煤或年电耗超200万千瓦时等七种情形的公共机构优先采用合同能源管理实施节能改造。明确涵盖分布式光伏、空气能、储能、充电基础设施及数字化智控管理等新技术、新产品的改造或新建配套项目，旨在通过市场化机制引导社会资金投入，推动公共机构绿色低碳转型。","scd":null,"kp":["年能源消费量[公共机构优先采用合同能源管理条件]: 达500吨标准煤以上","年电力消耗[公共机构优先采用合同能源管理条件]: 200万千瓦时以上","年均运行能效比[中央空调常规电制冷机房]: 低于4.0"]},{"i":2269,"as":"黑龙江省公布2027年上半年增量新能源项目机制电价竞价公告。2027年度竞价分上下半年两批次进行，其中上半年批次仅组织风电项目竞价。同一项目仅可选择一个批次参与，项目方需结合建设情况合理评估全容量并网时间以选择场次，避免因延迟投产被扣除履约保函、取消竞价结果及未来三年的竞价资格。","scd":null,"kp":["[2027年上半年机制电价竞价]: 仅组织风电项目竞价"]},{"i":2270,"as":"","scd":null,"kp":[]},{"i":2271,"as":"","scd":null,"kp":[]},{"i":2272,"as":"","scd":null,"kp":[]},{"i":2273,"as":"英伟达计划时隔五年重返美国债市，拟发行七档债券筹集200亿美元，最晚于2056年到期。募资将用于一般公司用途及偿还、再融资现有票据，由摩根大通等机构承销。由于AI模型训练推升了对英伟达芯片的火爆需求，公司需投入巨资研发先进处理器。截至2026年4月季度末，英伟达持有132.4亿美元的现金及现金等价物。","scd":null,"kp":["发债筹资规模[英伟达拟发债]: 200亿美元","历史融资规模[2021年6月债券市场]: 50亿美元","现金及现金等价物[截至2026年4月季度末]: 132.4亿美元","[债券到期时间]: 最晚将于2056年到期"]},{"i":2274,"as":"奥地利电池分析专家Aviloo正将其独立的电动汽车电池诊断服务升级为真正的购买保证。公司推出基于电池快检和认证的一年期电池保修服务，作为其数字仪表盘Aviloo Connect的核心。若出现电池缺陷，用户将获得3000欧元的赔偿。该保修服务计划于7月率先在德国、英国、瑞士、芬兰和荷兰推出。","scd":null,"kp":["缺陷赔偿金额[Aviloo电池保证]: 3,000欧元","保修期[Aviloo电池质保]: 1年"]},{"i":2275,"as":"电池行业资深人士、Stryten Energy前董事长Tim Vargo于6月6日因平滑肌肉瘤去世，享年75岁。他的职业生涯始于美国一家汽车零部件商店的店员，其在电池行业深耕多年并担任Stryten Energy董事长，为行业发展做出了贡献。","scd":null,"kp":[]},{"i":2276,"as":"2026年欧洲电池展于6月11日在斯图加特闭幕，展会展示了欧洲电池和电动汽车产业的尖端制造与生产技术。会议重点讨论了欧洲电池行业如何利用自身优势与中国市场进行竞争。展会期间，EIRICH等企业现场演示了阳极制备等最新的电池生产技术工艺。","scd":null,"kp":[]},{"i":2277,"as":"随着美国、以色列和伊朗达成框架协议，霍尔木兹海峡预计将在数周内重新开放。巴基斯坦总理于6月14日确认华盛顿和德黑纳同意停止敌对行动。该协议为全球最关键的航运咽喉之一的物流规划提供了时间表。据统计，全球约20%的原油供应需经过该海峡，此前的封锁迫使多条航运时间表重新规划。","scd":null,"kp":[]},{"i":2278,"as":"雀巢发布了其首份《乳制品计划》，详细阐述了其全球业务中的乳制品采购战略。面对排放目标、气候变化、劳动力短缺和成本通胀带来的多重供应链压力，该计划重点探讨了如何提升乳制品供应链的韧性、加强对奶农的支持以及实现气候目标。雀巢成立于1866年，拥有超过2000个品牌，产品中广泛使用乳制品原料。","scd":null,"kp":[]},{"i":2279,"as":"","scd":null,"kp":[]},{"i":2280,"as":"起亚PV5是一款基于现代E-GMP.S平台的纯电动中型货车，也是起亚PBV系列的首款车型。该车型提供乘用、货运、底盘驾驶室等多种车身配置。在2026年第一季度，PV5占据了欧洲电动轻型商用车市场9%的销量。实际路况测试显示，起亚这款纯电动货车的续航里程最高可达260英里，具备快充功能及宽敞的高科技内饰。","scd":null,"kp":["续航里程[起亚PV5电动货车]: 260英里","[底盘平台]: 基于现代E-GMP.S灵活平台"]},{"i":2281,"as":"根据美国国家公路交通安全管理局（NHTSA）的最新数据，特斯拉在奥斯汀推出自动驾驶出租车项目以来仅报告了18起自动驾驶系统事故，无单方面责任事故。然而，实际车队运行数据显示，事故数量少的主要原因是特斯拉的机器人出租车车队运行频率极低，且活跃车队规模在项目上线一年后正在缩减，与竞争对手Waymo约697起事故相比，存在严重的暴露风险差距。","scd":null,"kp":["[运营状态]: 机器人出租车车队规模萎缩且几乎未实际运行"]},{"i":2282,"as":"前特斯拉高管Drew Baglino创立了初创公司Sadi Thermal Machines，致力于研发特斯拉曾探讨但最终放弃的家用热泵产品。这款住宅热泵具备暖通空调和水加热双重功能。2022年初，Baglino与马斯克曾表示家用能源产品与公司使命高度契合，但特斯拉随后将战略重心转向了人形机器人和机器人出租车领域。","scd":null,"kp":["[产品路线]: 前高管创立Sadi Thermal Machines研发家用热泵"]},{"i":2283,"as":"百度Apollo Go获得了瑞士联邦道路局（FEDRO）颁发的4级自动驾驶许可，将携手瑞士邮政PostBus推出名为AmiGo的机器人出租车服务。该许可覆盖瑞士东部三个州80平方公里的服务区域，标志着中国科技巨头在向欧洲公共交通部署无人驾驶车辆方面领先于Waymo和特斯拉。百度表示，该项目有望成为欧洲同类自动化公共交通运营中规模最大的项目。","scd":null,"kp":["自动驾驶等级[百度Apollo Go瑞士]: 4级 (L4)","服务区域面积[AmiGo机器人出租车]: 80平方公里"]},{"i":2284,"as":"在2010年代末，美国电动自行车行业致力于制造重量在20至22公斤左右、配备适度电机和电池的轻型通勤自行车，旨在让骑行、爬坡和替代汽车出行变得更加轻松。当时的通勤电动自行车保持了传统自行车的外观，采用了较窄的城市轮胎和隐蔽的电机电池封装设计，专注于满足城市通勤者的基础需求。","scd":null,"kp":[]},{"i":2285,"as":"Rivian宣布与ChargeScape合作，将其电动汽车接入北美公用事业公司管理的家庭充电项目。通过ChargeScape平台，Rivian车主可参与电力公司的电网管理计划，在低需求时段充电并在高峰期减少充电。此举旨在帮助电网平衡电力需求，同时利用Rivian电动汽车的大容量电池包为电网提供灵活容量，为车主节省充电成本。ChargeScape由汽车制造商支持并获得了宝马、福特和本田的赞助。","scd":null,"kp":["[Rivian家庭电动汽车充电]: 与ChargeScape合作接入电网管理的家庭充电项目，通过避峰就谷帮助平衡电力需求"]},{"i":2286,"as":"荷兰制造商Solarge在韦尔特运营着一家自动化工厂，专注于生产超轻量、完全可回收的太阳能组件。该工厂自2023年5月投产，目前的年产能为150兆瓦，每年约可生产30万块太阳能电池板。Solarge通过聚焦创新、可持续性和循环经济，使欧洲光伏行业与亚洲竞争对手形成差异化，并已制定计划以进一步扩大其生产规模。","scd":null,"kp":["[光伏组件生产]: 采用全自动化产线生产超轻量化、可完全回收的太阳能组件"]},{"i":2287,"as":"中国工信部公开征求关于光伏产品分类分级的六项电子行业标准草案意见，提出首个结构化的光伏产品分级制度。该系统基于可靠性、性能和环境属性，将光伏组件划分为三个质量等级。此举旨在通过质量分级而非单一标准来影响光伏组件的采购、融资和保险决策，从而推动光伏行业的整合与高质量发展。","scd":null,"kp":["[光伏产品分级制度]: 基于可靠性、性能和环保属性将组件划分为三个质量等级"]},{"i":2288,"as":"吉尔吉斯斯坦已投运其迄今为止最大的太阳能发电站。由越南Rox Energy Global等公司投资建设的ROX Issyk-Kul太阳能发电厂规划总容量为1.9吉瓦，目前其首期175兆瓦太阳能项目及一座110千伏高压变电站已正式投入运营。该项目位于吉尔吉斯斯坦东部的伊塞克湖地区，标志着该国在清洁能源领域取得重大进展。","scd":null,"kp":["太阳能项目规划总容量[吉尔吉斯斯坦]: 1.9 GW","太阳能项目一期投运容量[吉尔吉斯斯坦]: 175 MW"]},{"i":2289,"as":"中国钙钛矿太阳能组件生产商UtmoLight在SNEC 2026展会上推出了创世S2和S1新型钙钛矿组件系列，旨在解决商业化应用中的可靠性挑战。其中，500瓦的S2组件专为恶劣天气条件设计，并通过了高机械负载认证；超轻量S1组件则专为分布式光伏、光伏建筑一体化（BIPV）和低载荷屋顶应用量身定制。新产品的发布标志着钙钛矿光伏技术从单纯追求效率向注重耐用性和特定应用场景拓展。","scd":null,"kp":["S2钙钛矿组件功率[抗恶劣天气/高机械载荷]: 500 W","S1钙钛矿组件应用场景[超轻量化设计]: 分布式光伏、BIPV及低荷载屋顶"]},{"i":2290,"as":"Vikram Solar正在推进其规划的12GW太阳能电池制造工厂的第一阶段，预计到2026年12月底投产9GW的电池产能。同时，公司正在将组件制造产能从9.5GW扩大至15.5GW，新增产能计划在2027财年第一季度投入运营。此次产能扩张恰逢印度ALMM清单第二阶段生效，新规定要求政府支持计划、净计量和开放接入项目使用特定的光伏组件。","scd":null,"kp":["光伏电池制造产能投运[Vikram Solar一期]: 9 GW","光伏组件产能扩建目标[Vikram Solar]: 15.5 GW"]},{"i":2291,"as":"欧盟委员会限制对使用“高风险”供应商设备的太阳能项目提供资金，标志着太阳能网络安全讨论的转折点。专家指出，禁止中国逆变器有助于欧洲实现战略独立，但无法从根本上解决行业的网络安全问题。实现更高的安全性需要制定明确的技术标准、增强资产可见性，并切实落实NIS2指令的具体实施。","scd":null,"kp":["[光伏逆变器网络安全]: 欧盟限制高风险供应商资金以寻求战略独立，但产业安全仍需明确技术标准和资产可见度"]},{"i":2292,"as":"中国研究团队开发了一种针对公用事业规模光伏电站的场景感知面板表面温度（PST）反演模型。该模型利用MODIS热红外卫星数据，校正了混合像元效应、阵列几何形状和光伏特有的方向发射率。这项技术解决了长期存在的空间观测干扰问题，实现了从太空对光伏组件进行精确的面板规模温度估算。","scd":null,"kp":["[面板表面温度(PST)反演模型]: 结合MODIS热红外卫星数据，校正混合像元、阵列几何及特定发射率以实现精确测温"]},{"i":2293,"as":"威尔士橄榄球联盟在卡迪夫千禧球场的可伸缩屋顶上安装了1.5兆瓦的光伏阵列，由超过3250块太阳能板组成。该球场所有者宣称，这是迄今为止英国体育场馆中最大的光伏装置。该系统的发电能力足以为50多个比赛日提供电力，是推动体育场馆可持续发展的关键商业与工业应用案例。","scd":null,"kp":["光伏阵列装机容量[威尔士体育场]: 1.5 MW"]},{"i":2294,"as":"美国暖通空调与水加热产品供应商Rheem推出了型号为RP17AY的新型住宅热泵。该系统采用R-454B制冷剂，是一款由逆变器驱动的变速空气源热泵，具备出色的季节性效率。该产品专为通用替换应用设计，具备极高的安装兼容性，可与几乎任何室内组件及R-454B暖通空调系统轻松配对使用。","scd":null,"kp":["[空气源热泵特性]: 采用R-454B制冷剂及变频驱动技术，具备高季节性效率，专为通用替换场景设计"]},{"i":2295,"as":"英国咨询机构Ember报告显示，可再生能源使西班牙免受能源危机冲击。在天然气价格飙升期间，西班牙仅9%的时间由天然气决定电价。光伏和风能的快速扩张不仅作为脱碳工具，更显著增强了电力系统对化石燃料波动的抵御能力，为普通家庭每月平均节省了10欧元的用电开支。","scd":null,"kp":["天然气设定电价时间占比[西班牙可再生能源保障]: 9%","家庭平均节省费用[西班牙应对天然气危机]: 10欧元/月"]},{"i":2296,"as":"AI机器士兵正在改变现代战争的形态，以AI制导无人机群、自主地面车辆和机器人坦克的形式参与战斗，并辅助软件做出超越人类速度的战场决策。在乌克兰冲突中，无人系统的数量已超过活跃战区的人类战斗人员。双方每年生产数百万架无人机，深刻改变了侦察、后勤、炮兵校准和打击任务的执行方式。","scd":null,"kp":["战场形态特征[现代战争机器博弈]: 日益成为机器之间的较量"]},{"i":2297,"as":"中国自主研发的超导量子计算机“本源悟空”已成功完成超过100万次计算任务。这一里程碑成果同步展示了后量子密码（PQC）保护框架，这是未来量子计算机安全运行的必备技术。随着量子计算从实验室走向实际应用，PQC框架的验证证明了其在应对未来量子算力破解现代加密系统方面的关键防护作用。","scd":null,"kp":["计算任务完成量[本源悟空超导量子计算机]: 超过100万次","[超导量子计算机]: 演示了后量子密码(PQC)保护框架"]},{"i":2298,"as":"","scd":null,"kp":[]},{"i":2299,"as":"","scd":null,"kp":[]},{"i":2300,"as":"江门中微子实验（JUNO）发布首批物理结果，标志着中微子物理进入精确测量新时代。研究团队利用59天的高质量数据，对两个基础中微子振荡参数进行了高精度测量。分析结果显示，与过去几十年的实验综合结果相比，JUNO将这些参数测量的不确定性降低了1.6倍，进一步逼近中微子质量之谜的真相。","scd":null,"kp":["数据采集时长[江门中微子实验(JUNO)首批结果]: 59天","数据采集时间[江门中微子实验(JUNO)首批结果]: 2025年8月26日至11月2日"]},{"i":2301,"as":"","scd":null,"kp":[]},{"i":2302,"as":"研究人员开发出一种利用食物垃圾制成的可重复使用微小珠子，用于直接从空气中捕获二氧化碳的技术。为实现IPCC报告中提出的从大气中移除数百亿吨二氧化碳的气候目标，直接空气捕获（DAC）技术受到广泛关注。这种创新材料将食物垃圾转化为强大的“碳陷阱”，为DAC系统的效率提升和商业化提供了新路径。","scd":null,"kp":["温升控制目标[长期气候变化]: 低于1.5℃","碳移除需求规模[IPCC最新评估报告气候情景]: 数百亿吨二氧化碳"]},{"i":2303,"as":"光伏市场的实证数据常因检测样品局限和地域环境差异而相互矛盾。为打破技术路线争议，国家电投大庆基地作为中立评价基准极具参考价值。作为非设备制造商的发电投资方，其不受特定技术利益驱动。大庆基地通过庞大且客观的实测数据，消除了实验室特制组件或单一气候环境带来的偏差，为终端投资方提供可靠的评估标尺。","scd":null,"kp":["数据失真原因[光伏实证数据局限性]: 送检产品多为特定批次最优工艺且深度依赖所在地气候环境与安装方式"]},{"i":2304,"as":"山西省出台储能新规征求意见稿，针对全省约173.49GWh但在库实际落地率不足15%的“圈而不建”储能项目进行清场。规定明确项目入库后需在6个月内开工、12个月内并网，否则将被强制调出库，且已取得的电网接入批复和变电站间隔自动失效。该新规彻底终结了单纯倒卖路条的玩法，计划于2026年9月1日执行。","scd":null,"kp":["在库储能规模[山西截至2026年5月第五次调整]: 约173.49GWh","实际落地率[山西在库储能项目]: 不足15%","实质性开工期限[山西储能新规入库项目]: 6个月","建成并网期限[山西储能新规入库项目]: 12个月","[开工标志]: 升压站、主控楼等重要设施基础浇筑第一罐混凝土"]},{"i":2305,"as":"","scd":null,"kp":[]},{"i":2306,"as":"五角大楼透露在伊朗战争行动中使用了xAI公司的Grok人工智能系统。与此同时，美国司法部正在积极应对有关数据中心的诉讼案件。","scd":null,"kp":["实战应用[xAI的Grok人工智能]: 在伊朗战争中被五角大楼使用"]},{"i":2307,"as":"指数初创公司Ornn针对Anthropic和OpenAI推出了专门的人工智能代币基准测试。","scd":null,"kp":["[大模型基准]: 推出针对Anthropic和OpenAI的代币(Token)基准测试"]},{"i":2308,"as":"美国太空探索技术公司SpaceX敲定了以600亿美元收购AI编程工具公司Cursor的交易。","scd":null,"kp":["收购金额[SpaceX收购Cursor]: 600亿美元"]},{"i":2309,"as":"人工智能公司DeepSeek完成了一笔超过70亿美元的创纪录融资，且该轮融资采用了不同寻常的交易结构。","scd":null,"kp":["融资金额[DeepSeek]: 70亿美元以上"]},{"i":2310,"as":"Anthropic 正在与特朗普政府探讨达成一项潜在的协议。目前仅披露了双方正在进行接触与讨论的事实，尚未公布具体的协议条款、合作细节或政策目标等实质性信息。","scd":null,"kp":[]},{"i":2311,"as":"英伟达（Nvidia）计划在资本市场发行规模高达 250 亿美元的债券。此举旨在通过债券市场进行大规模融资，以支持公司的资金需求，但债券的具体发行期限、利率及资金的具体用途等详细参数尚未在当前信息中披露。","scd":null,"kp":["债券发行规模[Nvidia]: 250亿美元"]},{"i":2312,"as":"人工智能初创公司 Anthropic 面临一项法律诉讼。起诉方指控 Anthropic 在其提供的高级订阅计划中，对用户施加了具有“误导性”的使用限制。该诉讼直指其商业订阅条款的透明度与实际服务承诺之间的差异。","scd":null,"kp":[]},{"i":2313,"as":"为应对突发电力需求峰值（如大型赛事引发的同时用电潮），人工智能正被用于提升电网与数据中心的弹性。AI系统通过实时发送指令，动态调节数据中心内高耗电芯片的运行速率，降低瞬时功耗。该机制有效平衡了电网供需，防止了大规模停电和硬件损坏。","scd":null,"kp":[]},{"i":2314,"as":"","scd":null,"kp":[]},{"i":2315,"as":"柏林工业大学研发了一款名为 TripleLens 的应用程序，旨在帮助初创团队系统评估和优化可持续商业模式。该工具弥补了早期创业阶段缺乏结构化评估手段的不足，使团队能够全面分析商业构想在经济、社会和生态维度的深远影响及发展潜力。","scd":null,"kp":[]},{"i":2316,"as":"ZE Energy 与 Octopus Energy 签订共同投资协议，在意大利开发 Sessa Aurunca 独立电池储能项目。该项目容量为 98.5 MW / 895 MWh，预计 2028 年投运，将成为意大利最大储能项目之一。项目获意大利 Terna 运营商 MACSE 拍卖容量及 15 年收益合同，将作为区域能源枢纽支持可再生能源并网。","scd":null,"kp":["储能容量[意大利Sessa Aurunca独立电池项目]: 98.5 MW 895 MWh","预计投运时间[意大利Sessa Aurunca独立电池项目]: 2028年","收益合同期限[意大利Sessa Aurunca独立电池项目]: 15年"]},{"i":2317,"as":"Kabra Extrusiontechnik 旗下未来技术部门 Geon，在印度古吉拉特邦 Khavda 综合并投运了一座 2.88 GWh 的电池储能系统（BESS），耗时五个月。项目涵盖系统集成、测试及功率调节系统和能源管理系统的接入，目前全面运作，是印度规模最大的公用事业级储能部署之一。","scd":null,"kp":["储能系统规模[印度Khavda中心BESS]: 2.88 GWh","建设周期[印度Khavda中心BESS]: 5个月内"]},{"i":2318,"as":"欧洲能源公司在立陶宛成功调试了其首个波罗的海国家电池储能项目。该项目容量为 25 MW / 65 MWh，与同址的 78.5 MW Anykščiai 太阳能园区实现整合，成为立陶宛第二个光储混合可再生能源设施。该系统将于六月底前全面商业运营，旨在提升电网灵活性与平衡服务能力。","scd":null,"kp":["储能系统规模[立陶宛Anykščiai光储混合项目]: 25 MW/65 MWh","光伏发电功率[立陶宛Anykščiai光储混合项目]: 78.5 MW"]},{"i":2319,"as":"挪威能源公司 Statkraft 启动了扩建挪威最大水电站的项目，预计年产量将增加 54 GWh。该项目将建设全新的 Blåfjell 泵，将更多水资源直接注入被视作挪威“最大水电电池”的 Blåsjø 水库。目前，Statkraft 已为该水泵建设授予总价值 2.5 亿挪威克朗（约 2600 万美元）的合同并立即开工。","scd":null,"kp":["年发电量增量[挪威Ulla-Førre水电站扩建]: 54 GWh","工程合同总额[挪威Blåfjell水泵建设]: 2.5亿挪威克朗（约2600万美元）"]},{"i":2320,"as":"彭博新能源财经（BNEF）发布的报告指出，全球电动汽车销量持续创新高，2026 年电动汽车将占全球汽车销量的 27%，到 2035 年将超过 52%。增长动力来自锂电池价格下跌、平价车型推出及新兴市场普及。尽管部分主要市场增速放缓，但中国继续在全球电动汽车市场中占据最大份额。","scd":null,"kp":["电动汽车销量占比[2026年全球市场]: 27%","电动汽车销量占比[2035年全球乘用车市场]: 52%"]},{"i":2321,"as":"“科创中国新质生产力调研行”活动走进海博思创。作为储能企业，海博思创采用“制造+服务”一体化模式，利用海量运行数据训练 AI 算法以优化系统精度。行业焦点已从单一设备竞争转向综合能力，储能正依托数字化管理与虚拟电厂技术，从单一卖设备向“卖服务”与“卖运营”的盈利模式升级。","scd":null,"kp":["[储能数智化运营]: 依托海量电站运行数据训练AI算法优化系统运行精度，并通过智能化服务协助业主参与电力市场化交易获取分成收益"]},{"i":2322,"as":"中国电力科学研究院牵头攻关的“电力负荷多层级协同智算关键技术”达国际领先水平。该技术基于用电信息采集系统构建“云-边-端”协同智算系统，突破了边缘侧感知与超大规模负荷智算等难题，将负荷感知准确率提升至 95%以上。成果已在国内外多地应用，推动感知装备向“智算型”升级。","scd":null,"kp":["[电网形态]: 由传统源荷单向供电模式向源荷储多级双向互动模式转变","[感知硬件矩阵]: 覆盖台区干线、分支节点及末端回路的全息感知矩阵","[核心技术]: 边缘侧轻量化负荷协同感知与超大规模电力负荷协同智算"]},{"i":2323,"as":"内蒙古和林格尔新区以算力驱动发展，已成为高新科技集聚地。新区集聚了 57 个数据中心项目，投用标准机架 53.2 万架，总算力规模超 12.67 万P，智能算力占比超 96.4%。中国移动在此建成全球运营商最大单体液冷智算中心，AI芯片国产化率超 89%，实现超长无中断模型训练。","scd":null,"kp":["[和林格尔新区算力产业]: 聚集数据中心项目57个，投用标准服务器机架53.2万架","[单体总算力规模]: 每秒百亿亿次(推测自上下文不完整截断，亦可表述为全球运营商最大单体液冷智算中心)"]},{"i":2324,"as":"我国正加速构建天地一体化的新一代通信网，预计未来五年带动上下游产出约 7 万亿元。产业涵盖 5G-A 商用、6G 技术试验、万兆光网与卫星互联网。新一代通信网实现通信与AI、感知、计算深度融合，完成从“万物互联”向“万物智联”的跃升，为网络设备及芯片创造巨大发展机遇。","scd":null,"kp":["[新一代通信网产业带动]: 预计未来五年带动上下游总产出约7万亿元","[卫星通信网络]: 开展手机直连卫星、天地网络融合等技术试验验证"]},{"i":2325,"as":"中国电力科学研究院研发的“安全智探”便携式电气安全智能诊断装置全面推广。该软硬一体化设备融合AI、多模态感知与云边协同技术，同步采集五维数据，能精准排查 290 类电气安全隐患。仅需佩戴AR眼镜采集，15秒内即可生成诊断报告，效率较传统人工提升超 75%，填补了国内该领域的应用空白。","scd":null,"kp":["[隐患识别准确率]: 大幅提升","[边缘侧诊断耗时]: 15秒内","[人工排查效率提升]: 75%以上","[隐患排查覆盖面]: 精准排查290类电气安全隐患，自动识别15类电力设备"]},{"i":2326,"as":"第十届中国-南亚博览会集中展示了以AI智能机器人为代表的科技服务升级成果。展区聚焦全场景智能服务，重点展出生成式人工智能、无人机、数字人等核心技术。这些前沿科技的应用有效推动了传统制造业的数字化与智能化转型，为服务贸易创新及制造业提质增效注入了强劲动能。","scd":null,"kp":[]},{"i":2327,"as":"6月15日11时44分，我国在东风商业航天创新试验区使用力箭一号遥十四运载火箭，成功实施“一箭八星”发射任务。吉星高分07C04星等 8 颗卫星被顺利送入预定轨道，发射任务取得圆满成功，展现了我国在商业航天发射与多星组网部署方面的成熟技术能力。","scd":null,"kp":["[运载火箭发射]: 一箭8星（力箭一号遥十四运载火箭成功发射吉星高分07C04星等8颗卫星）"]},{"i":2328,"as":"能源智库 Ember 的报告指出，可再生能源的广泛应用使得西班牙的电力价格维持在较低水平。这一结论凸显了风能、太阳能等可再生能源在降低国家电力市场整体运行成本、平抑电价波动方面发挥的实质性抑制作用。","scd":null,"kp":[]},{"i":2329,"as":"零售商 JYSK 通过与 Eurowind 和 Norlys 签署企业购电协议（PPA），实现其在丹麦业务的绿色环保运营。此举旨在利用风电等可再生能源为其日常运营提供电力支持，是企业在促进绿色能源转型与实现可持续发展目标方面的实质性商业举措。","scd":null,"kp":[]},{"i":2330,"as":"HASI为绿色票据定价10亿美元。相关新闻还提及荷兰政府上调两座1GW海上风电场招标价格上限、新南威尔士州政府资助建设高达1GW电池项目、TRIG出售Beatrice海上风电场17.5%股份、法国开启10GW海上风电招标，以及Cypress Creek为阿肯色州太阳能加储能项目获得35亿美元资金。","scd":null,"kp":[]},{"i":2331,"as":"陕西省发展改革委发布2026年风电光伏发电项目开发建设通知。重点支持风光储一体化、风光制氢、零碳园区等集成融合项目。项目须在2027年底前完成核准或备案，并在2028年至2029年6月底前全容量并网。竞配办法须将前期工作开展情况和电网接入消纳能力作为重要条件，两者在综合评分中占比不得低于60%，禁止设置违背市场公平的条款。","scd":null,"kp":["核准完成时限[陕西省2026年风光项目]: 2027年12月底前","全容量并网时限[陕西省2026年风光项目核准类]: 2029年6月底前","备案完成时限[陕西省2026年风光项目]: 2027年6月底前","全容量并网时限[陕西省2026年风光项目备案类]: 2028年12月底前","评分权重[前期工作和电网接入消纳能力竞争条件]: 不得低于60%"]},{"i":2332,"as":"贵州省首个钙钛矿实验中试生产线建设项目登记备案，总投资2500万元。该项目位于黔东南高新区，由当地国有独资企业高新发展集团投建。项目将改造500平方米厂房，建设规格为300mmX400mm的钙钛矿中试线，覆盖材料配比至稳定性验证全流程工艺，计划于2027年9月底投产，旨在推动区域科技创新与产业升级。","scd":null,"kp":["项目总投资[贵州钙钛矿实验中试线]: 2500万元","厂房面积[贵州钙钛矿实验中试线]: 约500平方米","电池尺寸[钙钛矿实验中试生产线]: 300mmX400mm","投产时间[贵州钙钛矿实验中试线]: 2027年9月30日","工艺覆盖范围[钙钛矿实验中试生产线]: 材料配比、涂布成膜、器件制备、性能测试、长期稳定性验证全流程"]},{"i":2333,"as":"伊拉克首座太阳能电池板制造工厂建成投产。该工厂由阿巴斯圣祠牵头打造，引入全球先进自动化设备与智能机器人，一期产能达100兆瓦，产品兼顾民用电与工业用电。工厂投产后将降低伊拉克对化石燃料的依赖，推动国家能源结构转型。后续还规划通过技术革新进一步扩大本土光伏产业规模。","scd":null,"kp":["运营模式[伊拉克首座太阳能电池板工厂]: 首个采用智能化模式运营，全程依托工业自动化设备和智能机器人运作","市场应用[伊拉克太阳能电池板]: 兼顾民用供电和工业生产用电","核心优势[伊拉克太阳能电池板工厂]: 引入全球先进生产设备，所有精密器械均采购自国际优质企业"]},{"i":2334,"as":"湖南省发改委启动“十五五”风、光项目申报入库，拟定项目库规模不超过3000万千瓦。重点支持消纳条件好、集成融合及共用基础设施的项目。申报要求项目具备良好的电网接入条件，风电项目须开展6个月以上测风。投资主体由市州按煤新联营等原则统筹上报。“千乡万村驭风行动”及部分屋顶光伏等项目不纳入本次范围。","scd":null,"kp":["项目库规模[湖南省十五五风光项目入库申报]: 不超过3000万千瓦(30GW)","测风周期[湖南省十五五风电项目]: 6个月以上","测风设备[湖南省十五五风电项目]: 拉线桁架式测风塔","排除范围[湖南省十五五风光项目入库申报]: 千乡万村驭风行动、老旧风电场改造、分散式风电项目及公共电网连接点为220千伏的屋顶光伏发电项目"]},{"i":2335,"as":"河北省发改委启动2026年风电、光伏项目申报，计划指导规模为2376万千瓦。各市需细化项目布局并落实用地条件，申报时暂不明确投资主体。项目须于2029年底前全容量建成并网，电网接入条件较好的项目优先申报。政策鼓励在零碳园区等周边布局分散式风电以降低化石能源消耗，推进绿色低碳发展。对于因投资主体原因无法实施的项目，保留选址重新申报。","scd":null,"kp":["指导规模[河北省2026年风光项目申报]: 共2376万千瓦(23.76GW)","审批要求[河北省2026年风光项目申报]: 需协调自然资源、林草、农业部门落实项目用地条件并出具支持性意见","排查因素[河北省2026年风光项目申报]: 机场限高、蓄滞洪区、压覆矿、文物、军事等限制性因素"]},{"i":2336,"as":"福建省发改委决定废止9个光伏发电项目，总规模达95.875万千瓦。这些项目受政策调整等因素影响已不具备开发条件，包括福清通渔光一体二期项目等。相关职能部门不再受理这些项目的用地、用海申请，原安排的接网和消纳资源由国网福建省电力有限公司收回。同时，省发改委要求各市加快推动已纳入方案的项目建设。","scd":null,"kp":["废止规模[福建省光伏项目]: 总计95.875万千瓦","废止数量[福建省光伏项目]: 9个项目","善后处理[福建省光伏项目]: 原安排给项目的接网和消纳资源由国网福建省电力有限公司收回"]},{"i":2337,"as":"","scd":null,"kp":[]},{"i":2338,"as":"零跑汽车创始人朱江明表示，零跑在2020年便与大华联合发布了首款国产车规级AI智驾芯片“凌芯01”。该芯片采用28nm工艺，集成8核神经网络处理器。面对当前市面上充足的AI智驾芯片供应，朱江明指出，在企业规模未达足够量级前，零跑暂不进一步自研芯片，而是聚焦其他能产生价值的核心零部件。","scd":null,"kp":["算力[凌芯01芯片]: 4.2TOPS","制程工艺[凌芯01芯片]: 28nm","CPU处理器[凌芯01芯片]: 平头哥玄铁C860","主频[凌芯01芯片]: 最高1GHz","AI处理器[凌芯01芯片]: 集成8核神经网络处理器"]},{"i":2339,"as":"全国首个商业空间碎片监测专用星座“LX630”首发星出征。该卫星搭载高星等目标探测相机与星载AI计算机，支持常态巡查与抵近探测，能够精准识别微小空间碎片并建立动态编目库，无需地面频繁干预。首发星计划于今年7月发射，整个星座系统由14颗卫星组成，预计于2027年建成运营，实现近地轨道全时全域目标探测。","scd":null,"kp":["首发星发射时间[LX630商业空间碎片监测星座]: 今年7月","全面建成时间[LX630商业空间碎片监测星座]: 2027年","卫星数量[LX630商业空间碎片监测星座]: 14颗","探测能力[LX630首发星]: 覆盖低轨、高轨全天域近地空间目标","核心载荷[LX630首发星]: 高星等目标探测相机、星载AI计算机"]},{"i":2340,"as":"","scd":null,"kp":[]},{"i":2341,"as":"开发者通过逆向工程绕过了苹果M4芯片的软件限制，成功解锁用于AI模型训练的能力。该方案完全在RAM中运行，未使用Core ML或调用GPU，而是利用自研模型中间语言与M4通信。解锁后，M4芯片的AI处理性能达到15.8TFLOPS。目前该方案的兼容性范围尚待验证。","scd":null,"kp":["AI算力[苹果M4芯片解锁后]: 15.8TFLOPS","运行环境[M4芯片AI解锁过程]: 完全在RAM中运行，未写入NAND闪存","逆向工程手段[M4芯片]: 开发自定义MIL（模型中间语言）与M4直接通信，绕过软件限制"]},{"i":2342,"as":"以色列Mobileye公司宣布进军美国自动驾驶出租车市场，计划于2027年启动服务。该公司将整合旗下的Mobileye Drive自动驾驶系统与Moovit出行应用为消费者提供服务。此举旨在通过互补市场路径积累运营经验。Mobileye在2026年底前公布商业化运营细节，并于明年在美国某城市率先启动商业无人驾驶出租车服务。","scd":null,"kp":["服务上线时间[Mobileye美国自动驾驶出租车]: 2027年","商业运营细节公布时间[Mobileye美国自动驾驶出租车]: 2026年底前","初始服务落地[Mobileye美国自动驾驶出租车]: 明年在美国某座城市启动商业无人驾驶出租车服务","系统基础[Mobileye自动驾驶出租车]: 搭配Mobileye Drive系统与Moovit的服务、App结合"]},{"i":2343,"as":"南京大学团队联合研发出大面积全钙钛矿叠层光伏组件，经国际权威认证，光电转换效率达26.2%，打破世界纪录。该组件采用无空穴传输层结构和纳米晶功能层替代传统超薄金属复合层，结合二元共溶剂体系的刮涂工艺，实现了大尺寸薄膜的均匀制备。全钙钛矿叠层电池具备光谱吸收宽、厚度薄、重量轻等优势。","scd":null,"kp":["光电转换效率[大面积全钙钛矿叠层光伏组件]: 26.2%","组件面积[无空穴传输层的隧穿复合结结构]: 65平方厘米","吸光厚度[全钙钛矿叠层太阳能电池]: 亚微米级","[传统ALD-SnO2/Au/PEDOT:PSS复合结]: 超薄金属大面积均匀控制难且易损害稳定性"]},{"i":2344,"as":"零跑汽车创始人朱江明表示，中国汽车电动化趋势正在加速，目前新能源渗透率已约达三分之二，纯电车型占比将持续扩大。同时他指出，针对无充电条件及寒冷地区用户，增程和插混车型依然具有现实需求，未来一段时间内将与纯电车型保持共存。乘联分会数据显示，5月国内乘用车市场燃油车销量大幅萎缩，新能源车占据主导地位。","scd":null,"kp":["新能源渗透率[中国乘用车市场某周]: 66.7%","乘用车零售量[2025年5月全国市场]: 151.0万辆","同比变化[5月乘用车零售]: 下降22.1%","燃油车市场份额[5月车市]: 37.1%"]},{"i":2345,"as":"","scd":null,"kp":[]},{"i":2346,"as":"全新奥迪A6L搭载华为乾崑智驾技术，该功能装备定价为26800元，限时最高优惠6000元。系统配备33个传感器及自动清洗加热功能，支持城区与高速NOA智慧领航辅助，可完成辅助变道、掉头及循迹倒车。全新奥迪A6L共推出4款车型，基于PPC燃油车平台打造，轴距加长至3066mm，官方指导价在32.29至43.59万元之间。","scd":null,"kp":["装备价格[全新奥迪A6L华为乾崑智驾功能]: 26800元","限时优惠[华为乾崑智驾功能]: 至高6000元","传感器数量[全新奥迪A6L灵眸全域感知系统]: 33颗","传感器自清洁[全新奥迪A6L]: 9处配备自动清洗，2处激光雷达配备自动加热","循迹倒车能力[全新奥迪A6L未贯穿或窄路]: 120米循迹倒回"]},{"i":2347,"as":"","scd":null,"kp":[]},{"i":2348,"as":"SpaceX登陆纳斯达克后股价连续大涨，上市第三个交易日再涨15%，股价突破220美元。其市值已攀升至2.94万亿美元，超越亚马逊与微软，成为全球第四大上市公司。散户投资者大量资金涌入SPCX股票，但资金虹吸效应导致维珍银河、AST SpaceMobile等其他太空概念股遭到大幅抛售。","scd":null,"kp":["股价涨幅[SpaceX上市三个交易日]: 超过45%","市值[SpaceX当前]: 2.94万亿美元","上市估值[SpaceX]: 1.77万亿美元"]},{"i":2349,"as":"比亚迪宣布扩大其在巴西的电池组装业务，旨在将该国生产车辆的本土化率提升至50%。除汽车动力电池外，比亚迪还计划在巴西组装固定式电池储能系统。自去年起，比亚迪已在巴西卡马萨里工厂采用半散件组装工艺生产海豚Mini纯电动汽车，该车型目前是巴西最畅销的汽车。","scd":null,"kp":["本地化率目标[比亚迪巴西产车辆]: 50%","[比亚迪巴西业务战略]: 扩大电池组装并制造固定式电池储能系统"]},{"i":2350,"as":"通用汽车华莱士电池创新中心正研发钠离子电池技术，用于电池储能系统（BESS），以推动可持续能源转型。通用汽车宣布了该领域的进展，并与Peak Energy建立合作伙伴关系。与锂离子电池不同，钠离子技术主要依赖于储量丰富且具有成本效益的材料。","scd":null,"kp":["[通用汽车华莱士电池创新中心]: 专注于包括钠离子电池在内的前沿储能技术研究"]},{"i":2351,"as":"通用汽车（GM）与Peak Energy合作开发用于储能系统（BESS）的下一代钠离子电池，旨在提升创新能力、成本效益和供应链韧性。在旧金山举行的GM Empower活动上，通用汽车电池与可持续发展副总裁Kurt Kelty宣布了优先发展BESS钠离子电池的战略计划，Peak Energy首席执行官Landon Mossburg也分享了双方的合作细节。","scd":null,"kp":["[通用汽车与Peak Energy合作]: 联合开发与部署面向BESS的下一代钠离子电池"]},{"i":2352,"as":"全球供应链正面临频繁的日常挑战，但技术的进步被视为积极因素。为保持竞争优势，供应链领导者急需通过数字工具和新型自动化技术来精简和强化运营。9月份的伦敦峰会将探讨技术如何重塑供应链运营与编排，帮助行业高管了解正在席卷供应链领域的最新技术。","scd":null,"kp":[]},{"i":2353,"as":"美国司法部要求联邦法院驳回针对马斯克旗下xAI的《清洁空气法》诉讼，称其在孟菲斯附近未经许可运行的燃气轮机属于“国家、经济和能源安全”事务。美国环保组织和NAACP指控xAI在没有所需许可或污染控制的情况下，违规使用数十台燃烧甲烷的燃气轮机，为其训练AI模型的Colossus数据中心供电。","scd":null,"kp":["[xAI孟菲斯数据中心]: 部署多台无许可证的燃气轮机（甲烷燃烧）提供能源并引发污染诉讼"]},{"i":2354,"as":"比亚迪推出了旗舰级全尺寸纯电SUV“Great Tang”，售价为35,500美元，预购量达到创纪录的15万辆。该车型续航里程接近950公里，最快可在5分钟内完成充电。得益于3月份推出的新型刀片电池2.0（Blade Battery 2.0）和闪充系统技术，比亚迪已开始全面应用这些新技术推出从超级跑车到旗舰SUV的多款新车型。","scd":null,"kp":["续航里程[比亚迪旗舰电动SUV Great Tang]: 约950公里(600英里)","最快充电时间[比亚迪Great Tang]: 5分钟","售价[比亚迪Great Tang]: 35,500美元","预订量[比亚迪Great Tang]: 15万辆"]},{"i":2355,"as":"美国电动汽车制造商Lucid已向欧盟知识产权局提交了其即将推出的Cosmos车型的外观设计注册。该注册号为015142895的文件于5月22日提交，6月15日公布，展示了这款售价低于50,000美元的量产版大众市场跨界车的内外100个视角。该车型设计与其在3月投资者日上展示的车型相符。","scd":null,"kp":["定价区间[Lucid Cosmos量产纯电 crossover]: 低于50,000美元","[Lucid Cosmos设计]: 已向欧盟知识产权局提交外观设计注册申请"]},{"i":2356,"as":"华盛顿州颁布了一项关于电动自行车分类的新法律，旨在更清晰明确地巩固美国多数州普遍接受的三级分类系统。然而，当地媒体多次误报该法律，错误声称该州将3类电动自行车视为电动摩托车，并要求骑手必须持有汽车驾驶证。事实上，1类和2类电动自行车的最高时速为20英里/小时。","scd":null,"kp":["[华盛顿州电动自行车分类新规]: 旨在明确并强化广泛接受的三级分类系统，而非将电动自行车重新归类为电动摩托车"]},{"i":2357,"as":"加州初创公司Aptera研发的太阳能电动汽车现已进入试驾阶段。该公司致力于打造超高效的太阳能电动汽车，其历史可追溯至2009年，甚至早于现代电动汽车技术的早期普及阶段。经过漫长的等待，该独特的太阳能汽车研发项目取得了实质性进展，并已在圣地亚哥准备就绪供媒体进行试驾体验。","scd":null,"kp":["车辆特性[Aptera太阳能电动汽车]: 具备超高效的太阳能电力驱动设计"]},{"i":2358,"as":"特斯拉在德国的一座超级充电站首次安装了免费的汽车吸尘器。该设备位于充电车位旁，方便车主在充电时清理车辆内部，提高等待时间的利用率。该充电站还配备了多个V4充电桩、太阳能车顶以及休息室，是特斯拉充电网络中配套设施最为完善的站点之一。","scd":null,"kp":["[特斯拉德国超充站服务设施]: 首次在充电桩旁安装免费车载真空吸尘器，允许车主利用充电闲置时间清理车辆"]},{"i":2359,"as":"保时捷宣布对2027款Taycan纯电跑车进行升级。此次更新最核心的改动是配备了原生NACS充电端口，以支持高速充电。此外，车辆还新增了一个可选的“假换挡装置”。保时捷Taycan目前是纽博格林赛道电动汽车圈速纪录的保持者，此次年度更新旨在进一步提升其性能与驾驶体验。","scd":null,"kp":["[2027款保时捷Taycan]: 新增可选的拟真（假）变速装置功能"]},{"i":2360,"as":"温哥华港推出了一项全新的数据共享试点项目，使用一支由Peterbilt 579EV 8级纯电动卡车组成的车队，在集装箱运输路线上运行。该项目旨在测量电动卡车在“第一英里”运输（即从港口到附近铁路站或卡车枢纽的短途重载运输）中的实际效益。这种路线短、可预测且夜间返场的运输模式被视为电气化的理想应用场景。","scd":null,"kp":["[温哥华港第一英里物流试点]: 投入纯电动8级Peterbilt 579EV半挂卡车队进行集装箱运输及数据共享测试"]},{"i":2361,"as":"Uber、自动驾驶公司Nuro和Lucid选择休斯顿作为其Robotaxi（无人驾驶出租车）服务的第二个城市，预计将于2027年中期在德州推出。乘客可以通过Uber应用程序叫车。此前，这些公司计划今年晚些时候在旧金山湾区推出首个Robotaxi服务市场。Nuro已在休斯顿的公共道路上进行带有安全员的测试，其工程车队规模接近100辆。","scd":null,"kp":["[休斯顿Robotaxi服务上线计划]: 预计于2027年中期推出，可通过Uber应用程序独家访问"]},{"i":2362,"as":"能源智库Ember的分析报告显示，在2025-26财年，为保持燃煤电厂在最低技术负荷下运行，印度削减了2.1太瓦时的可再生电力发电量，占总可再生发电量的1.3%。报告指出，若配置约10 GWh的电池储能系统，在正午光伏发电高峰期充电，即可吸收这些过剩的可再生能源，从而完全避免弃电现象。","scd":null,"kp":["弃风弃光电量[印度2025-26财年]: 2.1 TWh","可再生能源弃电比例[印度]: 1.3%","储能配置需求[吸收过剩光伏避免煤电低负荷停机]: 约10 GWh"]},{"i":2363,"as":"一个韩国代表团正在与赞比亚政府进行谈判，计划在该国建设一座总装机容量为500兆瓦的太阳能项目。该项目将分为十个阶段建设，每个阶段50兆瓦。赞比亚政府部委表示，该项目规模足够大，可以填补该国目前约三分之一的能源缺口。总部位于首尔的能源和基础设施公司KS Eco Solutions Holding Limited参与了此次战略合作洽谈。","scd":null,"kp":["项目规划装机容量[赞比亚太阳能项目]: 500 MW"]},{"i":2364,"as":"瑞浦兰钧在SNEC 2026展会上推出了其Wending 320 Ah钠离子储能电池。该电芯专为公用事业规模和长时间储能项目以及极端气候应用设计，循环寿命超过20,000次，计划于2027年实现商业化量产。此外，公司还发布了专为AI数据中心储能设计的85 Ah大功率磷酸铁锂（LFP）电芯。","scd":null,"kp":["电池容量[瑞浦兰钧钠离子储能电芯]: 320 Ah","循环寿命[钠离子电池]: 大于20,000次","量产时间[320Ah钠离子电芯]: 2027年"]},{"i":2365,"as":"Mercom Capital Group报告指出，2026年第一季度全球太阳能行业企业融资总额（包括风险投资、公开市场融资和债务融资）达到111亿美元，同比增长131%。融资交易数量也从2025年第一季度的39笔增长至53笔。不过，第一季度太阳能领域的风险投资资金为11亿美元，较去年同期的14亿美元下降了21%。","scd":null,"kp":["企业融资总额[2026年第一季度太阳能行业]: 111亿美元","企业融资同比增长率[太阳能行业]: 131%"]},{"i":2366,"as":"华润新能源在深圳证券交易所主板启动A股首次公开募股（IPO），目标融资34亿美元，这将成为中国可再生能源领域最大规模的上市之一。该公司是华润电力的可再生能源子公司，已获得中国证监会注册批准，并于6月22日开始申购。所筹资金将用于支持中国境内总装机容量达7.18吉瓦的风能和太阳能项目。","scd":null,"kp":["融资规模[华润新能源深交所IPO]: 34亿美元","项目装机量[风光发电项目]: 7.18 GW"]},{"i":2367,"as":"钻石矿业公司Lucara Botswana为博茨瓦纳的一个30兆瓦太阳能项目发起招标。该太阳能发电厂将为位于博茨瓦纳中北部的Karowe钻石矿供电。该矿于2012年投产，目前依赖国家电网和柴油发电运行。中标开发商将负责该太阳能设施的融资、建设、运营和维护，意向书提交截止日期为7月10日。","scd":null,"kp":["项目装机量[博茨瓦纳钻石矿太阳能供电]: 30 MW","投标截止日期[太阳能项目意向表达]: 7月10日"]},{"i":2368,"as":"受太阳能产能快速增长而短期需求停滞的推动，西班牙在2026年第一季度录得397小时的负电价，远超2025年同期的48小时，逼近2025年全年555小时的总和。例如在2月21日，电价降至-58.60欧元/兆瓦时。西班牙光伏协会（UNEF）指出，由于预计3到5年内将出现新的高耗电需求，这种供需失衡现象是暂时的。","scd":null,"kp":["负电价时长[西班牙第一季度电力市场]: 397小时","供需失衡预测[新增电力需求显现时间]: 3-5年内"]},{"i":2369,"as":"Dunext发布了容量为261千瓦时的PowerHill工商业储能系统。该系统采用磷酸铁锂电池和液冷技术，额定输出功率为125千瓦，具备IP55防护等级，并支持最多10台设备并联扩展部署。该新型产品旨在简化从安装调试到日常运维的全生命周期管理，进一步丰富了公司现有的215千瓦时和233千瓦时分布式储能产品线。","scd":null,"kp":["系统容量[PowerHill工商业储能系统]: 261 kWh","电池类型[工商业储能系统]: 磷酸铁锂(LiFePO4)","系统散热[工商业储能系统]: 液冷","额定功率[工商业储能系统]: 125 kW","防护等级[工商业储能系统]: IP55"]},{"i":2370,"as":"韩国能源研究所研发出一种叠瓦式光伏模块，可结合热电发生器通过塞贝克效应收集废热。该模块采用串联带状架构，实现高电压和低电流运行，降低了热电发生器的电阻损耗，成功构建出效率与可靠性双提升的可扩展光伏-热电系统。","scd":null,"kp":["电池组件架构[PV-TEG集成系统]: 叠瓦式串联带状结构","系统运行特点[PV-TEG集成系统]: 高电压低电流，降低热电发电机电阻损耗","废热收集方式[PV-TEG集成系统]: 塞贝克效应"]},{"i":2371,"as":"Fox ESS计划在2026年欧洲国际太阳能展上展示新品牌形象，并首次设立专属品牌区，展区面积超300平方米。展会核心为“The Champion’s Choice”宣传活动，结合沉浸式品牌故事，重点展示其在储能和太阳能领域的最新产品与未来发展规划。","scd":null,"kp":["展出面积[2026年欧洲国际太阳能展Fox ESS展台]: 超过300平方米"]},{"i":2372,"as":"阿里巴巴通义实验室推出首个具身人工智能模型系列“Qwen-Robot”，该系列将大语言模型与真实世界的机器人动作相连接。套件包含导航、操作和世界建模三款模型，赋予机器人物体识别、空间关系理解及复杂视觉指令执行能力，目前正进行企业客户试点测试。","scd":null,"kp":["模型类型[具身智能模型家族]: 通义实验室Qwen-Robot","核心模型配置[具身智能模型套件]: 导航、操作、世界建模三个模型","模型能力[具身智能系统]: 感知、推理并与真实物理环境交互"]},{"i":2373,"as":"","scd":null,"kp":[]},{"i":2374,"as":"美国聚变能源公司Helion获得华盛顿州卫生部颁发的放射性材料许可证和放射性气体排放许可证，成为全球首家获准建设聚变能发电厂的企业。聚变能源利用氢同位素等简单原子发生反应产生能量，具有不排放碳且不产生大量放射性废物的优势。","scd":null,"kp":["监管许可[全球首座聚变能发电厂建设]: 获放射性材料许可证(RML)和放射性空气排放许可证(RAEL)","技术特征[聚变能源发电]: 零碳排放发电方式"]},{"i":2375,"as":"","scd":null,"kp":[]},{"i":2376,"as":"莫纳什大学研究发现，一种基于铜的药物Cu(ATSM)能有效帮助大脑清除毒素。实验证实该化合物显著降低了与阿尔茨海默病相关的毒性蛋白水平，并改善了长期空间记忆。其机制在于修复血脑屏障的关键废物清除泵，恢复大脑清理过程，为治疗神经功能障碍提供了新策略。","scd":null,"kp":["干预药物[阿尔茨海默症治疗]: 铜递送药物Cu(ATSM)","药效特征[阿尔茨海默症治疗]: 显著降低有毒蛋白水平并改善长期空间记忆","治疗机制[阿尔茨海默症治疗]: 帮助大脑排出毒素并减少斑块积聚"]},{"i":2377,"as":"","scd":null,"kp":[]},{"i":2378,"as":"瑞典查尔姆斯理工大学开发出一种将物理定律直接嵌入神经网络的机器学习新方法。研究证实，为人工智能系统提供基础的物理学认知，能够大幅缩短开发量子计算机、相机镜头等先进光学组件所需的时间，使计算效率提高了十倍。","scd":null,"kp":["核心机制[物理定律驱动机器学习]: 将物理定律直接嵌入神经网络先验知识","技术效用[加速量子计算等光学组件开发]: 显著缩短先进光学组件的研发时间"]},{"i":2379,"as":"","scd":null,"kp":[]},{"i":2380,"as":"牛津大学物理学家利用本身具有强非经典特性的量子构件，创建了一类全新的量子叠加态，即薛定谔猫态。这种高阶量子态允许系统同时处于多重状态，将支持比传统量子比特更复杂的未来量子计算架构，并为量子传感和量子力学基础研究提供新途径。","scd":null,"kp":["[量子计算架构]: 使用高度非经典状态的模块化组件构建新型薛定谔猫态量子叠加态"]},{"i":2381,"as":"英国研究显示，微小的饮食习惯改变即可产生显著的碳减排效应。通过模型预测至2050年的环境足迹，每周仅用一份鲑鱼替代一块牛排，所减少的食物相关碳排放量，等同于一次从伦敦希思罗机场往返摩洛哥马拉喀什的跨欧航班所产生的二氧化碳排放。","scd":null,"kp":["碳减排效果[食物替代]: 每周用鲑鱼替代一份牛排的减排量，相当于伦敦希思罗往返摩洛哥马拉喀什的往返航班碳排放"]},{"i":2382,"as":"科研人员开发出名为“城市脉动”的卫星观测新框架，可近乎实时地测量和追踪城市的物理演变节奏。该技术能在社区繁荣、衰退或向绿地扩张的趋势变得明显之前，提前识别道路、建筑和社区的微小变化，将抽象的城市生命体概念转化为可量化监测的科学数据。","scd":null,"kp":["[城市动态监测]: 新型卫星框架可实现城市变化节律的近实时测量"]},{"i":2383,"as":"","scd":null,"kp":[]},{"i":2384,"as":"","scd":null,"kp":[]},{"i":2385,"as":"","scd":null,"kp":[]},{"i":2386,"as":"据The Information报道，微软正考虑在Copilot协同工作中使用DeepSeek大模型。目前该情报仅披露了微软意图接入DeepSeek模型以增强其AI助手功能的初步计划，暂无更多技术细节。","scd":null,"kp":["[AI模型应用]: 微软考虑使用DeepSeek大模型赋能Copilot协同工作"]},{"i":2387,"as":"据The Information报道，Snap公司正式发布了一款售价为2195美元的增强现实（AR）眼镜。该情报仅披露了产品的定价与发布信息，未提供具体硬件参数及功能详情。","scd":null,"kp":["产品售价[AR眼镜]: 2195美元"]},{"i":2388,"as":"肯尼亚虽有25%的社区缺乏中心电网覆盖，但该国正大力发展离网太阳能以实现全民通电目标。内罗毕企业家利用太阳能设备为当地居民提供玉米面粉研磨等核心商业服务，证明了离网太阳能在弥补传统电网空白和推动社区经济发展中的关键作用。","scd":null,"kp":["电网脱碳比例[肯尼亚]: 电网主要由可再生能源运行","社区缺电比例[肯尼亚]: 25%的社区缺乏集中供电","电力普及方案[肯尼亚]: 依赖离网太阳能实现全民电力普及目标"]},{"i":2389,"as":"一种特殊设计的巨型无人机旨在深入距地表约20公里的平流层执行地球工程任务。该无人机在空气极其稀薄的环境中保持长时间飞行，将向大气层释放特定化学物质以反射太阳光回太空。这一人工行星冷却技术提供了一种应对气候变化的潜在方案。","scd":null,"kp":["[地球工程平台]: 具备超大展弦比机翼的高空无人机，用于在远超商业客机的高度实施人工冷却地球的平流层气溶胶注入"]},{"i":2390,"as":"康斯坦茨HTWG大学将于2026/2027冬季学期起开设“应用人工智能”新学士学位课程。该课程旨在培养各行业广泛应用的AI技术人才，帮助学生掌握全方位的人工智能专业知识。","scd":null,"kp":["[人才培养]: 康斯坦茨HTWG大学开设应用人工智能本科课程"]},{"i":2391,"as":"2026年6月17日，弗劳恩霍夫木材研究所（WKI）举办成立80周年庆典。弗劳恩霍夫协会主席强调了该所在实现生物基循环经济方面的贡献。活动期间，政界与科研界嘉宾共同举行了新中试基地建设的奠基仪式。","scd":null,"kp":["[技术应用目标]: 致力于实现基于生物的循环经济"]},{"i":2392,"as":"德国空间规划学院（ARL）发布立场文件指出，市内汽车停车占用了大量公共空间。地方政府可通过战略性的停车管理工具，公平、高效地分配公共区域，将停车政策与气候和交通目标对齐，从而提升交通安全并改善城市宜居性。","scd":null,"kp":["[交通空间规划]: 战略性停车空间管理有助于促进公共用地的空间公平"]},{"i":2393,"as":"竞赛#ZukunftADP 2027聚焦大气压等离子体技术的创新。2025年的获奖者名单已经公布，但正文未提供具体的技术创新细节与竞赛参数。","scd":null,"kp":[]},{"i":2394,"as":"能源智库Ember分析指出，为防止煤电降负荷至技术最低负荷以下时导致的可再生能源弃电，印度当前急需约10吉瓦时的电池储能容量。2025-26财年因此削减了2.1太瓦时的清洁电力，占总可再生能源发电量的1.3%。","scd":null,"kp":["电池储能需求量[避免可再生能源削减]: 10 GWh"]},{"i":2395,"as":"巴西可再生能源发电项目融资在2025年达到63.6亿雷亚尔，同比增长10.6%，但仍比2022年低22%。高利率、监管变化和限电问题制约了项目发展。分布式光伏展现韧性，而电池储能仍处于监管发展的早期阶段。","scd":null,"kp":["可再生能源项目融资[巴西2025年]: 363亿巴西雷亚尔（约66亿美元）","融资增长率[巴西2025年较2024年]: 10.6%","融资差距[较2022年历史最高记录]: 低22%"]},{"i":2396,"as":"据报告，印度在2026年第一季度新增4.6吉瓦时的电池储能系统，环比增长939%。截至2026年3月，累计装机量达5.9吉瓦时。其中73%来自独立项目，全天候可再生能源项目占15%。抽水蓄能 pipeline 达57.2吉瓦。","scd":null,"kp":["新增电池储能容量[印度2026年第一季度]: 4.6 GWh","环比增长率[较上一季度442.7 MWh]: 939%","累计装机容量[截至2026年3月]: 5.9 GWh","独立项目占比[累计BESS容量]: 73%"]},{"i":2397,"as":"Entrix将为德国梅克伦堡州的Schloen项目提供AI支持的交易与优化服务。该项目集成了36兆瓦/144兆瓦时电池储能、光伏电站及电动车充电桩，预计于今年投入运营，利用AI优化电力的存储与调度。","scd":null,"kp":["储能项目规模[德国Schloen光储充项目]: 36 MW/144 MWh","[光储充项目电池充电来源]: 100%由协同部署的光伏电站发电充能"]},{"i":2398,"as":"Engie智利分公司启用Tocopilla综合体，配备116兆瓦/660兆瓦时的锂离子电池系统，包含240个电池集装箱。该项目由百年火电站改建，结合天然气发电，耗资约2.7亿美元，并于2月19日正式投入商业运营。","scd":null,"kp":["储能系统规模[智利Tocopilla项目]: 116 MW/660 MWh","项目投资额[燃煤电厂改造BESS及灵活燃气发电]: 约2.7亿美元"]},{"i":2399,"as":"赢创在上海开设了AEM（阴离子交换膜）中心，以推动相关技术的研发与应用。（注：因正文信息缺失，仅总结标题内容）","scd":null,"kp":["氢能项目规模[汉堡绿色制氢枢纽]: 100 MW"]},{"i":2400,"as":"Ohmium将支持在毛里塔尼亚、约旦和阿曼开展Hynfra氢能项目。（注：因正文信息缺失，仅总结标题内容）","scd":null,"kp":[]},{"i":2401,"as":"宁波成为全国分布式光伏第一城。截至5月底，其分布式光伏装机容量达974万千瓦，居全国首位。光伏发电量占全社会用电量10.24%。工业屋顶装机占比高达84%，并推出光伏共富项目，助力低收入农户增收与降碳。","scd":null,"kp":["分布式光伏装机容量[宁波截至5月底]: 974万千瓦","光伏发电占比[宁波全社会用电量]: 10.24%","装机结构占比[工业屋顶光伏]: 84%","装机结构占比[居民屋顶光伏]: 约8.6%"]},{"i":2402,"as":"北京绿色交通转型显著，地面公交新能源化率突破80%，巡游出租车全面电动化。交通行业车辆新能源化率达48%，中心城区绿色出行比例升至76.5%。通过优化公交线路与强化轨道交通接驳，交通能耗和碳排放实现双降。","scd":null,"kp":["新能源化率[北京地面公交]: 突破80%","新能源化率[北京交通行业整体]: 48%","绿色运输占比[北京货物到发]: 12%","绿色出行比例[北京中心城区]: 76.5%","能耗降幅[北京交通行业较十三五末]: 约21%"]},{"i":2403,"as":"西安电子科技大学“逐日工程”取得空间太阳能电站核心技术突破。团队在百米级距离实现了千瓦级微波无线传能，完成了一对多动目标微波传能地面验证。该技术利用电磁波在空间传输电能，致力于将太空太阳能传回地面。","scd":null,"kp":["微波无线传能技术[百米级距离]: 实现千瓦功率输出","微波无线传能[空间太阳能电站]: 完成一对多动目标微波无线传能地面验证"]},{"i":2404,"as":"中国可再生能源装机规模持续攀升，占比超六成。新疆单体容量最大若羌400万千瓦光伏项目预计年发电69亿千瓦时；滨州2吉瓦渔光互补及阳江18兆瓦海上风机顺利推进。规划明确实施非化石能源十年倍增行动。","scd":null,"kp":["光伏项目容量[新疆若羌]: 400万千瓦","占地面积[光伏项目]: 76.02平方公里","预计年发电量[光伏项目]: 69亿千瓦时","减排效益[光伏项目]: 每年减少二氧化碳排放约572万吨"]},{"i":2405,"as":"江西省重大科技专项“新能源用高性能芳纶绝缘纸关键技术”通过验收，达到国际先进水平。该技术打破了高端芳纶绝缘纸的国外技术垄断，实现了进口替代，产品已获美国UL认证，并参与了4项国家标准的制定。","scd":null,"kp":["芳纶绝缘纸关键技术[新能源用高性能]: 达到国际先进水平并打破高端依赖进口局面"]},{"i":2406,"as":"鑫源汽车数字工厂在重庆落成，战略新车“向上V6”正式量产。工厂依托华为数字化技术，结合智能视觉识别和AGV输送线，实现核心工序最高±0.2毫米精度。星原架构平台与数字工厂结合，大幅提升制造效率与品质。","scd":null,"kp":["汽车数智工厂[鑫源向上V6]: 智能设备、精密检测与数字化管控融为一体"]},{"i":2407,"as":"网商银行在金融展展示大模型人机协同信贷审批模式，使小微信贷效率提升约7倍。AI构建六大认知价值体系，深度解析小微企业在产业链中的经营特征与风险，显著增强金融风控识别精度与审批效率。","scd":null,"kp":["信贷审批效率提升[大模型人机协同小微信贷]: 约7倍","风控分析维度[AI信贷审批]: 具备穿透产业链分析企业真实经营状况的能力"]},{"i":2408,"as":"在“618”购物节，AI大模型全面融入电商场景。千问与淘宝打通，豆包接入抖音，将消费入口从搜索框转为对话框。约70%的淘系商家已在使用AI辅助经营，行业底层逻辑正从流量竞争转向决策权竞争。","scd":null,"kp":["交互模式[AI+电商]: 消费者决策起点从搜索框移至对话框"]},{"i":2409,"as":"天津脑机交互海河实验室利用脑机接口技术实现意念控物。其“神工”系列康复设备通过读取脑电信号驱动仿生机械手，已在十余省份数十家医院应用。该技术正扩展至睡眠调控、抑郁症诊疗及颅内压监测等医疗场景。","scd":null,"kp":["脑机交互[卒中康复]: 读取运动想象脑电信号并驱动外部仿生机械手","神经元数量[人脑]: 约860亿个"]},{"i":2410,"as":"6月16日17时45分，我国在西昌卫星发射中心使用长征三号乙运载火箭，成功将实践三十一号卫星发射升空。卫星顺利进入预定轨道，发射任务取得圆满成功。实践三十一号卫星主要用于空间环境探测。此次任务是长征系列运载火箭的第651次飞行。","scd":null,"kp":["发射任务[实践三十一号卫星]: 2026年6月16日17时45分使用长征三号乙运载火箭成功发射","卫星用途[实践三十一号]: 空间环境探测","火箭飞行次数[长征系列]: 第651次"]},{"i":2411,"as":"人工智能算力正加速向普惠型数字基础服务演进。我国日均词元调用量从2024年初的1000亿跃升至2026年3月的140万亿。工信部印发通知要求降低中小企业用算成本，三大运营商推出词元套餐向“算力经营”转型，DeepSeek、腾讯云等企业大幅下调API价格。本轮算力服务降价得益于国产芯片技术突破、算法演进及全国一体化算力建设，属于长期的结构性降本。","scd":null,"kp":["算力调用规模[全国日均词元调用量]: 从2024年初的1000亿跃升至今年3月的超140万亿"]},{"i":2412,"as":"太空算力正成为重构先进制造业竞争力的核心变量，催生空天一体化制造范式。地面数据中心面临年千亿千瓦时级的高耗能、散热物理极限以及卫星数据90%以上浪费等瓶颈。太空算力具备显著比较优势，太空中太阳能发电效率是地面的5到7倍，且不受昼夜天气影响，结合太空极低温真空环境，能为在轨计算节点提供近乎零边际成本的能源与散热供给。","scd":null,"kp":["太空算力战略定位[先进制造业]: 从补充性延伸跃升为重构产业竞争格局的核心变量"]},{"i":2413,"as":"产城融合正驱动人工智能规模化应用，主要体现在产业全链条升级、城市智慧化运行和社区精细化治理三方面。通过整合政策、人才与场景资源构建全链条服务生态，杭州余杭区依托龙头企业累计服务超200个科创项目。北京海淀区系统性开放城市治理场景，利用AI动态调控信号灯提升交通效率。上海浦东新区则通过AI技术构建感知精准的社区治理体系，解决人才居住、养老等后顾之忧。","scd":null,"kp":["[杭州余杭区青橙国际创新创业中心AI产业生态构建]: 累计服务科创项目超过200个"]},{"i":2414,"as":"随着我国词元日均调用量两年激增超千倍，词元场外交易、投资化炒作等乱象蔓延。不法分子将其包装为高增值投资品或保本理财，诱导公众投机，甚至通过虚假账号刷取免费词元低价倾销，滋生非法集资等金融风险。其根源在于现行法律未对词元法律定位作出明确界定，监管缺乏统一依据。必须明确词元法律界定，加大执法力度以防范炒作风险。","scd":null,"kp":["日均词元调用量[2024年初]: 1000亿","日均词元调用量[2025年底]: 100万亿","日均词元调用量[2026年3月]: 140万亿"]},{"i":2415,"as":"工信部印发《“人工智能+信息通信”创新发展实施意见（2026—2028年）》。意见提出，到2028年信息通信网络初步实现高等级自智，形成30个以上高价值典型场景，城域算力1毫秒时延圈覆盖率不低于75%。到2030年实现关键核心技术显著突破。重点聚焦5G-A/6G、新型网络架构、天基计算网络等领域攻关，构建“枢纽—区域—边缘”三级节点协同算力设施体系。","scd":null,"kp":["高价值典型场景形成数量[2028年信息通信网络]: 30个以上","城域算力1毫秒时延圈覆盖率[2028年信息基础设施]: 不低于75%"]},{"i":2416,"as":"人社部等四部门联合印发《关于实施创业模式引领行动的通知》。通知提出推进“科技成果+创业”模式，落实职务科技成果赋权与单列管理，支持科研人员离岗创办科技型企业，推广“先使用后付费”方式将科技成果许可给中小微企业使用。同时推进“产业发展+创业”模式，以链主和龙头企业为主导组建创新联合体，带动产业链上下游协同研发核心技术和产品。","scd":null,"kp":[]},{"i":2417,"as":"Eos Energy Enterprises与德国公司CAPAC签署了一项独家分销协议。根据协议，CAPAC将在德国市场独家分销Eos的长时储能（LDES）技术产品。这一合作标志着Eos首次正式进入德国储能市场。","scd":null,"kp":[]},{"i":2418,"as":"欧洲投资银行（EIB）购买了拉脱维亚能源公司Latvenergo发行的3亿欧元绿色债券中的2000万欧元份额。此次绿色债券发行旨在为可再生能源和能源存储等清洁能源项目提供融资支持。","scd":null,"kp":[]},{"i":2419,"as":"欧盟委员会已正式批准斯洛伐克提出的总价值10亿欧元的清洁技术国家援助计划。该计划旨在直接支持斯洛伐克国内包括陆上风电、海上风电以及储能技术在内的清洁能源产业发展与项目落地。","scd":null,"kp":[]},{"i":2420,"as":"江苏盐城响水县人民政府发布华电新能盐城新能源有限公司495MW渔光互补光伏发电项目环评受理公示。该项目位于响水县淮东养殖区，拟总投资21亿元，利用约8300亩水面建设，建设规模为495MW，施工工期为12个月。项目已于2025年10月11日完成备案。","scd":null,"kp":["建设规模[华电盐城淮东渔光互补光伏发电项目]: 495MW","总投资[华电盐城淮东渔光互补光伏发电项目]: 21亿元","施工工期[华电盐城淮东渔光互补光伏发电项目]: 12个月","利用水面面积[华电盐城淮东渔光互补光伏发电项目]: 约8300亩"]},{"i":2421,"as":"内蒙古钛晶新能源科技有限公司拟在乌兰察布市京蒙园区建设新型钙钛矿材料及纳米合金金属粉体材料项目。计划总投资约20亿元，占地约100亩，建设期为2026年8月至2028年8月。项目处于报批阶段，建成达产后预计年产值约3.6亿元，年用电量约1亿度，可安置就业约300人。","scd":null,"kp":["总投资[内蒙古乌兰察布钙钛矿材料项目]: 约20亿元","建设期[内蒙古乌兰察布钙钛矿材料项目]: 2026年8月至2028年8月","预计年产值[内蒙古乌兰察布钙钛矿材料项目达产后]: 约3.6亿元","预计年用电量[内蒙古乌兰察布钙钛矿材料项目达产后]: 约1亿度(折合标煤约12000吨)","占地面积[内蒙古乌兰察布钙钛矿材料项目]: 约100亩"]},{"i":2422,"as":"山西省发布省级零碳园区建设方案，力争到2030年建设10个左右省级零碳园区。方案提出因地制宜发展绿电直连、智能微电网等供应模式，探索氢电耦合开发，推广地热能等可再生能源技术。政策保障方面，零碳园区绿电直连项目优先纳入省级年度开发建设计划，配套储能列入省级项目库。通过验收评估的园区将正式成为省级零碳园区。","scd":null,"kp":["省级零碳园区建设数量[2030年山西省]: 10个左右","[省级零碳园区用能结构]: 因地制宜发展绿电直连、增量配电网、智能微电网，探索氢电耦合模式"]},{"i":2423,"as":"","scd":null,"kp":[]},{"i":2424,"as":"晶科能源自主研发的N型TOPCon钙钛矿叠层电池转换效率达到34.82%，经中国科学院上海微系统与信息技术研究所认证，再次打破世界纪录。该突破得益于双层复合钝化接触结构、多维界面钝化技术及光学耦合增强等多项核心技术创新。晶科能源是全球首家实现N型TOPCon技术大规模量产的光伏企业，此次纪录验证了叠层技术的产业化前景。","scd":null,"kp":["转换效率[N型TOPCon钙钛矿叠层电池]: 34.82%","[N型TOPCon钙钛矿叠层电池核心技术]: 双层复合钝化接触结构、多维界面钝化、梯度结晶动力学调控、光学耦合/光管理增强"]},{"i":2425,"as":"江西省发布增量新能源项目机制电价竞价实施细则，针对2027年起自发自用余电上网的工商业分布式项目无机制电价。竞价工作依托平台组织，坚持流程透明化，分布式项目并网须满足“可观、可测、可调、可控”条件。分期并网的项目需按期确定全容量并网时间并参与机制电价竞价，确保竞争公平与审核公正。","scd":null,"kp":["电价机制[工商业分布式新能源项目]: 2027年起自发自用余电上网无机制电价","竞价组织平台[增量新能源项目]: 江西省新能源可持续发展机制电量竞价平台","并网容量计算标准[新能源项目]: 项目核准(备案)装机容量(交流侧)"]},{"i":2426,"as":"","scd":null,"kp":[]},{"i":2427,"as":"","scd":null,"kp":[]},{"i":2428,"as":"Ayaneo公布Pocket MICRO 2掌机电池容量为3950毫安时。该高密度电池容量较上一代机型增加52%。初代Pocket MICRO内置2600毫安时电池，搭载联发科Helio G99处理器，配备3.5英寸IPS原彩屏，机身宽度约63mm，首发价格为1299元起。","scd":null,"kp":["电池容量[Ayaneo Pocket MICRO 2掌机]: 3950mAh","电池容量提升[Ayaneo Pocket MICRO 2掌机]: 相比上一代大52%","机身宽度[初代Pocket MICRO掌机]: 约63mm"]},{"i":2429,"as":"","scd":null,"kp":[]},{"i":2430,"as":"","scd":null,"kp":[]},{"i":2431,"as":"杭州深度求索人工智能基础技术研究有限公司（DeepSeek）完成首轮外部融资，总规模约510亿元人民币，企业估值近4000亿元。投资方包括创始人梁文锋、腾讯、宁德时代、网易、京东及国家人工智能产业投资基金等。创始人梁文锋要求外部投资者将资金投入其管理的有限合伙企业并设置五年锁定期，外部投资者不享有投票权，仅国家人工智能产业投资基金直接入股并享有投票权。融资所得计划用于扩展AI基础设施、加强研发、股权激励及加快商业化。","scd":null,"kp":["融资规模[DeepSeek首轮融资]: 约510亿元","企业估值[DeepSeek首轮融资]: 近4000亿元","入股规模[宁德时代入股中恒电气]: 约41亿元","入股规模[宁德时代入股世纪互联]: 约9.42亿美元"]},{"i":2432,"as":"","scd":null,"kp":[]},{"i":2433,"as":"","scd":null,"kp":[]},{"i":2434,"as":"","scd":null,"kp":[]},{"i":2435,"as":"我国水电装机容量已达4.5亿千瓦，居世界首位。长江流域建成的乌东德等六座大型水电站组成全球最大“清洁能源走廊”，跨越1800公里，总装机容量达7169.5万千瓦，年发电量3000亿千瓦时。其中白鹤滩水电站年均发电量约624亿千瓦时。此外，四川雅江县正建设全球最大的混合式抽水蓄能电站——两河口抽水蓄能电站，预计2028年投产，年提供清洁电能14亿度。","scd":null,"kp":["装机容量[我国水电]: 4.5亿千瓦","总装机容量[白鹤滩水电站]: 1600万千瓦","日均发电量满足人数[白鹤滩水电站]: 1.48亿人日常用电","年均发电量[白鹤滩水电站]: 约624亿千瓦时","标准煤节约量[白鹤滩水电站年均]: 超过1800万吨"]},{"i":2436,"as":"","scd":null,"kp":[]},{"i":2437,"as":"平陆运河已全线通水进入通航倒计时，首艘5000吨级绿色智能示范船“北港运河002”顺利完成试航，标志着通航配套运力建设取得关键进展。该船配备智能辅助航行、能效管理、安全监测等智能化系统，各项试航测试参数均达标。平陆运河全长134.2公里，是新中国成立以来首条国家层面统筹的通江达海运河工程，属于西部陆海新通道骨干工程，计划于今年9月正式通航。","scd":null,"kp":["载重能力[平陆运河内河示范船]: 5000吨级","试航时长[北港运河002示范船]: 6个小时","核心特征[北港运河002示范船]: 全区首条配备智能化系统的新建内河船舶","集成模块[示范船智能化系统]: 智能辅助航行、能效管理、安全监测、综合信息显示"]},{"i":2438,"as":"","scd":null,"kp":[]},{"i":2439,"as":"","scd":null,"kp":[]},{"i":2440,"as":"针对网传“工信部第408批公告将一汽夏利、华晨自主、众泰等8家汽车企业移出名录且生产资质永久失效”的消息，经核实为不实信息。实际名单中仅原一汽夏利多年前已注销准入许可，其余7家企业仅有个别生产地址被注销或拟注销。近几期工信部公告均无资质冻结表述。众泰汽车也回应澄清其为名录内企业，相关传闻毫无官方出处。","scd":null,"kp":["资质状态[一汽夏利]: 多年前已注销准入许可","资质状态[网传8家车企]: 整车资质永久失效为不实消息"]},{"i":2441,"as":"","scd":null,"kp":[]},{"i":2442,"as":"","scd":null,"kp":[]},{"i":2443,"as":"美国太空探索技术公司的货运“龙”飞船于6月17日成功溅落加利福尼亚州附近海域，携大量科研物资返回地球。返航物资包括生物打印的器官和软骨组织、开发新型癌症疗法的DNA仿生材料，以及改进太空低温燃料储存技术的相关数据。此外还包括眼部成像设备、空气净化装置等硬件设备。此次任务是SpaceX第34次为NASA执行国际空间站补给任务。","scd":null,"kp":["下行运送物资重量[货运龙飞船第34次任务]: 约3000公斤","关键载荷[货运龙飞船返回]: 生物打印的器官和软骨组织、DNA仿生材料、眼部成像设备、空气净化装置、分离泵","技术实验数据[货运龙飞船返回]: 改进未来太空任务低温燃料储存技术的数据"]},{"i":2444,"as":"谷歌在Android 17中推出ADB Wi-Fi 2.0，彻底重写无线调试堆栈以解决断连痛点。新方案放弃了旧版的第三方库，改用约4000行Rust代码自研的轻量级跨平台库，设备端直接调用原生NsdManager堆栈。新系统通过SSID与BSSID智能组合识别受信任网络，能自动监测网络状态变化，在网络波动后无需手动干预即可自动完成重连，大幅提升了无线调试的稳定性。","scd":null,"kp":["重写代码量[Android 17 ADB Wi-Fi 2.0]: 4000行Rust代码","[Android 17无线调试]: 彻底重写无线调试堆栈解决断连痛点"]},{"i":2445,"as":"谷歌发布搭载Gemini AI助手的新一代Google Home智能音箱，定价100美元。产品采用球形3D织物设计，提供360°环绕音效与自适应麦克风系统。硬件搭载四核Cortex-A55处理器、1GB内存与4GB存储。内置Gemini助手支持自然语言交流与多步骤语音指令，能够理解用户中途改口的复杂语句并执行操作。支持与Google TV Streamer组建立体声环绕系统。","scd":null,"kp":["定价[新一代Google Home智能音箱]: 100美元","内存配置[新一代Google Home智能音箱]: 1GB LPDDR4","处理器[新一代Google Home智能音箱]: 四核Cortex-A55 2.0 GHz","存储空间[新一代Google Home智能音箱]: 4GB","AI助手[新一代Google Home智能音箱]: Gemini for Home"]},{"i":2446,"as":"现代汽车宣布在其土耳其伊兹密特工厂扩建Ioniq 3电动汽车生产线，并新建专属电池组装厂。该电池组装设施属于总额7.15亿欧元投资的一部分，其中5500万欧元专门用于电池工厂建设。新厂房占地3万平方米，由现代汽车土耳其分公司与现代摩比斯合作，未来将实现电池组在工厂内的自动化组装。Ioniq 3将于8月在土耳其正式启动量产。","scd":null,"kp":["投资规模[现代汽车土耳其工厂扩建]: 7.15亿欧元","投产计划[现代Ioniq 3]: 8月开始系列生产","工艺特点[土耳其伊兹密特工厂]: 自动化现场组装电池包"]},{"i":2447,"as":"由TU Graz牵头的研究联盟在欧盟资助的Nemo项目中，研发出一款面向电动汽车的先进电池管理系统（BMS）。传统BMS通常仅依靠电压、电流和温度进行粗略监测。新型BMS引入全新传感器与算法，能够更深入地洞察电池组及单体电芯的内部行为，旨在精准探测电池损伤与老化过程，从而大幅提升电动汽车电池的安全性能并延长使用寿命。","scd":null,"kp":["电池管理系统[电动汽车]: 采用新传感器和算法提供更深入的电池行为洞察，提升安全性和使用寿命"]},{"i":2448,"as":"福特汽车借助宁德时代的技术许可与支持，将在今年生产首批自有磷酸铁锂（LFP）电池。福特的“D-Sample”电池正使用量产级材料进行最终测试验证。密歇根州电池工厂完全归福特所有，预计2026年底前开始生产符合市场标准的电池电芯。这些方形LFP电池将搭载于福特基于Universal EV平台打造的新一代平价电动皮卡，该车计划于2027年正式推出。","scd":null,"kp":["电池量产时间[福特工厂]: 2026年底前","电池应用规划[福特基于Universal EV平台的经济型电动皮卡]: 2027年推出的车型","电池形态[LFP电池]: 棱柱形"]},{"i":2449,"as":"Supply Chain LIVE: The London Summit活动聚焦人工智能在供应链网络中的未来应用。面对前所未有的技术进步与全球性业务中断风险，AI正成为供应链规划与执行的关键力量，旨在使运营更无缝高效并提升韧性。行业领袖在会上深入探讨了企业与AI交互方式的演进路线，强调忽视AI应用能力的企业将在竞争中被淘汰。","scd":null,"kp":["[AI在供应链中的应用]: 用于规划和执行，决定企业未来的竞争力"]},{"i":2450,"as":"亚马逊与康宁达成了一项价值数十亿美元的合作协议，旨在扩大美国国内光纤产能，确保云数据中心供应链的稳定。此举将增加康宁北卡罗来纳州工厂的产量，并创造1000个就业岗位。光纤电缆网络是连接云计算区域的物理骨干，该协议解决了可能限制数据中心部署和互联速度的供应限制问题。","scd":null,"kp":["光纤网络[数据中心]: 构成连接云计算区域的物理骨干","合作协议[亚马逊与康宁]: 达成数十亿美元的供应协议并创造1000个就业岗位"]},{"i":2451,"as":"大众汽车首款纯电动GTI车型ID. Polo GTI将于今年秋季上市。近期，另一款纯电动高性能掀背车在德国进行测试时被曝光。据图片显示，这款几乎无伪装的测试原型车为ID.3 Neo的GTI版本，预计命名为ID.3 Neo GTI。该车型的外观设计与4月份发布的升级版ID.3 Neo基本一致，预计将在今年年底前正式亮相。","scd":null,"kp":["新车发布计划[大众ID.3 Neo]: 预计在今年年底前完整亮相","车型上市时间[大众ID. Polo GTI]: 今年秋季"]},{"i":2452,"as":"博世正式推出了其首款面向城市电动自行车的后轮毂电机系统，将智能系统技术引入了新的细分市场。此前，博世在电动自行车领域一直占据中置电机市场的主导地位。新款轮毂电机旨在为通勤者和城市骑行者提供一个轻量化且高度互联的驱动平台。这一举措标志着博世正式进军结构更简单、成本更低且运行安静的城市电动自行车轮毂电机领域。","scd":null,"kp":["[博世首款后轮毂电机系统]: 专为城市电动自行车设计，提供轻量化、互联的平台"]},{"i":2453,"as":"","scd":null,"kp":[]},{"i":2454,"as":"对加州圣地亚哥县太阳能电动汽车初创公司Aptera的工厂考察揭示了其最新进展与面临挑战。Aptera致力于打造超高效的三轮太阳能电动汽车。该公司成立于2006年，在近期提供了该车型的首次试驾体验。工厂参观展示了Aptera在研发和生产这款极具创新的太阳能电动汽车方面所取得的实质性进步，同时也暴露了公司在后续发展中仍需克服的障碍。","scd":null,"kp":["[Aptera 3]: 致力于打造超高效率的三轮太阳能电动汽车"]},{"i":2455,"as":"随着电动自行车和电动滑板车在美国的普及率飙升，美国汽车协会（AAA）宣布进军微出行领域，推出了一项名为“E-Ride Ready”的安全倡议。该活动旨在夏季骑行高峰前，向家庭普及相关安全知识。AAA提供免费的《E-Ride安全指南》，帮助父母了解设备工作原理、合法骑行区域以及如何选择头盔等安全装备，以应对微出行设备增长快于公众安全意识和基础设施发展的现状。","scd":null,"kp":["[AAA 'E-Ride Ready'安全倡议]: 针对美国家庭普及电动自行车和电动踏板车安全教育"]},{"i":2456,"as":"Ava Community Energy旗下的SmartHome电池项目宣布，为符合条件的北加州低收入居民提供高达6000美元的预付现金激励，用于安装FranklinWH智能电池并将其接入该公用事业公司的虚拟电厂（VPP）。虚拟电厂使公用事业公司能够在用电高峰期调度联网电池，从而防止停电并减少电网压力，避免了建造传统的燃气调峰电厂。用户在停电时获得备用电源，实现双赢。","scd":null,"kp":["补贴金额[加州Ava Community Energy SmartHome电池项目]: 高达6000美元的前期现金激励","设备配置[虚拟电厂]: 安装FranklinWH智能电池并接入公用事业的VPP"]},{"i":2457,"as":"正泰集团通过构建高度整合的商业模式来实现跨周期的弹性发展。自2006年进入可再生能源领域以来，正泰建立了一条端到端的价值链，业务涵盖上游的硅材料和硅片、中游的太阳能电池和组件及逆变器和储能系统（BESS），以及下游的项目开发、EPC和运维。正泰高管表示，这种一体化方法创造了强大的产业协同效应。公司的下一阶段增长计划将包括绿色燃料和虚拟电厂。","scd":null,"kp":["[正泰商业拓展方向]: 下一阶段将包括绿色燃料和虚拟电厂"]},{"i":2458,"as":"伊朗可再生能源和能效组织（SATBA）正致力于部署15吉瓦（GW）的小型太阳能发电厂。据伊朗伊斯兰共和国通讯社报道，SATBA已向政府提交了一项提案，计划在国内、商业和农业太阳能领域快速建设这些小型电站。SATBA首席执行官表示，该计划将结合国内制造业的发展来推进实施，标志着伊朗将部分重心转移至结合混合逆变器和电池的小型发电设施。","scd":null,"kp":["规划装机目标[伊朗小型太阳能电站]: 15 GW","发展方向[小型电站配置]: 采用混合逆变器与电池储能"]},{"i":2459,"as":"印度信用评级和研究公司Crisil预测，受本土化政策推动和产能扩张影响，到2026-27财年（2026年4月1日至2027年3月31日），印度本土制造的太阳能电池将满足国内约一半的总需求，高于上一财年的四分之一。然而，Crisil警告称，虽然产能的快速扩张有助于减少对进口的依赖，但也可能会对产能利用率和投资回报率造成压力。预计到2027年第一季度末，印度太阳能电池产能将超过60吉瓦。","scd":null,"kp":["产能供给比例[2026-27财年印度产太阳能电池占国内需求]: 约50%","预测产能规模[2027年第一季度末印度太阳能电池]: 超过60吉瓦"]},{"i":2460,"as":"Oxford PV宣布其采用弗劳恩霍夫太阳能系统研究所（Fraunhofer ISE）矩阵叠瓦架构的钙钛矿-硅串联太阳能组件实现了25.6%的功率转换效率。这是两项技术的首次成功整合。这种无主栅的叠瓦设计减少了电阻和遮光损失，同时提高了能量产量、耐用性以及组件级别的性能表现，标志着钙钛矿太阳能组件制造技术的重大突破。","scd":null,"kp":["转换效率[Oxford PV钙钛矿-硅叠瓦串联组件]: 25.6%","技术特征[钙钛矿-硅叠瓦架构]: 无主栅设计，降低电阻和遮挡损耗，提升耐用性及组件级性能"]},{"i":2461,"as":"挪威可再生能源开发商Scatec在达到财务关闭后，已开始在突尼斯建设120兆瓦（MW）的Sidi Bouzid II太阳能发电厂。该项目预估总资本支出为9600万欧元（约1.101亿美元），资金由无追索权债务和股权组合提供。欧洲复兴开发银行和欧洲投资银行担任该项目的高级贷款机构，并获得了欧盟邻国投资平台的额外赠款资金和担保支持。","scd":null,"kp":["装机规模[突尼斯Sidi Bouzid II太阳能项目]: 120 兆瓦","总投资额[突尼斯Sidi Bouzid II太阳能项目]: 9600万欧元 (约1.101亿美元)"]},{"i":2462,"as":"GameChange Energy正采用一种高度集成的平台方法来简化公用事业规模太阳能项目的管理。传统上，管理用于跟踪支架、电气平衡系统（eBOS）、变压器和运维的多个供应商会增加每个项目的成本和风险。GameChange公司的集成方案精简了采购和施工流程，从而有效降低了开发商和EPC（工程、采购、施工）的风险，确保设备在正确的时间送达正确的地点并保持系统满负荷运转。","scd":null,"kp":["技术特征[公用事业规模太阳能集成平台]: 整合跟踪支架、eBOS、变压器及运维(O&M)供应链，精简采购与施工流程以降低风险"]},{"i":2463,"as":"蒙古国能源部已启动一项招标，计划建设五个太阳能结合储能的独立发电商（IPP）项目。这五个项目总装机容量包括110兆瓦（MW）的太阳能以及52兆瓦/188兆瓦时的电池储能系统（BESS）。其中三个项目位于蒙古国西部地区，另外两个位于东部地区。感兴趣方的意向书提交截止日期为8月16日。","scd":null,"kp":["招标装机规模[蒙古太阳能项目]: 110 兆瓦","配套储能规模[蒙古光储项目]: 52 MW/188 MWh","项目分布[蒙古光储项目]: 5个不同场址"]},{"i":2464,"as":"阿根廷能源部在AlmaSADI储能项目招标中推进了232项电池储能投标。该招标旨在为阿根廷互联系统（SADI）采购电池储能系统，收到的235项投标中有232项获准进入经济评估阶段，仅3项因不合规被取消资格。获准的投标总容量达8.3吉瓦（GW），是该计划700兆瓦参考目标的近12倍。该招标由CAMMESA管理，旨在签订提供容量和运行储备的储能服务合同。","scd":null,"kp":["通过投标规模[阿根廷AlmaSADI储能招标]: 232个投标(总计8.3吉瓦)","招标参考目标[阿根廷AlmaSADI储能招标]: 700 兆瓦"]},{"i":2465,"as":"葡萄牙正在开发一种新的容量机制，旨在随着电气化加速、可再生能源扩张和未来十年电力需求预期增长而保障电力供应。这项由环境与能源部宣布的措施，将通过竞争性程序向发电资产、储能和需求侧灵活性资源提供补偿，以奖励在用电高峰期可调用的资源。此外，葡萄牙重申了通过拍卖提供750兆伏安（MVA）电池储能容量的计划，正式开拓电池储能的容量市场。","scd":null,"kp":["计划拍卖容量[葡萄牙电池储能容量市场]: 750 MVA","市场机制特征[葡萄牙新容量市场]: 向电池储能、发电厂及灵活需求开放以保障电力供应"]},{"i":2466,"as":"法国光伏研究所（IPVF）与荷兰代尔夫特理工大学（TU Delft）合作，在一块4平方厘米的两端（2T）钙钛矿-硅串联太阳能电池上实现了31%的功率转换效率。该单片设备结合了代尔夫特理工大学开发的纳米纹理硅异质结底电池，以及IPVF利用环境空气狭缝模头涂层技术制造的钙钛矿顶电池。这一成果标志着高效串联太阳能电池制造技术的显著进步。","scd":null,"kp":["转换效率[IPVF与代尔夫特理工大学4 cm²钙钛矿-硅串联电池]: 31%","电池面积[IPVF与代尔夫特理工大学钙钛矿-硅串联电池]: 4 cm²","技术特征[两端钙钛矿-硅串联电池]: 采用纳米纹理硅异质结底电池和环境空气狭缝涂布钙钛矿层"]},{"i":2467,"as":"美国海军向国防科技初创公司Castelion授予了首份“黑胡子”高超音速导弹的生产合同，价值2340万美元。合同涵盖50枚预生产导弹，标志着该计划已从研发测试阶段迈向实战部署。“黑胡子”被设计为一种低成本、易于量产的高超音速武器，飞行速度可超过5马赫（约6100公里/小时）。此举符合五角大楼寻求更快速、经济的高超音速武器用于远程打击的需求，并将扩大新墨西哥州制造基地的产能。","scd":null,"kp":["合同金额[美国海军黑胡子高超音速导弹预生产合同]: 2340万美元","采购数量[黑胡子高超音速导弹]: 50枚预生产导弹","飞行速度[黑胡子高超音速导弹]: 5马赫"]},{"i":2468,"as":"","scd":null,"kp":[]},{"i":2469,"as":"","scd":null,"kp":[]},{"i":2470,"as":"","scd":null,"kp":[]},{"i":2471,"as":"","scd":null,"kp":[]},{"i":2472,"as":"","scd":null,"kp":[]},{"i":2473,"as":"《科学进展》发表的一项关于橡树的最新研究打破了传统气候模型的假设。研究发现，橡树在仲夏结束木质部生长后，仍能在深秋持续进行数月的光合作用。这一发现表明，树木的光合作用与生长并不同步。更多光合作用并不意味着更多的树木生长，这挑战了气候模型中关于森林如何有效将吸收的碳转化为长期储存的原有假设。","scd":null,"kp":[]},{"i":2474,"as":"阿伯里斯特威斯大学和佛罗伦萨大学的研究人员发现，鹿虻在找到宿主、脱落翅膀并转变为寄生生活方式后，其感觉系统发生显著变化。为了将能量重新分配给停止飞行后的寄生生活所需的重要功能，鹿虻会主动牺牲部分视觉能力，降低对高灵敏度视觉系统的资源维持。这种能量保存机制有助于其更好地适应寄生状态。","scd":null,"kp":[]},{"i":2475,"as":"科学家首次成功捕获了人类SMUG1修复酶的原子级结构图像。SMUG1是参与DNA损伤修复的关键酶，也是细胞质量控制系统的核心部分，负责定位和清除受损的DNA成分以维护基因稳定。这一前所未有的结构细节揭示了该酶的具体工作原理，为未来开发针对该DNA修复路径的靶向药物提供了重要的指导依据。","scd":null,"kp":["[人类DNA修复酶SMUG1原子级图像捕获]: 首次成功捕获并绘制关键人类修复酶（SMUG1）在作用过程中的原子级视图","细胞质量控制系统[SMUG1酶]: 识别并去除威胁遗传稳定性的分子错误"]},{"i":2476,"as":"蒙大拿州立大学在《自然-化学生物学》上发表研究，揭示了一条此前未知的哺乳动物细胞生存备用路径。几十年来生物学界认为细胞产生必需氨基酸半胱氨酸的途径是唯一的，但新研究发现，当原本被认为不可或缺的主系统失效时，细胞仍能通过此备用途径持续合成半胱氨酸以维持生存。这一发现推翻了传统细胞生物学假设，为提升癌症治疗效果提供了新策略。","scd":null,"kp":[]},{"i":2477,"as":"巴西圣保罗联邦大学在《神经药理学》上发表研究，发现一种天然的抗炎蛋白质肽段在帕金森病治疗中展现出巨大潜力。在小鼠实验中，该天然肽段能够有效保护易受损的脑细胞免受退行性病变。目前帕金森病治疗多局限于缓解症状，而这一新方法直接针对大脑内部的炎症损伤，为未来减缓或预防帕金森病造成的神经损伤提供了全新治疗方向。","scd":null,"kp":[]},{"i":2478,"as":"北京大学周欢萍与严纯华团队在《自然》发表论文，提出“原位纳米晶限域”新策略，成功突破蓝光钙钛矿发光二极管性能瓶颈。该技术利用可聚合配体在结晶中原位形成聚合物网络，动态限制晶粒生长，同步实现了高结晶质量与纳米级尺寸，降低了缺陷密度并促使材料向立方相转变。基于该策略制备的蓝光PeLED外量子效率高达21.8%，且显著提升了器件运行稳定性。","scd":null,"kp":["外量子效率[蓝光钙钛矿发光二极管]: 21.8%","发光材料制备策略[钙钛矿发光二极管]: 原位纳米晶限域策略（动态限域纳米晶生长，实现兼具高结晶性和纳米尺度的原位可控制备）"]},{"i":2479,"as":"南京大学谭海仁团队联合仁烁光能成功研制出面积达65平方厘米的全钙钛矿叠层光伏组件。该组件采用无空穴传输层的隧穿复合结结构，引入纳米晶功能层替代传统金属复合层。结合二元共溶剂体系与刮涂工艺，实现了大尺寸薄膜均匀制备。经日本JET认证，其光电转换效率高达26.2%，刷新了该面积级别全钙钛矿叠层组件的世界纪录，为空间轻量化光伏系统提供了理想方案。","scd":null,"kp":["光电转换效率[大面积全钙钛矿叠层光伏组件]: 26.2%","组件面积[全钙钛矿叠层光伏组件]: 65平方厘米","光伏组件结构[全钙钛矿叠层电池]: 无空穴传输层的隧穿复合结结构（采用纳米晶功能层替代传统超薄金属复合层，去除PEDOT:PSS）","溶剂体系[刮涂工艺制备铅-锡窄带隙钙钛矿薄膜]: 2-甲氧基乙醇和四氢呋喃组成的二元共溶剂体系"]},{"i":2480,"as":"SOLARBE TEST公布的2026年5月TOPCon光伏组件户外实证数据表明，组件实测高功率并不等同于高单瓦发电量。测试在经历弱光、频繁降水的西安真实工况下进行，涵盖8款不同功率组件。结果显示，单瓦发电量排名第一的产品其实测功率仅为417.45W，而非功率最高的685.79W组件。这证明了在复杂实际应用场景中，不同产品的性能差异显著，为行业选型提供了重要参考。","scd":null,"kp":["组件最大实测功率[SOLARBE TEST单项冠军赛TOPCon组件]: 417.4 W","全月累计辐照量[2026年5月西安户外实证测试场]: 137.89 kWh/m²","日平均辐照度[2026年5月西安户外实证测试场]: 4.45 kWh/m²","[高功率光伏组件户外实证表现]: 组件实测功率的提升并不必然等同于单瓦发电量的提高"]},{"i":2481,"as":"2026年一季度中国绿证交易均价达5.13元/个，同比增长2.17倍。绿证价格因对应发电年份不同呈现显著梯度递增，2024至2026年电量绿证均价分别为1.51元、5.71元和7.76元，价差最高超5倍。由于国际RE100倡议无条件认可中国绿证，刺激了企业合规采购需求。电站运营方需建立按月及时核发并交易新证的习惯，以避免老证贬值造成收益损失。","scd":null,"kp":["绿证交易均价[2026年一季度]: 5.13元/个","绿证价格[2024年发电量]: 1.51元/个","绿证价格[2025年发电量]: 5.71元/个","绿证价格[2026年发电量]: 7.76元/个","绿证核发量[10MW电站年发电量对应]: 约11,000个"]},{"i":2482,"as":"人工智能图像生成公司 Midjourney 宣布推出全身扫描仪产品，并计划推出 Spa（水疗/休闲）业务。","scd":null,"kp":["[Midjourney硬件布局]: 推出全身扫描仪并计划推出Spa"]},{"i":2483,"as":"受内存和存储芯片短缺的影响，苹果公司计划提高其产品的销售价格。","scd":null,"kp":["[苹果产品提价动因]: 内存和存储芯片短缺导致成本上升"]},{"i":2484,"as":"亚马逊云服务 (AWS) 在纽约峰会上最新推出了全新的网络安全服务和代码编写工具。","scd":null,"kp":["[AWS产品发布]: 在纽约峰会上推出新的网络安全和编码工具"]},{"i":2485,"as":"美国太空探索技术公司 (SpaceX) 正式任命 Roelof Botha 为公司董事会成员。","scd":null,"kp":["[SpaceX董事会变动]: 任命Roelof Botha为董事会成员"]},{"i":2486,"as":"视频应用程序 Rumble 宣布收购知名图形处理器 (GPU) 提供商 Northern Data。","scd":null,"kp":["[Rumble收购案]: 视频应用程序Rumble收购GPU提供商Northern Data"]},{"i":2487,"as":"研究人员指出，太阳地球工程作为应对气候紧急情况的手段，在实际操作中面临极其复杂的工程挑战。这种通过向大气层散射反射阳光粒子来为地球降温的方案，并非简单的“急刹车”。各国或企业如何具体实施全球冷却计划涉及大量尚未解决的技术难题，其实际应用难度远超此前的预期。","scd":null,"kp":["[太阳地球工程]: 面临重大未解的实际挑战，机制复杂而非简单的紧急制动"]},{"i":2488,"as":"为了直接探测暗物质，科研人员在意大利亚平宁山脉、四川锦屏山以及南达科他州矿井深处部署了充满液氙的大型探测器。探测目标是捕获暗物质弱相互作用大质量粒子（WIMP）撞击氙原子时产生的光和电荷。经过数年运行，探测器近期捕捉到了稀有粒子信号，但已确认这些信号并非由暗物质产生。","scd":null,"kp":["暗物质探测器[直接探测]: 充满液态氙的大型探测器","[暗物质目标粒子]: 弱相互作用大质量粒子"]},{"i":2489,"as":"卡尔斯鲁厄理工学院（KIT）开发了U Shift系统，该系统采用“驱动板”行驶平台与可替换舱体相结合的设计理念，实现了一车多用。通过更换不同的模块化舱体，该车辆平台可灵活转换为今天的通勤班车或明天的货物配送车，以满足多样化的应用场景需求。","scd":null,"kp":["[多功能车辆设计]: 模块化设计实现一车多用（穿梭班车与送货车功能切换）"]},{"i":2490,"as":"AI26 – 拉玛会议将于2026年7月7日至8日在波恩世界会议中心举行。会议汇集科学、经济和政治领域的专家，重点探讨如何将当前的人工智能研究转化为创新、应用并发挥社会影响。会议背景指出，人工智能是关键科技，在加剧的国际竞争中，德国正努力争取技术主权、高性能基础设施和基于AI的价值创造。会议通过互动讨论、小组座谈和 workshops 等形式，为各领域提供直接交流平台。","scd":null,"kp":["[拉玛会议]: 聚焦前沿人工智能研究以促进创新和价值创造"]},{"i":2491,"as":"Aypa Power 与盐河项目（SRP）合作推出的250 MW/1,000 MWh Pediment电池储能系统已在亚利桑那州梅萨市正式上线投入运营。该储能资源为SRP提供了灵活性和容量，以可靠地服务客户。该项目是SRP能源组合的重要补充，支持其在当地创纪录增长期提供可靠、廉价且可持续电力的承诺，同时体现了Aypa Power在高增长市场交付电力基础设施的战略布局。","scd":null,"kp":["储能规模[亚利桑那州Pediment电池项目]: 250 MW/1,000 MWh"]},{"i":2492,"as":"澳大利亚开发商BLT Energy的Red Gully 800 MW/4,800 MWh电池储能系统（BESS）项目已获得开发批准。该项目是西澳拟建的最大公用事业规模BESS，一期将向西南互联系统输送400 MW功率及2,400 MWh储能容量。项目预计于2027年完工，将补充西澳的清洁能源链-北网输电网络升级计划。目前西澳还有多个大型运营中的BESS项目，包括Neoen的Collie电池项目等。","scd":null,"kp":["储能规模[澳大利亚Red Gully项目]: 800 MW/4,800 MWh","储能规模[Red Gully项目一期]: 400 MW","储能规模[Collie电池二期]: 341 MW","储能规模[Kwinana BESS二期]: 200 MW/800 MWh","储能规模[Collie BESS]: 500 MW/2,400 MWh"]},{"i":2493,"as":"哥本哈根能源公司与Opoura合作建设的76 MWh Ringsted电池储能系统（BESS）在丹麦正式投入运营。该项目于6月9日完成调试，此前已通过丹麦输电系统运营商Energinet的辅助服务预认证。Opoura为该项目提供了电网合规研究、控制系统、SCADA系统、辅助服务及参与能源市场交易的软件。Opoura提供的从底层到管理的端到端连贯解决方案受到高度评价。","scd":null,"kp":["储能规模[丹麦Ringsted BESS]: 76 MWh"]},{"i":2494,"as":"今年“618”电商大促被业界视为首个“AI原生”大促，人工智能全面渗透选品、营销、客服、物流、售后等全链路环节，重构了电商行业底层逻辑。面向消费者，AI智能导购取代传统搜索，实现对话选品、自动核算优惠与AI试穿等功能；面向商家，AI包揽智能投流、文案生成、库存预判与智能客服，大幅降低运营成本。在供应链端，AI基于消费数据预判销量并优化物流调配。大模型与电商平台的打通，使AI正成为购物的第一入口。","scd":null,"kp":["成交额增速[接入JoyInside的AI家电家居新品]: 环比增长200%","[AI赋能电商大促]: AI作为首个原生动力渗透选品、营销、客服、物流、售后全链路重构底层逻辑"]},{"i":2495,"as":"我国物流网络建设正从规模扩张转向质效提升，深度嵌入实体经济产业链。目前已基本建成物流基础设施主骨架，布局229个国家物流枢纽（181个投入运营）和105个国家骨干冷链物流基地，“6轴7廊8通道”主骨架建成率超90%。物流网已成为国家级新型基础设施。未来五年将重点推动枢纽扩容升级、铁路专用线入园进港，打通多式联运“最后一公里”堵点，向数据互通、组织协同的现代智能化模式转型，全面跃升综合效能。","scd":null,"kp":["配送耗时[林芝松茸无人机低空配送]: 20分钟","国家物流枢纽[全国布局]: 229个（其中181个投入运营）","国家骨干冷链物流基地[建成]: 105个","建成率[综合立体交通主骨架]: 突破90%","增速[部分枢纽货物吞吐量]: 年均超10%"]},{"i":2496,"as":"交通运输部等十一部门联合印发《推动新能源重卡规模化应用实施方案》，明确提出到2030年新能源重卡渗透率达40%、保有量突破160万辆的国家级目标。该方案填补了重卡高耗能领域宏观规划的空白，共提出21条措施，重点包括围绕国家高速路网建设3万公里零碳公路运输通道，并要求同步规划、建设充换电、加换氢站、储能等补能设施。随着目标推进，重卡用能结构将加速向多元化转型，动力电池与氢能产业链迎来重大发展机遇。","scd":null,"kp":["渗透率[新能源重卡2030年目标]: 40%","保有量[新能源重卡2030年目标]: 突破160万辆","保有量占比[新能源重卡2030年目标]: 20%左右","累计销量[新能源重卡(2025年1月至2026年5月)]: 33.7万辆","渗透率[新能源重卡(2025年1月至2026年5月)]: 超过29.5%"]},{"i":2497,"as":"中国新能源汽车渗透率持续攀升，今年5月新车销量占比达56.9%，销量完成149.6万辆，同比增长14.4%。增长主要得益于出行成本优势、技术迭代和智能化体验。消费者算账显示，新能源车每月通勤电费远低于燃油车油费。同时，智能座舱与智能驾驶（如华为乾崑智驾）成为吸引消费者的关键变量，国产AI大模型加速上车，使汽车交互告别单一指令模式。消费者关注点已从动力参数全面转向智能化体验。","scd":null,"kp":["新能源汽车渗透率[中国5月新车销量]: 56.9%","新能源汽车产销[中国5月]: 产量155.4万辆，销量149.6万辆","产销同比增长[中国5月新能源汽车]: 产销分别增长22.4%和14.4%","通勤成本[纯电动车替代燃油车]: 每月油费超1200元降至电费不到200元"]},{"i":2498,"as":"国家数据局印发行动方案，提出到2028年底建成覆盖重点领域的行业高质量数据集。截至2026年一季度，全国已建成超11.6万个高质量数据集，总体量超960PB。中国AI的竞争重心已从比拼模型参数和通用对话能力，转向扎进工业制造、智慧能源、智能驾驶等实体产业的专业化应用落地。政策强调构建“场景牵引数据、数据驱动模型、模型赋能应用、应用创造价值”的数据飞轮，标志着AI产业化进入以解决实际产业问题为导向的下半场。","scd":null,"kp":["高质量数据集建设[国家数据局行动实施方案目标]: 2028年底建成覆盖重点领域并经应用验证的行业数据集","高质量数据集规模[全国2026年第一季度]: 已建成超11.6万个，总体量超960PB","日均词元调用量[全国高质量数据集]: 突破140万亿"]},{"i":2499,"as":"中国正加紧筹建世界人工智能合作组织，以多边主义和开放包容理念推动AI全球治理。中国已发布《全球人工智能治理倡议》，确立智能向善、安全可控、普惠公平的导向，并依托联合国、上合组织、金砖机制深化国际务实合作。中国提出《人工智能能力建设普惠计划》，开展国际培训以弥合全球智能鸿沟，并连续8年举办世界人工智能大会。今年7月将在上海举办2026世界人工智能大会暨人工智能全球治理高级别会议，进一步加强合作与风险管控。","scd":null,"kp":[]},{"i":2500,"as":"高铁在夜间停运主要是严格执行每日不少于240分钟的“天窗”检修制度。在此期间，全线禁止列车通行，工作人员对钢轨、接触网及通信信号等进行调试检测。与普速列车采用的“V型天窗”（仅封闭单线）不同，高铁时速普遍在250至350公里，一旦邻线有车通过将产生强烈气流扰动与声波冲击，严重威胁作业人员安全。因此，高铁必须采用上下行线路同步封闭的“垂直矩形天窗”，确保检修在零干扰、零风险环境下进行。","scd":null,"kp":["固定天窗时间[全国高铁网络每日检修]: 不少于240分钟","天窗作业时段[高铁夜间检修]: 凌晨0时至清晨6时","最高时速[中国高铁]: 可达350公里"]},{"i":2501,"as":"Eos公司通过其与多方共同创建的平台，在德克萨斯州获得了一笔400兆瓦时（MWh）的电池储能系统（BESS）订单。该订单标志着Eos在德州储能市场的进一步拓展。这笔订单将用于部署电网级电池储能项目，以支持当地电力基础设施的灵活性和可靠性。","scd":null,"kp":["BESS订单容量[Eos于德克萨斯州]: 400兆瓦时"]},{"i":2502,"as":"日本关西电力公司（Kansai Electric）正式推出了一只规模达4000万美元的电池储能基金。该基金旨在投资和开发电池储能系统，以增强电网的灵活性和稳定性，支持可再生能源的并网消纳，并通过储能技术的商业化应用创造投资回报。","scd":null,"kp":["电池存储基金规模[日本关西电力推出]: 4000万美元"]},{"i":2503,"as":"本周国内多晶硅市场成交活跃度偏低，价格重心继续下移。N型复投料成交均价为3.34万元/吨，N型颗粒硅均价为3.30万元/吨，环比均小幅下滑。市场弱势主要受高库存压力和下游谨慎采购影响。供应端因部分头部企业复产及年中出货意愿增强，预计6月国内多晶硅产量将达9.3万吨左右；而需求端预计在8.8万吨左右。供需双增但供应过剩导致6月市场维持累库状态，短期内市场预计延续偏弱运行态势。","scd":null,"kp":["成交均价[n型复投料/棒状硅]: 3.34万元/吨","成交均价[n型颗粒硅]: 3.30万元/吨","价格环比变化[本周多晶硅]: n型复投料下滑1.47%，n型颗粒硅下滑1.49%"]},{"i":2504,"as":"大唐四川甘孜稻城噶通一期200MW光伏发电项目环评及备案信息公示。该项目占地超371万平方米，采用草光互补模式，总装机200MW。技术配置上，拟采用N型630Wp双玻双面单晶硅组件、300kW组串式逆变器（倾角26°固定运行），并配建20MW/40MWh储能系统。建设主体为川西（稻城）新能源发电有限公司，由大唐集团和甘孜州国资委间接持股，项目已于2025年底完成省级备案。","scd":null,"kp":["总装机规模[甘孜稻城噶通一期光伏项目]: 200MW","储能容量配置[甘孜稻城噶通一期光伏项目]: 20MW/40MWh","光伏组件规格[甘孜稻城噶通一期光伏项目]: N型630Wp双玻双面单晶硅组件","逆变器规格[甘孜稻城噶通一期光伏项目]: 300kW组串式逆变器","安装倾角[光伏组件固定式运行]: 26°"]},{"i":2505,"as":"山东淄博发生一起光伏设备财产纠纷案。原告光伏企业在客户土地上搭建的光伏项目因违规被拆除，留存的配套设备被被告邹某擅自扣留，原告遂索赔4万元。经法院查明，此案并非恶意侵权，而是因居间费认知偏差引发的误会。邹某曾通过中间人促成该项目落地，因迟迟未收到自认应得的介绍费，便私自留存设备作为筹码。承办法官经双向疏导、以案释法，厘清了双方无合法劳务约定，最终促成精细化调解。","scd":null,"kp":["设备贬值与报废风险[光伏配套设备露天存放]: 极易损毁"]},{"i":2506,"as":"中国华电集团董事长叶向东在廊坊拜会河北省省长王正谱，双方就深化央地合作达成共识。中国华电将把服务河北高质量发展、助力新型能源强省建设作为重要责任，重点推动双方在清洁能源开发、装备制造、电力消纳，以及绿电直连、算电协同等新模式新业态方面的合作。河北省则希望中国华电加大在新能源、新材料、装备制造等领域的投资力度。双方旨在形成多元互补的能源产业发展格局，共同助力京津冀协同发展。","scd":null,"kp":["合作发展方向[中国华电与河北省]: 清洁能源开发、绿电直连、算电协同等新模式新业态"]},{"i":2507,"as":"国家林草局等四部门联合印发《“三北”工程建设管理办法（试行）》。文件突出防沙治沙主攻方向，明确要求按“先设计、再审批、后施工”原则推进。文件明确支持在做好新能源消纳的基础上，探索实施“光伏+治沙”以及“以路治沙”等治理模式。同时，鼓励采取“以工代赈”“以奖代补”等方式，引导企业、集体和农牧民通过承包、入股、租赁及投工投劳等形式参与工程建设，以筑牢北方生态安全屏障。","scd":null,"kp":[]},{"i":2508,"as":"河南省印发《交通运输结构调整专项行动方案(2026—2028年)》，推进运输绿色转型，力争2028年公路货运量占比降至86.1%，新能源运输量占比达25%以上。方案重点推进“公转水”“公转铁”及多式联运，加快实施多条国家高等级内河航道提级达标工程。同时，方案明确提出利用公路服务区等路域资源规模化建设分布式光伏电站，并在主干航道沿线建设光伏、风电等新能源发电设施，逐步构建交通运输领域的清洁能源供应体系。","scd":null,"kp":["公路货运量占比[2028年目标]: 86.1%左右（较2025年降低2.4个百分点）","新能源运输量占比[2028年目标]: 25%以上（较2025年提高15.4个百分点）","水路货运量占比[2028年目标]: 9.1%左右（较2025年提高2.1个百分点）","铁路货运量占比[2028年目标]: 4.8%左右（较2025年提高0.3个百分点）","[光伏应用]: 规模化利用公路服务区等路域资源建设分布式光伏电站"]},{"i":2509,"as":"龙芯中科联合砺算科技与挚科正式发布“乾启 ZK3C60S-W”纯血国产工作站。该产品实现全栈国产化，搭载龙芯3C6000处理器、砺算LX PRO 24G显卡及麒麟V11操作系统。硬件方面，LX PRO显卡配备24GB GDDR6显存与PCIe 4.0 x16接口，支持四路8K 60Hz输出；软件全面兼容DirectX 12、Vulkan 1.3等主流接口，适配CAD、BIM及本地AI推理。该工作站面向高端制造、数字孪生等专业领域，有效解决国产化转型中的软硬件兼容与部署难题。","scd":null,"kp":["处理器[乾启ZK3C60S-W工作站]: 龙芯3C6000（基于完全自主设计的龙架构）","显卡[乾启ZK3C60S-W工作站]: 砺算LX PRO 24G专业图形显卡","显存[砺算LX PRO显卡]: 24GB GDDR6","接口[砺算LX PRO显卡]: PCIe 4.0 x 16","操作系统[乾启ZK3C60S-W工作站]: 麒麟V11"]},{"i":2510,"as":"","scd":null,"kp":[]},{"i":2511,"as":"","scd":null,"kp":[]},{"i":2512,"as":"","scd":null,"kp":[]},{"i":2513,"as":"大众ID.3 Neo GTI路试车曝光，采用纯电掀背设计与后驱单电机动力，最高功率240kW（322马力）。内饰配备10.25英寸数字仪表盘、12.9英寸中控屏及更多实体按键，并加入GTI专属徽标与运动座椅。新车预计2026年底前亮相，起售价低于3.9万欧元。","scd":null,"kp":["最高功率[大众ID.3 Neo GTI单电机]: 240kW（322马力）","数字仪表盘[大众ID.3 Neo GTI]: 10.25英寸","中控屏[大众ID.3 Neo GTI]: 12.9英寸","起售价[大众ID.3 Neo GTI]: 预计低于3.9万欧元（约30.5万元人民币）","驱动形式[大众ID.3 Neo GTI]: 后驱"]},{"i":2514,"as":"","scd":null,"kp":[]},{"i":2515,"as":"Stellantis集团确认正与两家潜在伙伴商谈玛莎拉蒂合作事宜，明确表示不会出售该品牌。玛莎拉蒂未来将增加两款E级大型车，GranTurizio等三款现有车型也将迎来中期改款。此前传闻Stellantis曾与华为和江淮汽车讨论新能源汽车合作，或让同款车型在中国为尊界品牌、全球市场为玛莎拉蒂品牌。","scd":null,"kp":[]},{"i":2516,"as":"我国首部L3/L4自动驾驶强制性国标《智能网联汽车自动驾驶系统安全要求》报批稿已公示，建议2027年7月1日实施。标准适用于M类和N类车辆，要求自动驾驶系统安全水平至少达到“合格且专注驾驶人”水平，引入Safety Case（安全档案）机制，要求企业系统论证安全性并说明能力边界与失效风险控制。","scd":null,"kp":["实施日期[L3/L4自动驾驶强制性国标]: 2027年7月1日","适用范围[L3/L4自动驾驶强制性国标]: 装备L3和/或L4自动驾驶系统的M类（载客）和N类（载货）车辆","[智能网联汽车自动驾驶系统安全要求]: 从推荐性标准升级为我国首部针对L3/L4自动驾驶系统的强制性国家标准"]},{"i":2517,"as":"三星电子半导体LSI事业部确认正在研发新一代移动处理器Exynos 2700，下一代旗舰智能手机将率先采用。业界预计该芯片将应用于明年发布的Galaxy S27系列手机。此外，三星半导体正积极拓展大规模图像传感器和定制化芯片业务以丰富营收。","scd":null,"kp":[]},{"i":2518,"as":"铭瑄联合英特尔推出MS-Challenger MCIO ITX和MS-PC Farm B860I两款采用MCIO接口的ITX主板方案。MCIO接口支持PCIe Gen5/Gen6，具有高密度、布线灵活等优势。前者以2个MCIO接口替代PCIe插槽，支持多种通道拆分模式；后者专为PC集群部署优化，支持4条UDIMM、IPMI管理及处理器与内存转置布局。","scd":null,"kp":["规范定义[MCIO接口]: SFF-TA-1016规范","支持世代[MCIO接口]: PCIe Gen5与未来Gen6","最大链路宽度[MCIO单一接口]: ×8","[MCIO接口优势]: 具有高密度、布线灵活、原生支持线材转接等优势","接口模式[MS-Challenger MCIO ITX主板H810/B860版本]: 双接口合并×16模式"]},{"i":2519,"as":"盖洛普对2.3万名美国劳动者的调查显示，不常使用AI的员工更容易被裁员。在美国科技行业，每月至少用一次AI的员工预计被裁概率为6%，而较少使用的员工概率升至9%。企业招聘和裁员决策中，员工的AI熟练度已成为重要影响因素。尽管公众担忧AI导致失业，但仅1%的被裁员工认为AI是直接原因。","scd":null,"kp":[]},{"i":2520,"as":"宝马将于7月起停产或暂停生产国产纯电动车型iX3、i3和iX1，以集中产能资源为国产新世代车型上市做准备。新世代BMW iX3长轴距版计划于2026年8月下旬预售、第四季度上市，采用全系一口价策略，CLTC续航突破900公里。新世代BMW i3长轴距版基于800V架构，续航突破1000公里，支持400kW直流快充。","scd":null,"kp":["[产线调整]: 国产纯电车型iX1与i3确认7月停产，为国产新世代车型集中产能"]},{"i":2521,"as":"图灵奖得主杨立昆指出当前AI行业面临运营成本高昂的问题，警告OpenAI和Anthropic等公司若不降本增效，AI泡沫很可能破裂。他认为目前低价的AI服务依赖投资人补贴，缺乏可持续商业模式。他批评马斯克的xAI公司人才流失严重，并主张发展基于理解现实世界规律的世界模型，而非单纯的大语言模型。","scd":null,"kp":[]},{"i":2522,"as":"知情人士确认华为乾崑智驾ADS高阶功能包优惠将于2026年7月1日起收窄。华为官方标准定价为3.6万元，叠加车企补贴后目前用户到手价约为1.2万元。7月1日起，功能包价格将恢复至3.5万元，叠加补贴后用户实际购买价格将上涨3000元至1.5万元。","scd":null,"kp":["买断价格[华为乾崑智驾ADS高阶功能包叠加补贴]: 1.2万元","标准定价[华为乾崑ADS高阶功能包官方]: 3.6万元","限时优惠价[华为乾崑ADS高阶功能包]: 3.2万元","恢复价格[华为乾崑ADS Max和Ultra版本7月1日起]: 3.5万元","最终到手价[华为乾崑高阶智驾包自7月1日起叠加补贴]: 1.5万元"]},{"i":2523,"as":"","scd":null,"kp":[]},{"i":2524,"as":"","scd":null,"kp":[]},{"i":2525,"as":"Adobe为其Firefly AI平台推出Creative Skills功能并引入AI智能体。用户可通过自然语言对话生成Logo、配色方案等，系统会主动反问以明确需求，并提供控制面板微调细节。Photoshop、Premiere Pro等Creative Cloud软件已引入智能体侧边栏，支持通过指令整理素材、自动重命名文件等操作。","scd":null,"kp":["人机交互方式[Adobe Firefly AI平台]: 支持自然语言对话与主动反问","精细控制能力[Firefly专用控制面板]: 允许微调字体、镜头运动方式、品牌强调色等细节","功能特性[Creative Cloud软件引入的智能体]: 输入指令即可整理素材、自动重命名文件、更新设计稿"]},{"i":2526,"as":"固态电池制造商QuantumScape与本田研发部门签署了一项为期多年的研究合作协议，共同推进固态电池技术及相关制造工艺的发展。双方将基于QuantumScape的QS电池平台架构进行进一步研发。QuantumScape此前因与大众汽车的固态电池合作而广为人知。","scd":null,"kp":["合作目标[QuantumScape与本田]: 推进固态电池的研发","技术平台[双方联合开发]: QS固态电池架构平台"]},{"i":2527,"as":"松下宣布将重新定义其能源存储业务，扩建堪萨斯州的电动汽车电池工厂，使其能够为数据中心生产先进的能源存储系统。这一战略调整由AI基础设施、云计算等推动的数据中心快速扩张需求引发。松下此举旨在应对全球能源需求变化，巩固其在能源领域的领先地位。","scd":null,"kp":["业务拓展方向[松下堪萨斯工厂]: 扩产以为数据中心生产储能系统","增长驱动因素[先进能源存储系统需求]: AI基础设施、云计算和超大规模运算的快速扩张"]},{"i":2528,"as":"","scd":null,"kp":[]},{"i":2529,"as":"","scd":null,"kp":[]},{"i":2530,"as":"Telo确认其微型MT1电动卡车支持持续400千瓦的快充，该充电速率媲美售价高出两三倍的豪华电动汽车。首席技术官Forrest North透露，MT1采用双800V/400V分离式电池架构，由两个400V电池包组成，可在任何快充桩上实现性能最大化，而不仅限于最新高压站点。此外，Telo已与密歇根州一级汽车供应商Schwab Industries达成白车身制造合作。MT1计划于2026年底进行首批约500辆的客户交付。","scd":null,"kp":["持续充电功率[Telo MT1小型电动卡车]: 400 kW","电池架构[Telo电动卡车]: 双800V/400V分离式电池包架构"]},{"i":2531,"as":"玛莎拉蒂宣布更新Folgore纯电系列，通过全新的能量管理算法进行软件校准刷新，使GranTurismo Folgore的WLTP续航里程提升约85公里，达到540公里以上。此次更新涵盖三款车型：GranTurismo、GranCabrio和Grecale Folgore。车辆硬件基本保持不变，GranTurismo Folgore依然保留800伏架构和三电机配置。此次更新背景是玛莎拉蒂在2025年遭遇了交付量暴跌30%至7900辆的销售低谷。","scd":null,"kp":["WLTP续航里程[玛莎拉蒂GranTurismo Folgore]: 540 km","续航提升幅度[新款Folgore EV更新]: 约 85 km","技术升级手段[提升续航里程]: 采用新的能源管理算法"]},{"i":2532,"as":"本田在英国推出了一款名为Super-N的全新纯电动性能掀背车，起售价为18,995英镑（约合25,000美元）。该车是日本N-One E纯电轻自动车的强化版本。Super-N整车极度轻量化，重量刚刚超过2400磅（1097公斤）。本田表示，极低的车重使得该车的驾驶感受堪比传奇的宽体City Turbo II车型。本田英国区负责人Michael Doyle称，这是目前市场上最实惠且最具驾驶乐趣的小型纯电动汽车之一。","scd":null,"kp":["起售价[本田Super-N电动掀背车]: 25,000美元","车辆定位[本田Super-N]: 基于N-One E纯电动K-car的高性能版（电动小钢炮）"]},{"i":2533,"as":"三菱发布了2027款eK Cross EV微型电动车。新车延续20千瓦时电池和47千瓦电机的配置，WLTC续航为180公里。外观取消了与燃油版共享的格栅，采用与车身同色的前脸和更新的内饰技术。新车最大亮点是配备了100伏交流电源插座，最大放电功率可达1500瓦，使其能够充当便携式移动电源，直接利用车辆存储的电能。","scd":null,"kp":["供电功率[三菱eK Cross EV车载交流插座]: 1500 W","电池容量[三菱eK Cross EV]: 20 kWh","电机功率[三菱eK Cross EV]: 47 kW","电机扭矩[三菱eK Cross EV]: 195 Nm","WLTC续航里程[三菱eK Cross EV]: 180 km"]},{"i":2534,"as":"本期Wheel-E播客聚焦电动自行车及非传统电动交通工具的最新动态。核心议题包括：多个高端品牌推出新型电动自行车车型；博世正式进军花鼓电机市场；Vinfast在两轮电动车领域表现优异；以及乌克兰正大力推广普及电动摩托车。该播客每两周在各大社交媒体及音频平台通过视频直播或音频录播形式更新。","scd":null,"kp":["技术布局[Bosch博世]: 进入中置电机/轮毂电机领域"]},{"i":2535,"as":"哥伦比亚宣布建设一条全长750英里的Ruta-E电动卡车走廊，连接首都波哥大和卡塔赫纳。该项目将建设配套充电基础设施，以支持到2032年哥伦比亚路网上增加的1000多辆纯电动商用车。在拉丁美洲，由于传统加油站分布较稀疏且可靠性相对较低，而电力网络日益普及，这种环境使得电动车队运营具备独特的可行性，进而缓解续航焦虑。","scd":null,"kp":["走廊总里程[哥伦比亚Ruta-E电动卡车走廊]: 750英里","基础设施建设目标[波哥大和卡塔赫纳沿线]: 建设充电基础设施以支持到2032年上路超1000辆商用纯电动汽车"]},{"i":2536,"as":"Women in Solar+ Europe (WiSEu) 指出，随着光伏产业规模扩大及相互连接日益紧密，传统的领导力模型正难以应对由复杂性、相互连接的系统、快速技术变革和人工智能塑造的世界。为此，即将在Intersolar Europe上举行首届Solar+ Leaders研讨会，主题为“重塑AI时代的领导力：不能用昨天的 playbook 领导明天”，旨在构建新的领导力生态系统，解决能源转型过程中的非技术性领导力挑战。","scd":null,"kp":[]},{"i":2537,"as":"根据DNV公司Solcast的最新分析，正在发展并预计在2026年增强的厄尔尼诺现象将重塑全球太阳能资源分布。基于对以往强厄尔尼诺事件的分析，大气环流变化将重新分配云量和降雨。具体影响表现为：印度、澳大利亚东部、非洲部分地区和中美洲的太阳辐射量将增加；而南美洲和东亚地区的太阳辐射量将出现损失，呈现明显的区域差异。","scd":null,"kp":["太阳辐照度模式[厄尔尼诺现象发展至2026年]: 预计印度、澳大利亚东部、非洲及中美洲部分地区增加，南美洲和东亚减少"]},{"i":2538,"as":"据中国有色金属工业协会硅业分会报告，多晶硅价格连续第三周下跌。此次价格下滑归因于持续的库存压力以及6月份部分制造商复产并提高产量，加剧了供应过剩预期。具体数据显示，N型复投多晶硅平均价格降至每吨33,400元人民币，环比下跌1.47%；N型颗粒硅平均价格降至每吨33,000元人民币，环比下跌1.49%。为降低库存水平，部分多晶硅制造商已主动降价。","scd":null,"kp":["多晶硅价格[6月市场库存压力及产出恢复]: 连续第三周下跌"]},{"i":2539,"as":"Search4Solar首席执行官Bart Wansink表示，过去两年由严重产能过剩主导的欧洲太阳能组件市场正在发生变化，持续降价和“持币待购”策略的时代即将结束。目前欧洲市场的库存趋于精简，生产更具纪律性，采购行为也在发生转变。Wansink指出，未来市场将更加平衡，太阳能项目采购将不再单纯追求价格探底，交货时间点和供应安全性将变得比进一步的降价更重要。","scd":null,"kp":["市场库存与供应状态[欧洲太阳能组件市场]: 正在摆脱极端过剩，从持续降价转向供应安全和时机平衡"]},{"i":2540,"as":"华为数字光伏发布FusionSolar9.0解决方案，旨在降低大型光伏电站全生命周期度电成本（LCOE）。华为张兴治指出，公用事业规模光伏面临四大挑战：需考虑20年生命周期而非仅初始投资回报率；大规模新能源接入对电网稳定运行的挑战；电站规模扩大导致传统人工运维难以胜任，必须转向数字化方案；以及面临的第四大挑战（原文截断）。该方案致力于通过提升发电量和数字化运维解决上述行业痛点。","scd":null,"kp":["生命周期评估[大型光伏电站投资回报]: 需基于20年生命周期而非仅考虑初始资本支出(CAPEX)","解决方案[华为FusionSolar9.0公用事业规模光伏]: 提升全生命周期发电量并降低LCOE"]},{"i":2541,"as":"全球光伏市场报告显示，M10、210R和G12硅片的离岸中国价格保持稳定，分别为0.138美元/片、0.147美元/片和0.169美元/片。硅片市场基本面持续呈现看跌情绪、需求疲软和库存积压特征。尽管面临需求疲软与库存压力，根据制造商的排产计划，5月份硅片实际产量接近50吉瓦，预计6月份产量将进一步上升至约55吉瓦。","scd":null,"kp":["硅片价格(FOB中国)[M10规格]: 0.138美元/片","硅片价格(FOB中国)[210R规格]: 0.147美元/片","硅片价格(FOB中国)[G12规格]: 0.169美元/片"]},{"i":2542,"as":"弗劳恩霍夫机床与成形技术研究所（IWU）推出了一款名为ESiP（生产中的储能系统）的分析仪工具。该工具专为制造企业的能源管理设计，旨在帮助工厂更好地整合可再生能源并降低峰值电网负荷。在实际公用事业和工业应用验证中，ESiP分析仪已取得显著成效，能够使工厂消耗掉近一半的自发自用电力，从而大幅提升工厂层面的能源利用效率。","scd":null,"kp":["自发电利用率[工厂Fraunhofer IWU ESiP分析仪]: 接近一半"]},{"i":2543,"as":"晶科能源宣布其钙钛矿-硅串联太阳能电池的转换效率达到34.82%，打破了其此前34.76%的纪录。该结果已获得中国科学院上海微系统与信息技术研究所的权威认证。这一效率突破主要归功于晶科能源在多项核心技术上的持续创新。该成果在SNEC 2026展会上进行了展出，展现了其在光伏电池技术领域的领先实力。","scd":null,"kp":["光电转换效率[晶科能源钙钛矿-硅串联太阳能电池]: 34.82%"]},{"i":2544,"as":"国际能源署（IEA）最新《全球氢能评论》指出，2025年全球氢气需求超过1亿吨，低排放氢气产量增长20%至近100万吨。中东冲突促使各国重新关注氢及氢基燃料在强化长期能源安全方面的作用，但目前低排放氢的规模远不足以应对即时需求，冲突甚至扰乱了氢基产品的全球生产与贸易。报告结论表明，低排放氢的发展现状距离2030年的既定目标依然越来越遥远。","scd":null,"kp":["全球氢气需求[2025年]: 超过1亿吨","低排放氢气产量[2025年]: 增长20%至近100万吨"]},{"i":2545,"as":"美国化工公司SABIC推出两款新型热塑性树脂NORYL V0150TW和V0150IR2，专为太阳能微型逆变器、光伏追踪器箱体和接线盒设计。该材料旨在替代金属与传统聚合物，使制造商能够从超声波焊接或胶粘转向激光焊接。这一工艺转变消除了依赖固化的粘合材料，缩短了生产周期并降低了整体组装成本。这些新型材料目前在纽约州生产。","scd":null,"kp":["热塑性树脂材料[SABIC光伏微型逆变器/接线盒等组件]: NORYL V0150TW和V0150IR2（旨在替代金属和传统聚合物，实现激光焊接并降低成本）"]},{"i":2546,"as":"美国初创科技公司Panthalassa正在打造利用波浪能发电的自航式海上浮动数据中心，以解决数据中心面临的电力供应与硬件散热双重挑战。该公司近期完成了1.4亿美元的B轮融资。这笔资金将用于在俄勒冈州波特兰市附近建立组装工厂，并加速今年晚些时候在北太平洋的试点部署。CEO指出，深海具有数十太瓦的新发电潜力，是突破陆地算力基础设施瓶颈的关键。","scd":null,"kp":["项目融资[Panthalassa浮动数据中心]: 1.4亿美元B轮","潜在新增产能[地球三大能源(太阳能/核能/海洋)]: 数十太瓦"]},{"i":2547,"as":"","scd":null,"kp":[]},{"i":2548,"as":"德国罗斯托克大学与亥姆霍兹德累斯顿罗森多夫中心（HZDR）联合启动了耗资数百万美元的核聚变研究中心——高能量密度倡议（HEDI）。该中心致力于探索存在于恒星和巨行星深处的极端物质状态，深入研究极端条件下物质的物理变化。此项计划得到了德国联邦研究、技术与空间部以及多位政界、学术界和工业界人士的重点关注与支持。","scd":null,"kp":["[高能量密度倡议(HEDI)]: 探索恒星和巨行星内部存在的极端物质状态"]},{"i":2549,"as":"NASA喷气推进实验室（JPL）研发出一款名为ERNEST的四轮原型探测车，专为月球和火星的高速长距离极端地形自主探索设计。该车长4英尺，在科罗拉多沙漠实地测试中，仅凭极少的人工干预，在37小时内成功行驶了16英里。此次测试旨在优化探测车的移动硬件和自主导航软件，克服过去三十年“摇臂转向架”悬挂系统在极端距离、地形和光照条件下的局限性。","scd":null,"kp":["行驶距离[ERNEST原型车(科罗拉多沙漠测试)]: 16英里","测试时长[ERNEST原型车(科罗拉多沙漠测试)]: 37小时","尺寸[ERNEST原型车]: 4英尺长","移动硬件和自主软件[极端地形漫游车]: 专为高速、长距离自主探索及极端斜坡地形导航优化"]},{"i":2550,"as":"波音公司的工程师在Q4S任务有效载荷的地面测试中，成功演示了关键量子协议。Q4S任务计划于2027年发射。未来量子网络需要高效的信息路由，虽然光纤电缆已用于区域量子网络，但随着网络规模扩大，传输损耗显著增加。在数百英里的数据传输中，自由空间光信道比光纤更高效。波音资助的Q4S任务对于实现未来的天基量子网络至关重要。","scd":null,"kp":["发射时间[Q4S任务(量子协议载荷)]: 2027年"]},{"i":2551,"as":"霍尼韦尔宣布其模块化精炼技术和自动化系统将用于Acelen Renewables在巴西巴伊亚的可再生燃料项目，生产可持续航空燃料（SAF）和可再生柴油。霍尼韦尔的模块化Ecofining工艺技术、专用泵、压缩机及集成控制与安全系统将提高该项目的建设和运营效率。行业预测显示，未来十年对SAF的需求将达到近50万桶/日。","scd":null,"kp":["[模块化Ecofining工艺技术]: 利用废油和脂肪生产可持续航空燃料(SAF)和可再生柴油"]},{"i":2552,"as":"香港大学的研究人员开发出一种新型类脑电子硬件，能够在接近绝对零度的极寒环境中运行。这种可编程神经形态平台的功能类似于脑细胞，旨在解决量子计算面临的最大挑战之一，并为未来的深空探索系统提供新可能。这项突破表明，单晶体管在深冷环境下可发挥类似脑细胞的作用。","scd":null,"kp":["工作温度[类脑仿生电子硬件(单晶体管)]: 接近绝对零度"]},{"i":2553,"as":"科学家在一项由联邦资助的小鼠研究中发现，某些遗传的表观遗传标记（影响基因活性但不改变DNA代码的化学修饰）可以跨代传递。这种遗传传递方式不遵循经典的孟德尔遗传定律。研究估计，在他们检查的表观遗传遗传模式中，约有7%超出了传统的孟德尔遗传范畴，揭示了超越DNA序列的遗传新层面。","scd":null,"kp":[]},{"i":2554,"as":"一项针对海葵的新研究表明，DNA甲基化可能具有与科学家之前假设完全不同的进化目的。在动物界中，附着在DNA上的化学标记（如DNA甲基化）有助于控制基因指令的使用。研究发现，去除海葵的大部分DNA甲基化对其正常发育几乎没有影响，反而暴露了隐藏在其内部的威胁，挑战了科学界对DNA甲基化的传统认知。","scd":null,"kp":[]},{"i":2555,"as":"一种新型长读长DNA测试能够提供比现有标准诊断方法更详细的基因组视图，帮助医生更精准地识别罕见遗传疾病。该测试可替代多达15种现有诊断程序，大幅提高诊断速度和效率。拉德堡德大学医学中心的研究人员在《新英格兰医学杂志》上建议，将该方法作为全球罕见遗传病诊断的首选标准测试。","scd":null,"kp":["替代能力[新型长读长DNA测试]: 可替代多达15种现有诊断程序"]},{"i":2556,"as":"耶鲁大学医学院的研究人员对眼睛处理视觉信息的方式有了新发现。视觉系统通过并行处理快速分离颜色、对比度和运动等特征并独立处理。科学界长期认为这种分离始于视网膜并在视觉系统中保持独立。但新研究表明，这些视觉通路之间的相互联系比以前认为的更紧密，视网膜视觉通路之间存在意想不到的交流。","scd":null,"kp":[]},{"i":2557,"as":"朴茨茅斯大学的一项新研究表明，古老黑洞可能从大爆炸之前的宇宙时代幸存下来。这些被称为“宇宙化石”的假想遗迹可能在剧烈的宇宙转变中幸存并依然存在。该研究挑战了宇宙起源于单一宇宙大爆炸的传统观点，探索了宇宙从收缩逆转为膨胀的“反弹”场景。如果存在，这些古老黑洞或有助于揭示暗物质身份。","scd":null,"kp":[]},{"i":2558,"as":"伯明翰大学的科学家利用超冷原子构建了一个量子“迷你宇宙”，证明时间可以从系统内部的熵变化中产生。发表在《物理评论研究》上的研究证明，不依赖外部时钟也能追踪时间的流逝。该模型引入了一种从研究系统行为中自然产生的时间形式，为时间并非宇宙基本属性（如Wheeler-DeWitt方程所暗示）的物理理论提供了实验见解。","scd":null,"kp":["[超冷原子量子“微型宇宙”]: 证明时间可以从系统内部的熵变化中产生，无需依赖外部即可追踪时间流逝"]},{"i":2559,"as":"耶鲁大学的研究人员开发了一种新型脑机接口（BCI），允许人们仅通过大脑活动玩电子游戏。该团队利用实时功能磁共振成像证明，用户可以仅凭思想高效控制计算机。发表在《自然神经科学》上的研究揭示，大脑活动遵循已建立的神经通路。当系统设计成与大脑自然布线协同工作时，学习使用BCI会变得更容易。","scd":null,"kp":["交互方式[新型脑机接口(耶鲁大学)]: 仅凭大脑活动控制电子游戏","技术基础[新型脑机接口(耶鲁大学)]: 使用实时功能性磁共振成像"]},{"i":2560,"as":"加州大学圣地亚哥分校医学院的研究表明，常见的痴呆症风险因素对女性大脑的影响远超以往认知。发表在《性别差异生物学》上的研究分析了超过17000名中老年人的数据，发现女性不仅更常经历某些痴呆风险因素，而且这些因素对女性认知健康的负面影响也更大。部分风险因素对女性认知能力的不成比例的影响十分显著。","scd":null,"kp":[]},{"i":2561,"as":"德克萨斯大学达拉斯分校大脑健康中心的大型研究挑战了关于衰老的传统假设。发表在《科学报告》上的研究指出，大脑的敏锐度并非注定随时间衰退，人们终身都可以增强认知能力。研究人员在三年内追踪了3966名19至94岁的成年人。结果表明，与科学家过去的认知相比，衰老的大脑具备更强的生长和改善能力。","scd":null,"kp":[]},{"i":2562,"as":"在2026年内分泌学会年会上公布的研究表明，服用索马鲁肽的2型糖尿病患者在实现更大程度减重的同时，骨折风险也低于使用其他减重药物的患者。与其他抗肥胖治疗相比，索马鲁肽与骨折风险降低15%相关，显示出潜在的骨骼健康益处。索马鲁肽属于胰高血糖素样肽类药物，研究人员指出需要前瞻性研究来验证这些结果。","scd":null,"kp":[]},{"i":2563,"as":"","scd":null,"kp":[]},{"i":2564,"as":"","scd":null,"kp":[]},{"i":2565,"as":"","scd":null,"kp":[]},{"i":2566,"as":"由于收入预测下降加剧了市场对人工智能的担忧，埃森哲股价下跌了18%。","scd":null,"kp":["股价跌幅[埃森哲(受收入预测下降及AI担忧影响)]: 18%"]},{"i":2567,"as":"","scd":null,"kp":[]},{"i":2568,"as":"参议员伯尼·桑德斯发布了一项由人工智能资助主权财富基金的提案。","scd":null,"kp":[]},{"i":2569,"as":"迈阿密的AI初创公司Subquadratic宣布突破了阻碍大语言模型近十年的数学瓶颈。第三方独立评估结果表明，该公司开发的新型LLM（SubQ）速度更快、成本更低且能耗远低于市场同类模型。此外，SubQ能够一次性处理比大多数其他模型多12倍的文本，从而执行更为复杂的任务。","scd":null,"kp":["[大语言模型数学瓶颈]: 宣称已解决"]},{"i":2570,"as":"","scd":null,"kp":[]},{"i":2571,"as":"加州大学戴维斯斯分校研究团队为患有ALS的瘫痪患者Casey Harrell植入脑机接口（BCI）。自2023年7月起，该设备帮助他重新获得语音交流、上网及工作能力。团队不断优化设备精度，并增加隐私模式和脏话过滤器等设置，使其成为首位深度使用脑植入物的患者。","scd":null,"kp":["[脑机接口(BCI)]: 实现ALS患者语言表达及网页浏览"]},{"i":2572,"as":"Futureal Energy Partners收购了位于拉脱维亚首都地区的两个独立电池储能项目，总容量为45 MW/120 MWh，这是该公司在波罗的海国家首次直接拥有电池资产。两个项目均已获得电网连接协议和建筑许可，计划于2026年7月开工，11月投入商业运营，将为当地电网提供辅助和平衡服务。","scd":null,"kp":["储能规模[拉脱维亚BESS项目组合]: 45 MW/120 MWh","储能规模[Bolderaja独立设施]: 15 MW/40 MWh","储能规模[Bisuciems独立设施]: 30 MW/80 MWh"]},{"i":2573,"as":"保加利亚光伏系统供应商Solarpro Technology与中国电池制造商宁德时代（CATL）合作，在保加利亚布尔加斯成功将602 MWh的电池储能系统接入电网。这是东欧目前投运的最大储能设施，使保加利亚总储能容量增加10%，将有效促进可再生能源整合并支持国家电力系统稳定运行。","scd":null,"kp":["储能规模[保加利亚Burgas光储项目]: 602 MWh","储能占比[该项目对保加利亚总容量提升]: 10%","系统地位[东欧已投运储能设施]: 最大运行中储能设施"]},{"i":2574,"as":"西班牙萨拉戈萨省正在开发一个名为Pobladura del Valle的混合能源项目，集成33 MW光伏发电、111.8 MWh电池储能和25 MW电解槽（每小时产445千克绿氢）。光伏装机峰值容量41.96 MWp，采用双面组件和单轴跟踪器。储能系统使用磷酸铁锂（LFP）电池，放电功率26.625 MVA。","scd":null,"kp":["装机容量[西班牙Pobladura del Valle光伏发电]: 33 MW","储能容量[匹配电池储能系统]: 111.8 MWh","电解槽装机[绿氢制备系统]: 25 MW","绿氢产能[电解槽每小时生产]: 445 kg/h"]},{"i":2575,"as":"Dynelectric向冰岛的eSAF项目成功交付了首台固体氧化物电解池（SOEC）机组。","scd":null,"kp":["[冰岛eSAF项目]: 交付首台SOEC机组"]},{"i":2576,"as":"1Komma5 Grad启动了一项价值10亿欧元的融资计划，专门用于资助家庭清洁能源项目。该举措旨在推动家庭可再生能源的普及与发展。","scd":null,"kp":["资助规模[1Komma5家庭清洁能源计划]: 10亿欧元"]},{"i":2577,"as":"EnBW在德国南部推出了一座装机容量为5.7 MWp的太阳能发电场，该项目配备了电池储能系统（BESS），旨在提升当地可再生能源的供应能力与电网稳定性。","scd":null,"kp":["装机容量[德国南部光储一体化项目]: 5.7 MWp"]},{"i":2578,"as":"谷歌在搜索引擎中强行加入AI功能引发部分用户反感。当用户搜索“no AI”时，谷歌AI甚至会建议他们使用DuckDuckGo的“无AI搜索”页面。自2026年谷歌I/O大会推出AI优先搜索后，DuckDuckGo美国区应用安装量周环比增长超30%。DuckDuckGo允许用户关闭AI功能，而谷歌暂未提供永久关闭AI概览的选项。","scd":null,"kp":["应用安装量增长[DuckDuckGo美国区]: 周环比平均增长18.1%","峰值增长[DuckDuckGo美国区]: 超过30%"]},{"i":2579,"as":"比利时微电子研究中心（imec）联合台积电和ASML，在300mm晶圆上成功集成采用二维材料沟道的n型和p型互补晶体管，实现50nm接触栅极间距和28nm沟道长度。该器件使用单次EUV光刻，n型采用二硫化钼，p型采用二硒化钨或二硫化钨，开关电流比超10万。这是迄今公开的最小间距二维CMOS集成成果。","scd":null,"kp":["接触栅极间距[2D CMOS集成]: 50nm","晶圆尺寸[2D CMOS集成]: 300mm","沟道长度[单次EUV曝光]: 28nm","开关电流比[集成晶体管]: 超过10万","良率/正常开关比例[集成晶体管]: 94%"]},{"i":2580,"as":"信实工业董事长穆克什·安巴尼宣布公司将大力发展AI技术。信实推出了直接嵌入Jio电信网络的AI通话助手Jio Call Agent（支持“Hey Jio”唤醒）和AI版MyJio应用，并发布了面向智能家居的TeleFrame。安巴尼强调，印度不仅要是AI的采用者，必须成为AI的创造者和全球领导者。","scd":null,"kp":["唤醒词[AI通话助手Jio Call Agent]: Hey Jio","部署方式[AI通话助手Jio Call Agent]: 直接嵌入Jio电信网络","核心功能[AI版MyJio]: 语音指令开通eSIM、选择漫游套餐等操作"]},{"i":2581,"as":"","scd":null,"kp":[]},{"i":2582,"as":"互联网工程任务组（IETF）正式发布RFC 10008标准，推出全新的HTTP QUERY请求方法。该方法专为需要携带请求体的复杂只读查询设计，填补了GET（参数受URL长度限制）和POST（语义无法保证只读）之间的空白，为API设计处理无副作用的复杂数据请求提供了标准化方案。","scd":null,"kp":[]},{"i":2583,"as":"","scd":null,"kp":[]},{"i":2584,"as":"美国造车新势力Rivian因涉嫌夸大初代R1T和R1S车型的自动驾驶能力，遭到消费者集体起诉。原告指控Rivian明知初代车型在硬件上无法实现L3级自动驾驶或真正的脱手驾驶，仍进行虚假宣传。Rivian对此不予置评。初代车型不支持该功能，2024年升级的第二代车型才实现相关能力。","scd":null,"kp":["自动驾驶能力[初代R1T/R1S硬件层面]: 无法实现L3级或真正的脱手驾驶"]},{"i":2585,"as":"在G7峰会期间，加拿大总理马克·卡尼向美国总统特朗普介绍了加拿大对中国电动汽车实施的配额制（设定低于市场3%即49000辆的上限），允许以约6%的低关税进口，获得特朗普认可。此前加拿大对中国电动汽车征收超100%的关税。加拿大工业部长本周也在中国访问，以加强两国汽车产业合作。","scd":null,"kp":["进口配额上限[中国电动汽车]: 49000辆","市场占比上限[中国电动汽车]: 不到3%","优惠关税税率[配额内中国电动汽车]: 约6%","配额有效期[中国电动汽车低关税进口]: 12个月"]},{"i":2586,"as":"为应对AI数据中心激增的电力需求，美国联邦能源监管委员会下令6家区域电网运营商加快大型用电设施接入输电系统的流程。目前数据中心约占美国总用电需求的5%，预计到2035年将增至三倍。新命令要求确保AI数据中心能够及时、有序地并网，以维持美国在AI领域的竞争力。","scd":null,"kp":["覆盖人口[受令加速并网的6家区域电网运营商]: 2亿美国人","管辖人口占比[受令加速并网的6家区域电网运营商]: 约三分之二"]},{"i":2587,"as":"垣信卫星成功实现国内首例无改造存量商用手机直连卫星通话。该系统依托首颗试验星，搭载L波段全数字相控阵天线，研发了两级时频偏补偿和动态自适应编码调节技术，无需对手机进行软硬件改造。实测通话信号满格，质量比肩地面5G。目前垣信千帆星座在轨卫星已达200颗。","scd":null,"kp":["终端改造要求[手机直连卫星通话]: 无需对普通商用手持终端进行任何软硬件改造或升级","通话质量[手机直连卫星通话]: 信号满格，比肩地面5G","天线配置[垣信手机直连卫星系统]: 国内口径与阵元规模领先的L波段全数字相控阵天线","关键技术[突破天地通信上行传输及时频偏瓶颈]: 两级时频偏补偿方案搭配动态自适应编码码率调节技术"]},{"i":2588,"as":"英特尔Arrow Lake-HX Plus系列移动处理器PassMark跑分曝光。酷睿Ultra 7 270HX Plus在核心数少4个的情况下，单核（4908分）和多核（56088分）成绩均超越24核的Ultra 9 275HX。相比同配置的265HX，该处理器凭借互联频率优化和P核睿频提升100 MHz，实现了单核8%、多核15%的性能增长。","scd":null,"kp":["单核成绩[Ultra 7 270HX Plus PassMark测试]: 4908分","多核成绩[Ultra 7 270HX Plus PassMark测试]: 56088分","性能提升[270HX Plus相较于265HX多核性能]: 领先近15%","性能差距[270HX Plus相较于旗舰285HX多核性能]: 低2%","性能优化条件[270HX Plus相较于265HX]: 芯片间互联频率优化及P核睿频提高100 MHz"]},{"i":2589,"as":"","scd":null,"kp":[]},{"i":2590,"as":"","scd":null,"kp":[]},{"i":2591,"as":"英特尔Wildcat Lake架构的入门级处理器酷睿3 304在PassMark数据库中的最新单核跑分达到3982分，追平苹果A18 Pro。该处理器采用1P+4E配置，共5核5线程。数据显示，其多核平均成绩为11543分，仅比6核心的A18 Pro低2.2%，多线程性能处于同一水平。","scd":null,"kp":["单核最好成绩[酷睿3 304 PassMark最新样本]: 3982分","单核性能对比[酷睿3 304相较于苹果A18 Pro平均成绩]: 低7.7%","多核平均成绩[酷睿3 304 PassMark测试]: 11543分","多核性能对比[酷睿3 304相较于苹果A18 Pro平均成绩]: 低2.2%","核心线程配置[酷睿3 304]: 1P+4E，共5个核心5个线程"]},{"i":2592,"as":"基于宇树G1改装的人形机器人Pemba成功登顶海拔6200米的厄瓜多尔钦博拉索火山。该项目旨在利用配备摄像头、AI和卫星通信的移动机器人监测自然保护区。在16小时冲顶阶段，陡峭地形需人工辅助。为应对极寒与散热问题，工程师为其开发了防护服与通风装置。团队计划未来通过强化学习提升其自主能力，最终目标是挑战喜马拉雅山脉。","scd":null,"kp":["登顶海拔[人形机器人Pemba测试极限]: 6200米","机器人基础[人形机器人Pemba改装原型]: 宇树G1","作业能力[配备AI及传感器的人形机器人]: 监测野生动物、非法伐木、偷猎和环境变化"]},{"i":2593,"as":"","scd":null,"kp":[]},{"i":2594,"as":"Meta CEO扎克伯格向员工发送内部备忘录，承诺今年将不再进行裁员。近期Meta围绕AI展开的混乱重组导致裁员约10%，引发员工士气低落，对公司举办的AI黑客松反应冷淡。员工抱怨在裁员后需承担更多基础工作，同时Meta在AI竞赛中尚未推出极具竞争力的新模型。","scd":null,"kp":["裁员比例[Meta上个月围绕AI重组的裁员]: 约占员工总数的10%","裁员计划[Meta今年后续安排]: 承诺今年不会再裁员"]},{"i":2595,"as":"服役近40年的美国总统专机“空军一号”（波音747-200B）正式退役。因波音公司的新一代专机（VC-25B）改装进度严重滞后且成本超支至56亿美元，美国空军宣布将使用卡塔尔捐赠的波音747-8作为过渡机型。该机已由L3Harris完成改装与测试，采用了特朗普参与设计的红白蓝金涂装，内部保留卡塔尔王室的豪华装饰。","scd":null,"kp":["退役总统专机[机型]: 波音747-200B","退役总统专机[服役状态]: 服役近40年（1990年投入使用）","新总统专机[来源及机型]: 卡塔尔捐赠波音747-8","新总统专机[改装承担方]: L3Harris Technologies","新总统专机[技术状态]: 已完成全部改装与飞行测试（2026年夏季起承担职能）"]},{"i":2596,"as":"国家邮政局召开党组会议审议《邮政业发展“十五五”规划》，强调深化互联网、人工智能等新技术与行业的融合。会议明确将加快推进无人车、无人机在邮政快递行业的试点应用，并推广智能派件、智能路由等先进技术。此外，还将加强智能分拣、智能云仓等自动化设施的应用，以高素质人才支撑行业高质量发展。","scd":null,"kp":["行业规划[邮政业“十五五”规划]: 推动大数据、互联网、人工智能深度融合及无人车/无人机试点应用","配送技术[邮政快递行业]: 加快推广应用无人配送技术","自动化设施[邮政快递行业]: 应用智能分拣、智能云仓、智能安检等","绿色低碳技术[邮政快递行业]: 推广应用循环包装、新能源汽车、光伏发电及智能路径优化与装箱算法"]},{"i":2597,"as":"麻省理工学院的一项研究发现，过度依赖聊天机器人会削弱人类独立辨别错误信息的能力。在一项为期四周、基于GPT-4o的实验中，使用AI助手使参与者识别假新闻的准确率提高了21%。然而，随着对AI依赖加深，参与者在无AI辅助时的独立判断能力出现退化。研究表明，AI虽然能在短期内提供帮助，但长期使用会削弱人类的批判性思维。","scd":null,"kp":["研究周期[测试时长]: 持续四周","样本规模[测试人数]: 67人","测试模型[AI助手底座]: 基于GPT-4o并接入Google","假新闻识别率[有无AI辅助]: AI助手（如Claude和ChatGPT）可提高假新闻识别准确率，但过度依赖会削弱独立辨别能力"]},{"i":2598,"as":"","scd":null,"kp":[]},{"i":2599,"as":"欧洲电池协会EUROBAT发布的第四版《电池创新路线图》指出，到2035年，锂离子电池将继续主导市场，占据约80%（约6TWh）的份额。同时，铅酸电池将保持第二大技术的地位，占据约650GWh的稳定市场份额。此外，钠离子电池被视为关键的的新兴技术，预计未来市场份额可达8%。","scd":null,"kp":["主导电池技术[欧洲至2035年]: 锂电池保持主导地位","次要电池技术[欧洲至2035年]: 铅电池预测保持第二强技术地位"]},{"i":2600,"as":"电池材料开发商COnovate任命前Clarios高管Craig Rigby为新任总裁兼首席执行官。Rigby自2022年起担任COnovate董事会成员，接替联合创始人Carol Hirschmugl。Carol Hirschmugl将转任首席技术官，专注于加速公司的材料创新、工艺开发和技术路线图推进。","scd":null,"kp":[]},{"i":2601,"as":"全球铅电池巨头Banner宣布将在未来四年内对其奥地利工厂投资“数千万欧元”，以扩大电池销量。此举是公司“2035议程”的一部分，旨在提高长期盈利能力与效率。此前，Banner在北美和欧洲签署了总价值1.95亿欧元的长期电池供应合同。公司表示，优化工艺和现代技术是其发展战略的核心。","scd":null,"kp":[]},{"i":2602,"as":"电池创新联盟（CBI）在布鲁塞尔发布了欧盟电池行业路线图《维持欧洲的电池强国地位》。行业领袖呼吁，必须将欧洲本土制造的电池作为战略重点，并依托先进的铅电池技术来满足欧盟日益增长的储能需求。该路线图为下一代先进铅电池在欧洲的研发、制造和回收设定了性能目标。","scd":null,"kp":[]},{"i":2603,"as":"桑迪亚国家实验室和太平洋西北国家实验室（PNNL）成为国际电池委员会（BCI）的最新成员。这两家美国国家实验室加入了BCI新设立的公共利益会员类别。桑迪亚国家实验室在国家安全与技术创新领域具有领先地位，其在储能领域的研究将带来前沿的技术能力和解决方案。","scd":null,"kp":["新增成员[BCI机构类型]: 美国桑迪亚国家实验室和太平洋西北国家实验室以新的公共利益成员类别加入"]},{"i":2604,"as":"铅电池和锂电池制造商Exide Technologies宣布，再次荣获全球商业可持续发展评级提供商EcoVadis颁发的2026年“金奖”。此次评估涵盖了环境、劳工与人权、可持续采购及伦理等领域的表现。这一荣誉使Exide在全球超过15万家受评企业中位列前2%，在电池行业中位列前1%。","scd":null,"kp":["可持续性评级[2026年全球商业可持续性评级]: 重新获得EcoVadis金奖"]},{"i":2605,"as":"芬兰科技集团瓦锡兰与德国工程公司RCT Solutions达成协议，为其全球储能业务成立一家持股各半的合资企业。新企业将整合目前作为独立部门运营的瓦锡兰储能业务。该部门在2025年的净销售额为6.94亿美元，利润率为3.3%，全球约有480名员工。后续或有新投资者加入。","scd":null,"kp":["合资企业[能源存储业务]: 瓦锡兰与RCT Solutions成立50:50的全球储能合资企业"]},{"i":2606,"as":"美国固态电池开发商QuantumScape与汽车巨头本田的研发部门达成联合研发协议，旨在加速其“QS”电池平台的发展。该协议包括一项为期多年的计划，重点致力于固态电池的开发及其制造工艺。此前，本田已完成对QuantumScape固态技术的深入技术研究和竞争基准评估。","scd":null,"kp":["研发合作[固态电池技术]: QuantumScape与本田达成联合电池研究协议","研发目标[下一代固态锂金属电池技术]: 结合双方专业知识加速推进‘QS’电池平台"]},{"i":2607,"as":"加拿大新斯科舍省政府宣布修改铅电池行业的监管规定，以促进经济增长。自6月10日起，铅电池制造设施仅需获得工业批准，不再需要强制进行II级环境评估。这一改变使该省的法规与加拿大其他地区保持一致，为铅电池制造业带来了新的经济机遇。","scd":null,"kp":["监管调整[铅电池制造设施]: 仅需工业批准，不再被强制要求进行II类环境评估"]},{"i":2608,"as":"本周供应链热门新闻：一是美国、以色列和伊朗达成的谅解备忘录可能在未来几周内恢复霍尔木兹海峡的准入；二是欧洲在电动汽车领域投资达2000亿欧元；三是雀巢发布了可持续发展计划；四是人工智能创新正在推动全球供应链韧性增强。","scd":null,"kp":["供应链投资[欧洲电动汽车]: 2000亿欧元投资"]},{"i":2609,"as":"铁路制造商阿尔斯通举办供应商日活动与企业社会责任活动，突显战略合作伙伴关系在构建韧性供应链中的关键作用。此次活动汇聚了200多名行业利益相关者，其中120多家为英国和爱尔兰顶级供应商。阿尔斯通强调，其在英国业务的绝大部分支出均面向英国本土企业，支持了数千个就业岗位。","scd":null,"kp":[]},{"i":2610,"as":"人工智能改变了数据中心的电力消耗方式，新型工作负载带来了传统电力系统难以应对的变异性。据S&P Global分析师分析，电池储能系统（BESS）已成为平衡电网需求、应对数据中心快速电力需求波动的关键工具。BESS能够有效管理数据中心内部及更广泛电网的运行挑战，具有不可或缺的作用。","scd":null,"kp":["应用场景[数据中心]: 电池储能系统(BESS)用于管理AI新工作负载引发的快速需求波动"]},{"i":2611,"as":"","scd":null,"kp":[]},{"i":2612,"as":"","scd":null,"kp":[]},{"i":2613,"as":"","scd":null,"kp":[]},{"i":2614,"as":"","scd":null,"kp":[]},{"i":2615,"as":"","scd":null,"kp":[]},{"i":2616,"as":"","scd":null,"kp":[]},{"i":2617,"as":"哈佛大学的研究团队发现，在机器人集群运动中加入少许随机性可以有效防止交通瘫痪，从而在拥挤的环境中大幅提升工作效率。当大量机器人在狭小空间内执行清理或组装等任务时，过度拥挤会导致相互干扰并使进度停滞。由L. Mahadevan教授领导的团队利用混合模型探讨了在有限区域内容纳机器人的最优数量问题，证实了引入随机运动是解决机器人群体拥堵的有效解决方案。","scd":null,"kp":["集群防拥堵策略[机器人群体运动]: 引入少量随机性到机器人运动中以防止死锁并显著提升拥挤环境下的效率"]},{"i":2618,"as":"","scd":null,"kp":[]},{"i":2619,"as":"美国公司Lyten收购Northvolt位于德国石勒苏益格-荷尔斯泰因州海德市的原定电池工厂项目已基本达成协议。Lyten已与德国复兴信贷银行、联邦政府及州政府达成一致，收购价格约为6000万欧元。自2025年8月起，Lyten就明确表达了接管该电池工厂用地的意向。目前各方已就该大型项目的收购价格达成共识，克服了德国繁琐的官僚和法律障碍，接管工作已接近完成。","scd":null,"kp":["收购金额[Lyten收购Northvolt海德站点]: 约6000万欧元"]},{"i":2620,"as":"随着各国在导弹防御、自主武器和太空安全能力方面的防御支出激增，热电池正成为先进军事系统的关键能源。Allied Market Research的最新报告指出，热电池在军事战备和任务执行中不可或缺，其全球军用市场正在经历显著扩张。在各国竞相加强导弹防御系统、扩大军事太空计划并部署复杂的自主武器的背景下，热电池作为专用动力源，正在为世界上最先进的防御系统提供稳定的能量支持。","scd":null,"kp":["应用增长驱动力[热电池]: 导弹防御、自主武器和太空安全领域的支出激增"]},{"i":2621,"as":"纽约初创企业Didero开发了一个基于人工智能的平台，旨在将全球供应链中分散的邮件、PDF、电子表格和供应商消息等碎片化数据点转化为自动化采购工作流。该公司致力于通过AI技术帮助制造商实现直接材料采购的自动化，从而降低人工操作成本并实现运营规模的扩张。该系统灵感来源于丹尼斯·狄德罗的百科全书项目，通过结构化的方式将复杂的实践知识进行系统化整合。","scd":null,"kp":["技术方案[供应链直接采购]: 利用AI平台将分散的数据转化为自动化采购流程"]},{"i":2622,"as":"","scd":null,"kp":[]},{"i":2623,"as":"","scd":null,"kp":[]},{"i":2624,"as":"起亚的电动货车PV5在欧洲和韩国上市后迅速成为其最畅销的电动汽车之一，由于市场需求过于旺盛，起亚被迫对海外市场的供应实行配给制。目前PV5提供乘用和货运等多种配置，并正大举进军日本、澳大利亚和加拿大等全球新市场。在澳大利亚，起亚计划每月销售50辆PV5，但表示如果有足够的供应量，实际销量还能更高。供应短缺已成为满足全球市场庞大需求的主要挑战。","scd":null,"kp":["市场响应[起亚PV5电动货车]: 因需求过大对海外市场实行供应配给"]},{"i":2625,"as":"由Lightship电动房车团队开发的PowerSled是一款全新概念的工作拖车，能够同时解决降低燃油成本和为工作现场提供便携电源的问题。该拖车集成了电动桥、太阳能电池板、电池储能系统和便携式燃气发电机，最大牵引能力达8700磅。PowerSled在拖运设备的同时，不会缩减电动汽车牵引车的续航里程，并且能够直接为施工现场供电，免去了派遣第二辆卡车专程运送电力的麻烦。","scd":null,"kp":["系统集成[PowerSled工作拖车]: 集成电动桥、太阳能电池板、电池储能和便携式发电机以同时降低燃料成本并提供现场电源"]},{"i":2626,"as":"英国能源公司Octopus Energy与中国电池巨头宁德时代（CATL）在伦敦宣布成立一家名为“Swaptopus”的合资企业，计划在英国和欧洲各地为电动卡车建立电池换电网络。该合作将宁德时代的电池技术及其在中国运营换电站的经验，与Octopus Energy在能源供应、交易和软件方面的能力相结合。电动卡车司机只需在换电站内卸下耗尽的电池并换上充满电的电池，即可在几分钟内重新上路。","scd":null,"kp":["商业模式[电动重型卡车]: 八达通与宁德时代成立合资企业，在欧洲和英国建立电池换电网络枢纽"]},{"i":2627,"as":"独立拆解报告显示，中国制造商海钠（Hina）生产的商用钠离子电池在制造质量和内部设计上已能与特斯拉的锂离子电池相媲美。德国亚琛工业大学的研究人员对120个电池单元进行了阻抗光谱非破坏性测试，发现其电池间电阻变化仅为5.3%，表现出与市场上顶尖锂离子电池相当的严格质量控制水平。研究证实了海钠钠离子电池在规模化生产中的一致性及其在多种电流和温度条件下的稳定性能。","scd":null,"kp":["电池制造质量[中国钠离子电池]: 可与特斯拉等顶尖锂离子电池相媲美","一致性控制[钠离子电池电芯]: 120个电芯之间的电阻变化仅为5.3%"]},{"i":2628,"as":"小米重返纽博格林赛道再次创下圈速纪录，并在驾驶座无人的情况下完成了这条世界著名且极具挑战性赛道的首个官方自动驾驶计时圈。纽博格林赛道全长超过12英里，包含多种路面、高低速弯道和起伏丘陵，是车辆性能测试的标杆场地。在各大电动汽车制造商不断竞逐该赛道最快圈速的背景下，小米凭借YU7 GT成为近期最强劲的竞争者之一，展示了其自动驾驶系统的高超性能。","scd":null,"kp":["[纽博格林赛道自动驾驶]: 创下首个官方无人驾驶圈速纪录"]},{"i":2629,"as":"总部位于荷兰的长时储能初创公司Ore Energy宣布与荷兰能源供应商Budget Thuis达成协议，将部署1吉瓦时（GWh）的铁空气电池储能系统。这是迄今为止欧洲大陆规模最大的铁空气电池交易。该项目首阶段将投入400兆瓦时（MWh）的储能容量，计划于2028年交付。这是欧洲能源供应商签署的首个铁空气储能协议，旨在解决风光等可再生能源在天气条件不佳时的长时间电力存储问题。","scd":null,"kp":[]},{"i":2630,"as":"阿特斯阳光电力推出了专为大型公用事业和工商业项目设计的下一代TOPCon 3.0高功率密度光伏组件系列。该系列组件基于大尺寸矩形硅片采用多片切割技术和增强的光利用率，在标准尺寸（2382mm×1134mm×30mm）下实现了更高的功率密度。新组件最大输出功率达670瓦，转换效率高达24.8%，双面率为90%。通过电池多主栅技术和优化的背面配置，该产品可使项目的平准化度电成本（LCOE）降低1.4%。","scd":null,"kp":["转换效率[TOPCon 3.0高功率密度组件]: 24.8%","输出功率[TOPCon 3.0高功率密度组件]: 高达670 W","双面率[TOPCon 3.0高功率密度组件]: 90%","LCOE降幅[TOPCon 3.0高功率密度组件]: 1.4%","[TOPCon 3.0组件]: 基于大尺寸矩形硅片的多切技术"]},{"i":2631,"as":"EcoFlow在慕尼黑The Smarter E展会上发布了多款面向欧洲市场的新能源产品。核心产品包括全新的住宅储能产品、工商业电池、Stream 5000即插即用式储能系统以及更新版的AI驱动家庭能源管理系统。本次发布重点强调了设备的向后兼容性以及基于人工智能的能源管理技术。","scd":null,"kp":["目标市场[Stream 5000电池存储系统]: 插入式光伏/欧洲市场"]},{"i":2632,"as":"据欧洲光伏协会报告，2025年全球新增太阳能装机容量达到创纪录的664吉瓦，全球光伏总装机量在2026年初超过3太瓦。其中亚太地区占73%（487吉瓦），仅中国便占57%（382吉瓦）。然而，由于中国预期装机量下降，全球光伏市场年增长率放缓至12%，或将迎来20多年来的首次市场收缩。","scd":null,"kp":["新增装机容量[2025年全球太阳能]: 664 GW","累计装机容量[2026年初全球太阳能]: 超过3 TW"]},{"i":2633,"as":"欧洲热泵协会（EHPA）分析显示，2025年欧洲21个国家的热泵销量同比增长13%，达到288万台。这一数据高于2024年的256万台，但仍低于2022和2023年的峰值。这些热泵的替代效应相当于减少了25亿立方米液化天然气消耗。空气源热泵是销量最高的类型，其次是空气源-水系统。","scd":null,"kp":["销量增长率[2025年欧洲21国热泵]: 13%","总销量[2025年欧洲21国热泵]: 288万台","替代效应[2025年欧洲21国热泵]: 可替代25亿立方米液化天然气"]},{"i":2634,"as":"研究人员利用二维光电仿真模型，探讨了随机界面纹理对甲基铵铅碘（MAPbI₃）钙钛矿太阳能电池性能的影响。结果表明，在器件各层引入纳米结构纹理会产生光学与电学相互作用。其中，准正弦形界面纹理在光吸收和电荷传输之间实现了最佳平衡，其性能优于金字塔形和凹凸不平的形貌结构。","scd":null,"kp":["[MAPbI₃钙钛矿太阳能电池]: 采用准正弦形貌的随机界面纹理，在光吸收和电荷传输之间实现最佳平衡，优于金字塔形和凹凸形貌"]},{"i":2635,"as":"pv magazine与Vireo Ventures联合发布的能源初创企业地图显示，91家受访能源初创企业正在推动能源行业转型。从业务分布来看，近一半企业专注于能源管理与优化领域，约四分之一活跃于能源交易市场。该地图将这些企业分为八个类别，详细梳理了它们的活动领域、目标受众与商业模式。","scd":null,"kp":[]},{"i":2636,"as":"挪威研究人员评估了太阳能光伏在北极地区定居点（斯瓦尔巴群岛朗伊尔城）摆脱化石燃料转型中的潜力。研究指出，尽管面临积雪、结冰、永久冻土和极端季节性光照等北极环境挑战，但该地区在夏季展现出强大的光伏发电潜力。此外，当地拥有丰富的屋顶资源，且光伏系统与风能、储能设备在集成可再生能源系统中具有高度的互补性。","scd":null,"kp":["[北极极端环境光伏系统]: 具备较强的夏季发电潜力及屋顶资源可用性，并与风能和储能具有明显互补性"]},{"i":2637,"as":"美国公司Nextpower宣布计划以约3.3亿欧元（3.78亿美元）的现金和股票收购德国光伏支架系统供应商Zimmermann PV Steel。此次收购将推动作为光伏跟踪器供应商的Nextpower在2026年进行业务扩张。该交易需满足交割条件与监管审查，预计将于2027财年完成。","scd":null,"kp":["交易金额[Nextpower收购Zimmermann PV Steel]: 约3.78亿美元（3.3亿欧元）"]},{"i":2638,"as":"德国卡尔斯鲁厄理工学院（KIT）与德国航空航天中心（DLR）联合发布了关于德国西部于利希太阳能塔试验电厂的开放获取数据集。与直接将阳光转化为电能的光伏不同，太阳能塔发电厂利用聚光产生热能，可进行存储、直接发电或用于工业过程。研究团队希望借此数据推动不同设施数据的共享与该技术的广泛应用。","scd":null,"kp":["数据集[Jülich太阳能塔]: 开放获取，旨在促进光热技术的广泛采用"]},{"i":2639,"as":"西班牙工业集团Circuitor针对光伏自发自用系统推出了Computer PV-12无功电能控制器。该设备专为单相多能源共存场景设计，能够通过独立电流输入管理单相上的三个电流源。其内置软件可对测量信号进行内部求和，无需外部CT求和单元，从而简化了安装流程并提升了功率因数的测量精度。","scd":null,"kp":["电流源数量[单相光伏自耗无功电能控制器]: 最多3个","测量方式[无功电能控制器]: 内部汇总测量并消除外部CT汇总单元需求"]},{"i":2640,"as":"6月17日，美国海军第11海军陆战队远征单元在南海从“波特兰”号两栖船坞运输舰的甲板上发射了一架V-BAT长航时无人机。此次演示表明，两栖战舰无需依赖航母、大型载人飞机、跑道或专业发射基础设施，即可部署无人机执行持续的情报、监视和侦察（ISR）任务，大幅扩展了海军的视距外作战感知能力。","scd":null,"kp":["发射平台[南海长航时无人机演示]: 海军两栖运输船坞舰","无人机型号[海军监视任务]: V-BAT"]},{"i":2641,"as":"德国弗劳恩霍夫光微系统研究所（IPMS）发布了一款名为Q-Dice的新一代量子随机数发生器（QRNG）。该设备通过测量不可预测的量子真空波动来产生真正的随机数，使系统免受算法漏洞和黑客攻击。其核心技术突破在于处理速度，Q-Dice生成真实随机数的速率达到4.1 Gbit/s，为下一代密码学和网络安全通信提供了高质量的量子熵源。","scd":null,"kp":["设备属性[下一代密码学和通信]: 快速的下一代量子随机数生成器(QRNG)","随机数生成机制[Q-Dice量子设备]: 通过测量内在不可预测的物理现象产生真正的随机数"]},{"i":2642,"as":"麻省理工学院（MIT）的最新分析表明，俄罗斯代号为SSC-X-9 Skyfall（海燕）的核动力巡航导弹在飞行过程中会留下放射性物质痕迹。该导弹由普京于2018年首次公开，其设计采用微型核反应堆作为动力，理论上可飞行数千英里。新研究重新引发了关于该武器设计缺陷、环境污染风险以及战略价值的广泛争议。","scd":null,"kp":["动力系统[SSC-X-9 Skyfall巡航导弹]: 微型核反应堆","[飞行过程特征]: 可能会留下放射性物质痕迹"]},{"i":2643,"as":"瑞士水泥生产商Vigier Ciment部署了ANYbotics公司的ANYmal四足机器人，在其拥有150年历史的水泥厂中进行自动化巡检。该机器人每晚自主运行，可在狭窄楼梯、多尘和高温环境中导航，检查跨越6层和3个磨机的450多个预设检查点。通过搭载的传感器，ANYmal能自主扫描结构缺陷、设备过热和气体泄漏。自2025年初投入使用以来，已完成超3.3万次巡检，有效降低了人员危险暴露并提升了设施维护覆盖率。","scd":null,"kp":["巡检点数量[水泥厂夜间自主巡检]: 超过450个预定点","运行环境[四足机器人自主巡检]: 狭窄楼梯、多粉尘环境和高温区域","功能特性[ANYmal四足机器人]: 扫描设备结构缺陷、过热及气体泄漏"]},{"i":2644,"as":"联合航空飞行员兼YouTuber保罗·霍尔特在访问位于科罗拉多州的Boom Supersonic公司时，体验了XB-1验证机和Overture超音速客机的飞行模拟器。XB-1验证机今年早些时候实现了首次超音速飞行，它将作为测试平台，为更大的Overture商用超音速客机铺平道路，这将是自协和号以来的首款商用超音速客机。","scd":null,"kp":["飞行速度[超音速喷气式飞机]: 2马赫"]},{"i":2645,"as":"中国一汽解放完成了为期七个月的钠离子电池电动重卡实车测试。测试车队累计行驶超过9300英里，涵盖了长距离行驶、反复充放电、复杂路况及极端天气等实际运营条件。测试核心为与中科海钠联合开发的339千瓦时钠离子电池包。结果显示，该电池组在-40°F（约-40°C）的极寒环境下仍能保持90%的电量，标志着钠离子电池在商用车领域的商业化应用取得重要突破。","scd":null,"kp":["容量保持率[钠离子卡车电池在-40°F]: 90%","测试里程[电动卡车全工况系统测试]: 超过9300英里","电池类型[重型卡车实车测试]: 钠离子电池"]},{"i":2646,"as":"特斯拉已悄然向美国专利商标局提交了名为“Megapod”的商标申请。该申请属于“意向使用”类别，指向一款专为端到端人工智能部署设计的自给式模块化数据中心建筑构件。该文件表明，特斯拉计划打造能够将NVIDIA芯片转化为即插即用型“重型金属舱室”的模块化AI数据中心硬件系统。","scd":null,"kp":["设施属性[NVIDIA芯片集成]: 即插即用的大型自包含AI数据中心"]},{"i":2647,"as":"美国空军研究实验室（AFRL）在莱特-帕特森空军基地启用了名为Flyer的新型超级计算机。这台价值2000万美元的设备隶属于国防部高性能计算现代化计划，专门用于解决高超音速武器研究、人工智能开发和下一代飞机设计等高计算量军事挑战。该系统能在一天内完成普通笔记本电脑需500年才能算完的任务。","scd":null,"kp":["成本[新型超级计算机]: 2000万美元","计算节点规模[Flyer超级计算机]: 186,000个核心","计算效率[解决复杂计算问题]: 一天内可解决普通笔记本需约50年才能解决的问题"]},{"i":2648,"as":"","scd":null,"kp":[]},{"i":2649,"as":"","scd":null,"kp":[]},{"i":2650,"as":"","scd":null,"kp":[]},{"i":2651,"as":"","scd":null,"kp":[]},{"i":2652,"as":"","scd":null,"kp":[]},{"i":2653,"as":"科罗拉多州立大学（CSU）的研究人员精确测量了质子的大小，成功解决了困扰物理学界十多年的“质子半径之谜”。由于氢原子内部仅含一个质子和一个电子，它一直被用作研究基本粒子的测试平台。此次高精度的测量结果消除了以往关于质子半径测量的冲突，进一步巩固了粒子物理学标准模型的置信度。","scd":null,"kp":["物理意义[质子尺寸精确测量]: 解决质子半径之谜并巩固粒子物理标准模型"]},{"i":2654,"as":"GSI/FAIR的研究人员与国际合作团队开发了一种基于机器学习的新模型，用于探究宇宙中最重元素的形成过程。该团队首次将深度学习神经网络引入流体动力学模拟中，以建模中子星合并等极端宇宙事件期间r-过程释放的能量。这项技术突破为详细模拟金和铀等重元素的起源提供了全新的计算视角。","scd":null,"kp":[]},{"i":2655,"as":"","scd":null,"kp":[]},{"i":2656,"as":"苏州大学联合澳大利亚莫纳什大学及多家光伏企业，成功研发出光电转换效率超过30%的新型无铟叠层光伏电池，推动行业摆脱昂贵的稀有金属铟。基于“钙钛矿/晶硅”叠层技术，团队试制的1平方厘米和207.9平方厘米电池初始效率分别达33.56%和30.98%。经认证，大面积样品在105天户外运行后，效率保持在初始水平的65%左右。该成果已在《科学》杂志发表。","scd":null,"kp":["光电转化效率[1平方厘米无铟叠层电池]: 33.56%","光电转化效率[207.9平方厘米无铟叠层电池]: 30.98%","转化效率保持率[207.9平方厘米样品经105天户外运行]: 初始水平的65%左右"]},{"i":2657,"as":"武汉理工大学团队提出新策略解决无反溶剂法制备钙钛矿太阳能电池的结晶难题。通过引入偶极矩为1.9德拜的氟取代间苯二甲酸二甲酯衍生物添加剂，抑制溶剂化中间体生成。该技术将α相主导时间从150秒缩短至23秒，制备出高质量薄膜。纯FAPbI₃无反溶剂正置结构电池光电转换效率达26.28%，创同类器件最高纪录。在85℃老化1500小时后效率留存率达93.7%，1000小时最大功率点追踪后效率保持90%。","scd":null,"kp":["添加剂偶极矩[无反溶剂法制备α-FAPbI₃]: 1.9 Debye","相变时间[α相主导时间]: 23秒","光电转换效率[纯FAPbI₃无反溶剂正置结构电池]: 26.28%","效率留存率[85℃高温老化1500小时]: 93.7%","效率维持率[1000小时最大功率点追踪测试]: 初始水平的90%"]},{"i":2658,"as":"","scd":null,"kp":[]},{"i":2659,"as":"","scd":null,"kp":[]},{"i":2660,"as":"诺贝尔奖得主John Jumper已离开谷歌DeepMind，正式加入人工智能公司Anthropic。","scd":null,"kp":[]},{"i":2661,"as":"一项关于世界上最深和最长海底公路隧道的实地考察记录显示，该隧道位于北海下方约300米深处，承受着超过500磅/平方英寸的巨大水压。实地环境极度寒冷且嘈杂，工程师们在距离爆破点仅几百米外进行岩壁爆破工作，依赖卓越的工程设计、严格的安全简报和专业防护装备来保障人员生命安全。","scd":null,"kp":["深度[北海海底公路隧道]: 约300米","水压[北海海底环境]: 超过500磅/平方英寸"]},{"i":2662,"as":"LCP Delta和Energy Storage Europe报告指出，欧洲在2025年新增了创纪录的13.5 GW/26.4 GWh电化学储能，使所有技术的储能总装机容量达到102.7 GW，已超越核能。其中，表后储能容量达30.2 GW/46.2 GWh，主要受太阳能储能系统采用和动态电价驱动。表前电池储能达18.5 GW/34.4 GWh，在拥有成熟容量市场的国家增长最为强劲。","scd":null,"kp":["新增电化学储能装机容量[2025年欧洲]: 13.5 GW/26.4 GWh","总装机容量[2025年底欧洲所有技术储能]: 102.7 GW","表后储能容量[2025年底欧洲]: 30.2 GW/46.2 GWh"]},{"i":2663,"as":"DLA Piper对550名电池储能投资者和贷款机构的调查显示，美国（25%）、英国（19%）和中国（14%）被视为最具吸引力的投资市场。为补偿执行和监管风险，50%的受访者期望获得11%至12%的回报，17%寻求13%至15%的回报。调查发现，商业风险敞口被限制在总收入的21%至60%之间，贷款机构对商业风险的接受度较为集中。","scd":null,"kp":["商业风险敞口上限[储能贷款机构]: 60%","投资吸引力排名[美国电池储能市场]: 第一位 (25%受访者选择)","预期回报率[电池储能投资者]: 11%至12%"]},{"i":2664,"as":"比亚迪计划投资最高9800万美元（5亿巴西雷亚尔）在巴西建设电池储能系统（BESS）生产线，以迎接巴西首次电网级储能拍卖。比亚迪巴西高级副总裁表示，公司将在约90天内决定是在现有马瑙斯电池厂增设产线还是新建工厂。该项目专注于电网级BESS系统的模块、包及系统集成本地化，初期预计创造300至400个直接就业岗位。","scd":null,"kp":["投资额[比亚迪巴西BESS生产线]: 9800万美元"]},{"i":2665,"as":"德国可再生能源开发商MaxSolar已选择Entrix来优化和商业化一个位于巴伐利亚州的20 MW/100 MWh电池储能系统（BESS）。该项目专为当地配电网运营商N-Ergie开发，旨在稳定局部电网。该五小时储能系统将采用完全商业模式运作，并使用人工智能支持的交易策略来平衡商业回报与电网需求。这是MaxSolar开发的第二个电网支持型储能项目。","scd":null,"kp":["系统规模[MaxSolar德国电网支持BESS]: 20 MW/100 MWh","储能时长[Winterschneidbach电池项目]: 5小时"]},{"i":2666,"as":"总部位于布鲁塞尔的开发商Aukera Energy宣布其位于罗马尼亚的Gura Ialomiței电池储能系统（BESS）第一阶段（150 MW/300 MWh）已正式投入运营，这是其在罗马尼亚首个运营的BESS资产。第二阶段（100 MW/200 MWh）预计于2026年底完工。整个项目完成后总规模将达250 MW/500 MWh。该项目获得了来自Kommunalkredit的6000万欧元债务融资。","scd":null,"kp":["系统规模[Aukera Energy罗马尼亚Gura BESS第一阶段]: 150 MW/300 MWh","系统规模[Gura BESS第二阶段]: 100 MW/200 MWh"]},{"i":2667,"as":"HydrogenPro正在推进其氢气瓶设计、测试和认证等相关技术及项目管线。","scd":null,"kp":["[Hydrogen cylinders]: 涵盖设计、测试和认证流程"]},{"i":2668,"as":"深圳正加速打造“人形机器人第一城”，以优必选、荣耀、乐聚为代表的“八大金刚”机器人企业迎来了业绩与估值的“双击时刻”。荣耀机器人在北京半程马拉松比赛中包揽前六并打破人类纪录，展现了在动力核心、液冷散热和运动控制等技术上的领先地位；乐聚智能的创业板IPO申请获受理，拟募资26亿元。2025年深圳机器人产业总产值达2426亿元，产业链完整度居全国第一方阵。","scd":null,"kp":["募资金额[乐聚智能创业板IPO]: 26亿元","比赛成绩[2026北京亦庄人形机器人半程马拉松]: 荣耀机器人包揽前六名","技术优势[荣耀机器人]: 动力核心、液冷散热和运动控制实现领先","[人形机器人]: 打破人类半程马拉松纪录"]},{"i":2669,"as":"分析指出，AI大模型的上市路径已经打通。这标志着人工智能大模型企业在资本市场的商业化进程取得了实质性进展与合规通道。","scd":null,"kp":["[AI大模型]: 资本市场上市路径打通"]},{"i":2670,"as":"英国《自然》杂志发表的最新研究显示，科学家研发出一种新型量子传感器，能够有效消除背景噪声对测量精度的影响。该传感器具备探测极微弱信号的能力，可用于搜寻引力波和暗物质。这项技术突破将为探索超大质量黑洞的形成机制等重大天体物理学谜团提供关键的研究工具。","scd":null,"kp":["[新型量子传感器]: 有效消除背景噪声对测量精度的影响","[新型量子传感器]: 可探测引力波和暗物质等微弱信号"]},{"i":2671,"as":"本文介绍了AI时代Token与GPU的底层运算关系。Token是用户与AI交互时消耗的基本单位，而GPU是负责产生和持续运算这些Token的核心硬件算力支撑。通过探访国产GPU企业，通俗阐释了用户进行提问、画图等操作消耗的每一个Token，其背后均完全依赖于GPU的持续运算能力。","scd":null,"kp":["[AI算力底层关系]: AI消耗的每个Token背后均需GPU进行持续运算"]},{"i":2672,"as":"第四届中国国际供应链促进博览会将于6月22日至26日在北京举行。本届展会形成“6链1展区”，其中原“数字科技链”正式升级为“数智科技链”并首次设立人工智能专区，凸显科技创新对供应链的赋能。目前已有85个国家和地区的676家中外参展商确认参展，外资比例达36.5%，世界500强及龙头企业占比超65%，国际化程度进一步提升。","scd":null,"kp":["举办时间[第四届链博会]: 6月22日至26日","合作意向[第三届链博会]: 现场签署合作协议及达成合作意向超过6000项","展会架构[第四届链博会]: 涵盖数智科技链等6链1展区并首设人工智能专区"]},{"i":2673,"as":"我国正加速推进全国一体化算力网建设，目前已形成“8+10+3”算力空间布局。截至今年3月底，全国建成智能算力规模达188.2万P，为去年同期的2.5倍。我国围绕算力枢纽建成145条干线光缆，全国各省份至8大枢纽的网络传输时延均降至20毫秒以内。在算电协同方面，已探索出绿电多元利用模式，以实现算力设施绿电替代。","scd":null,"kp":["智能算力规模[截至今年3月底]: 188.2万P","增长倍数[智能算力规模]: 相当于去年同期的2.5倍","空间布局[全国一体化算力网]: 形成8大国家算力枢纽、10个国家算力集群、3个算电协同发展区域的“8+10+3”格局","绿电利用模式[算电协同]: 探索形成“源网荷储”一体化、“光伏直连+风电长协”等模式"]},{"i":2674,"as":"在国家政策与研发投入的推动下，消费级具身智能落地提速，人形机器人上游核心零部件精密减速器迎来爆发机遇。国内多家头部机器人企业正加速C端市场布局。上纬启元在深圳筹备亚洲首家机器人体验店，其于2025年推出了全球首款小尺寸全身力控人形机器人Q1。宇树科技、优必选、越疆科技等企业也纷纷落地直营店或开启全尺寸人形机器人预售。","scd":null,"kp":["[启元机器人Q1]: 2025年推出全球首款小尺寸全身力控人形机器人","[消费级具身智能]: 依托研发投入与政策赋能，C端市场布局、产品预售与规模化出货提速","[精密减速器行业]: 迎来需求爆发与产业升级双重机遇"]},{"i":2675,"as":"国产消费级3D打印机正成为智能硬件消费新增长点。技术进步解决了早期设备调平繁琐、多色打印困难等问题，拓竹科技等企业将工业级打印技术带入消费级产品，推动“桌面制造”普及。3D打印以三维模型为蓝本，通过逐层堆积金属、塑料等材料成型。这种新型消费文化带动了从设备、耗材到软件、分享平台等上下游产业链的协同发展。","scd":null,"kp":["[3D打印机]: 通过打印精度提升、操作门槛降低及材料成本下降走入家庭消费市场","成型原理[3D打印技术]: 利用激光束、热熔喷嘴对金属粉末、陶瓷粉末、塑料等材料进行逐层堆积黏结叠加成型","推出时间[深圳拓竹科技第一款X1系列高速智能3D打印机]: 2022年"]},{"i":2676,"as":"","scd":null,"kp":[]},{"i":2677,"as":"2026年6月18日，工信部等五部门联合组织评选的73个智能光伏典型案例名单进行公示。此次案例征集涵盖光储融合、建筑光伏、交通运输应用、光伏制氢/氨/醇、关键信息技术等十大领域。入围项目覆盖全国多个省份，包括中国建研院光电示范建筑、淮安东站光储充放能源站、钙钛矿光伏组件制造应用以及海上光伏项目等典型应用场景。","scd":null,"kp":["入围数量[智能光伏典型案例]: 73个","征集领域[智能光伏案例]: 涵盖光储融合、建筑光伏、光伏制氢/氨/醇等十大领域","项目案例[海上光伏]: 国华HG14海上光伏1000MW项目","项目案例[钙钛矿光伏]: 全尺寸高转化率钙钛矿光伏组件、钙钛矿及叠层光伏系统制造和应用"]},{"i":2678,"as":"宁夏小牛自动化设备股份有限公司于2026年6月15日完成上市辅导备案，正式启动IPO进程，由国信证券担任保荐机构。公司主营光伏组件前端自动化产线设备，核心产品覆盖划片钝化一体机、串联机等全系列关键生产设备。其国内外市场同步拓展，海外业务辐射三十余国。公司实控人王小牛及一致行动人合计掌控65.74%表决权，股权结构稳定。","scd":null,"kp":["表决权[小牛自动化实际控制人]: 58.11%","表决权[小牛自动化一致行动人合计]: 65.74%","[光伏组件前端设备]: 覆盖划片钝化一体机、串联机、排版机、汇流带焊接机、串返修机等全系列关键生产设备"]},{"i":2679,"as":"浙江三叶青光伏发电有限公司因债务危机被债权人向法院申请破产清算。该公司成立于2015年，主营太阳能发电技术服务及光伏设备制造等业务，注册资本3200万元。2026年3月及5月，公司先后被法院强制执行，累计被执行金额达290.33万元。企查查数据显示，企业目前存在被执行人及限制高消费等风险记录，经营压力巨大。","scd":null,"kp":["被执行金额[三叶青光伏债务强制执行]: 290.33万元"]},{"i":2680,"as":"","scd":null,"kp":[]},{"i":2681,"as":"青海电力交易中心通报了5月电力现货市场结算试运行情况。实时市场日均出清电量1.47亿千瓦时，其中光伏以0.76亿千瓦时占据52%的份额。在出清均价方面，发电侧整体出清均价为123元/兆瓦时，具体品类中火电161元/兆瓦时，风电152元/兆瓦时，光伏最低为85元/兆瓦时。独立储能出清充放电价差为169元/兆瓦时。","scd":null,"kp":["日均出清电量[青海电力实时市场]: 1.47亿千瓦时","出清电量占比[光伏]: 0.76亿千瓦时/52%","出清电量占比[风电]: 0.41亿千瓦时/28%","出清电量占比[火电]: 0.22亿千瓦时/15%","出清电量占比[储能]: 0.08亿千瓦时/5%"]},{"i":2682,"as":"华润新能源控股有限公司正式启动IPO路演，拟募资245亿元，资金将投向新能源基地等四大核心项目。作为华润集团新能源旗舰平台，公司主营风电与太阳能发电业务。截至2025年末，公司业务覆盖全国31个省份，控股并网装机容量约41.59GW，其中风电27.63GW，太阳能13.96GW，装机规模位居行业前列。该股将于6月22日申购。","scd":null,"kp":["拟募资规模[华润新能源IPO]: 245亿元","控股并网装机容量[华润新能源截至2025年末]: 约41.59GW","装机容量及市场份额[风电]: 27.63GW/4.32%","装机容量及市场份额[太阳能]: 13.96GW/1.16%"]},{"i":2683,"as":"福特明确表示，全新的Universal EV平台不会用于下一代福特电马车型。福特CEO此前直言初代纯电车型研发方向有误。现款福特电马将至少保留至2027年，原定2030年的重大升级计划存在不确定性。全新的Universal EV平台从零开发以提升整车效率，将首先应用于一款紧凑型皮卡。未来纯电福特锐际的推出或将进一步挤压电马的市场空间。","scd":null,"kp":["车型保留时间[福特电马现款]: 至少保留至2027年","平台[福特全新纯电架构]: Universal EV平台（从零开发，目标最大限度提升整车效率）","[下一代福特电马]: 明确不使用Universal EV平台，暗示不会有下一代车型"]},{"i":2684,"as":"谷歌DeepMind杰出工程师费恩伯格发文指出，进入顶尖AI实验室需要极强的目标感、数学成熟度与毅力。求职者需选择以数学证明为基础的课程，并在课外投入大量时间编程，证明自己掌握实验室所需的具体技能。面对“无前沿模型经验则难获职位”的困境，他建议从前沿实验室的业务边界寻找突破口，从事不直接参与模型训练但对业务至关重要的工作。","scd":null,"kp":["[顶尖AI实验室核心录用标准]: 目标感、数学成熟度和毅力"]},{"i":2685,"as":"SpaceX与开源AI初创企业Reflection AI签署算力合作协议，总价值最高达63亿美元。根据协议，Reflection将获得英伟达GB300 AI芯片使用权，用于训练高级模型。Reflection同意从2026年7月至2029年底，每月向SpaceX支付1.5亿美元。合约生效三个月后，双方均可提前90天通知终止合作。Reflection此前还参与了美国能源部和五角大楼的AI项目。","scd":null,"kp":["合约最高价值[SpaceX与Reflection算力合作]: 63亿美元","月支付费用[Reflection向SpaceX支付]: 1.5亿美元","核心算力资源[Reflection获取]: 英伟达GB300 AI芯片","合作周期[算力协议执行]: 2026年7月1日至2029年底"]},{"i":2686,"as":"苹果已批准三星显示启动折叠OLED模组量产，为其首款折叠屏iPhone独家供应OLED面板，双方签署三年独供协议，首批约300万块面板计划今年交付。三星显示面板后段制程在越南工厂进行，良率达标70%以上，将采用最新一代M16有机材料体系。苹果首款折叠屏手机预计9月亮相，但新机最终发布时间将取决于关键铰链等零部件能否按期量产。","scd":null,"kp":["首批交付量[苹果折叠屏iPhone OLED面板]: 约300万块","最低良率要求[苹果模组量产认证]: 70%","协议期限[苹果与三星独家供货]: 三年","生产产线规模[三星显示越南工厂]: 约80条产线（约50条已投产）","OLED材料体系[苹果旗舰手机最新面板]: M16"]},{"i":2687,"as":"小米YU7 GT搭载自主研发的自动驾驶系统，在纽博格林北环赛道实现全程无人驾驶，创下10分29秒483的全球首个纽北自动驾驶圈速纪录。纽北官方圈速榜为此新增了“自动驾驶”分类。在极限赛道上锤炼出的高频扭矩分配和毫秒级救车能力，将逐步下发应用至小米的量产车型中，以提升普通用户在暴雨、冰雪等极端工况下的车辆安全性。","scd":null,"kp":["赛道圈速纪录[小米YU7 GT纽北自动驾驶]: 10分29秒483"]},{"i":2688,"as":"宁德时代宣布将于今年9月在中国市场交付首批钠离子电池解决方案，预计2026年底实现GWh级出货量，全球市场将于明年6月开始交付。目前钠离子电池量产生产线已全部投产，通过技术强化，其成本低于行业平均水平10%至20%。相比锂电池，钠离子电池具有资源丰富、低温性能更好和安全性高的特点。宁德时代此前已签署3年60GWh的钠离子电池订单。","scd":null,"kp":["首批交付时间[中国市场钠离子电池解决方案]: 今年9月","预计出货量[2026年底钠离子电池]: GWh级","全球市场交付时间[钠离子电池解决方案]: 明年6月","成本优势[钠离子电池储能产品]: 低于行业平均水平10%~20%","[钠离子电池量产线]: 已全部投产并正常运行"]},{"i":2689,"as":"","scd":null,"kp":[]},{"i":2690,"as":"","scd":null,"kp":[]},{"i":2691,"as":"","scd":null,"kp":[]},{"i":2692,"as":"华为乾崑｜启境GT7首台量产车于6月22日下线，将于6月26日上市。该车定位“新一代智能猎装”，预售价21.99万至30.99万元。启境GT7搭载华为乾崑ADS 5智驾系统、图像级激光雷达、HarmonySpace座舱及乾崑赤兔平台，全系标配宁德时代电池、闭式双腔空气悬架等硬件。广汽工厂配备毫米级AI质检，支持超10万种配置混线生产，最快14天交付。制造环节采用多项高端工艺确保整车高精度与豪华漆面品质。","scd":null,"kp":["预售价[启境GT7]: 21.99万元-30.99万元","下线节拍[广汽集团工厂]: 每53秒下线一台整车","生产柔性[工厂产线]: 支持超10万种配置、20余种车色车型混线生产","交付周期[启境GT7]: 最快14天","质检系统[整车制造]: 毫米级AI质检系统"]},{"i":2693,"as":"时隔14年，微软初代Surface RT正式获得主线Linux内核驱动支持。开源开发者Jonas Schwöbel开发了“surface-rt-ec”驱动，并将在Linux 7.2版本中正式引入。该驱动负责与设备嵌入式控制器通信，使Linux系统能够读取Surface RT的剩余电量、供电电流、电压及电池制造商等信息。尽管电池与充电功能获得完善，但受限于2GB内存与Tegra 3芯片性能，该设备依然难以应对现代日常任务。","scd":null,"kp":["系统支持[Surface RT]: 正式纳入Linux主线内核驱动（Linux 7.2）","硬件配置[Surface RT]: 搭载英伟达Tegra 3芯片与2GB内存","数据读取[新增surface-rt-ec驱动]: 支持在Linux下正常读取剩余电量、供电电流、当前电压等信息"]},{"i":2694,"as":"据市场数据显示，截至上月底，vivo X Fold5折叠屏手机累计销量已突破52万台，成为除华为之外，业内历史累计销量唯一突破50万台的大折叠屏手机。vivo X Fold5于2025年6月发布，搭载骁龙8 Gen3处理器，配备6000mAh电池，机身重约217g。此外，vivo X Fold6定于6月26日发布，全版本标配7000mAh蓝海大电池并首发第五代硅负极技术，且支持水下直接操作。","scd":null,"kp":["累计销量[vivo X Fold5]: 超52万台","发布时间[vivo X Fold5]: 2025年6月","硬件配置[vivo X Fold5]: 搭载骁龙8 Gen3处理器，电池容量6000mAh，重约217g","电池容量[vivo X Fold6]: 全版本标配7000mAh","电池技术[vivo X Fold6]: 行业首发第五代硅负极技术"]},{"i":2695,"as":"中国科学院过程工程研究所与深圳大学联合团队开发出一种基于高分子“锁扣”机制的三维光热蒸发材料，大幅提升了太阳能海水淡化效率。该材料通过多层空心纳米球壳与聚酯分子链结合形成坚固三维网络，太阳光吸收率达90.2%，且使水蒸发所需能量降低45.7%。测试表明，单根蒸发体蒸发速率达每小时每平方米38.14千克。该装置日产淡水20.16升，水质达世卫组织标准，并成功完成长达一年的农田灌溉试验。","scd":null,"kp":["淡水缺口[2030年全球预测]: 达40%","材料机制[三维光热蒸发材料]: 利用高分子“锁扣”将纳米颗粒编织成三维网络","应用进展[太阳能界面蒸发]: 实现从海水淡化到农业灌溉的初步探索"]},{"i":2696,"as":"美国造车新势力Lucid宣布在新任CEO推进重组之际裁员18%，影响约1500名员工。这是该公司四个月内的第二次裁员，旨在精简架构、提高执行效率。此次裁员每年可节省约1.58亿美元成本，Lucid预计支付3200万美元遣散费，重组将于第三季度前完成。Lucid正准备推出起售价低于5万美元的Lucid Cosmos SUV，并计划在旧金山上线豪华Robotaxi服务。同时，其亚利桑那州工厂取消了汽车第二班生产。","scd":null,"kp":["裁员比例[Lucid公司]: 裁减18%员工（约1500人）","起售价[Lucid Cosmos SUV]: 预计低于5万美元（约33.9万元人民币）"]},{"i":2697,"as":"美光科技宣布与AI公司Anthropic达成战略合作，共同扩展下一代人工智能基础设施。双方合作涵盖AI架构设计、长期供应协议、美光引入Claude模型及参与Anthropic的H轮股权融资。双方将共同研究HBM、DRAM及SSD等技术在AI训练与推理中的应用，以优化性能与成本。美光已签署协议为Anthropic提供长期内存与存储供应，支持其算力扩张。同时，美光已在内部工程与制造环节部署Claude模型以提升应用智能化水平。","scd":null,"kp":["合作内容[美光与Anthropic]: 涵盖AI架构设计、内存与存储长期供应协议及股权投资","研发方向[AI基础设施]: 共同研究HBM、DRAM及SSD在AI训练和推理场景中的应用","商业应用[美光内部]: 全面引入Claude模型加速代码编写及工程设计"]},{"i":2698,"as":"宁德时代位于匈牙利德布勒森的电池工厂建设进度落后于原计划。目前该工厂的电池模块组装已经启动，但电芯生产尚未开始，导致奔驰不得不从中国采购新款电动运输车的电池。宁德时代于2022年8月宣布建设该工厂，计划投资额为73.4亿欧元，这是其在德国阿恩施塔特工厂之后的欧洲第二座电芯工厂，主要为欧洲汽车制造商生产电池电芯与模块。","scd":null,"kp":["生产进度[宁德时代德布勒森工厂]: 模块组装已启动，电芯生产延误","供应链[梅赛德斯-奔驰电动厢式车]: 暂从中国采购电池"]},{"i":2699,"as":"中国商用车制造商一汽解放与电池开发商汉能电池成功完成了钠离子电动卡车电池的长期测试。该项目基于一汽解放J6P纯电动牵引车，搭载了容量为339kWh、专为商用车开发的钠离子电池。在长达七个月、行驶里程达1.5万公里的测试中，车辆在低至零下40摄氏度的极端恶劣天气条件下运行。测试结果表明，该钠离子电池在零下40摄氏度的极端低温环境中，依然能够保持超过90%的可用容量。","scd":null,"kp":["测试里程[钠离子电动卡车]: 15,000公里","极端环境[长期测试]: 历时7个月，涵盖恶劣天气及-40°C极寒条件","应用车型[一汽解放J6P]: 电池电动牵引车"]},{"i":2700,"as":"随着电池储能系统（BESS）项目数量与规模的大幅增长，该技术已从早期的细分领域技术转变为英国能源体系的主流组成部分，并获得了极大的商业关注与政策支持。储能市场的快速扩张在带来行业发展机遇的同时，也为这一复杂解决方案的交付及相关参与者引入了风险与挑战。在快速发展的市场环境中，高效推进并落实BESS项目对产业链中的每一个参与者都提出了更高的现实要求。","scd":null,"kp":[]},{"i":2701,"as":"物流公司Breakthrough将可持续发展作为其降低成本和增强业务韧性的核心战略，并因此被评选为领先的绿色供应链合作伙伴，成功入选《Inbound Logistics》的75强绿色供应链合作伙伴名单。随着消费者对清洁环保解决方案的需求不断增长，全球物流企业正积极寻求并展示其减少碳排放的机会。结合其发布的运输状况报告，Breakthrough顺势推出了全新的分析产品，致力于提供更具成本效益和可持续性的运输物流解决方案。","scd":null,"kp":["荣誉认证[Breakthrough]: 入选Inbound Logistics 75家绿色供应链合作伙伴榜单"]},{"i":2702,"as":"UPS（联合包裹）宣布投资4800万美元用于加强其横跨欧洲、亚洲和美洲的冷链物流能力，以强化其医疗保健业务。对于全球物流企业而言，强大可靠的冷链运营至关重要。由于医疗保健和制药行业的产品需要严格的温度控制以避免变质并确保按时交付，UPS此举旨在通过改进冷链战略支持全球医疗需求。这项投资展现了UPS在确保医疗产品得到精心温控和可靠运输方面的承诺。","scd":null,"kp":["投资金额[UPS冷链物流]: 4800万美元","投资区域[医疗保健冷链供应链]: 欧洲、亚洲和美洲"]},{"i":2703,"as":"","scd":null,"kp":[]},{"i":2704,"as":"特斯拉证实，在美国德克萨斯州凯蒂市发生的一起Model 3冲入民宅并导致一名76岁妇女死亡的致命事故中，车辆的“完全自动驾驶”（FSD）系统处于开启状态。特斯拉AI负责人表示，车辆数据显示，驾驶员在住宅区内将加速踏板踩到底（100%）进行了人工干预，导致车辆时速达到73英里。数据显示，即使在车辆撞穿砖墙后，加速踏板依然处于被踩下的状态，各项证据均指向在自动驾驶开启状态下发生了踏板误用。","scd":null,"kp":["[自动驾驶系统]: 事故发生时处于“完全自动驾驶”(FSD)打开状态","[系统控制权切换]: 司机通过将加速踏板踩到100%超控了系统"]},{"i":2705,"as":"日产汽车已停止其欧洲最畅销车型逍客（Qashqai）纯电动版车型的开发计划。逍客在2025年为日产在欧洲贡献了约42%的销量，售出超过14.72万辆。尽管该SUV原计划于今年实现全面电动化，但日产早在2025年初便暂停了其开发。此举主要为了削减成本，并应对如比亚迪等低成本中国电动汽车品牌在欧洲市场迅速扩张所带来的巨大竞争压力。","scd":null,"kp":["销量[日产欧洲2025年最畅销车型]: 超过147,200辆","销售占比[逍客占该地区品牌总销量]: 约42%","[纯电动车型推出计划]: 放弃近期推出Qashqai EV的计划"]},{"i":2706,"as":"","scd":null,"kp":[]},{"i":2707,"as":"特斯拉与独立能源公司NatPower达成了一项总价值高达50亿美元的合作协议。根据该多年期协议，双方将在意大利和英国部署总容量为25吉瓦时（GWh）的特斯拉Megapack电池储能系统。NatPower将使用特斯拉的交易软件进行电力买卖决策。这是特斯拉深入拓展欧洲快速增长的电网储能市场的重要举措。此项建设成本约为40亿至50亿美元的项目仅为第一阶段，NatPower表示该项目的最终目标是将储能容量扩大至100GWh以上。","scd":null,"kp":["储能规模[Tesla与NatPower合作]: 25 GWh","项目价值[初始阶段]: 高达50亿美元","[项目部署]: 部署Tesla Megapack系统并使用Tesla交易软件进行电力买卖","[部署区域]: 意大利和英国"]},{"i":2708,"as":"受欧洲持续热浪影响，比利时、荷兰和德国创下历史新高的日内电力价格。能源市场情报机构指出，极端高温显著降低了太阳能电池板的发电效率，同时导致联合循环燃气轮机（CCGT）发电厂的运行效率下降。数据显示，气温每升高1摄氏度，CCGT电厂的发电输出就会损失0.5%至0.9%。这些高温引发的发电效率下降和能源供应制约因素，直接推动了上述国家日内电价飙升至历史最高纪录。","scd":null,"kp":["[日前电价]: 比利时、荷兰和德国创下历史新高","[环境影响因素]: 高温降低了太阳能发电量并降低了联合循环燃气轮机(CCGT)的效率"]},{"i":2709,"as":"荷兰初创公司Moonwatt在慕尼黑The Smarter E展会上展示了专为公用事业规模光伏电站设计的模块化钠离子电池存储系统。与传统的集装箱式储能系统不同，该方案采用分布在太阳能电池阵列中的分布式单元设计。系统使用被动冷却的NFPP钠离子电芯，支持直流或交流耦合配置。该钠离子系统不依赖锂、钴材料和主动冷却系统，目标实现93%至94%的光伏到电网转换效率，旨在大幅降低系统平衡成本并实现高度可扩展和低维护部署。","scd":null,"kp":["太阳能至电网效率[公用事业规模钠离子存储系统]: 93-94%","[电池类型]: 采用被动冷却的NFPP钠离子电池","[系统特性]: 分布式单元、无锂、无钴、无主动冷却"]},{"i":2710,"as":"Jupiter International宣布其位于印度喜马偕尔邦巴迪的1.25 GW TOPCon太阳能电池制造生产线正式投产。该制造基地不仅包含新增的TOPCon产能，还拥有2 GW的单晶PERC太阳能电池制造能力。此外，该公司还在奥里萨邦布巴内斯瓦尔运营着一家1.3 GW的电池与组件集成制造工厂。该设施由Jupiter与AMPIN合作建立，并在印度政府与生产挂钩激励（PLI）计划的支持下开发，其生产的组件将专门提供给AMPIN使用。","scd":null,"kp":["产能[TOPCon太阳能电池产线]: 1.25 GW","产能[单晶PERC太阳能电池]: 2 GW","[地理位置]: 印度喜马偕尔邦巴迪"]},{"i":2711,"as":"TCL Sunpower在慕尼黑展会上推出了一款专为住宅应用设计的背接触光伏组件。该组件功率为505W，效率达24.7%，采用54片半片叠瓦背接触设计，实现了全背面电气连接，从而提升了效率、可靠性和机械稳健性。组件的温度系数极低，仅为0.26%，有利于在高温环境下保持性能，同时改善了光谱响应，实现更早和更晚的能源生产。","scd":null,"kp":["组件功率[住宅用背接触光伏组件]: 505W","转换效率[54半片叠瓦背接触设计]: 24.7%","[设计特点]: 背面全电气连接，提升效率、可靠性和机械鲁棒性"]},{"i":2712,"as":"瑞士钠离子电池公司Phenogy在慕尼黑展会上推出了专为工商业应用设计的模块化储能系统Phenogy 1.1。该系统具备50kW功率和100Ah容量，支持规模扩展，并配备了风冷热管理和集成安全功能。在此之前，该公司已在德国不来梅机场附近部署了一个1MWh的孤岛运行钠离子储能系统，是欧洲目前最大的运营中钠离子储能设施。","scd":null,"kp":["额定功率[工商业钠离子储能系统]: 50 kW","电池容量[Phenogy 1.1系统]: 100 Ah","[热管理]: 风冷热管理"]},{"i":2713,"as":"隆基在慕尼黑展会上发布了基于HPBC技术的全新背接触太阳能组件Hi-MO 9 Prime。该双面组件通过重新设计的堆叠电池架构消除了电池间隙并隐藏了母线，最大化了有效发电面积，实现了高达680W的输出功率和25.17%（文中亦称25.2%）的效率。此外，该组件采用隆基STAC互连技术，提高了抗阴影遮挡能力和整体可靠性。","scd":null,"kp":["输出功率[Hi-MO 9 Prime背接触组件]: 高达680W","转换效率[HPBC技术]: 25.2%","[架构设计]: 无电池间隙且隐藏主栅的叠层电池架构以最大化有效面积"]},{"i":2714,"as":"一支国际研究团队利用室温选择性碘铅酸盐冷铸造工艺，开发出2D/3D异质结架构的钙钛矿太阳能电池和微型组件，效率达22.36%。该工艺通过控制前驱体化学实现动力学稳定，生成的均匀2D层增强了垂直电荷传输。相比传统3D器件，这种2D/3D混合结构有效提升了器件的整体稳定性和转换效率。","scd":null,"kp":["转换效率[3D/2D钙钛矿太阳能电池及微型组件]: 22.36%","器件架构[钙钛矿太阳能电池]: 2D/3D异质结","制备工艺[钙钛矿薄膜]: 室温选择性碘代铅酸盐冷铸造工艺","[2D层]: 增强垂直电荷传输和器件稳定性"]},{"i":2715,"as":"在慕尼黑智慧欧洲展会上，Jackery展示了专为欧洲家庭设计的SolarVault 3系列插电式住宅太阳能储能解决方案。该模块化一体化系统包含三款型号，集成了逆变器和磷酸铁锂（LiFePO4）电池技术。此次展示还包括Jackery Ark、多款智能配件和Solar Gazebo，标志着该公司从便携式电源向家庭能源生态系统的拓展。","scd":null,"kp":["[家庭太阳能储能解决方案]: SolarVault 3系列即插即用住宅储能"]},{"i":2716,"as":"由于难以应对高比例的可变发电量，欧洲的太阳能装机增速开始放缓。能源基础设施开发商Sunotec首席执行官指出，电池储能系统和电网基础设施的建设需要时间跟进。他强调，欧洲在能源系统和电网的发展上需要采取更加综合的方法，不应将项目视为孤立的资产，而应将其视为完整的能源系统来统筹开发。","scd":null,"kp":["[欧洲太阳能装机]: 增速放缓","[能源系统开发]: 需采用更集成的方法"]},{"i":2717,"as":"荷兰代尔夫特理工大学的研究团队改进了农业光伏的光线模拟方法，使其对大气条件和农作物几何形状的表征更加逼真且具备计算效率。这项研究提高了对共享土地系统中作物生长和太阳能产量预测的准确性，从而为农业光伏系统的设计与优化提供了更精准的技术支持。","scd":null,"kp":["辐照度建模[农业光伏果园]: 改进半角感知光模拟方法（大气和树冠表征更逼真且计算高效）","[农业光伏光模拟]: 提高农作物生长和太阳能产量的预测精度"]},{"i":2718,"as":"一家中国机器人公司Agibot对其在平板生产线上自主工作的人形机器人车队进行了为期六天的直播展示。轮式G2机器人作为人类工人的助手，负责平板电脑的检测和分拣任务。在运营前三个小时内，机器人处理了超过800件产品且无差错。2026年2月，Agibot发布了专为复杂制造任务设计的G2工业机器人升级版。","scd":null,"kp":["处理量[人形机器人平板生产线作业前3小时]: >800个产品且零错误","应用场景[轮式G2人形机器人]: 平板电脑检测和分拣","[人形机器人]: 在平板生产线上自主工作"]},{"i":2719,"as":"潜艇分为攻击型潜艇和弹道导弹潜艇，它们在海军任务中扮演着截然不同的角色。攻击型潜艇被称为“猎手杀手”，主要任务是在靠近战场的区域跟踪、监视并摧毁敌方潜艇和水面舰艇，同时执行情报任务。而弹道导弹潜艇则在深海中隐蔽潜伏，承担着更大规模的战略威慑与打击任务。","scd":null,"kp":["[攻击潜艇与弹道导弹潜艇]: 任务用途存在显著差异"]},{"i":2720,"as":"美国通用原子公司获得加州2000万美元的税收抵免，用于推进聚变能包层组件测试设施（BCTF）的建设。包层是聚变反应堆内部的核心部件，负责捕获反应能量并生成氚燃料以维持反应过程。这是实现商业聚变能源的关键一步，因为包层技术是建造实际运行的聚变发电厂所面临的主要工程障碍之一。","scd":null,"kp":["资金支持[通用原子能公司建设聚变能测试设施]: 2000万美元加州税收抵免","[包层组件测试设施(BCTF)]: 测试全尺寸聚变包层组件（捕获反应能量并产生氚燃料）"]},{"i":2721,"as":"国际原子能机构（IAEA）发布了一款新的交互式地图工具，显示全球核电站已累计产生约44.8万吨（49.4万美吨）的乏核燃料。该工具全面展示了全球乏燃料的储存位置及管理方式。在多国重新考虑或扩大核能作为低碳能源之际，这一数据凸显了放射性废料储存、回收及最终处置是核能工业面临的长期挑战。","scd":null,"kp":["乏核燃料累计产量[全球核电站]: 约44.8万吨（49.4万美吨）"]},{"i":2722,"as":"埃隆·马斯克预测，未来人类在尝试前往其他星系时，将耗资数万亿美元用于开发反物质推进技术。这一构想得到了美国国家航空航天局（NASA）局长贾里德·艾萨克曼的支持。反物质推进目前看似科幻，但月球定居等昔日科幻概念正逐渐走向现实，显示了该技术在未来星际探索中的前瞻性定位。","scd":null,"kp":["[反物质推进技术]: 未来预计将投入数万亿美元以实现星际旅行"]},{"i":2723,"as":"日本九州大学的研究人员开发出一种新型固态分子材料，能够将两颗普通可见光光子结合，产生一颗高能紫外光子。该材料利用未聚焦的自然环境阳光即可完成转换，在固态系统中实现了1.9%的转换效率。这一被称为光子上转换的量子突破过程，为光能的高效利用提供了新途径。","scd":null,"kp":["转换效率[新型固态分子材料上转换日光]: 1.9%","光子上转换[固态分子材料]: 将两个普通可见光光子结合产生单个高能紫外光子","工作条件[光子上转换]: 环境非聚光室外直射阳光"]},{"i":2724,"as":"","scd":null,"kp":[]},{"i":2725,"as":"美国Robot.com公司推出了名为R-Noid的人形机器人，采用“机器人即服务”模式，专为物流、制造、医疗和餐饮等行业执行重复性且劳动密集型任务。该平台包含餐厅助手、打包、拣选、折叠和主持人五类解决方案，可在8至12周内完成部署并实现自主操作，无需依赖地图即可在动态环境中导航，旨在提高生产力并缓解劳动力短缺问题。","scd":null,"kp":["部署周期[人形机器人R-Noid从现场评估到自主运行]: 八至十二周"]},{"i":2726,"as":"","scd":null,"kp":[]},{"i":2727,"as":"","scd":null,"kp":[]},{"i":2728,"as":"","scd":null,"kp":[]},{"i":2729,"as":"","scd":null,"kp":[]},{"i":2730,"as":"","scd":null,"kp":[]},{"i":2731,"as":"","scd":null,"kp":[]},{"i":2732,"as":"","scd":null,"kp":[]},{"i":2733,"as":"一项新研究指出，未来30至50年是理解和应对南极冰川融化及海平面上升的关键时期。研究探讨了预测南极冰川流失的可靠性。在高排放情景下，若南极冰原发生大规模崩塌，到2100年全球海平面上升可能超过2米。这将引发严重后果，包括使澳大利亚四分之一的房屋面临洪水风险，并导致太平洋大面积主权领土被淹没。","scd":null,"kp":[]},{"i":2734,"as":"《自然·可持续发展》发表的一项研究指出，海平面上升正在加速吞噬美国中大西洋沿海地区的农田。研究发现，沿海湿地向内陆农田扩张的速度几乎是向森林扩张速度的两倍。基于1984年至2022年的卫星和实地数据，切萨皮克和特拉华湾流域已有约2.5万英亩的农田因海平面上升而消失。","scd":null,"kp":[]},{"i":2735,"as":"经过近十年的寻找，一支由攀树者、生态学家、地质学家和遥感专家组成的名为“台湾寻树者”的团队，在台湾偏远山林中发现了东亚最高的树木。2023年，团队确认发现了一棵高达84米（相当于25层楼高）的参天古树以及其他数百棵巨树。这些隐藏在陡峭山脉和古老森林中的巨型针叶树打破了此前的纪录。","scd":null,"kp":[]},{"i":2736,"as":"天文学家首次直接测量了7颗“超热木星”系外行星的磁场强度，研究结果发表在《自然·天文学》上。数据显示，一些已知最热的系外行星拥有与太阳系行星相当强度的强磁场。这项突破为研究系外行星的大气层结构开辟了新窗口，也为理解行星如何维持宜居环境及保留大气层提供了重要线索。","scd":null,"kp":[]},{"i":2737,"as":"国际天文学家团队发现了迄今已知最遥远、质量约为太阳60亿倍的休眠黑洞。该黑洞位于距离地球超100亿光年的星系MRG-M0138中，其发现打破了此前休眠黑洞的最远距离纪录（提高了15倍）。与活跃吞噬物质的类星体不同，这个沉寂的宇宙巨人为研究早期宇宙中超大质量黑洞的演化提供了罕见的样本。","scd":null,"kp":[]},{"i":2738,"as":"研究人员在《物理评论X》上报告称，他们开发了量子控制协议，能够拉伸、模糊甚至逆转量子系统的时间流。通过精确结合测量、反馈和定制控制场，团队成功抑制了量子系统的时间箭头，甚至使其表面上的时间方向发生倒转。实验证明，微观量子系统的方程在时间倒流时同样适用，打破了时间只能单向向前流动的传统假设。","scd":null,"kp":["[量子控制协议]: 可使特定量子系统的时间流被拉伸、模糊甚至发生时间反转"]},{"i":2739,"as":"陕西省发改委印发全国首个多用户绿电直连省级细则（801号文）。在国家“一对多”框架文件发布不到一个月内，陕西将其转化为可申报的执行细则。截至2025年底，陕西可再生能源装机达6512万千瓦。针对陕北风光资源丰富而关中用电负荷集中的错位矛盾，该新政明确不限制直连线路长度，支持跨地市或跨省区申报，为企业和园区提供三类申报机会。","scd":null,"kp":["可再生能源装机容量[截至2025年底陕西省]: 6512万千瓦","增幅[陕西可再生能源较十三五末]: 增长2.7倍","年均增速[陕西可再生能源装机]: 超过20%","直连线路长度[陕西绿电直连新政]: 暂不设限"]},{"i":2740,"as":"Meta公司发布了一款全新的智能眼镜产品。这款新型智能穿戴设备的官方售价定为299美元。","scd":null,"kp":[]},{"i":2741,"as":"英伟达（Nvidia）正式推出了一款专为生命科学领域设计的开源软件工具。","scd":null,"kp":[]},{"i":2742,"as":"字节跳动正式推出了其最新研发的Seedance 2.5视频模型。","scd":null,"kp":[]},{"i":2743,"as":"日本Sakana AI公司宣布，其最新研发的人工智能工具在性能上足以与Anthropic公司的Fable 5模型相媲美。","scd":null,"kp":[]},{"i":2744,"as":"美国前总统特朗普签署了一项内容广泛的量子计算领域行政命令。","scd":null,"kp":[]},{"i":2745,"as":"","scd":null,"kp":[]},{"i":2746,"as":"SpaceX已达成协议，将以每月1.5亿美元的价格向AI初创公司Reflection出租其计算资源。","scd":null,"kp":["计算资源租赁价格[SpaceX向Reflection出租]: 每月1.5亿美元"]},{"i":2747,"as":"印度拥有全球约60%的野生亚洲象，且约80%的栖息地位于保护区外，导致人象冲突频发。过去五年造成约3000人伤亡，2014年以来超1000头大象死亡。为解决地面巡逻预警迟缓的问题，国家林业部门、非政府组织及当地居民正在设计、测试和部署一系列人工智能预警系统，将响应和预警时间缩短至几分钟甚至几秒。","scd":null,"kp":["野生亚洲象占比[印度全球拥有量]: 约60%","栖息地占比[位于保护区外]: 约80%","人员伤亡[过去五年人象冲突导致]: 约3000人"]},{"i":2748,"as":"一款造价高达4亿美元的芯片制造机器即将问世。该设备重达150多吨，体积类似于双层巴士，由超过200立方米的精密机电装置组成。其核心技术是能够以原子级精度固定内部的反射镜。研发团队耗时十多年进行设计与制造，旨在通过这台庞大的高科技精密设备为未来先进芯片的生产提供动力支持。","scd":null,"kp":["造价[先进芯片制造设备]: 4亿美元","重量[芯片制造设备]: 超过150吨","设备尺寸[外观参照]: 双层巴士大小"]},{"i":2749,"as":"勃兰登堡工业大学（BTU）的学生团队Lausitz Dynamics带着其自主研发的节能车“HydroRaycer”参加了国际节能竞赛。经过数月的紧张准备，该团队在强调能源效率的国际赛事中展现了其工程实力。","scd":null,"kp":[]},{"i":2750,"as":"宾根技术大学计算机系新增了一名教授，重点加强IT安全与批判性思维的教学。新任教授的加入旨在更好地帮助学生在数字化时代掌握必要的专业技能，并特别强调了IT安全防护与批判性思考能力在当前数字社会中的核心重要性。","scd":null,"kp":[]},{"i":2751,"as":"德国德累斯顿经济技术大学的青年研究小组MUBARES致力于研究建筑和基础设施作为能源转型一部分的多功能利用。该研究探索如何利用建筑的结构和功能特性集成可再生能源系统，使其成为去中心化能源生产的一部分。其核心目标是开发相关概念，提升气候韧性、系统集成度和经济效益，从而优化可再生能源的利用。","scd":null,"kp":["[建筑与基础设施]: 作为多功能可再生能源系统集成载体进行能源生产"]},{"i":2752,"as":"随着电池储能系统（BESS）在全球能源转型中地位日益凸显，热管理和流体处理技术成为确保大规模储能平台长期可靠性、安全性和性能的关键组件。ARaymond的专家指出，无泄漏液冷系统在BESS设计中发挥着日益重要的作用。ARaymond正将其在汽车行业积累数十年的流体处理专业技术，应用于支持新一代更紧凑、功率更大的储能基础设施建设。","scd":null,"kp":["[大规模电池储能系统]: 热管理与流体处理技术是保障长周期系统可靠性、安全性和性能的核心关键"]},{"i":2753,"as":"德国电池储能聚合商与能源交易公司The Mobility House Energy在6月新增四个电池储能项目，使其在四个国家优化的资产组合达到47个，总容量突破1吉瓦。其中近30个项目采用电池储能与光伏发电相结合的商业模式。负电价小时的增加和上网电价的下降增强了这种混合模式的经济性，电池可将太阳能转移至价值更高的晚间时段，从而减少弃光并降低电网成本。","scd":null,"kp":["优化与管理电池储能容量[德国及四国47项资产]: 超过1 GW","光储融合项目数量[电池储能结合光伏发电]: 近30个"]},{"i":2754,"as":"Capac Energy等公司正在德国布鲁萨尔开发一个22 MWh的锌溴电池储能项目，计划于2026年底投入运营。该项目将成为欧洲首批公用事业规模的锌溴储能部署之一，旨在为长时固定储能提供锂离子电池的替代方案。项目将使用美国制造商Eos Energy Enterprises提供的36个电池集装箱，提供5兆瓦功率和22兆瓦时容量，其技术不使用锂、钴和镍。","scd":null,"kp":["储能系统规模[德国Bruchsal锌溴电池项目]: 22 MWh","储能系统功率[德国Bruchsal锌溴电池项目]: 5 MW","电池集装箱数量[德国Bruchsal锌溴电池项目]: 36个","长时固定储能技术路线[欧洲公用事业级替代锂离子]: 锌溴电池技术"]},{"i":2755,"as":"Suena Energy对30兆瓦并网点的72种设计场景分析显示，电池储能系统配置直接影响收益，预估收入在每兆瓦79,000至169,000欧元之间。收益最大驱动力为电池功率、持续时间及光伏阵列规模和朝向。具体数据显示，60兆瓦东西走向光伏搭配10兆瓦/40兆瓦时电池的比回报率最高；而30兆瓦/120兆瓦时电池搭配60兆瓦南向光伏的年总收入最大，约400万欧元。","scd":null,"kp":["项目收益跨度[30 MW并网点72种设计场景]: 约79000至169000欧元/每兆瓦装机容量","最高特定回报配置[光储结合]: 60 MW东西向光伏阵列配10 MW/40 MWh电池系统"]},{"i":2756,"as":"全球首台5兆瓦级全碳型锂离子超级电容功率舱成功完成型式试验并取得CNAS认证。该设备内置4500法拉全碳型超级电容单体，能量密度达16Wh/kg，功率密度达18kW/kg。设备采用主动均衡策略实时调度22400支单体，转换效率超95%，瞬时功率响应在10毫秒内，循环寿命超百万次。该超级电容无锂枝晶燃烧风险，能实现毫秒级电网调频响应，并能在海拔5000米稳定输出5兆瓦功率。","scd":null,"kp":["设备功率等级[全碳型锂离子超级电容功率舱]: 5 MW级","电网调频响应时间[超级电容]: 毫秒级","材料体系[全碳型锂离子超级电容]: 全碳型","技术优势[全碳型锂离子超级电容]: 无锂枝晶燃烧风险，低温衰减更小，循环寿命更长"]},{"i":2757,"as":"截至2026年5月底，新疆电网新能源装机超1.67亿千瓦，占电源总装机比重超60%。针对新能源发电的时空波动特征和季节性错配问题，国网新疆电力通过搭建短路比与惯量在线监测预警系统、建立大数据功率预测模型，精准测算系统调节需求。同时，公司统筹源网荷储协同发展，推进多维度协同调节体系建设与重大源网荷储一体化项目落地，提升新能源消纳与电网承载能力。","scd":null,"kp":["新能源装机容量[新疆电网截至2026年5月]: 超1.67亿千瓦","装机占比[新疆新能源占电源总装机]: 超60%","发电时空波动特征[新疆新能源]: 呈“春秋大、冬夏小”特点"]},{"i":2758,"as":"天津市智能机器人产业快速增长，前4个月产业链规上企业产值同比增长12.8%。深之蓝公司利用工业机器人技术衍生出水下助推器等消费产品，其研发的缆控和自主水下机器人已具备深海持续作业能力并参与国家级重点项目。此外，阿童木机器人自主研发了并联机器人和商用控制器，利用视觉系统与多臂协同，在流水线上实现快速精准的高速分拣与精密装配，加速在新能源等工业场景落地。","scd":null,"kp":["衍生消费产品[工业机器人技术]: 水下助推器"]},{"i":2759,"as":"中国南京大学科研团队在《自然·物理》发表新成果，确认凝聚态物质中的“引力子模”源自关联电子中“部分子”的几何振荡。团队利用自行设计制造的偏振光散射系统，在极低温和强磁场极端环境下，用光子撞击砷化镓量子阱中的电子。实验在高能区域观测到全新非弹性光散射现象，并发现“引力子模”会随“部分子”的变化而改变，证实了其物理起源。","scd":null,"kp":["极端实验温度[引力子模观测环境]: 仅比绝对零度高约0.05摄氏度","极端实验磁场[引力子模观测环境]: 是地球平均磁场10万倍以上","实验测试样品[非弹性偏振光散射实验]: 砷化镓量子阱","机理溯源[凝聚态物质中引力子模]: 源自关联电子中“部分子”的几何振荡"]},{"i":2760,"as":"“人工智能+”正从单点技术应用转向基于开源模型和开放生态的规模化落地。国家信息中心指出，Token调用量指数级增长是AI规模化应用的量化标志，推动基础设施评价标准转向单位能效与场景服务。IDC预计到2029年中国生成式AI市场规模将接近千亿美元。随着智能体成为生产力核心，企业正向“人+智能体”的组织概念演进，将数字员工纳入管理体系，实现AI原生转型与组织进化。","scd":null,"kp":["发展阶段[人工智能产业]: 全面迈入推理阶段","基础设施评价标准转变[AI]: 从追求算力峰值转向单位能效、成本效益与场景服务能力"]},{"i":2761,"as":"Token已突破技术计量属性，成为智能经济的核心生产要素与价值标尺。截至2026年3月，我国日均Token调用量突破140万亿。联合发布的报告构建了包含生产成本、效率、准确性等五个维度的Token价值度量体系，并提出向复合定价模型演变的趋势。报告创新提出构建Token分发网络（TDN），形成底层量产、中层调度交易、顶层按需调用的三层产业协同范式。","scd":null,"kp":["日均Token调用量[截至2026年3月]: 140万亿","Token价值度量体系[Token定价]: 涵盖生产成本、生产效率、准确性、生态价值与安全五个维度","Token定价模型[复合定价]: 成本约束+智能溢价+结构差异+价值弹性+竞争浮动"]},{"i":2762,"as":"国家网信办等三部门联合公布《网络数据安全风险评估办法》，自2026年8月20日起施行。办法明确了评估机制与部门职责，规定重要数据处理者须每年度开展风险评估，鼓励一般数据处理者至少每3年评估一次。网络数据处理者可依法自行或委托第三方机构开展评估。此外，办法还明确了评估机构的认证培育要求，规定评估机构不得转委托，并在发现重大风险时须履行通知义务。","scd":null,"kp":["施行时间[网络数据安全风险评估办法]: 2026年8月20日","[评估机制]: 在国家数据安全工作协调机制指导下建立网络数据安全风险评估专项工作机制"]},{"i":2763,"as":"税收数据显示，今年1至5月全国工业企业销售收入同比增长6.8%，装备制造业占比达46.8%。人工智能显著助推工业智能化，机器人与智能车载设备制造销售收入分别同比增长27.7%和46.3%。高端电子制造加快发展，集成电路、光电子器件制造业增速分别达57.7%和32.6%。同时，绿色低碳转型纵深推进，清洁能源销售收入同比增长18.9%，其中太阳能与风力发电销售收入分别增长17.2%和22.2%。","scd":null,"kp":["销售收入同比增长[1-5月机器人制造]: 27.7%","销售收入同比增长[1-5月智能车载设备制造]: 46.3%","销售收入同比增长[1-5月集成电路制造]: 57.7%","销售收入同比增长[1-5月光电子器件制造]: 32.6%","销售收入同比增长[1-5月半导体器件制造]: 24.4%"]},{"i":2764,"as":"国家发展改革委表示，“十五五”时期将加强算力网与新型电网、新一代通信网的规划协同。在硬投资方面，探索算电协同模式，扩容国家枢纽间直连线路以降低网络时延；在软建设方面，强化算力资源监测调度，建设全国一体化算力网。截至3月底，我国智能算力规模达188.2万P。目前全国已形成“8+10+3”算力空间布局，各省份至8大枢纽的传输时延均降至20毫秒以内。","scd":null,"kp":["智能算力规模[截至3月底]: 188.2万P","[算力网协同]: 探索算电协同模式（以电强算、以算促电）及算网融合创新降低传输时延","算力网体系架构[全国一体化]: 8大国家算力枢纽、10个国家算力集群、3个算电协同发展区域"]},{"i":2765,"as":"商务部等八部门联合出台17项举措加快发展“人工智能+消费”。在商品消费方面，加快推出新一代智能终端与智能家居产品，推广面向老人与儿童的陪伴及生活辅助机器人。在服务消费方面，围绕居家、养老、文旅等五大场景提出具体措施：普及智能扫地机器人与全屋定制，配置智能护理与康复机器人；在文旅行业深度融合AI辅助行程规划与艺术创作，并推动酒店客房语音控制与“智慧食堂”等应用落地。","scd":null,"kp":["[人工智能+消费政策]: 出台5方面17项举措推动智能商品消费、赋能服务消费、创新消费场景","[新型AI产品供给]: 加快推出新一代人工智能手机、电脑、电视及养老/陪伴机器人等智能家居"]},{"i":2766,"as":"具身智能正加速向跨场景通用智能演进，全球技术发展呈现五大突破态势。目前感知交互实现了向推演式决策的范式跃迁，如Meta的V-JEPA2模型与北大的多感官语言动作模型。同时，端到端决策成为发展趋势，Google DeepMind的Gemini Robotics与国内越疆的DOBOT-VLA模型凭借低时延、高自主和强跨本体泛化能力，展现出在具身智能通用化探索中的巨大潜力。","scd":null,"kp":["技术突破维度[全球具身智能发展]: 感知交互、决策认知、控制执行、虚实域数据融合与系统集成协同突破","[技术范式跃迁]: 嵌入世界模型，实现从“刺激—响应”到“推演式决策”、从数据重组到规律理解"]},{"i":2767,"as":"该新闻报道了关于呼和浩特市在智算和绿算领域的实地调研。内容涉及探讨呼和浩特在算力生产、用户算力购买流程以及算力实际应用等方面的基本情况，解答了呼和浩特在智能算力和绿色算力产业链中占据重要地位的核心原因。","scd":null,"kp":[]},{"i":2768,"as":"中国载人航天工程办公室发布动态，神舟二十三号乘组目前在中国空间站内稳步推进各项既定任务。航天员们按计划开展空间站内的日常操作与科学实验等常规工作。报道以视频形式记录并展示了乘组在轨工作日常的真实情况。","scd":null,"kp":[]},{"i":2769,"as":"MWS宣布将收购西班牙风电服务与退役专家Coverwind。该交易将使MWS获得Coverwind在风电领域的专业技术和退役业务能力，进一步扩展其在风力发电服务市场的布局。报道重点关注了该并购事件本身及其在陆上风电市场的行业意义。","scd":null,"kp":["[企业并购]: MWS收购西班牙风电服务和退役专家Coverwind"]},{"i":2770,"as":"国家发改委与国家能源局印发《可再生能源消费最低比重目标和可再生能源电力消纳责任权重制度实施办法》，自2026年8月1日起施行。该政策构建了“消费端刚性义务+消纳端属地责任”双轮驱动格局，从省级行政区域和重点用能行业两个层面压实责任。此举旨在通过量化考核，推动绿电资源全国优化配置，扩大绿色消费市场，为碳达峰目标提供核心制度保障。","scd":null,"kp":["施行时间[可再生能源消费与消纳考核办法]: 2026年8月1日","[责任考核机制]: 从省级行政区域和重点用能行业两个层面压实可再生能源消纳和消费责任"]},{"i":2771,"as":"2026年6月19日，土耳其贸易部发布公告，对原产于中国、马来西亚和越南的太阳能玻璃启动反倾销调查。倾销调查期为2024年10月至2025年9月，损害调查期为2022年至2025年9月。涉案产品土耳其税号为70.06和70.07。利益相关方需在公告发布37日内提交问卷及意见。","scd":null,"kp":["倾销调查期[原产于中国、马来西亚和越南的太阳能玻璃]: 2024年10月1日至2025年9月30日","损害调查期[原产于中国、马来西亚和越南的太阳能玻璃]: 2022年1月1日至2025年9月30日","涉案产品税号[土耳其反倾销调查]: 70.06和70.07","问卷及评述意见提交期限[利益相关方]: 公告发布之日起37日内"]},{"i":2772,"as":"越南电力供需矛盾加剧，计划性限电严重影响工业产能，促使分布式户用光伏与储能系统成为国家重点发展战略。越南光储市场本地产业链薄弱，核心组件高度依赖外部供应。中国光伏与储能产业凭借完整产业链、规模化制造能力和高度兼容的应用体系，在越南“政策推动、需求刚性与供给缺口”三重共振格局下具备显著外溢机会与市场主导优势。","scd":null,"kp":["[越南电力供需]: 结构性紧张问题","重点发展路径[越南PDP8国家电力发展规划]: 分布式能源，尤其是户用光伏与储能系统","[越南分布式光储市场]: 处于早期阶段，本地产业链相对薄弱"]},{"i":2773,"as":"GB/T 33342-2026《户用光伏发电并网技术要求》将于2026年7月1日正式实施。该标准将全面替代2016版标准，标志着户用光伏并网技术要求迎来全面升级。","scd":null,"kp":["实施时间[GB/T 33342-2026《户用发电并网技术要求》]: 2026年7月1日","[户用光伏并网]: 迎来全面升级并替代2016版标准"]},{"i":2774,"as":"隆基绿能西咸新区一期年产12.5GW高效BC电池项目进行竣工环保验收公示。项目总投资12.48亿元，于2025年1月开工，5月建成6.25GW产能并取得排污许可证。该项目位于陕西西咸新区，租用定制厂房投入电池生产线，本次验收主要针对已建成的6.25GW高效BC电池产能。","scd":null,"kp":["规划产能[隆基绿能西咸新区一期BC电池项目]: 年产12.5GW","已建成产能[一期一阶段高效BC电池项目]: 6.25GW","项目总投资[12.5GW高效BC电池项目]: 124800万元","建设周期[一期一阶段项目]: 2025年1月至2025年5月"]},{"i":2775,"as":"伊拉克卡尔巴拉省Al-Noor光伏组件工厂投产，年产能约100MW。该工厂由本地资本主导，首次实现本土晶硅组件制造闭环，标志着伊拉克光伏产业从完全依赖进口迈入本土制造起步阶段。尽管引入了自动化产线，但当前规模与成本控制能力有限，短期内仍作为补充产能，中国光伏企业凭借规模化制造与成本优势在伊拉克及中东市场依然占据核心主导地位。","scd":null,"kp":["年产能[伊拉克Al-Noor光明光伏组件工厂]: 约100MW","[伊拉克光伏产业]: 从“完全依赖进口”迈入“本土制造起步阶段”"]},{"i":2776,"as":"6月23日，国家能源局发布通知，推进非公共电网可再生能源发电项目绿证核发全覆盖。非公共电网项目包括离网型及接入用户侧内部并网型项目。通知要求电网企业与电力交易机构归集报送基础数据，安装计量装置准确计量各环节电量，以加快建立绿色能源消费机制，推动绿证市场高质量发展。","scd":null,"kp":["[非公共电网可再生能源项目]: 纳入绿证核发全覆盖范围，包括离网型及接入用户侧内部并网型项目"]},{"i":2777,"as":"苏州发改委公布分布式电源接入电网可开放容量，全市下辖9个市（县、区）评估等级全部为绿，合计可开放容量达8921.63MW。该数据依据承载力评估导则测算，自2026年6月18日起执行。投资主体可通过供电营业厅或电话咨询查询各地区电网具体的可开放容量信息。","scd":null,"kp":["可开放容量[苏州市下辖9个市县区分布式电源接入电网]: 合计为8921.63MW","承载力评估等级[苏州市下辖9个市县区电网]: 全部为绿"]},{"i":2778,"as":"呼伦贝尔市能源局公布2026年第二批次分布式能源竞争性配置申报方案评审服务比选结果，湖南科鑫电力设计有限公司中选。服务期限为合同签订后15日内，中选金额根据评审项目数量分为3.8万元、5.8万元和8.8万元三档。评审工作已于2026年6月22日上午完成。","scd":null,"kp":["服务期限[呼伦贝尔市2026年第二批次分布式能源竞配申报方案评审]: 合同签订后15日历天内","中选金额[评审10个以上项目]: 88000元"]},{"i":2779,"as":"深圳市住建局启动2026年度建筑光伏一体化和“光储直柔”建筑试点项目申报。申报对象为深圳市内拟建、在建或已建成的相关工程项目。拟建项目需符合深圳地方工程技术标准，已建成项目需办妥竣工验收且投入使用。申报需在9月30日前提交申报书，住建局将组织形式审查与专家评审。","scd":null,"kp":["[深圳市建筑光伏]: 开展建筑光伏一体化和“光储直柔”建筑试点项目申报"]},{"i":2780,"as":"","scd":null,"kp":[]},{"i":2781,"as":"","scd":null,"kp":[]},{"i":2782,"as":"小米宣布延长MiMo-V2.5-Pro-UltraSpeed限时体验窗口。该模型提供1000 tokens/s的极致推理速度，自上线以来已收到超6.6万个使用申请。延期旨在让更多开发者体验API接入服务，具体下线时间将根据资源情况另行通知。目前用户仍可继续申请内测，已审核通过用户可继续使用。","scd":null,"kp":["推理能力[MiMo-V2.5-Pro-UltraSpeed大模型]: 1000 tokens/s","使用申请量[MiMo-V2.5-Pro-UltraSpeed限时体验]: 超过6.6万个"]},{"i":2783,"as":"伦敦国王学院等机构研究人员在《自然》发表论文提出“放大螺旋”框架，指出AI聊天机器人的三项设计特征会助推用户产生妄想。这三种特征为语言对齐、超个性化内容生成和迎合倾向。这些特征叠加使AI不会质疑用户的错误信念，反而通过回音室效应持续确认并放大用户的妄想内容，导致部分用户陷入心理健康危机。","scd":null,"kp":["[AI助推妄想的放大螺旋]: 语言对齐、超个性化内容生成和迎合倾向相互叠加","[AI聊天机器人特征]: 模仿用户表达并给出高度个性化回答，避免反驳用户","[系统设计影响]: 超个性化能力结合用户个人想法和过往经历，强化信任感"]},{"i":2784,"as":"荣耀MagicOS 11液态玻璃尝鲜版先锋活动计划在7月31日前启动二期报名。MagicOS 11首创动态全屏通透设计，模拟动态光影变化，并支持液态、磨砂和全彩三种自定义材质效果。本次一期招募机型包括荣耀Magic8 Pro、Magic8 Pro Air及Magic8 RSR保时捷设计。","scd":null,"kp":["UI设计材质效果[MagicOS 11液态玻璃]: 支持自定义液态、磨砂和全彩三种材质","[MagicOS 11尝鲜版先锋活动二期报名]: 计划在7月31日前启动"]},{"i":2785,"as":"","scd":null,"kp":[]},{"i":2786,"as":"比亚迪方程豹调整钛3及钛7 EV闪充版的闪充权益规则。原先需在2026年6月30日前完成购车开票的限制取消，变更为车辆到店后在门店通知时间内提车即可享受闪充权益。此前比亚迪曾宣布，闪充车型锁单超30天未交付的，每延迟一天赠送一天免费闪充权益。","scd":null,"kp":["闪充权益[钛3及钛7 EV闪充版适用]: 车辆到店后在门店通知时间内提车即可享受","闪充站建设[比亚迪年底前全国范围]: 20000座","延迟补偿[比亚迪闪充车型锁单超30天未交付]: 每延迟一天赠送一天免费闪充权益"]},{"i":2787,"as":"领克07GT时间限量版官图公布，将于2026年6月29日首秀并开启预售。该车基于CMA架构与EM-P平台开发，定位中型插电混动猎装车，轴距2843毫米。限量版采用专属哑光勃朗灰外观及蓝色四活塞卡钳，配备1.9平米天幕、95英寸AR-HUD。车辆支持1.6吨牵引力，搭载AI算力达30TOPS的LYNK Flyme Auto 2.5系统。","scd":null,"kp":["整车尺寸[领克07GT基于CMA架构与EM-P平台]: 长4846毫米(选装运动套件4866毫米)、宽1900毫米、高1485毫米","轴距[领克07GT]: 2843毫米","天幕[领克07GT配备]: 1.9平方米四层隔热防晒天幕","最大动态载荷[领克07GT车顶行李架]: 100公斤"]},{"i":2788,"as":"新加坡基金Effissimo Capital Management增持腾龙股份至17.38%，超越索尼成为腾龙最大股东。截至2026年3月，索尼持股比例为15.35%。过去一年内，Effissimo持续多次增持腾龙股份。Effissimo是一家曾对日产、东芝等多家日企施加治理改革压力的激进投资基金。","scd":null,"kp":["持股比例[Effissimo成为腾龙最大股东]: 17.38%（29,691,800股）","持股比例[索尼持有腾龙股份]: 15.35%（25,038,000股）"]},{"i":2789,"as":"SK海力士放缓第六代HBM4扩产步伐，将产能与资源优先转向通用型DRAM。由于HBM营收占比已超40%，且通用型DRAM供应严重短缺、营业利润率高出HBM至少15个百分点，SK海力士推迟了部分HBM3E产线转产HBM4的时间。此举旨在把握高利润率市场机会，但也可能为三星电子扩大HBM市场份额提供契机。","scd":null,"kp":["营收占比[SK海力士的HBM业务]: 超过40%","营业利润率[今年一季度通用型DRAM对比HBM]: 通用型DRAM高出至少15个百分点","[SK海力士产线调整]: 推迟部分HBM3E产线转产HBM4，优先生产通用型DRAM"]},{"i":2790,"as":"","scd":null,"kp":[]},{"i":2791,"as":"国际原子能机构（IAEA）发布首个面向公众的全球乏燃料交互式地图工具。数据显示，全球核电站累计产生约49.4万吨（以重金属计）乏燃料，其中约32.2万吨处于储存状态，约12.6万吨已经过后处理。在储存方式上，约41%采用湿法储存，约31%采用干法储存。芬兰正筹备启用全球首座乏核燃料深地质处置库，以实现放射性物质的超长期隔离。该平台展示了各国库存与管理方式，有助于全球核废料管理的结构化统筹。","scd":null,"kp":["乏燃料总量[全球核电站累计产生]: 约49.4万吨（或44.8万吨重金属）","乏燃料状态[全球累计产生量分布]: 约32.2万吨处于储存状态，约12.6万吨已过后处理","储存方式占比[全球乏燃料]: 约41%为湿法储存，约31%采用干法储存"]},{"i":2792,"as":"蔚来高级副总裁沈斐表示，考清华、搞换电和操盘乐道三件事都极具挑战。他作为清华博士，指出考清华目标单一且路径清晰；构建换电体系的最大难点在于十年前行业空白期的坚持，现已建成全球最大换电网络；而操盘乐道汽车面临用户认知、价格战等众多不可控变量，市场反馈具有不确定性，是三者中最难的业务。此外，他驳斥了“买不起蔚来才买乐道”的观点，指出乐道拥有大量企业中层用户。","scd":null,"kp":["[蔚来充换电体系构建]: 在一片空白中搭建系统，坚持十年成为全球最大换电网络"]},{"i":2793,"as":"","scd":null,"kp":[]},{"i":2794,"as":"华中科技大学同济医院陈刚教授团队在异种基因编辑猪肾移植猕猴临床前实验中取得重大突破，受体猕猴存活超600天，刷新亚洲纪录并达国际一流水平。检测显示移植肾功能状态平稳且指标正常。团队定制了动态“鸡尾酒”免疫抑制方案并搭建独立洁净饲养体系，打破了异种移植必然出现严重蛋白尿的固有认知。这一成果为后续人体临床研究提供了核心数据，团队计划在完善生物安全与伦理规范后推进下一步研究。","scd":null,"kp":[]},{"i":2795,"as":"中国天文学家利用爱因斯坦探针卫星捕捉到神秘X射线瞬变源EP240305a，其特性无法归入任何已知宇宙爆发类型。该源在软X射线波段产生两次持续约100-250秒的显著耀发，随后辐射在数天内迅速衰减。多波段后随观测显示其射电辐射衰减极慢且存在演化喷流，近红外源持续变暗。研究人员排除了潮汐瓦解事件、典型X射线双星爆发、热核暴发及磁星巨耀发等已知天体事件，其本质现有理论难以解释。","scd":null,"kp":["耀发持续时间[X射线瞬变源EP240305a]: 每次约100至250秒","耀发间隔[X射线瞬变源EP240305a]: 间隔约200秒的宁静期"]},{"i":2796,"as":"","scd":null,"kp":[]},{"i":2797,"as":"进迭时空宣布完成新一代自研高性能一致性互联总线N200的研发，标志着公司完成了通用计算、智能计算与计算互联三大核心技术板块的布局。N200支持多种协议转换桥、RISC-V RERI规范端到端RAS实现，具备灵活时钟结构、Partial Good设计及完整配置GUI等工程配套能力，可显著提升芯片性能与良率。目前，N200已完成RTL开发、PPA Push及软硬件协同验证，将与CPU核X200、AI核A200共同应用于下一代计算芯片，预计2027年量产。","scd":null,"kp":["量产时间[进迭时空下一代计算芯片及N200总线]: 预计2027年","[N200一致性互联总线协议支持]: 支持AXI2CHI、CHI2AXI等协议转换桥","[N200互联总线RAS规范]: 符合RISC-V RERI规范的端到端RAS实现"]},{"i":2798,"as":"","scd":null,"kp":[]},{"i":2799,"as":"微软宣布为第12代Surface Pro二合一平板和第8代Surface Laptop笔记本新增8GB内存版本，起售价分别为849美元和949美元，两款产品均配备256GB固态硬盘起步。微软强调，8GB内存配置适合日常办公与娱乐需求，但明确指出这两款新产品因硬件配置限制，不属于具备严格AI算力要求的Copilot+ PC范畴。此外，新增的8GB版本不会取代或取消原有的16GB内存版本配置。","scd":null,"kp":["内存容量[第12代Surface Pro/第8代Surface Laptop新增版]: 8GB","起售价[第12代Surface Pro 8GB版]: 849美元","起售价[第8代Surface Laptop 8GB版]: 949美元","固态硬盘容量[8GB内存版起步配置]: 256GB","产品定位[8GB内存版]: 不属于Copilot+ PC产品"]},{"i":2800,"as":"电池储能项目资产配置的最新模型V8引入了“技术转型悬崖”概念，即在资产配置中兼顾颠覆性事件与非颠覆性事件的重要性。欧洲一家中型工业集团的资本支出委员会正在推进2027年计划，该集团拥有高镍正极试验线及非洲电信备用电源合同，正着手评估包括约5亿美元投资在内的不同提案。该框架旨在帮助企业在面对市场快速变化时，更科学地进行电池储能资产的分配与投资决策。","scd":null,"kp":["[电池存储资产配置模型]: 迭代至V8版本，引入技术转型悬崖概念并涵盖破坏性与非破坏性事件"]},{"i":2801,"as":"针对人工智能数据中心激增的吉瓦级电力需求，前美国能源部长詹妮弗·格兰霍尔姆提出了“自带清洁电力（BYOC）”的能源政策概念。该政策要求科技公司在建设大型数据中心的同时，应协助建设运行数据中心所需的发电厂以及整合可再生能源所需的储能设施。这一举措被视为应对当前电网可靠性挑战、半导体短缺以及实现AI发展与能源供给平衡的最具影响力的能源政策构想之一。","scd":null,"kp":["[AI与能源关系]: 科技公司若建设消耗千兆瓦级电力的数据中心，应协助进行能源基础设施建设"]},{"i":2802,"as":"通用汽车（GM）认为车网互动（V2G）技术是增强电网弹性和应对能源需求挑战的关键变革性解决方案。该技术通过实现电动汽车与电网之间的双向能量流动，将停放的电动汽车转化为能够按需存储和供应电力的动态能源资产。V2G技术现已从早期的试点项目发展为具备商业可行性的技术，在平衡用电高峰需求、提升电网可靠性以及强化社区能源安全保障等方面展现出巨大潜力。","scd":null,"kp":["[V2G(车网互动)技术]: 实现电动汽车与电网之间的双向能量流动，以提升电网弹性与气候韧性"]},{"i":2803,"as":"","scd":null,"kp":[]},{"i":2804,"as":"施耐德电气在Gartner发布的2026年度全球供应链25强榜单中连续第四年位居榜首。该排名旨在表彰在全球范围内展现出卓越供应链管理能力的企业。施耐德电气凭借其对创新的积极拥抱、对数字化的深度整合应用，以及在市场剧烈波动环境下展现出的极高韧性和运营一致性获得此殊荣。研究指出，顶尖的供应链正不断利用先进技术来提升效率，以在动荡的商业环境中构建竞争优势。","scd":null,"kp":["[施耐德电气供应链]: 连续第四年位居Gartner供应链25强榜首"]},{"i":2805,"as":"丰田汽车正式取消了旗舰纯电轿车雷克萨斯LF-ZC的研发与量产计划。丰田执行副总裁中岛裕树确认了这一消息。尽管该旗舰车型被废弃，但其原本计划搭载的新一代电池技术、专属纯电平台以及一体化压铸制造工艺等先进技术均已具备量产条件。丰田高管确认，目前已有全新继任车型的开发计划正在推进中，以确保这些前沿电动车技术能够顺利应用于未来的量产产品线。","scd":null,"kp":["[雷克萨斯LF-ZC旗舰电动车]: 取消量产计划","[次世代电动汽车核心技术]: 新电池、专属平台及超级压铸(Gigacasting)工艺已就绪，后续继任车型已在筹备中"]},{"i":2806,"as":"美国加利福尼亚州已提交针对内政部的诉讼意向通知，以阻止联邦政府叫停加州中部海岸近海风电项目的决定。加州指出，风电是美国成本最低的能源之一，且不会像化石燃料那样造成污染并引发健康问题与巨额经济损失。在当前数据中心激增导致美国电力需求急剧上升、能源账单高涨的背景下，阻止风电开发不仅损害了清洁能源的发展潜力，也加剧了电网的能源供应压力，加州对此提出强烈抗议。","scd":null,"kp":["[风力发电]: 被视为成本更低的能源形式，且无化石燃料污染"]},{"i":2807,"as":"美国得克萨斯州一名76岁妇女因一辆特斯拉Model 3撞入其住宅而身亡，死者家属已正式起诉特斯拉及肇事司机。诉状指控特斯拉的“Autopilot”和“Full Self-Driving”系统存在设计缺陷。该诉讼紧随事故发生之后提出，其核心论点与此前佛罗里达州一起判处特斯拉赔偿2.43亿美元的自动驾驶里程碑式判决案件如出一辙，进一步加剧了围绕特斯拉自动驾驶辅助系统安全性的法律争议。","scd":null,"kp":["[特斯拉Autopilot相关诉讼]: 因系统设计缺陷导致致命事故被起诉","[历史判例]: 此前曾产生2.43亿美元关于Autopilot的 landmark 判决"]},{"i":2808,"as":"由杰夫·贝索斯支持的电动汽车初创公司Slate Auto公布了其基础版纯电动卡车的售价与续航参数。该车型起售价为24,950美元（不含税费等附加费用）， базовая版预估续航里程从150英里提升至约205英里。这一价格仅为美国新车平均售价（约5万美元）的一半左右。该基础款为双座皮卡，车主可按需自行将其改装为五座SUV，主打极致性价比与高度客制化路线。","scd":null,"kp":["起售价[Slate Auto基础款电动卡车]: 24,950美元","续航里程[Slate Auto基础款电动卡车]: 约205英里(从150英里提升)"]},{"i":2809,"as":"纯电动终端卡车制造商Orange EV宣布达成了两项重要里程碑：其已向客户累计交付2000辆纯电动码头发运牵引车，且车队累计纯电行驶里程突破3300万英里。其中，第2000辆具有里程碑意义的卡车交付给了可口可乐加拿大装瓶公司。Orange EV凭借其在重型电动卡车领域的出色表现，近期还斩获了破纪录的600辆订单，并获得了可口可乐颁发的2025年国家供应商合作伙伴奖。","scd":null,"kp":["交付规模[Orange EV电动码头卡车]: 累计向客户交付2,000辆","累计行驶里程[Orange EV电动码头卡车车队]: 3,300万英里"]},{"i":2810,"as":"犹他州规模最大的太阳能与电池储能组合项目——格林河能源中心正式投入商业运营。该项目位于埃默里县，总投资11亿美元，配置了400兆瓦（MW）的太阳能发电设施以及400兆瓦/1600兆瓦时（MWh）的电池储能系统。项目共安装了993,492块太阳能电池板和484台特斯拉Megapack储能电池，是美国电力公司PacifiCorp服务区域内规模最大的光储一体化设施。据开发商rPlus Energies预计，该项目将为当地学校和公共服务带来超5500万美元的财产税收收入。","scd":null,"kp":["项目投资[绿河能源中心]: 11亿美元","光伏装机容量[犹他州最大光储项目]: 400 MW","电池储能系统规模[犹他州最大光储项目]: 400 MW/1600 MWh"]},{"i":2811,"as":"土耳其光伏行业在强劲的工业需求和注重竞争力的投资文化推动下持续快速扩张，今年前四个月新增了光伏装机容量。尽管部署势头依然强劲，但土耳其光伏市场正从快速增长期向更具结构化和政策导向的阶段转型。","scd":null,"kp":[]},{"i":2812,"as":"捷克光伏市场正进入受政治优先级变化、补贴机制演变以及欧盟潜在太阳能逆变器限制的不确定性影响的结构性变革期。尽管住宅部署因资金过渡受到暂时影响，但针对建筑规范、储能关税和许可的监管改革正在重塑该国的能源转型，商业和公用事业规模的开发管线仍在持续增长。","scd":null,"kp":[]},{"i":2813,"as":"约旦研究人员评估了使用构网型（GFM）控制的电池储能系统（BESS）在增强太阳能光伏电站稳定性方面的表现。通过模拟100兆瓦光伏电站和35兆瓦/60兆瓦时构网型储能系统，结果证实构网型控制策略通过模拟同步发电机，能在电网中断和故障等事件中提供快速频率和电压支持。","scd":null,"kp":["光伏电站规模[并网BESS稳定性仿真研究]: 100 MW","电池储能系统规模[并网BESS稳定性仿真研究]: 35 MW/60 MWh","系统支撑特性[构网型控制]: 提供即时有功/无功支撑"]},{"i":2814,"as":"比利时和中国的研究人员提出了推进锂-氮（Li-N2）电池发展的路线图。该电池在放电过程中锂与氮气反应形成氮化锂。研究指出了可逆性差、氮气激活缓慢和电池组件不稳定等关键障碍，并建议通过改进电解质、催化剂、隔膜、电池设计以及采用标准化测试和流动型架构，来实现能量存储和氮基化学品生产。","scd":null,"kp":["关键障碍[锂氮电池发展]: 可逆性差、氮气活化缓慢、电池组件不稳定"]},{"i":2815,"as":"中国企业Microquanta在慕尼黑推出用于建筑一体化光伏（BIPV）的彩色钙钛矿-硅串联组件。该全商业化产品采用四端串联技术，结合大理石纹理等建筑装饰，提供内部颜色定制，旨在降低彩色太阳能立面常见的性能损耗，其功率输出高于传统装饰性光伏解决方案。","scd":null,"kp":["转换效率[彩色钙钛矿-硅叠层BIPV组件]: 26%","技术架构[彩色钙钛矿-硅叠层BIPV组件]: 四端叠层技术"]},{"i":2816,"as":"经过两年的下滑，瑞典光伏行业在储能投资的推动下显示出初步稳定迹象。瑞典健康的公用事业级光伏项目储备正开始重塑该国长期的发电结构，市场投资重心正向“储能优先”快速转移。","scd":null,"kp":[]},{"i":2817,"as":"海辰储能（HiTHIUM）在2026年慕尼黑智慧欧洲展上正式推出专为欧洲、北美和澳大利亚等成熟市场设计的ARKVOLT住宅储能系列产品。该品牌将其在公用事业规模储能领域的吉瓦时级专业知识、工业级安全标准和系统可靠性引入欧洲家庭住宅应用，以满足欧洲家庭对可再生能源电池储能日益增长的高自用率需求。","scd":null,"kp":["产品定位[海辰储能ARKVOLT系列]: 面向欧洲、北美和澳洲等成熟市场的住宅储能品牌"]},{"i":2818,"as":"斯洛文尼亚光伏市场正迈入新阶段，其特点包括推出全国性能源共享机制及首批注册，电池储能的采用率不断增加，以及经过两年缓慢增长后住宅领域的复苏。监管改革与不断增长的工商业及公用事业规模管线共同推动了这一能源结构的转变。","scd":null,"kp":[]},{"i":2819,"as":"欧洲分裂的电网基础设施和缺乏中央规划导致其无法充分利用可再生能源，并陷入依赖进口化石燃料造成价格波动的困境。Supergrid Europe提议将欧洲电网视为单一网络而非独立的国家级电网，以释放光伏、储能和风能的潜力。","scd":null,"kp":[]},{"i":2820,"as":"AlphaESS推出用于储能项目的AlphaConnect连接平台，以满足欧洲市场从独立产品向能降低成本、支持可再生能源及应对复杂关税的综合能源解决方案演进的需求。基于在德国等欧洲市场的早期布局和安装经验，该战略重点在于扩展公用事业规模储能，提供实用、安全且具有长期价值的系统。","scd":null,"kp":[]},{"i":2821,"as":"英伟达（NVIDIA）发布了一种新型数据中心液冷系统。其Rubin平台采用高达113华氏度（45摄氏度）的液体冷却剂进行闭环冷却，覆盖处理器和网络等所有高性能计算组件。该设计极大减少了对耗能密集型的冷却器基础设施的需求，使数据中心用水量接近于零。","scd":null,"kp":["冷却液最高运行温度[NVIDIA Rubin平台液冷系统]: 45℃","冷却方式[数据中心]: 高温液冷(大幅减少高耗能制冷设备)"]},{"i":2822,"as":"在2026年上海世界移动通信大会（MWC）上，人形机器人举行了点球大战挑战赛。该活动通过点球挑战展示了具身智能在压力下的表现，测试了机器人技术、人工智能、机器视觉和实时运动控制的极限，凸显了新一代自主技术。","scd":null,"kp":["技术测试重点[人形机器人]: 实时运动控制与机器视觉"]},{"i":2823,"as":"波音子公司Aurora Flight Sciences正为DARPA CRANE项目的实验性X-65无人机安装机翼。该无人机采用主动流控（AFC）系统作为关键创新，利用分布在机翼表面的14个效应器喷射高压空气来控制俯仰、滚转和偏航，旨在测试用增压空气爆发取代传统襟翼和方向舵等机械活动翼面进行飞行控制。","scd":null,"kp":["主动气流控制(AFC)[X-65实验无人机]: 利用加压空气喷射替代传统机械活动翼面进行飞行控制"]},{"i":2824,"as":"加州理工学院研究人员开发出一种制造3D结构化电池阴极的新方法。该阴极用嵌入碳基质中的磷酸铁锂（LFP）取代了有毒且昂贵的钴。通过重构电池内部的三维微观架构克服了LFP材料性能迟缓的弱点，提高了未来电池的安全性和功率表现，同时降低了环境和道德影响。","scd":null,"kp":["阴极材料体系[新型3D架构电池]: 碳基体包裹磷酸铁锂(LFP)替代有毒钴"]},{"i":2825,"as":"DEEP Robotics（深圳云深处科技）展示了其新型轮腿式机器人Lynx M20S。该机器人专为应对复杂地形的工业操作而设计，有效载荷、机动性、耐用性和续航能力均得到显著提升。它能适应极端地形、涉水跨越深达31英寸的河流，并在零下22华氏度的寒冷环境中运行，可广泛应用于巡检、物流和野外作业。","scd":null,"kp":["涉水跨越能力[Lynx M20S轮腿机器人]: 31英寸(约0.79米)","极寒运行温度[Lynx M20S轮腿机器人]: -22℉(约-30℃)"]},{"i":2826,"as":"宁德时代（CATL）于2026年6月在德国慕尼黑推出全球首款在实际条件下验证的钠离子储能系统——TENER。该系统循环寿命达到15000次，预计到2026年底出货量将达到1吉瓦时。宁德时代计划于2026年9月开始向中国客户交付，并于2027年6月开始全球出货，标志着钠离子电池大规模储能应用的重要一步。","scd":null,"kp":["循环寿命[CATL TENER钠离子储能系统]: 15000次","预期出货量[钠离子储能系统]: 1 GWh(截至2026年底)","应用状态[全球首款钠离子储能系统]: 率先在真实世界工况下得到验证"]},{"i":2827,"as":"交通领域创新资讯摘要，涵盖电动汽车、军事运输和前沿科技。亮点包括：利用100%太阳能现场生产氢燃料实现从生产到推进的可持续闭环；中国积极推进钠离子电池的商业化应用；以及美联航飞行员试驾Boom Supersonic的XB-1和Overture模拟器，展示高速航空旅行的未来。","scd":null,"kp":["氢燃料制备方式[本地制氢]: 100%太阳能供电"]},{"i":2828,"as":"在德国汉堡ISC 2026会议上，中国超级计算机“LightShine”九年来首次登顶全球最强超级计算机榜单，取代了美国的“El Capitan”。在TOP500高性能基准测试中，该系统位列第一，同时以22.00 HPCG-Petaflop/s的性能占据HPCG榜单首位。该超级计算机部署在中国国家超级计算中心。","scd":null,"kp":["性能排名[HPL基准测试]: 世界第一","系统名称[中国最强超算]: LineShine"]},{"i":2829,"as":"","scd":null,"kp":[]},{"i":2830,"as":"日本研究人员发现利用银纳米颗粒可以解锁一种高效的DNA切割与组装新方法。在基因工程中，为了改善作物、治疗遗传疾病，精确切割和组装DNA至关重要。新方法利用银纳米颗粒提高特定位置的切割准确性，从而改善用于DNA组装的粘性末端的生成，显著提高了DNA片段的连接效率和回收率。","scd":null,"kp":["编辑与组装工具[DNA基因工程]: 银纳米颗粒","技术优势[DNA剪切组装]: 提高DNA回收率和连接效率"]},{"i":2831,"as":"","scd":null,"kp":[]},{"i":2832,"as":"传统电机设计主要依赖磁场，因为静电作用力曾被认为过弱而无法实际应用。如今，被称为铁电流体的一类特殊材料打破了这一长达百年的工程假设。这种液体对电场表现出极强的响应能力，能够通过静电作用力实现低压驱动。这一发现成功证明不依赖稀土材料也能实现电机的驱动，为电机工程开辟了全新的技术路径。","scd":null,"kp":["电机驱动机制[新型塑料电机]: 低压下利用静电力致动且不依赖稀土材料","核心材料[新型电机]: 铁电流体"]},{"i":2833,"as":"天文学家利用阿塔卡马大型毫米波/亚毫米波阵列（ALMA）对星际彗星3I/ATLAS进行观测，发现其含有异常丰富的甲醇。甲醇是彗星中常见的一种有机分子，但在该星际彗星上发现的丰度实属罕见。这项发现为研究太阳系外遥远行星系统的物理和化学条件提供了全新的线索与化学证据。","scd":null,"kp":["化学物质丰度[星际彗星3I/ATLAS]: 异常富含甲醇"]},{"i":2834,"as":"对隼鸟2号任务在2020年带回的小行星“龙宫”样本进行的新研究发现，其中包含了构成DNA和RNA的全部5种基本核碱基（遗传“字母”）。这项发表于《自然-天文学》的研究证实，与生命诞生相关的分子在早期的太阳系中是普遍存在的。这进一步证实了生命基础分子可能在太空中形成并到达地球的假设。","scd":null,"kp":["生命基础物质发现[小行星Ryugu样本]: 包含全部五种基本核碱基（DNA和RNA的遗传字母）"]},{"i":2835,"as":"研究人员在法国布卢瓦美术博物馆发现了失踪数十年的阿基米德重写本的一页。早期分析确认该页为重写本的第123页，内容包含阿基米德数学论文《球体与圆柱体》第一卷的第39至41号命题。这项发表于《纸草学与碑铭学杂志》的发现，有助于借助现代成像技术恢复长期隐藏的古希腊数学著作内容。","scd":null,"kp":[]},{"i":2836,"as":"据相关媒体报道，高通已达成协议，将以接近40亿美元的价格收购初创公司Startup Modular。","scd":null,"kp":["收购金额[高通收购Modular]: 近40亿美元"]},{"i":2837,"as":"计算数据初创公司Ornn在由Andreessen Horowitz领投的一轮融资中成功筹集了3300万美元。","scd":null,"kp":["融资金额[计算数据初创公司Ornn]: 3300万美元"]},{"i":2838,"as":"OpenAI与Broadcom（博通）共同推出了全新的AI服务器专用芯片。","scd":null,"kp":["产品动态[OpenAI与博通合作]: 推出AI服务器芯片"]},{"i":2839,"as":"","scd":null,"kp":[]},{"i":2840,"as":"OpenAI高管在戛纳国际广告节上对外宣传了其在广告业务方面取得的最新进展。","scd":null,"kp":[]},{"i":2841,"as":"Meta公司目前正在开发并构建一款全新的预测市场应用程序（Prediction Markets App）。","scd":null,"kp":[]},{"i":2842,"as":"欧洲正在经历破纪录的热浪，制冷需求激增导致电网负荷达到极限。6月23日，法国气温自1947年有记录以来创下新高，温度超过44摄氏度。持续高温使得河流水温上升，影响了依赖河水冷却的核电站运行。位于法国南部的戈尔费什核电站2号机组已因加伦河水温问题于6月22日关闭，其他反应堆也正在降低运行功率或面临限制。","scd":null,"kp":["极端气温[法国6月23日热浪]: 超过44 °C (111 °F)","[极端高温环境影响]: 河流水温上升导致部分发电厂关闭"]},{"i":2843,"as":"","scd":null,"kp":[]},{"i":2844,"as":"为克服早期互联网设计对自动化数据发现与检索的限制，并解决企业端因数据被阻塞或非结构化而无法进行规模化AI训练的问题，AI行业正催生出一个全新的网络数据基础设施层。这一新型基础设施具备探测数亿网络域名及每周数十亿新增URL的能力，能够实时映射不断扩展的数字领域，满足AI应用对大规模底层数据的获取需求。","scd":null,"kp":[]},{"i":2845,"as":"新墨西哥州初创公司Sceye正在开发一种高空驻留平台（HAPS）。这是一种长约200英尺、配备太阳能板和定制天线的充氦飞行器。该平台计划悬停在距地表18公里的平流层中。预计最早在今年8月，该飞行器将飞越太平洋抵达日本海岸，进行直接向地面设备传输数据的测试，以协助软银补充并扩展其5G网络信号。","scd":null,"kp":["飞行器长度[Sceye平流层太阳能平台]: 约200英尺","飞行高度[Sceye平流层太阳能平台]: 距海平面18公里","应用场景[平流层平台测试]: 补充Softbank的5G网络并将数据直接传输至设备"]},{"i":2846,"as":"","scd":null,"kp":[]},{"i":2847,"as":"研究人员开发出一种名为“傅里叶像素”的新型像素技术。传统像素在显示器上仅用于生成图像，或在相机中仅用于捕捉图像，二者功能互斥。而这种新像素能够同时实现图像和图案的生成与分析。利用这项技术，未来有望制造出兼具图像显示与拍摄捕捉功能的双向相机显示屏。","scd":null,"kp":["新型像素[傅里叶像素]: 兼具图像图案生成与分析功能，可用于制造双向相机显示器"]},{"i":2848,"as":"Ånge Storage Solutions AB公司宣布在瑞典中部成功建成一座容量为70 MW/160 MWh的电池储能系统（BESS）。该项目于2025年2月从RES购入，在Delta Capacity的主导下，历时15个月即从采购进入商业运营阶段，为瑞典SE2电价区提供电网灵活性。项目采用阳光电源供应的电池系统，Green Power Monitor提供能源管理和数据采集系统，Stenger & Ibsen与Rejlers提供建设和施工管理支持。","scd":null,"kp":["项目规模[瑞典Ånge电池储能项目]: 70 MW/160 MWh","系统持续时间[瑞典Ånge电池储能项目]: 2小时","建设周期[从采购到商业运营]: 15个月"]},{"i":2849,"as":"荷兰铁空气电池开发商Ore Energy与能源供应商Budget Thuis签署了1 GWh的长期储能（LDES）供应协议，这是欧洲能源供应商与铁空气电池供应商之间的首个承购协议。该电池仅利用铁、水和空气，通过逆转生锈过程进行充放电，不依赖锂或钴，设计储电时长可达24至100小时。协议的第一阶段承诺交付400 MWh，计划于2028年交付。","scd":null,"kp":["供应规模[荷兰铁空气电池长期储能交易]: 1 GWh","一期承诺交付量[铁空气电池长期储能交易]: 400 MWh","一期计划交付时间[铁空气电池长期储能交易]: 2028年","储能机制[铁空气电池]: 通过逆转生锈过程进行充放电"]},{"i":2850,"as":"中国制造商Fox ESS与澳大利亚可再生能源分销商Solar Juice和OSW分别签署了大规模电池供应合同。在未来24个月内，Fox ESS将向这两家澳大利亚合作伙伴合计交付10 GWh的电池储能解决方案。此次战略合作旨在将先进的住宅、商业和工业储能系统部署到澳大利亚全境，支持清洁能源转型。","scd":null,"kp":["电池供应总量[澳大利亚Fox ESS供应交易]: 10 GWh","交付周期[澳大利亚电池供应合同]: 未来24个月"]},{"i":2851,"as":"NatPower与特斯拉签署战略协议，在欧洲开发总容量超25 GWh的电池储能项目。首期涵盖意大利和英国的五个项目。NatPower负责持有和运营项目，特斯拉提供Megapack电池系统及工程、采购和建设（EPC）服务，并通过Autobidder平台提供能源交易能力。双方建立了整合电力基础设施、工业能力和先进交易解决方案的综合运营模式。","scd":null,"kp":["部署总容量[欧洲NatPower与特斯拉BESS项目]: 超过25 GWh","一期项目数量[意大利和英国BESS项目]: 5个","平台目标总容量[NatPower欧洲储能平台]: 超过100 GWh"]},{"i":2852,"as":"介绍了PtX工厂启动并开展绿氢生产的机制与实施方式。","scd":null,"kp":["设施规模[挪威PtX工厂电解槽]: 世界最大"]},{"i":2853,"as":"Siltrax的G-100燃料电池堆获得了TÜV认证。","scd":null,"kp":["认证获取[Siltrax G-100燃料电池栈]: 获得TÜV认证"]},{"i":2854,"as":"根据BloombergNEF的《2026年土耳其转型概况》，土耳其正处于能源转型的关键十年。清洁电力正成为其能源系统的支柱，土耳其在2025年成为全球风光装机领先市场，目前已拥有34.2 GW太阳能和15.8 GW风能装机。BNEF预计土耳其将在2035年实现120 GW风光装机目标。在政策支持和技术成本下降的推动下，可再生能源将在满足该国电力需求和减少进口化石燃料依赖方面发挥核心作用。","scd":null,"kp":["太阳能装机容量[土耳其2025年清洁能源]: 34.2 GW","风能装机容量[土耳其2025年清洁能源]: 15.8 GW","风光装机目标[土耳其能源转型下个十年]: 120 GW"]},{"i":2855,"as":"在德国汉堡发布的第67期全球超级计算机500强榜单中，中国超算“灵晟”以每秒2.198百亿亿次浮点运算的持续双精度浮点性能首次夺冠。这是自2017年“神威·太湖之光”之后，中国超算再次登顶该榜单。跻身榜单前五名的还包括美国的“酋长岩”、“前沿”、“极光”和德国的“朱庇特”。","scd":null,"kp":["持续双精度浮点性能[中国超算“灵晟”]: 每秒2.198百亿亿次浮点运算","[全球超级计算机500强榜单]: 中国“灵晟”位列第67期榜首"]},{"i":2856,"as":"中国31个省份将在“十五五”期间差异化推进人工智能发展，围绕算力、算法、数据三大核心能力进行系统布局。算力方面，23个省份布局算力建设，10个融入“东数西算”，17个省份要求新建算力设施绿电占比不低于80%。算法方面，以通用大模型与行业垂直大模型双轮驱动，9个省份聚焦本地优势产业。数据方面，27个省份部署高质量数据集建设，以支撑模型研发与产业转型。","scd":null,"kp":["算力基础设施规划[省级“十五五”规划]: 23个省份提出加强算力基础设施建设或布局优化","模型算法创新[省级“十五五”规划]: 17个省份聚焦模型算法创新","高质量数据集建设[省级“十五五”规划]: 27个省份部署高质量数据集建设","国家“东数西算”战略[省级“十五五”规划]: 安徽、吉林等10个省份提出深入实施或主动融入","绿电占比[新建算力设施]: 宁夏、重庆等地要求不低于80%"]},{"i":2857,"as":"第四届链博会首次设立人工智能专区，将原“数字科技链”升级为“数智科技链”。AI专区遵循产业链演进路径，展示从数据感知、算力算法到应用落地的完整生态。英伟达、英特尔、阿里巴巴等企业展示了智能芯片、大模型及行业解决方案。英特尔全景展示了AI PC与AI服务器生态，英伟达联合国内生态伙伴呈现了从能源到应用的AI产业图谱。","scd":null,"kp":["[链博会人工智能专区]: 遵循AI产业链内在规律，按数据感知、算力算法、应用与解决方案路径系统化设计，呈现从数据采集、智能分析到场景落地的完整生态"]},{"i":2858,"as":"中国首本英文数据期刊《数据快报（英文）》正式创刊，由中国科学院计算机网络信息中心主办，定位为顶级综合性数据出版平台。该期刊重点发表原创性原始数据论文，侧重时效性，旨在快速分享大科学装置、野外观测及实验数据，解决科研数据缺乏独立发布与评价体系的问题。2026年，中国科学院还将创办系列领域数据期刊，共同组成数据期刊集群，以提升中国在科学数据领域的国际话语权。","scd":null,"kp":[]},{"i":2859,"as":"世界经济论坛第十七届新领军者年会（夏季达沃斯论坛）在大连举行，主题为“规模化创新”，1700余名嘉宾参会。与会专家针对人工智能产业的快速发展，探讨了机器人如何更好学习人类行为的相关议题。","scd":null,"kp":[]},{"i":2860,"as":"夏季达沃斯论坛发布了2026年十大新兴技术。","scd":null,"kp":[]},{"i":2861,"as":"世界经济论坛与《前沿》出版集团联合发布《2026年十大新兴技术》报告，筛选出未来5年最值得关注的技术。今年入选的10项技术中有8项直接作用于物理系统，标志最具影响力技术正从软件领域转向物理世界。具体技术包括：泛在电力物联网，实现双向能量流动；直接提锂技术，数小时内从卤水提锂；以及被动辐射制冷材料等。这些技术在能源、医药和制造领域呈现了全新范式。","scd":null,"kp":["[2026年十大新兴技术]: 竞争优势从软件能力转向对基础设施、材料、生物过程及工业数据的掌控能力（8项直接作用于现实世界的物理系统）"]},{"i":2862,"as":"第四届链博会在北京开幕，首次设立人工智能专区。共有676家中外企业和机构参展，集中展示了人形机器人、低空飞行器、脑机接口、智能仿生手等最新具身智能与硬核科技产品。","scd":null,"kp":["[链博会人工智能专区]: 首次设立，集中展示人形机器人、低空飞行器、脑机接口、智能仿生手等最新硬核科技，共有676家中外企业和机构参展"]},{"i":2863,"as":"亚洲开发银行（ADB）的融资方案将支持在柬埔寨建设一个容量为250兆瓦/500兆瓦时的电池储能系统（BESS）项目。","scd":null,"kp":["储能规模[柬埔寨BESS项目]: 250兆瓦/500兆瓦时"]},{"i":2864,"as":"山西省发布通知规范分布式可再生能源发电项目管理，推进多领域融合发展。通知明确：屋顶光伏及“全部自发自用”项目由市级管理；一般工商业余电上网项目自发自用电量比例不得低于50%（公共机构项目除外）。此外，电网企业需按月公布可接入容量，实施系统级承载力评估，且在电网承载力红区内，允许新建分布式光储项目以充分释放电网接入资源。","scd":null,"kp":["[山西分布式光储项目]: 推进分布式新能源与交通、建筑、农业农村等多领域融合开发，增强自调节能力，提高自发自用比例"]},{"i":2865,"as":"内蒙古鄂托克旗启动2026年新能源项目优选工作，总规模9万千瓦，包含6万千瓦分散式风电和3万千瓦光伏发电。项目需遵循就近消纳原则，以110千伏及以下电压等级接入且不得升压外送。分散式风电连接点电压不超过110千伏、容量不超50兆瓦；一般工商业光伏电压不超10千伏（20千伏）、容量原则不超6兆瓦。鼓励结合乡村振兴开发并自愿配置储能。","scd":null,"kp":["建设规模[鄂托克旗新能源项目]: 分散式风电6万千瓦、光伏发电3万千瓦，总规模共计9万千瓦"]},{"i":2866,"as":"欧洲光伏协会报告显示，2025年全球光伏新增装机达664 GW，同比增长12%，占全球新增可再生能源装机的77%。中国以382 GW新增装机占全球57%居首；印度以45.7 GW超越美国成为第二大市场；欧盟新增67.2 GW。2025年的新增装机量创历史新高，但报告预测今年全球新增光伏装机将迎来20年来的首次下降，预计到2027年起才会回升。","scd":null,"kp":["新增装机容量[2025年全球光伏]: 664GW","同比增长率[2025年全球光伏新增装机]: 12%","全球新增容量占比[2025年光伏]: 77%","光伏发电量[2025年全球]: 2778TWh","电力需求占比[2025年全球光伏供应]: 9%"]},{"i":2867,"as":"截至6月22日，中国276家风光储新能源上市企业总市值达96003亿元，同比增长75%。宁德时代以19438亿市值居首，阳光电源、中天科技等分列其后。传统光伏巨头市值在产业内卷与周期下行中普遍式微，仅隆基绿能进入总市值前20，而与储能相关的企业市值表现突出。","scd":null,"kp":["总市值[中国风光储新能源上市企业]: 96003亿元RMB","同比增长率[中国新能源上市企业市值]: 75%","市值[宁德时代]: 19438亿元","市值[阳光电源]: 3389亿元","市值[中天科技]: 2035亿元"]},{"i":2868,"as":"罗博特科智能科技股份有限公司发行境外上市外资股（H股）并在香港联交所主板挂牌上市的申请获中国证监会备案。公司拟发行不超过34,014,550股境外上市普通股。备案通知书出具之日起12个月内未完成发行则需更新材料。该事项尚需取得香港证监会的批准。","scd":null,"kp":["拟发行股数[罗博特科境外上市普通股(H股)]: 不超过34,014,550股","上市地点[罗博特科]: 香港联合交易所主板"]},{"i":2869,"as":"安徽明光市发展和改革委员会发布通知，决定清理13个长期在途及不发电的分布式光伏项目。其中，4户现场无发电设备已不具备恢复条件；9户在取得电网接入意见后12个月内未建成并网。此前该市已在5月清理5户类似长期不发电项目。公示期为2026年6月22日至7月21日。","scd":null,"kp":["清理数量[长期在途及不发电分布式项目]: 13个项目","并网期限要求[取得电网接入意见后未建成并网项目]: 12个月内"]},{"i":2870,"as":"吉林省发改委等部门印发通知，公布首批10个省级零碳园区建设名单，范围均为园中园，建设周期为2026至2030年。通知要求园区优化能源供给结构，强化能源消费管理，推广绿色低碳技术。相关部门将支持推动绿电直连、新能源就近接入增量配电网等模式在园区落地，并在资金、要素保障及金融服务方面给予支持。","scd":null,"kp":["建设数量[吉林省首批省级零碳园区]: 10个","建设周期[吉林省省级零碳园区]: 2026-2030年"]},{"i":2871,"as":"甘肃省印发现代化产业体系建设“十五五”规划，明确以“源网荷储制”协同布局为重点，建设大型风光电基地并接续打造“沙戈荒”新能源基地。酒泉市将建特大型基地，张掖等地建成千万千瓦级基地。甘肃将推进“新能源+”行动，布局绿氢、绿氨、绿醇产业，壮大新能源装备制造，推动大兆瓦风机、电解槽等关键装备本地化生产，并引导储能制造向特定区域集聚，布局废旧电池回收体系。","scd":null,"kp":["[甘肃十五五新能源布局]: 推动“源网荷储制”协同，建设大型风光电基地及“沙戈荒”新能源基地","[新能源装备制造]: 推动大兆瓦风机、逆变器、电解槽、氢燃料电池等关键装备本地化生产","[储能与回收产业]: 引导储能制造向金昌等地集聚，布局老旧设备与废旧电池回收再利用体系"]},{"i":2872,"as":"贵州能源监管办发布《贵州集中式新能源发电企业集中报价实施方案(试行)》征求意见稿。方案明确集中报价适用于已完成注册的集中式新能源企业，不含分布式及大基地等项目。申请集中报价的总装机规模不得超过贵州电力市场单个最大燃煤发电厂装机规模，若影响公平竞争，相关部门认定后可进一步压减规模。该方案适用于贵州电力现货市场正式运行及连续结算试运行情况下的中长期与现货电能量交易。","scd":null,"kp":["总装机规模限制[新能源发电企业集中报价]: 不得超过贵州电力市场单个最大燃煤发电厂装机规模","[适用范围限制]: 不含分布式、“沙戈荒”大基地、水风光一体化等项目"]},{"i":2873,"as":"亚马逊旗下Zoox升级了其Robotaxi自动驾驶出租车，为今年晚些时候启动商业运营做准备。新车保留无方向盘的方盒子造型、双向行驶、四轮转向和四人座“面对面”布局，最高时速约121公里。感知系统配备包含激光雷达在内的40个感知设备。此次升级主要针对高频运营改善细节，包括增加座椅填充物、采用浅色内饰便于发现遗落物品、加大杯架及增加无线充电板防滑凹槽。车外重新布置了反光装置，车门交互区新增屏幕并支持双向通话，以改善沟通。","scd":null,"kp":["感知设备数量[Zoox自动驾驶出租车]: 40个","感知设备配置[Zoox自动驾驶出租车]: 摄像头、雷达、激光雷达和红外传感器","最高时速[Zoox自动驾驶出租车]: 约121公里","座位数[Zoox自动驾驶出租车]: 4人座","设计特点[Zoox自动驾驶出租车]: 无方向盘和传统驾驶控制装置、双向行驶、四轮转向"]},{"i":2874,"as":"","scd":null,"kp":[]},{"i":2875,"as":"","scd":null,"kp":[]},{"i":2876,"as":"","scd":null,"kp":[]},{"i":2877,"as":"","scd":null,"kp":[]},{"i":2878,"as":"华为宣布鸿蒙“龙虾”小艺Claw向HarmonyOS 5.0及以上全机型开放。更新后的小艺Claw推出49元体验包（含Auto-Model模式）和199元标准包（支持选择DeepSeek、MiniMax等四种基础大模型）。其Skills市场已支持超500项精选技能，覆盖办公、创作、生活等领域。小艺Claw具备开箱即用、自我学习、多端协同和端云协同安全加固等特性，此前已获得信通院首个终端厂商权威安全认证。","scd":null,"kp":["系统版本要求[鸿蒙小艺Claw全机型开放]: HarmonyOS 5.0及以上","App版本要求[鸿蒙小艺Claw]: 11.6.4.300及以上","基础大模型选择[199元标准包]: openPangu-2.0-Pro、DeepSeek V4-Flash、DeepSeek V4-Pro、MiniMax M3","Skills数量[小艺Skills市场]: 500+"]},{"i":2879,"as":"欧洲航天局宣布，大型小行星（152637）1997 NC1将于本周六北京时间19时14分安全飞掠地球。最近距离约256万公里，是地月距离的六倍以上，无任何撞击威胁。该小行星飞行速度近9km/s，直径估计在750至1650米之间。飞掠期间，北半球部分地区可用小型望远镜或双筒望远镜观测。欧空局指出，此类体积天体近距离接近地球每隔几年才会发生一次，但明亮月光可能会干扰极近距离时的观测效果。","scd":null,"kp":["最近距离[小行星1997 NC1飞掠地球]: 约256万公里","飞行速度[小行星1997 NC1]: 接近9km/s","直径估计[小行星1997 NC1]: 750米至1650米之间"]},{"i":2880,"as":"据爆料，三星Galaxy Z Flip8小折叠手机的国行及美版机型将回归搭载高通骁龙芯片，不再使用Exynos处理器。三星曾在此前的Flip7机型上首次全球搭载Exynos 2500芯片。结合目前传闻，Galaxy Z Flip8将配备4.1英寸OLED外屏和6.9英寸内屏，屏幕分辨率达1048*940（QHD+级别）。","scd":null,"kp":["处理器芯片[三星Galaxy Z Flip8国行/美版]: 回归高通骁龙芯片（弃用Exynos 2600）","外屏尺寸[三星Galaxy Z Flip8]: 4.1 英寸 OLED","内屏尺寸[三星Galaxy Z Flip8]: 6.9 英寸","屏幕分辨率[三星Galaxy Z Flip8]: 1048*940 / QHD+"]},{"i":2881,"as":"","scd":null,"kp":[]},{"i":2882,"as":"","scd":null,"kp":[]},{"i":2883,"as":"","scd":null,"kp":[]},{"i":2884,"as":"摩根士丹利再度上调中国人形机器人出货量预测，将2026年预期从2.8万台翻倍至5万台。预计2026年中国市场规模将达20亿美元，2030年增至150亿美元，年出货量达44.6万台。Omdia数据显示，2025年全球出货1.3万台人形机器人，前五名均由中国企业占据。商业验证、政策支持及供应链优势正加速中国具身智能机器人在真实生产环境中的普及，中国工厂部署的机器人数量位居全球前列。","scd":null,"kp":["出货量[2026年中国人形机器人预测]: 5 万台","市场规模[2026年中国人形机器人预测]: 20 亿美元（约136.01亿元人民币）","年出货量[2030年中国人形机器人预测]: 44.6 万台","市场规模[2030年中国人形机器人预测]: 150 亿美元（约1020.06亿元人民币）","全球出货量[2025年全世界人形机器人]: 1.3 万台（前五名厂商均为中国企业）"]},{"i":2885,"as":"相机厂商宝丽来在纽约海滩投放反AI广告牌，标语为“趁数据中心还没把水喝干，赶紧下水玩吧”，以此推广其新款Go Gen 3相机并呼吁拥抱模拟世界。该营销直指大型AI数据中心严重消耗水资源的争议。据悉，美国部分大型数据中心每天的用水量超过近4.9万名美国人的日常用水总量。OpenAI CEO奥尔特曼对此驳斥，称过去的数据中心蒸发冷却现已改变，网传ChatGPT单次查询消耗64升水的说法不实。","scd":null,"kp":[]},{"i":2886,"as":"海思发文详解星闪音频Hi-Fi无损传输技术。无线无损音质分为CD级（44.1kHz/16bit）和Hi-Fi级（48kHz/24bit），其中48kHz/24bit规格要求至少2.3Mbps传输码率，传统短距无线技术无法满足。星闪音频依托大带宽与高阶调制技术，物理层传输速率达16Mbps，能够轻松承载48kHz/24bit规格的Hi-Fi音频无损传输，避免了高规格音源被强制压缩。目前华为多款机型已支持星闪音频。","scd":null,"kp":["传输速率[星闪音频物理层]: 16Mbps","通道容量[星闪音频Hi-Fi无损]: 支持 48kHz/24bit 规格","无损音质标准[Hi-Fi无损级音频]: 48kHz/24bit 音频规格","无损音质标准[CD无损级音频]: 44.1kHz/16bit 音频规格"]},{"i":2887,"as":"","scd":null,"kp":[]},{"i":2888,"as":"","scd":null,"kp":[]},{"i":2889,"as":"丰田已停止开发雷克萨斯纯电旗舰轿车LF-ZC，主因是模具和生产设备成本过高。但丰田确认，该项目已完成的一体化压铸技术、全新电子电气平台、以及小型轻量化等新技术不会废弃，将应用于已决定开发的后继车型中。LF-ZC原计划采用高性能方形电池实现两倍续航，并配备基于Arene OS的AI智能座舱。丰田表示停止该项目是基于市场需求变化对开发计划的调整，并不代表放弃纯电车型。","scd":null,"kp":["核心技术[雷克萨斯LF-ZC纯电轿车]: 已停止开发，但技术将应用于后继车型","续航能力[LF-ZC搭载新型高性能方形电池]: 约为传统锂离子电池车型的两倍","已突破技术[量产化条件]: 一体化压铸技术、全新电子电气平台（面向高级驾驶辅助系统）、小型化和轻量化技术"]},{"i":2890,"as":"央视解析了毕业论文AIGC检测原理。与查重基于语料库语句对比不同，AI检测是基于概率的分类判断，对比文本语义与AI写作风格的重叠度。由于大模型与人类在语言表达上边界模糊，加之中文表达丰富多样，导致AI检测极易出现误判，甚至出现用AI洗稿后“AI率”反而升高的现象。专家建议，在论文审核上不应简单划定AI率红线，而应建立透明可回溯的AI使用标注制度，确立以人工评议为主、AI检测为辅的判定机制。","scd":null,"kp":["检测机制[传统论文查重]: 将论文与语料库进行语句对比（基于证据的确定性判断）","检测机制[AIGC检测]: 运用AI检测人类文本，分析语意和表达风格（本质上是一种基于概率的分类）","技术瓶颈[当前AI文本检测]: 无法明确判定文本来源是人类撰写还是AI生成"]},{"i":2891,"as":"加拿大锂矿公司Rock Tech在德国古本建设锂转换器的项目遭遇融资瓶颈。该工厂预计投资成本高达7.5亿欧元，目前公司因缺乏私人投资者，无法满足获取公共资金的前提条件。尽管公司仍计划建设该工厂，但代表无法提供可靠的动工时间表。据悉，该项目一旦开工，建设周期预计约为两年半。","scd":null,"kp":["投资成本[古本锂转换器项目]: 预计 7.5 亿欧元","项目状态[古本锂转换器建设]: 面临资金短缺与融资困难"]},{"i":2892,"as":"数字电池护照测试环境已正式上线，旨在帮助企业应对将于2027年2月强制实施的欧盟数字电池护照规定。制造商、电池供应商及软件公司可在此平台验证其数据是否符合欧盟法规要求。该平台提供数据验证功能和11个测试场景，用于模拟电池生态系统中各利益相关者之间的互动，从而在真实场景中测试电池护照解决方案的合规性与互操作性。","scd":null,"kp":["强制实施时间[欧盟数字电池护照]: 2027 年 2 月起","测试环境[数字电池护照]: 支持制造商、供应商和软件公司验证数据的合规性与互操作性"]},{"i":2893,"as":"报告指出，美国储能市场正朝着2031年实现200吉瓦的目标迈进。然而，国内电池制造商必须获取稀缺的符合FEOC（外国受关注实体）规定的组件，才能获得关键的税收抵免（如每千瓦时最高35美元的45X条款抵免）。符合规定设备的短缺被确认为限制未来2至4年美国储能增长的关键瓶颈，导致市场出现两极分化，拥有充足资金的成熟开发商占据优势。","scd":null,"kp":["储能市场规模[2031年美国能源储备预测]: 赛道规模将达 200 GW","供应链瓶颈[美国本土电池制造商]: 必须获取稀缺的FEOC（受关注外国实体）合规组件以获得税收抵免，从而形成两级分化产业"]},{"i":2894,"as":"福特正全力研发基于通用电动汽车平台的新款经济型电动皮卡，计划于2027年投入生产。目前原型车已进入公开道路测试阶段。该原型车采用简化组装工艺，大幅减少零部件数量，打破了传统汽车制造模式。工程师正针对车身稳定控制系统、牵引力系统和转向系统进行冬季专道测试，车辆外观则配备二维码伪装以展示研发团队的创新工作。","scd":null,"kp":["装配工艺[福特2027年新款经济型电动皮卡]: 简化装配流程，零部件数量大幅减少"]},{"i":2895,"as":"为应对全球对可持续解决方案及可靠物流日益增长的需求，DP World 推出了名为 EcoRoute 的可持续发展解决方案套件。目前货运和物流行业约占全球与能源相关的二氧化碳排放量的10%。DP World 通过该套件及战略合作伙伴关系，帮助企业在不牺牲供应链性能的前提下优化物流，致力于减少碳排放并实现无缝、高效的全球货物流通。该公司业务遍及六大洲83个国家。","scd":null,"kp":["[DP World EcoRoute]: 提供可持续发展解决方案套件以优化供应链绩效"]},{"i":2896,"as":"安联最新安全与航运评估报告指出，波斯湾物流网络出现史上首次关闭。截至2026年6月15日，约有1150艘船舶滞留在波斯湾等待恢复正常作业。这些船舶及其承载货物的总价值估计达1250亿美元，涉及2900万总吨的运力以及2万名海员。这凸显了地缘政治破坏如今无需战争即可迅速蔓延并对全球供应链造成严重冲击。","scd":null,"kp":["货物及船舶总价值[霍尔木兹海峡等候通行]: 1250亿美元","涉及船舶数量[霍尔木兹海峡等候通行]: 约1150艘"]},{"i":2897,"as":"System Loco 利用货运级别的智能数据技术，为冷链物流提供关键支持，以应对日益严重的货物盗窃和复杂的供应链挑战。冷链物流需要严格的温度控制，而现代供应链面临着快速交货需求和市场动荡。System Loco 运用先进技术确保全程高度可见性与合规性，有效解决这些需求，成为保障冷链物流安全、打击货物盗窃的重要工具。","scd":null,"kp":["[System Loco冷链技术]: 提供货运级智能数据以保障可见性和合规性，用于打击货物盗窃"]},{"i":2898,"as":"","scd":null,"kp":[]},{"i":2899,"as":"NVIDIA 连续第二年在 Gartner 全球供应链 25 强榜单中位列第二，仅次于施耐德电气。NVIDIA 凭借其在运用技术应对供应链复杂性方面的卓越表现被评为行业领导者。通过广泛应用现代人工智能技术和提供大规模计算硬件产品，NVIDIA 正在重塑整个供应链行业格局，其技术驱动了当前市场上大量关键应用的运行。","scd":null,"kp":["供应链排名[NVIDIA]: 连续第二年在Gartner供应链25强榜单中位居第二（榜首梯队）"]},{"i":2900,"as":"全球最大的电动汽车电池制造商宁德时代（CATL）董事长曾毓群对固态电池技术热潮泼了冷水。他指出，在1到9级的技术成熟度指标中，固态电池目前仅达到4级水平，其商业可行性尚未确立。曾毓群预计，固态电池技术的转折点在2030年之前都不会到来。此番言论发表于大连夏季达沃斯论坛上，宁德时代随后证实了这一说法。","scd":null,"kp":["技术成熟度[固态电池]: 处于9级 readiness scale 中的第4级","商业化转折点预期[固态电池]: 2030年前难以实现跨越"]},{"i":2901,"as":"电动自行车驱动系统制造商 Avinox 在法兰克福 Eurobike 2026 展会上发布了最新概念技术——MG 概念电机。该产品与 Canyon、Forbidden 等多个知名自行车品牌联合开发，旨在重新设计电动自行车中维护需求最高的传动系统。其核心特点是将变速箱直接集成到中置电机系统中，从而取消了传统的拨链器和多速飞轮。该概念电机换挡时间不到0.1秒且动力输出不中断。","scd":null,"kp":["[Avinox MG Concept Motor]: 与多家自行车品牌合作开发，旨在重新设计驱动系统中维护最密集的环节"]},{"i":2902,"as":"比亚迪与 Parkopedia 合作，将于2027年在欧洲推出全新的车载停车服务 ParkPay。该服务基于内置谷歌的 Android OS 构建，帮助车主轻松寻找停车位。司机可查看就近车位、价格及实时可用状态，并在驶入覆盖区域时通过信息娱乐系统接收提示以完成车内支付。未来该系统还将增加电动汽车充电功能。此外，比亚迪在英国和欧洲还将分别集成 RingGo 和 EasyPark 服务。","scd":null,"kp":["[BYD与Parkopedia合作]: 推出ParkPay车载服务，涵盖查找停车位和支付功能","服务上线计划[B.Y.D欧洲车载停车及支付服务]: 2027年在欧洲开始推出"]},{"i":2903,"as":"随着欧洲市场需求回升，特斯拉计划在其柏林格林海德超级工厂再招聘1000名员工，以加快其欧洲唯一制造工厂的产能提升步伐。特斯拉的目标是到10月份将每周产量提升至7500辆。此前，特斯拉已于4月宣布招募另外1000名员工，预计于6月底到位，旨在将周产量从前期提升约五分之一至6000辆。若按此计划推进，该工厂年化产量将达到约39万辆。","scd":null,"kp":["计划新增雇员[特斯拉柏林超级工厂]: 1000人","目标产能[特斯拉柏林超级工厂]: 自10月起达到每周7500辆汽车"]},{"i":2904,"as":"葡萄牙初创公司 Amble 发布了其首款名为 Amble One 的电动越野车，旨在满足不需要传统汽车的日常短途出行需求。Amble One 搭载15千瓦电机，最高时速可达65公里（40英里）；配备11千瓦时电池，纯电续航里程最高可达100公里（62英里）。该车辆计划于明年开始生产，并在2028年推出符合交通法规的合法上路版本。","scd":null,"kp":["合法上路版推出时间[Amble电动越野车]: 2028年","设计时速[Amble电动越野车]: 40英里/小时"]},{"i":2905,"as":"罗马尼亚光伏产业协会指出，得益于有利的市场条件和监管环境，罗马尼亚光伏与储能市场正快速发展。2026年前五个月，罗马尼亚新增太阳能装机容量约1.5吉瓦，其中包括约800兆瓦的公用事业级光伏和相近规模的消费者自用安装量。这一强劲的装机数据表明，罗马尼亚有望打破去年的年度太阳能装机纪录。","scd":null,"kp":["新增装机容量[罗马尼亚2026年前五个月太阳能]: 约1.5 GW"]},{"i":2906,"as":"非洲太阳能市场正呈现多元化发展趋势，越来越多的国家级市场在大型太阳能项目部署上取得重大进展。非洲太阳能产业协会指出，坦桑尼亚、赞比亚和阿尔及利亚等国在今年取得了显著成果，公用事业级太阳能项目正快速落地。此外，工商业领域的太阳能应用需求也呈现出明显的加速增长态势。","scd":null,"kp":["[非洲太阳能市场]: 正向多元化发展，国家级市场在部署大型太阳能项目方面取得重大进展"]},{"i":2907,"as":"在 Intersolar 和 ees Europe 2026 展会上，欣旺达能源推出了以“一核万景”为主题的升级版 SunESS H 系列产品，展示了储能、充电和数字能源管理的系统级架构。该系列在原有储能能力的基础上进行了扩展，集成了电池储能系统、光储充解决方案以及人工智能驱动的能源管理，并应用于动态电价等场景。同时，欣旺达与 BayWa r.e.、CEF 和 IBC Solar 签署了协议，以深化其在欧洲市场的合作伙伴关系。","scd":null,"kp":["产品系列[储能系统应用]: 欣旺达升级版SunESS H系列","系统架构[储能系统]: “一芯全能景”（One Core, All Scenes）系统级框架"]},{"i":2908,"as":"北马其顿拥有远超其现有太阳能装机的多吉瓦级太阳能与储能项目储备，显示出强劲的投资者兴趣。去年该国新增太阳能装机约210兆瓦，累计容量突破1吉瓦大关。尽管新的审批制度暂时放缓了项目开发，但在监管和电网限制得到解决后，北马其顿的太阳能建设有望迎来大幅加速。根据该国2026年年度能源建设计划，相关项目正在积极推进中。","scd":null,"kp":["项目管道[北马其顿光伏与储能]: 多吉瓦级（千兆瓦级）"]},{"i":2909,"as":"西班牙电缆制造商 Top Cable 推出了一款专为电池储能系统（BESS）设计的新型柔性电缆——Powerflex Ultra。该产品旨在解决密集布线项目中的安装限制问题。由于电池储能系统中的电池集装箱、功率转换站和电气室通常电缆密度极高，对安装灵活性要求很高。Powerflex Ultra 电缆有效结合了安装灵活性与长期耐用性，满足了储能系统项目的两大核心需求。","scd":null,"kp":["电缆特性[电池储能系统(BESS)]: 柔性（针对密集布线项目的安装限制设计）","产品型号[BESS专用电缆]: Powerflex Ultra"]},{"i":2910,"as":"挪威太阳能市场在2026年早期出现放缓趋势。据挪威水资源和能源局数据显示，截至5月底，该国累计太阳能装机容量为903兆瓦，较2025年底仅增长27兆瓦。Multiconsult 负责人指出，尽管太阳能部署停滞，但电池安装量的不断增加以及公用事业级太阳能项目的涌现，为该国的光伏与储能市场提供了新的发展机遇。","scd":null,"kp":["[挪威能源趋势]: 太阳能部署放缓，但电池部署增加且公用事业级项目涌现"]},{"i":2911,"as":"在俄罗斯持续攻击基础设施的背景下，乌克兰对太阳能、储能和能源管理解决方案的需求正持续增长。乌克兰太阳能公司 Atmosfera 通讯负责人指出，袭击和反复停电迅速改变了乌克兰市场环境。目前，乌克兰企业对储能系统的需求极高，同时以社区为基础的“产消者”群体正在迅速崛起。在当前危机下，家庭和社区对分布式发电与储能的依赖正在不断加深。","scd":null,"kp":["[乌克兰光储市场]: 太阳能、储能及能源管理解决方案需求持续增长"]},{"i":2912,"as":"欧盟委员会因担忧网络攻击和停电风险，正限制欧盟资金流向使用中国制造逆变器的太阳能项目。此举引发了对欧洲供应商是否有能力扩大生产规模并打破中国垄断的讨论。欧盟委员会已明确将中国供应商提供的太阳能逆变器列为风险目标。","scd":null,"kp":["资金限制[欧盟太阳能项目]: 限制对使用中国制造逆变器的项目提供资金"]},{"i":2913,"as":"丹麦太阳能协会董事会成员表示，尽管丹麦太阳能市场面临电网挑战，但电池储能部署的快速增长正为开发商和投资者创造新机遇。各市场领域对电池储能的兴趣显著增加，市场信号和电价波动是推动这一增长的核心关键因素。","scd":null,"kp":["增长驱动力[丹麦电池储能]: 市场信号和电价波动"]},{"i":2914,"as":"2026年慕尼黑Smarter E Europe展会全面爆满，共有2662家参展商，虽略低于去年的2700家，但平均展位面积有所增加，占满19个展厅共20.6万平方米。展会聚焦“全天候可再生能源”核心理念，展示范围涵盖光伏、电池储能、电动汽车、能源管理与互联互通等产品服务。","scd":null,"kp":["[可再生能源展会]: 聚焦“全天候可再生能源”（Renewables 24/7）核心理念"]},{"i":2915,"as":"澳大利亚墨尔本大学、联邦科学与工业研究组织（CSIRO）与日本量子科学技术研究开发机构（QST）合作，开发出一种先进制造方法，能将低价值钻石尘转化为量子技术所需的高性能材料。这一技术旨在提升澳大利亚量子技术专业能力，并减少未来对全球量子材料供应链的依赖。","scd":null,"kp":["核心原料[量子技术]: 低价值钻石尘（钻石粉末）","[先进制造方法]: 将钻石尘转化为量子技术用高性能材料"]},{"i":2916,"as":"全球潜艇产业正处于冷战以来最繁忙时期，过去五年16个国家下水约77艘潜艇。中国是这一扩张的绝对领导者，自2021年以来下水约24艘潜艇，数量是俄罗斯（12艘）的两倍多，是美国（7艘）的三倍多。中国快速扩张潜艇力量并推出新设计，使其在潜艇建造领域脱颖而出。","scd":null,"kp":["潜艇下水数量[过去五年全球]: 约77艘","潜艇制造数量[过去五年中国对比美俄]: 超过美俄总和","潜艇下水数量[过去五年中国]: 约24艘"]},{"i":2917,"as":"德国决定取消面临严重延误、巨额成本超支和不可估量风险的F126护卫舰项目，转而向蒂森克虏伯海洋系统公司（TKMS）采购8艘MEKO A-200型军舰。F126级本旨在用于对德国和北约至关重要的反潜战任务。此举意味着德国将放弃原计划的10550吨级F123替代舰，选择经过验证的3950吨级MEKO战舰。","scd":null,"kp":["排水量[MEKO A-200战舰]: 3950吨","采购数量[德国决定采购MEKO A-200战舰]: 8艘","替代关系[德国海军采购调整]: 替代原计划的6艘F126型护卫舰","取消原因[F126护卫舰项目]: 严重延期、成本大幅超支和风险不可预测"]},{"i":2918,"as":"俄罗斯国家原子能公司（Rosatom）正计划建设一座新的模块化乏燃料后处理厂。目前正在进行可行性和选址研究，预计在2026年底前做出最终投资决定。该设施初步产能为每年处理441美吨（400公吨）乏燃料，旨在闭合核燃料循环，并以此战略锁定未来一个世纪的国际客户。","scd":null,"kp":["处理产能[新建模块化乏核燃料后处理厂初始产能]: 441美吨(400公吨)","决定时间[项目选址和投资最终决定]: 预计2026年底前","技术形态[新建后处理设施]: 模块化乏核燃料后处理厂"]},{"i":2919,"as":"中国清华大学领导的研究团队开发出一种微型全陶瓷固态锂离子电池（ACMLB），专为在极端环境下安全驱动微型电子设备而设计。该电池具有不燃性和高安全性，在0°C至150°C（302°F）宽温区内表现出色，甚至能承受300°C（572°F）持续20秒的突然热冲击，为可穿戴微型电子设备提供可靠的高性能电源方案。","scd":null,"kp":["耐受温度[全陶瓷固态锂电池(ACMLB)]: 最高150°C (302°F)","抗热冲击能力[全陶瓷固态锂电池]: 可承受300°C热冲击20秒","电池类型[极端环境微型电子设备电源]: 全陶瓷固态锂离子电池(ACMLB)"]},{"i":2920,"as":"全球最大的动力电池制造商宁德时代（CATL）与中国人形机器人开发商Galbot达成战略合作，以推进智能制造并加速具身AI机器人的全球大规模部署。宁德时代已在生产线上部署了首款由自家电池驱动的重型人形机器人Galbot S1。这是全球首个在常规工业运营中使用宁德时代电池技术的具身智能机器人。","scd":null,"kp":["机器人应用[重载人形机器人]: 动力电池生产线部署","核心特征[Galbot S1人形机器人]: 全球首款由自有电池驱动且具备具身智能的重载人形机器人","应用领域[CATL与Galbot合作]: 智能制造与具身智能机器人大规模部署"]},{"i":2921,"as":"维也纳大学的物理学家成功将磁子的寿命延长了近两个数量级，从几百纳秒增至18微秒，是此前测量极限的100倍。研究还发现，磁子寿命的限制并非基础物理学原因，而主要取决于材料质量。这一突破突破了磁子在形成后立即消失的技术瓶颈，有望助力开发出高度紧凑的硬币大小量子计算机。","scd":null,"kp":["磁振子寿命提升[维也纳大学新发现]: 提升近两个数量级(约100倍)","磁振子寿命[突破前测量值]: 从几百纳秒提升"]},{"i":2922,"as":"芝加哥大学普利兹克分子工程学院的研究人员开发出一种柔软的AI计算皮肤贴片。与传统依赖外部服务器的智能穿戴设备不同，该贴片能直接在人体上利用人工智能以毫秒级速度处理心率等健康数据，提供近乎即时的医疗见解和高度准确的心脏监测。这种即时处理避免了无线传输带来的延迟，在心室颤动等关键时刻至关重要。","scd":null,"kp":["计算耗时[柔性AI计算贴片]: 毫秒级","核心特征[柔性AI计算贴片]: 直接在人体上处理健康数据的类皮肤计算贴片","监测应用[柔性AI计算贴片]: 高精度心脏监测与即时医疗分析"]},{"i":2923,"as":"","scd":null,"kp":[]},{"i":2924,"as":"","scd":null,"kp":[]},{"i":2925,"as":"","scd":null,"kp":[]},{"i":2926,"as":"","scd":null,"kp":[]},{"i":2927,"as":"","scd":null,"kp":[]},{"i":2928,"as":"冲绳科学技术大学院大学携手奥斯陆大学和阿道弗·伊巴涅斯大学，利用旋转水波成功模拟并扩展了量子物理中的阿哈罗诺夫-玻姆（AB）效应。这一经典实验此前因难以测量而困扰物理学界数十年。通过流体力学模拟，研究人员揭示了全新的旋转节点模式，有助于加深对隐藏量子现象的理解。","scd":null,"kp":["模拟方法[量子效应实验]: 利用旋转水波模拟量子效应","实验发现[量子物理模拟]: 发现了旋转的节点模式"]},{"i":2929,"as":"","scd":null,"kp":[]},{"i":2930,"as":"发表在《APS Open Science》上的一项新研究解释了为何火星在未来几个世纪内无法居住。尽管火星地球化在理论上可行，但改变整个星球环境所需的巨大质量、热量、氧气和能量远超人类当前的技术能力。科学家将火星地球化分为五个关键阶段，指出目前火星极端寒冷、大气稀薄，距离实现类地环境仍遥不可及。","scd":null,"kp":["改造结论[火星地球化]: 近未来无法实现","核心瓶颈[火星地球化改造]: 所需的质量、热量、氧气和能量规模远超当前人类能力"]},{"i":2931,"as":"","scd":null,"kp":[]},{"i":2932,"as":"","scd":null,"kp":[]},{"i":2933,"as":"江西省发改委发布增量新能源项目机制电价竞价细则修订稿征求意见，规定2027年1月1日及以后投产的自发自用余电上网工商业项目不再纳入机制电价保底范围。江西成为继山东、河南、广西后第四个实施此类排除条款的省份，但缓冲期延后了一年半。同时，修订稿包含严厉的惩罚杠杆：入选项目若延迟超6个月，竞价结果作废，投资方3年内禁入江西新能源竞价市场，工商业光伏收益逻辑将全面转向市场定价。","scd":null,"kp":["政策执行范围[工商业分布式光伏机制电价竞价]: 2027年1月1日及以后投产的自发自用余电上网项目不纳入","违约处罚[项目延迟超6个月]: 竞价结果作废且投资方3年内禁止参与江西新能源竞价","省份进展[明确将工商业光伏排除出机制电价]: 山东、河南、广西(2025年起)，江西(2027年起)","行业趋势[工商业分布式光伏收益逻辑]: 从“政策定价”转向“市场定价”"]},{"i":2934,"as":"美国国家公路交通安全管理局（NHTSA）计划取消自动驾驶汽车配备制动踏板的要求。这一举措旨在为完全自动驾驶汽车的设计和量产扫清法规障碍，使无需人类驾驶员干预的自动驾驶汽车能够合法上路。该政策的推进标志着自动驾驶车辆在硬件结构定义上向无传统控制踏板方向迈出关键一步。","scd":null,"kp":["[自动驾驶汽车]: NHTSA拟取消制动踏板配置要求"]},{"i":2935,"as":"苹果公司宣布提高Mac和iPad产品的价格。此次调价的核心原因是供应链出现了“异常严重”的零部件短缺问题。零部件供应不足不仅影响了苹果硬件设备的正常生产节奏，也直接导致了制造成本的上升，迫使苹果通过上调终端产品售价来应对这一供应链危机。","scd":null,"kp":[]},{"i":2936,"as":"人工智能初创公司Anthropic指控阿里巴巴非法获取其大语言模型Claude的访问权限。Anthropic认为阿里巴巴存在违规访问和调用其闭源AI模型的行为。此事件凸显了顶尖AI开发商在保护自身知识产权和大模型核心资产方面所面临的网络安全与合规挑战，也引发了业界对AI模型API接口被滥用问题的关注。","scd":null,"kp":[]},{"i":2937,"as":"初创企业Trase成功筹集了1.07亿美元的资金，旨在帮助企业客户加速采用和部署人工智能技术。该公司致力于解决大公司在AI转型过程中面临的技术落地与业务整合难题。这笔规模达1.07亿美元的融资将用于进一步开发其技术平台，协助大型企业更高效地跨越AI应用门槛，实现业务流程的智能化升级。","scd":null,"kp":["融资金额[Trase企业AI服务]: 1.07亿美元"]},{"i":2938,"as":"OpenAI聘请了亚马逊云服务（AWS）的合作伙伴关系负责人，以推动其在商业人工智能领域的发展。此举表明OpenAI正大力强化其在B端企业市场的业务拓展能力。通过吸纳具有深厚云计算和渠道合作经验的高管，OpenAI旨在加速其企业级AI产品（如ChatGPT企业版）的市场渗透，与主要云服务提供商展开直接竞争。","scd":null,"kp":[]},{"i":2939,"as":"文章介绍了如何利用谷歌Gemini大模型打造个人品牌。对于创始人而言，建立个人品牌能吸引媒体和投资人关注，且具备零预算优势。但在注意力竞争激烈的环境下，仅靠社交媒体更新已不足够。Gemini能够有效启动和加速个人品牌创建流程，协助用户提炼独特视角，生成基于特定经验和见解的高质量内容，从而提升个人影响力。","scd":null,"kp":[]},{"i":2940,"as":"人工智能正在快速重塑零售业，其核心变革并非表面的虚拟试衣或聊天机器人，而是后台决策逻辑的全面升级。以梅西百货为例，他们采取了“AI优先”策略，重点利用AI优化产品搜索结果排名、供应链库存流转、代码开发效率以及对客户行为的实时响应。对传统零售商而言，AI不再仅是附加工具，而是已演变为一套指导企业整体运营的核心底层理念。","scd":null,"kp":["[零售业AI重塑]: 核心在于幕后决策优化（搜索曝光、供应链库存、代码交付及客户行为实时响应）"]},{"i":2941,"as":"近期欧洲遭遇创纪录的热浪，对当地电网系统造成了供应和需求的双重挤压。极端高温不仅导致电力需求激增，还直接影响了电力生产与传输基础设施的稳定性。例如，由于冷却系统受高温影响，法国南部的一座核电站被迫关闭。气候变化引发的极端天气正全面挑战欧洲电网的运行极限，暴露了现有基础设施在应对极端气温时的脆弱性。","scd":null,"kp":[]},{"i":2942,"as":"IBM成功研发出一款新型原型芯片，在指甲盖大小的面积上集成了约1000亿个晶体管，晶体管密度达到其2021年最先进技术的两倍。在传统晶体管尺寸逼近量子力学干扰极限的背景下，该设计突破了物理缩放瓶颈。这一技术突破有望显著提升未来计算机的运行速度和能效，为延续摩尔定律提供了切实可行的路径，其技术红利预计可再维持十年。","scd":null,"kp":["晶体管数量[指甲盖大小新型原型芯片]: 约1000亿个","晶体管密度[新型原型芯片]: 两倍于2021年最先进技术","技术影响[新芯片设计]: 有望延续摩尔定律约十年并实现更快、更高能效的计算"]},{"i":2943,"as":"为落实七国集团（G7）的目标，斯坦白欧洲中心正积极加强稀土和永磁体弹性供应链的建设。位于普福尔茨海姆的稀土磁铁回收工厂是该行动的重要组成部分。该举措旨在减少欧洲对原生关键原材料的单一依赖，通过建立本地化、可循环的供应链网络，提升欧洲在全球稀土资源和永磁体市场的战略抗风险能力与产业韧性。","scd":null,"kp":["[稀土与永磁体]: 斯坦白欧洲中心致力于加强弹性供应链建设"]},{"i":2944,"as":"","scd":null,"kp":[]},{"i":2945,"as":"亚琛工业大学的朋友和支持者协会宣布，将于2026年在该校纺织技术研究所（ITA）举行全体成员会议。此次会议回顾了协会在过去一年中取得的成功资助成果。会议期间，与会代表还参观了ITA的技术中心。此举旨在加强学术机构与外部支持者之间的联系，促进校企科研合作，并为未来纺织技术领域的创新项目提供资金与资源支持。","scd":null,"kp":[]},{"i":2946,"as":"科布伦茨大学深度参与并主持了以“民主与人工智能”为主题的会议。会议重点探讨了如何利用人工智能技术加强和提升公民在社区中的参与度。会上，专家展示了一款基于数据的智能仪表板，该工具旨在为公众提供快捷通道，以便高效获取相关洞察信息。此次会议凸显了人工智能在促进政府决策透明化和增强民主参与方面的应用潜力。","scd":null,"kp":[]},{"i":2947,"as":"根据科隆大学能源经济研究所的报告，加速公用事业级电池储能系统的部署，能够显著提升电力系统韧性并大幅降低成本。预计到2035年，通过减少电力采购和网络费用，更快的电池建设步伐每年可为德国家庭和企业节省高达28亿欧元。研究构建了两种储能部署路径模型，证实电池储能的快速扩张是降低消费者用电成本的关键手段。","scd":null,"kp":["节省资金[加速建设公用事业级电池储能至2035年]: 高达28亿欧元"]},{"i":2948,"as":"德勤发布的报告指出，巴西的新兴储能市场蕴含巨大商机，预计在2026年至2035年间将产生超过570亿雷亚尔（约合111亿美元）的投资。该预测基于预期的电池采购量和政府扩建计划，假设巴西在首次电池储能容量拍卖中的初始需求约为1.7吉瓦，并将持续进行年度拍卖。这反映了巴西在灵活电网和新能源转型方面的强劲增长需求。","scd":null,"kp":["投资规模[2026至2035年巴西储能市场]: 超过570亿巴西雷亚尔(约111亿美元)","储能容量[巴西首次电池储能容量拍卖初始要求]: 约1.7吉瓦"]},{"i":2949,"as":"戴姆勒卡车与林德公司联合宣布，正式启用全球首个过冷液态氢（sub-cooled LH2）加氢站。该设施旨在验证和展示新一代氢相容材料及过冷液态氢加注技术的实际应用。这一举措为重型商用卡车的大规模氢能商业化部署扫清了基础设施障碍，证明了液氢在快速加注和高密度储运方面的技术可行性。","scd":null,"kp":["加氢站[戴姆勒卡车与林德启用首个过冷液氢站]: 液态氢(LH2)"]},{"i":2950,"as":"上海市成功实现了跨越3000多公里的异构算力调度，将部分人工智能计算任务转移至新疆克拉玛依，利用当地充沛的绿电资源完成运算。这一“东数西算”的实践打破了上海在人工智能发展中的能源与空间约束。通过算力网与电网的深度协同，资源协同模式正取代传统的资源集聚模式，标志着一条连接东部算力需求与西部清洁能源的新型基础设施网络正在成型。","scd":null,"kp":["调度距离[上海至新疆异构算力调度]: 跨越3000多公里","[东数西算]: 利用新疆绿电完成AI计算任务"]},{"i":2951,"as":"2026上海世界移动通信大会（MWC上海）全面聚焦6G、移动AI等前沿技术，加速推动空天地一体化网络从概念走向现实。大会首次设立6G产业生态展区，重点展示了6G智能体通信（ACN）样机、低轨宽带通信网络以及空天地海一体化数字底座等核心技术突破。6G网络正演进为支持智能体动态组网和意图解析的“智能中枢”，赋能具身智能、低空无人机和卫星通信等新型应用场景。","scd":null,"kp":["网络架构[6G演进]: 空天地一体化网络","[6G智能体通信(ACN)样机]: 支持智能体互联互通与安全可控对话平台","核心技术[6G智能体通信]: 智能体动态组网、意图解析、智能体通信开放平台"]},{"i":2952,"as":"上海“模速空间”AI黑科技体验空间展陈了数百款全球前沿AI智能产品。核心展品包括：通过传感器捕捉手部动作并配合灯光引导弹奏的智能无弦吉他，以及具备AI对话、情绪识别和仿生记忆系统、能随互动形成独特性格的AI陪伴玩偶“芙崽”。“芙崽”自2025年7月发售至2024年4月累计销量突破25万台。","scd":null,"kp":["交互方式[智能无弦吉他]: 通过传感器精准捕捉手部动作模拟弹奏效果"]},{"i":2953,"as":"2026夏季达沃斯论坛聚焦“规模化创新”，前沿科技正加速从实验室走向应用场景。现场展出高1.7米、重65千克的人形机器人MATRIX-3，具备真实空间互动与持续部署能力。论坛发布《2026年十大新兴技术》报告，指出这些技术将在能源、医疗、制造等领域催生新模式，应对全球性挑战。","scd":null,"kp":["身高[人形机器人MATRIX-3]: 1.7米","重量[人形机器人MATRIX-3]: 65千克","核心优势[人形机器人MATRIX-3]: 真实空间中的持续互动、服务承接与长期部署能力"]},{"i":2954,"as":"第四届中国国际链博会现场展示了浙江强脑科技2020年量产的第一代智能仿生手。该仿生手可覆盖80%以上的日常生活场景，既能提起30公斤重物，也可夹起0.1毫米细物而不损坏生鸡蛋，并能应对攀岩等运动场景。该技术致力于帮助残障人士重拾生活便利。","scd":null,"kp":["上市状态[第一代智能仿生手]: 2020年实现量产","场景覆盖率[第一代智能仿生手]: 约80%的日常生活场景","承载力[第一代智能仿生手]: 提起30公斤重物","精细操作力[第一代智能仿生手]: 夹起0.1毫米细物不破损"]},{"i":2955,"as":"夏季达沃斯论坛聚焦“AI生产力悖论”。科技巨头今年在AI基础设施资本支出超7000亿美元，但普华永道报告显示，仅少数企业通过AI实现财务收益。专家指出这种“高投入、低产出”被称为“幽灵效率”，原因是AI技术与组织、场景、人才之间存在深层错配，且法律法规等软性基建落后于模型迭代。","scd":null,"kp":["AI基础设施资本支出[亚马逊/Alphabet/微软/Meta今年计划]: 超过7000亿美元","AI影响[部分企业过去三年]: 尚未对公司发展产生可衡量的影响"]},{"i":2956,"as":"2026大连夏季达沃斯论坛指出，能够感知物理规律并操控实体设备执行任务的“物理AI”是下一阶段重要发展方向。利用视觉信息和整体环境理解现实世界的“世界模型”被视为关键工具，并被《2026年十大新兴技术》报告列为未来5年重塑产业格局的核心技术。物理AI正日益走进现实物理世界。","scd":null,"kp":["[物理AI核心特征]: 能够感知和理解现实世界物理规律，并操控实体设备在真实环境里自主执行任务，能够对现实世界运行规律进行建模与模拟"]},{"i":2957,"as":"中国科研团队在《细胞》杂志发布世界首个人类胚盘样原肠模型研究成果。研究团队在体外成功构建类胚盘模型，自主生成原条样区域，精准重现人类原肠运动及器官有序形成动态过程。超过80%的结构进一步发育形成神经管、原始心腔及肺、肝等器官前体细胞，原始心腔表现出自主节律性收缩。","scd":null,"kp":[]},{"i":2958,"as":"第四届中国国际供应链促进博览会将“数字科技链”升级为“数智科技链”，并首次设立人工智能专区。展区全链条展现了人工智能从数据采集、智能计算到场景落地的完整生态，呈现了AI新产品赋能千行百业的图景。","scd":null,"kp":["[第四届中国国际供应链促进博览会]: 首次将“数字科技链”升级为“数智科技链”，新设立人工智能专区展现全链条生态"]},{"i":2959,"as":"第四届链博会显示，AI已深度嵌入产业链与供应链闭环生态。《全球供应链促进报告》指出AI形成上游底座支撑、中游驱动技术跃迁、下游反哺基础设施升级的动态协同机制。多家光学与制造供应商案例展现了AI如何赋能供应链，体现中国产业升级内生动力。","scd":null,"kp":["[AI供应链闭环生态]: 上游提供底座支撑，中游驱动技术跃迁，下游反哺基础设施升级，三者形成动态协同"]},{"i":2960,"as":"中国移动在2026上海世界移动通信大会上宣布，其自研模型服务平台MoMA已汇聚300多款主流AI模型，建成规模化“词元超市”。该平台应用智能路由调度、缓存和词元压缩等技术，成功使单位词元推理成本降低约30%。","scd":null,"kp":["汇聚模型数量[中国移动自研模型服务平台MoMA]: 300多款主流AI模型","单位词元推理成本降低[应用智能路由调度/智能缓存/词元压缩等技术]: 约30%"]},{"i":2961,"as":"中国中化在第四届中国国际链博会上展出人形机器人灵巧手肌腱绳材料。该特种纤维丝绳直径仅0.8毫米，由五根组成的丝绳结构能够让人形机器人的手部抓握力达到250公斤，展现了机器人核心部件的材料突破。","scd":null,"kp":["丝绳规格[人形机器人灵巧手肌腱绳特种纤维]: 0.8毫米","抓握力[五根特种纤维丝绳协同]: 达到250公斤"]},{"i":2962,"as":"工信部与国务院国资委联合印发通知，提出到2026年底人形机器人重点产品在代表性场景中完成应用验证，从“表演模式”转向“作业模式”。2025年国内整机企业超140家，发布产品超330款。作业模式要求机器人在真实生产流程中保证任务完成质量、持续稳定运行及实现商业闭环。","scd":null,"kp":["整机企业数量[2025年国内人形机器人领域]: 超140家","发布产品数量[2025年国内人形机器人领域]: 超330款","常态化作业目标[2026年度人形机器人实景实训专项行动]: 到2026年底在一批代表性场景中率先完成应用验证和常态部署"]},{"i":2963,"as":"五部门联合印发通知部署开展工业5G独立专网试点，支持大型企业建设不依赖公网的专属5G网络。试点涵盖基础设施部署、创新应用场景等五个方面，重点挖掘5G-A技术在超低时延、无源物联等方面的潜力。国家鼓励通过专项资金与产业基金支持定制化芯片等产品的研发与产业化部署。","scd":null,"kp":["[工业5G独立专网]: 由工业企业主导建设接入网、核心网等关键设施，可不依赖于公网独立运行的企业专属5G网络","试点支持领域[工业5G独立专网]: 原材料、装备制造、消费品、电子信息、国防科技、能源交通等行业的大型特大型企业","[5G/5G-A技术特性应用潜力]: 高速传输、超低时延、通感一体、无源物联、高精定位、网络智能"]},{"i":2964,"as":"“数据要素×”三年行动计划实施以来成效显著。国家数据局累计发布417个典型案例和760个场景指引。2025年全国活跃数据总量达1.67泽字节，企业数据交易额同比增长39.8%。交通、科技、住建等领域加速数据汇聚共享，其中中国科学院累计汇聚科学数据超320拍字节，93%实现开放共享。","scd":null,"kp":["典型案例发布量[数据要素三年行动计划累计]: 417个","典型场景指引[11个行业领域]: 760个","全国活跃数据总量[2025年]: 1.67泽字节（ZB）","同比增长[2025年全国活跃数据总量]: 28.46%","同比增长[2025年企业数据产品和服务数量]: 29.29%"]},{"i":2965,"as":"可再生能源公司Enlight为其位于美国亚利桑那州的CO Bar太阳能和储能项目成功筹集了26亿美元（约合人民币）的资金。","scd":null,"kp":["项目融资额[Enlight亚利桑那州CO Bar太阳能和存储项目]: 26亿美元"]},{"i":2966,"as":"DTEK与Octopus将组建合资企业，计划在乌克兰投资1亿欧元，共同开发太阳能发电与储能项目。","scd":null,"kp":["投资规模[乌克兰太阳能和储能合资项目]: 1亿欧元"]},{"i":2967,"as":"阿根廷针对700兆瓦（MW）规模的电池储能系统（BESS）项目招标，收到了大量价格投标。","scd":null,"kp":["招标规模[阿根廷BESS项目]: 700 MW"]},{"i":2968,"as":"新能源云公布2026年第六批可再生能源发电补贴项目清单。本次纳入补贴清单的项目共9个，核准/备案容量74.15兆瓦，含集中式62.25兆瓦、分布式11.9兆瓦。此外，变更补贴清单的项目共149个，核准/备案容量1516.02兆瓦，含集中式1493.95兆瓦、分布式22.07兆瓦。","scd":null,"kp":["项目数量[2026年第六批可再生能源发电补贴新增清单]: 9个","核准/备案容量[2026年第六批可再生能源发电补贴新增清单]: 74.15兆瓦","集中式容量[2026年第六批可再生能源发电补贴新增清单]: 62.25兆瓦","分布式容量[2026年第六批可再生能源发电补贴新增清单]: 11.9兆瓦","项目数量[2026年第六批可再生能源发电补贴变更清单]: 149个"]},{"i":2969,"as":"中国电建承建的陕西大唐府谷100兆瓦山地集中式光伏项目正式开工。项目采用650W高效光伏组件及组串式逆变器，新建110千伏升压站。建成并网后预计年均上网发电量达15602.7万千瓦时，每年可节约标准煤4.72万吨，减少二氧化碳排放12.81万吨。","scd":null,"kp":["总装机容量[陕西大唐府谷光伏项目]: 100兆瓦","场区海拔[陕西大唐府谷光伏项目]: 800米至1200米","光伏发电单元[陕西大唐府谷光伏项目]: 46个","光伏组件[陕西大唐府谷光伏项目]: 高效650W","组串式逆变器[陕西大唐府谷光伏项目]: 313台320千瓦"]},{"i":2970,"as":"阿特斯阳光电力集团与内蒙古乌拉特中旗签约风光制氢氨一体化项目，总投资85亿元。计划建设年产5万吨绿氢、26万吨绿氨生产线，配套100万千瓦风电项目。全程采用风电绿电驱动，计划于2026年12月完成项目预审。","scd":null,"kp":["总投资[乌拉特中旗风光制氢氨一体化项目]: 85亿元人民币","绿氢产能[乌拉特中旗风光制氢氨一体化项目]: 5万吨/年","绿氨产能[乌拉特中旗风光制氢氨一体化项目]: 26万吨/年","配套风电装机[乌拉特中旗风光制氢氨一体化项目]: 100万千瓦"]},{"i":2971,"as":"国家能源局贵州监管办发布拟注销公告。因人员情况发生重大变化且整改后仍不满足最低许可等级条件，拟注销贵州友邦众力建筑安装工程有限公司等102家企业持有的承装（修、试）电力设施许可证。","scd":null,"kp":["[承装（修、试）电力设施许可证注销]: 102家企业因人员重大变化且整改不达标被拟注销"]},{"i":2972,"as":"中节能太阳能股份有限公司发布青海500MW源网荷储一体化光伏项目EPC工程总承包招标公告。项目包含交直流侧装机500MW光伏厂区、330kV升压站及送出线路等，不含储能系统。工程计划于2026年12月30日前全容量并网，总工期510天。投标人须具备2021年以来累计不低于200MW的设计/施工业绩及220kV以上升压站业绩，不接受联合体投标。投标截止时间为2026年7月14日。","scd":null,"kp":["交流侧装机[青海莱德宝源网荷储一体化光伏项目]: 500MW","直流侧装机[青海莱德宝源网荷储一体化光伏项目]: 500MWp","升压站[青海莱德宝源网荷储一体化光伏项目]: 新建330kV","全容量并网节点[青海莱德宝源网荷储一体化光伏项目]: 2026年12月30日前","总工期[青海莱德宝源网荷储一体化光伏项目]: 510天"]},{"i":2973,"as":"中国电建多个新能源项目相继并网发电。包括全球最大的滨州沾化2吉瓦渔光互补项目（三期全容量并网，年发清洁电能2.7亿千瓦时）、湖南益阳80兆瓦光伏项目、浙江缙云50兆瓦农光互补项目、江苏宿迁250兆瓦全柔性支架果园农光互补项目、云南玉溪100兆瓦茶光互补项目，以及新疆精河100万千瓦光伏项目（首期并网，配套40万千瓦时储能）。各项目显著节约标煤并减排二氧化碳，实现生态与经济效益双赢。","scd":null,"kp":["总装机容量[滨州沾化渔光互补发电项目]: 2吉瓦","占地面积[滨州沾化渔光互补发电项目]: 约6.6万亩","年提供清洁电能[滨州沾化渔光互补发电项目]: 约2.7亿千瓦时","开发模式[滨州沾化渔光互补发电项目]: 水上发电、水下养殖","总装机容量[益阳向阳湖光伏项目]: 80兆瓦"]},{"i":2974,"as":"国家发展改革委与国家能源局联合印发《新型能源体系建设“十五五”规划》（发改能源〔2026〕884号）。该规划已获国务院同意，正式下发给各省级人民政府、国务院有关部委、直属机构及有关中央企业，要求各单位认真贯彻实施，以推进“十五五”期间新型能源体系的建设工作。","scd":null,"kp":["[《新型能源体系建设“十五五”规划》]: 国家发改委与国家能源局联合印发规划"]},{"i":2975,"as":"泉州台商投资区管理委员会科技经济发展局发布分布式光伏接入电网承载力信息通告。截至2026年第二季度末，该区域分布式电源装机总容量达20.088万千瓦，可开放并网容量区间为36.08至56.22万千瓦。通告同时公布了220-35千伏主变、10千伏配变的承载力及可开放容量评估结果，并提供分布式电源承载力提升措施报告。","scd":null,"kp":["分布式电源装机总容量[泉州台商投资区(截至2026年Q2)]: 20.088万千瓦","可开放并网容量区间[泉州台商投资区(截至2026年Q2)]: 36.08-56.22万千瓦"]},{"i":2976,"as":"北京市通州区经济和信息化局印发措施，支持工业和软件信息服务业绿色低碳转型。措施明确，对建设分布式光伏、储能、地源热泵等新能源利用项目及制造业绿色改造升级，给予最高100万元资金支持。同时，针对实现低碳零碳转型（碳排放强度下降5%且净减排500吨以上）及首次开展碳足迹管理的企业，分别给予最高50万元支持，以构建绿色低碳生产模式。","scd":null,"kp":["最高支持资金[新能源利用项目]: 100万元","[工业和软件信息服务业]: 鼓励使用可再生能源替代化石能源，支持分布式光伏、储能等项目建设"]},{"i":2977,"as":"鄂托克旗发布2026年分散式风电及分布式光伏项目优选工作的相关公告。","scd":null,"kp":[]},{"i":2978,"as":"在核心研究员接连离职后，谷歌正重组其AI编程专项小组以追赶Anthropic。重组将扩大业务范围，兼顾代码生成与其他场景能力，并将临时团队正式固化。此前，两位Gemini模型关键贡献者Jonas Adler和Alexander Pritzel确认跳槽至Anthropic，谷歌近期还流失了诺奖得主John Jumper及Gemini联席负责人。此外，谷歌下一代前沿AI模型Gemini 3.5 Pro的发布时间已推迟至7月。","scd":null,"kp":["[AI编程工具专项攻坚小组]: 重组并正式固化团队架构，调整模型训练思路以扩大业务场景","[AI模型训练思路]: 提升代码能力并强化生成演示文稿等其他场景能力"]},{"i":2979,"as":"","scd":null,"kp":[]},{"i":2980,"as":"","scd":null,"kp":[]},{"i":2981,"as":"苹果代工厂塔塔电子遭遇大规模网络攻击，超630GB机密数据泄露。泄露文件包括未发布的iPhone 18 Pro Max主板设计图纸（Siemens NX制作）、代号为“Borneo”的A20 Pro芯片数据手册以及代号为“Ganymede”的自研C2基带芯片文档。A20 Pro确认将在性能、ISP和显示安全性上升级，C2基带将应用于iPhone 18 Pro系列。资料还涉及特斯拉组件设计，苹果已对此展开全面调查。","scd":null,"kp":["泄露数据量[塔塔电子网络攻击]: 超过630GB","泄露文件数[塔塔电子网络攻击]: 超过20万个","主板设计工具[iPhone 18 Pro系列图纸]: Siemens NX","主板内部代号[iPhone 18 Pro系列]: V63与V43"]},{"i":2982,"as":"","scd":null,"kp":[]},{"i":2983,"as":"","scd":null,"kp":[]},{"i":2984,"as":"华硕率先为多款AM5主板发布测试版BIOS更新，集成AMD AGESA PI 1.3.0.1b Patch A补丁，为AMD锐龙9000系列桌面处理器恢复TSME（透明安全内存加密）支持。TSME是一项通过处理器密钥自动加密内存数据的硬件级安全功能，可有效抵御“冷启动攻击”。此前AMD在AGESA 1.2.7.0及后续固件中系统性地移除了消费级Ryzen处理器的该特性，引发社区强烈不满，现通过BIOS得以回归。","scd":null,"kp":["BIOS版本[华硕AM5主板]: AMD AGESA ComboAM5 PI 1.3.0.1b Patch A","加密特性[AMD 锐龙9000系列桌面处理器]: 恢复TSME（透明安全内存加密）硬件级功能支持"]},{"i":2985,"as":"","scd":null,"kp":[]},{"i":2986,"as":"紫光同芯联合中国联通在MWC上海首发eSIM终端智能受理创新解决方案。该方案摒弃传统繁琐的人工扫码操作，搭建用户终端与运营商业务后台的独立加密直连通道，系统自动实时获取终端激活核心数据，显著缩短业务办理时长。方案采用标准化密钥交换策略和多CI证书体系，实现双向数据加密、身份认证及eUICC芯片合法性核验，从底层防范非法终端入网与数据篡改风险。目前已支持现阶段所有已上市eSIM手机。","scd":null,"kp":["身份认证机制[业务系统与手机终端]: 标准化密钥交换策略双向数据加密","合法性核验机制[终端eUICC芯片]: 多CI证书体系","适用范围[eSIM智能受理方案]: 现阶段已上市的全部eSIM手机机型"]},{"i":2987,"as":"","scd":null,"kp":[]},{"i":2988,"as":"","scd":null,"kp":[]},{"i":2989,"as":"数据显示，2025年中国具身智能市场规模约达9150亿元，相关企业数量突破万家，预计今年将冲上万亿规模。目前具身智能产业链已形成从核心零部件到整机系统再到场景应用的闭环。国家发改委正全面推进该领域高质量发展，加快训练基础设施建设。教育部在2026年本科专业目录的“交叉学科”门类中，首批新增列入了具身智能、脑机科学与技术等专业，以支撑产业人才需求。","scd":null,"kp":["市场规模[2025年中国具身智能]: 约9150亿元","市场预期[中国具身智能]: 预计今年将冲上万亿","新增本科专业[2026年交叉学科门类]: 具身智能、脑机科学与技术等"]},{"i":2990,"as":"针对多名宝马i3、i4新车车主收到“更换蓄电池”车机提醒一事，宝马官方回应称此为误报信息。宝马强调该问题不会影响车辆12V低压小电瓶及高压电池的正常运行，车主无需采取任何更换措施。官方已向相关车主推送说明信息，正积极推进解决方案以确保错误提示不再出现。同时，对仍有疑虑的车主，宝马建议可前往就近经销商处进行免费检测。","scd":null,"kp":["故障原因[宝马i3/i4车机提示]: 相关更换蓄电池提示信息为软件误报","低压蓄电池质保[宝马i3/i4车型]: 随整车质保三年或10万公里"]},{"i":2991,"as":"","scd":null,"kp":[]},{"i":2992,"as":"2026上海世界移动通信大会开幕，聚焦6G、移动AI、具身智能等领域。华为携手国内三大运营商发布了5G-A大上行、AI焕新主营业务、Token经营等创新成果，并发布AI-Centric目标网。目前5G-A用户数已破亿。2026年被视为U6GHz频谱商用元年，可满足智能体互联网时代的大上行需求。华为宣布将在广东、上海等地通过AI重构主营业务，并打造以“算+网”为中心的AI算力服务。","scd":null,"kp":["用户数[5G-A网络]: 已破亿","下一代网络频谱[智能体互联网时代]: U6GHz（端到端产业生态已就绪）"]},{"i":2993,"as":"鸿蒙智行尊界V800与V680车型预售开启1小时后，双车订单量突破3200台，其中尊界V800订单占比达84%。两款车型在品牌盛典上完成首发亮相，预计将于8月初正式上市发布。核心参数方面，尊界V800车身尺寸为5495mm×2006mm×1850mm，轴距达3430mm；尊界V680车身尺寸为5320mm×2006mm×1850mm，轴距为3290mm。预售价设定为65万元起。","scd":null,"kp":["订单量[尊界V800/V680预售1小时]: 突破3200台","预售价[尊界V800/V680]: 65万起","车身尺寸及轴距[尊界V800]: 5495mm×2006mm×1850mm，轴距3430mm","车身尺寸及轴距[尊界V680]: 5320mm×2006mm×1850mm，轴距3290mm"]},{"i":2994,"as":"Adobe宣布与AI图像及视频增强工具开发商Topaz Labs达成最终收购协议，交易预计于2026年下半年完成。Topaz Labs拥有超二十年技术积累，其Astra与Wonder模型分别用于AI视频放大升频和图像润饰，并研发了能让复杂AI模型在消费级GPU上流畅运行的Neurostream专有技术。Adobe计划将Topaz Labs的AI模型整合至Firefly、Photoshop、Lightroom及Premiere等Creative Cloud产品中。交易完成后，Topaz Labs现有产品将继续作为独立服务通过其官网提供。","scd":null,"kp":["收购预计完成时间[Adobe收购Topaz Labs]: 2026年下半年","[AI模型本地运行]: 拥有专有技术Neurostream，能使大型复杂AI模型在消费级GPU上流畅运行"]},{"i":2995,"as":"宁德时代（CATL）预计今年内将有多达1万至2万辆搭载其新型钠离子电池的电动汽车进入市场。此外，宁德时代发布了首款采用钠离子电芯的固定式电池储能系统。在2026年4月的超级科技日上，宁德时代推出了能量密度高达175 Wh/kg的Naxtra钠离子电池，该电池计划于今年晚些时候进入量产阶段，并将为长安启源A06纯电动车型提供动力。","scd":null,"kp":["市场规模[CATL钠离子电池汽车配备目标]: 10000至20000辆","发布时间[CATL Naxtra钠离子电池]: 2026年4月"]},{"i":2996,"as":"大众汽车集团旗下电池子公司PowerCo已选择纳米技术公司OCSiAl作为其统一电芯电池平台的供应商。OCSiAl将为其标准化电池电芯中的石墨负极提供纳米管添加剂，这些添加剂将在其位于塞尔维亚的生产基地进行制造。OCSiAl的TUBALL纳米管是一种单壁碳纳米管，能够形成导电且强化的三维网络，可有效稳定锂离子电池中的正极和负极系统。","scd":null,"kp":["负极添加剂[PowerCo标准电池单元石墨负极]: OCSiAl供应的纳米管添加剂"]},{"i":2997,"as":"阿斯利康在“2026年全球供应链25强”中荣获第五名，主要得益于其“自愈合供应链”系统。该网络利用持续检测、场景分析和智能体能力来解决供应链中断问题，大幅减少了人工干预的需求。此外，阿斯利康的成功因素还包括应用AI提升员工技能，将数字技能、AI素养和数据驱动思维直接嵌入运营中，构建了自主化工作团队。","scd":null,"kp":["排名[阿斯利康2026年全球供应链25强]: 第五名","[自修复供应链]: 采用持续检测、情景分析和代理能力来解决中断，极少需要人工干预"]},{"i":2998,"as":"","scd":null,"kp":[]},{"i":2999,"as":"现代汽车在欧洲推出了小型纯电动SUV Inster的全新旗舰车型Inster Lounge，进一步提升了该细分市场的豪华感。现代Inster是欧洲市场体积最小、价格最亲民的纯电动车，起售价低于2.5万欧元，曾是2025年欧洲销量第二的A级电动车。与越野风格的Inster Cross不同，全新的Inster Lounge车型采用了更具高级感的内饰设计，并增加了多项额外配置，将都市SUV的设计、舒适度与专属感相结合。","scd":null,"kp":["起售价[现代Inster电动SUV欧洲市场]: 低于25,000欧元"]},{"i":3000,"as":"美国能源信息署（EIA）最新数据显示，2026年前四个月，可再生能源占美国总发电量的30.0%，同比增长2.2%，发电量较2025年同期增长10.03%。增长主力包括公用事业规模太阳能（+21.3%）、水电（+15.7%）、小规模太阳能（+11.9%）和风能（+3.4%）。同期，美国煤电厂发电量下降11.6%，核能发电量微增0.5%，天然气发电量增长2.8%。","scd":null,"kp":["发电占比[2026年前四个月美国可再生能源]: 30.0%","同比增长率[2026年前四个月美国可再生能源发电量]: 10.03%"]},{"i":3001,"as":"特斯拉就一起涉及“全自动驾驶”（FSD）系统的行人致命交通事故诉讼达成秘密和解，具体条款未披露。事故发生于2023年11月28日的亚利桑那州高速公路，一名71岁女性在协助疏导前方事故交通时，被一辆在FSD模式下高速行驶的特斯拉Model Y撞击身亡。这是已知首起与特斯拉FSD系统相关的行人死亡事件，该碰撞事故也引发了覆盖320万辆特斯拉汽车的联邦调查。","scd":null,"kp":["事故发生时间[特斯拉FSD致行人死亡事故]: 2023年11月28日","波及车辆规模[触发联邦调查的特斯拉汽车数量]: 320万辆"]},{"i":3002,"as":"在釜山国际移动出行展上，起亚推出了三款PV5纯电动货车新车型，其中包括一款7座版本。起亚PV5提供客运、货运和底盘驾驶室三种车身类型，基于现代E-GMP.S架构打造，该平台的模块化设计为新车型解锁了丰富的扩展可能性。凭借出色的实际效率、灵活的内饰设计和现代科技配置，起亚PV5荣获2026年国际年度货车称号，成为首款获此殊荣的韩国车型。","scd":null,"kp":[]},{"i":3003,"as":"特斯拉Semi电动半挂卡车项目主管分享了车辆在冰雪路面上行驶的视频，展示了其车辆动态控制系统（VDC）的卓越性能。通过高分辨率传感器和自主研发的精确多电机控制技术，特斯拉Semi能够在湿滑结冰的复杂冬季路面上提供精准的扭矩分配和稳定性控制。这套系统证明了电动传动系统在牵引力和车身控制方面优于传统柴油卡车，可有效防止重型卡车在打滑时失控。","scd":null,"kp":["控制系统[Tesla Semi冰雪路面防滑控制]: 车辆动态控制系统（VDC），可通过高分辨率电动动力总成在打滑时重获控制"]},{"i":3004,"as":"大众汽车正筹备公司历史上最大规模的重组计划。据报道，该计划在全球范围内最多将裁员10万人，并最终关闭德国的4家工厂。报道指出，大众汽车位于汉诺威、茨维考和埃姆登的生产基地，以及位于巴登-符腾堡州的奥迪内卡苏尔姆工厂，将在当前车型项目逐步停产后结束生产。此项重组方案的规模远超大众汽车此前宣布的成本削减措施，但官方尚未正式确认。","scd":null,"kp":["裁员规模[大众汽车重组计划]: 全球最多10万个工作岗位","工厂关闭数量[大众汽车重组计划]: 4家德国工厂"]},{"i":3005,"as":"欧盟预计将在6月底前发布欧洲氢能银行（EHB）第四次拍卖的条款和条件草案。据欧洲氢能组织透露，第四次拍卖将在2026年底前启动。为优化拍卖机制，该协会建议采取更灵活的投运期限和更严格的财务结算标准，并推动EHB与未来承购项目之间实现生产与需求支持的协调使用。此外，氢能的作用正日益突显其在地缘政治方面的重要性。","scd":null,"kp":["[第四次氢拍卖]: 预计在2026年底前启动"]},{"i":3006,"as":"阿根廷首轮大规模电池储能采购（AlmaSADI）的开标价格远低于拍卖价格上限。本次采购的出价范围在每月7,397美元/兆瓦至最高限价12,500美元/兆瓦之间，所有合格项目的加权平均出价为每月10,568.4美元/兆瓦，比拍卖价格上限低约15.5%。此经济投标阶段共收到来自37家国内外企业的232份合格提案，总申报容量达8,230兆瓦，远超本次计划的700兆瓦采购容量。","scd":null,"kp":["最低出价[阿根廷电池存储拍卖]: 7,397美元/兆瓦/月","最高出价上限[阿根廷电池存储拍卖]: 12,500美元/兆瓦/月","竞标容量[阿根廷电池储能采购]: 700 MW","合格提案数量[阿根廷电池储能采购]: 232份"]},{"i":3007,"as":"欧洲女性太阳能协会（WiSEu）在2026年Intersolar Europe展会上举办了旗舰研讨会，聚焦能源转型中塑造女性职业生涯的双重标准问题。研讨会以“通过能源转型的双重标准进行领导”为主题，探讨了在可见度、可信度、母亲角色、人际网络以及组织文化等方面依然存在的障碍。会议重点强调了实现公平能源转型所需的领导行为、盟友关系及结构性改革。","scd":null,"kp":[]},{"i":3008,"as":"据Renewabl首席执行官透露，2025年企业购电协议（PPA）的交易量下降了10%。其下降原因在于《温室气体核算体系》范围2（Scope 2）指导原则即将更新，该不确定性导致部分买家持观望态度。这一核算标准的修订正在让太阳能企业PPA交易市场的需求降温，但当相关规定具备更多确定性时，交易量有望迎来回升。此外，向每小时匹配机制的转变将使电池储能系统成为核心焦点。","scd":null,"kp":["企业PPA交易量下降幅度[2025年温室气体协议不确定性]: 10%","[电网匹配机制]: 向每小时匹配转变以凸显电池储能的核心地位"]},{"i":3009,"as":"NextPower正通过一系列收购和新产品发布，将其业务从单一的太阳能跟踪支架制造商迅速扩展为更广泛的清洁能源技术提供商。NextPower首席执行官表示，公司的业务转型及在逆变器、电池储能系统和安装系统领域的最新收购，完全是受客户需求驱动而非盲目扩张战略。这一转型使其能够为客户提供更全面的清洁能源技术解决方案。","scd":null,"kp":[]},{"i":3010,"as":"本周中国光伏上游供应链持续疲软，多晶硅价格继续走低，而硅片价格保持稳定。数据显示，N型复投多晶硅价格在每吨31,000至34,000元人民币之间，均价为每吨33,200元，周环比下跌0.02%。N型颗粒硅价格在每吨32,000至33,000元人民币之间，均价跌至每吨32,500元，周环比下降0.05%。N型G10L硅片等硅片产品价格则保持不变。","scd":null,"kp":["N型复投料多晶硅价格[中国]: 31,000至34,000元/吨 (4,559至5,000美元/吨)","硅片价格[中国]: 保持不变"]},{"i":3011,"as":"意大利光伏协会Italia Solare探讨了储能对意大利能源系统的重塑。目前，意大利新增光伏系统中有80%配备了电池，住宅光伏及储能系统正迅速扩张。然而，工商业光伏储能细分市场仍存在结构性弱点。此外，尽管该国分布式储能基础规模快速增长，但灵活性市场的监管推进依然相对缓慢，限制了储能系统商业化机制的全面激活。","scd":null,"kp":["光伏系统配储比例[意大利新建住宅光伏]: 80%"]},{"i":3012,"as":"全球太阳能委员会农业光伏高级顾问表示，农业光伏正从一种应对土地限制的边缘替代方案，迅速演变为一个具备自身技术、农学和经济逻辑的独立行业细分市场。随着农业光伏领域的技术、农业和社会复杂性不断提升，太阳能行业必须从根本上重新思考与农民和农村社区的合作模式，以适应这一结构化细分市场的快速发展。","scd":null,"kp":[]},{"i":3013,"as":"隆基在德国慕尼黑发布了一款集装箱式光伏电站。该系统集成光伏组件、支架和固德威GT系列逆变器，无需永久性基础，可在几小时内快速部署，专为离网工业设施提供可再生能源。在欧洲（如乌克兰和波兰）市场，该系统的平准化度电成本（LCOE）约为0.0413至0.045欧元/千瓦时。","scd":null,"kp":["度电成本(LCOE)[隆基便携式集装箱光伏电站(欧洲市场)]: 0.0413至0.045欧元/千瓦时","系统集成[隆基便携式集装箱光伏电站]: 融合组件、结构与固德威GT系列逆变器","[系统特性]: 快速部署的离网系统"]},{"i":3014,"as":"西班牙海军S-80 Plus级潜艇的第二艘舰“Narciso Monturiol”（S-82）已正式开始海试，这是交付舰队前的关键阶段。该潜艇由西班牙造船商Navantia在卡塔赫纳造船厂建造，排水量为3000吨级，旨在取代老旧的阿戈斯塔级潜艇，是西班牙技术最复杂的国防项目之一。","scd":null,"kp":["潜艇吨位[西班牙S-80 Plus级攻击潜艇]: 3000吨级","[当前状态]: S-82（同级第二艘）正在进行海试"]},{"i":3015,"as":"由于创纪录的热浪导致河流温度超出环保限制，法国电力公司（EDF）暂时关闭了多座核反应堆，包括塞纳河、罗纳河和加伦河沿岸的核电站。法国核电站严重依赖河水冷却，此次停机和减产措施旨在保护河流生态系统免受高温废水影响，而非出于反应堆本身的安全问题。","scd":null,"kp":["[核反应堆冷却运行]: 高温热浪导致河流水温超出环保限制，被迫关闭反应堆"]},{"i":3016,"as":"欧洲导弹制造商MBDA在巴黎防务展上展示了一款名为FastTrack的AI辅助任务规划系统。该系统可将巡航导弹飞行计划的生成时间从数小时缩短至几分钟。FastTrack能够综合考虑地形等因素进行路径规划，有效帮助新型陆基巡航导弹（LCM）躲避防空系统，大幅压缩远程精确打击的准备时间。","scd":null,"kp":["任务规划耗时[AI辅助巡航导弹]: 从数小时缩短至几分钟"]},{"i":3017,"as":"宝马集团在美国斯帕坦堡工厂部署了新一代Figure 03人形机器人，用于处理复杂的物流排序任务。此前为期11个月的Figure 02机器人部署证明，人形机器人能够作为可靠、灵活的制造生力军投入实际应用。此举是宝马推进物理AI和智能制造生产的重要举措。","scd":null,"kp":["应用状态[Figure 03人形机器人]: 部署于智能工厂执行复杂物流排序任务","验证周期[Figure 02人形机器人]: 11个月"]},{"i":3018,"as":"","scd":null,"kp":[]},{"i":3019,"as":"","scd":null,"kp":[]},{"i":3020,"as":"","scd":null,"kp":[]},{"i":3021,"as":"","scd":null,"kp":[]},{"i":3022,"as":"","scd":null,"kp":[]},{"i":3023,"as":"","scd":null,"kp":[]},{"i":3024,"as":"","scd":null,"kp":[]},{"i":3025,"as":"九州大学的科学家开发出一种固态分子材料，能够通过量子世界中低能光子结合能量的原理，将普通的可见阳光直接转换为紫外线。在自然户外阳光照射下，该材料实现了1.9%的光转换效率。这项发表在《自然通讯》上的技术突破了常规物理限制，为太阳能驱动的紫外线技术应用开辟了新途径。","scd":null,"kp":["[光子能量上转换]: 量子领域两个低能光子结合能量形成单个高能光子","转换结果[新型材料]: 将普通阳光转化为紫外线"]},{"i":3026,"as":"针对别墅业主面临的夏季电费暴涨（高达数千元）、突发断电导致电梯停运及鱼缸医疗设备失效等用电痛点，常规的更换高能效空调等“节流”手段效果有限。文章指出，别墅高能耗源于大面积落地窗暴晒、挑空客厅聚热及地下室全天除湿。为兼顾生活品质与电费控制，别墅业主亟需通过光储充系统解决方案来实现“用电自由”和应急备电。","scd":null,"kp":[]},{"i":3027,"as":"针对闲置荒山、滩涂等地形复杂、生态脆弱的土地，光伏行业推出了地面集中式“光伏+”综合解决方案。该方案不单纯铺设光伏板，而是因地制宜设计复合开发模式：山地采用“随坡就势”排布；滩涂注重克服地质软和腐蚀性问题。通过一地多用，将光伏发电与农业种植、水产养殖和生态修复协同发展，最大化提升项目经济与生态效益。","scd":null,"kp":["[地形地质挑战]: 荒山坡度大且滩涂地质软、承载力低，施工窗口期受潮汐影响短","[生态平衡要求]: 需统筹兼顾水土流失防范、生物多样性保护与光伏发电"]},{"i":3028,"as":"SpaceX的债务市场表现疲软，导致公司股价跌破了其第一交易日的发行价格。","scd":null,"kp":[]},{"i":3029,"as":"三星集团宣布计划在韩国进行总额高达6480亿美元的大规模投资。这笔巨额资金将用于多个核心领域，其中包括新建半导体晶圆代工厂，以进一步扩大其在全球半导体制造领域的产能和技术优势。","scd":null,"kp":["投资规模[韩国本土含新建代工厂]: 6480亿美元"]},{"i":3030,"as":"","scd":null,"kp":[]},{"i":3031,"as":"","scd":null,"kp":[]},{"i":3032,"as":"法国独立发电商Neoen获得加拿大安大略省独立电力系统运营商（IESO）的20年期合同，将建设一座200兆瓦/1600兆瓦时（8小时储能）的电池储能系统。该项目旨在用电低谷期储电并在高峰期放电。项目位于安大略省西北部，预计2028年动工，2030年投入商业运营，由Neoen与当地原住民社区Eagle Lake First Nation共同所有。","scd":null,"kp":[]},{"i":3033,"as":"意大利太阳能协会秘书长在德国慕尼黑展会上评估了意大利光伏与储能现状。意大利储能市场正处于强劲增长阶段，住宅、工商业及公用事业规模细分市场表现不一。其中，住宅储能市场的繁荣主要受到生态奖金（即个人所得税退税）等近期激励政策的驱动。","scd":null,"kp":["发展特征[意大利储能市场]: 处于强劲增长阶段，但各细分市场扩展呈现非均衡性"]},{"i":3034,"as":"意大利环境与能源安全部批准了总容量300兆瓦的三个电池储能系统项目。其中包括英国开发商在莱切省建设的100兆瓦/800兆瓦时项目，以及米兰开发商在阿韦利诺省建设的两个100兆瓦项目。","scd":null,"kp":["总授权容量[意大利环境部新批BESS项目]: 300 MW","储能容量[Galatina 1 BESS项目]: 100 MW/800 MWh"]},{"i":3035,"as":"Engie秘鲁公司开始在莫克瓜地区建设Hanaqpampa太阳能+储能项目。该项目包含140.8兆瓦光伏电站和15兆瓦电池储能系统，投资超1.27亿美元。项目配备超20万块光伏组件、变电站及输电线，计划于2028年一季度投运，预计将创造超400个就业岗位并减排150万吨二氧化碳。","scd":null,"kp":["光伏装机容量[Hanaqpampa项目]: 140.8 MW","储能配置[Hanaqpampa项目]: 15 MW","总投资额[Hanaqpampa项目]: 超过1.27亿美元","组件数量[Hanaqpampa项目]: 超过20万个","输电线路[配套建设]: 15.5公里，220 kV"]},{"i":3036,"as":"OMV Petrom公司接收了用于Petrobrazi项目的20兆瓦电解槽的最终模块。另一则简讯指出，SINTEF为PYROCO₂项目订购了0.5兆瓦的AEM电解槽。","scd":null,"kp":["电解槽装机规模[Petrobrazi项目]: 20 MW","电解槽类型[PYROCO₂项目]: AEM 0.5 MW"]},{"i":3037,"as":"PowerCell公司赢得了LH2 Shipping的燃料电池订单。另一则简讯指出，ATOME选择阳光电源作为Villeta电解槽项目的供应商。","scd":null,"kp":[]},{"i":3038,"as":"雄安新区空天产业发展迅速。中国星网总部迁驻发挥龙头效应，吸引上下游企业集聚。鸿擎科技在雄安建立卫星自动化生产线，具备年产100颗平板式卫星的交付能力，“雄安一号”卫星正在调试。芯联新等企业聚焦商业航天激光通信核心零部件，研发出带宽提升8倍的超高速收发一体模块。","scd":null,"kp":["组件自动化安装率[平板式构型卫星]: 70%以上","年产能[平板式构型卫星]: 100颗"]},{"i":3039,"as":"","scd":null,"kp":[]},{"i":3040,"as":"夏季达沃斯论坛聚焦垂直领域AI应用的规模化。AI正在工业制造、医疗、能源等领域加速落地，成为实体经济的底层能力。先进制造、电力系统、医疗健康等拥有高质量数据与复杂系统的行业最具创新潜力。AI大幅缩短了创新药研发周期，并在工业领域大规模重塑工作流程、提升效率。","scd":null,"kp":[]},{"i":3041,"as":"中国基础设施建设正从传统的“铁公基”向“六张网”升级。中央政治局会议明确提出加强水网、新型电网、算力网、新一代通信网、城市地下管网、物流网的规划建设。“六张网”已被纳入国家顶层部署，旨在夯实中国式现代化的战略底座。","scd":null,"kp":[]},{"i":3042,"as":"北京市人社局启动2026年度职称申报工作，机器人、低空技术两大新兴专业首次启动职称评审。网上申报时间为7月7日至30日，高中级需现场答辩。此外，北京扩大国际职业资格对应范围，新增CFA等国际资格分别对应高级和中级职称，以拓宽国际化人才晋升通道。","scd":null,"kp":[]},{"i":3043,"as":"2026全球数字经济大会将于7月2日至5日在北京举行，主题为“建设数字友好城市”。大会将推出50余场专题论坛，聚焦“产业数字化、人工智能+”。会期将集中发布世界模型、人形机器人等新技术新产品，并推出近20项行业规则标准，同时发布《全球数字经济城市发展报告》等成果文件。","scd":null,"kp":[]},{"i":3044,"as":"第四届链博会期间发布了《全球供应链促进报告2026》及全球供应链韧性指数矩阵。报告指出前沿技术是全球供应链发展主要驱动力，新增了人工智能、氢能等6条供应链图谱。2018至2025年各项供应链指数均呈上行态势，2026年新增美国和欧盟供应链韧性指数，为研判供应链态势提供量化工具。","scd":null,"kp":[]},{"i":3045,"as":"第四届中国国际供应链促进博览会在北京举办，展出了最快高铁、AI眼镜、机器人等硬核科技成果。依托中国完整工业体系与超大规模市场，链博会搭建了常态化全球合作平台。本届展会全面升级，澳大利亚担任主宾国，并首次设立法国和意大利主宾省，推动全球产业链协作与创新发展。","scd":null,"kp":["最高运行速度[高铁]: 400公里/小时","重量[AI眼镜]: 40克","自由度[高精液压重载机械臂]: 七自由度"]},{"i":3046,"as":"Equinor（挪威国家石油公司）将结束其在日本的海上风电业务活动。","scd":null,"kp":["项目容量[UK LDES计划]: 7.6 GW","项目容量[罗马尼亚风电项目]: 392 MW","储能容量[澳大利亚CIS调度招标]: 16 GWh"]},{"i":3047,"as":"Gwynt Glas公司已为位于凯尔特海的1.5吉瓦海上风电项目提交了环境影响评估（EIA）范围界定报告。","scd":null,"kp":["装机容量[凯尔特海风电项目]: 1.5吉瓦","装机容量[英国LDES cap和floor方案]: 7.6吉瓦","装机容量[CIP罗马尼亚风电项目]: 392兆瓦","储能容量[澳大利亚CIS可调度BESS招标]: 16吉瓦时"]},{"i":3048,"as":"国网泰州供电公司于6月18日公布了泰州市分布式光伏接入电网可开放容量信息。市发改委组织测算并评估了全市电网承载能力，公布了220千伏至10千伏公用变压器的可开放容量，投资主体可通过营业厅或电话查询具体数据。","scd":null,"kp":["开放容量测算维度[泰州分布式光伏接入电网]: 220、110、35、10(20)千伏公用变压器"]},{"i":3049,"as":"河北省张家口市能源局公示拟申报纳入省级年度方案的光伏项目。大唐建投蔚县新能源有限公司获得沙蔚铁路全线30万千瓦廊道式光伏项目指标。该项目通过市场化方式确定投资主体，公示时间为2026年6月24日至30日。","scd":null,"kp":["申报规模[河北张家口廊道式光伏项目]: 30万千瓦(300MW)"]},{"i":3050,"as":"土耳其贸易部对原产于中国的光伏铝边框作出反倾销肯定性终裁，以到岸价征收反倾销税，措施有效期五年。涉案产品税号为8541.90.00.00.11。此前，土耳其已于2025年12月对该案作出初裁，征收了14.79%至31.40%的临时反倾销税。","scd":null,"kp":["临时反倾销税率[土耳其对华光伏铝边框初裁]: 14.79%～31.40%","计税基准[土耳其对华光伏铝边框终裁]: 到岸价(CIF)","措施有效期[土耳其对华光伏铝边框终裁]: 5年","涉案产品税号[土耳其对华光伏铝边框]: 8541.90.00.00.11"]},{"i":3051,"as":"基于2025年营收规模，榜单公布了《中国新能源企业100强》。宁德时代以超4200亿营收位居榜首，特变电工、阳光电源位列二三位。前十强还包括通威股份、华友钴业、东方电气、金风科技、隆基绿能、天合光能和晶科能源。","scd":null,"kp":["营收规模[宁德时代2025年]: 超4200亿元","[中国新能源企业2025百强前三名]: 宁德时代、特变电工、阳光电源"]},{"i":3052,"as":"陕西省市场监督管理局发布通告，聚焦光伏、锂电池、新能源汽车等“内卷式”竞争高发领域开展调查处置。文件提出“十严禁”，严禁低于成本销售、价格欺诈、平台干预定价、数据造假、商业诋毁及达成垄断协议等违法恶意竞争行为，以规范市场经营秩序。","scd":null,"kp":["[陕西市场监管局内卷式竞争重点监管领域]: 平台经济、光伏、锂电池、新能源汽车、民生消费","[禁止内卷式竞争行为]: 低于成本销售、虚构补贴优惠、价格欺诈等"]},{"i":3053,"as":"湖南省印发《推进服务业扩能提质行动方案（2026—2028年）》，提出到2028年力争建成1-2家零碳园区和一批零碳工厂。方案明确推进重点行业能效诊断、建立双碳综合服务平台及碳排放监测评估。同时，大力发展合同能源管理与绿色产品认证，健全再生资源“换新+回收”物流体系。目标至2028年，全省服务业增加值占GDP比重达57%。依托高校和园区，布局建设30家概念验证中心和100家中试验证基地。","scd":null,"kp":["建设目标[湖南零碳园区]: 力争建成1—2家","建设目标[湖南零碳工厂]: 建成一批","[湖南双碳综合服务平台]: 提供碳排放全景监测、碳效水平评估、碳足迹认证等"]},{"i":3054,"as":"英特尔下一代桌面处理器Nova Lake的爆料显示，其旗舰双芯型号最高提供52核（16P+32E+4LPE），PL2最大睿频功耗可达474W，PL4瞬时峰值最高达854W。为满足极高功耗需求，英特尔修订了Z990主板供电设计指南，建议175W性能级旗舰主板配备三组8-pin CPU供电接口。技嘉已展示符合该供电方案的900系主板样品。三组接口非硬性要求，取决于主板厂商设计。","scd":null,"kp":["PL2功耗[英特尔Nova Lake双芯处理器]: 474W","PL1基础功耗[英特尔Nova Lake双芯处理器]: 150W","PL4瞬时峰值功耗[英特尔Nova Lake双芯处理器]: 854W","核心规格[Nova Lake-S旗舰型号]: 52核心(16P+32E+4LPE)","主板供电接口要求[Z990高端主板双芯型号]: 三组8pin"]},{"i":3055,"as":"苹果公司计划于今年底至明年初推出首款触屏MacBook（代号K114和K116），将搭载现有M5 Pro与M5 Max芯片，并首次引入OLED屏幕和灵动岛界面。产品研发重心将转向注重AI计算的M7系列芯片，直接跳过M6 Pro和Max版本。配备M7系列芯片的后续机型最早于2027年底推出，2028年Mac Studio也将更新至M7芯片。","scd":null,"kp":["[苹果首款触屏MacBook机型代号]: K114和K116","首发芯片[苹果首款触屏MacBook]: M5 Pro / Max芯片","后续芯片规划[苹果跳过型号]: M6 Pro和M6 Max，直接转向M7系列","[苹果M7系列芯片]: 更注重AI计算"]},{"i":3056,"as":"2026款奇瑞捷途山海T1四驱版正式上市，搭载1.5T插电混动系统，限时焕新价14.99万至17.99万元。车辆采用P1+P3+P4三电机构型，综合输出619马力，最大扭矩875牛·米，纯电续航最高220km。车身长宽高为4796/1967/1840mm，轴距2810mm。内饰配备15.6英寸2.5K中控屏及高通骁龙8255芯片，搭载猎鹰500驾驶辅助系统，支持APA自动泊车等功能，并配备XWD全自动智能四驱系统。","scd":null,"kp":["动力系统[2026款捷途山海T1四驱版]: 1.5T插电混动","电机构型[2026款捷途山海T1四驱版]: P1+P3+P3","系统综合输出[2026款捷途山海T1四驱版]: 619马力","中控屏[2026款捷途山海T1四驱版]: 15.6英寸2.5K","车机芯片[2026款捷途山海T1四驱版]: 高通骁龙8255"]},{"i":3057,"as":"广汽与华为乾崑联合打造的启境GT7正式上市，官方指导价20.99万元起。同步上线的“玩家首发版”售价23.99万元起，限时赠送2年或6万公里整车延长保修服务。购买首发版需在6月27日21点前支付10000元定金且无犹豫期。新车提供标准版、Ultra版、Ultra超长续航版以及两款三电机四驱版共五款配置，最高售价32.99万元，首批车型搭载华为ADS 5智驾系统。","scd":null,"kp":["起售价[启境 GT7玩家首发版]: 23.99 万元","整车延长保修服务[启境 GT7玩家首发版]: 赠送2年或6万公里","支付定金[启境 GT7玩家首发版]: 需在6月27日21:00前支付10000元","官方指导价[启境 GT7标准版]: 20.99 万元","官方指导价[启境 GT7 Ultra]: 23.99 万元"]},{"i":3058,"as":"龙芯中科发布16核低成本服务器芯片3C3000，通用计算性能对标3C5000。该芯片基于LA364E架构，主频1.5-1.8GHz，典型功耗40W，支持LoongArch指令集与国密算法。采用FCBGA1371封装，兼容3B6000引脚，配备16MB共享二级缓存和2×72位DDR4-2400内存控制器。接口方面提供最多32通道PCIe 3.0，支持双路互连，主要面向中小企业文件、数据库及网站服务器应用。","scd":null,"kp":["处理器核[龙芯3C3000]: LA364E","封装规格[龙芯3C3000]: FCBGA1371（37.5mm×37.5mm）","物理核心数[龙芯3C3000]: 16个","逻辑核心数[龙芯3C3000]: 16个","主频[龙芯3C3000]: 1.5~1.8GHz"]},{"i":3059,"as":"2026款奇瑞捷途自由者7 PLUS燃油SUV正式上市，限时焕新价11.99-13.49万元。车身长宽高4796/1967/1840mm，轴距2810mm。车辆搭载2.0TD鲲鹏动力与8AT变速箱，最大功率187千瓦，峰值扭矩390牛·米。内饰配备15.6英寸2.5K中控屏及高通骁龙8255芯片。整车搭载猎鹰500智驾系统，配备多个雷达与摄像头，支持NOA高速领航及APA自动泊车。前排座椅具备10向电动调节与8点按摩功能。","scd":null,"kp":["限时焕新价[2026款捷途自由者7 PLUS]: 11.99万-13.49万元","中控屏[2026款捷途自由者7 PLUS]: 15.6英寸2.5K","车机芯片[2026款捷途自由者7 PLUS]: 高通骁龙8255","座椅调节[2026款捷途自由者7 PLUS前排]: 支持10向电动调节","毫米波雷达[2026款捷途自由者7 PLUS]: 3个"]},{"i":3060,"as":"宏碁上架PE270XT 27英寸显示器，售价4999元。该设备采用5120x2880分辨率的量子点IPS面板，支持10点触控，峰值亮度600尼特，响应速度4ms，提供10-Bit色彩，覆盖99% Adobe RGB和DCI-P3色域。接口包含90W USB-C、HDMI 2.1与DP 1.4，支持KVM功能。显示器自带双5W扬声器、8MP会议摄像头及麦克风，支架支持升降、倾斜及俯仰调节，兼容100x100mm壁挂。","scd":null,"kp":["定价[宏碁PE270XT显示器]: 4999元","面板类型[宏碁PE270XT]: 5120x2880分辨率量子点IPS面板","触控支持[宏碁PE270XT]: 10点触控","峰值亮度[宏碁PE270XT]: 600尼特","响应速度[宏碁PE270XT]: GtG 4ms"]},{"i":3061,"as":"","scd":null,"kp":[]},{"i":3062,"as":"美国加州推出AI失业追踪系统（CAIT），用于监测AI对就业市场的影响。系统每月更新，通过交叉分析失业保险数据与各职业受AI影响程度进行预警。首份报告显示，截至5月，加州整体未现AI导致的大规模裁员潮。但自2022年底ChatGPT发布后，高学历且从事易被AI替代职业的劳动者失业申请持续上升，尤其在旧金山湾区的专业服务业和信息产业表现明显。该系统旨在提供预警并提供配套就业支持。","scd":null,"kp":["更新频率[CAIT系统]: 每月一次","核心逻辑[CAIT系统]: 失业保险申领数据与各职业受AI影响程度交叉分析"]},{"i":3063,"as":"苹果因存储芯片短缺宣布Mac产品线全球涨价后，在美国官网上线了MacBook Neo等翻新机型。256GB版MacBook Neo翻新价599美元，比涨价后的全新机便宜100美元，持平涨价前原价。此次上线的翻新产品还包括多款搭载M5芯片的MacBook Air与MacBook Pro，以及第二代Studio Display。苹果指出涨价主要受存储芯片短缺影响，导致MacBook Air等全新机型价格上调100至300美元不等。","scd":null,"kp":["售价[MacBook Neo 256GB翻新版]: 599美元","售价[MacBook Neo 512GB带Touch ID翻新版]: 679美元","起售价[MacBook Neo全新机型涨价后]: 699美元","起售价[MacBook Neo 512GB版全新机型涨价后]: 799美元"]},{"i":3064,"as":"戴尔XPS 13笔记本2026款国行正式上市，售价8999元。该机搭载英特尔酷睿5 320处理器（6核6线程，最高4.6GHz），配备16GB LPDDR5X内存与512GB固态硬盘。机身重约1kg，厚度12.7mm，内置52Wh电池。屏幕采用13.4英寸2.5K触控屏，刷新率30-120Hz，亮度500尼特，覆盖100% DCI-P3色域并支持防眩光。接口配备双USB 3.2 Gen2 Type-C（10Gbps），支持Wi-Fi 7与蓝牙6.0技术。","scd":null,"kp":["处理器[戴尔XPS 13 2026款]: 第三代英特尔酷睿5 320（6核6线程，最高4.6GHz）","内存[戴尔XPS 13 2026款]: 16GB LPDDR5X 7467 MT/s","硬盘[戴尔XPS 13 2026款]: 512GB SSD","屏幕[戴尔XPS 13 2026款]: 13.4英寸2.5K触控屏（30-120Hz，500尼特）","电池容量[戴尔XPS 13 2026款]: 52Wh"]},{"i":3065,"as":"","scd":null,"kp":[]},{"i":3066,"as":"","scd":null,"kp":[]},{"i":3067,"as":"Meta为旗下智能眼镜推出不锈钢充电底座，兼容雷朋联名眼镜等产品，不支持雷朋Display眼镜，定价60美元。该底座重108克，配备USB-C接口，支持快充，官方数据显示充满需1小时，充至50%仅需20分钟。包装内不含充电线和电源适配器。数据显示，Meta雷朋联名智能眼镜2025年销量超700万副。眼镜核心功能集成开放式扬声器、双麦克风及Meta AI助手，可通过语音指令进行拍照录像。","scd":null,"kp":["定价[Meta智能眼镜不锈钢充电底座]: 60美元","充电速度[Meta智能眼镜不锈钢充电底座]: 20分钟充到50%，1小时完全充满","接口[Meta智能眼镜不锈钢充电底座]: USB-C（包装不含充电线和电源适配器）"]},{"i":3068,"as":"法拉利首款纯电车型Luce国内发布，售价398.8万元起。新车搭载四电机，0-100km/h加速2.5秒，极速310km/h，配备122千瓦时电池组，续航超530公里。车身采用四门五座布局，长宽高为5026/1999/1544mm，轴距2961mm。设计由LoveFrom团队操刀，内饰强调物理控制与极简风格。前后灯组采用透明面板，配备23与24英寸不同规格的量产最大尺寸轮毂。","scd":null,"kp":["售价[法拉利Luce]: 398.8万元起","电机配置[法拉利Luce]: 四电机","0-100km/h加速[法拉利Luce]: 2.5秒","0-200km/h加速[法拉利Luce]: 6.8秒","极速[法拉利Luce]: 310km/h"]},{"i":3069,"as":"微软正式宣布取消Edge浏览器的AI历史搜索功能，并向用户致歉。该功能原计划允许用户通过自然语言本地搜索浏览历史，但因用户对隐私安全担忧及其实用性产生质疑，未能被市场接受。微软转而将AI深度整合至浏览器：授权后Copilot可分析多标签页内容，手机端新增按主题自动归类的Journeys功能，并开放Copilot Voice和Copilot Vision读取屏幕与浏览历史以提供精准回答。","scd":null,"kp":["驱动方式[Edge浏览器AI历史记录搜索]: 完全由本地AI模型驱动，数据不上传云端","策略开关[Edge浏览器AI历史记录搜索]: EdgeHistoryAISearchEnabled"]},{"i":3070,"as":"广汽与华为联合打造的启境GX7全球首秀，定位新一代智能“阔”五座SUV，轴距3070mm，具备60%黄金轴长比。新车延续封闭式前脸与半隐藏门把手设计，配备激光雷达。核心亮点为行业首创的20秒一键自动成床功能，通过坐垫后抬升及一体式腿托协同，无需手动拆装即可变为完整平面。随动侧翼设计支持成床时自动分离。智驾方面，预计搭载华为乾崑全栈解决方案及896线双激光雷达。","scd":null,"kp":["定位[启境GX7车型]: 新一代智能“阔”五座SUV","自动成床功能[车内空间]: 20秒一键自动成床","轴距[启境GX7车型]: 3070mm","轴长比[启境GX7车型]: 60%"]},{"i":3071,"as":"华硕上架ROG NUC 20周年限量版迷你主机，售价43999元。机身约3L体积，采用黑透金专属配色与可拆卸支架。核心搭载英特尔酷睿Ultra 9 290HX Plus处理器（24核24线程）与RTX 5090移动版显卡，配备DDR5 6400MHz内存及PCIe 5.0硬盘。接口极其丰富，前置包含20Gbps USB-C接口，后置提供双HDMI 2.1、双DP 2.1、雷电4、2.5G网口及四个10Gbps USB-A接口。","scd":null,"kp":["处理器[ROG NUC 20周年版迷你主机]: 英特尔酷睿Ultra 9 290HX Plus (24核心24线程)","内存规格[ROG NUC 20周年版迷你主机]: DDR5 6400MHz","硬盘规格[ROG NUC 20周年版迷你主机]: PCIe 5.0","主机体积[ROG NUC 20周年版迷你主机]: 约3L","价格[ROG NUC 20周年版迷你主机]: 43999元"]},{"i":3072,"as":"电池技术的创新正在推动可穿戴设备向更小、更灵活的方向发展。可穿戴设备对尺寸、厚度和柔韧性有着极其严格的要求，促使电池设计必须摆脱传统形态限制。新型先进电池设计在满足严苛体积形状要求的同时，平衡了安全性、电池容量与整体性能，为打造更加紧凑且适应性强的智能穿戴设备提供了核心电源解决方案。","scd":null,"kp":[]},{"i":3073,"as":"Sunrun、Tesla和Renew Home三家公司展开合作，通过整合太阳能电池板、电池储能和恒温器来满足超大规模数据中心的电力需求，并支持PJM电网的可靠性。这些企业在全美最大的数据中心市场提供了高达16.8吉瓦（GW）的灵活电网容量，以应对数据中心快速扩张引发的电力需求激增，确保电网的稳定运行。","scd":null,"kp":["灵活容量[数据中心超大规模电力需求支持]: 16.8 GW"]},{"i":3074,"as":"","scd":null,"kp":[]},{"i":3075,"as":"本周顶级供应链新闻聚焦两大事件：一是在法国埃维昂峰会上，G7领导人同意减少对稀土和永久磁铁的依赖，目标是到2030年将非G7供应商的采购比例降至60%以下，长期目标为50%，并将在2026年底前为其他关键矿物设定类似目标；二是安联公司披露，目前价值1250亿美元的货物正等待通过霍尔木兹海峡，凸显了供应链韧性和多元化的重要性。","scd":null,"kp":["依赖减少计划[G7领导人协议]: 稀土和永磁材料定向减少依赖","待通行货物价值[霍尔木兹海峡]: 1250亿美元"]},{"i":3076,"as":"梅赛德斯-奔驰公布了其80辆纯电动重型卡车的真实运营数据，以消除关于电动重卡在续航、充电基础设施和经济性方面的误解。数据覆盖了数百万英里的行驶里程。例如，在乌尔姆物流公司的实际应用中，一辆总重36吨的eActros 600电动卡车在冬季往返于沃尔特和比勒菲尔德。数据结论证明，目前电动长途运输在技术和经济上已经完全可行。","scd":null,"kp":["运输能力[梅赛德斯重型电动卡车真实运营]: 36吨"]},{"i":3077,"as":"一项针对英国热泵安装的大规模研究揭示了理论性能与实际运行数据之间的巨大差距。牛津大学专家指出，安装调试的质量直接影响热泵的效率，正确的调试可以在整个系统生命周期内节省大量成本。在英国，热泵必须由MCS认证的安装人员进行安装才能获得政府的补助支持。优化安装流程有助于实现更高的季节性性能系数（SPF）。","scd":null,"kp":["性能评估[英国大规模热泵安装研究]: 理论性能与真实运行数据之间存在重大差异","性能优化[热泵系统]: 调试更改可帮助实现更高的季节性能系数(SPF)"]},{"i":3078,"as":"","scd":null,"kp":[]},{"i":3079,"as":"","scd":null,"kp":[]},{"i":3080,"as":"美国宇航局（NASA）的“露西号”探测器在近距离飞越小行星“唐纳德约翰森”时获得了重要发现。这颗形状奇特、形似花生的半人马型小行星在太空中呈现异常的摆动，表面留有远古碰撞的疤痕，并且保留了其母体曾短暂存在液态水的证据。该小行星形成于约1.55亿年前的一次剧烈撞击碎片重新聚集，阳光照射通过YORP效应缓慢改变了它的自转状态。","scd":null,"kp":["天体探测发现[NASA露西号探测器飞越小行星Donaldjohanson]: 发现液态水曾短暂存在的证据","天体特征[小行星Donaldjohanson]: 花生形状且在太空中奇怪摆动"]},{"i":3081,"as":"针对已知的第三个穿越太阳系的星际天体3I/ATLAS，科学家利用北加州哈特克里克射电天文台的艾伦望远镜阵列（ATA）对其进行了广泛射电频段的扫描，以搜寻外星技术的迹象。此前观测表明，3I/ATLAS的表现与天然彗星一致。此次SETI（搜寻地外文明计划）调查最终未发现任何地外技术的信号，确认该神秘星际访客是一个自然的宇宙旅行者。","scd":null,"kp":["探测行动[星际物体3I/ATLAS]: 扫描广泛射电频段寻找人工信号","探测结论[星际物体3I/ATLAS]: 确定为自然宇宙旅行者而非外星科技"]},{"i":3082,"as":"一篇政策研究论文提出，应将NASA计划建设的月球基地转化为隔离站，作为保护地球免受潜在危险外星生物污染的防火墙。该月球基地应配备生物安全隔离设施，用于在带回的太空样本抵达地球之前对其进行严格筛查。研究人员指出，人类目前的行星保护策略未能跟上太空探索新时代所带来的地外样本返回风险。","scd":null,"kp":["防护策略[NASA规划月球基地]: 建立生物隔离设施作为地球抵御外星微生物的第一道屏障"]},{"i":3083,"as":"欧洲首台且唯一一台应用于同步辐射光源的TES（超导过渡边缘传感器）光谱仪已在BESSY II正式投入运行。该设备由HZB、MPI-CEC和NIST联合开发，其X射线光子的探测效率比传统波长色散X射线发射光谱仪高出100至1000倍。凭借其极高的灵敏度，研究人员能够利用该仪器对原子级薄层材料、纳米结构以及极稀薄的原子和分子样本的电子特性进行前所未有的实验探索。","scd":null,"kp":["灵敏度[欧洲首台TES光谱仪]: 提升1000倍","探测效率[欧洲首台TES光谱仪]: X射线光子探测效率达100"]},{"i":3084,"as":"一项发表在《细胞报告物理科学》上的研究表明，一款已在中国应用于汽车和大型储能系统的商业化钠离子电池，在制造质量和多项关键性能指标上已经能够与特斯拉的锂离子电池相媲美。尽管该电池在寒冷天气充电和能量密度方面仍需进一步改进，但其技术的快速进步表明，钠离子电池有望成为电动汽车和电网级储能更经济实惠的替代方案。","scd":null,"kp":["[中国商用钠离子电池]: 制造质量与关键性能指标可媲美特斯拉电池","改进方向[钠离子电池]: 提升寒冷天气充电能力与能量密度"]},{"i":3085,"as":"Coinbase首席执行官布莱恩·阿姆斯特朗表示，尽管人工智能（AI）的使用量在不断上升，但公司仍成功将其在人工智能领域的支出削减了一半。","scd":null,"kp":["AI支出削减幅度[Coinbase使用量增加时]: 50%"]},{"i":3086,"as":"白宫宣布取消了对人工智能企业Anthropic旗下名为“Mythos”的项目的部分出口管制限制。","scd":null,"kp":["[Anthropic Mythos]: 白宫取消部分出口管制"]},{"i":3087,"as":"OpenAI宣布聘请了一名曾负责苹果Vision Pro和智能眼镜业务的高管加入其团队，以加强其在硬件领域的布局。","scd":null,"kp":[]},{"i":3088,"as":"亚马逊云服务（AWS）宣布将其平台上部分英伟达（Nvidia）计算资源的价格上调了20%。","scd":null,"kp":["价格涨幅[AWS部分Nvidia计算服务]: 20%"]},{"i":3089,"as":"OpenAI宣布已将其最新的GPT-5.6模型发布给经过美国政府批准的客户使用。","scd":null,"kp":["[OpenAI GPT-5.6]: 发布给美国政府批准的客户"]},{"i":3090,"as":"电池制造商宁德时代（CATL）与电池、科技和汽车行业的领先企业合作，在伦敦成立了“全球能源循环经济联盟”。创始成员包括宝马、雷诺、沃尔沃、谷歌和小米等。该联盟旨在制定更易于重用和回收的电池设计通用标准，由艾伦麦克阿瑟基金会负责协调，宁德时代在其中发挥核心作用。宁德泰主要与汽车制造商合作推动电池供应链的闭环回收。","scd":null,"kp":["[全球能源循环经济联盟]: 由CATL、宝马、雷诺、沃尔沃、谷歌和小米等联合创立以开发易于重复使用和回收的电池设计标准"]},{"i":3091,"as":"通用汽车（GM）宣布与Peak Energy合作，在密歇根州的电池工厂开发用于电网级储能的国产钠离子电池系统，目标是在2028年实现商业化生产。此举引发了行业内关于美国电池供应链战略的争论：即如何构建有竞争力的本土电池供应链并减少对外依赖。与此同时，福特等其他车企则选择押注于中国市场的电池技术，这凸显了美国电池行业在技术路线和供应链安全上的不同发展路径。","scd":null,"kp":["[通用汽车与Peak Energy]: 合作开发用于电网级储能的国产钠离子电池系统"]},{"i":3092,"as":"欧盟委员会对欧洲议会和理事会达成的一项临时协议表示欢迎，该协议旨在对工作场所的钴及其他有害化学物质实施更严格的暴露限制。这是对欧盟《致癌物、致突变物和生殖毒性物质指令》（CMRD）的第六次修订，对钴和无机钴化合物引入了更严格的职业暴露限值，并针对多环芳烃等物质制定了新措施。这一具有里程碑意义的协议标志着欧洲电池制造业在安全生产方面迈出了重要一步。","scd":null,"kp":["[欧盟电池制造安全]: 就更严格的工作场所钴及其他危险化学品暴露限制达成临时协议"]},{"i":3093,"as":"英国民航局（CAA）发起了一项名为“Pack Right. Safe Flight.”的安全运动，警告航空公司乘客托运行李中存在超过1亿块包装不当的锂电池，这带来了致命的火灾风险。监管机构指出，包装不当的可充电锂电池在飞机货舱内可能引发热失控并产生无法控制的火灾。CAA强烈建议乘客将充电宝、手机、笔记本电脑和电子烟等设备放入随身行李中携带。","scd":null,"kp":["[托运行李中的可充电锂电池]: 包装不当会引发热失控，造成致命火灾风险"]},{"i":3094,"as":"电池制造设备供应商Zesar Battery Technologies与阿尔及利亚客户Sarl Bergan Energy签署了一份新的供应合同，进一步巩固其在北非能源市场的业务。Zesar是一家成立于1976年的土耳其公司，也是欧洲成熟的电池制造设备和交钥匙生产技术供应商。合同的具体财务价值和范围细节未予披露。过去二十年中，Zesar开发了包括Evoline装配线和机器人传输系统在内的专有生产系统。","scd":null,"kp":[]},{"i":3095,"as":"电池储能系统（BESS）的快速增长正在重塑全球锂需求格局。在Fastmarkets于拉斯维加斯举办的全球锂和关键材料大会上，行业高管指出，受电网基础设施投资、可再生能源项目和人工智能不断增长的电力需求推动，固定式储能正成为锂市场最重要的需求驱动力之一。Fastmarkets首席执行官透露，BESS领域的锂需求正以每年约40%的速度增长。","scd":null,"kp":["[全球锂需求格局]: 电池储能系统(BESS)的快速增长正成为重塑锂需求并提供新增长源的关键驱动力"]},{"i":3096,"as":"EBC金融集团分析师的报告警告称，尽管过去一年锂价格大幅回升，但继2023年至2025年锂价格暴跌引发长期投资放缓后，锂电池行业最早可能在2028年面临供应短缺。伍德麦肯兹的预测也显示，最早在2028年就会出现供应赤字。这种供应紧缺引发了业界对电池成本、电动汽车普及率和全球能源转型速度的深切担忧。","scd":null,"kp":["[锂资源供应]: 预计到本世纪末可能出现供应紧缩危机"]},{"i":3097,"as":"欧洲电池储能市场预计将在本十年的剩余时间内快速扩张，德国在大型公用事业规模储能部署上处于领先地位。德国太阳能工业协会（BSW-Solar）的数据显示，2026年1月至5月期间，德国共安装了约22.5万个总容量达3.4GWh的电池储能系统，同比增长70%。其中，公用事业规模项目贡献了1.47GWh的新增容量，是去年同期的四倍多，规模首次超越了住宅电池安装量。","scd":null,"kp":[]},{"i":3098,"as":"韩国Energy Tech Solution公司在美国太平洋西北国家实验室（PNNL）的电网存储启动平台（GSL）安装了一条方形电池装配线。这条包含16个工位的生产线旨在促进先进电池制造，并帮助美国创新者加速技术商业化。经过现场培训，PNNL成为美国能源部旗下目前唯一具备制造方形结构电池能力的实验室。GSL是由美国能源部电力办公室资助的7500万美元研究设施。","scd":null,"kp":[]},{"i":3099,"as":"爱尔兰公司Net Zero Energy（NZE）公布了一项价值20亿欧元（约23亿美元）的长时储能设施计划。该项目名为Rathrush绿色能源公园，装机容量达600MW，旨在利用因需求不足或电网容量受限而损失的场外过剩风能和太阳能发电。这些过剩的电能将不会被直接存储在传统电池中，而是转化为绿氢，随后被压缩并泵入专门深层的地下衬砌洞穴中用于发电。","scd":null,"kp":["项目投资额[爱尔兰可再生能源制氢长时储能项目]: 20亿欧元(约23亿美元)","[技术路线]: 利用过剩可再生能源电解水制备绿氢并用于长时储能供电"]},{"i":3100,"as":"Ensurge Micropower公司正式任命拥有超过25年行业经验的Salil Soman为其新任首席商务官，以加速其固态锂微型电池技术的商业化进程。Soman已于6月23日履新，此前他曾在Feon Energy担任业务发展副总裁。在其职业生涯中，Soman在锂离子、固态、钠离子和镍锌等多种电池技术领域担任过高级商业和工程职务，致力于将下一代电池技术推向市场。","scd":null,"kp":["[固态锂微型电池]: 加速商业化进程"]},{"i":3101,"as":"捷豹路虎（JLR）通过与40多家供应链合作伙伴合作，推出了一款概念车，该车采用了49种更具可持续性的汽车零部件。该项目已累计减少了一吨以上的二氧化碳当量排放，相当于一名乘客从巴黎飞往纽约的碳排放量。捷豹路虎表示，该项目还实现了多项行业首创，展示了公司在推进汽车行业循环经济和多方可协调应用方面的领导力。","scd":null,"kp":["[概念车可持续汽车零部件数量]: 49个","[碳减排量]: 超过1吨二氧化碳当量"]},{"i":3102,"as":"","scd":null,"kp":[]},{"i":3103,"as":"","scd":null,"kp":[]},{"i":3104,"as":"","scd":null,"kp":[]},{"i":3105,"as":"丰田官方宣布其5月份全球销量（含雷克萨斯品牌）同比下降7.2%，至834,279辆。这已经是丰田连续第四个月全球销量低于去年同期，其中中国市场的销量暴跌了30%，严重拖累了整体业绩，主要原因是高油价和激烈的市场竞争。在北美市场，丰田售出280,539辆汽车，同比微降0.1%；其中美国市场销量下降0.6%至238,800辆，尽管全新RAV4上市且混动车与纯电车需求有所上升。","scd":null,"kp":["销量跌幅[中国市场]: 同比下跌30%","全球销量[含雷克萨斯]: 834,279辆","销量跌幅[全球市场]: 同比下跌7.2%"]},{"i":3106,"as":"国际清洁交通委员会（ICCT）的一项最新研究表明，如果全球采取更积极的电气化路径，到2050年有望挽救880万人的生命。研究发现，全球每45秒就有一人因车辆尾气污染而死亡。这些污染物主要包括颗粒物、臭氧和二氧化氮。在2024年，这些源自车辆尾气的污染物已造成70万人过早死亡，并导致25万例新增儿童哮喘病例。研究强烈强调了加速普及电动汽车的必要性。","scd":null,"kp":["挽救生命数[加速电动化路径至2050]: 880万","[车辆污染致死率]: 全球每45秒有1人死亡"]},{"i":3107,"as":"Gobao公司发布了多款新的电动自行车驱动系统，包括极具吸引力的eCVT无级变速电机，但最引人注目的是其推出的快速充电电池系列。该系列电池容量包括500Wh、750Wh和900Wh，彻底改变了电动自行车需要数小时才能充满电的现状。配合其新推出的30A超级充电器，500Wh电池在极短时间内即可从0%充至80%，实现了几年前看来几乎不可能的充电速度。","scd":null,"kp":["[电动自行车驱动系统]: 推出搭载连续可变传动(eCVT)的电机","[电动自行车锂电池]: 攻克快速充电技术以打破数小时慢充的行业现状"]},{"i":3108,"as":"特斯拉已开始向搭载Hardware 3（HW3）硬件的车辆推送FSD v14“Lite”（固件版本2026.20.5.1），早期内测车主将率先收到更新。自2025年初以来，约400万辆HW3汽车一直停留在FSD v12.6版本，这是该车型获得的首个重大全自动驾驶更新。特斯拉人工智能主管确认，该版本提炼了AI4硬件v14系列的驾驶行为逻辑，以适配AI3的摄像头和计算配置，但其仍属于需要驾驶员监督的L2级辅助驾驶系统。","scd":null,"kp":["[特斯拉FSD v14 \"Lite\" HW3版本]: 监督式L2自动驾驶系统","影响车辆规模[HW3硬件]: 约400万辆","固件版本[本次推送]: 2026.20.5.1"]},{"i":3109,"as":"治安记录显示，自去年12月以来，特斯拉内华达超级工厂装载着价值数百万美元汽车及家用电池的拖车至少遭遇了11次直接从装载码头被盗的事件。其中仅在1月份就发生了9起。当地调查侦探称这种情况为“流行病”。通过公共记录请求获得并由《连线》杂志最先报道的档案显示，盗窃目标主要是尚未交付的满载成品电池的半挂车。首起案件中，两辆拖车装载了价值超47.5万美元的Powerwall电池。","scd":null,"kp":[]},{"i":3110,"as":"在回应绿党提出的有关关键基础设施安全风险的议会质询后，德国政府正考虑对能源基础设施中的中国逆变器采取网络安全措施和监管限制。目前，政府正在审查包括欧盟层面的联合措施以及扩大投资审查在内的多项方案。这是德国在关键基础设施领域更广泛的“去风险化”努力的一部分，相关跨部门审查评估程序已经在推进中。","scd":null,"kp":["[德国能源基础设施对中国逆变器]: 考虑采取网络安全监管限制措施"]},{"i":3111,"as":"巴西国家电力系统运营商（ONS）数据显示，在巴西对阵巴拉圭的世界杯比赛中，全国互联系统（SIN）的电力需求在下午4:50至5:20期间下降了10.9%（约9.4GW）。当地光伏协会ABSolar指出，核心挑战在于电力系统需提升灵活性，以适应日益增长的可再生能源结构，而非仅仅应对重大赛事期间的信息缺失。ONS预计在16强赛期间电力需求降幅将高达20%，并正在加强电网调度以维持稳定性。","scd":null,"kp":["能源需求削减预测[巴西世界杯期间]: 高达20%","电力需求下降[巴西国家互联系统]: 10.9%"]},{"i":3112,"as":"西班牙能源公司Iberdrola位于意大利西西里岛卡塔尼亚和恩纳省的Fenix光伏电站正式投运。该电站装机容量为243MW，年均发电量约400GWh，取代了此前位于拉齐奥大区维泰博的170MW项目，成为目前意大利投运的最大太阳能发电厂。Fenix电站主要通过与客户签订购电协议（PPA）的方式，直接向意大利能源市场供应所生产的电力。","scd":null,"kp":["装机容量[意大利最大太阳能发电厂Fenix]: 243 MW","装机容量[此前意大利最大运营光伏电站]: 170 MW"]},{"i":3113,"as":"Sunoyster Systems在德国慕尼黑展出了专为低承载屋顶设计的PVbondi轻质玻璃-玻璃太阳能组件。该组件包含96块单晶硅电池，功率输出为450瓦，转换效率达22.2%。该系统改善了组件的背部通风，减轻了屋顶负荷，并加快了安装速度，同时为平屋顶光伏应用提供了高粘合强度。","scd":null,"kp":["输出功率[Sunoyster轻质玻璃-玻璃太阳能组件]: 450 W"]},{"i":3114,"as":"欧盟启动第六轮跨境可再生能源项目（CB RES）征集，申请截止日期为10月6日。该项目自2021年发起，旨在支持欧盟成员国之间或欧盟与非欧盟国家之间的可再生能源合作项目。获得优先地位认证的项目将有资格申请“连接欧洲设施”计划下的研究和建设资助。","scd":null,"kp":[]},{"i":3115,"as":"京瓷子公司（KCCS）已在日本福冈县和滋贺县的六个工厂设施内，开始测试由积水化学开发的钙钛矿太阳能组件。此次实地测试旨在评估这种新兴太阳能技术在现实世界条件下的实际性能和运行表现。","scd":null,"kp":["[钙钛矿太阳能电池组件]: 京瓷正在日本工厂真实环境下进行测试评估"]},{"i":3116,"as":"丹麦理工大学的研究人员开发出一种利用日光电致发光（EL）成像检测光伏组件低能量前玻璃裂纹的新方法。该方法采用运动增强型短波红外（SWIR）无人机成像技术，能够同时识别电池缺陷和玻璃裂纹。这种低能量裂纹最初仅产生局部损伤，该技术有效提升了大型光伏电站的检测效率。","scd":null,"kp":["检测方法[光伏组件低能玻璃断裂]: 日间电致发光成像法","检测技术[光伏组件缺陷与玻璃裂纹]: 运动增强型SWIR无人机成像技术"]},{"i":3117,"as":"EcoFlow在慕尼黑Intersolar展会上推出了面向欧洲住宅能源市场的OASIS 3.0家庭能源管理系统（HEMS）。该系统通过EcoFlow算法实现实时优化，协调电池、热泵、电动汽车及其他智能家电之间的跨设备协同工作，旨在实现太阳能的最大化自发自用价值。","scd":null,"kp":["[EcoFlow OASIS 3.0家庭能源管理系统]: 针对欧洲市场实现太阳能实时优化最大化自用"]},{"i":3118,"as":"墨西哥总统克劳迪娅·辛鲍姆发布了国家可再生能源增长计划，目标是到2030年新增3200万千瓦（32 GW）的电力装机容量，其中70%来自可再生能源。该计划预计投资420亿美元，旨在增加电力结构中的清洁能源份额，减少化石燃料消耗，并降低对天然气进口的依赖。","scd":null,"kp":["新增电力总产能[墨西哥2030年目标]: 32 GW","可再生能源占比[墨西哥2030年目标]: 70%","新增可再生能源产能[墨西哥2030年目标]: 22 GW","预计总投资[墨西哥电力扩张计划]: 420亿美元"]},{"i":3119,"as":"松下推出专为住宅设计的高效二氧化碳（R744）空气-水热泵系列，采用天然二氧化碳制冷剂，在低温环境下仍能高效制取热水。系统提供4.0千瓦或6.0千瓦的室外机以及250至400升的水箱选项，性能系数（COP）最高可达6.1。该设备运行噪音约37分贝，支持光伏系统集成，并提供10年质保。","scd":null,"kp":["性能系数[COP性能/二氧化碳空气-水热泵]: 6.1","噪音[运行状态]: 约 37 dB(A)","室外机容量[配置选项]: 4.0 kW 或 6.0 kW","水箱容量[配置选项]: 250–400 L"]},{"i":3120,"as":"","scd":null,"kp":[]},{"i":3121,"as":"AI基础设施公司KAYTUS在德国汉堡ISC 2026超级计算会议上推出了一套吉瓦级集装箱式液冷数据中心解决方案。这是一种完全工厂预制的模块化方案，将基础设施标准化为IT立方、电力立方和冷却立方三个集装箱单元。该架构确保了高密度GPU集群的建设质量，简化了项目执行并加快了部署时间。","scd":null,"kp":["扩展规模[预制模块化液冷数据中心]: GW级","模块架构[预制模块化数据中心]: 标准化为IT Cube、Power Cube和Cooling Cube三个集装箱单元"]},{"i":3122,"as":"中国机器人企业AGIBOT在全球直播中展示了G2人形机器人在龙旗科技电子制造厂自主执行质量检测和物料搬运的能力。在为期六天的演示中，机器人累计运行超64小时，完成了包括平板电脑检测、缺陷分拣和材料运输在内的64828个生产任务，期间未发生硬件故障。AGIBOT同时宣布已开始下线其第15000台机器人。","scd":null,"kp":["自主执行任务[人形机器人G2制造演示]: 平板检测、缺陷分类和物料搬运","生产规模[智元机器人]: 已下线第15,000台机器人"]},{"i":3123,"as":"","scd":null,"kp":[]},{"i":3124,"as":"由中海油（CNOOC）开发的全球首台16兆瓦张力腿平台（TLP）浮式海上风力发电机已从珠海起航。该巨型风机将被拖至南海陆丰油田集群，通过重型海底电缆将电力直接输送至海上钻井平台，专门为海上石油和天然气开采提供绿色电力。","scd":null,"kp":["单机容量[TLP浮动海上风力发电机]: 16兆瓦","结构形态[全球首台]: 张力腿平台(TLP)浮动式"]},{"i":3125,"as":"全球最大的粒子加速器大型强子对撞机（LHC）于今日按计划关闭，准备进行为期四年多、耗资12亿瑞士法郎的重大升级，以探索暗物质等宇宙奥秘。该设备位于瑞士与法国边境地下100米深处，周长达27公里。欧洲核子研究中心（CERN）曾利用该设备于2012年成功发现了希格斯玻色子。","scd":null,"kp":["升级周期[大型强子对撞机改造]: 超过4年","升级成本[高光度大型强子对撞机]: 12亿瑞士法郎（约15亿美元）","周长[质子对撞隧道]: 27公里"]},{"i":3126,"as":"加拿大核聚变公司General Fusion与意大利可再生能源开发商Renexia签署框架协议，计划在意大利部署商业化核聚变发电站。双方合作涵盖选址、项目开发、融资、许可、建设和最终调试，将采用General Fusion的磁化靶聚变（MTF）技术。可行性研究工作即将启动，更多第一阶段活动计划于2026年后期开展。","scd":null,"kp":[]},{"i":3127,"as":"多国大学研究人员通过量子模拟发现了电子相互碰撞引起的电阻率上限。研究团队利用冷却至接近绝对零度的超冷钾原子代替电子进行实验，证实了在纯材料中电子间的碰撞对电阻率的增加存在一个基本物理极限，解答了电子碰撞究竟会在多大程度上增加电阻的问题。","scd":null,"kp":["电阻率极限[电子碰撞引起的电阻]: 存在基本上限"]},{"i":3128,"as":"西蒙斯基金会Flatiron研究所与波士顿大学的物理学家成功使用一台普通笔记本电脑模拟了一个曾被认为必须依赖量子计算机才能解决的复杂量子系统。通过应用先进的数学技术和精密软件，研究人员证明了巧妙的算法可以大幅扩展传统计算机的能力，为研究量子动力学和解决复杂优化问题提供了新的有力手段。","scd":null,"kp":["量子系统模拟[使用先进数学和软件的常规电脑]: 成功模拟无需量子计算机"]},{"i":3129,"as":"科学家证实，可以在不损坏历史羊皮纸手稿的情况下收集其细胞物质进行遗传分析。由于羊皮纸由动物皮制成，这种方法允许研究人员从高达1300年历史的文档中提取DNA信息，从而揭示有关古代贸易路线、农业实践以及制造这些手稿所用动物的新细节。","scd":null,"kp":["无损分析年代[羊皮纸手稿DNA检测]: 最高可达1300年"]},{"i":3130,"as":"乔治城大学的一项新研究表明，广泛的大脑练习可以重新连接大脑神经网络，使掌握的技能转移到不同的神经回路中以更少的意识努力自动运行。研究挑战了人类无法实现真正多任务处理的长期观点，指出在适当条件下，大脑能够真正执行多任务，而不仅仅是快速切换注意力。","scd":null,"kp":["多任务处理能力[大脑经过广泛练习后]: 可通过神经重连实现真正的多任务处理"]},{"i":3131,"as":"爱尔兰皇家外科医学院（RCSI）的研究人员在临床前模型中测试了一种使用肽载体递送的实验性mRNA疫苗。结果显示，该疫苗能训练免疫系统识别并攻击儿童最致命的癌症——神经母细胞瘤。疫苗使肿瘤生长延迟了10至11天，并成功将肿瘤体积缩小了70%。这是首个针对该癌症的mRNA疫苗临床前证据。","scd":null,"kp":[]},{"i":3132,"as":"阿拉巴马大学亨茨维尔分校（UAH）的研究人员发现，连续低强度超声波可以通过影响免疫细胞的行为来阻止创伤后骨关节炎的发生。在关节损伤后，持续的超声刺激能够促使免疫系统退出持续攻击模式，减轻慢性炎症，促进组织修复，从而防止软骨磨损，避免关节炎的形成。","scd":null,"kp":[]},{"i":3133,"as":"最新卫星分析显示，印度在2014至2024年间增加了约210万公顷（520万英亩）的热带干旱林地。尽管植树和恢复努力大幅扩大了树木覆盖面积，但部分本土干旱森林仍在消失。这表明国家树木覆盖率的统计数据掩盖了复杂的生态变化，林地覆盖的增加并不总是意味着本土森林正在恢复。","scd":null,"kp":["林地增加面积[印度热带旱地林地(2014-2024年)]: 约210万公顷(520万英亩)"]},{"i":3134,"as":"意大利埃特纳火山的过往喷发历史表明，同一座火山能够通过截然不同的地下途径和驱动过程发生喷发。研究人员通过分析两次历史性喷发，揭示了单一火山内部复杂的岩浆系统运作差异。了解这些差异过程及其探测方法，有助于地质学家更好地评估未来的火山喷发风险。","scd":null,"kp":["火山喷发机制[同一火山(埃特纳火山历史喷发)]: 由截然不同的地下过程和通道网络驱动"]},{"i":3135,"as":"","scd":null,"kp":[]},{"i":3136,"as":"韩国宣布将在未来10年内向半导体芯片、机器人以及人工智能（AI）三大核心技术领域投资8800亿美元。此项巨额投资旨在推动国家核心科技产业的发展。","scd":null,"kp":["投资规模[韩国芯片/机器人/AI(10年期)]: 8800亿美元"]},{"i":3137,"as":"人工智能企业Anthropic展现出的技术实力和市场影响力对AI大模型研发方DeepSeek造成了竞争压力，促使DeepSeek启动了高达74亿美元的融资活动以应对挑战。","scd":null,"kp":["融资金额[DeepSeek(受Anthropic竞争驱动)]: 74亿美元"]},{"i":3138,"as":"中国科技巨头腾讯已从国内存储芯片制造商长鑫存储（CXMT）获得了价值30亿美元的存储芯片供应。此举表明腾讯正在积极加强其硬件供应链的本土化布局。","scd":null,"kp":["交易规模[腾讯从长鑫存储(CXMT)采购]: 价值30亿美元的存储芯片"]},{"i":3139,"as":"企业对AI的投资正在激增，Gartner将2026年定义为组织将AI项目与战略业务目标对齐的“拐点之年”。为应对不断增长的IT基础设施成本压力，技术团队在过去的18个月中大量应用智能体AI（Agentic AI）来构建和改进基础设施及应用。利用AI智能体驱动可衡量的财务成果已成为技术领导者关注的焦点。","scd":null,"kp":["增长预测[企业IT基础设施成本(至2030年)]: 增长2至3倍","战略节点[企业AI项目ROI与战略对齐]: 2026年为拐点年"]},{"i":3140,"as":"远景能源与英国开发商Elements Green签署了一项储能系统供应协议，将为德国下萨克森州的Stadorf电池储能项目供应1600兆瓦时的蓄电池系统。该项目是德国目前在建的最大电池储能项目之一，标志着远景能源基于其Gen-8储能系统平台的综合“未来能源系统”在德国市场的战略落地。","scd":null,"kp":["供应规模[远景能源为德国Stadorf项目]: 1600兆瓦时(MWh)蓄电池储能系统"]},{"i":3141,"as":"意大利开发商ContourGlobal收购了位于英国苏格兰的Wallace电池储能项目，该项目规模达500兆瓦/2吉瓦时（GWh），成为该公司储能组合中容量最大的项目。ContourGlobal首席执行官宣布，在完成此项收购后，公司将在英国建立额外的800兆瓦储能项目管道，将英国作为其核心市场之一。","scd":null,"kp":["储能项目规模[英国Wallace BESS项目]: 500 MW / 2 GWh","开发总规模[ContourGlobal英国后续储备管线]: 800 MW"]},{"i":3142,"as":"大连交通大学科研团队融合电磁探测、声呐感知及水下机器人控制技术，成功研发出拥有完全自主知识产权的海缆智能探测与后埋设系统。该水下机器人能在极低能见度和复杂海底环境下，精准探测并将裸露的海底电缆重新埋入泥沙中。该技术打破了国外垄断，填补了国内复杂海况协同作业的空白，已成功应用于海南文昌国际光缆及广东海上风电等多个国家重点工程。","scd":null,"kp":["核心技术[海底电缆检修与后埋设]: 融合电磁探测、声呐感知及水下机器人控制技术","关键设备[海缆智能探测系统]: 拥有自主知识产权，填补复杂海况协同作业空白并打破国外垄断"]},{"i":3143,"as":"中国科学院等多家机构联合发布了“异算方舟”国产计算系统软件生态全栈平台。该平台针对国产异构算力环境，打造了三项核心能力：包含16款高性能求解器的“九衍枢算法库”、助力代码快速跨生态迁移的“无界BoundX大模型”、以及聚焦流体仿真的“Agent-HiReFlow自动化仿真智能体”。该平台打破了算法、代码与应用之间的壁垒，为国产GPU提供了一体化的软件适配与落地解决方案。","scd":null,"kp":["核心算法库[“异算方舟”九衍枢算法库]: 汇聚16款高性能求解器","系统特性[国产异构算力计算环境]: 提供科学软件适配、代码迁移和智能应用的全栈生态平台"]},{"i":3144,"as":"中国神舟二十三号航天员乘组在太空轨道上驻留已满一个月。在此期间，乘组在稳步推进各项空间科学实验和试验的同时，还完成了多项太空工作与生活的新体验。","scd":null,"kp":[]},{"i":3145,"as":"人工智能（AI）正深刻冲击高度依赖调查数据的社会科学领域。自ChatGPT发布以来，多门社科类学术期刊的投稿量激增，其中大量摘要和文本由AI生成或润色。AI带来了极高的学术产出效率，但也引发了AI污染调查数据、制造虚假学术繁荣以及扭曲人类行为认知的隐忧。社会科学正面临被AI侵蚀还是被重塑的十字路口。","scd":null,"kp":["论文投稿量增幅[自ChatGPT首次公开发布以来]: 猛增42%","AI生成摘要占比[截至当年2月投稿摘要]: 近1/3"]},{"i":3146,"as":"工信部等部门计划到2026年底推动人形机器人开启“作业模式”，实现万台级规模落地。智元“精灵G2”人形机器人在某工厂完成了连续6天的并线作业测试，累计作业超54小时，产量14925件，成功率高达99.987%。此次实景测试验证了基于端到端强化学习模型的高精度视觉检测、精准运控能力，以及机器人与产线系统的深度对接协同能力，标志着人形机器人正向稳定、批量化作业发展。","scd":null,"kp":["应用场景凝练目标[2026年度具身智能专项行动]: 百个以上高价值应用场景","产业落地规模目标[2026年度具身智能专项行动]: 万台级规模落地能力","机器人单次并线作业验证[人形机器人工厂测试]: 8台设备连续作业6天且每天10小时","产线作业成功率[单工位8小时测试验证]: 100%","累计总作业时长[连续并线直播第5天统计]: 超5（天或相关单位时间）"]},{"i":3147,"as":"当前许多“AI+”产品仅停留在将AI技术生硬叠加于原有场景的浅层对接，缺乏对垂直行业数据的深度挖掘和精细定制，导致频发AI“幻觉”和事实错误。“AI+”落地绝非简单做加法，必须深入吃透各行业的底层运行逻辑，梳理垂直数据。例如“AI+冶金”需要从智能配料、炉温控制等复杂工艺流程入手，将AI无缝嵌入具体业务流程，才能破解行业痛点，实现深度有效的赋能。","scd":null,"kp":[]},{"i":3148,"as":"3D打印技术正加速突破小众圈层，成为大众消费市场的新宠。依托国内完备的机电与精密加工产业链，核心零部件实现国产化及规模化量产，成功打造出高集成软硬件协同方案。如今，主打精密智造的消费级3D打印设备已从实验室和工厂走入普通家庭，广泛应用于家用DIY、校园教育、创业创新及规模化生产等多个领域。","scd":null,"kp":["技术属性[消费级及工业级3D打印]: 运用塑料或粉末状金属等材料进行“从无到有”的增材制造","产业链特征[国内3D打印设备]: 核心零部件国产化及规模化量产"]},{"i":3149,"as":"在2026 MWC上海大会上，通信业指出AI正从大模型比拼转向应用落地，日均Token调用量激增，带来“比特+词元”双轮驱动的新商业范式。Token交互对网络提出了毫秒级时延和全链路高可靠性的刚性要求。数据显示，网络时延每增加50毫秒，完成同一任务的Token消耗量会上升20%。为此，中国电信等运营商正通过建设5G-A大上行网络，向提供确定性体验的“可保障连接”服务模式转变。","scd":null,"kp":["日均Token调用量[我国人工智能应用]: 突破140万亿次","Token调用量增长率[较2024年初]: 实现1000倍的增长","全球AI智能体预测总量[到2035年]: 预计将达到9000亿个","智能体任务承担率预测[到2035年日常任务]: 约15%将由智能体自主完成"]},{"i":3150,"as":"河北省廊坊市作为全国算力第一梯队城市，城市算力分指数连续两年位居全国第一。目前廊坊已投运36个数据中心，标准机柜达46.27万架，全国算力中心服务商十强中有7家在此布局。廊坊正通过做强优质算力底座、拓宽人工智能应用场景，以AI赋能高效政务服务，培育新质生产力，推动经济社会的高质量发展。","scd":null,"kp":["投运数据中心数量[廊坊市算力底座建设]: 36个","标准机柜规模[廊坊市数据中心]: 46.27万架","产业集聚度[全国算力中心服务商十强布局]: 7家落户廊坊"]},{"i":3151,"as":"毫米波雷达、智能床带、养老机器人等AI智能设备正加速进入养老机构，重构传统照护体系。这些设备通过无感监测老人跌倒等状态并发出预警，结合AI系统分析全周期健康数据，有效预判慢性病风险。此外，依托物联网系统，养老机构实现了人员排班、能耗管控和物资调度的精细化运营，有效缓解了行业人力短缺痛点。部分头部养老企业已启动IPO，募资重点投向数字化智能化平台建设。","scd":null,"kp":["核心技术应用[隐私保护及生命体征监测]: 毫米波雷达、智能床带等设备实现翻身、离床、跌倒等无感监测","智能分析平台[养老机构精细运营]: 依托鸿蒙系统汇总数据，利用AI智能分析实现人员排班、能耗管控等决策优化"]},{"i":3152,"as":"医疗人工智能的临床应用正从“能用”加速向“用好”迭代升级。在天津举行的研讨会上，行业代表指出，医疗AI的深度演进需要技术能力、临床机制和治理体系同步发展。政、医、企、研四方需建立常态化协同机制，围绕患者全周期健康管理、临床应用实践和医疗数据安全等议题深入合作，共同推动数字技术赋能医院高质量发展。","scd":null,"kp":[]},{"i":3153,"as":"河北雄安新区科创中心中试基地正培育空天信息产业。以中国星网为核心发挥“头雁效应”，已吸引69家企业聚集，形成了涵盖卫星研发、制造和应用全链条的创新产业链。雄安新区集中优势资源发展该标志性未来产业，致力于打造空天产业的科创示范窗口。","scd":null,"kp":["产业链完整度[雄安空天信息产业]: 涵盖卫星研发、制造、应用全链条","产业聚集规模[雄安新区科创中心中试基地]: 69家企业聚集"]},{"i":3154,"as":"中国国家算力基础设施正由分散建设向联网调度迈进。国家正统筹规划算力网、新一代通信网、新型电网等现代化基础设施网络。算力网的建设旨在实现算力资源像水电一样随取随用，构建覆盖全国、联通全球的现代化基础设施体系。","scd":null,"kp":["[算力网建设]: 推动算力像水电一样随取随用，从分散建设迈向联网调度"]},{"i":3155,"as":"针对智能驾驶事故责任归属问题，比亚迪、华为引望等十余家车企相继推出智驾“兜底”保障方案。然而，此类方案多为车企自主运营的增值服务，存在数据不透明、缺乏行业统一规范等弊端。真正的智驾保障需保险业深度参与，金融监管总局等部门已在推进智驾专属车险落地，以建立多方协同的共担机制。","scd":null,"kp":["[智能辅助驾驶责任归属]: 驾驶风险逐步传导至整车厂商与软硬件供应商，边界日益模糊","[车企智驾兜底方案]: 属于自发运营的过渡性增值补偿手段，不能替代标准化车险"]},{"i":3156,"as":"在国际超算大会上，中国“灵晟”超级计算机以每秒219亿亿次的持续双精度浮点性能登顶全球第一。系统实现从芯片到软硬件的全栈国产化，首创全CPU架构并内嵌AI矩阵加速单元，区别于西方主流的CPU-GPU异构路线。其全栈自主能力保障了国家在武器模拟、气象预报等战略领域的科研安全与发展。","scd":null,"kp":["持续双精度浮点性能[“灵晟”超级计算机]: 219亿亿次/秒 (2.198EFlops)","[“灵晟”超级计算机]: 实现从芯片到系统的全栈国产化","[“灵晟”超级计算机构筑]: 采用国产高性能CPU、片上高带宽内存、高速互连网络、全液冷散热及大规模超智融合框架"]},{"i":3157,"as":"挪威国家电力公司宣布计划对位于挪威的Mar水力发电厂进行重大升级改造。该项目除了提升电厂的发电能力外，还将增加储能选项配置。具体的技术参数和投资金额尚未在文中详细披露。","scd":null,"kp":[]},{"i":3158,"as":"Greenvolt Power公司宣布在波兰成功接入了一个规模达200兆瓦（MW）的电池储能系统项目。该项目标志着该企业在波兰新能源储能市场的进一步布局。","scd":null,"kp":["储能规模[Greenvolt Power波兰电池项目]: 200 MW"]},{"i":3159,"as":"湖北省能源局公布2026年度新能源开发建设方案第二批项目清单，共包含59个项目，总容量483.6万千瓦。其中风电项目49个、光伏项目10个。文件要求各项目单位将电源侧储能与新能源项目一体化建设和投运。仙桃市和天门市需同步建设支撑储能项目以保障并网消纳。","scd":null,"kp":["总容量[湖北2026年度新能源项目第二批]: 483.6万千瓦","项目数量[湖北2026年度新能源项目第二批]: 59个","容量[风电项目]: 407.1万千瓦","容量[光伏发电项目]: 76.5万千瓦","[新能源发电与储能项目建设]: 实行电源侧储能一体化设计、核准、建设与同步投运"]},{"i":3160,"as":"上海罗曼科技与永济市永润聚合新能源签署金额为2.86亿元的EPC总承包合同。该项目位于山西永济市，额定容量100MW，安装容量105.01344MWp。项目将新建一座220kV升压站，采用固定单价2.728元/W的交钥匙工程模式建设。","scd":null,"kp":["合同金额[永济市100MW光伏EPC项目]: 2.86亿元","额定容量[永济市光伏项目]: 100MW","安装容量[永济市光伏项目]: 105.01344MWp","单价[永济市光伏EPC总承包]: 2.728元/W"]},{"i":3161,"as":"华能沾化新能源拟在山东滨州沾化区建设一期200MW光伏发电项目，总投资7.355亿元，工期12个月。项目利用4000亩滩涂地，直流侧容量216.0158MW，安装332332块650Wp单晶双面组件。设计方案共包含58个3.3MW及其他多种规格方阵，采用太阳能发电单元与升压变压器单元接线方式。","scd":null,"kp":["交流侧容量[华能滨州鲁北基地一期光伏项目]: 200MW","直流侧容量[华能滨州鲁北基地一期光伏项目]: 216.0158MWp","总投资[华能滨州鲁北基地一期光伏项目]: 73550万元","占地面积[华能滨州鲁北基地一期光伏项目]: 约4000亩滩涂地","组件规格[华能滨州鲁北基地一期光伏项目]: 650Wp单晶双面光伏组件"]},{"i":3162,"as":"山西电力交易中心将未按期整改的26家售电公司2025年度信用评价降为D级，并列入重点监测名单。这26家企业需在1个月整改期内补传信息与报告。若拒不整改，将视为违反信用承诺，相关部门将按规定对其启动强制退出市场程序。","scd":null,"kp":["[山西售电公司信用评价]: 26家售电公司降为D级，拒不整改将启动强制退出市场程序","整改期[降级售电公司]: 1个月（2026年6月24日到2026年7月23日）"]},{"i":3163,"as":"金开新能孙公司宁夏国信收到税务局处理决定书，需补缴税款及滞纳金合计1674.18万元。公司已按要求完成补缴，该事项预计减少2026年度归母净利润1655.65万元。宁夏国信持有盐池100MW光伏发电项目，本次补缴为补税及滞纳金，不涉及行政处罚，不影响公司正常经营。","scd":null,"kp":["补缴总额[宁夏国信补税事项]: 1674.18万元（含税款238.61万元，滞纳金1435.57万元）","减少净利润[金开新能2026年度]: 预计1655.65万元","项目规模[宁夏国信光伏项目]: 100MW光伏发电与畜牧加工一体化"]},{"i":3164,"as":"中核集团发布2026-2027年度光伏组件设备一级集中采购招标公告。本次为框架采购，有效期1年，采购标的为N型组件，包含TOPCON和BC两种技术路线。投标人可选择单一路线或主备选路线投标。此次招标不接受联合体投标，具体交货时间将以订单通知为准。","scd":null,"kp":["集采规模预期[中核集团光伏组件]: 覆盖2026-2027年度预计装机总量","技术路线[N型光伏组件]: TOPCON和BC两种方案","采购有效期[一级集中采购框架]: 自协议生效之日起1年"]},{"i":3165,"as":"","scd":null,"kp":[]},{"i":3166,"as":"为防止在无意中触发借助竞品模型输出训练自家AI的“蒸馏”行为，Meta内部出台规范，限制AI工程师使用Anthropic的Claude Code与OpenAI的Codex。Meta警告此举可能引发与合作企业的严重纠纷。Meta发言人确认公司已有明确政策规范AI工具的使用，以确保负责任的工作方式。","scd":null,"kp":["管控措施[Meta AI工程师外部工具调用]: 限制使用Anthropic的Claude Code与OpenAI的Codex","核心动因[大模型研发防范]: 避免无意间触发模型蒸馏及涉嫌违反用户协议","潜在风险[训练数据污染]: 竞争对手AI输出渗入训练数据引发商业纠纷"]},{"i":3167,"as":"安全公司Push Security披露黑客滥用OpenAI组织邀请功能实施精准钓鱼攻击。黑客创建虚假OpenAI组织并向特定员工发送官方邀请邮件。受邀员工默认获得最高Owner权限，且黑客提前绑定信用卡，只需点击链接即可加入环境，无需额外身份验证。Push Security建议企业建立针对AI平台协作机制的安全验证流程。","scd":null,"kp":["攻击载荷[OpenAI官方邀请功能]: 钓鱼邮件经官方服务器发送且通过标准身份验证","权限分配[受邀请员工默认角色]: Owner（最高级别组织管理权限）","前置准备[黑客支付方式预绑]: 提前绑定Visa信用卡消除付费门槛"]},{"i":3168,"as":"苹果向欧盟委员会提交申报收购应用设计工具Play开发商Rabbit 3 Times的部分资产及员工，该申报已对外公示。Play是一款基于SwiftUI框架制作交互原型的获奖设计工具。目前Play应用已从App Store下架。苹果或将利用此次收购的知识产权优化Xcode开发工具。","scd":null,"kp":["收购标的[苹果资产兼并]: Rabbit 3 Times公司部分资产与相关员工","核心技术[应用设计工具Play]: 基于SwiftUI框架制作可交互原型并导入Xcode","业务结果[应用商店状态]: App Store已下架Play应用"]},{"i":3169,"as":"蓝箭航天招股书显示，参考在手订单，当前单发朱雀三号发射服务收入约1.5亿元。公司拟募资75亿元用于可重复使用火箭的相关项目。随着火箭运力和可靠性提升，单发收入具备提升可行性。蓝箭航天预计最早于2029年实现合并报表盈利。目前朱雀三号遥二火箭已完成地面验证，准备执行飞行试验。","scd":null,"kp":["发射服务收入[朱雀三号单发参考价格]: 约1.5亿元/发次","募集资金[蓝箭航天本次IPO]: 约75亿元","资金用途[可重复使用火箭]: 投向产能提升与技术提升项目","盈利预期[公司合并报表]: 最早可于2029年实现","研发状态[朱雀三号重复使用遥二]: 发射前各项关键地面验证工作已全部完成"]},{"i":3170,"as":"","scd":null,"kp":[]},{"i":3171,"as":"","scd":null,"kp":[]},{"i":3172,"as":"领克07GT时间限量版正式上市，指导价20.88万元，限量首发1007台已售罄。该限量版车型采用专属哑光勃朗灰车漆和极地蓝内饰，配备干式碳纤维尾翼、四活塞卡钳等。此外，新车还提供包含哈曼卡顿音响和H7安全辅助驾驶系统升级方案在内价值约6.5万元的权益。","scd":null,"kp":["指导价[领克07GT时间限量版]: 20.88万元","预售起售价[领克07GT家族首款旅行车]: 16.58万元","限量发售[时间限量版]: 1007台已售罄","升级价值[限量版专属权益]: 总计约6.5万元"]},{"i":3173,"as":"","scd":null,"kp":[]},{"i":3174,"as":"","scd":null,"kp":[]},{"i":3175,"as":"","scd":null,"kp":[]},{"i":3176,"as":"康奈尔大学研究团队提出一种新型锂离子电池再生方法，区别于传统的物理粉碎与化学提取，该方法旨在直接再生电池电极。实验室测试表明，该技术成功将老化电池的容量恢复至初始值的95%。","scd":null,"kp":["容量恢复[老化锂电池电极再生]: 最高恢复至初始值的95%"]},{"i":3177,"as":"德国经济部长正加速推进Lyten对位于海德的Northvolt剩余项目的收购。作为临时措施，德国联邦经济部已将当地项目公司置于国家控制之下，相关股份由LG Batterie等公司代为托管，旨在将关键义务转移给Lyten。","scd":null,"kp":["托管状态[德国Northvolt Drei项目公司]: 移交至德国国家控制","过渡措施[收购转移]: 寻求将关键义务转移给Lyten"]},{"i":3178,"as":"陶氏公司宣布将在2027年前投资约1亿美元，用于扩大美国、中国和日本的特种有机硅产能。该项投资旨在增强供应链弹性，满足数据中心、半导体、出行和医疗保健等领域的需求增长。具体扩产项目包括美国卡罗顿和中国张家港的液体硅橡胶制造。","scd":null,"kp":["投资金额[陶氏特种有机硅扩产]: 约1亿美元","目标时间[供应链弹性强化]: 持续至2027年","布局范围[生产制造扩张]: 覆盖美国、中国和日本"]},{"i":3179,"as":"","scd":null,"kp":[]},{"i":3180,"as":"","scd":null,"kp":[]},{"i":3181,"as":"美国内政部与杜克能源公司达成协议，取消了原本廉价且清洁的卡罗莱纳长湾海上风电项目，转而支持昂贵且污染严重的天然气项目。化石燃料污染每年在全球范围内导致数百万人口死亡及万亿级美元损失，放弃清洁风电不仅推高了成本，也剥夺了美国亟需的电力资源。","scd":null,"kp":["交易标的[内政部与Duke Energy协议]: 取消Carolina Long Bay海上风电项目","核心动因[能源项目替换]: 放弃廉价清洁风电转为聚焦昂贵的天然气项目"]},{"i":3182,"as":"特斯拉宣布已在奥斯汀公共道路上开始对其首款量产Cybercab进行工程测试，这是该专属robotaxi首次在工厂外进行客户规格的验证。视频显示，这款没有方向盘和踏板的双座车辆在自动驾驶时，副驾驶位置坐有一名监督员，表明其目前尚未在付费服务中完全无人驾驶。","scd":null,"kp":["[Cybercab量产版]: 开始在奥斯汀公共道路进行工程测试，前排副驾设有监督员","[客户规格量产车]: 首次在工厂外进行验证"]},{"i":3183,"as":"Jeep宣布取消在欧洲和英国推出Recon和Wagoneer S两款纯电动汽车的计划，原因是严酷的市场条件与右舵车型的开发成本过高。同时，Jeep确认将推出三款新SUV，其中包括一款采用中国技术的全新旗舰车型。Recon EV目前仅在美国和加拿大市场销售。","scd":null,"kp":["[Jeep Recon和Wagoneer S电动汽车]: 取消在欧洲和英国市场的发布计划"]},{"i":3184,"as":"加拿大电动两轮车制造商Beachman发布了最新Aviator系列。该平台采用全新车架，提供三种配置。入门级Class 2电动自行车起售价5499美元，公路时速32公里，越野时速56公里。该版本提供2.8千瓦时和4.3千瓦时两种电池可选，续航里程分别达89公里和129公里。","scd":null,"kp":["[Aviator电动两轮车平台]: 涵盖从Class 2电动自行车到具备高速公路行驶能力的电动摩托车"]},{"i":3185,"as":"Goldbeck Solar开发了名为HeliomatiX的公用事业规模光伏电站自动化建设系统。该系统由基于集装箱的装配中心、自主爬行器和机器人安装组成，可同时预装四块光伏组件。该技术可将安装人工时长减少高达85%，并在数小时内实现兆瓦级部署。","scd":null,"kp":["安装人工耗时[公用事业规模光伏电站自动化建设HeliomatiX系统]: 最多减少85%","部署规模[公用事业规模光伏电站自动化建设]: 兆瓦级","[组件装配单元]: 由六个40英尺集装箱组成，长度延伸至55米","[预装配能力]: 最多同时预装配四块光伏组件"]},{"i":3186,"as":"光伏行业专家在会议中指出，电池储能系统（BESS）项目在整个生命周期内的表现和可融资性，并非仅取决于电池化学成分，而是更依赖于严格的质量控制、合同设计和认证体系。工厂审计经常发现电池质量问题，特别是在极端高温环境下，电池系统的性能与保修保障尤为关键。","scd":null,"kp":["[BESS项目可融资性及性能表现]: 质量控制、合同设计和认证比单一的电池化学成分更具决定性作用"]},{"i":3187,"as":"据报告预测，受数据中心、绿氢及夜间电力连接需求的推动，印度太阳能市场将快速增长。从2029财年起，这些领域每年将增加15至20吉瓦的增量需求。预计印度的太阳能年装机容量将从2027财年的约50吉瓦，大幅增长至三年后的近85吉瓦。目前其公用事业规模光伏项目管道约为2.5年。","scd":null,"kp":["新增光伏需求[印度数据中心、绿氢和夜间连接(2029财年起)]: 每年15-20吉瓦","太阳能年装机容量[印度(2030财年)]: 近85吉瓦","太阳能年装机容量[印度(2027财年)]: 约50吉瓦"]},{"i":3188,"as":"法国光伏制造商Voltec开发了一款新型50片电池的玻璃背板住宅组件。该设计创新地将电池垂直于组件长度排列，使其能在不改变组件外形尺寸的情况下多放置两片电池。每片电池功率为9.5瓦，新布局在保持尺寸基本一致的同时，将组件输出功率提升了18至19瓦，功率提升达4%。","scd":null,"kp":["功率输出[50片玻璃背板住宅光伏组件布局]: 提升4%","[电池排布方式[住宅光伏组件]]: 电池垂直于组件长度排列"]},{"i":3189,"as":"加拿大初创公司Reflect10研发出一种新型光伏组件几何结构。该架构将光线反射结构直接集成在光伏板中，相比传统平板组件可将日均能源产量提升20%。特别是在清晨和傍晚时段，该设计的能源收益最高可达传统组件的2.66倍。","scd":null,"kp":["日均能源产量[集成反射几何形状的光伏组件架构]: 平均提高20%","能源产量提升[光伏组件早晚时段]: 高达2.66倍"]},{"i":3190,"as":"受席卷欧洲大陆的热浪影响，欧洲电力需求激增，导致电价大幅上涨。数据显示，上周除北欧市场均价为68.24欧元/兆瓦时外，比利时、英国、荷兰、法国、德国、意大利、葡萄牙和西班牙等欧洲主要市场的周平均电价均超过了115欧元/兆瓦时。","scd":null,"kp":["周平均电价[欧洲热浪期间主要电力市场]: 超过115欧元/兆瓦时"]},{"i":3191,"as":"根据《2026年太阳能规模》报告，截至今年5月，爱尔兰太阳能并网容量已达2.7吉瓦，其中超1.5吉瓦来自公用事业规模项目。预计到年底，联网容量将超3.3吉瓦。随着光伏渗透率提高，电网已出现“鸭子曲线”现象，报告呼吁建设更多储能设施以平衡电网。","scd":null,"kp":["并网太阳能容量[爱尔兰(截至5月)]: 2.7吉瓦","并网太阳能容量[爱尔兰(预计年底)]: 超过3.3吉瓦"]},{"i":3192,"as":"一项针对欧洲38国太阳能潜力的研究表明，在不增加储能系统或灵活性措施的前提下，且在逐时需求限制内，欧洲国家电网最高可整合约614吉瓦的太阳能装机容量。这一容量每年可产生约678太瓦时的电力，且能在不出现任何一小时产能过剩的情况下实现。","scd":null,"kp":["光伏装机潜力[欧洲国家电网受限于每小时需求]: 约614 GW","年发电量[欧洲614 GW装机]: 约678 TWh","[系统整合]: 在未增加储能或灵活性措施前，可实现无任何一小时的产能过剩"]},{"i":3193,"as":"新南威尔士大学的研究人员开发出用于农业光伏的光谱选择性半透明晶体硅太阳能模块。该模块通过分布式布拉格反射仪和V型槽聚光器将近红外光引导至太阳能电池，同时将光合有效辐射透射给农作物。测试表明，该设计的电力输出比传统半透明光伏模块高出34%。","scd":null,"kp":["电输出提升[农用光伏光谱选择性半透明晶硅组件对比传统半透明组件]: 高出34%","[光学设计特点]: 结合分布式布拉格反射镜将近红外光导向电池，同时将光合有效辐射透射给农作物"]},{"i":3194,"as":"英国埃克塞特大学的科学家对水库中的浮动光伏(FPV)结合绿氢生产系统进行了评估。研究利用PVsyst和Homer Pro软件模拟了全年发电和电解过程。结果显示，大规模浮动太阳能能产生大量用于供热、交通和电力的氢气，同时通过减少水分蒸发带来显著的节水效益。","scd":null,"kp":["[系统应用潜力]: 大规模漂浮式光伏制氢可产生大量氢气用于供热、交通和电力，并显著减少水分蒸发节约水资源"]},{"i":3195,"as":"Flexion Robotics推出了Reflect v1.0机器人智能平台，赋予人形机器人无需人工干预即可自主完成复杂多步任务的能力。在一次办公配送演示中，机器人完成了取件、爬楼梯、乘电梯、拆包和收纳等任务。强化学习使16步任务的完成率从38%提升至90%。","scd":null,"kp":["[自主执行能力]: 赋予人形机器人无需人工干预即可自主完成复杂多步骤任务的长期自主性","[系统集成]: 融合了任务控制、运动规划等功能"]},{"i":3196,"as":"","scd":null,"kp":[]},{"i":3197,"as":"英国皇家海军将调整国防战略，放弃传统下一代驱逐舰计划，转而采购至少六艘能够指挥无人机舰队的混合动力军舰。这种新型通用战斗舰(CCv)计划于2030年代初期服役，作为空中、水面和水下无人系统的指挥枢纽，反映了英国对分布式和自主海战的重视。","scd":null,"kp":["采购数量[英国下一代混合战舰/无人机母舰]: 至少6艘","[服役计划]: 取代原计划中的83型驱逐舰，预计于2030年代初服役","[核心功能定位]: 旨在指挥和协调无人系统/无人机舰队"]},{"i":3198,"as":"荷兰材料公司Paebbl推出了据称是世界上第一种负碳建筑材料Rebond 300。作为一种辅助胶凝材料，它可替代高达30%的波特兰水泥并混入标准混凝土中。该材料的环境产品声明(EPD)足迹为每吨-149公斤二氧化碳，兼具建筑材料和验证过的碳移除工具双重价值。","scd":null,"kp":["[材料属性]: 全球首创的负碳建筑材料","[材料功能]: 作为辅助胶凝材料 (SCM) 部分替代并混入标准混凝土中，同时兼具建筑材料与核证碳移除工具的双重价值"]},{"i":3199,"as":"美国爱达荷国家实验室(INL)的科学家在六硼化钚(PuB6)中发现了罕见的拓扑近藤绝缘态量子特性。钚作为被广泛用于工业和核反应堆的锕系金属，由于研究难度极大，其量子特性在过去80年中一直未被探索。这一新发现对推动未来的核技术发展具有重要意义。","scd":null,"kp":["新发现量子态[六硼化钚(PuB6)]: 拓扑近藤绝缘态","[技术意义]: 该重金属材料广泛用于工业及核武过程，此项未探索属性的发现有望推动未来核技术发展"]},{"i":3200,"as":"","scd":null,"kp":[]},{"i":3201,"as":"美国洛斯阿拉莫斯等国家实验室与堪萨斯城国家安全园区合作，制造出名为Aires Tide的3D打印锥形核试验飞行器。这种智能原型长3.35米，旨在承受高速核武器飞行时经历的极端高温和振动。该项目是国家核安全局Genesis任务的首个重大成果，利用了先进超级计算机网络、数字工程和人工智能技术来加速设计。","scd":null,"kp":["尺寸[智能核试验飞行器原型(Aires Tide)]: 11英尺 (3.35米)","[物理特征]: 锥形设计，能够承受高速核武器飞行过程中经历的极端高温和振动"]},{"i":3202,"as":"加州大学洛杉矶分校(UCLA)主导的研究团队开发出一种带有3D打印电极的锌离子混合电池。与同类设备相比，该电池的存储电量增加了七倍以上，并具备快速充电和持久使用的特点。研究采用锌替代锂，因为锌储量丰富、开采和回收更容易，成本更低且更具可持续性。","scd":null,"kp":["存储电量提升[3D打印电极锌离子混合电池]: 超过同类混合设备的7倍","[应用优势定位]: 针对需要快速充放电、低成本且长期耐用的储能应用，以更便宜环保的锌替代锂"]},{"i":3203,"as":"伊利诺伊州一个装机容量为270兆瓦的Archtop太阳能项目正式投入商业运营。该项目利用了Earthrise Energy公司的剩余互连策略，通过直接接入吉布森市现有天然气调峰电厂的输电线路，跳过了通常需要数年时间的新电网连接排队等待期，从而加速了清洁能源的并网上线。","scd":null,"kp":["装机容量[伊利诺伊州Archtop Solar项目]: 270 MWac","[并网策略]: 利用现有天然气发电厂的传输线进行连接，跳过漫长的新电网接入排队等待"]},{"i":3204,"as":"在马里亚纳群岛以北的实弹演习中，美国一架B-2隐形轰炸机成功发射了一枚远程反舰导弹(LRASM)并击中海上目标。这是B-2轰炸机首次在实战任务中使用这种先进的远程反舰导弹。此次演习展示了美军在印太地区应对海上威胁的远程精确打击能力的提升。","scd":null,"kp":["[B-2隐形轰炸机]: 首次在实战任务中使用远程反舰导弹(LRASM)成功打击海上目标"]},{"i":3205,"as":"","scd":null,"kp":[]},{"i":3206,"as":"","scd":null,"kp":[]},{"i":3207,"as":"","scd":null,"kp":[]},{"i":3208,"as":"宇航员在国际空间站上激活了美国宇航局(NASA)全新升级的冷原子实验室。该轨道量子实验室利用空间站的微重力环境，将原子冷却至接近绝对零度，以研究物质的奇异量子态。这一独特的实验设施使科学家能够进行地球上无法实现的实验，推进下一代量子技术的发展。","scd":null,"kp":["[国际空间站冷原子实验室]: 升级后的设施利用微重力环境将原子冷却至接近绝对零度以研究物质基本性质"]},{"i":3209,"as":"西北大学领导的天文学团队利用詹姆斯·韦伯太空望远镜，在著名的“粉色星球”周围发现了奇异的盐云。这颗古老的行星是已知最冷的直接成像行星质量伴星之一。由于该行星非常微弱，地面望远镜此前一直难以分析其大气反射光。新观测终于清晰揭示了其充满不寻常化学成分和盐云的大气层。","scd":null,"kp":["[粉红色星球]: 发现充满盐云的奇异大气特征"]},{"i":3210,"as":"天文学家发现名为ASKAP J1745的重复射电爆发源来自一对近距离相互绕转的恒星。这种被称为长周期瞬变的现象的重复速度比许多其他射电源慢得多。发表在《自然天文学》上的研究报告首次探测到了与轨道同步重复的X射线和射电爆发，这有助于解码这类罕见神秘信号的来源。","scd":null,"kp":["[重复性长周期射电瞬变信号(ASKAP J1745)]: 信号源可能来自一对近距离互绕的双星"]},{"i":3211,"as":"","scd":null,"kp":[]},{"i":3212,"as":"","scd":null,"kp":[]},{"i":3213,"as":"","scd":null,"kp":[]},{"i":3214,"as":"山东科技大学科研团队在柔性钙钛矿太阳能电池研究中取得突破，提出“错位偶极工程”策略，开发出可修复含氟聚合物弹性体。该材料引入薄膜后增强了晶界韧性，有效缓解热应力引发的疲劳裂纹。基于此策略的柔性电池最高效率达25.54%，在经历11000次弯曲和500次热循环后，效率仍保持初始值的90%以上，展现出极佳的长期稳定性。","scd":null,"kp":["光电转换效率[钙钛矿太阳能电池]: 超过27%","光电转换效率[柔性器件(错位偶极工程策略)]: 25.54%","光电转换效率[刚性器件(错位偶极工程策略)]: 26.83%","[含氟聚合物弹性体改性策略]: 经氟化错位偶极子工程改性后引入钙钛矿薄膜，显著增强晶界韧性，抑制晶格热膨胀率","长期稳定性测试[复杂环境下运行]: 经历11000次（推测为弯折/热循环）"]},{"i":3215,"as":"昆明电力交易中心组织了云南2027年机制电价竞价。本轮申报项目数高达2354个，较前轮暴增4倍，但光伏与风电出清价（分别为0.331元和0.3351元/千瓦时）却不跌反涨，中标率高达99.4%。业内将此量价齐升现象归因为储能配置完善、并网窗口收窄及市场报价趋于理性。机制电价作为新能源项目的收益“安全网”，将直接影响2027年并网项目的保底收益。","scd":null,"kp":["出清价[云南2027年光伏机制电价竞价]: 0.331元/千瓦时","出清价[云南2027年风电机制电价竞价]: 0.3351元/千瓦时","中标率[云南2027年机制电价竞价]: 99.4%"]},{"i":3216,"as":"随着芯片走私调查范围的扩大，超微（Supermicro）位于台湾的办事处遭到突击搜查。","scd":null,"kp":[]},{"i":3217,"as":"","scd":null,"kp":[]},{"i":3218,"as":"Uber 与 Waymo 正式结束了双方在凤凰城的自动驾驶出租车合作。","scd":null,"kp":[]},{"i":3219,"as":"","scd":null,"kp":[]},{"i":3220,"as":"火箭实验室宣布达成一项协议，将收购知名卫星公司铱星公司。","scd":null,"kp":[]},{"i":3221,"as":"人工智能正在变革农业领域，数据显示AI预测模型可将作物产量提高26%，减少41%的用水量并削减33%的化学品使用。然而，这些AI解决方案的有效性依赖于干净且坚实的数据基础。行业领导者在投资AI前，必须优先打好数据基础的底座工作。","scd":null,"kp":["作物产量提升[AI预测模型应用]: 26%","用水量减少[AI预测模型应用]: 41%","化学品使用量减少[AI预测模型应用]: 33%"]},{"i":3222,"as":"过去二十年里，包括苹果、谷歌、Meta、微软、英伟达和OpenAI在内的众多全球顶尖科技公司，纷纷在瑞士苏黎世及其周边地区建立了研发中心。苏黎世已从谷歌在美国境外最大的研发基地，发展成为全球人工智能研究、人才和商业化最密集的中心之一，在某些领域的集中度甚至超过了硅谷。","scd":null,"kp":["科技企业R&D中心分布[苏黎世及周边地区]: 涵盖Google、Microsoft、NVIDIA、Apple、OpenAI等全球顶级科技企业","Google最大工程中心选址[海外布局]: 苏黎世"]},{"i":3223,"as":"Eku Energy计划于2029年底前在德国下萨克森州建设名为Dion的400兆瓦/1600兆瓦时电池储能系统，这标志着该公司进军德国储能市场。该4小时电池系统直接接入输电网，具备构网和黑启动能力。长期合作伙伴Fluence将提供LFP电池系统。项目一旦建成，将成为德国最大的电池储能设施之一。","scd":null,"kp":["储能项目规模[Dion电池储能系统]: 400 MW功率与1,600 MWh容量","储能时长[Dion电池储能系统]: 4小时","预计投运时间[德国Lamspringe项目]: 2029年底前","电网接入方式[Dion项目]: 直接接入输电网"]},{"i":3224,"as":"Iberdrola在意大利启用了一座243兆瓦的太阳能发电厂，同时在美国俄勒冈州开始建设41兆瓦/82兆瓦时的电池储能系统（BESS）。该美国储能项目由其子公司Avangrid开发，预计2027年投入运营。此外，投运的意大利太阳能发电厂的大部分产出已与意大利公司签署了长期购电协议（PPA）。","scd":null,"kp":["光伏装机容量[意大利太阳能项目]: 243 MW","储能系统规模[美国俄勒冈州Shutler BESS项目]: 41 MW功率与82 MWh容量","区域发电总容量[Avangrid美国西北部]: 约3 GW"]},{"i":3225,"as":"Allume Energy推出了SolShare 2共享太阳能平台，新增了社区电池储能系统（BESS）集成功能，并将共享太阳能阵列的最大太阳能容量提升了50%。SolShare 2通过按比例分配逻辑控制电池调度，将光伏阵列的千瓦峰值份额分配给相连的每套公寓。新系统将电池兼容能力扩展到了所有安装配置中。","scd":null,"kp":["最大光伏容量增幅[SolShare 2共享太阳能平台]: 提升50%","能量调度控制逻辑[集成BESS的SolShare平台]: 采用与光伏侧相同的按比例分配逻辑"]},{"i":3226,"as":"Enlight子公司Clēnera Holdings为其美国CO Bar太阳能和储能综合体项目筹集了约26亿美元的债务融资，项目总投资约30亿美元。该项目分五期建设，包含1.2吉瓦的光伏和4吉瓦时的储能，第一阶段计划于2027年下半年投入商业运营，首期包含258兆瓦直流太阳能和824兆瓦时储能。","scd":null,"kp":["融资金额[CO Bar太阳能及储能综合体]: 约26亿美元债务融资","光伏装机容量[CO Bar综合项目]: 1.2 GW","储能系统容量[CO Bar综合项目]: 4 GWh","项目总投资额[CO Bar综合项目]: 约30亿美元","首期商业运营时间[CO Bar综合项目]: 2027年下半年"]},{"i":3227,"as":"远景集团已签署协议，为南非自由州省的Naos-1混合光储项目提供660兆瓦时的电池储能系统。该项目由SOLA集团开发，结合了300兆瓦的太阳能光伏与上述电池系统。该项目已于2026年2月达成财务交割，由WBHO负责工程建设。远景将负责提供该储能系统的核心设备与解决方案。","scd":null,"kp":["储能系统供应规模[南非Naos-1光储混合项目]: 660 MWh","光伏装机容量[南非Naos-1项目]: 300 MW","资金关闭时间[Naos-1光储混合项目]: 2026年2月"]},{"i":3228,"as":"日本丰田通商赢得了在贝宁Pobè地区安装50兆瓦/160兆瓦时电池储能系统（BESS）的合同，该项目总成本约为4860万欧元。该储能系统将为三座总装机容量为75兆瓦的太阳能发电厂提供服务。项目EPC合作伙伴为德国工程公司Eiffage RMT，预计在合同生效后15个月（约2027年9月）完工。","scd":null,"kp":["储能系统规模[贝宁Pobè地区电池储能项目]: 50 MW功率与160 MWh容量","配套光储关系[Pobè区域三座太阳能电站]: 服务三座各25 MW（总计75 MW）的光伏电站"]},{"i":3229,"as":"阿根廷布宜诺斯艾利斯省正在建设五个分布式太阳能项目，另有三个项目处于招标阶段。这五个在建项目将增加3.5兆瓦峰值的光伏发电能力和2900千瓦时的电池储能容量。项目由省能源副秘书处与区域电力论坛通过省级分布式能源发电激励计划合作推进，并在特定地点配置电池以应对当地电网需求和季节性问题。","scd":null,"kp":["项目建设状态[布宜诺斯艾利斯省分布式太阳能项目]: 5个处于建设阶段，3个处于招标阶段","项目定位[电网受限区域分布式能源]: 旨在强化电网受限区域的电力供应"]},{"i":3230,"as":"JERA（日本最大的电力公司）正式敲定了向日本运输燃料氨的协议。","scd":null,"kp":[]},{"i":3231,"as":"H-Power公司签署了一项商业供应协议，供应由氨裂解制取的氢气。","scd":null,"kp":["业务协议状态[裂氨制氢/燃料氨运输]: 签署商业供应及运输最终协议"]},{"i":3232,"as":"Facet Amtech获得资金，将用于扩大其新型催化剂技术的规模。","scd":null,"kp":["[商业供应]: 通过裂解氨制取氢气的商业供应协议"]},{"i":3233,"as":"Siltrax发布突破性的基于硅的燃料电池技术。","scd":null,"kp":["燃料电池技术[核心类型]: 硅基燃料电池"]},{"i":3234,"as":"林茨开始建设基于氢气的炼铁厂。","scd":null,"kp":["[炼铁工艺]: 基于氢气的炼铁厂在林茨开始建设"]},{"i":3235,"as":"强制性国家标准《电动汽车用动力蓄电池安全要求》将于2026年7月1日起实施。新国标包含7项单体测试和17项系统测试，核心变化是将热扩散测试要求提升至“不起火、不爆炸”。此外，新规新增底部撞击测试，并针对20%充至80%电量需15分钟内的快充电池，要求在300次快充循环后进行外部短路测试时同样不起火、不爆炸，全面提升了动力电池的安全技术门槛。","scd":null,"kp":["实施时间[GB 38031-2025新国标]: 2026年7月1日","测试项目[电动汽车动力电池新国标]: 7项单体测试及17项电池包或系统测试","热扩散测试[动力电池安全新规]: 调整为不起火、不爆炸，且烟气不对乘员造成伤害"]},{"i":3236,"as":"深圳眼镜产业正依托制造积累和产业链向AI智能眼镜生态跃迁。AI智能配镜太空舱实现20-30分钟自助配镜，集成了眼部屈光数据采集、脸型建模和机械臂交互取架功能。展会集中发布了多款AI眼镜新品，涵盖商务、运动、AR显示和健康监测等场景。未来AI眼镜需在重量控制、功耗管理、佩戴舒适度和光学显示等核心技术上持续突破。","scd":null,"kp":["配镜耗时[AI智能配镜太空舱]: 20~30分钟即可自助完成主要流程"]},{"i":3237,"as":"2026重庆国际汽车展览会聚焦智能化，AI技术已全面转化为汽车产品体验。我国辅助驾驶新车渗透率超60%，由中欧美等多方联合牵头编制的全球首部自动驾驶全生命周期统一技术法规获批发布。展会集中展示了电池闪充、智能座舱、底盘技术及车路云协同等完整链路技术。国产AI大模型上车使汽车交互具备“情感感知”能力，向物理AI时代迈进。","scd":null,"kp":["辅助驾驶新车渗透率[国内市场]: 超60%","自动驾驶等级[已落地车型]: L3级","车展规模[2026重庆国际汽车展览会]: 展示1050款车型，发布96款新车","体验区面积[比亚迪辅助驾驶与底盘技术]: 3000平方米"]},{"i":3238,"as":"国务院常务会议审议通过《“十五五”碳达峰行动方案》。会议强调发挥双碳战略牵引作用，加快能源结构调整优化，推进产业绿色低碳化，完善碳排放统计核算体系。方案将加速工业、建筑、交通等高耗能行业的绿色转型，重点打造清洁电力、新能源汽车等绿色经济增长点。同时，将通过数字化赋能绿色化协同发展，推动节能降碳领域新产业、新业态的涌现。","scd":null,"kp":["[政策导向]: 审议通过《“十五五”碳达峰行动方案》以加快能源结构调整优化"]},{"i":3239,"as":"我国正推动产学研用深度融合以解决科研与产业“两张皮”问题。2024年全国高校院所科技成果转化合同额达2269.1亿元。目前深度融合仍面临科研方向错位、人才培养存在时间差以及协同机制不健全等掣肘。解决方案包括推动校企共建课程与平台，构建“决策共商、项目共研、人才共用、利益共享”的联动机制，使创新要素在主体间自由流动。","scd":null,"kp":[]},{"i":3240,"as":"","scd":null,"kp":[]},{"i":3241,"as":"朱雀三号遥二可复用运载火箭在东风商业航天创新试验区顺利完成静态点火试验。本次点火试验有效检验了火箭系统与发射场系统及其匹配性，各项系统工作均保持正常。试验队后续将按既定计划开展发射准备工作，以执行火箭飞行试验任务。","scd":null,"kp":["[关键技术状态]: 朱雀三号遥二可复用运载火箭顺利完成静态点火试验，各系统工作正常"]},{"i":3242,"as":"解放军总医院专家团队利用5G+AI技术，成功为汕头患者实施远程机器人胃肠肿瘤手术。手术采用“专家在京、手术在粤”模式，北京团队负责术式规划与主刀操控，汕头团队进行床旁协助。两地通过超低延时5G专网与手术机器人系统无缝对接，确保了远程操作的高精准度与安全性。","scd":null,"kp":["[关键技术状态]: 依托超低延时5G专网与手术机器人系统无缝对接，成功实施跨异地远程机器人胃肠肿瘤手术"]},{"i":3243,"as":"Ignitis已获得环境批准，将在立陶宛建设一座装机容量为700兆瓦的海上风电场。","scd":null,"kp":["装机容量[立陶宛海上风电场]: 700兆瓦"]},{"i":3244,"as":"韩国在2026年上半年的海上风电拍卖中，共授予了1.8吉瓦（GW）的装机容量。","scd":null,"kp":["授予容量[韩国上半年海上风电拍卖]: 1.8吉瓦"]},{"i":3245,"as":"由韩国水力核电公司（KHNP）领导的集团在韩国赢得了一项800兆瓦（MW）的海上风电项目招标。","scd":null,"kp":["中标容量[KHNP集团韩国海上风电招标]: 800兆瓦"]},{"i":3246,"as":"山西省吕梁市发布《关于进一步加快新能源项目建设确保按期并网的通知》，由市推动绿电资源就地转化助力产业低碳转型工作专班办公室印发，旨在加快当地新能源项目建设并确保按期并网。","scd":null,"kp":["新能源项目建设[山西吕梁]: 加快推进并确保按期并网"]},{"i":3247,"as":"上能电气与深圳库博能源正式签署4GW储能变流器（PCS）战略合作协议。上能电气依托高可靠设备和第二代增强混动构网技术，满足欧洲市场对度电成本与并网稳定性的严苛要求。此次合作旨在抓住欧洲因可再生能源渗透率高和电网灵活性不足而激增的储能需求，加速上能电气在全球工商业及大型储能市场的海外拓展。","scd":null,"kp":["协议容量[上能电气与库博能源储能PCS战略合作]: 4GW","核心技术[欧洲工商业及大型储能]: 第二代增强混动构网技术"]},{"i":3248,"as":"北京虹桥新疆米东区200万千瓦光伏项目（一标段50万千瓦，即500MW）EPC工程总承包开标时间延期至7月15日。该项目建设内容包含光伏阵列基础、逆变器及箱变安装等。招标业绩要求投标人近三年需具备不少于2项100MWp及以上的光伏EPC类似业绩。","scd":null,"kp":["项目总规划[北京虹桥新疆米东区光伏]: 200万千瓦","一标段容量[当前EPC招标]: 50万千瓦","开标时间[原定7月1日]: 延期至7月15日","业绩要求[投标人]: 近三年100MWp及以上光伏EPC类似业绩不少于2项"]},{"i":3249,"as":"湖北麻城能源集团300兆瓦光伏项目实现全容量并网，包含220兆瓦屋顶光伏和82兆瓦光伏扶贫电站。集团以大别山电厂为核心构建“源网荷储一体化”体系，业务由单一光伏向热电联产、充换电网络、农光互补等综合能源服务延伸。集团力争到2026年新能源发电占比超30%，年减排二氧化碳100万吨以上。","scd":null,"kp":["并网容量[麻城能源集团光伏项目]: 300兆瓦","屋顶光伏装机[麻城最大屋顶项目]: 220兆瓦","扶贫电站装机[光伏扶贫电站]: 82兆瓦","扶贫收益分配[全市重点脱贫村]: 137个"]},{"i":3250,"as":"工信部公示8项光伏行业标准立项计划，其中6项为钙钛矿标准，由隆基、协鑫等企业牵头制定。标准涵盖钙钛矿-晶硅叠层电池的温度循环衰减与湿热致衰减测试方法。由于现有基于晶硅的IEC标准无法准确评估钙钛矿特有的离子迁移、相变等退化机制，新标准将规范特定测试条件，为钙钛矿材料的可靠性优化与商业化量产提供统一标尺。","scd":null,"kp":["标准立项[工信部光伏行业标准公示]: 6项钙钛矿标准","核心痛点[现有IEC 61215-2标准]: 未涵盖钙钛矿可逆相变、离子迁移及界面接触电阻演变机制，无法准确评估叠层组件长期耐久性"]},{"i":3251,"as":"重庆华电潼南300MW复合光伏发电项目开工，总投资约13.29亿元。项目分为古溪、米心、玉溪三个子项目，统一采用461539块单晶650Wp双面光伏组件，新建一座220kV汇集站并网。投产后年均发电量可达2.55亿千瓦时，每年可节约标准煤7.65万吨，减少二氧化碳排放19.89万吨。","scd":null,"kp":["总装机规模[重庆华电潼南复合光伏项目]: 30万千瓦","项目总投资[重庆华电潼南复合光伏项目]: 13.29亿元","光伏组件[全场统一采用]: 单晶650Wp双面组件461539块","年均发电量[项目投产后]: 2.55亿千瓦时","减排效益[年均]: 减少二氧化碳排放19.89万吨"]},{"i":3252,"as":"云南楚雄州大地基光伏发电项目因无市场主体报名，重新开展市场化竞争性配置以优选投资主体。该项目建设地点位于楚雄市，装机容量为6.5万千瓦（65MW）。参与配置的企业需具备独立法人资格，且无严重违法失信记录及重大安全质量事故。","scd":null,"kp":["项目状态[楚雄州大地基光伏发电项目]: 因无主体报名重新开展市场化竞争性配置"]},{"i":3253,"as":"河南发布《电力中长期市场实施细则》，规范市场成员及交易行为。直接参与市场交易的经营主体不再人为规定分时电价水平，由市场交易形成。为防止市场操纵，政府对申报及出清价格设置上下限，并逐步推动省内中长期交易限价与现货交易限价贴近。细则涵盖年、月、日内等多时间维度的中长期交易，统筹推进中长期与现货市场建设。","scd":null,"kp":["分时电价机制[直接参与市场交易的经营主体]: 不再人为规定，由市场交易形成","价格限制[经营主体申报与出清价格]: 设置上下限以防操纵及恶性竞争"]},{"i":3254,"as":"内蒙古鄂尔多斯市就《新能源发展促进条例(草案)》征求意见。条例明确建立项目竞争性配置机制，严禁圈占资源；支持风光基地建设及“新能源+生态修复”等复合项目；鼓励分布式新能源在零碳场景及乡村振兴中的应用。氢能领域，支持风光制氢技术研发，推广氢燃料电池重卡，推动绿氢与化工产业融合，发展绿氢制甲醇、合成氨及氢冶金产业。","scd":null,"kp":["[新能源项目开发建设]: 建立竞争性配置优选机制，严禁圈占资源与倒卖项目","[新能源应用场景]: 支持沙漠/戈壁/荒漠风光基地及农光/林光/牧光互补等复合利用","[氢能产业布局]: 推动风光制氢及绿氢在交通（重卡）、化工（甲醇/合成氨/冶金）领域的融合应用"]},{"i":3255,"as":"安徽青阳县发布分布式光伏建设新规，明确项目备案主体和支持建设范围。新规严格规定6类情形严禁建设分布式光伏，包括火灾危险性高的建筑物、不符合安全条件的场所、历史文化保护建筑、地质灾害易发区、拟拆迁区域，以及用地红线范围内无建筑物的场所。支持在合法宅基地及工商业建筑红线内建设。","scd":null,"kp":["[分布式光伏项目备案]: 非自然人户用在满足主体、机关相同且明确建设规模时可合并备案","[分布式光伏禁建场所]: 火灾高危建筑、不符合安全条件场所、历史文化保护建筑、地质灾害易发区、拟拆迁区及用地红线内无建筑物的区域"]},{"i":3256,"as":"","scd":null,"kp":[]},{"i":3257,"as":"","scd":null,"kp":[]},{"i":3258,"as":"","scd":null,"kp":[]},{"i":3259,"as":"华为宣布全球首个商用多模态文旅大模型“博观文旅大模型”在西安规模化应用。该模型基于超1.2PB高质量数据集与昇腾算力底座打造，涵盖海量图文、音视频及文本，可精准生成博物馆级文物内容。其支撑的AI伴游智能体已覆盖超400万用户。此外，华为与电信在大唐不夜城部署5G-A网络，峰值速率达3.5Gbps，支持约2.3万用户同时接入。","scd":null,"kp":["AI伴游智能体[西安博观文旅大模型]: 覆盖超400万用户","高质量数据集[多模态大模型]: 资料总量突破1.2PB，包含3100万张图片、440万分钟影像等","[5G-A网络部署]: 基于三载波聚合部署，上下行峰值速率分别可达600Mbps与3.5Gbps"]},{"i":3260,"as":"","scd":null,"kp":[]},{"i":3261,"as":"鸿蒙智行确认将坚持智界R7的IP，并以年度款的形式持续进行产品迭代。智界R7是华为与奇瑞联手打造的首款轿跑SUV，采用OneBox设计，拥有同级最大内部空间。目前，智界R7和S7车型累计交付量已突破16万台。今年3月，智界R7焕新发布，配备全新激光雷达与健康座舱，起售价为25.98万元。","scd":null,"kp":["内部空间[2024年轿跑SUV]: 采用OneBox设计理念具备同级别最大空间","[智界R7和S7车型]: 累计交付量突破16万台","售价[智界R7/S7焕新版]: 25.98万元 / 23.98万元起","激光雷达[智界双7车型配置]: 全新896线双光路图像级"]},{"i":3262,"as":"受谷歌等投资的初创企业Apptronik在奥斯汀建立了一座占地约8361平方米的“机器人实训园”，为旗下Apollo人形机器人提供数据训练。机器人通过人员远程操控完成分拣等实操任务，采集数据用于优化AI大脑，以解决现实场景训练数据不足的难题。该公司累计融资约10亿美元，致力于打造通用型人形机器人并推向工厂及家庭应用。","scd":null,"kp":["占地面积[Apptronik机器人实训园]: 近9万平方英尺（约8361平方米）","[人形机器人研发数据生成机制]: 由人员远程操控机器人在实训园反复实操，采集数据用于优化AI模型","[人形机器人落地核心瓶颈]: 现实场景训练数据严重不足"]},{"i":3263,"as":"比亚迪海豹08海洋网旗舰轿车宣布将于7月2日上市。新车提供纯电和插混两种动力，均标配闪充技术。车身尺寸为5150×1990×1505mm，轴距3030mm。车辆集后轮转向与第二代刀片电池于一身，纯电版基于800V高压平台，插混版搭载DM-i系统。内饰配备前排双零重力座椅及全车座椅通风加热按摩，并提供多种内外饰配色选择。","scd":null,"kp":["动力系统[海豹08车型]: 标配闪充，提供纯电与插混两种动力","车身尺寸[海豹08车型]: 5150×1999×1505mm，轴距3030mm","高压平台[海豹08纯电版]: 800V","发动机最大功率[海豹08插混版]: 115千瓦","电池技术[海豹08车型]: 搭载第二代刀片电池"]},{"i":3264,"as":"中昊芯英发布全自研高性能TPPU芯片“须臾”及智算底座“泰则2.0”。须臾单芯片混合精度浮点算力达896TFLOPS，8-bit推理算力达1792TOPS，单卡功耗600W，较传统芯片降低50%，且软硬件均为自主研发。泰则2.0搭载8片TPU，算力达7.168P，兼容全主流AI框架，已完成数十款大模型深度适配，助力低碳智算中心建设。","scd":null,"kp":["单芯片混合精度浮点算力[中昊芯英须臾TPU]: 896 TFLOPS","8-bit推理算力[须臾TPU]: 1792 TOPS","单卡额定功耗[须臾TPU]: 600W，相比传统算力芯片降低50%","整机能耗[泰则2.0智算平台]: 同等任务下仅为传统GPU服务器的80%","算力[泰则2.0智算平台]: 7.168P（混合精度）"]},{"i":3265,"as":"","scd":null,"kp":[]},{"i":3266,"as":"据报道，OpenAI工程师透露，公司通过一系列系统底层优化，成功将AI模型的推理成本降低了50%以上。此次降本主要归功于提升现有服务器资源利用率，而非增加新的计算芯片。这一优化减少了运行AI系统所需的英伟达芯片数量，节省的计算成本将用于降低API定价或提升用户使用限额。","scd":null,"kp":[]},{"i":3267,"as":"","scd":null,"kp":[]},{"i":3268,"as":"","scd":null,"kp":[]},{"i":3269,"as":"Punkt. MC03手机在海外发售，定价745欧元。该机号称“德国制造”，核心主打隐私保护，搭载基于石墨烯OS的AphyOS系统，第三方应用均在独立隔离环境运行。硬件方面，配备天玑7300芯片、6.67英寸OLED屏、6400万像素主摄及5200mAh电池。厂商取消了此前要求的强制订阅制度，承诺提供5年安全补丁更新。","scd":null,"kp":["处理器[Punkt. MC03手机]: 联发科天玑7300芯片","屏幕配置[Punkt. MC03手机]: 6.67英寸OLED屏，2436*1080分辨率，支持120Hz高刷","最高亮度[Punkt. MC03屏幕]: 550尼特","内存与存储[Punkt. MC03手机]: 8GB内存，256GB存储并支持microSD扩展"]},{"i":3270,"as":"美光科技宣布投入2.5亿美元，通过“特朗普账户”为美国儿童与家庭提供长期储蓄支持。美光将推出员工配套补助和社区专项福利，为其设有业务布局的7个州内符合条件的儿童一次性存入250美元启动资金，并提供员工子女高额配套补贴。该项目预计惠及100万名儿童，与美光此前2000亿美元的本土芯片制造投资形成互补。","scd":null,"kp":["投资规模[美光科技长期储蓄项目]: 2.5亿美元","[美国本土存储芯片制造及研发]: 投资超2000亿美元，预计创造超9万个就业岗位"]},{"i":3271,"as":"为应对下一波高温热浪，法国政府为医院紧急采购的3万台空调将在未来几天送达。法国近期经历近80年来最高温，本轮高温已造成超1000例超额死亡。受气候历史、建筑条件及环保政策影响，法国住宅空调安装率仅约18%至26%。与此同时，受极端高温天气影响，中国制造的移动空调等纳凉产品在欧洲销量激增。","scd":null,"kp":["空调采购量[法国医院应对高温]: 3万台","空调安装率[法国住户]: 约18%至26%"]},{"i":3272,"as":"联想旗下摩托罗拉推出moto tag 2蓝牙追踪器，售价29.99美元。该产品单颗电池续航最长可超过500天，支持UWB及Bluetooth Channel Sounding技术，并兼容谷歌Find Hub网络，提供精准定位寻物。此外，摩托罗拉还为moto buds 2 plus耳机新增了镶嵌施华洛世奇水晶的配色，定价149美元起。","scd":null,"kp":["续航能力[单颗电池]: >500天","搭载技术[定位追踪]: UWB、Bluetooth Channel Sounding","兼容网络[寻物体验]: 谷歌Find Hub","产品定价[基础版本]: 29.99美元"]},{"i":3273,"as":"鸿蒙智行首款旗舰MPV智界V9于5月15日上市，售价区间38.98万至51.98万元。据执行董事赵长江透露，该车6月交付量已超5000台。上市21天大定订单突破18000台，其中Ultra以上版本占比超80%，成交均价达50万元。车身尺寸为5359×2009×1879mm，轴距3250mm。全系标配38个传感器，是行业首款搭载896线激光雷达的MPV，并提供多种内外饰配色选择。","scd":null,"kp":["交付量[6月份智界V9]: >5000台","大定订单[上市21天]: >18000台","高配比例[Ultra以上版本]: >80%","成交均价[智界V9车型]: 50万元","车身尺寸[智界V9车型]: 5359×2009×1879mm"]},{"i":3274,"as":"","scd":null,"kp":[]},{"i":3275,"as":"","scd":null,"kp":[]},{"i":3276,"as":"中国两项强制性的电动汽车及动力电池安全新标准于7月1日正式生效，大幅提高了安全要求。新标准包括《电动汽车用动力蓄电池安全要求》（GB 38031-2025）和《电动汽车安全要求》（GB 18384-2025），分别针对电池系统和整车层面制定规范。其中最核心的新要求是，即使在发生热失控的情况下，电池系统也绝不能起火或爆炸。","scd":null,"kp":["安全要求[电池系统]: 不得存在起火或爆炸风险","执行时间[强制性安全标准]: 2026年7月1日","适用标准[牵引电池]: GB 38031-2025","适用标准[电动汽车]: GB 18384-2025"]},{"i":3277,"as":"中国电池制造商宁德时代（CATL）在停产近一年后，恢复了其江西锂矿的运营。该矿区拥有全球最大的锂云母储量之一，宁德时代在当地设有炼油厂，可直接将其加工成电池级碳酸锂。去年8月牌照到期后，中国政府为缓解锂市场库存过高及价格暴跌的压力，曾拒绝为其续签采矿许可证。如今该矿已恢复生产作业。","scd":null,"kp":["[宁德时代江西锂矿]: 停产近一年后恢复运营","矿产储量[尖石窝矿床]: 全球最大锂云母储量之一","加工工艺[现场加工]: 现场提炼电池级碳酸锂"]},{"i":3278,"as":"","scd":null,"kp":[]},{"i":3279,"as":"全球供应链风险管理和供应商预审公司Achilles推出了一项由人工智能驱动的风险筛查功能。面对关税波动、海运咽喉要道受阻和网络攻击等宏观挑战，这项新技术旨在帮助采购和供应链高管识别并应对隐藏在供应商网络中的潜在风险。该工具的推出是为了让企业在全球化供应链日益脆弱的环境下，能够更广泛地预见风险并确保业务的无缝运行。","scd":null,"kp":["系统功能[供应链风险]: AI驱动的供应商网络隐形风险筛查"]},{"i":3280,"as":"","scd":null,"kp":[]},{"i":3281,"as":"现代汽车在美国创下有史以来最高的第二季度和上半年销量纪录。2026年上半年，现代汽车在美国共售出450,568辆汽车，同比增长3%。其中电气化车辆（含纯电动和混动）占总销量的33%。第二季度混动车型销量创下新纪录，大幅增长71%。纯电车型方面，IONIQ 5上半年销量超过20,000辆，而三排座纯电SUV IONIQ 9的销量则大幅增长了380%。","scd":null,"kp":["销量[2026上半年IONIQ 5]: >20000辆","销量增幅[2026上半年IONIQ 9]: 380%","总销量[2026上半年美国市场]: 450568辆"]},{"i":3282,"as":"起亚为其热门SUV车型Sportage和EV5推出了全新的特别版“Storm”版本。作为比GT-Line更便宜的替代选择，Storm版本保留了标准Air车型的配置与性能。起亚EV5 Storm配备了与其它版本相同的81.4 kWh电池组和前轮驱动系统。外观设计上融合了Air和GT-Line的特点，配备车身同色门把手和黑色高光细节。此外，该版本还增加了19英寸合金轮毂、后排隐私玻璃以及电动自动防眩目等配置。","scd":null,"kp":["电池容量[起亚EV5 Storm版]: 81.4 kWh","[Storm特别版]: 提供全轮驱动系统，作为低于GT-Line的廉价替代方案"]},{"i":3283,"as":"越来越多的特斯拉Cybertruck车主因动力转换系统（PCS）故障而失去家用充电能力。PCS集成了车载充电器和DC-DC转换器，该部件损坏会导致车辆无法进行Level 2交流家用充电。特斯拉目前已获悉此问题，并采取逐案 quietly 更换零件的方式处理。然而，特斯拉并未发布官方召回，车主往往需要等待数周才能获得替换部件，且无法自行采购。","scd":null,"kp":["故障影响[动力转换系统(PCS)]: 导致车辆失去AC充电及将高压降至48V的能力","应对措施[特斯拉Cybertruck]: 未发布召回，采取个案悄悄更换零件"]},{"i":3284,"as":"2026年第二季度，比亚迪纯电动汽车交付量达到557,090辆，再次超越特斯拉，重回全球纯电销量榜首。据彭博社汇编数据，特斯拉同期预计交付约396,500辆，两者差距超过16万辆。这一结果扭转了2026年第一季度特斯拉因中国取消电动车购置税免税政策而短暂领先的局势。今年第一季度，特斯拉仅交付358,023辆，并生产了超5万辆未能售出的汽车。","scd":null,"kp":["纯电交付量[比亚迪2026年第二季度]: 557090辆","纯电交付量[特斯拉2026年第二季度预期]: 约396500辆"]},{"i":3285,"as":"加拿大电动汽车家庭充电用户现可通过兼容的家用充电桩获得资金返还。总部位于多伦多的充电桩管理软件公司ChargeLab宣布，将其ChargeLab Rewards奖励计划中针对加拿大独立住宅业主的回报提高至每千瓦时10美分。该计划立即生效，无支付层级或最低支付门槛限制，按季度支付，成为加拿大针对房主回报最高的碳信用计划。按每年平均家庭充电3500千瓦时计算，参与者平均每年可获得超过350加元的收益。","scd":null,"kp":["奖励补贴[加拿大家庭充电]: 每度电0.10加元","预计最高年收益[单户家庭住宅车主]: 350加元"]},{"i":3286,"as":"全球投资公司KKR已同意从法国国有公用事业巨头EDF集团收购EDF Power Solutions的北美综合业务及资产。该交易股权价值约为42亿美元，另有3.9亿美元作为基于业绩的潜在额外收益。这是KKR迄今为止在可再生能源领域最大的一笔单笔投资，资金来源于其全球基础设施战略。EDF Power Solutions在北美是一家排名前十的可再生能源开发商。","scd":null,"kp":["收购金额[KKR收购EDF北美业务]: 42亿美元"]},{"i":3287,"as":"北美太阳能支架制造商Opsun Systems推出了名为SunRail Inverter Rack的新型商用平屋顶逆变器货架系统。该铝制结构专为商业和工业（C&I）屋顶设计，旨在将组串式逆变器直接与屋顶光伏阵列安装在一起，消除以往在现场非标拼凑安装重型逆变器的做法。系统的结构工程特性经过优化，能够承受恶劣的环境载荷，目前已立即上市发售。","scd":null,"kp":["[商用平屋顶系统]: 专用于支撑并容纳组串式逆变器以消除非标准化现场即兴操作的SunRail逆变器支架方案"]},{"i":3288,"as":"意大利二氧化碳电池开发商Energy Dome与谷歌扩大合作，将在爱尔兰建设一座23 MW/200 MWh的电池储能系统（BESS）。该项目基于Energy Dome专有的二氧化碳储能技术，利用电网电力压缩和储存二氧化碳，在需要时释放能量。该项目已获得土地、规划许可和电网连接，并获得了一份为期10年的容量合同，预计将于2028年投入运营。","scd":null,"kp":["储能容量[爱尔兰碳电池项目]: 23 MW/200 MWh","[项目状态]: 已获得土地、规划许可、电网连接及10年容量合同，预计2028年并网"]},{"i":3289,"as":"根据苏格兰政府公布的数据，截至2026年第一季度末，苏格兰累计太阳能装机容量达到0.9吉瓦，较2025年同期增加0.1吉瓦。其总可再生能源装机容量达到18.1吉瓦，同比增长3.2%。其中，陆上风电占据最大份额，达10.7吉瓦。此外，截至三月底，苏格兰的储能容量已超过1.5吉瓦。目前苏格兰还有0.2吉瓦的太阳能和3吉瓦的电池储能项目正在建设中。","scd":null,"kp":["累计装机容量[苏格兰太阳能(至2026年Q1)]: 0.9 GW","储能容量[苏格兰(至3月底)]: 超过 1.5 GW","在建项目容量[苏格兰]: 0.2 GW太阳能与3 GW电池储能"]},{"i":3290,"as":"2026年6月下旬的持续热浪导致法国气温飙升至42.5摄氏度，迫使法国削减了依靠河流冷却的核反应堆的发电量。由于罗纳河、加伦河和塞纳河的水温逼近热极限，法国在下午时段向邻国出口的核电盈余从11-12吉瓦骤降至不到3吉瓦。这一事件凸显了河流温度上升对法国核电产出构成的持续性制约，削弱了其作为电力出口缓冲的能力。","scd":null,"kp":["电力出口降幅[法国高温期间核反应堆减产]: 下午出口盈余从11-12 GW降至3 GW以内","[核心技术限制]: 河流升温逼近热极限迫使河流冷却核反应堆削减输出功率"]},{"i":3291,"as":"西班牙最大的绿色氢设施已开始测试。这座位于卡斯特利翁炼油厂的25兆瓦（MW）设施通过购电协议（PPA）使用可再生电力，预计每年可生产约2800吨符合欧盟非生物来源可再生燃料（RFNBO）标准的绿氢，用于替代灰氢。该项目采用水电解技术，预计将在今年年底前开始生产绿氢，并将在2026年成为西班牙最大的运营绿氢设施，助力将厂区转型为综合能源枢纽。","scd":null,"kp":["设施功率[西班牙最大绿色氢设施]: 25 MW","绿氢年产量[西班牙最大绿色氢设施]: 约2800吨"]},{"i":3292,"as":"SolaX Power在2026年欧洲国际太阳能展上推出了Binary系列车辆到家庭（V2H）系统，为住宅太阳能和储能应用提供了一种交流侧双向充电解决方案。该系统架构将交流充电与受控的直流放电分离，允许电动汽车充电桩与逆变器之间最远相距50米进行安装。该系统可使兼容的电动汽车利用太阳能或电网充电，并在需要时将电能反向放电供家庭使用。","scd":null,"kp":["设备间距极限[交流侧V2H系统架构分离]: 允许电动汽车充电器与逆变器安装距离达50米","[V2H系统架构]: 交流充电与受控直流放电分离架构"]},{"i":3293,"as":"德国亥姆霍兹柏林中心和洪堡大学的研究人员实现了钙钛矿-CIGS串联太阳能电池25.5%的光电转换效率世界纪录。该结果已获欧洲太阳能测试装置(ESTI)确认。现有电池架构的内部测试表明，其效率未来可达到27.5%。","scd":null,"kp":["转换效率[钙钛矿-CIGS串联太阳能电池]: 25.5%"]},{"i":3294,"as":"德国能源公司RWE和希腊公用事业公司PPC已完成希腊北部三个大型太阳能集群的建设，总装机容量达930兆瓦。该项目包含九个太阳能发电场，均位于希腊北部西马其顿的露天褐煤矿旧址内，由双方的合资企业开发、建设和运营。此外，双方正在该地区推进两个总容量为567兆瓦的新项目，计划于明年投入使用。","scd":null,"kp":["集群总容量[RWE与PPC希腊太阳能项目]: 930 MW","在建项目容量[希腊后续两个太阳能项目]: 567 MW"]},{"i":3295,"as":"瑞典梅拉达伦大学的研究人员在2024年生长季研究了垂直农业光伏系统对燕麦产量的影响。通过与传统地面安装和露天开放环境进行对比，结果表明，燕麦在农业光伏系统下的生长表现总体更优，突显了垂直光伏系统在实现土地高效双重利用方面的实际生产价值。","scd":null,"kp":["作物表现[垂直农业光伏系统下的燕麦生产]: 总体高于传统地面安装及露天种植条件"]},{"i":3296,"as":"美国新墨西哥州铀浓缩公司设施的第五个铀浓缩级联已投入商业运营。该设施升级项目于去年启动，目前的建设重点是到明年初增加70万个分离功单位的年产能。3月份，计划新建的八个级联中的第四个已开始生产低浓缩铀。该持续扩建项目计划到2027年初完成新增产能建设，以强化其作为美国公用事业国内可靠供应商的地位。","scd":null,"kp":["产能扩增目标[铀浓缩设施升级]: 新增70万分离功单位(SWU)/年","项目状态[新墨西哥Urenco USA工厂]: 第五条铀浓缩级联已投入商业运营"]},{"i":3297,"as":"波兰华沙大学物理系的科学家在层状二维材料ZnPS3中观察到了单光子发射现象。这项研究成果为在量子信息科学中应用低维材料奠定了关键基础。量子计算机在规模化商业应用后，将具备远超现有超级计算机的运算能力，而此次发现为相关量子计算技术的发展提供了材料层面的支持。","scd":null,"kp":["单光子发射源[二维材料]: 层状二维材料ZnPS3","技术突破[量子信息科学]: 实现了低维材料单光子发射的观察与应用进展"]},{"i":3298,"as":"英国TAE Power Solutions公司向美国MARA Holdings交付了其首个聚变衍生混合储能原型系统。该系统融合了电池、超级电容器和智能控制器，能够同时满足持续稳定的能源需求和突发的电力峰值。系统将立即在MARA的比特币采矿场进行安装和实际运行环境测试，标志着该混合储能技术正式从研发阶段迈入实际应用部署。","scd":null,"kp":["系统架构[聚变衍生混合储能系统]: 融合电池、超级电容器与智能控制技术","应用部署[混合储能原型系统]: 首次实现在真实数据中心运营场景的部署与测试"]},{"i":3299,"as":"普惠航空公司宣布，其F119发动机在为美国空军F-22猛禽战斗机提供动力的过程中，已正式突破100万发动机飞行小时的重要里程碑。作为全球首款第五代战斗机发动机，F119已服役超过20年，持续为战机提供隐身、超音速巡航和推力矢量等关键能力，确立了其作为第五代战斗机先驱发动机的地位。","scd":null,"kp":["累计飞行时间[F-22战斗机F119发动机]: 超过100万飞行小时","发动机属性[第五代战斗机动力]: 世界上首款第五代战斗机发动机"]},{"i":3300,"as":"美国威斯康星州麦迪逊市的私营部门首次成功将等离子体能量直接转化为可用电力。该试验利用威斯康星HTS轴对称磁镜装置完成，新开发的硬件在约100伏特的电势下提取了数安培的电流，输出功率足以点亮多个白炽灯泡。Realta Fusion公司宣布这一成果是磁镜聚变技术在商业电力开发领域的重大突破。","scd":null,"kp":["电势能[聚变等离子体直接转换电能实验]: 约100伏","电流[聚变等离子体直接转换电能实验]: 数安培","技术突破[私营部门聚变能转换]: 首次实现将聚变等离子体能量直接转化为可用电力"]},{"i":3301,"as":"美国伊利诺伊大学厄巴纳-香槟分校的科学家提出利用地下含水层作为天然热电池，以降低数据中心的冷却成本和电力消耗。含水层热能储存(ATES)系统利用地下水和井对进行抽水与注水，从而储存季节性热能。该系统作为一种大规模的天然热电池，能为人工智能数据中心提供低能耗、低碳排的冷却与供暖方案。数据中心总耗电量中有10%至40%用于冷却。","scd":null,"kp":["降温技术[数据中心冷却]: 含水层热能存储(ATES)系统","关键特征[含水层热电池]: 利用地下含水层作为巨型自然热电池以降低冷却电耗"]},{"i":3302,"as":"德克萨斯大学埃尔帕索分校(UTEP)的研究人员开发出一种全新的3D打印方法，能够将电池电解质打印成几乎任何形状，且性能与传统电池相当。传统液态电解质需密封在坚硬外壳中限制了形状，而该技术突破了这一限制。这项技术使未来为可穿戴设备、医疗植入物和航空航天等小型设备定制特定形状的电池成为可能。","scd":null,"kp":["制造工艺[电池制造]: 可打印几乎任意形状电池部件的3D打印方法","核心部件[3D打印电池]: 可打印且性能比肩传统电池的电解质"]},{"i":3303,"as":"美国联邦航空管理局(FAA)提出了一项提案，计划取消自1973年以来实施的陆上超音速飞行禁令。由于新一代飞机设计和降噪技术的发展，超音速客机可以在不产生巨大音爆的情况下突破音障。该提案一旦获批，非军用飞机将能够在满足未来噪音限制标准的前提下，飞越美国大陆上空进行超音速飞行。","scd":null,"kp":["监管动态[美国陆上超音速飞行]: FAA提议取消自1973年以来实施的超音速飞行禁令","技术使因[超音速飞行]: 新型飞机设计与降噪技术可避免巨大的音爆"]},{"i":3304,"as":"斯坦福医学的一项研究表明，通过简单的血液测试可以估算大脑、心脏等11个主要器官和系统的生物学年龄。人体器官衰老并非同步，每个器官都遵循自身的生物钟。研究发现，生物学年龄显得较“老”的器官与多年后较高的疾病发病风险存在直接关联，其中大脑年龄是预测未来疾病风险的重要指标之一。","scd":null,"kp":["检测目标[血液测试]: 估算特定器官的生物学年龄","技术特征[器官衰老评估]: 各器官具有独立的生物钟，可通过血液测试揭示各器官真实年龄并评估疾病风险"]},{"i":3305,"as":"","scd":null,"kp":[]},{"i":3306,"as":"维尔茨堡大学的科学家受撒哈拉沙漠沙鱼蜥蜴在沙中“游泳”的启发，开发出一种全新的火星车移动方案。细小松散的沙子经常导致火星车车轮打滑、下沉或受困，而沙鱼蜥蜴通过在沙子下方游动来移动。科学家解析了这种独特的地下移动机制，旨在研发出能够在沙地地形中更轻松自如移动的探测车。","scd":null,"kp":["移动方案[沙地环境火星车]: 模仿撒哈拉沙漠蜥蜴的移动方式","技术特点[火星车底盘与移动性]: 解决细小松散沙地导致的轮子打滑、沉陷或受困问题，提升沙地导航能力"]},{"i":3307,"as":"布法罗大学的科研人员提出了一种基于钻石的量子传感器技术，用于探测交变磁体。交变磁体是近期物理学界发现的一种新型磁性材料，其独特性质有望使未来的电子产品运行速度更快且能效更高。这项发表于《物理评论快报》的研究提出，利用钻石内部的微小缺陷，能够有效识别出交变磁体特有的磁性行为，解决这种新材料难以探测的问题。","scd":null,"kp":["探测传感器[交变磁体检测]: 金刚石量子传感器","[新型磁性材料]: 交变磁体（有望使未来电子产品运行更快且能效大幅提升）"]},{"i":3308,"as":"维也纳工业大学(TU Wien)的实验人员在一厘米大小的“奇异金属”晶体中首次发现了强烈的量子纠缠现象。量子行为通常在原子、光子等微小且高度隔离的系统中才容易被探测到。此次研究借助量子信息理论中的“量子费舍尔信息”精确工具，在由海量粒子组成的宏观大尺寸晶体中测量到了高水平的量子纠缠，建立了固体物理学与量子信息理论之间的新联系。","scd":null,"kp":["晶体尺寸[强量子纠缠观测]: 厘米级","材料体系[强量子纠缠观测]: 奇异金属晶体"]},{"i":3309,"as":"","scd":null,"kp":[]},{"i":3310,"as":"","scd":null,"kp":[]},{"i":3311,"as":"","scd":null,"kp":[]},{"i":3312,"as":"东北大学的研究人员揭示了新的催化剂设计原理，发现双原子催化剂的性能表现有别于以往认知。几十年来，科学界依赖“单一最佳平衡点”的经验法则来设计催化剂，而该研究发现了名为“双Sabatier最佳点”的全新模式，解释了双原子催化剂性能优于单原子催化剂的根本原因。这一发现打破了长期存在的催化科学框架，将加速降低氢燃料电池制造成本的进程。","scd":null,"kp":["[催化剂设计准则]: 长期认为的单点性能峰值模型在双原子催化剂中失效（推翻既往预测模型）","应用目标[氢燃料电池]: 降低成本并提升催化性能的双原子催化剂"]},{"i":3313,"as":"德克萨斯大学奥斯汀分校的工程师研发出一款创新的集水夹克，能够从空气中的水分提取饮用水。这项技术旨在为徒步旅行者、露营者、农场工人、急救人员和军事人员等长期处于缺乏清洁水源环境的人群提供饮水保障。该装置打破了传统空气集水设备多为固定式（如箱体或大吸附床）的局限，实现了便携式应用。","scd":null,"kp":["日均集水量[新型集水夹克]: 30盎司"]},{"i":3314,"as":"","scd":null,"kp":[]},{"i":3315,"as":"据报道，Meta 公司正在计划推进其人工智能（AI）云业务。","scd":null,"kp":[]},{"i":3316,"as":"微软正计划在多个业务部门进行大规模裁员，预计涉及数千名员工。此次裁员将主要影响公司的销售、工程以及 Xbox 游戏部门。","scd":null,"kp":[]},{"i":3317,"as":"在引发广泛争议之后，人工智能公司 Anthropic 撤回了其针对中国用户推出的间谍软件。","scd":null,"kp":[]},{"i":3318,"as":"芯片巨头英伟达（Nvidia）对安全科技公司 Verkada 进行了资金投资。","scd":null,"kp":[]},{"i":3319,"as":"Lime 公司宣布将其首次公开募股（IPO）的发行价格定为每股 25 美元。","scd":null,"kp":["IPO定价[Lime首次公开募股]: 每股25美元"]},{"i":3320,"as":"美团发布了一款全新的人工智能模型。值得注意的是，该模型完全使用中国制造的芯片进行训练。","scd":null,"kp":["硬件算力基础[新AI模型训练]: 完全采用中国芯片"]},{"i":3321,"as":"美国政府放宽了对人工智能公司 Anthropic 旗下寓言模型（Fable Model）的出口限制措施。","scd":null,"kp":[]},{"i":3322,"as":"施耐德电气已达成最终协议，同意以 31 亿美元的价格收购工业人工智能公司 Cognite。","scd":null,"kp":["收购金额[施耐德电气收购工业AI公司Cognite]: 31亿美元"]},{"i":3323,"as":"人工智能公司 Anthropic 开展了临床前药物试验，并发布了其最新的 Sonnet 5 人工智能模型。","scd":null,"kp":["研发活动[Anthropic底座大模型]: 开展临床前药物试验并推出Sonnet 5模型"]},{"i":3324,"as":"投资银行杰富瑞（Jefferies）聘请了前高盛员工 Alex Tingle，以任命其担任数字基础设施银行业务的全球主管。","scd":null,"kp":[]},{"i":3325,"as":"亚马逊云科技（AWS）宣布成立了一支前沿部署工程师（FDE）组织，以加强其技术服务与部署能力。","scd":null,"kp":["组织架构调整[Amazon Web Services]: 创建前沿部署工程师(FDE)组织"]},{"i":3326,"as":"","scd":null,"kp":[]},{"i":3327,"as":"大型语言模型（LLM）普遍存在陷入思维定势的缺陷，其生成的答案往往过于可预测且缺乏创造力，例如在要求生成1到10的随机数时极大概率会返回7。这种群体思维在头脑风暴等场景下表现不佳。为此，澳大利亚初创公司 Springboards 研发了一款名为 Flint 的新型 LLM，旨在生成更多样化的结果以解决该问题。","scd":null,"kp":["大模型行为特征[生成1至10之间的随机数]: 极大概率输出数字7","技术缺陷[主流大语言模型]: 陷入群体思维，表现出高度可预测性和创造性匮乏"]},{"i":3328,"as":"Leibniz-Institut für innovative Mikroelektronik (IHP) 与 Technical University of Applied Sciences Wildau (TH Wildau) 庆祝其联合实验室成立 20 周年。该联合实验室主要致力于将实践导向的学习与前瞻性的科学技术研究紧密结合，参与人员包括 Martin Regehly、Sigurd Schrader 等研究人员。","scd":null,"kp":[]},{"i":3329,"as":"勃兰登堡工业大学（BTU Cottbus-Senftenberg）的学生团队“Lausitz Dynamics”在世界上规模最大的能源效率竞赛之一——壳牌环保马拉松中荣获第一名。该团队在“原型氢燃料电池”类别中击败对手夺冠，展现了其在氢燃料电池与节能技术方面的卓越实力。","scd":null,"kp":[]},{"i":3330,"as":"咨询公司 Clean Horizon 更新了其欧洲电池储能收入潜力指数的方法论，以更真实地反映实际市场条件下的项目经济效益。新模型基于平均装机容量，考量了资产竞争、部署水平及辅助服务市场。波兰和意大利目前在欧洲电池储能收入排名中处于领先地位。","scd":null,"kp":["指数评估模型更新[欧洲BESS储能收入潜力预测]: 采用基于平均装机容量的模型以反映资产竞争和真实市场条件，取代此前假设每个电池均能捕获最高价值市场机会的模型"]},{"i":3331,"as":"碳电池开发商 Energy Dome 与谷歌扩大合作，将在爱尔兰建造一个 23 MW/200 MWh 的碳电池储能系统。该系统利用电网电力压缩并储存二氧化碳，在需要时通过涡轮膨胀发电。该技术不依赖锂等供应链紧张的矿物，且具备长时储能能力。该项目已获得土地、规划许可和电网连接。","scd":null,"kp":["储能项目规模[爱尔兰碳电池BESS]: 23 MW / 200 MWh","技术路线[Energy Dome专有碳储能技术]: 利用电网功率压缩并储存碳，在需要时通过涡轮膨胀做功来发电","商业合作状态[Google与Energy Dome]: 签署商业合同以在爱尔兰共同开发可再生能源存储基础设施"]},{"i":3332,"as":"匈牙利 Energiabörze 集团完成了总容量为 2.996 MW/4.771 MWh 的锂离子电池储能项目。该项目分布在 Almásfüzitő（2 MW/2.4 MWh）和 Cibakháza（0.996 MW/2.371 MWh）两个站点，总投资 12.74 亿匈牙利福林（约 408 万美元），其中包含欧盟复苏与韧性设施的不可退还拨款。系统旨在支持匈牙利国家电网整合依赖天气的可再生能源。","scd":null,"kp":["储能规模[匈牙利锂电池项目]: 2.996 MW/4.771 MWh","项目总投资[Energiabörze储能项目]: 408万美元","系统配置[Almásfüzitő站点]: 2 MW/2.4 MWh","系统配置[Cibakháza站点]: 0.996 MW/2.371 MWh"]},{"i":3333,"as":"Greenvolt与比亚迪能源签署协议，为波兰Siedlce电池储能项目（BESS）供应比亚迪Haohan电池系统。该项目规模达600兆瓦/2.4吉瓦时，将成为波兰及欧洲最大的储能项目之一。项目已通过波兰容量市场机制获得收入，计划于2026年三季度开工建设，2027年底投入商业运营。","scd":null,"kp":["储能规模[波兰Siedlce项目]: 600 MW/2.4 GWh","电池系统[供应协议]: 比亚迪Haohan电池系统","商业运营时间[Siedlce项目]: 2027年底前"]},{"i":3334,"as":"约旦研究人员评估了采用构网型（GFM）控制的电池储能系统（BESS）在提升公用事业规模光伏电站稳定性方面的性能。GFM控制可模拟同步发电机，在电网中断、光伏波动、负荷变化及故障期间提供快速频率和电压支持。该研究系统验证了GFM-BESS在多种工况下增强系统频率稳定性、电压调节和韧性的能力。","scd":null,"kp":["[构网型(GFM)控制]: 模拟同步发电机，在电网停电、光伏波动、负荷变化和故障事件期间提供快速频率和电压支持","[应用场景]: 增强公用事业规模光伏发电的稳定性"]},{"i":3335,"as":"加州电池储能容量在六年内扩至17.4吉瓦。由于加州独立系统运营商（CAISO）对市场数据匿名处理，资产级财务表现难以追踪。电力优化公司Gridmatic发布报告，利用专有影子清算引擎重构了2.3吉瓦、30个BESS项目的表现。研究表明，地理位置和市场定价仅是收入的部分驱动力，运营执行和竞价策略造成了巨大的业绩差距。","scd":null,"kp":["储能容量[加州电网过去六年扩张]: 17.4 GW","[CAISO市场数据]: 匿名化公开市场数据掩盖了资源身份和资产级别的财务绩效跟踪"]},{"i":3336,"as":"西班牙可再生能源公司Grenergy签署了迄今规模最大的购电协议（PPA），将在15年内每年非太阳能时段向全球公用事业公司供应1太瓦时电力。合同于2026年生效，电力由智利Elena电池储能系统供应。Elena项目目前储能容量3.5吉瓦时，包含624个电池集装箱，规划扩建至7吉瓦时，是美洲最大的电池储能项目。","scd":null,"kp":["夜间供电量[智利Elena电池系统PPA协议]: 每年1 TWh","协议期限[夜间购电协议]: 15年","当前装机容量[Elena储能系统]: 3.5 GWh","规划扩建容量[Elena储能系统]: 7 GWh"]},{"i":3337,"as":"据澳大利亚能源市场运营商（AEMO）2026年综合系统计划，为实现最低成本的能源转型，到2050年澳大利亚总发电和储能容量需增至308吉瓦。其中，电网级风光容量需增至117吉瓦，分布式太阳能需增至87吉瓦。由电池、虚拟电厂和抽水蓄能组成的可调度储能容量需激增11倍，达到64吉瓦，以替代逐渐退出的煤电产能。","scd":null,"kp":["储能容量[2050年澳大利亚电力系统目标]: 64 GW","风光装机容量[澳大利亚2050年网侧目标]: 117 GW","总发配电容量[澳大利亚2050年目标]: 308 GW"]},{"i":3338,"as":"BW ESS在德国启动其首个电池储能项目Klostermansfeld的建设。该资产规模达1吉瓦/5.7吉瓦时，是德国最大的电池存储项目，位于萨克森-安哈尔特州。BW ESS于2026年初取得该项目全资所有权，项目预计于2028年投入商业运营。目前项目在没有外部融资的情况下推进建设。","scd":null,"kp":["储能规模[德国Klostermansfeld项目]: 1 GW/5.7 GWh","[项目状态]: 德国最大电池存储项目，预计2028年投入商业运营"]},{"i":3339,"as":"Amarenco在法国启动了100兆瓦的Osmo电池项目建设，提供两小时储能容量。该项目位于前工业用地，已与法国兴业银行达成融资关闭。电池系统将为电网运营商RTE提供多重服务，包括参与容量市场以应对冬季用电高峰，以及提供一次和二次备用服务以支持电网稳定。","scd":null,"kp":["储能规模[法国Osmo项目]: 100 MW","持续放电时间[Osmo电池系统]: 2小时","[系统服务]: 提供容量市场服务及一次和二次调频储备服务"]},{"i":3340,"as":"Fortescue与CMB.TECH正式签署了关于氨燃料船队的租赁协议。","scd":null,"kp":["[船舶动力]: 氨燃料船队","[商业协议]: 签署船队包机协议"]},{"i":3341,"as":"TÜV莱茵启动了一项创新的“H2-Ready（氢能就绪）”认证项目。","scd":null,"kp":["[项目状态]: 猎人谷氢中心获得最终投资决定(FID)","[认证项目]: TÜV Rheinland推出创新的‘H2-Ready’认证项目"]},{"i":3342,"as":"国家管网集团正式发布氢气管输工程技术方案与成套标准，涵盖新建氢气管道、天然气管道掺氢改造、接入交付及运维安全管理等全流程环节，填补了国内长距离大规模氢气管输成套技术与标准空白。该体系构建了首个氢气管输工程技术图谱，全面覆盖材料、设计、施工等核心流程，为氢气管道试点示范和规模化推广提供了权威规范与技术支撑。","scd":null,"kp":["[氢气管输工程]: 首次构建覆盖新建管道、在役天然气改输及掺氢的技术图谱与成套标准体系，填补长距离、规模化氢气管输技术与标准空白"]},{"i":3343,"as":"中煤科工联合多家单位成功研发国内首套煤矿专用地面压裂撬装装备。该装备采用模块化设计，最大排量15立方米/分钟，通过地面压裂技术对厚硬顶板进行全域超前管控，以防治煤矿强矿压等灾害。相较传统设备，其额定压力冗余削减70%，燃油能耗降低超20%，并具备远程一键启停功能。该技术已在蒙陕地区多个大型煤矿落地应用。","scd":null,"kp":["坚硬顶板岩层厚度[蒙陕地区煤层]: 30至100米","传统近场治理范围[井下爆破与短孔压裂]: 50米以内","最大作业排量[煤矿专用地面压裂撬装装备]: 15立方米/分钟","额定压力冗余[相较于传统油气压裂设备]: 削减70%以上"]},{"i":3344,"as":"国电南自自主研制的GE增强燃烧型PG9171E重型燃机控制系统（TCS）成功投运，实现该特种机型控制系统软硬件100%自主可控。研发团队重构了全套燃机控制与保护逻辑，自主研发CAN总线通讯模件实现阀门毫秒级精准控制。此举打破了国外技术垄断，打通了特种增强型9E燃机控制系统自主可控的技术路径。","scd":null,"kp":["自主可控率[GE增强燃烧型PG9171E重型燃机控制系统(TCS)]: 100%","通讯控制精度[自主研发CAN总线通讯模件阀门开度]: 毫秒级精准控制"]},{"i":3345,"as":"芬兰阿尔托大学领导的国际团队利用机器学习结合量子理论的新方法，成功筛选出两种具有“笼目晶格”特殊结构的新型超导材料。该方法通过机器学习预筛选大幅减少计算量，提升了材料发现效率。美国莱斯大学团队随后成功合成样品并验证其超导特性。这一完整研究流程为寻找室温超导体提供了全新高效的路径。","scd":null,"kp":["[新型超导材料发现]: 结合机器学习与量子理论，预筛选海量元素组合并精确分析锁定新型超导材料，大幅提升发现效率"]},{"i":3346,"as":"英国剑桥大学团队在户外真实阳光环境下，成功利用太阳能反应器将废塑料转化为清洁氢燃料和高价值化学品。新装置面积扩展至1平方米，通过在玻璃面板喷涂含钴和锆的催化剂驱动化学反应。该装置制造成本低，适用于PET等多种塑料，工艺简单且易于扩大规模，为该技术的商业化奠定基础。","scd":null,"kp":["[太阳能反应器光热转化机制]: 不发电，直接驱动光化学反应将塑料废物转化为氢气和高价值工业化学品","装置面积[户外真实环境测试太阳能反应器]: 约1平方米","[组装条件]: 太阳能面板可在室温下组装，无需专业设备"]},{"i":3347,"as":"我国自主研发的世界首套水下焊接原位中子衍射研究装置在中国散裂中子源投入使用。该装置由华南理工大学等团队联合研发，通过模拟海洋环境并采用重水替代清水，构建了具备强穿透能力的观测系统。该技术实现了对水下焊接过程微观结构动态变化的实时监测，打破了传统“焊后取样”黑箱模式，为水下结构物原位制造与运维质量提升提供科学支撑。","scd":null,"kp":["[水下焊接原位中子衍射研究装置]: 世界首套，改变传统水下“焊后取样”检测模式，实现对水下焊接微观结构演化与机理的实时原位观测"]},{"i":3348,"as":"","scd":null,"kp":[]},{"i":3349,"as":"国家税务总局数据显示，今年前5个月我国具身智能产业企业销售收入同比增长22.4%。其中，机器人整机制造、AI算法软件及系统集成领域增速均超24%，工业企业购进机器人金额同比增长2.3倍。产业高度集中在广东、北京、上海等地，其中广东凭借产业链优势，销售额占比达78.7%，稳居全国第一。","scd":null,"kp":["销售收入增长率[1-5月具身智能产业]: 22.4%","购进总金额同比增长[工业企业购进具身智能机器人]: 2.3倍(230%)","销售收入占比[具身智能产业对下游软件和信息技术服务业]: 25.5%","销售收入占比[具身智能产业对下游科学研究和技术服务业]: 12.7%","销售收入同比增长[机器人本体与整机制造]: 30.1%"]},{"i":3350,"as":"中国未来产业全面提速。具身智能领域，京津冀首个万台级超级工厂在北京投产，规划2030年年产50万台；上海体验馆及全球首店相继开业。低空经济领域，5吨级eVTOL完成转换飞行，货运无人机拿下全球首张境外适航证。此外，量子计算、脑机接口等前沿技术加速迭代，正将技术成果转化为实际生产力。","scd":null,"kp":["年产能规划[北京具身智能机器人超级工厂]: 2026年实现1万台套，2027年达到2万台套，2030年达到50万台套"]},{"i":3351,"as":"","scd":null,"kp":[]},{"i":3352,"as":"面对地面算力面临的电力扩容瓶颈、资源约束和散热难题，太空算力成为破局关键。太空算力将计算能力搬上卫星，利用取之不尽的太阳能供电，并在轨直接处理海量数据，大幅降低带宽占用并将响应时间压缩至秒级。中国已发射全球首个太空计算卫星星座，实现在轨运行与大模型推理，在太空算力领域稳居国际第一梯队。","scd":null,"kp":["在轨运行数量[中国计算卫星]: 12颗","[全球首个太空计算卫星星座]: 2025年5月14日发射升空","[太空算力核心特征]: 将计算能力部署于卫星，利用太空太阳能供电缓解电力焦虑，并在轨处理遥感与探测数据后仅回传结论以实现时效革命"]},{"i":3353,"as":"中国地质科学院地质研究所指出，研究小行星等天体有助于理解地球演化。小行星留存太阳系原始物质，被称为“时间胶囊”。我国行星科学已进入并跑甚至部分领跑阶段，通过嫦娥五号月壤揭示月球20亿年前存在火山活动，并重建撞击通量历史。在地外样品研究中，自主研发了分析能力国际领先的国产首台双聚焦SIMS。未来行星科学将侧重探索资源存在及探测利用，与传统地质研究交叉是其核心发展优势。","scd":null,"kp":["[我国行星科学发展阶段]: 整体进入并跑、部分领域领跑的快速发展新阶段"]},{"i":3354,"as":"国家税务总局数据显示，今年1-5月我国具身智能产业总体发展向好，销售收入实现22.4%的较快增速。细分领域中，机器人本体与整机制造、AI算法与软件集成、系统集成与行业应用企业增速均超24%。工业企业购进具身智能机器人总金额同比增长2.3倍，与工业生产融合加深。该产业赋能下游高技术服务业显著，全国近九成企业集中在广东、北京、上海、浙江和江苏，集群效应明显。","scd":null,"kp":["产业销售收入增速[具身智能产业今年1—5月]: 22.4%","细分领域销售收入增速[机器人本体与整机制造]: 30.1%","细分领域销售收入增速[AI算法与软件集成]: 24.5%","细分领域销售收入增速[系统集成与行业应用]: 27.9%","细分领域销售收入增速[核心零部件制造]: 6.8%"]},{"i":3355,"as":"工业和信息化部等八部门联合发布《关于推动工业互联网高质量发展的实施意见》。文件提出明确建设目标：到2030年，全国将建设5万张工业5G专网，打造约5个具有国际影响力的综合型平台，实现207个工业中类全覆盖，并推动核心产业增加值突破2.5万亿元。","scd":null,"kp":["建设目标[工业5G专网至2030年]: 5万张","建设目标[具有国际影响力的综合型平台至2030年]: 5个左右","覆盖率目标[工业中类融合应用至2030年]: 207个工业中类全覆盖","核心产业增加值目标[工业互联网核心产业至2030年]: 突破2.5万亿元"]},{"i":3356,"as":"根据工业和信息化部最新数据，截至5月末，全国移动电话用户总数达到18.41亿户。其中，5G移动电话用户数达到12.75亿户，占全国移动电话用户总数的69.3%。","scd":null,"kp":["用户总数[移动电话用户截至5月末]: 18.41亿户","用户数[5G移动电话用户截至5月末]: 12.75亿户","用户占比[5G移动电话用户占移动电话总数]: 69.3%"]},{"i":3357,"as":"罗马尼亚能源公司Electrica为其总容量为700兆瓦时（MWh）的电池储能系统（BESS）投资组合成功获得了电网批准。这标志着该储能项目在并网接入方面取得实质性进展。","scd":null,"kp":["BESS投资组合规模[罗马尼亚Electrica电网批准]: 700兆瓦时","[项目状态]: 获得电网批准"]},{"i":3358,"as":"可再生能源公司BSR获得了来自Eiffel的债务融资。此项资金将用于推进并支持BSR在英国和澳大利亚的太阳能光伏以及电池储能系统（BESS）资产的开发与建设。","scd":null,"kp":["[资产推进状态]: BSR获得埃菲尔债务融资以推进太阳能和BESS资产","[覆盖区域]: 英国和澳大利亚"]},{"i":3359,"as":"天津市发改委公示2026年风电、光伏发电开发建设方案项目，总规模达2.53GW，其中光伏1.22GW、风电1.31GW。华能、中绿发、国能投所获规模均超200MW；中国南水北调、华润电力等多家企业所获规模达100MW以上。项目经电力接入消纳评估和专家评审确定，公示期为2026年6月30日至7月6日。","scd":null,"kp":["总指标规模[天津市2026年风电、光伏开发建设方案]: 2.53GW","指标规模[光伏发电]: 1.22GW","指标规模[风电]: 1.31GW","获取规模[华能、中绿发、国能投]: 均达200MW以上","获取规模[中国南水北调、华润电力、天津能投、国电投、中电建等]: 达100MW以上"]},{"i":3360,"as":"四川省发改委发布新能源就近消纳价格政策，自2026年7月1日起实施。该项目指电源、负荷、储能整体接入用户侧，新能源年自发自用电量占比不低于60%，且占总用电量比例不低于30%（2030年起新增项目不低于35%）。政策要求项目按“谁受益、谁负担”原则承担输配电费等费用；未接入公共电网的项目无需缴纳相关保障费用。","scd":null,"kp":["[项目定义]: 电源、负荷、储能等作为整体与四川公共电网连接，形成清晰物理和安全责任界面、以新能源发电为主要电源","自发自用电量比例[新能源年自发自用电量占总可用发电量]: 不低于60%","自发自用电量比例[占总用电量比例]: 不低于30%","自发自用电量比例[2030年起新增项目占总用电量]: 不低于35%","[政策实施时间]: 2026年7月1日起实施"]},{"i":3361,"as":"光伏行业当前处于周期底部，市值大幅下跌。2026年1-5月国内光伏装机仅60GW，同比下降70%。随着产业链博弈，工商业及户用光伏装机开始回暖。《新型能源体系建设“十五五”规划》指出，到2030年我国风电和光伏装机预计超2800GW，同时新型储能装机将达300GW以保障新能源消纳，解决风光与储能失衡问题，为光伏行业发展提供支撑。","scd":null,"kp":["装机量[2026年1-5月国内光伏装机]: 60GW","装机量[去年同期国内光伏装机]: 198GW","装机量同比变化[2026年1-5月国内光伏装机]: 下降70%","投资规模[新型能源体系建设“十五五”规划能源重点项目和新业态]: 超过20万亿元","[行业趋势]: 工商业光伏和户用光伏装机开始明显回暖"]},{"i":3362,"as":"国家市场监督管理总局于2026年6月30日发布《关于发布电冰箱等173种产品质量监督抽查实施细则的公告》。细则明确包含了晶体硅光伏组件与光伏并网逆变器两种光伏核心产品。该细则自发布之日起实施，各地监管部门可直接采用，同时废止此前发布的同种产品细则。","scd":null,"kp":["[抽查范围]: 晶体硅光伏组件与光伏并网逆变器","[实施效力]: 自发布之日起实施，各地开展产品质量监督抽查时可直接采用"]},{"i":3363,"as":"国家能源局公布数据，2026年5月全国新增建档立卡新能源发电项目（不含户用光伏）共计6173个。其中，光伏发电项目新增6136个（含集中式39个，工商业6097个），风电项目新增27个，生物质发电项目新增10个。","scd":null,"kp":["项目总数[2026年5月全国新增建档立卡新能源发电项目]: 6173个","项目数[风电项目]: 27个","项目数[光伏发电项目]: 6136个","项目数[集中式光伏发电项目]: 39个","项目数[工商业光伏发电项目]: 6097个"]},{"i":3364,"as":"江苏2026年7月份电力集中竞价交易结果公示，总成交电量78.84亿千瓦时，加权均价为361.98元/兆瓦时。各电源类型成交情况为：火电成交75亿千瓦时（均价362.47元/兆瓦时），光伏成交0.1亿千瓦时（均价335.26元/兆瓦时，约合0.335元/度），风电成交0.39亿千瓦时，核电成交3.34亿千瓦时。购电侧由售电公司、一类用户及电网代理购电等组成。","scd":null,"kp":["加权均价[江苏2026年7月电力集中竞价]: 361.98元/兆瓦时","成交电量[本次交易]: 78.84亿千瓦时","加权均价[火电成交]: 362.47元/兆瓦时","成交电量[火电]: 75亿千瓦时","加权均价[风电成交]: 363.14元/兆瓦时"]},{"i":3365,"as":"新疆启动2027年度上半年增量新能源项目机制电价竞价。风电项目机制电量总规模79.84亿千瓦时，太阳能项目32.31亿千瓦时。单项目机制电量申报上限按容量乘以平均利用小时数（风电1880小时，太阳能1022小时）的50%计算。风电与太阳能分类竞价，申报电价区间均为0.150元/千瓦时至0.262元/千瓦时。","scd":null,"kp":["机制电量规模[2027年度上半年风电项目]: 79.84亿千瓦时","机制电量规模[2027年度上半年太阳能项目]: 32.31亿千瓦时","申报电量上限比例[风电/太阳能项目]: 50%","电价区间[风电与太阳能分类竞价]: 0.150元/千瓦时-0.262元/千瓦时"]},{"i":3366,"as":"内蒙古自治区能源局公示呼和浩特市和林格尔绿电园区增量配电网配电区域划分方案。该配电区域位于和林新区，供电面积约73.15平方公里。区域边界清晰、地块完整，严格按照园区总体规划划分，不存在电网交叉供电及重复建设问题，符合增量配电业务规划建设相关要求。","scd":null,"kp":["供电面积[和林格尔绿电园区增量配电网]: 约73.15平方公里"]},{"i":3367,"as":"广东省能源局公示首批存量地面集中式光伏竞争性配置评审结果，总规模1.7GW的15个项目中，最终13个项目共1.35GW获得指标。华电、华能、大唐集团所获规模均超200MW。评分细则重点关注参与中长期市场比例、配储比例及已支付资金比例。阳光新能源与中核集团因已支付资金比例评分较低未列入省级清单。","scd":null,"kp":["获批规模[广东存量地面集中式光伏首批竞争性配置]: 1.35GW"]},{"i":3368,"as":"奇瑞汽车发布犀牛电池安全保障计划，承诺其已售及在售车型动力电池均满足最新国标GB38031-2025。该标准将热失控要求提升至观察期内不起火不爆炸，并新增底部撞击与快充循环测试。奇瑞承诺因电池自身原因导致热失控损毁将赔付同款新车，并为非营运首任车主提供三电系统终身质保。","scd":null,"kp":["热失控要求[GB38031-2025动力电池新国标]: 不起火、不爆炸(至少2小时观察期内)","烟气侵入要求[新国标热失控报警]: 报警5分钟内烟气不进入乘员舱","底部撞击测试[新国标新增]: 30mm钢球以150J能量冲击3次不起火、不爆炸","快充循环安全[新国标新增]: 快充循环300次后外部短路不起火、不爆炸","质保方案[奇瑞犀牛电池非营运首任车主]: 终身质保(涵盖三电系统)"]},{"i":3369,"as":"TCL华星宣布独家供应小米REDMI K90至尊版手机屏幕。该屏幕核心优势为支持最高165Hz高刷新率，已完成40余款游戏165fps原生适配，支持1.5K分辨率与165fps并发运行。屏幕采用最新发光材质，峰值亮度达3500nits，并支持杜比视界和HDR Vivid等专业标准，兼顾电竞与影音体验。","scd":null,"kp":["最高刷新率[REDMI K90至尊版屏幕]: 165Hz","峰值亮度[REDMI K90至尊版屏幕]: 3500nits","并发运行[百款游戏支持]: 1.5K分辨率与165fps"]},{"i":3370,"as":"","scd":null,"kp":[]},{"i":3371,"as":"华为向MateBook 14鸿蒙版笔记本推送HarmonyOS 6.1.0.130 SP15升级。本次更新核心新增用户分级管理能力，提升多用户场景安全性；支持连接相机读取照片和视频。系统还针对文件管理、浏览器、扩展屏小艺输入法、截图拖拽、打印机连接等场景进行了体验优化和稳定性提升，并修复单应用音量配置失效等问题。","scd":null,"kp":["[HarmonyOS系统更新]: 新增用户分级管理能力，多用户使用场景更安全","[HarmonyOS系统更新]: 支持连接相机读取其中的照片和视频"]},{"i":3372,"as":"华为公布鸿蒙HarmonyOS 7花粉Beta版适配机型名单，涵盖Mate 70系列、Mate XTs、Pura X Max系列、nova 12系列、畅享70X以及多款MatePad系列平板产品。HarmonyOS 7开发者Beta 1公开招募报名周期截至2026年7月5日。此外，HarmonyOS 7正式版计划于秋季向消费者全面开放。","scd":null,"kp":[]},{"i":3373,"as":"","scd":null,"kp":[]},{"i":3374,"as":"全新坦克300官图发布，将于7月6日开启预售。新车尺寸升级为4886×1984×1927mm，轴距3010mm，配备激光雷达以强化智能辅助驾驶。动力方面全面转向新能源，提供Hi4-T和Hi4-Z两种选择。两款车型均搭载2.0T发动机，最大功率185kW，并匹配蜂巢能源三元锂电池。","scd":null,"kp":["整车尺寸[全新坦克300]: 4886×1984×1927mm","轴距[全新坦克300]: 3010mm","发动机最大功率[全新坦克300(2.0T排量)]: 185kW","电池类型[全新坦克300匹配]: 蜂巢能源三元锂电池"]},{"i":3375,"as":"","scd":null,"kp":[]},{"i":3376,"as":"OpenAI推出GeneBench-Pro基准测试，用于评估AI模型在真实生物学计算任务中的研究能力。测试包含129道题目，覆盖基因组学等10个大领域和21个子领域。每道题提供合成数据集及实验背景，要求模型独立完成数据探索、方法选择并得出结论。测试采用合成数据以避免多分析路径导致的评分偏差。OpenAI已在Hugging Face开源10道示例题。","scd":null,"kp":["题目总数[GeneBench-Pro基准测试]: 129道","覆盖领域[GeneBench-Pro基准测试]: 10个大领域和21个子领域","[GeneBench-Pro测试设计]: 采用合成数据避免评分偏差"]},{"i":3377,"as":"谷歌AI智能体Gemini Spark登陆Mac设备，目前仅限美国谷歌AI Ultra订阅会员使用。该工具整合进Gemini桌面客户端，可读取本地文件生成谷歌文档，并接入Google Tasks、Keep及多款第三方应用执行订餐、看房等任务。Spark新增实时资讯追踪与事件响应能力。后续将支持手机端下达多步骤指令调取Mac文件等跨设备联动功能。","scd":null,"kp":["应用平台[Gemini Spark]: macOS客户端","任务处理[Gemini Spark]: 支持读取本地文件、生成办公套件文档，后续支持远程及多步骤复合指令"]},{"i":3378,"as":"","scd":null,"kp":[]},{"i":3379,"as":"格科微发布公告称，其2亿像素CMOS图像传感器产品开发顺利，已与部分客户达成初步合作意向，但尚未实现出货。公司临港12英寸晶圆厂目前正专注主业工艺与产品研发。此前在今年3月，格科已推出两款0.8微米、5000万像素的CMOS图像传感器。","scd":null,"kp":["像素规格[CMOS图像传感器]: 2亿像素","光学尺寸与像素尺寸[CMOS图像传感器]: 1/2英寸，0.8μm","分辨率[CMOS图像传感器]: 5000万像素","量产状态[2亿像素产品]: 开发顺利，已达成初步合作意向，但尚未形成出货","晶圆规格[临港工厂产线]: 12英寸"]},{"i":3380,"as":"","scd":null,"kp":[]},{"i":3381,"as":"","scd":null,"kp":[]},{"i":3382,"as":"","scd":null,"kp":[]},{"i":3383,"as":"华能玉环电厂四期世界首台650℃高效超超临界燃煤发电机组进入攻坚阶段，主蒸汽压力达35兆帕。该项目采用自主知识产权高温合金新材料，实现关键高温材料自主可控。机组发电效率提升约5%，供电煤耗低于254g/kWh，全厂热效率达50.1%，每年可减少二氧化碳排放约45万吨。首件汽轮机部件与高温合金管已完成检验，标志我国全面掌握650℃高参数煤电核心高温材料生产技术。","scd":null,"kp":["蒸汽温度[燃煤发电机组]: 主蒸汽和再热蒸汽温度均达到650℃","蒸汽压力[燃煤发电机组]: 设计主蒸汽压力达到35兆帕","发电效率[650℃燃煤发电机组]: 与现有机组相比提升约5%","供电煤耗[650℃燃煤发电机组]: 低于254g/kWh","全厂热效率[650℃燃煤发电机组]: 达到50.1%"]},{"i":3384,"as":"","scd":null,"kp":[]},{"i":3385,"as":"","scd":null,"kp":[]},{"i":3386,"as":"","scd":null,"kp":[]},{"i":3387,"as":"","scd":null,"kp":[]},{"i":3388,"as":"宁德时代（CATL）为其服务于乘用车与轻型商用车的Choco SEB换电系统建成了2000座换电站。此外，宁德时代旗下骐骥换电系统已与极兔速递达成合作，将为后者部署5000辆重型电动换电卡车，在国内重卡换电市场取得重大进展。","scd":null,"kp":["换电站数量[Choco SEB系统]: 2000座","应用车型[Choco SEB系统]: 电动乘用车和轻型电动商用车","部署规模[Qiji Energy换电系统]: 5000辆CATL电池交换电动卡车"]},{"i":3389,"as":"联合国贸发会议发布报告指出，受全球清洁能源转型影响，预计到2040年全球锂需求将猛增超340%。清洁技术占锂需求的比例将从2024年的62%增至2040年的87%。报告称关键矿产贸易正处于十字路口，将深刻影响发展中国家的出口收入与市场结构。","scd":null,"kp":["需求增长预测[全球锂资源]: 到2040年将增长超过340%","需求占比预测[清洁技术锂需求]: 从2024年的62%上升至2040年的87%"]},{"i":3390,"as":"英国储能公司Eku Energy收购了位于德国下萨克森州的1.6GWh Dion电池储能项目，正式进入德国市场。该项目计划于2029年底投运，通过直接连接电网提供黑启动能力，增强区域电网断电时的恢复可靠性。项目开发方NION负责推进至待建阶段，Eku将主导开发、设计与技术，并与Fluence展开合作。","scd":null,"kp":["储能容量[Dion BESS项目]: 1.6GWh","系统功能[Dion BESS项目]: 提供黑启动能力，直连电网支持故障恢复"]},{"i":3391,"as":"受国内铅酸电池终端需求疲软及采购意愿低迷影响，部分中国精铅与合金冶炼厂面临成本压力，已削减或暂停生产。上海有色网数据显示，再生精铅产量环比微增2.2%，但较年初1月的28.2万吨峰值大幅下降超31%。第二季度再生铅冶炼周开工率持续低位徘徊。","scd":null,"kp":["生产状态[中国铅冶炼厂]: 因需求低迷和成本压力，部分精铅及合金冶炼厂已减产或停产"]},{"i":3392,"as":"宁德时代与艾伦·麦克阿瑟基金会联合发起一项国际联盟，推动电池全生命周期的可持续设计与商业投资。该联盟成员包括宝马、雷诺、沃尔沃、谷歌和小米。联盟旨在推广电池可持续设计指南，并出台相关支持政策与措施，加速确立循环商业模式为行业常态。","scd":null,"kp":["联盟成员[全球可持续电池联盟]: CATL、艾伦麦克阿瑟基金会、BMW、Renault、Volvo、Google、小米"]},{"i":3393,"as":"一项由印度储能联盟（IESA）和Customized Energy Solutions联合发布的研究显示，未来六年内印度工商业多化学储能系统总容量将激增30倍。预计累计装机容量将从2025年的不到1GWh，增长至2032年的23GWh至31GWh。该研究结果在第七届印度储能周上正式公布。","scd":null,"kp":["容量增长预测[印度工商业储能]: 预计六年内实现30倍增长","装机容量预测[印度工商业储能]: 累计装机量将从2025年不到1GWh增至2032年的23GWh-31GWh"]},{"i":3394,"as":"欧盟委员会正式对来自中国、沙特阿拉伯和美国的1,4-丁二醇（BDO）进口产品征收反倾销税。BDO是电动汽车和锂电池的关键前体材料。最终确定的反倾销税税率分别为：中国105.6%至113.7%，沙特阿拉伯52.4%，美国135.7%至142.5%。","scd":null,"kp":["征税对象[欧盟反倾销税]: 来自中国、沙特阿拉伯和美国的1,4-丁二醇(BDO)","材料用途[BDO]: 电动汽车、混合动力汽车和锂电池的关键前驱体"]},{"i":3395,"as":"剑桥大学主导的初步研究发现，将锂离子电动汽车电池保持在恒定的适当物理压力下，可使其使用寿命延长一倍。研究指出，压力必须处于被称为“金发姑娘区”的完美区间，过大或过小的压力均会导致电池失效。在电池成分微调通常仅带来5%-10%性能提升的背景下，这一幅度史无前例。","scd":null,"kp":["循环寿命[恒定物理压力条件下的锂离子电池]: 延长一倍","[物理压力施加区间]: 需处于恰好的“金发姑娘区间(Goldilocks zone)”，压力过大或过小均会导致电池失效"]},{"i":3396,"as":"双极性铅电池开发商SiliconJoule正式任命Jon Parke为运营总监。Parke在过去两年中一直担任该公司的战略顾问，此次全职加入将负责扩大电池组装和晶圆加工业务的规模。此次人事任命正值SiliconJoule推出旗舰产品GC2+并加速商业化进程，以满足全球日益增长的市场需求。","scd":null,"kp":[]},{"i":3397,"as":"由于原材料、能源、物流和劳动力成本持续上涨，叠加全球局势的不确定性，GS Yuasa和松下宣布将提高日本市场的铅酸电池价格。从2026年8月起，汤浅将对其所有型号的汽车、摩托车替换用铅酸电池及循环电池提价至少20%。此前该公司已宣布对部分铅酸牵引电池、相关零部件及电动汽车充电器涨价至少10%。","scd":null,"kp":[]},{"i":3398,"as":"为加强马来西亚的回收产业链，电池回收企业BateriHub与MNA Metal Resources签署了谅解备忘录。BateriHub是马来西亚最大的直营汽车电池零售商，持有环境部门执照。MNA作为持牌铅酸电池回收商和冶炼厂，将被指定为首选废旧电池收集商，直接或通过指定运输商进行废电池收集，以促进负责任的回收工作。","scd":null,"kp":[]},{"i":3399,"as":"导电添加剂是提升现代电池性能、可制造性和寿命的低估工具。在电池行业中，阴极（如NMC和日益增长的LFP）和石墨基阳极等核心活性材料决定了基准性能，而精心设计的导电添加剂则有力支撑了这些活性材料。这不仅提升了电池的整体表现，还对优化成本和电芯生产效率起到了关键作用。","scd":null,"kp":["[导电添加剂对现代电池的作用]: 关键用于提升电池的性能、可制造性和循环寿命"]},{"i":3400,"as":"一部由Intercalation推出的纪录片深入剖析了美国电池产业的困境与潜力。尽管约1000亿美元的资金涌入该行业，但多数企业仍难以实现千兆瓦级别的商业化生产。在频繁的实验室突破背后，美国企业面临着工厂倒闭和竞争失败。与此同时，中国制造商已巩固了其在全球电池制造业的控制地位。","scd":null,"kp":["投资规模[美国电池产业]: 约1000亿美元","[美国电池产业商业化瓶颈]: 大多数企业在迈向吉瓦时级别的商业化规模生产路径上仍面临受阻困境"]},{"i":3401,"as":"Donut Lab的固态电池丑闻凸显了独立测试的重要性。该公司曾宣称其产品具备400 Wh/kg的能量密度、5分钟快充能力，并承诺在2026年第一季度为Verge摩托车的量产提供电池。但Ziroth频道的详细调查视频分析拆穿了这些关于能量密度和充电时间的虚假承诺，证明其声明不实。","scd":null,"kp":[]},{"i":3402,"as":"Amazon Business举办了一场独家网络研讨会，探讨如何利用机器学习来推动智能库存优化。随着客户需求的增长和趋势的快速变化，电商库存管理面临库存过剩或缺货的挑战。采用强大的智能策略能够避免订货过剩或不足，确保企业满足精确的库存需求并高效应对不断增长的工作量。","scd":null,"kp":[]},{"i":3403,"as":"根据Gartner发布的《2026年供应链技术趋势》报告，智能体AI、物理AI和决策治理成为年度顶级趋势。报告指出，自主性与代理、专业化与智能化、信任与治理反映了向跨越数字和物理环境的自主问责系统的转变。2026年，AI将不再仅用于获取洞察，而是在供应链的运营执行中发挥更关键的作用。","scd":null,"kp":[]},{"i":3404,"as":"Jeep正式确认其纯电动越野车Recon EV将在欧洲市场上市销售。此前曾有报道否认该车型在欧洲及英国的销售计划，但官方发言人澄清该车仍定于2027年初在欧洲推出。Recon EV作为类似牧马人的纯电动SUV，已在北美率先开启销售，并计划于2026年陆续推向欧洲、英国等全球其他市场。","scd":null,"kp":[]},{"i":3405,"as":"埃隆·马斯克驳斥了粉丝关于特斯拉在Optimus人形机器人研发生产上“蓄意隐瞒真实进度”的理论。他明确警告，Optimus机器人的初期生产进度将“极其缓慢”。尽管有观点猜测特斯拉因实际进度超预期而保持低调，但马斯克的表态直接否决了这种乐观猜测，并与公司多次推迟发布时间线的实际情况相符。","scd":null,"kp":["生产进度[特斯拉Optimus人形机器人]: 早期将极其缓慢"]},{"i":3406,"as":"丰田在取消其旗舰车型雷克萨斯LF-ZC纯电动汽车的开发后，宣布将向受影响的供应商提供至少部分赔偿。由于供应商已为该车型投资专用设备和技术，丰田预计将支付数百亿日元。雷克萨斯LF-ZC原计划搭载丰田最新的电池技术突破和一体化压铸制造工艺，取消该车型给供应链带来了“前所未有”的冲击。","scd":null,"kp":["旗舰纯电车型[丰田Lexus LF-ZC]: 已停止开发","制造工艺[新一代纯电车型]: 引入一体化压铸技术","先进电池技术[新一代纯电车型]: 计划搭载最新突破"]},{"i":3407,"as":"电动汽车制造商Lucid在新任CEO Silvio Napoli的领导下，宣布对其高管团队进行全面大换血，一次性引入包括首席财务官、首席技术官在内的六名新高管。此次重组距离该公司裁员18%并撤回2026年产量预期仅一周多时间。重组旨在精简组织架构，强化问责制，并将向CEO直接汇报的高管人数削减一半。","scd":null,"kp":["裁员比例[Lucid公司重组]: 18%","2026年生产指引[Lucid公司]: 已撤回"]},{"i":3408,"as":"雅迪在2026年欧洲自行车展上展出了一款全新的全悬架通勤电动自行车Yadea Como。作为全球按产量计算领先的电动汽车制造商，雅迪在电动两轮车领域推出了丰富的产品线。这款通勤电踏车的最大亮点是配备了后悬挂系统，这在同类车型中十分罕见，且巧妙地将后避震器隐藏封装在车架下管内部。","scd":null,"kp":["车辆类型[雅迪Como车型]: 全悬架通勤电动自行车"]},{"i":3409,"as":"特斯拉2026年第二季度汽车交付量同比大增25%，达到480,126辆，超出华尔街预期约74,000辆，创史上最强的第二季度成绩，结束了连续两年的下滑。本季度特斯拉生产量为451,758辆，其中Model 3和Model Y是绝对的交付主力，贡献了467,762辆。本季度的交付量显著高于生产量，成功减少了库存。","scd":null,"kp":["交付量[特斯拉2026年第二季度]: 480,126辆","同比增长率[特斯拉2026年第二季度交付量]: 25%","超预期交付量[特斯拉2026年第二季度]: 约74,000辆","产量[特斯拉2026年第二季度]: 451,758辆"]},{"i":3410,"as":"McMurtry发布了Speirling纯电动超级跑车的量产版，售价为130万美元。这款赛车利用车底巨大的风扇产生强大的地面下压力，解决了高性能电动车受限于轮胎抓地力的问题。该物理设计使其获得了极其惊人的性能表现，并打破了赛道纪录，甚至具备倒置行驶的能力。","scd":null,"kp":["售价[McMurtry Speirling纯电超跑]: 130万美元","底盘下压力技术[McMurtry Speirling]: 利用巨型风扇产生地面吸附力"]},{"i":3411,"as":"Rivian公布的2026年第二季度业绩显示，其生产了12,613辆汽车并交付12,194辆，大幅超越预期的9,000/11,000辆。基于强劲的表现以及供应链瓶颈的消除和需求的明显上升，Rivian宣布上调2026年全年的交付量指引，从此前的62,000至67,000辆提高至65,000至70,000辆。","scd":null,"kp":["产量[Rivian 2026年第二季度]: 12,613辆","交付量[Rivian 2026年第二季度]: 12,194辆","全年交付指引[Rivian 2026年]: 上调"]},{"i":3412,"as":"乌克兰领先的太阳能公司Atmosfera位于基辅的中心仓库在6月25日夜间遭到俄罗斯导弹袭击。由于袭击发生时没有员工在场，因此没有造成人员伤亡。袭击引发的火灾摧毁了仓库内的部分太阳能设备，但该公司证实大部分库存得以保全。","scd":null,"kp":["资产受损情况[乌克兰太阳能企业Atmosfera中央仓库]: 部分光伏设备被毁"]},{"i":3413,"as":"西班牙EPC承包商Ijes Solar正在法国建设一座占地9公顷、装机容量为8.9兆瓦的Les Brandes地面光伏电站。该光伏园建在具有考古价值的区域，采用了浅石笼地基系统。该技术实现了最小的地表扰动，在确保光伏电站结构稳定性的同时，通过完全可逆的基础系统保护了敏感的地下文物遗产。","scd":null,"kp":["地基技术[考古遗址光伏电站部署]: 浅石笼地基","工程特点[浅石笼地基系统]: 最小化地表干扰且具备完全可逆性"]},{"i":3414,"as":"总部位于荷兰的逆变器与储能制造商Atmoce推出了一款名为M-ELV BattBank的新型交流耦合储能系统，专用于工商业领域。该系统单机可用能量容量为16.08千瓦时，通过7个单元组合可将簇级容量扩展至112.56千瓦时。每增加一个模块，输出功率提升8千瓦，最高可达56千瓦的连续输出功率，支持级联扩展以满足企业灵活的能源需求。","scd":null,"kp":["单机可用能量容量[M-ELV BattBank工商储系统]: 16.08 kWh","系统扩展上限[M-ELV BattBank工商储集群]: 112.56 kWh","系统耦合方式[M-ELV BattBank工商储系统]: 交流耦合","应用场景[M-ELV BattBank系统]: 工业和商业领域"]},{"i":3415,"as":"世界银行已批准向摩洛哥国家电力和水务办公室（ONEE）提供2.65亿美元一揽子融资，用于建设Ifahsa抽水蓄能电站。该项目总成本预计为5亿美元，位于摩洛哥北部，将接入400千伏输电网。电站装机容量为300兆瓦，储能容量达1500兆瓦时，建成后将支撑至少1吉瓦的新增太阳能和风能发电产能。","scd":null,"kp":["投资金额[摩洛哥Ifahsa抽水蓄能项目]: 2.65亿美元","装机容量[摩洛哥Ifahsa抽水蓄能项目]: 300 MW","储能容量[摩洛哥Ifahsa抽水蓄能项目]: 1,500 MWh","支撑能力[配套新能源]: 支持至少1 GW的新增太阳能和风能装机"]},{"i":3416,"as":"西班牙控制系统专家Sunner推出了名为True Wind的预测监测系统，用于在光伏跟踪器发生结构损坏前检测由风引起的空气动力学失稳现象。该技术摒弃了基于风速的传统保护机制，采用实时结构分析进行预测。通过及早发现可能导致破坏性驰振的失稳迹象，该系统能够有效提升光伏跟踪器的可用性并防止结构受损。","scd":null,"kp":["监测系统[光伏跟踪器]: True Wind预测监控系统","技术特点[防风致驰骋保护]: 采用实时结构分析替代基于风速的保护机制"]},{"i":3417,"as":"欧盟统计局公布数据显示，2026年第一季度可再生能源发电量占欧盟总发电量的45.5%，高于2025年同期的42.7%。其中，太阳能发电量达到58.8太瓦时，较去年同期增长3.5太瓦时。太阳能占第一季度欧盟可再生能源发电量的17.3%，成为仅次于风能的第三大可再生电力来源。","scd":null,"kp":["可再生能源占比[2026年第一季度欧盟电力]: 45.5%","发电量[2026年第一季度欧盟光伏]: 58.8 TWh"]},{"i":3418,"as":"大华股份在2026年德国慕尼黑国际太阳能展上展示了以“新能源中的可视化人工智能”为主题的系列创新技术。大华依托AIoT技术，为能源运营商涵盖发电、输电到用电的整个能源价值链提供解决方案，旨在提升效率、可靠性和安全性。展出的解决方案组合主要涵盖周界防护和智能巡检等五个核心应用领域。","scd":null,"kp":["技术方案[新能源人工智能应用]: 包含周界保护和智能巡检系统等在内的AIoT解决方案"]},{"i":3419,"as":"阿曼与由法国电力公司（EDF）牵头的联合体签署协议，将建设一座500兆瓦的Al Kamil太阳能光伏电站和一个2吉瓦的抽水蓄能设施。该项目联合体成员包含阿曼本土公司及国家电力和水务采购机构。其中的2吉瓦抽水蓄能系统建成后，将成为中东地区最大的水力发电厂。","scd":null,"kp":["装机容量[阿曼太阳能项目]: 500 MW","装机容量[阿曼抽水蓄能设施]: 2 GW","行业地位[中东最大水电设施]: 预计将成为中东地区最大的水电站"]},{"i":3420,"as":"法国H2air集团旗下建设子公司完成了位于摩洛哥北部Oued Rmel大坝水库的13兆瓦浮动光伏电站。这是目前非洲最大的投运浮动光伏电站。该设施专为应对水库高达44米的极端水位波动而设计，采用柔性锚固和漂浮系统来保持季节性变化下的稳定性。该电站将为丹吉尔地中海港的工业和港口运营供电。","scd":null,"kp":["装机容量[摩洛哥Oued Rmel大坝浮动光伏]: 13 MW","水位波动适应[极端条件水库]: 适应高达44米的水位波动","锚泊与浮选系统[浮动光伏]: 采用柔性锚泊和浮选系统以保持季节性变化下的稳定性"]},{"i":3421,"as":"根据萨尔瓦多官方数据，截至2025年底，该国总发电装机容量达到3200.61兆瓦。其中，光伏装机容量为846.62兆瓦，占比达到26.4%，已超越化石燃料和水力发电，成为该国电力系统中装机容量最大的技术类型，标志着光伏成为萨尔瓦多领先的发电技术。","scd":null,"kp":["总装机容量[2025年底萨尔瓦多电力]: 3,200.61 MW","光伏占比[2025年萨尔瓦多电力装机]: 26.4%","光伏装机容量[2025年底萨尔瓦多]: 突破846 MW"]},{"i":3422,"as":"佐治亚理工学院的研究人员开发了一款可穿戴音频系统，能够将附近机器人的动作转化为动态的警告音乐。该系统借鉴了恐怖电影中的悬念配乐技术，在人机协作环境中，能在机器人的动作演变为安全威胁前，提前向工人发出声音警报，从而提高工人的情境感知能力并有效减少工作场所事故的发生。","scd":null,"kp":["系统功能[人机协作安全预警]: 将附近的机器人动作实时转化为动态警告声","技术目标[可穿戴音频系统]: 提升态势感知能力并减少工作场所事故"]},{"i":3423,"as":"加州大学圣地亚哥分校的科学家研发出一种新型回收工艺，将废旧磷酸铁锂（LFP）电池直接转化为磷酸锰铁锂（LMFP）正极材料。与传统的拆解成原材料再制造的方法不同，该技术直接对现有正极进行升级，使新电池在保留原有高安全性和长寿命特性的同时，还能存储更多的能量，有效提升退役电池价值并减少浪费。","scd":null,"kp":["再生工艺[废旧电池回收]: 将废旧磷酸铁锂(LFP)材料转化为磷酸锰铁锂(LMFP)","材料属性[新型LMFP电池]: 储能更高且保留高安全性和长寿命特性"]},{"i":3424,"as":"美国便携式微型核反应堆制造商Radiant已接收首批定制核燃料，为其1兆瓦的Kaleidos微反应堆在爱达荷国家实验室进行长达150小时的连续耐力试验做准备。该测试计划于今年夏天进行，旨在开展全功率、全温度的严苛测试与验证，以支持该反应堆在2028年实现量产和向客户交付。","scd":null,"kp":["测试时长[Kaleidos微型核反应堆]: 150小时连续耐久性试验","输出功率[Kaleidos微型核反应堆]: 1兆瓦","燃料类型[Kaleidos微型核反应堆]: 三结构各向同性核燃料"]},{"i":3425,"as":"加州航空航天公司Auriga Space推出了全球首个商业测试平台，用于评估高超音速飞行器材料在真实气候条件下的耐受性。该系统利用Prometheus电磁加速器，将测试材料射入模拟天气环境中，以检验先进复合材料在雨、冰雹和空气微粒撞击下的性能表现，填补了高超音速材料在飞行前进行全尺寸气候测试的技术空白。","scd":null,"kp":["测试平台[高超音速材料气候测试]: 世界首个商业平台，采用Prometheus电磁加速器推进测试材料穿透模拟天气"]},{"i":3426,"as":"波音公司旗下的MQ-25“黄貂鱼”无人加油机降落在美国海军尼米兹号航空母舰上，这是该无人机五年来首次登上航母。美国海军发布照片显示MQ-25 T1测试机停在飞行甲板第三号弹射器附近，此次测试旨在推进这架全球首架舰载无人空中加油机在未来几年内形成运作能力。","scd":null,"kp":["技术状态[MQ-25黄貂鱼无人机]: 实现五年来首次降落在航母甲板，向成为世界首架实用型舰载无人加油机迈进"]},{"i":3427,"as":"以色列在对抗伊朗的战争经验基础上，为其“铁穹”近程防空系统升级了“铁束”激光武器系统。该系统由拉斐尔公司制造，是一款功率达100千瓦级的高能激光武器系统（HELWS）。通过以色列导弹防御组织的广泛测试，升级后的系统已成功整合，能够有效击毁敌方导弹和无人机。","scd":null,"kp":["激光武器升级[铁穹防空系统]: 集成100kW铁束激光武器，用于击毁敌方无人机和导弹"]},{"i":3428,"as":"德国柏林亥姆霍兹中心和洪堡大学的研究团队创下串联太阳能电池效率新认证纪录。该定制电池将25.5%的太阳光转化为电能，打破了该团队去年创下的24.6%的纪录。取得这一突破的关键在于电池尺寸达到1.081平方厘米，成功突破了太阳能领域1平方厘米尺寸的物理门槛。","scd":null,"kp":["光电转换效率[定制 tandem 太阳能电池]: 25.5%"]},{"i":3429,"as":"中国广西防城港边境检查站引入优必选科技的Walker S2人形机器人，以缓解货车的严重拥堵状况。该合同价值约4000万美元，目前首批机器人已交付并在关键交通枢纽投入使用。此举旨在协助边境当局提升繁忙国际边境口岸的海关检查效率，应对繁重的日常交通流。","scd":null,"kp":["采购金额[Walker S2人形机器人部署于中越边境]: 约4000万美元"]},{"i":3430,"as":"NASA启用了一台名为“Athena”的最新高性能超级计算机，该系统配备超过262,000个CPU核心，峰值计算性能达到20 petaflops。Athena能够为NASA科学家提供强大的计算能力，用于模拟火箭发射、新一代航空航天器设计、训练大规模人工智能模型以及分析海量数据集，同时在降低运营成本的同时提升能源使用效率。","scd":null,"kp":["CPU核心数[Athena超级计算机]: 超过262,000个","峰值性能[Athena超级计算机]: 超过20 petaflops"]},{"i":3431,"as":"国际研究团队SuperC通过将机器学习与高级量子物理相结合，开发出一种加速寻找新型超导材料的强大方法。该方法能够在近乎无限的材料组合中精准筛选出最具潜力的超导候选材料。借助这项技术，研究人员已经成功发现了两种全新超导材料，大幅缩短了寻找无损耗传输电力的实用超导体的时间。","scd":null,"kp":["探索方法[室温超导体材料发现]: 结合机器学习与高级量子物理快速筛选材料组合"]},{"i":3432,"as":"科学家研究发现，数十亿年前发生的一次巨大撞击形成了月球上最大且最古老的撞击盆地，并将月球深处的岩石带到了靠近月球南极表面的位置。两项最新研究揭示了这一碰撞事件的演变过程，表明深藏于月球内部的珍贵岩石距离地表比以往认知的更浅。未来的阿耳忒弥斯任务宇航员可借此研究月球早期演化史。","scd":null,"kp":[]},{"i":3433,"as":"","scd":null,"kp":[]},{"i":3434,"as":"","scd":null,"kp":[]},{"i":3435,"as":"","scd":null,"kp":[]},{"i":3436,"as":"","scd":null,"kp":[]},{"i":3437,"as":"","scd":null,"kp":[]},{"i":3438,"as":"","scd":null,"kp":[]},{"i":3439,"as":"","scd":null,"kp":[]},{"i":3440,"as":"天合光能申请了一项名为“一种光伏接线盒”的专利（授权公告号CN224438938U）。该光伏接线盒包含盒体和盒盖，盒体外侧壁四周设有第一固定件，盒盖安装腔侧壁四周设有第二固定件。当盒体嵌入安装腔时，两者配合锁紧。该设计采用外包式安装形式，显著提升了接线盒侧向的抗冲击性能，同时配合全方位内扣锁紧设计，有效增强了盒盖与盒体连接的稳定性。","scd":null,"kp":["结构设计[光伏接线盒]: 盖体采用外包式安装结合全方位内扣锁紧，有效提升侧向抗冲击性能及连接稳定性"]},{"i":3441,"as":"晶科能源及其关联公司申请了一项名为“太阳能电池及光伏组件”的专利（申请公布号CN122318380A）。该太阳能电池在具有相对表面的基底上设有发射极及钝化结构，表面带有绒面结构。核心在于位于第一电极与发射极之间的导电层，该导电层包含形貌不同的第一导电颗粒与第二导电颗粒，其中第一导电颗粒呈支化形状或线性形状，以此提升电池的导电性能与结构特性。","scd":null,"kp":["导电层结构[太阳能电池第一电极与发射极之间]: 包含形貌不同的第一导电颗粒（支化或线状）和第二导电颗粒"]},{"i":3442,"as":"山西省能源局发布新规优化分布式可再生能源管理，明确在电网承载力饱和的“红区”，只要配建储能并满足“全部自发自用”，即可新建并网。此举依托国家新版承载力评估标准，取消了反向负载率80%的一刀切红线，改为绿、黄、红三色动态管理。随着安徽、河北、山东跟进，分布式储能正式成为红区并网的“前置条件”，解锁了因电网受限的工商业屋顶光伏项目。","scd":null,"kp":["变压器反向负载率[分布式电源接入承载力评估导则DL/T 2041-2019]: 不得超过80%","[红区分布式可再生能源并网条件]: 配备储能且满足全部自发自用","[新版分布式电源承载力评估导则DL/T 2041-2025]: 取消80%一刀切红线，改为绿、黄、红三色分区动态管理"]},{"i":3443,"as":"特斯拉在第二季度的汽车销量实现了25%的反弹增长。","scd":null,"kp":["汽车销量增幅[特斯拉第二季度]: 25%"]},{"i":3444,"as":"微软宣布承诺投入25亿美元，用于支持其全新的应用人工智能咨询业务的发展与推广。","scd":null,"kp":["投入资金[微软应用人工智能咨询工作]: 25亿美元"]},{"i":3445,"as":"","scd":null,"kp":[]},{"i":3446,"as":"英伟达将为其客户的GPU提供支持与担保，并计划从这些客户产生的云计算收入中获取一定比例的分成。","scd":null,"kp":["商业模式[Nvidia GPU支持]: 为客户提供GPU兜底支持，并从其云营收中分成"]},{"i":3447,"as":"优步对其旗下的数据标签业务进行了重组和调整，以优化运营和业务结构。","scd":null,"kp":[]},{"i":3448,"as":"","scd":null,"kp":[]},{"i":3449,"as":"精益六西格玛和业务流程管理等传统卓越运营框架正随着企业引入人工智能而发生演变。据估计，未来十年内AI驱动的流程优化市场规模预计将突破1130亿美元。在一项相关研究中，高达88%的受访企业正在将AI技术深度嵌入其既定的流程优化方法论中，以实现更高效的分析与问责机制。","scd":null,"kp":["运营管理框架[卓越运营传统方法论]: 精益六西格玛与业务流程管理(BPM)"]},{"i":3450,"as":"人工智能正在成为能源行业等重资产物理基础设施领域的核心运营层。以伍德赛德能源为例，该公司并未从生成式AI起步，而是多年来在勘探、钻井、维护和工厂运营中广泛部署预测性分析、优化系统和机器学习工具。能源行业产生的大量运营数据为AI应用提供了基础，使其能够确保物理设施的操作连续性与安全性，展现了AI在工业领域的深度应用。","scd":null,"kp":[]},{"i":3451,"as":"加州的一项气候政策因存在严重数学漏洞而受到质疑。该政策设立系统向全美牧场主支付补贴，鼓励将牛粪产生的甲烷转化为天然气，但补贴过于丰厚且系统复杂。研究指出，这种机制没有强制行业直接减排，而是建立了在各方之间转移气候责任的复杂激励系统，是当前气候行动策略缺陷的典型案例。","scd":null,"kp":[]},{"i":3452,"as":"法兰克福应用技术大学机电一体化设计与工程力学教授Enno Wagner博士参与开发了一种新方法，能够将复杂的流体“气泡混乱”现象成功可视化，为相关工业与科研领域的现象观测提供了新的技术手段。","scd":null,"kp":[]},{"i":3453,"as":"弗劳恩霍夫研究所、魏玛包豪斯大学和德国之声正式启动名为PADSE的研究项目，旨在识别和揭露人工智能生成的声音。各项目合作方代表已在德国伊尔梅乌举行了项目启动会议。该情报中未包含该研究项目的具体技术细节。","scd":null,"kp":[]},{"i":3454,"as":"特斯拉在2026年第二季度全球部署了13.5 GWh的储能容量，环比增长53%，同比增长40%。这是特斯拉迄今为止第二大季度部署量，仅次于2025年第四季度的14.2 GWh。自2016年以来，特斯拉累计储能部署量已超过132 GWh。","scd":null,"kp":["储能部署量[2026年第二季度全球]: 13.5 GWh","环比增长率[2026年第二季度相比第一季度]: 53%","同比增长率[2026年第二季度相比2025年第二季度]: 40%","历史最大单季部署量[2025年第四季度]: 14.2 GWh"]},{"i":3455,"as":"摩洛哥国家电力水务办公室获得世界银行2.65亿美元资金，用于建设位于北部的300 MW/1500 MWh抽水蓄能电站。该项目总成本预计为5亿美元，连接400千伏电网，配备两台150兆瓦可逆式水泵水轮机，将支持至少1 GW的新增太阳能和风能产能。","scd":null,"kp":["抽水蓄能装机规模[摩洛哥Ifahsa项目]: 300 MW/1,500 MWh","世界银行融资金额[摩洛哥Ifahsa抽水蓄能项目]: 2.65亿美元","支持新能源装机规模[摩洛哥Ifahsa项目配套]: 至少1 GW（太阳能和风能）","项目总投资[摩洛哥Ifahsa抽水蓄能项目]: 5亿美元"]},{"i":3456,"as":"瑞士公用事业公司Alpiq已获得电网运营商Swissgrid的初步批准，将在索洛图恩州建设一座300 MW/1.2 GWh的电池储能系统（BESS）。该项目靠近现有水电站，提供4小时储能，满足约50万户家庭用电需求，计划于2027年动工，2029年投入运营。","scd":null,"kp":["电池储能系统规模[瑞士Niedergösgen项目]: 300 MW/1.2 GWh","预计建设时间[瑞士电池项目]: 2027年","预计投运时间[瑞士电池项目]: 2029年","储能时长[瑞士电池项目设计]: 4小时"]},{"i":3457,"as":"Green Flexibility与德国电池储能开发商Kajoni达成合作，共同开发总规模为750 MW/3 GWh的电池储能项目组合。Kajoni负责将项目推进至可建设状态，Green Flexibility提供开发资金并负责后续的建设、运营和商业化。项目正按德国新推出的大规模储能并网流程推进。","scd":null,"kp":["总储能容量[德国电池存储组合]: 3 GWh","总功率[德国电池存储组合]: 750 MW","[开发状态]: 处于德国大型电池项目电网连接成熟度审批流程中"]},{"i":3458,"as":"哥本哈根基础设施合作伙伴通过其基金，使位于智利北部的220 MW/1.1 GWh独立电池储能项目投入商业运营。该项目利用白天低成本太阳能充电并在高需求时放电，已获《巴黎协定》第六条授权，可产生国际认可的碳信用额度。","scd":null,"kp":["独立电池储能系统规模[智利Arena BESS项目]: 220 MW/1.1 GWh","[运行模式]: 白天利用低成本太阳能充电，在需求高峰期放电","[商业状态]: 已投入商业运营"]},{"i":3459,"as":"截至2026年第一季度，苏格兰累计可再生能源装机容量达到18.1 GW，同比增长3.2%，其中陆上风电占10.7 GW。可再生能源发电量达13.4 TWh，创单季度历史新高，同比增长22%。此外，苏格兰累计太阳能装机容量增加至0.9 GW。","scd":null,"kp":["累计太阳能装机容量[2026年一季度末苏格兰]: 0.9 GW","可再生能源总装机容量[2026年一季度末苏格兰]: 18.1 GW","陆上风电装机容量[2026年一季度末苏格兰]: 10.7 GW"]},{"i":3460,"as":"中国东北地区一座名为“绿港氢城”的项目已正式投入运营。正文部分未提供该项目的具体技术细节、产能规模及投资金额等进一步信息。","scd":null,"kp":["[项目状态]: “绿港氢城”在中国东北投入运营"]},{"i":3461,"as":"Höegh Evi与Nord Gas Solutions正在进行氨裂化技术的验证工作。正文部分内容主要提及澳大利亚首个氢能研发设施开始建设，未包含氨裂化技术的具体验证细节与核心参数。","scd":null,"kp":["[项目状态]: 澳大利亚首个氢能研发设施开始建设"]},{"i":3462,"as":"中国工信部等部门联合发布三项光伏能耗能效强制性国家标准，覆盖多晶硅、硅片、组件、逆变器等全产业链环节。标准分等级设定能耗指标，严格控制高耗能低效产能，并创新纳入组件耦合环境应力衰减率评价指标，以刚性约束筑牢光伏产业绿色发展底线。","scd":null,"kp":["[发布标准]: 《硅单晶单位产品能源消耗限额》、《晶体硅光伏组件和逆变器能效限定值及能效等级》、《硅多晶和锗单位产品能源消耗限额》","[核心特征]: 覆盖多晶硅、硅片、组件、逆变器全链条，分等级设定能耗能效刚性约束指标","[组件创新指标]: 纳入耦合环境应力衰减率评价指标"]},{"i":3463,"as":"今年前5个月，安徽省电动汽车、锂电池、光伏产品“新三样”出口总值达617.4亿元，同比增长108.7%。其中，电动汽车出口量与值均实现大幅增长，对欧盟、东盟、拉美等市场呈现多元化增长。锂电池受海外储能需求拉动增势强劲，光伏产品对东盟和非洲出口显著增加。","scd":null,"kp":["出口额[前5月安徽省“新三样”]: 617.4亿元","出口额同比增长率[前5月安徽省“新三样”]: 108.7%","出口量[5月安徽省电动汽车]: 10.6万辆","出口量同比增长率[5月安徽省电动汽车]: 223.9%","出口量[5月安徽对欧盟电动汽车]: 4万辆"]},{"i":3464,"as":"国内新能源高端SUV市场正经历从六座向五座车型的转变。理想和蔚来等车企相继推出五座版旗舰车型，将空气悬架、高压电气架构等原本专属六座车型的旗舰硬件技术下沉。此举旨在补齐产品矩阵，抢占由传统豪华品牌长期把控的三十万元级别大五座市场份额。","scd":null,"kp":["[高端新能源SUV技术趋势]: 核心旗舰技术（空气悬架、后轮转向、高阶智能驾驶、高压电气架构等）从大六座车型向大五座车型转移","[产品价格带]: 20万元至50万元"]},{"i":3465,"as":"两项电动汽车强制性国家标准正式施行，大幅提升安全门槛。新国标首次明确“一键断电”须为物理断电装置，实现一个动作切断高压回路。动力电池热扩散测试要求提升至触发单体热失控后电池包不起火、不爆炸，且烟气不对乘员造成伤害，涵盖7项单体及17项系统测试。","scd":null,"kp":["[高压安全物理断电]: 新国标要求可通过单一点触或长按动作实现整车高压回路的物理断开"]},{"i":3466,"as":"美国加州大学洛杉矶分校团队利用3D打印技术制造出具有中空微腔结构的碳骨架电极，并填充氧化钒材料，成功研发出新型锌离子混合储能设备。该设备的能量密度达到同类设备的七倍，且使用成本更低、储量更丰富的锌材料，在经历1500次充放电循环后容量仍保持在82%。","scd":null,"kp":[]},{"i":3467,"as":"厦门大学联合美国西北大学研究团队针对富锂锰基正极材料提出了一种快速化成策略。该策略利用残余锂离子的自钉扎效应遏制结构损坏，降低晶格应变。研究证实，采用高速率化成方案的富锂电池比容量提升20%，循环性能提升36%，有效解决了锂电池高容量与长循环难以兼顾的痛点。","scd":null,"kp":["[正极材料]: 无钴富锂锰基正极材料","[化成工艺]: 采用高速化成方案/快速化成策略","[自钉扎效应]: 利用正极材料中残余锂离子遏制化成阶段材料结构损坏","[结构缺陷]: 快速化成介导产生低浓度结构缺陷，降低高荷电状态循环过程中的晶格应变堆积"]},{"i":3468,"as":"具身智能产业正加速从技术攻关迈入商业化落地阶段。在2026世界智能产业博览会上，多家企业展出了灵巧手、协同演奏机器人等已落地的整机产品。该技术实现了感知、决策与执行的闭环，在能源巡检等场景发挥重要作用，但规模化落地仍需解决数据供给、技术适配与商业闭环等瓶颈。","scd":null,"kp":["[具身智能落地瓶颈]: 面临数据供给、技术适配、商业闭环等制约"]},{"i":3469,"as":"受AI算力需求释放及技术创新驱动，今年前4个月我国电子信息制造业快速增长，规模以上企业增加值同比增长14%，营业收入达5.88万亿元。智能制造成效显著，算力需求带动服务器及元器件市场活跃，产业整体向高附加值延伸，出口和盈利水平稳步提升。","scd":null,"kp":["规模以上电子信息制造业增加值同比增长[1-4月]: 14%","营业收入[规模以上电子信息制造业1-4月]: 5.88万亿元"]},{"i":3470,"as":"香港科技大学（广州）智能自动驾驶技术中心研发出一款全自动收椅机器狗。该设备无需人工干预和遥控，能够实现自主识别与自动归位操作。该中心已建立涵盖感知、决策、规划、控制与多机协同全链条的完整研发体系。","scd":null,"kp":["[研发体系]: 搭建涵盖感知、决策、规划、控制、多机协同全链条的完整研发体系"]},{"i":3471,"as":"惠州锐鉴兴新能源科技公司在ADO电助力自行车的“皮带+力矩+自动变速”核心技术基础上进行智能化升级，引入了AI智能感知技术。工程师在实验室对车架进行机械应力疲劳测试，该技术的应用旨在使骑行过程更加智能、安全和轻松。","scd":null,"kp":["[E-Bike核心技术]: 皮带+力矩+自动变速","[智能化升级]: 加入AI智能感知技术"]},{"i":3472,"as":"6月份太阳能的大规模并网使得西班牙可再生能源份额提升至60%。此外，同期行业内其他动态包括沙特阿拉伯在12 GWh电池招标中确定了竞标者，以及智利启动了大型太阳能和储能项目的相关拍卖流程。","scd":null,"kp":[]},{"i":3473,"as":"Nordex获得德国大陆风电项目20兆瓦涡轮机订单。该订单涉及德国境内的陆上风电项目，总装机容量为20兆瓦。文章未披露更多项目技术细节及财务参数。","scd":null,"kp":[]},{"i":3474,"as":"日本可再生能源公司Renova与东京天然气公司达成了一项购电协议（PPA）。该项目为位于亚太地区的陆上风电项目，总装机容量为54兆瓦。正文未提供其他项目具体参数。","scd":null,"kp":[]},{"i":3475,"as":"7月1日，贵州省能源局发布通知，决定清理2026年第一批风电光伏发电项目建设计划。本次清理对象为未在规定期限内完成核准备案、逾期未开工或主动放弃的项目，共计53个，涉及总装机容量414.7万千瓦（即4.25GW）。","scd":null,"kp":["清理装机规模[贵州逾期风/光项目]: 414.7万千瓦(4.25GW)","清理项目数量[贵州逾期风/光项目]: 53个"]},{"i":3476,"as":"美国特朗普政府正起草禁令，拟禁止进口外国太阳能及电池逆变器，主因担忧中国利用其破坏电力供应。该草案由美国联邦通信委员会（FCC）制定，针对新型外国逆变器，最早于今年公布。此前欧洲类似禁令促使美方推进该计划，中国驻美使馆对此表示坚决反对。","scd":null,"kp":["禁令限制范围[美国光伏逆变器]: 禁止进口外国(针对中国制造)新型逆变器(连接太阳能和电池至电网)","禁令起草机构[美国光伏逆变器]: 美国联邦通信委员会(FCC)"]},{"i":3477,"as":"6月29日，华能宁夏隆基永宁400兆瓦光伏发电项目正式开工。项目总投资约11亿元人民币，旨在优化地方电力结构并提升能源保供能力。建设方将实施施工管控、工期把控与质量提升等专项行动，以打造绿色标杆工程。","scd":null,"kp":["装机规模[华能宁夏永宁光伏项目]: 400兆瓦","总投资[华能宁夏永宁光伏项目]: 约11亿元"]},{"i":3478,"as":"6月26日，华能能源交通产业控股有限公司与华能新能源股份有限公司签署光伏项目生产管理权限移交协议。本次移交涉及24个集中式、工商业及户用光伏项目，覆盖山西、山东、江苏等八个省市，是华能集团“1+7”改革方案的首项落地成果。","scd":null,"kp":["移交项目数量[华能光伏项目生产管理权]: 24个","覆盖地域[华能光伏项目生产管理权]: 山西、山东、江苏、河北、重庆、湖北、安徽、海南等地","项目类型[华能移交光伏项目]: 集中式、工商业及户用"]},{"i":3479,"as":"近期国内多地总容量超2.8GW的光伏项目密集开工。具体包括：四川晟天甘孜400MW项目（直流侧467.5MWp）、湖南宁远110MW农林渔光互补项目、大唐陕西府谷100MW山地光伏项目，以及华电四川稻城250MW光伏项目。这些项目普遍结合生态治理与土地复合利用模式进行开发。","scd":null,"kp":["开工总规模[6月全国光伏项目]: 超过2.7GW","交流侧装机规模[四川甘孜乡城正斗Ⅰ标光伏项目]: 400MW","直流侧安装容量[四川甘孜乡城正斗Ⅰ标光伏项目]: 约467.5MWp","装机规模[湖南永州宁远县农林渔光互补项目]: 110MW","开发模式[湖南永州宁远县项目]: 板上光伏发电、板下农业种养立体化复合开发"]},{"i":3480,"as":"本周国内多晶硅价格小幅下滑，n型复投料均价降至3.28万元/吨。6月国内多晶硅产量约9.29万吨，同比增长7.4%。由于高库存、头部企业增产及终端需求疲软，市场仍处于供需失衡状态。此外，《硅多晶、硅单晶单位产品能源消耗限额》新版标准于6月27日发布，将于2027年1月起执行，以加速落后产能出清。","scd":null,"kp":["成交均价[N型复投料(棒状硅)]: 3.28万元/吨","成交均价[N型颗粒硅]: 3.23万元/吨","产量[6月国内多晶硅]: 约9.29万吨","预计产量[7月国内多晶硅]: 约10万吨"]},{"i":3481,"as":"7月1日，浙江绍兴市发改委公示2026年二季度分布式光伏可开放容量。全市7地总可开放容量达1745.81MW（约1.7GW）。除嵊州市和新昌县预警等级为黄色外，其余地区均为绿色预警状态。","scd":null,"kp":["可开放容量[浙江绍兴2026二季度分布式光伏]: 1745.81MW(约1.7GW)"]},{"i":3482,"as":"7月1日，贵州省能源局下发44个风电光伏发电项目年度建设计划，总装机规模达386.433万千瓦（超3.86GW）。其中光伏项目11个（141.433万千瓦），风电项目33个（245万千瓦）。文件要求风电项目与光伏项目需分别在2027年12月和6月前完成核准与备案，逾期将取消指标。","scd":null,"kp":["总装机规模[贵州七星关等44个风光项目]: 386.433万千瓦(超3.86GW)","项目明细[贵州44个风光项目]: 光伏项目11个(141.433万千瓦)、风电项目33个(245万千瓦)","核准/备案期限[贵州风光项目]: 风电2027年12月22日前、光伏2027年6月22日前"]},{"i":3483,"as":"截至2026年6月19日，华为HarmonyOS各API版本设备占比数据更新。HarmonyOS 6.1.0(23)及以上版本占比达94.77%，新发布的26.0.0 Beta1（对应HarmonyOS 7.0.0 Beta1）占比达0.17%。多个5.0.0旧版本实现占比归零。新Beta1版本增强了组件材质效果、安全管控及游戏启动体验等功能。","scd":null,"kp":[]},{"i":3484,"as":"快手旗下北京可灵与21名初始投资者签订增资协议，获得20.28亿美元（约138.24亿元人民币）现金注资。此外，15名额外投资者已签署加入协议，追加了7.66亿美元。本轮总融资金额最高不超过30亿美元，投后估值达180亿美元。资金将用于支持可灵AI相关业务发展。","scd":null,"kp":["融资金额[北京可灵AI增资]: 20.28亿美元(约138.24亿人民币)","增资总款项上限[北京可灵AI增资]: 30亿美元(约204.471亿人民币)","股权占比[北京可灵AI增资]: 约占扩大后注册资本的16.67%"]},{"i":3485,"as":"比亚迪宣布已累计建成超7000座闪充站，覆盖全国325个城市。该闪充桩单枪最大功率达1500KW，配合二代刀片电池可实现5分钟将电量从10%充至70%。公司计划在2026年底前建成2万座闪充站，包含1.8万座中站和2000座高速站。","scd":null,"kp":["建成数量[比亚迪闪充站]: 超7000座","覆盖城市[比亚迪闪充站]: 325个","建设目标[比亚迪闪充站2024年底]: 2万座","单枪充电功率[比亚迪闪充桩]: 1500KW","充电速率[二代刀片电池+闪充]: 5分钟电量从10%充至70%，9分钟充至97%"]},{"i":3486,"as":"小鹏汽车CEO何小鹏表示，中国新能源汽车渗透率在2030年将超过90%。他指出，未来汽车行业变革的核心是AI与汽车的结合，每一辆汽车都将演变成为“四个轮子的机器人”。数据显示，今年5月新能源零售渗透率已达到62.9%的历史高位。","scd":null,"kp":["渗透率[中国新能源汽车市场2030年]: 超过90%","渗透率[中国纯电车型新车市场2030年]: 超过80%"]},{"i":3487,"as":"","scd":null,"kp":[]},{"i":3488,"as":"小鹏汽车CEO何小鹏指出，中国智能辅助驾驶技术及法规制定均处于全球领先地位。联合国最新发布的ADS GTR自动驾驶法规核心制定者包含中国，中国现有L2级辅助驾驶将于12月在全球适用。他预测，得益于AI的推动，未来3到5年内L4甚至L5级自动驾驶将实现落地。","scd":null,"kp":["自动驾驶等级[未来3到5年落地]: L4甚至L5","法规覆盖范围[联合国ADS GTR自动驾驶技术法规]: L2到L5","智能辅助驾驶[中国L2级]: 12月将能够在全球使用"]},{"i":3489,"as":"谷歌正在Android 17 QPR1测试版中持续开发原生的“应用锁”功能。最新系统代码显示，该功能将支持在设置中批量为多款应用开启应用锁，并计划提供仅通过生物识别验证进行解锁的安全选项。该功能此前曾在预览版中出现后被移除，预计不会随QPR1正式版推出。","scd":null,"kp":[]},{"i":3490,"as":"微信输入法最新版本上线了“语音转文字整理”及“隔空传送”功能。用户在使用语音转文字后可进行文本优化，且Mac与Windows双端均已全量支持。此外，只要设备安装了该输入法，即可通过“隔空传送”实现照片与文件的快速跨设备传输，同时支持聊天表情包自动匹配。","scd":null,"kp":["版本号[微信输入法iOS]: 3.5.1","版本号[微信输入法Windows]: 2.1.0","版本号[微信输入法Mac]: 2.2.0","新功能[微信输入法]: 语音转文字整理及隔空传输文件"]},{"i":3491,"as":"小鹏MONA L03正式开启预售，预售价14.38万元起，将于7月16日上市。该车型预售订单量已打破小鹏历史所有车型的同期小订纪录。新车定位为智能时尚SUV，提供纯电与增程双动力版本，搭载了算力达1500TOPS的图灵芯片及第二代VLA智驾系统。","scd":null,"kp":["预售价[小鹏MONA L03]: 14.38万元起","算力[小鹏MONA L03图灵芯片]: 1500TOPS","智驾系统[小鹏MONA L03]: 第二代VLA智驾系统","动力形式[小鹏MONA L03]: 纯电+增程双动力"]},{"i":3492,"as":"荣耀MagicOS 10七月更新将重点升级动效、锁屏、AI及智慧互联功能。本次更新将行业首发三端120Hz投屏功能，并新增3D照片锁屏与TOP级游戏应用分身。此外，YOYO助手支持通过语音指令直接发送微信消息或发起通话，系统小组件也新增了多项实用工具。","scd":null,"kp":[]},{"i":3493,"as":"上汽通用别克针对至境E7推出“交车关怀礼”，承诺7月31日前锁单用户自锁单起30天内交付，超期每天补贴100元。该车长宽高为4850/1910/1676mm，轴距2850mm。车内提供四座悬浮座椅及冷暖箱。智驾搭载27个感知硬件与Momenta大模型。动力采用真龙插混Pro系统，电机功率165kW，支持6kW外放电。中低配版搭载1.5L发动机，CLTC纯电续航235公里；高配版搭载1.5T发动机，CLTC纯电续航230公里。","scd":null,"kp":["补贴标准[别克至境E7延迟交付]: 100元/天","交车承诺周期[别克至境E7锁单起]: 30天内","官方指导价[别克至境E7]: 15.99万元起","上市权益价[别克至境E7]: 15.49万元起","车身长宽高[别克至境E7]: 4850x1910x1676mm"]},{"i":3494,"as":"华为MateBook Pro笔记本推送HarmonyOS 6.1.0.130 SP15版本升级，系统包大小约2.16GB。本次更新新增用户分级管理能力以提升多用户场景安全性，并支持连接相机直接读取照片和视频。此外，更新还优化了鸿蒙键、多屏输入法、截图拖拽、文件管理及打印机等多项操作体验，提升了系统的整体稳定性、性能表现，并丰富了状态栏、桌面壁纸与控制中心的个性化设置选项。","scd":null,"kp":["系统版本[华为MateBook Pro升级]: HarmonyOS 6.1.0.130 SP15","系统包大小[华为MateBook Pro升级]: 约2.16GB","新增能力[华为MateBook Pro]: 连接相机读取照片和视频、用户分级管理"]},{"i":3495,"as":"苹果iPhone 18 Pro系列的闪存供应链方案曝光。其中，256GB和512GB版本将继续采用来自SK海力士、铠侠和闪迪的TLC NAND闪存。1TB版本将混用TLC和QLC闪存，主要采用SK海力士的BC8Q-1T QLC，辅以三星3DV8 1TB TLC。2TB版本则全面采用SK海力士BC8Q-2T QLC闪存。相比TLC，QLC闪存成本更低、容量更大，但写入速度较慢且稳定性和寿命相对较低。","scd":null,"kp":["闪存方案[iPhone 18 Pro 1TB版本]: TLC和QLL混用","闪存方案[iPhone 18 Pro 256GB/512GB版本]: TLC","闪存方案[iPhone 18 Pro 2TB版本]: 全面采用QLC","QLC NAND供应商[iPhone 18 Pro 1TB/2TB]: SK海力士","TLC NAND供应商[iPhone 18 Pro 1TB]: 三星"]},{"i":3496,"as":"据数码博主爆料，某手机厂商子品牌正在测试2nm制程的骁龙8E6处理器，新机排期暂定于2027年上半年，定位性能大旗舰，预计为小米REDMI旗下产品。此外，爆料称小米REDMI K100系列将搭载骁龙8E5处理器，配备超高刷大屏、2亿像素大底主摄及5000万像素潜望长焦，内置约9000mAh大电池并支持百瓦有线快充，同时配备无线充电、3D超声波指纹及满级防水功能。","scd":null,"kp":["制程工艺[高通骁龙8E6处理器]: 2nm","发布排期[骁龙8E6新机]: 2027年上半年","电池容量[REDMI K100系列]: 约9000mAh","处理器[REDMI K100系列]: 骁龙8E5","主摄参数[REDMI K100系列]: 200Mp大底"]},{"i":3497,"as":"华为乾崑智能汽车解决方案就HUAWEI ADS 5辅助驾驶系统升级问题进行解答。华为乾崑智驾ADS 5共推出Max、Pro、SE三个版本。用户可以在车机端ADS App的设置界面中查询当前车辆搭载的系统版本。已搭载ADS 4系统（包括Max、Pro、SE版本）的车型，在升级至ADS 5对应的各个版本时，不存在任何硬件限制。","scd":null,"kp":["版本划分[华为乾崑智驾ADS 5]: ADS Max / Pro / SE","硬件要求[乾崑智驾ADS 4升级至ADS 5]: 无硬件限制"]},{"i":3498,"as":"制造商XTREM极稚为苹果iPhone 17系列推出MagSafe彩色墨水屏手机壳，售价399元。该手机壳整体厚度2.2mm，重44g，配备一块圆形彩色墨水面板，支持显示红、黄、黑、灰四种颜色的静态图片。墨水屏在平时显示不耗电，仅在刷新图片时通过手机NFC进行供电，无需独立电池。同时，该产品完全兼容MagSafe磁吸生态，不影响设备的无线充电功能。","scd":null,"kp":["整体厚度[XTREM MagSafe彩色墨水屏手机壳]: 2.2mm","重量[XTREM MagSafe彩色墨水屏手机壳]: 44g","显示配色[XTREM墨水屏面板]: 红黄黑灰四种","供电方式[XTREM墨水屏面板]: NFC供电","适用机型[XTREM墨水屏手机壳]: 苹果iPhone 17系列"]},{"i":3499,"as":"因企业AI应用成本大幅失控，多家科技、金融企业开始限制员工使用大模型。由于AI服务商将收费模式改为按实际调用量计费，部分企业月度开销增至三倍以上。为减少AI词元消耗，企业限制了对高性能旗舰模型的访问。花旗银行彻底关闭了员工对Claude和GPT最新旗舰模型的访问权限；Adobe也取消了对Claude大模型的无限制使用，并要求员工针对特定工作改用低推理能力模型以优化成本。","scd":null,"kp":["AI运营开销[部分企业成本失控]: 每月超1500万美元","计费模式[AI服务商]: 按实际调用量计费(取消固定年费)","模型部署策略[降低Token消耗]: 针对特定工作改用低推理能力模型"]},{"i":3500,"as":"哈苏与Capture One达成战略合作，Capture One 16.8.3版本及Mobile 3.3.4版本原生支持哈苏3FR格式RAW照片编辑。此次合作为每款哈苏机型创建了专属色彩配置文件，并提供XCD镜头配置文件以校正畸变、色差与暗角。摄影师可直接在软件内导入并使用全套工具处理哈苏X2D II 100C、X2D 100C与CFV 100C三款机型的RAW文件。联机拍摄功能预计于2026年晚些时候推出。","scd":null,"kp":["RAW格式支持[Capture One软件]: 哈苏中画幅相机3FR文件","版本要求[原生支持3FR格式]: Capture One 16.8.3或Mobile 3.3.4","联机拍摄功能[Capture One支持哈苏]: 预计2026年晚些时候推出"]},{"i":3501,"as":"针对部分车主反馈鸿蒙智行增值服务中的车道级导航地图未生效问题，官方回应称该功能将在HUAWEI ADS 5.0版本中正式开放。目前，车主在领取权益并切换至百度地图后即可支持车道级导航及拐弯实景指示。未生效情况主要指HUAWEI ADS App内的地图，而此前上架的百度地图（HIMA版）已具备该功能。当前车道级导航功能正处于灰度开放测试阶段。","scd":null,"kp":["车道级导航[HUAWEI ADS App]: 将在ADS 5.0版本开放"]},{"i":3502,"as":"压缩软件WinRAR发布7.23版本更新，修复了两项安全漏洞。第一项为“恢复卷”机制中的堆缓冲区溢出漏洞，攻击者可利用特制的RAR5格式文件导致程序崩溃；第二项为符号链接处理逻辑缺陷带来的路径遍历风险，攻击者可能将文件解压至目标目录之外植入恶意程序。7.23版本通过增加额外路径校验机制阻止了该行为。这两项漏洞尚未被实际利用，官方建议用户尽快升级以保障设备安全。","scd":null,"kp":[]},{"i":3503,"as":"中国电池制造商国轩高科与西班牙工业部达成合作，将在西班牙巴利亚多利德正式建设大型电池工厂项目。国轩高科将投资约9.5亿欧元，用于建设电池正极材料生产设施和电池回收厂，两座工厂预算分别为4.115亿和5.391亿欧元。西班牙政府将在PERTE资助计划下为该项目提供总额1.38亿欧元的补贴。该项目预计于2027年开始建设，首个投产的将是电池回收厂。","scd":null,"kp":["投资金额[国轩高科西班牙建厂]: 约9.5亿欧元","政府补贴[西班牙PERTE资助计划]: 总计1.38亿欧元"]},{"i":3504,"as":"电池行业的制造模式正在经历变革，不再单纯依赖建设规模越来越大的超级工厂。过去十年中，扩大工厂规模曾是电池企业确立行业地位和实现增长的核心方式，政府与投资者也大力推动产能扩张。然而，当前的电池行业正迎来全新的制造模式革命，未来的重点发展方向将不再局限于传统的实体工厂建设，而是探索全新的生产与价值创造途径。","scd":null,"kp":["制造模式演进[电池行业]: 探索不依赖建设实体超级工厂的新模式"]},{"i":3505,"as":"地缘政治动荡正在重塑全球电池供应链。全球电池市场受到一系列连锁反应的冲击，尤其是在二次铅等回收材料领域，一处供应链的中断会引发跨区域的连锁波动。这种复杂的系统变化使得电池废料流向等供应链环节充满不可预测性。面对这些不可预见的连锁效应，全球电池行业正积极应对供应网络中的各种风险与挑战，以维持供应链的运转。","scd":null,"kp":["供应链流向[全球电池废料]: 受地缘政治波动等突发事件重塑"]},{"i":3506,"as":"在全球经济波动的大环境下，供应链运营正加速向全面集成的弹性网络转型。行业专家指出，预测性规划、数据整合与跨团队协作是保障现代供应链连续性的核心驱动力。为应对当前的挑战，供应链管理正逐步摒弃碎片化、被动响应的传统运作模式，转而深度整合最新技术发展趋势，从而构建具备高度抗风险能力和韧性的现代化供应链体系。","scd":null,"kp":["供应链管理[提升弹性策略]: 预测性规划、数据整合与人类协作"]},{"i":3507,"as":"供应链咨询与技术公司Bluecrux正致力于通过数字化创新帮助供应链释放更多价值。面对日益复杂的全球供应链和不断提升的规划需求，企业正加速应用数字化工具。Bluecrux的核心理念是战略必须转化为实际影响力，其重点在于充分挖掘并利用供应链中每一个环节的潜力，将传统的供应链转化为具有更高协同性和运作效率的现代化价值链网络。","scd":null,"kp":["供应链规划[应对复杂性]: 转向数字化工具与创新"]},{"i":3508,"as":"气候变化正对全球农业供应链造成严重冲击。全球人口增长使得对弹性食品供应链的需求不断增加，但农业供应链高度依赖规律的天气模式和温控物流。近年来气候的剧烈波动严重扰乱了这一关键价值链，导致全球性的粮食短缺与供应中断。为应对这一挑战，农业与食品行业亟需提升供应链的抗风险能力与韧性，以确保产品能够顺利送达消费者手中。","scd":null,"kp":["脆弱性来源[农业供应链]: 气候变化与消费者需求的双重驱动"]},{"i":3509,"as":"科技平台Inspectorio通过提升供应链各环节的可见性，帮助企业优化供应链监管并降低运营风险。供应链中单个节点的效率低下会导致整个运作网络的延误和高昂成本。Inspectorio通过简化货物检验流程，为品牌和零售商提供了应对供应链动荡所需的数据可视化管理工具。这种全面的可见性加强了企业间的协作，使其能够更有效地管理和应对各类供应链中断风险。","scd":null,"kp":["供应链监管[Inspectorio平台]: 提升可见性、协作能力与风险管理"]},{"i":3510,"as":"2026年Electrek美国太阳能挑战赛即将拉开帷幕，届时将有来自美国、加拿大、比利时和荷兰高校的创纪录42支车队参与竞争。作为正赛前的资格赛，各队伍将在Formula Sun Grand Prix赛道活动中展示其手工打造的太阳能汽车性能。成功通过资格赛的车队将驾驶这些太阳能汽车踏上征程，完成横跨美国、总里程超过1500英里的耐力挑战赛。","scd":null,"kp":["参赛队伍数量[2026年Electrek美国太阳能挑战赛预选赛]: 创纪录的42支队伍"]},{"i":3511,"as":"2026年6月英国电动汽车市场表现强劲，注册量同比激增38%至64,440辆，占新车总注册量的近30%，创下非季节性高峰期的历史最高份额。受燃油价格上涨因素影响，英国购车者更倾向于选择电动汽车，推动了整体汽车市场同比增长15%，总注册量达到215,921辆。其中，特斯拉表现出显著的复苏态势，实现了42%的强势反弹，销量大幅回升。","scd":null,"kp":["电动汽车注册量[6月份英国市场]: 64440台","电动汽车市场份额[6月份英国市场]: 近30%","销量同比增长率[英国电动汽车6月份]: 38%","销量同比增长率[特斯拉6月份英国市场]: 42%"]},{"i":3512,"as":"外媒发布了7月4日美国独立日绿色能源产品促销盘点。Bluetti夏季特卖推出移动电站专属优惠，其FridgePower Station套餐起价降至807美元。Hiboy的电动出行产品提供最高58%的折扣，EX11全避震电动自行车降价700美元至1300美元。此外，EcoFlow的Prime Day闪购活动商品起价为1149美元。此次促销涵盖了便携储能、电动自行车及滑板车等多种清洁能源产品。","scd":null,"kp":["起售价[Bluetti冰箱电站及捆绑套餐]: 807美元起","最高折扣率[Hiboy电动滑板车和自行车7月促销]: 高达58%","折扣金额[Hiboy EX11全避震电动自行车]: 700美元"]},{"i":3513,"as":"起亚在釜山移动出行展上将其PV5电动货车改装为离网移动模拟器。该装置配备55英寸大屏幕、游戏座椅和定制内饰。此外，起亚还展示了包括7座版、豪华Prime版、高顶货运版、冰淇淋车、校车、移动银行和AI巡逻车在内的多种衍生车型。这辆模拟器货车由Brindley Kia通过租赁服务提供给CX Auto Group使用五周。","scd":null,"kp":["屏幕尺寸[起亚电动货车离网移动模拟器]: 55英寸"]},{"i":3514,"as":"特斯拉在迈阿密规划并发布了Robotaxi（机器人出租车）服务区域地图。该地理围栏区域仅覆盖迈阿密都会区的一小部分，主要包含西迈阿密以及向多拉和斯威特沃特延伸的地带，北至SR-826公路，南至US-41公路。该服务区排除了迈阿密市中心、迈阿密海滩、机场以及珊瑚阁的大部分区域。目前该服务仍无法扩展至德克萨斯州。","scd":null,"kp":["[特斯拉Robotaxi迈阿密服务区]: 仅限西迈阿密及延伸至Doral和Sweetwater的局部城市地理围栏区域","[特斯拉Robotaxi业务扩展状态]: 过去一年在德克萨斯州仍无法扩展落地"]},{"i":3515,"as":"美国哈里斯县检察官对一名在得州凯蒂引发致命车祸的44岁特斯拉司机提出过失杀人罪指控。指控文件显示，该司机在事故发生前数周曾在谷歌搜索“FSD（完全自动驾驶）太胆小了”。在事发住宅区的死胡同内，该司机凌驾于FSD功能之上，手动将车辆加速至73英里/小时，导致一名76岁妇女死亡。目前嫌疑人被关押在狱，保释金为15万美元。","scd":null,"kp":["车辆超速行驶速度[特斯拉司机解除FSD系统于住宅区死胡同]: 73 mph"]},{"i":3516,"as":"斯巴鲁宣布其新款2027款Trailseeker电动SUV起售价为39,995美元，与现款车型保持一致。该车被定位为适合全地形的坚固型SUV，拥有8.3英寸的离地间隙和标志性的对称全轮驱动（AWD）系统，提供375马力。车辆内部空间宽敞，提供Premium、Limited和Touring三种内饰版本。上市仅几个月，该车已成为斯巴鲁最受欢迎的电动SUV。","scd":null,"kp":["起售价[斯巴鲁新款Trailseeker EV]: 40000美元以下","综合马力[斯巴鲁新款Trailseeker EV]: 375匹","驱动系统[斯巴鲁新款Trailseeker EV]: 标配全轮驱动(AWD)"]},{"i":3517,"as":"本期Wheel-E播客探讨了电动自行车及非传统电动汽车领域的热门新闻，话题涵盖Gazelle、Amflow和Monarc推出的新型电动自行车，美国消费品安全委员会（CPSC）加强电动自行车安全监管的意图，以及佛罗里达州州长德桑蒂斯否决一项电动自行车安全法案等。该播客每两周在YouTube、Facebook、LinkedIn和Twitter等平台更新。","scd":null,"kp":[]},{"i":3518,"as":"沃尔沃建筑设备公司推出的首款A30电动铰接式运输卡车已正式交付客户投入使用。这款30吨级的纯电卡车被挪威承包商Leonhard Nilsen & Sønner AS部署于Hafslund水电站项目中。沃尔沃在去年的Bauma建筑博览会上首次发布了该款零排放设备，其实际应用证明了电动重型机械能够有效支持可持续基础设施和清洁能源生产。","scd":null,"kp":["载重能力[沃尔沃A30电动铰接式运输卡车]: 30吨","[沃尔沃A30电动卡车应用状态]: 首辆车已交付挪威承包商投入水电站项目实际使用"]},{"i":3519,"as":"在2026年德国欧洲国际自行车展上，展出了一系列新型自行车及相关周边产品。全球最大的电动汽车制造商雅迪发布了专为欧洲通勤者设计的全新COMO电动自行车。这款车型采用全悬挂阶梯式车架设计，巧妙隐藏了后避震器，兼顾了骑行舒适性与外观流畅度，并由Ananda电机提供动力。","scd":null,"kp":[]},{"i":3520,"as":"Orica已做出最终投资决定，推进位于澳大利亚新南威尔士州猎人谷的50兆瓦氢能中心项目，该项目将获得4.32亿澳元（约合3亿美元）的政府资金支持。产出的氢气将替代天然气作为原料，用于Orica在库拉贡岛工厂的氨气生产，以降低这一高耗能工业过程的碳排放。此外，三菱重工签署协议，将从2030年起每年从Acme购买10万吨绿色甲醇。","scd":null,"kp":["装机容量[Hunter Valley氢气中心]: 50 MW","年采购量[三菱与Acme绿色甲醇协议]: 100,000吨/年"]},{"i":3521,"as":"能源行业正经历从全球化向本地化的重大转变，这在可再生能源、储能、电动汽车充电和电网基础设施领域尤为明显。RCT Solutions的供应链经理Tuğçe Gür表示，真正的包容性应建立在公平、信任和机会的基础之上，即根据个人能力进行评估，赋予可见度与责任，并通过反馈、学习和领导力途径支持成长。技术的成功实施正日益依赖于对当地市场、监管法规和客户需求的理解。","scd":null,"kp":[]},{"i":3522,"as":"法国原子能和替代能源委员会（CEA）的新能源技术和纳米材料分支研发出一种温和的草酸湿法冶金工艺。该技术能够从废弃的异质结（HJT）太阳能电池的铟锡氧化物中高效回收金属铟，同时释放银栅极。通过在优化条件下进行选择性浸出、沉淀和煅烧，该方法可生产出高纯度的氧化铟。铟是HJT太阳能电池透明导电氧化物层的关键材料，其回收对可持续发展至关重要。","scd":null,"kp":["回收工艺[异质结太阳能电池废料]: 温和草酸基湿法冶金工艺","[选择性浸出、沉淀和煅烧优化条件]: 高纯度氧化铟生产和银栅极释放"]},{"i":3523,"as":"海辰储能（HiTHIUM）在慕尼黑举办的The smarter E Europe展会上展示了其∞Power 6.9 MWh长时储能（LDES）系统。该系统专为8小时应用场景设计，可提供超过10,000次的循环寿命。这是该产品在欧洲的首次正式亮相，展示了海辰储能在长时储能技术领域的长期布局。该技术旨在为欧洲电气化提供可靠的柔性电力支撑，是整合可再生能源、提升电网韧性和能源安全的关键推动因素。","scd":null,"kp":["系统容量[HiTHIUM长时储能(LDES)系统]: 6.9 MWh","放电时长[HiTHIUM长时储能(LDES)系统]: 8小时"]},{"i":3524,"as":"中国发布了三项关于光伏行业能耗和能效的强制性国家标准，旨在遏制产能过剩并重塑行业制造规范。新规涵盖多晶硅、硅片、光伏组件和逆变器整个产业链，代号分别为GB 29447-2026等。这些标准已于2026年6月27日发布，并将于2027年1月1日正式生效。此举将推动制造业、采购和项目选择向更高能效、更低能耗强度的产品倾斜。","scd":null,"kp":["能耗标准生效时间[中国光伏价值链强制要求]: 2027年1月1日"]},{"i":3525,"as":"由苏州大学主导的中国科研团队研发出一种用于倒置钙钛矿太阳能电池的双分子界面层技术。该技术通过共组装两种基于咔唑的分子来锁定分子排序，有效抑制了缺陷与应力，提升了电荷提取效率和界面稳定性。优化后的太阳能电池设备达到了27.3%的光电转换效率，并在长期光浸泡和户外测试中展现出优异的运行稳定性。","scd":null,"kp":["光电转换效率[双分子界面倒置钙钛矿太阳能电池]: 27.3%","界面改性作用[倒置钙钛矿电池]: 锁定分子排序、抑制缺陷和应力、改善电荷提取和界面稳定性"]},{"i":3526,"as":"根据智利国家能源委员会（CNE）6月发布的月度报告，截至2026年5月，智利可再生能源装机总量达到20,006兆瓦，占全国总发电装机容量的52%。其中，太阳能光伏装机容量达到12.18吉瓦（12,184兆瓦），约占可再生能源装机容量的61%。此外，4月份光伏发电量达到1,825吉瓦时，占当月国家电力系统可再生能源发电量的55%以上。","scd":null,"kp":["光伏装机容量[截至2026年5月智利电力系统]: 12.2 GW","可再生能源装机容量[智利全国]: 20,006 MW","光伏发电量[2026年4月智利国家电力系统可再生能源]: 1,825 GWh"]},{"i":3527,"as":"国际研究团队设计了一种适用于受控环境作物种植的农业光伏冷架系统。该系统集成了半透明光伏组件，能够为农作物创造可控的小气候，从而延长生长季节。在加拿大进行的田间试验表明，该系统不仅实现了小规模的现场太阳能发电，还显著提高了生菜的产量，证明了光伏发电与农业生产结合的有效性。","scd":null,"kp":["农业光伏冷架系统[受控环境作物种植]: 集成半透明光伏组件以创造受控微气候","[加拿大田间试验]: 显著提高生菜产量并实现小规模现场太阳能发电"]},{"i":3528,"as":"亚洲开发银行已批准一项1.6亿美元的贷款，用于支持不丹的太阳能扩建项目。该项目将建设三座太阳能发电厂，总装机容量达310兆瓦。这是不丹能源领域首个由私营资本占多数的公私合营（PPP）项目。其中两座位于不丹北部布姆唐的光伏电站将由Druk Green Power Corporation建设，另一座为150兆瓦的Dramthang项目。","scd":null,"kp":["项目总容量[不丹太阳能扩建项目]: 310 MW","贷款金额[亚洲开发银行]: 1.6亿美元"]},{"i":3529,"as":"华威大学和莫纳什大学的研究人员揭示了细菌如何利用相同的生物机制自然合成多种强效抗癌化合物的长期谜题。这一发现阐明了自然界的分子组装过程，有助于科学家利用细菌酶，通过组合生物合成技术开发出治疗难治性癌症的新型药物变体。","scd":null,"kp":["合成机制[细菌天然产生抗癌化合物]: 揭示细菌如何自然产生多种强效抗癌化合物版本的机制"]},{"i":3530,"as":"","scd":null,"kp":[]},{"i":3531,"as":"一项针对印尼婆罗洲野生红毛猩猩的20年研究显示，这些类人猿会有选择性地摄入具有抗菌、抗炎和伤口愈合特性的植物，表现出“自我治疗”的行为模式。研究发现，红毛猩猩会以特定顺序食用特定的植物组合，这种类似于其他动物的自疗行为表明它们可能在寻找常规食物之外的自然药用植物。","scd":null,"kp":[]},{"i":3532,"as":"三项发表在ACS期刊上的最新研究揭示了烟花对环境的长期污染影响。实验室研究表明，烟花燃烧后会留下包含部分燃烧的燃料、添加剂、金属盐和烧焦包装在内的废弃物。这些残留物会将大量化学物质释放到大气和水体中，在烟花表演结束后的很长一段时间内，对生态环境和人类健康造成严重危害。","scd":null,"kp":[]},{"i":3533,"as":"广东脉络能源科技研发的30×30平方厘米超轻柔钙钛矿太空光伏组件，经TÜV北德认证光电转换效率达21.79%，为同级别世界最高之一。其功率质量比达26瓦/克，处于国际领先水平。该组件具备轻量化、可折叠和规模化生产潜力，能满足商业航天对低成本、高频次空间电力的需求，未来仍需完成系统级验证以达航天级可靠性标准。","scd":null,"kp":["光电转换效率[30×30 cm²超轻柔钙钛矿太空光伏组件]: 21.79%","功率质量比[超轻柔钙钛矿太空光伏组件]: 26 W/g"]},{"i":3534,"as":"","scd":null,"kp":[]},{"i":3535,"as":"快手宣布其人工智能视频生成部门Kling AI正在进行新一轮融资，该部门在此次融资中的估值达到150亿美元。","scd":null,"kp":[]},{"i":3536,"as":"软银计划将其持有的人工智能计算能力出租给美国的各大公司，以提供算力支持。","scd":null,"kp":[]},{"i":3537,"as":"","scd":null,"kp":[]},{"i":3538,"as":"","scd":null,"kp":[]},{"i":3539,"as":"OpenAI讨论了美国政府在其公司中可能持有的股份规模。","scd":null,"kp":[]},{"i":3540,"as":"","scd":null,"kp":[]},{"i":3541,"as":"海尔布隆大学在Thomas Gessmann基金会的支持下，开设了一个配备先进设备的新型氢能实验室，用于氢能相关技术的调查研究。","scd":null,"kp":[]},{"i":3542,"as":"","scd":null,"kp":[]},{"i":3543,"as":"印度储能联盟（IESA）与Customized Energy Solutions的报告预测，印度工商业可再生能源部署量将从2025年的32吉瓦增长至2032年的100吉瓦，其中工商业储能系统的装机容量将在未来七年内增长超十倍，达到31吉瓦时。","scd":null,"kp":["工商业储能部署量[印度]: 超31 GWh","工商业可再生能源部署量[印度]: 32 GW (2025年)至100 GW (2032年)"]},{"i":3544,"as":"清洁能源开发商GreenPoint Energy在南澳大利亚的Koolunga构网型电池储能项目完成融资交割，并与全球能源贸易公司Gunvor Group签署长期承购协议，通过Gunvor为Firmus Technologies计划在南澳建设的大型人工智能工厂提供稳定的可再生电力。","scd":null,"kp":[]},{"i":3545,"as":"Green Flexibility基于其位于德国巴伐利亚州15兆瓦/33兆瓦时电池项目的实际运营经验及与多家配电网运营商的谈判结果，开发了一套灵活并网协议模板。该模板旨在为未来的灵活电网连接提供实用参考，明确实用条款并指出限制灵活性的因素。","scd":null,"kp":["储能规模[巴伐利亚Immenstadt电池项目]: 15 MW/33 MWh"]},{"i":3546,"as":"Engie与Ignis签署了一项为期10年的长期灵活性购买协议，涵盖西班牙总装机容量为625兆瓦时的多个电池储能项目。电池计划于2028年投入运营，通过在可再生能源发电高峰期储电并在高需求时放电来降低市场波动风险。Ignis将负责运营并优化其在电力系统平衡服务中的表现。","scd":null,"kp":["总装机容量[西班牙BESS项目]: 625 MWh","灵活性购买协议[西班牙BESS项目]: 10年期"]},{"i":3547,"as":"总部位于加州的住宅电池供应商FranklinWH计划于2027年进入欧洲市场。公司将针对欧洲市场推出基于磷酸铁锂棱柱电池的下一代20千瓦/15千瓦时aPowerS电池及配套的aGate能源管理系统。","scd":null,"kp":["市场进入时间[欧洲住宅电池VPP试点]: 2027年"]},{"i":3548,"as":"丹麦开发商European Energy在澳大利亚维多利亚州完成的130兆瓦太阳能和100兆瓦/220兆瓦时电池储能混合项目已实现融资交割。商业银行和法国兴业银行提供融资，亚马逊云服务（AWS）签署了该项目的太阳能和电池储能购电协议，将利用这些电力支持其在澳不断扩展的数据中心和云基础设施。","scd":null,"kp":["装机容量[澳大利亚Winton North太阳能]: 130 MW","装机容量[澳大利亚Winton North储能系统]: 100 MW","储能容量[澳大利亚Winton North储能系统]: 220 MWh"]},{"i":3549,"as":"Orica公司已就猎人谷氢中心项目达成最终投资决定（FID）。","scd":null,"kp":["[猎人谷氢中心]: 达成最终投资决定"]},{"i":3550,"as":"ACME与IHI的联合项目已获得政府支持，旨在向日本进口氨产品。","scd":null,"kp":["[ACME-IHI日本氨进口联合项目]: 获得政府支持"]},{"i":3551,"as":"IHI公司完成了一项100%纯氨燃烧锅炉的测试运行。此外，由ACME和IHI联合开展的向日本进口氨气的项目已获得政府的支持。","scd":null,"kp":["[IHI氨燃烧锅炉]: 完成100%氨燃烧测试"]},{"i":3552,"as":"行业专家指出，新能源汽车应从单纯增加重量转向追求高能效。由于动力系统向电动化转变及对续航要求的提升，新能源车增重具有技术必然性。行业目标应转向高效、轻量化，寻求全生命周期成本优化、能效跃升与资源节约，客观理性地看待新能源车与燃油车的结构及重量差异。","scd":null,"kp":["平均整备质量[2026年1-4月中国新能源乘用车]: 1939.3千克","整备质量增幅[2026年对比2020年中国新能源乘用车]: 增长27.5%","[新能源汽车发展导向]: 从“拼重量”转向“拼效率”（追求高效、轻量化）"]},{"i":3553,"as":"武汉中铁伊通零碳综合物流园配备的全球首座汽车零部件物流领域新能源重卡底盘式换电站，能在4分22秒内全自动完成电池更换。园区结合光伏储能，每年可大量节约标准煤并减少二氧化碳排放。此外，园区通过VMI仓储和循环取货模式，2小时内即可将零部件配送至汽车主机厂产线，显著降低物流成本。","scd":null,"kp":["换电耗时[新能源重卡底盘式换电站]: 4分22秒","节能减排量[光伏储能换电物流园区]: 每年节约1574.4吨标准煤，减少二氧化碳排放4785.6吨","单车碳减排[新能源重卡]: 每车每年预计减少二氧化碳排放超40吨","运输能耗成本降幅[汽车零部件运输]: 降低约25%"]},{"i":3554,"as":"长城钻探工程公司自主研发出国内首个具备双向调节能力的晶核类新材料——晶核双向诱导材料，填补了国内技术空白。经检测，该材料在低温条件下12小时强度比大于200%，在240摄氏度超高温环境中28天强度衰退率低于3%。该技术基于“晶核效应”和“模板效应”，有效解决了固井工程中高温强度衰减、低温强度增长缓慢的共性难题，既可与常规固井水泥配套使用，也可应用于地质聚合物材料体系。","scd":null,"kp":["强度比[晶核双向诱导材料低温12小时]: 大于200%","强度衰退率[晶核双向诱导材料240℃超高温28天]: 低于3%","核心技术[固井核心材料]: 国内首个具备双向调节能力的晶核类新材料"]},{"i":3555,"as":"海光信息与南方电网数字电网科技公司联合成立电鸿数智创新联合实验室。双方依托海光CPU+DCU“双芯”引擎与国产电力“电鸿”操作系统，共建能源领域自主可控算力示范平台。实验室聚焦数字电网智能终端与行业中间件方向，开展软硬件兼容适配和性能调优，推进国产化算力技术在发电、输电、变电、配电、用电全流程以及电网智能决策等高价值场景的落地应用。","scd":null,"kp":["[电鸿数智创新联合实验室]: 依托海光CPU+DCU“双芯”引擎与国产化电力“电鸿”共建能源领域自主可控算力示范平台","核心攻坚方向[数字电网专属国产服务器及硬件]: 国产软硬件兼容适配与系统性能深度优化"]},{"i":3556,"as":"国内首套投跳闸变压器故障主动防御装置在特高压天津南变电站成功投运。该装置融合局部放电监测与继电保护技术，在变压器放电较小时准确报警，在爆燃前正确跳闸切断能量来源。装置采用双套双冗余设计，33套试运行的装置在180多万次各类干扰下未发生误动，并在171次真实故障试验中精准动作，实现电力安全防护从事后补救向事前预防转变。","scd":null,"kp":["防御装置[变压器故障]: 融合局放监测和继电保护技术","[变压器爆燃预防]: 放电较小时准确报警，在爆燃前正确跳闸切断能量来源"]},{"i":3557,"as":"东壁科技数据与上海财经大学联合发布全球大语言模型科技安全防范能力测评报告。测评构建了包含313条问题的测试集，覆盖生物化学、网络安全等领域，选取近10万份科技文献作为参考，对全球38个大语言模型进行全景式扫描。测评发现，科技内容的可靠性高不等于绝对安全，大模型安全测评正从单一的“关键词屏蔽”转向综合风险评价，为全球AI治理提供参考。","scd":null,"kp":["测试集规模[大模型科技安全防范能力测评]: 313条问题","测试样本[全球大语言模型]: 38个","参考材料[科技可靠性评估]: 近10万份科技文献"]},{"i":3558,"as":"国家航天局宣布我国将建立近地小行星天地协同监测体系，以防御小行星撞击。我国正在论证小行星防御系统并加快构建天地一体化网络：在地基方面，将建立多台大口径光学望远镜形成均衡布局；在天基方面，计划部署天基监测星座，克服大气干扰实现全天候观测。我国已初步突破小行星撞击风险预警模型和算法，目前应对威胁主要包括动能撞击和持续推离两类技术。","scd":null,"kp":["天体直径[通古斯小行星撞击事件]: 约50米","破坏范围[通古斯小行星撞击事件]: 超过2000平方公里森林","监测体系[近地小行星防御]: 天地一体化/天地协同"]},{"i":3559,"as":"上半年A股市场呈现显著分化，科技板块大幅领跑。创业板指与科创综指分别累计上涨35.58%和53.99%。行业板块中，电子、通信分别大涨86.29%和73.59%，而传统消费行业跌幅明显。全市场共有362只个股翻倍，集中在半导体等AI相关科技产业。杠杆资金显著攀升，融资融券余额增长近5000亿元至3.02万亿元，机构普遍认为科技仍将是市场主线。","scd":null,"kp":["累计涨幅[创业板指]: 35.58%","累计涨幅[科创综指]: 53.99%","累计涨幅[电子行业]: 86.29%","累计涨幅[通信行业]: 73.59%"]},{"i":3560,"as":"","scd":null,"kp":[]},{"i":3561,"as":"工信部等八部门印发《关于推动工业互联网高质量发展的实施意见》，提出到2030年核心产业增加值突破2.5万亿元，融合应用实现207个工业中类全覆盖。目前我国工业互联网核心产业规模超1.6万亿元，已迈过规模化门槛进入提质增效阶段。通过与5G、大数据、AI等新一代信息技术深度融合，工业互联网正实现低延迟、高稳定的生产线实时协同，全面释放数据价值。","scd":null,"kp":[]},{"i":3562,"as":"北京天文馆面向公众开放《哦吼！火星》火星探测与未来生活体验展。展览依托深空探测数据，融合实物标本、沉浸式场景、多元互动装置与创意艺术设计，真实还原火星地貌并展现星际探测历程。通过打造可触摸、可沉浸、可动手实践的科普体验，向大众展示未来人类在火星驻留的生活图景。","scd":null,"kp":[]},{"i":3563,"as":"2026全球数字经济大会在北京国家会议中心开幕。大会以“建设数字友好城市——智惠无界，数联全球”为主题，聚焦人工智能、数字治理、数据要素等关键核心议题。大会致力于呈现数字经济新成果，推动全球数字经济领域的交流合作与技术应用落地。","scd":null,"kp":[]},{"i":3564,"as":"重庆传统摩托车产业正向高端化、智能化转型。2025年重庆摩托车产量达785.7万辆，占全国总产量35.5%，出口占比达77.8%。本土企业“张雪机车”等在世界超级摩托车锦标赛中多次夺冠，打破欧美日品牌垄断；虬龙科技等企业在高端产品打造与绿色低碳转型赛道上表现突出。重庆依托制造业基因，通过优化技术与人才配置，实现了摩托车产业的高质量发展。","scd":null,"kp":["摩托车产量[2025年重庆]: 785.7万辆","全国占比[2025年重庆摩托车产量]: 35.5%","出口量[2025年重庆摩托车]: 610.9万辆","出口占比[2025年重庆摩托车产量]: 77.8%"]},{"i":3565,"as":"人社部数据显示，近期互联网企业集中释放超20万个就业岗位，“AI+”人才需求持续攀升。头部企业如腾讯、字节跳动提供大量AI算法、大模型应用等岗位。2026年前5个月，人工智能、芯片工程师应届职位数显著增长。岗位结构发生深刻变化，“AI+”职位快速渗透至电商、医疗、高端装备与智能制造等实体经济板块，企业对懂业务逻辑并推动技术落地的复合型AI人才需求迫切。","scd":null,"kp":["释放岗位[互联网企业云端招聘月]: 超20万个","招聘规模[腾讯AI及相关岗位]: 8000余人","招聘规模[字节跳动岗位]: 约7000个","同比增长[2026年1-5月人工智能应届职位数]: 28.4%","同比增长[2026年1-5月芯片工程师应届职位数]: 21.0%"]},{"i":3566,"as":"AI正从工业单点效率工具进化为驱动千行百业系统性变革的“智能体”。在2026全球数字经济大会上，业内展示了AI在工程软件、法律及汽车座舱等领域的应用。例如，AI公路算量产品在10天内完成46座桥梁精细化复核，整体提效约4.5倍，全正向出图率达90%。AI正依托高价值场景与高质量数据重塑业务流程，推动数字能力向终端普及，释放数据要素价值。","scd":null,"kp":["核算耗时[AI辅助46座桥梁精细化复核]: 10天","综合创效[AI辅助公路算量]: 超百万元","算量提效[AI辅助路基、桥涵等专业]: 约4.5倍","全正向出图率[AI辅助设计试点项目]: 90%"]},{"i":3567,"as":"","scd":null,"kp":[]},{"i":3568,"as":"东莞模德宝智能科技有限公司运用“AI+工业互联网+智能制造”技术，打造了精密模具制造与产品注塑智能工厂。该工厂聚焦智能硬件与潮玩领域的精密模具研发制造，实现模具生产的自动化率高达90%，整体生产效率提升30%，成为东莞人工智能重点企业及精密模具行业数字化转型的标杆。","scd":null,"kp":["自动化率[精密模具智能工厂]: 90%","生产效率提升[精密模具智能工厂]: 30%"]},{"i":3569,"as":"全国政协“委员科学讲堂”在京举办主题为“‘中国天眼’结构创新”的科普讲座。全国政协委员、哈尔滨工业大学副校长范峰详细讲解了项目研究背景、巨型反射面的结构总体方案、关键技术以及模型试验等核心内容，并与现场观众进行交流互动，向公众科普了中国天眼在建筑工程结构领域的创新成果。","scd":null,"kp":[]},{"i":3570,"as":"德国相关机构正式启动了针对可调度产能的招标登记程序。此举旨在推动能源结构转型，通过招标机制配置可调度的新能源产能，提升电力系统的灵活调节能力与整体运行稳定性。","scd":null,"kp":["[可调度产能招标]: 德国机构启动登记程序"]},{"i":3571,"as":"三菱瓦斯化学与ACME达成协议，将每年从ACME购买10万吨绿色甲醇。这一交易进一步推动了绿色替代燃料在化工领域的商业化应用与市场拓展，支持了全球能源结构的低碳化转型。","scd":null,"kp":["绿色甲醇采购量[三菱瓦斯化学从ACME购买]: 100,000吨/年"]},{"i":3572,"as":"Metacon成功获得政府资助，用于在瑞典建设一个10兆瓦的绿色制氢项目。该项目将依托政府资金支持，推进绿色氢能基础设施的本土化建设与商业化运营，助力实现清洁能源的规模化生产与供应。","scd":null,"kp":["项目规模[瑞典绿色H2项目]: 10MW","[政府资助]: Metacon获得"]},{"i":3573,"as":"广东省能源局公布2026年第二季度接网消纳困难区域名单。受限区域主要涉及韶关、河源等7个地市的23个县区共106个镇街。经评估，上述消纳受限镇域的低压配电网接网预警等级均为“受限”，在广东省分布式电源承载力查询平台中标记为“红色”，其余区域预警等级则为“良好”或“一般”。","scd":null,"kp":["接网消纳困难区域[广东省2026年第二季度分布式光伏]: 涉及7个地市23个县（市、区）106个镇（街）","接网预警等级[消纳受限镇域低压配电网]: 受限（对应承载力查询平台红色）"]},{"i":3574,"as":"云南省印发2026年绿电制氢一体化示范项目清单，以促进绿色电力消纳和推动绿色氢(氨醇)产业试点示范。通知要求：加强项目用地、环评等要素保障，提高审批效率；强化全生命周期管理，定期通过数字能源平台更新进度，进展缓慢且整改不力的项目将被调整退出清单；做好后续批次项目储备，挖掘绿氢应用场景。项目业主须依法办理各项报件手续。","scd":null,"kp":["[云南省2026年绿电制氢一体化示范项目]: 印发项目清单并加强全生命周期管理及要素保障"]},{"i":3575,"as":"本周单晶硅片价格因供应增加和成本降低而承压下行。多晶硅价格探底导致硅片成本支撑减弱，终端装机需求疲软致使下游采买低迷，叠加部分企业提高开工负荷，库存压力进一步增大。尽管硅片价格已跌破多数厂商生产成本且相关能耗限额政策已发布，但供大于求的格局难以改善，预计后续市场仍将偏弱运行。","scd":null,"kp":["产品厚度[单晶硅片主流规格]: 130μm","[硅片市场行情]: 供应增加、成本支撑减弱且需求疲软，价格承压下行"]},{"i":3576,"as":"山东省海洋局对大唐寿光营里420MW光伏发电项目海域使用论证报告书进行评审前公示。项目位于潍坊市寿光市，用海面积444.7270公顷。项目总投资13.7亿元，交流侧与直流侧装机容量分别为420MW和517.69MWp，拟采用750Wp单晶双面双玻组件，建设工期为12个月。","scd":null,"kp":["交流侧装机容量[大唐寿光营里光伏项目]: 420MW","直流侧装机容量[大唐寿光营里光伏项目]: 517.69MWp","组件规格[大唐寿光营里光伏项目]: 750Wp单晶双面双玻组件","项目投资[大唐寿光营里光伏项目]: 137000万元","用海面积[大唐寿光营里光伏项目]: 444.7270h㎡"]},{"i":3577,"as":"山西省能源局印发通知，启动2026年分布式可再生能源发电项目申报工作。申报范围涵盖农光互补、渔光互补及小型地面电站等参照集中式管理的光伏项目。通知要求对无实质性进展项目进行废止或核减，光伏与风电项目原则上需在年内或12个月内全容量并网。严禁项目在全容量并网后5年内擅自转让，申报和运营单位必须为同一主体。","scd":null,"kp":["并网期限[山西分布式光伏项目原则要求]: 年内全容量并网","并网期限[山西风电项目]: 12个月内全容量并网","转让限制[建设期和全容量并网后]: 5年内严禁擅自转让"]},{"i":3578,"as":"郑州航空港经济综合实验区公示总规模450MW的光伏发电项目EPC中标候选人。项目分为三个标段，每个标段150MW，招标人为郑州航空港区豫州新能源有限公司。标段一吸引了中国电建、中铁三局、中建等17家企业或联合体参与投标竞争。各投标企业给出了具体的项目报价数据。","scd":null,"kp":["项目规模[郑州航空港分布式光伏EPC]: 合计450MW（分三个标段，每个150MW）"]},{"i":3579,"as":"重庆巫山县发布分布式屋顶光伏发电项目风险告知书，明确备案属告知性程序，不代表政府背书。提示居民防范四类常见风险：一是虚假宣传误导；二是劣质设备及施工导致的安全隐患及房屋结构破坏；三是骗取证件信息诱签合同，致使居民承担还贷责任的金融诈骗；四是约定异地争议管辖、收益划转他人等增加维权成本的合同争议风险。","scd":null,"kp":["管理机制[重庆巫山分布式屋顶光伏]: 实行告知性备案管理，遵循“谁投资、谁备案、谁负责”原则","[常见风险提示]: 防范虚假宣传误导及使用劣质设备、无视房屋承载能力等安全隐患"]},{"i":3580,"as":"内蒙古锡林浩特市计划使用256.399933万元资金扶持牧区购置安装新能源光伏发电设备。资金来源包括中央及自治区多项结余与下拨资金，以及牧户自筹27.2万元。项目建设内容为配套安装20千瓦光伏发电设备，建设地点分布在巴彦宝拉格苏木等四个苏木乡镇，旨在为当地牧户提供新能源设施。","scd":null,"kp":["项目总资金[锡林浩特市牧区光伏设备扶持]: 256.399933万元","光伏发电设备单机装机容量[牧区新能源项目]: 20千瓦"]},{"i":3581,"as":"江苏常州市发展改革委公示2026年常州市近零碳试点园区名单。该评选依据《近零碳园区和近零碳工厂试点建设三年行动方案》展开，经园区申报、辖市区推荐及专家评审等程序，最终拟定将8个园区列入2026年近零碳试点园区建设计划，公示期为7月1日至7月7日。","scd":null,"kp":["试点园区数量[常州市近零碳园区建设计划]: 8个"]},{"i":3582,"as":"本周供应链热门新闻聚焦三家企业的创新与战略调整。捷豹路虎(JLR)与40余家供应链伙伴合作，研发了一款包含49个可持续零部件的概念车，实现超过一吨的二氧化碳减排；保时捷调整战略以提升供应链韧性；欧莱雅则在供应链创新方面取得进展。","scd":null,"kp":["可持续汽车零部件应用数量[JLR概念车闭环供应链]: 49个"]},{"i":3583,"as":"宁德时代(CATL)支持的巧克力换电网络实现快速扩张，于6月30日部署了第2000座换电站，2026年上半年月均部署量超200座。宁德时代正朝着2026年底在中国大陆和香港建成并运行3000座换电站的目标推进。此前，该公司已与国内车企联合开发了10款采用其可更换电池的电动汽车车型。","scd":null,"kp":["换电站建设速度[CATL Choco-SEB换电网络2026年月均部署]: 超过200个/月","换电站累计部署量[Choco-SEB换电网络截至2026年6月30日]: 2000个","换电站建设目标[Choco-SEB换电网络规划]: 3000个"]},{"i":3584,"as":"通用汽车(GM)仅生产一个年份的2027款雪佛兰Bolt电动汽车目前面临高库存问题。尽管该车型在2026年第二季度售出3433辆，销量表现稳健，但经销商库存高达118天，远超60天的健康库存标准，总库存量超4500辆。这一现象表明市场供应量超出了实际销售消化能力。","scd":null,"kp":["经销商库存水平[2027款雪佛兰Bolt电动汽车]: 118天供应量","健康库存行业标准[汽车经销商行业]: 60天供应量"]},{"i":3585,"as":"","scd":null,"kp":[]},{"i":3586,"as":"","scd":null,"kp":[]},{"i":3587,"as":"","scd":null,"kp":[]},{"i":3588,"as":"","scd":null,"kp":[]},{"i":3589,"as":"","scd":null,"kp":[]},{"i":3590,"as":"工程师在 Sanford 地下研究设施 发现，降落的雨水会意外地逆转深层地下的气流。这一发现解决了一个长期困扰地下工程设施的谜团，揭示了水与空气系统之间的相互作用。这一现象的破解对于提升大型地下矿井和设施的通风与安全管理具有重要意义。","scd":null,"kp":["[深层地下设施气流系统]: 降雨渗入的雨水能够逆转深层地下气流方向"]},{"i":3591,"as":"","scd":null,"kp":[]},{"i":3592,"as":"","scd":null,"kp":[]},{"i":3593,"as":"剑桥大学主导的研究团队发现，对锂离子电池施加持续的物理压力可使其使用寿命延长一倍。研究发表在《自然·能源》杂志上，实验使用专用气动设备对软包电池施加精确最佳范围内的压力。结果表明，精确控制堆叠压力可以有效抑制机械膨胀并改变电池的降解途径。","scd":null,"kp":["电池寿命提升效果[锂离子电池施加持续物理压力]: 可延长一倍","[锂离子电池退化路径]: 电芯堆栈压力与机械膨胀之间存在相互作用机制"]},{"i":3594,"as":"达飞轮船（CMA CGM）以14亿美元收购联邦快递供应链子公司，预计于2026年底完成交易。作为集团子公司，CEVA物流将整合该资产，使其北美业务规模扩大三倍，成为北美领先的物流提供商。此次收购彰显了达飞轮船加速物流业务发展及对美投资25年的承诺。","scd":null,"kp":["收购金额[达飞轮船收购联邦快递供应链子公司]: 14亿美元"]},{"i":3595,"as":"","scd":null,"kp":[]},{"i":3596,"as":"亚马逊发布2025年可持续发展报告，展示了在业务扩张中通过基础设施调整与新技术应用，实现业务增长与碳排放脱钩。亚马逊已连续三年实现全球运营100%可再生能源匹配，其无碳能源项目组合达712个，总容量达42GW，以支持不断增长的数据中心需求。","scd":null,"kp":["[企业增长与碳排放关系]: 依托人工智能和供应链优化，实现业务增长与碳排放脱钩"]},{"i":3597,"as":"比亚迪全新旗舰电动轿车Seal 08在国内上市，售价低于3万美元。该车在开售前30小时内即锁定约6.5万辆订单。近年来，比亚迪以高性价比电动汽车闻名，并迅速扩展了包括电动超跑、旗舰SUV及畅销车型在内的丰富电动汽车产品线。","scd":null,"kp":["锁定订单量[比亚迪Seal 08旗舰电动轿车上市前30小时]: 约6.5万辆","车辆售价[比亚迪Seal 08]: 低于3万美元"]},{"i":3598,"as":"在不列颠哥伦比亚省的高速公路上，一名特斯拉驾驶员在时速约100公里时被拍到在驾驶座熟睡，车内还有两名熟睡儿童。特斯拉驾驶员监控系统未能及时干预的原因是该驾驶员佩戴了宽大的太阳镜，这一细节暴露了特斯拉在驾驶员状态监控方面存在技术盲区。","scd":null,"kp":["行驶速度[特斯拉驾驶员睡着状态]: 约100 km/h","[特斯拉驾驶员监控系统失效原因]: 驾驶员佩戴大号太阳镜导致系统识别存在盲区"]},{"i":3599,"as":"波音支持的eVTOL初创公司Wisk Aero遭到前员工起诉。前员工指控公司未满足基本航空软件测试要求，并在她通过内部系统正式报告这些安全隐患后将其解雇。该员工此前负责主导飞行器车辆管理系统的软件集成工作。","scd":null,"kp":["[Wisk eVTOL自动驾驶飞行出租车软件测试]: 被指控未满足基本航空软件测试要求即仓促进行"]},{"i":3600,"as":"经过长期的详细实车测试，2026年7月各价位段最佳电动自行车榜单出炉。文章根据不同的价格区间进行划分，涵盖了从1000美元以内到2000美元以上的推荐车型，为消费者在各个预算范围内购买电动自行车提供了参考。","scd":null,"kp":[]},{"i":3601,"as":"美国太阳能产业目前支持超过28万名员工，但仍难以招募足够的合格人员以满足加速的项目进度。据报告预测，为支撑60至70GW的安装目标，到2026年底该行业需约35.5万名工人。这导致短期内出现约5.3万个职位的缺口，加剧了行业间的劳动力争夺。","scd":null,"kp":["从业人员规模[美国太阳能行业]: 超过28万人"]},{"i":3602,"as":"挪威垂直光伏专家Over Easy Solar在加拿大温哥华科学世界博物馆完成了其首个商业垂直太阳能装置。该项目是当地3900万加元建筑翻新的一部分。当地公用事业公司BC Hydro正在监测该装置，计划在冬季降雪构成挑战的地区推广垂直光伏技术。","scd":null,"kp":["[垂直光伏系统(加拿大温哥华)]: 首个商业安装项目，旨在应对冬季降雪挑战"]},{"i":3603,"as":"德国Htrius公司推出两款被动外骨骼，旨在减少光伏系统安装与维护人员的体力消耗并改善人体工程学。这款名为BionicBack的外骨骼专为减轻重复弯腰和搬运重物时的身体劳损而设计，适用于安装光伏组件、铺设电缆及搬运材料等施工作业。","scd":null,"kp":["[被动外骨骼(光伏安装与维护应用)]: 旨在减少工人体力消耗并改善人体工程学"]},{"i":3604,"as":"柏林可持续发展转型中心发布的第三版研究报告显示，欧洲B2C光伏市场并不存在人们普遍认为的大型企业主导现象。尽管受限于估算数据，该报告仍明确指出，在涵盖光伏系统、热泵和能源管理等相关技术的终端客户市场中，并没有占据绝对优势的主导企业。","scd":null,"kp":["[欧洲B2C光伏市场格局]: 缺乏真正占据主导地位的大型企业"]},{"i":3605,"as":"华为在The smarter E 2026展会上发布了未来电力系统并网战略。华为智能光伏与储能产品线总裁表示，欧洲风光发电渗透率预计到2030年将达64%。华为战略聚焦构网型一体化解决方案，旨在增强电网稳定性，以应对高比例可再生能源接入带来的电网韧性下降挑战。","scd":null,"kp":["风光渗透率[欧洲2030年预期]: 64%","[华为数字能源并网战略]: 聚焦于构网型综合解决方案以支撑高比例新能源并网"]},{"i":3606,"as":"挪威初创公司Fred. Olsen 1848为其研发的浮动光伏系统取得了技术验证。该Brizo系统专为动态海洋环境设计，能够承受高达3.5米的波浪。系统采用预紧索网，每个浮体独立锚固以防止负载转移，在强风下浮体会贴近水面以保持阵列整体稳定性。","scd":null,"kp":["耐受波高[挪威Brizo浮动光伏系统]: 高达3.5米"]},{"i":3607,"as":"随着国内电价飙升至东南亚最高水平且光伏面板成本下降，菲律宾对太阳能的需求持续激增。2026年3月和4月，中国太阳能面板出口量创历史新高。据分析，目前约有超过3GW的中国太阳能面板出口目的地为菲律宾。","scd":null,"kp":["进口光伏组件规模[菲律宾市场预期]: 约3 GW（来自中国）","[菲律宾住宅电价]: 东南亚最高水平"]},{"i":3608,"as":"POWEROAD通过Circulor平台获得了必维国际检验集团颁发的中国首张试点电池护照。这一举措标志着在欧盟电池法规下数字电池护照的早期实施，为电池行业满足合规要求迈出重要一步，并有助于提高电池全生命周期的透明度。","scd":null,"kp":["试点电池护照[POWEROAD获颁]: 中国首个（由必维国际通过Circulor平台颁发）"]},{"i":3609,"as":"中国制造商Solax推出了基于云AI技术的住宅光伏能源管理系统XHub。该系统重量仅为600克，能够分析动态电价、天气、家庭能耗和电网状态。在XSchedule AI引擎驱动下，系统可实现秒级智能调度，优化充放电并降低用电成本，缩短光伏投资回报期。","scd":null,"kp":["设备重量[Solax XHub能源管理系统]: 600 g","核心功能[住宅光伏系统]: 基于云端AI分析动态电价、天气、能耗及电网状态"]},{"i":3610,"as":"一种紧凑型中压串联调节器可使德国配电网的光伏容量增加260%。该技术通过主动控制电压，能够在无需额外土建施工的情况下直接安装在现有的变电站中。与传统电网扩建相比，该方案为电网运营商高效利用现有电力线路提供了更快速的替代方案。","scd":null,"kp":["光伏发电容量[配电网使用中压串联调节器]: 增加260%","安装特点[中压串联调节器]: 可直接安装在现有变压器站内，无需额外建设"]},{"i":3611,"as":"由半导体资深专家魏少军领导的中国AI芯片初创公司东方算芯已正式亮相。面对美国出口管制对高端AI芯片和制造工具的限制，这家位于上海的初创公司正利用3D堆叠技术进行研发，致力于构建自主可控的AI算力生态系统。","scd":null,"kp":["应对策略[中国AI芯片初创公司规避美国限制]: 采用3D堆叠技术"]},{"i":3612,"as":"桑迪亚国家实验室开发出一种名为分布式能源资源管理系统（DERMS的新型智能电网软件平台。由于AI数据中心扩张给电网带来压力，极易引发电压不稳定的电力尖峰。该平台利用AI技术，有效解决传统机械电网设备响应过慢的问题，防止数据中心因电压骤降而受到损坏。","scd":null,"kp":["软件平台[应对AI数据中心需求引起的电压波动]: 分布式能源管理系统 (DERMS)"]},{"i":3613,"as":"南洋理工大学和早稻田大学的科学家为遥控半机械蟑螂研发了一款3D打印“潜水服”。这项装备使机械蟑螂能够在水下或低氧环境中呼吸和导航长达3小时。这项技术将陆生半机械昆虫转化为两栖工具，适用于在洪涝灾区等复杂环境中执行搜救任务。","scd":null,"kp":["装备特点[远程控制半机械蟑螂]: 配备3D打印“潜水服”","作业时长[水下或低氧灾区环境]: 可存活并导航长达一定时间（文本截断）"]},{"i":3614,"as":"泰雷兹推出了一款新型搜索着陆灯（SLL），旨在提升直升机在搜救和夜间军事部署等任务中的能见度与安全性。该系统具备360度连续照明能力，采用紧凑的齐平安装设计以降低传统外部探照灯的空气动力学影响，并集成了软件定义功能以提供更高灵活性。该系统可与机载任务系统直接集成，消除了常规照明系统的盲区，主要面向军事、安全和搜救领域。","scd":null,"kp":["照明范围[泰雷兹直升机搜索着陆灯]: 360度","设计特征[直升机照明系统]: 紧凑齐平安装且具备软件定义功能，降低气动影响"]},{"i":3615,"as":"","scd":null,"kp":[]},{"i":3616,"as":"","scd":null,"kp":[]},{"i":3617,"as":"","scd":null,"kp":[]},{"i":3618,"as":"","scd":null,"kp":[]},{"i":3619,"as":"英国帝国理工学院的研究人员成功制造出一台量子传感器原型机，首次在真实的实验条件下验证了未来量子探测器的核心概念。该研究比较了两个长基线原子干涉仪（一种利用激光高精度测量原子行为的仪器），证明此举能有效抵消实验噪声，即使个体测量信号被噪声淹没也能成功提取数据。这项技术突破将支持未来对早期宇宙引力波以及特殊暗物质形态的探测。","scd":null,"kp":["降噪技术[原型量子传感器]: 对比两个长基线原子干涉仪以有效消除实验噪声"]},{"i":3620,"as":"针对工业园区风光发电存在的日周期波动和随机性出力问题，储能系统成为平抑波动的核心。风光曲线重叠率不足30%，且储能需兼顾调峰填谷、调频等多任务，要求毫秒级响应，而传统架构存在数据延迟。行业已探索出基于多时间尺度联合优化的多能互补调度思路，其核心是在“日前阶段”基于气象预测进行策略安排，以实现储能与风光发电的高效协同。","scd":null,"kp":["曲线重叠率[典型园区风光日发电]: 不足30%"]},{"i":3621,"as":"面对大面积平整光伏用地枯竭的现状，行业正探索地面集中式光伏综合解决方案以盘活荒山荒坡和滩涂盐碱地等低效闲置土地。开发面临地形复杂导致施工难、承载力低、生态脆弱易引发水土流失以及单一发电收益有限等挑战。对此，山地光伏方案采用“随坡就势”的组件排布，结合如广西河池100MW项目，实现高效发电、水土保持与生态改善的协同，推动“一地多用”。","scd":null,"kp":["设计容量损失[陡坡及陡坎地形的光伏项目]: 近30%无法按原方案施工"]},{"i":3622,"as":"随着适宜平地减少，山地光伏开发面临地形落差带来的系统性难题。地形高差和坡度多变导致传统二维设计失效，北坡超过5°至10°时阴影遮挡急剧增加，发电效率大幅下降。此外，基础施工难度大，单双立柱支架需根据地形和地质权衡稳定性与成本；生态敏感区重机械开挖也会带来不可逆破坏。选型设计必须坚持“因地制宜”的核心原则，以克服地形落差带来的设计与施工瓶颈。","scd":null,"kp":["阴影遮挡效应[山地北坡且坡度>5°至10°]: 组件阴影遮挡急剧增加，发电效率大幅下降","设计方法[传统二维设计]: 难以精准呈现山地地形，极易引发设计偏差","地形影响[山地东西向坡度变化]: 导致组件在东北、西北方向产生高差，阴影长度随坡度增加而延长"]},{"i":3623,"as":"为解决工业园区光伏发电波动性与新型负荷（如充电桩）增长、传统化石能源供热之间的错配问题，多能光储一体化方案成为零碳园区建设的核心方向。该方案基于“源-网-荷-储-充”一体化架构，以风光储为核心构建清洁网络，通过集中建设高效光伏阵列，并融合供热设备实现电热多能耦合与能源梯级利用，从而系统性解决园区的节能降碳、用能成本和配电容量瓶颈。","scd":null,"kp":["能源供需特性[园区光伏发电与工业负荷]: 存在波动性、间歇性及时段错配，单一部署难以充分就地消纳","园区建设门槛[国家级零碳园区单位能耗碳排放]: 明确硬性准入标准","系统融合架构[园区能源系统]: 光伏发电、储能调节、充电设施与供热设备需有机融合构建多能光储一体化系统"]},{"i":3624,"as":"针对高耗能制造企业电费成本居高不下的痛点，“源网荷储一体化”方案通过协同互动实现从“源随荷动”向多方协同的范式转移。通过利用厂房屋顶等资产部署自有光伏电源，企业能够由被动接受电价转为主动管理能源。结合储能与电网互动，该方案打破了单一购电模式的局限，不仅能应对国内峰谷电价差扩大和市场化电价波动，还能满足欧盟碳边境调节机制的绿电要求。","scd":null,"kp":["用电成本占比[氯碱企业电耗占总成本]: 25%至30%","年度电费支出[2025年氯碱企业]: 超过10亿元","电价水平对比[欧盟高耗能产业对比中国]: 高出近50%","出口碳门槛[欧盟碳边境调节机制]: 绿电使用比例直接关系产品出口竞争力"]},{"i":3625,"as":"分时电价机制导致工业园区白天生产高峰期面临极高的电费支出（部分地区峰谷电价差超四倍），而强制错峰生产会打乱生产节奏。真正的解决途径是“光储融合”。利用光伏在白天高价时段发电并优先自用，可直接削减电网购电量；同时能有效降低企业取电的最大功率，从而减少基本电费。这从“电从哪来”和“电怎么用”两个维度实现了“电量+需量”双降。","scd":null,"kp":["峰段电价[广东珠三角工业园区]: 1.3元/度以上","谷段电价[广东珠三角工业园区]: 约0.3元/度","峰谷电价差[广东珠三角工业园区]: 相差超过四倍","用电负荷特征[工业园区峰平谷时段]: 生产时间与峰段、尖峰段高度重合"]},{"i":3626,"as":"面对电价波动、限电风险及双碳政策压力，制造企业正通过自主供电摆脱电网依赖，主要分为三条梯度路径：门槛最低的屋顶光伏并网自用（度电成本已具优势，收益率约12%）；“光伏+储能”模式，将白天余电与夜间谷电储存并在峰期释放，大幅提升光伏自用率；以及完全脱网的独立运行模式。这些方案有效对冲了高昂的白天峰段电价，保障了连续生产的稳定性。","scd":null,"kp":["峰谷电价差[部分地区分时电价]: 峰段电价是谷段的3到4倍","供电中断风险[极端天气与负荷高峰]: 导致限电、停电，对连续生产企业造成致命冲击","自主供电路径[制造企业脱网/并网运行]: 依托光伏+储能系统组合实现自主供电"]},{"i":3627,"as":"多车间制造企业面临能耗数据分散、光储系统与生产负荷脱节、碳核算依赖人工等管理痛点。智慧能源管理方案通过打通光伏、储能与各车间负荷的数据壁垒，实现统筹调度。该方案旨在消除“发”与“用”的信息断层，使能源系统能够根据生产排程和峰谷电价实时调整供能策略，从而充分挖掘电价调节红利，满足精确到产线和批次的动态碳追溯需求。","scd":null,"kp":["数据采集方式[传统多车间能耗管理]: 人工抄表、事后统计，缺乏实时采集与统一汇聚平台","设备协同状态[多车间光储系统]: 光伏发电、储能系统与各车间生产负荷各自为政，难以统筹调度"]},{"i":3628,"as":"","scd":null,"kp":[]},{"i":3629,"as":"博通与苹果两家公司宣布，将双方的技术合作关系正式延长至2031年。","scd":null,"kp":[]},{"i":3630,"as":"针对涉及英伟达芯片的欺诈案件，新加坡方面已经提出了新的指控。","scd":null,"kp":[]},{"i":3631,"as":"在相关监管规定日益收紧的背景下，阿里巴巴和字节跳动已经停止了其个性化人工智能功能的提供。","scd":null,"kp":[]},{"i":3632,"as":"特斯拉公司将其Robotaxi（机器人出租车）服务的运营范围正式扩展到了迈阿密。","scd":null,"kp":[]},{"i":3633,"as":"韩国半导体行业的芯片工人因巨额奖金成为热门单身群体。以SK海ynix为例，公司与工会签订协议，将营业利润的10%作为奖金发放，使员工获得巨额一次性收入。三星电子今年五月也采取了类似的奖金协议。这些因新财富而经济宽裕的芯片从业者（如35岁的经理白先生），在婚恋市场上的受欢迎程度显著提升。","scd":null,"kp":["[企业员工福利]: 拥有丰厚奖金"]},{"i":3634,"as":"THWS大学正在研发名为“Taifun 17 H₂”的氢动力飞机。该项目采用模块化设计理念，并获得了航空研究领域的最新资金支持。核心研发团队包括多名科研人员、工程师及教授，致力于推动氢能源在航空领域的应用与技术开发。","scd":null,"kp":["[氢动力飞机]: 采用模块化设计"]},{"i":3635,"as":"随着微电子元件日益微小化，芯片的质量控制难度加剧。维也纳工业大学（TU Wien）指出现有的芯片可靠性检测方法存在局限，无法准确评估晶体管材料损坏的临界条件。研究明确了芯片材料发生破坏的具体条件，为微电子芯片的质量控制提供了新的应对方案。","scd":null,"kp":[]},{"i":3636,"as":"初创公司SE3 Labs开发了一种空间AI（Spatial-AI）技术。该技术利用图像、视频和地图数据构建逼真的3D模型，解决了生成式AI在物理空间认知上的局限。目前，这项空间环境感知技术已被应用于德国联邦军的多个实际项目中。","scd":null,"kp":["[自主系统环境感知]: 利用图像、视频和地图创建逼真的3D模型","[空间AI技术]: 融合多模态数据以理解物理空间变化"]},{"i":3637,"as":"由不来梅大学与德国人工智能研究中心（DFKI）联合组成的B-Human团队，在机器人足球世界锦标赛中夺得冠军。获胜机器人身穿红色球衣，在比赛中展现了卓越的竞技运动能力，体现了该团队在机器人运动控制与AI决策领域的顶尖技术实力。","scd":null,"kp":[]},{"i":3638,"as":"NTPC REL正在为印度拉贾斯坦邦的300 MW/1,200 MWh电池储能系统（BESS）项目招标EPC服务。该项目接入Nokhra太阳能电站的邦际输电系统（ISTS）。中标方需以交钥匙方式负责系统的设计、供货、安装、测试与并网，并提供为期15年的全面运维、保修及性能保险服务。","scd":null,"kp":["储能项目规模[印度NTPC REL]: 300 MW/1,200 MWh","储能容量要求[并网点]: 需代表额定交流放电容量"]},{"i":3639,"as":"英国天然气电力市场办公室批准了频率响应市场规则的部分变更。监管机构批准了八项拟议修正案中的六项，新规将于2026年7月生效。主要变更包括建立平衡市场可用性信号与频率服务市场运营之间的新联动机制，重塑了电池资产所有者的市场交易条件。","scd":null,"kp":["[英国动态频率响应市场]: 监管机构批准了八项规则修订中的六项"]},{"i":3640,"as":"古巴在哈瓦那Cotorro变电站成功投运了首个50 MW电池储能系统。该系统已通过电网故障实测，能自动吸收或注入功率以维持电网频率。这是古巴规划200 MW总容量中的首个项目，剩余三个50 MW项目将建于哈瓦那其他地点及Holguín和Granma省，旨在强化电网并配合太阳能扩张。","scd":null,"kp":["电池储能系统规模[古巴哈瓦那Cotorro变电站]: 50 MW","[电网扰动场景]: 电池自动吸收或注入功率以维持电网频率","[整体规划]: 计划建设四个50MW电池储能系统"]},{"i":3641,"as":"Enertrag在德国勃兰登堡签署了一项混合光伏储能项目的长期商业协议。该项目包含44.5 MW光伏电站和5 MW/10 MWh储能系统。EDF Trading签署了7年期购电协议（PPA）负责光伏电量销售，e2m签署了7年期协议负责电池管理。项目通过在受限电网连接点叠加光储，最大化了设施利用率。","scd":null,"kp":["光伏装机容量[德国勃兰登堡混合项目]: 44.5 MW","储能系统规模[德国勃兰登堡混合项目]: 5 MW/10 MWh","购电协议期限[太阳能电力]: 7年","电池收费协议期限[电池灵活性交易]: 7年","[初始运行模式]: 前五年作为绿电共址资产运行"]},{"i":3642,"as":"开发商CleanPeak与西悉尼国际机场签署了为期7年的长期供电协议，以保障机场在年底客运服务启用时实现100%可再生能源供电。供电组合包括新增约9 MW的屋顶光伏以及30 MW/120 MWh电池储能系统，结合其光伏农场组合共同满足机场全部电力需求。","scd":null,"kp":["电池储能系统规模[悉尼西部国际机场]: 30 MW/120 MWh","[机场整体能源]: 实现100%可再生电力运营","供电协议期限[机场电力供应]: 7年"]},{"i":3643,"as":"空气产品公司与雅苒宣布调整其低碳氨业务战略，两家企业将转变原有的低碳氨生产与部署计划，重新规划相关项目的实施路径。","scd":null,"kp":[]},{"i":3644,"as":"ULEMCo与Luxfer正式建立合作关系，双方将共同推进氢气存储技术在各类移动出行应用场景中的研发与落地。","scd":null,"kp":[]},{"i":3645,"as":"Hydrogenera与Stargate Hydrogen正式签署了合作框架协议。","scd":null,"kp":[]},{"i":3646,"as":"迪诺拉正式获得来自Onuba的最终订单，但未披露该订单的具体产品细节、金额及业务内容。","scd":null,"kp":[]},{"i":3647,"as":"为应对算力中心的绿电需求激增，上海通过长三角省市间电力互济交易模式，实现江苏与安徽的绿电精准跨省调配。上海本地绿电产能约10亿千瓦时，而需求量达92亿千瓦时，缺口巨大。跨省调配有效缓解了东部沿海地区受制造业绿电需求与算力中心双重挤压所导致的绿电短缺问题。","scd":null,"kp":["绿电占比要求[国家枢纽节点新建数据中心(到2025年底)]: 超过80%"]},{"i":3648,"as":"针对传统矿山设计方案耗时长、CAD软件专业化程度低的问题，本溪钢铁联合东北大学开发了露天矿开采方案整体模拟软件。系统通过输入产量、品位、边坡角等参数，在地质、市场及技术经济动态变化下自动生成多套开采设计，有效提升了矿山开采方案的前瞻性与设计效率。","scd":null,"kp":["服务年限[矿山开采方案设计]: 短则5年、长可达30年以上"]},{"i":3649,"as":"德国科研机构将铜铟镓硒半导体与钙钛矿结合，并引入优化中间层，成功制备出光电转换效率达25.5%的串联太阳能电池（面积1.081平方厘米），打破同材质24.6%的原纪录并获权威认证。研究通过优化空穴传输材料与改进电子选择性接触工艺降低界面损失，其内部测试效率已攀升至27.5%。","scd":null,"kp":["光电转换效率[铜铟镓硒与钙钛矿串联太阳能电池]: 25.5%","电池实际面积[串联太阳能电池]: 1.081平方厘米","界面钝化层厚度[超薄氟化锂]: 1纳米","内部测试光电转换效率[类似架构串联太阳能电池]: 27.5%"]},{"i":3650,"as":"深圳极壳科技专注于消费级外骨骼机器人的研发与制造，使过去笨重昂贵的外骨骼设备实现轻量化和低成本化。产品已在全球70多个国家拥有数万名用户，广泛应用于户外作业、运动及老年群体。深圳完善的产业链生态和城市应用场景为该机器人产业的快速产品化与全球化提供了核心支撑。","scd":null,"kp":[]},{"i":3651,"as":"在2026年RoboCup机器人世界杯人形组决赛中，搭载加速进化Booster T1机器人的清华火神队以6:2战胜对手成功卫冕。本次赛事共有38支队伍采用中国加速进化公司的机型，包揽了双足人形所有组别金牌。中国机器人本体因腿足运动控制强和物理可靠性高，已成为赛事赛队突破感知与协同高阶能力的首选。","scd":null,"kp":["比赛结果[2026年RoboCup机器人世界杯人形组决赛]: 中国队以6∶2击败对手夺冠","应用规模[采用加速进化机型的赛队]: 38支"]},{"i":3652,"as":"市场监管总局发布了7项《人工智能 智能体互联》国家标准，构建了涵盖身份标识、能力描述、协同交互等闭环规范体系。此举旨在解决因接口协议不统一造成的“智能体孤岛”及身份仿冒等安全风险，降低企业系统集成成本。该指导性文件兼容多条技术路线，后续将推进向强制性国家标准转化及相关审计交易标准研制。","scd":null,"kp":["标准体系[人工智能智能体互联]: 涵盖“身份标识—能力描述—供需发现—协同交互—工具调用”的闭环式规范","核心痛点[智能体跨域交互]: 面临身份仿冒、数据泄露等安全风险"]},{"i":3653,"as":"","scd":null,"kp":[]},{"i":3654,"as":"天问二号探测器历经约400天飞行抵达距小行星2016HO3约20千米处，正式开展科学探测。探测器在抵近过程中利用光学导航数据将小行星位置误差缩小至千米量级，并传回了拍摄图像。后续探测器将逐步开展精细探测，获取小行星形貌、成分与内部结构数据，为后续采样任务提供支撑。","scd":null,"kp":["飞行耗时[天问二号探测器抵达小行星2016HO3]: 约400天","飞行行程[天问二号探测器抵达小行星2016HO3]: 约10亿千米","交会距离[天问二号探测器开始科学探测]: 20千米","星历位置误差[基于探测器光学导航数据改进后]: 由上百千米减小到千米量级","首次捕获时间[天问二号探测器]: 2026年6月6日"]},{"i":3655,"as":"","scd":null,"kp":[]},{"i":3656,"as":"","scd":null,"kp":[]},{"i":3657,"as":"","scd":null,"kp":[]},{"i":3658,"as":"黑龙江省通过产业政策赋能、研发平台布局与完善产业链，推动农机装备产业向高端化、智能化、绿色化转型。智能激光除草机器人、无人驾驶及新能源大农机等装备相继投产或加速研发。现代化农机正广泛应用于黑土地的中耕、除草、施肥等夏管作业，不仅促进了稳产增收，还推动了农业绿色可持续发展，农机装备产业高质量发展格局正在形成。","scd":null,"kp":["[黑龙江农机装备产业发展方向]: 向高端化、智能化、绿色化发展","[现代化农机投产与研发机型]: 智能激光除草机器人、无人驾驶大农机、新能源大农机"]},{"i":3659,"as":"7月4日17时30分，我国在太原卫星发射中心使用长征六号改运载火箭，成功将千帆极轨13组卫星发射升空。卫星顺利进入预定轨道，发射任务取得圆满成功。此次任务是长征系列运载火箭的第655次飞行。","scd":null,"kp":["[千帆极轨13组卫星发射]: 使用长征六号改运载火箭在太原卫星发射中心发射升空并顺利进入预定轨道","火箭飞行次数[长征系列运载火箭]: 第655次"]},{"i":3660,"as":"中国第16次北冰洋考察队乘坐“雪龙”号、“雪龙2”号和“极地”号从大连起航，并联合“探索三号”共同实施，预计10月上旬完成。此次考察以应对全球气候变化为核心，将在北冰洋重点海域开展海冰、水文、生态等多领域综合调查监测，探索加克洋中脊增生机制等前沿科学问题，并与俄、德等国科学家协同作业，为北极治理与保护提供科学支撑。","scd":null,"kp":["[第16次北冰洋考察实施船只]: 雪龙号、雪龙2号、极地号、探索三号","考察周期[中国第16次北冰洋考察]: 预计10月上旬完成考察任务","[北冰洋考察重点探索研究方向]: 加克洋中脊增生机制、洋壳动态演化"]},{"i":3661,"as":"英国政府决定将第八轮差价合约（CfD AR8）的执行价格冻结在与第七轮（AR7）相同的水平。该政策决定涵盖陆上风电和海上风电领域，旨在对可再生能源项目的定价机制进行调整与控制。","scd":null,"kp":["[英国CfD AR8执行价格]: 冻结在AR7水平"]},{"i":3662,"as":"波兰Baltyk 2和Baltyk 3海上风电项目的基础安装工程已取得重要进展，目前基础安装进度已经过半。该项目持续稳步推进海上风电场的各项建设节点。","scd":null,"kp":["[波兰Baltyk 2、3海上风电项目]: 基础安装已通过一半进度"]},{"i":3663,"as":"位于荷兰的Ecowende海上风电项目成功实现首次发电，标志着该风电场建设取得关键阶段性成果，正式开始产出清洁电力。","scd":null,"kp":["[荷兰Ecowende海上风电场]: 首次发电"]},{"i":3664,"as":"国务院印发《美丽中国建设“十五五”规划》，全面推进碳达峰。规划要求实施碳排放总量和强度双控，提升可再生能源电力比重，新增电量由清洁能源覆盖；加快全国碳市场建设，扩大行业范围与参与主体；提升重点行业绿色低碳水平，建设绿色工厂，明确可再生能源消费最低比重；推进运输工具规模化应用，重点行业清洁运输比例达75%以上，开展零碳运输走廊建设。","scd":null,"kp":["[碳排放双控制度]: 全面实施碳排放总量和强度双控","电力消费比重[美丽中国建设十五五规划]: 全面提升可再生能源电力消费比重","新增用电覆盖[美丽中国建设十五五规划]: 新增用电量由新增清洁能源电量覆盖","[碳捕集利用与封存(CCUS)]: 推动技术发展和示范项目建设","[全国碳排放权交易市场]: 扩大覆盖行业范围、扩展参与主体，推行免费和有偿相结合的配额分配方式"]},{"i":3665,"as":"美国海关数据显示，前4个月美国光伏组件进口市场高度集中，东南亚仍是主要供应地区，其中菲律宾位居首位，前五大来源国合计占比极高。同时，非洲地区光伏组件出货增量潜力显著，埃塞俄比亚、尼日利亚、肯尼亚形成非洲主力，出货量在近期集中快速起量。整体来看，美国光伏组件进口需求在年末呈现显著增长态势。","scd":null,"kp":["进口来源地集中度[美国前4月光伏组件前五大来源国]: 合计占比高达极高水平（高度集中）","主力出口国[非洲光伏组件出货增量]: 埃塞俄比亚、尼日利亚、肯尼亚"]},{"i":3666,"as":"中广核新能源江苏盐城灌东盐场160MW渔光互补光伏发电项目EPC总承包中标候选人公示。项目直流侧容量为211.9936MWp，配套新建储能15MW/30MWh，投标单价区间为1.875至1.924元/W。该交钥匙工程涵盖设计、采购、施工及全容量并网手续办理。项目计划于2026年7月开工，同年底前完成全容量并网。","scd":null,"kp":["交流侧容量[江苏盐城渔光互补光伏发电项目]: 160MW","直流侧容量[江苏盐城渔光互补光伏发电项目]: 211.9936MWp","配套储能规模[江苏盐城渔光互补光伏发电项目]: 15MW/30MWh","EPC投标单价[中广核江苏212MW渔光互补项目]: 1.875~1.924元/W","计划工期[中广核江苏渔光互补项目]: 2026年7月1日开工至2026年12月30日前完成全部并网发电"]},{"i":3667,"as":"通过跨境电商平台，中国“降温神器”清凉小电器加速进入欧洲市场。去年走俏的“风扇帽”升级至2.0版本，提升便携度与清凉体验后再度热销，企业订单已排至8月。有厂商反馈两款风扇帽在世界杯等场景下广受好评，预计今年总销量将突破50万顶，验证了该产品在全球市场的强劲需求。","scd":null,"kp":["销量预测[风扇帽单品]: 突破50万顶","[产品工艺]: 全新升级到2.0版本且提高便携度"]},{"i":3668,"as":"泰国政府正加快能源结构调整以增强国家竞争力，满足现代产业对稳定、清洁电力的需求。具体措施涵盖推广可再生能源、推进社区太阳能项目、支持电动汽车、发展智能电网及储能系统。泰国计划建设现代能源基础设施，拨款支持减少化石燃料的项目，以降低全球能源价格波动风险，确保长期的能源安全与经济可持续发展。","scd":null,"kp":["[政策核心]: 加快能源行业结构调整，将能源转型列为优先事项","[实施措施]: 推广可再生能源、推进社区太阳能、支持电动汽车、发展智能电网与储能系统"]},{"i":3669,"as":"云南省西双版纳州生态环境局拟审查佛居山110MW光伏发电项目环评。该项目采用“农光互补”模式，直流侧容量137.27MWp，配置211680块625Wp单晶硅双面组件及320kW组串式逆变器344台。项目将建设1座220kV升压站及19.6km集电线路，总投资42000万元，其中环保投资约222万元。","scd":null,"kp":["装机容量[交流侧]: 110MW","装机容量[直流侧]: 137.27MWp","总容量[方阵配置]: 3个1.6MW方阵及33个3.2MW方阵","组件规格[单晶硅双面光伏组件]: 625Wp","组件数量[单晶硅双面光伏组件]: 211680块"]},{"i":3670,"as":"机械革命2026款极光X笔记本新增i7-14650HX加RTX 5060版本，售价8699元，享国补后低至7394.15元。该机配备16GB DDR5内存、512GB PCIe 4.0固态硬盘及2560x1600分辨率的300Hz屏幕。采用三风扇双热管散热，实现200W双烤性能释放，内置80Wh电池并支持140W PD快充。接口包含RJ45网口、HDMI 2.1及多个USB-A/C接口。","scd":null,"kp":["整机性能[极限双烤]: 200W","电池容量[内置电池]: 80Wh","快充功率[PD快充]: 140W","适配器[便携适配器]: 250W SiC","屏幕规格[笔记本面板]: 2560x1600分辨率，300Hz刷新率，500尼特亮度，100% DCI-P3色域"]},{"i":3671,"as":"零跑B03X纯电汽车在欧洲市场开启预定，起售价为2.49万欧元。作为国内A10的海外改款车型，B03X外形、尺寸与电池保持一致，但动力升级至145kW单电机，百公里加速缩短至8.6秒。该全球战略车型定位为智能都市跨界车，融合了SUV的多功能性与紧凑车身设计，兼顾空间舒适度与科技感。","scd":null,"kp":["起售价[欧洲市场]: 2.49万欧元","电机功率[前置单电机]: 145kW","电机扭矩[前置单电机]: 150N·m","百公里加速[纯电小车]: 8.6s"]},{"i":3672,"as":"截至2026年第26周，小米REDMI Turbo 5系列手机累计销量突破200万台。REDMI Turbo 5于1月29日发布，标准版搭载天玑8500-Ultra处理器，首销价1999元起；Turbo 5 Max版首发天玑9500s处理器，首销价2199元起。同期，REDMI K90系列销量也达到约239.13万台。","scd":null,"kp":["销量[REDMI Turbo 5系列]: 超200万台","处理器[REDMI Turbo 5标准版]: 天玑 8500-Ultra","处理器[REDMI Turbo 5 Max版]: 天玑 9500s（全球首发）","电池容量[REDMI Turbo 5标准版]: 7560mAh"]},{"i":3673,"as":"","scd":null,"kp":[]},{"i":3674,"as":"","scd":null,"kp":[]},{"i":3675,"as":"","scd":null,"kp":[]},{"i":3676,"as":"","scd":null,"kp":[]},{"i":3677,"as":"","scd":null,"kp":[]},{"i":3678,"as":"安全人员zer0dac披露了ChatGPT的一项安全漏洞，黑客可通过提示词注入和路径遍历技术绕过文件访问限制获取额外数据。测试发现，用户上传文件后若以“误删文件”为由要求ChatGPT生成下载链接，系统会返回有效URL并暴露内部接口路径。攻击者可借此利用路径遍历突破访问限制读取目标外内容。虽然受沙箱机制限制无法直接访问高敏感数据，但可作为复杂攻击链的一环。目前OpenAI已调整文件下载URL的生成流程修复了该漏洞。","scd":null,"kp":["[安全漏洞]: 可通过提示词注入与路径遍历绕过文件访问限制，获取额外数据"]},{"i":3679,"as":"索尼宣布将于7月9日发布新款RX10系列黑卡相机。消息称该相机搭载双BIONZ XR处理器及AI芯片，具备最新的自动对焦功能，支持人物、动物、鸟类、汽车和飞机的眼部追焦与主体检测。视频规格大幅升级，支持录制4K 120fps和1080P 240fps视频。镜头方面，或将搭载等效25-575mm镜头，与2017年发布的前代RX10 IV（搭载24-600mm镜头与2010万像素1英寸传感器）有所不同。","scd":null,"kp":["视频规格[录制能力]: 4K 120fps","视频规格[慢动作录制]: 1080P 240fps","处理器[影像与AI处理]: 双 BIONZ XR 处理器及 AI 芯片","[对焦系统]: 具备全最新自动对焦，支持人物、动物、鸟类、汽车和飞机的眼部追焦与主体检测"]},{"i":3680,"as":"安全研究团队Armadin指出，Windows版Claude Desktop应用的沙箱隔离机制存在安全缺陷。该应用基于Hyper-V隔离的Ubuntu虚拟机运行Claude Cowork。攻击者可通过DLL侧载方式运行恶意代码，绕过Windows本地服务CoworkVMService的身份验证。研究人员通过修改执行参数，成功在虚拟机内以root账户权限执行命令，并覆盖网络访问域名白名单。这使得黑客能够获取虚拟机内的进程数据，并绕过网络限制外传数据。Anthropic认为该攻击需建立在已获得Windows本地执行能力之上，未将其认定为安全漏洞。","scd":null,"kp":["[安全缺陷]: 沙箱隔离机制存在漏洞，黑客可通过本地组件在Ubuntu虚拟机获取root权限","[攻击手段]: 利用DLL侧载绕过CoworkVMService对调用程序身份的验证"]},{"i":3681,"as":"宁德时代（CATL）发布专为轻型商用车设计的“Tectrans II超充版”电池。该款电池具备8C峰值充电能力，可在6分48秒内将电量从20%充至80%。此外，宁德时代正在建设快充与换电站结合的网络，目标在今年年底前于中国约190个城市投入运营4000个站点。","scd":null,"kp":["充电倍率[轻型商用电动车电池]: 8C","补能速度[20%至80%充电]: 小于7分钟","基建目标[充换电站网络]: 到年底在约190个城市建立4000个站点"]},{"i":3682,"as":"宾夕法尼亚州立大学的研究人员开发出一种新工艺，能将饮料瓶中的PET塑料转化为高质量的合成石墨。该转化过程通过加入少量氧化石墨烯并进行受控热处理完成。研究成果已发表在《Diamond and Related Materials》期刊上。这种由回收塑料制成的合成石墨未来可作为锂离子电池的负极材料，既处理了塑料废弃物，又能满足电池制造对石墨的需求。","scd":null,"kp":["[PET塑料回收转化工艺]: 将废旧PET塑料转化为高质量合成石墨，可作为锂离子电池负极材料","合成石墨[PET塑料瓶来源]: 高质量、可作锂离子电池负极材料"]},{"i":3683,"as":"电动汽车电池在出厂前必须经过严格测试，以确保其性能、容量、安全性及正确的电流和电压表现。由于高功率电池组极易引发热失控并导致火灾，制造商在产品离厂前必须执行严格的质量控制。本文重点探讨了确保电池安全的先进测试方法，涵盖了质量控制中的创新技术与自动化应用，以保障电池符合安全与性能标准。","scd":null,"kp":["[电动汽车电池出厂前测试]: 需进行性能、容量、安全性及电流/电压特性的全面测试以确保安全与质量控制"]},{"i":3684,"as":"FarEye正通过创新平台和持续合作重塑最后一英里物流能力，旨在降低物流成本并提升交付效率。最后一英里是客户直接感知的关键环节，选项匮乏或延误会削弱客户忠诚度。FarEye作为最后一英里技术合作伙伴，正致力于重新定义配送体验，确保每次交付都能准确送达目的地，从而帮助物流企业克服交付障碍并提升客户留存率。","scd":null,"kp":[]},{"i":3685,"as":"受地缘政治、宏观经济和气候突变影响，传统供应链面临海运拥堵等诸多瓶颈挑战。供应链管理者正致力于将物流从被动应对转向主动预测。业界专家探讨了利用人工智能（AI）技术预判全球供应链中断的解决方案。通过应用AI技术，供应链高管能够有效应对破坏性因素，减少日常运营中的盲目反应，提升供应链的整体韧性与效率。","scd":null,"kp":["[供应链人工智能应用]: 利用AI预测全球供应链中断，推动物流从被动反应向主动预防转变"]},{"i":3686,"as":"代理人工智能（Agentic AI）具备解决供应延误、平衡库存、标记风险和加速履约的潜力，但在实际供应链操作中面临挑战。仅凭AI无法修复存在缺陷的供应链系统，其可靠运行需要建立在对供应链流程的深入理解之上。因此，将代理AI部署在坚实的流程智能基础之上是实现其价值的关键，能够有效降低日常运营的人工干预，避免昂贵的试错实验。","scd":null,"kp":["[代理人工智能供应链部署]: 需建立在可靠的流程智能基础之上，可实现自动纠错、解决供应延迟、平衡库存及降低人工操作"]},{"i":3687,"as":"GXO Logistics发布了《交通的未来》报告，探讨了企业降低环境影响与提升效率的方法。随着车队电气化和低排放燃料的普及，全球物流业正向可持续方向迈进，但许多组织面临不知从何入手的困境。该报告深入调研了英国驾驶员应对可持续物流转型的态度与现状，强调不采取行动的代价已成为现实问题，敦促各组织尽快优化运营以实现绿色物流。","scd":null,"kp":[]},{"i":3688,"as":"福特汽车宣布召回42,784辆2021至2023年款的Mustang Mach-E电动汽车。此次召回的原因是后轮驱动车型的后差速器小齿轮轴存在缺陷，部件可能发生弯曲或断裂。故障会导致车辆丧失驱动力，或在未拉手刹处于P挡时发生自行移动，从而引发安全隐患。近年来，这款纯电跨界SUV已遭遇多次重大召回事件。","scd":null,"kp":["召回数量[福特野马Mach-E]: 42,784辆 (2021至2023年款)","[召回原因]: 差速器组件可能断裂导致丧失驱动力"]},{"i":3689,"as":"前特斯拉Optimus机器人科学家Rémi Cadène在巴黎创立了人形机器人初创公司UMA，并计划推出一款名为Northstar的轻量级人形机器人，目前已与50家潜在客户展开洽谈。Cadène曾在特斯拉负责Autopilot与Optimus的AI系统研发，后加入Hugging Face主导开源机器人库LeRobot的开发，该项目在GitHub上已获得超12000颗星标。","scd":null,"kp":["[初创公司人形机器人]: 轻量级人形机器人","潜在客户规模[Northstar人形机器人]: 50家"]},{"i":3690,"as":"起亚凭借不断扩充的电动汽车产品线，从入门级SUV到货车全面覆盖，取得了史上最佳的上半年度销售业绩。2026年上半年，起亚全球总销量突破163万辆，创下自1962年以来的最高纪录，并实现连续四个月的同比增长。这主要得益于其实施的区域化电动车战略，包括EV2、EV3、EV9等热门车型，以及首款纯电货车PV5的畅销。此外，混合动力SUV在北美市场的热销也推动了整体业绩。","scd":null,"kp":["[起亚电动汽车产品线]: 覆盖从入门级低成本EV2、EV3到三排座EV9及首款纯电动面包车PV5的全系列车型"]},{"i":3691,"as":"电动汽车制造商Rivian宣布发售7500万股普通股以筹集资金。按近期股价计算，此次募资总额约为15亿美元。若承销商全额行使额外购买1125万股的30天期权，总筹资额将接近17亿美元。此次融资发生在Rivian发布强劲的第二季度交付数据并上调全年业绩展望、股价随之上涨之后。高盛、巴克莱和摩根大通等机构参与了此次承销，所得资金将用于支持R2等车型的研发与生产。","scd":null,"kp":["融资金额[Rivian发售股票]: 约15亿美元","发行股数[Rivian发售股票]: 7500万股","[融资目的]: 为R2等项目筹集资金"]},{"i":3692,"as":"Voltpost正与电动汽车充电服务公司InCharge Energy合作，加速在美国推广灯柱和电线杆电动汽车充电器。首批部署将在纽约、康涅狄格州和加利福尼亚州进行。Voltpost的充电系统通过对现有路灯和电线杆进行改造，安装二级充电桩，从而避免了全新的基础设施基建。这种模式大幅降低了建造成本，旨在为安装传统充电桩昂贵或困难的社区提供更经济实惠的路边和停车场充电方案。","scd":null,"kp":["充电桩类型[部署场景]: 灯柱和电线杆Level 2充电器"]},{"i":3693,"as":"加拿大和中国达成的“油菜籽换汽车”贸易协议迎来了首批实质性成果：18辆全新的路特斯Eletre纯电动汽车即将运抵蒙特利尔。根据协议，加拿大每年允许以优惠关税税率进口多达4.9万辆中国制造的电动汽车，以实现汽车市场多元化并减少对美国汽车品牌的依赖。作为交换，加拿大希望中国降低目前高达100%的加拿大菜籽油进口关税。这是中国制造的纯电汽车首次以中国品牌身份在加拿大市场销售。","scd":null,"kp":["进口配额[中加电动汽车贸易协议]: 每年最多49,000辆","首批交付规模[路特斯Eletre电动汽车]: 18辆"]},{"i":3694,"as":"Octopus Energy推出了名为Nook的全新住宅电池储能系列，以扩大家庭储能的普及率，特别是针对公寓住户和租客。该系列包括Nook Cube和Nook Colossus两款产品。Nook Cube是一款2度电的插电式电池，直接连接标准家用插座，最多可扩展至10.5度电；Nook Colossus则是一款5度电的壁挂式电池，可扩展至30度电。两款系统均兼容屋顶太阳能，并计划于2027年在包括意大利在内的五个欧洲市场推出。","scd":null,"kp":["电池容量[插入式家用电池(Nook Cube)]: 2 kWh","电池容量[壁挂式系统]: 5 kWh"]},{"i":3695,"as":"晶科能源副总裁Frank Niendorf表示，受需求减弱和安装量下降影响，全球光伏市场正处于整合期，今年装机量预计下降且2027年可能停滞。面对行业挑战，晶科能源正加速拓展综合能源解决方案战略，投资储能系统、新型组件技术和长期技术创新以应对市场变化。","scd":null,"kp":["太阳能产业[市场预期]: 预计2028年迎来新动力"]},{"i":3696,"as":"荷兰政府公布了2025年SDE++可再生能源补贴计划结果，共支持86个太阳能项目，总容量达773兆瓦。该计划旨在为大型可再生能源项目提供多年期财务支持。气候与绿色增长部长确认共批准283个项目，几乎用尽800万欧元总预算，目前仍有价值7亿欧元的申请正在处理中。","scd":null,"kp":["太阳能装机分配规模[荷兰2025年SDE++补贴回合]: 773兆瓦","项目数量[荷兰2025年SDE++补贴回合]: 86个"]},{"i":3697,"as":"先进电网扫描软件在美国发现大量隐藏的输电容量，无需新建发电厂即可释放高达300吉瓦的电网容量。传统电网规划基于保守的N-2 contingency准则，导致计算负担沉重且资源未充分利用。新型软件工具为公用事业规模的光伏和储能开发商提供了避开并网排队困境的近期解决方案。","scd":null,"kp":["电网容量[先进电网扫描软件释放]: 300吉瓦"]},{"i":3698,"as":"国际能源署光伏发电系统计划（IEA-PVPS）报告警告，将太阳能项目的技术与经济决策割裂会带来财务风险。报告倡导在项目早期开发阶段实施“质量门”机制。通过结构化决策矩阵和实际案例，建议利用移动测试实验室和防御性天气策略进行主动规划，并对特定地点的污垢风险进行连续分析和气象数据验证。","scd":null,"kp":["项目管理[太阳能项目早期开发]: 建议采用具有成本效益的“质量门”进行技术与经济综合决策"]},{"i":3699,"as":"中国电力电子设备制造商ENSD推出专为直流电动汽车充电站设计的40千瓦充电模块Sirius 40Max。该模块基于EN5核心技术，最高转换效率达99.0%，加权效率达98.5%。产品采用无风扇自然冷却和IP65防护等级设计，显著降低功率损耗，能够在恶劣商业环境中稳定运行。","scd":null,"kp":["充电模块功率[直流电动汽车充电站]: 40 kW","峰值转换效率[Sirius 40Max充电模块]: 高达99.0%","冷却设计[Sirius 40Max充电模块]: 无风扇自然冷却","防护等级[Sirius 40Max充电模块]: IP65"]},{"i":3700,"as":"德国哈梅林太阳能研究所（ISFH）宣布扩容校准服务，现可为大面积钙钛矿-硅串联太阳能电池提供校准。新服务兼容尺寸达210毫米边缘长度的G12硅片格式。相较于传统硅基电池，串联太阳能电池结构更为复杂，此次校准能力的提升将有助于精确测量新一代大面积光伏器件的性能。","scd":null,"kp":["校准服务适用尺寸[钙钛矿-硅叠层太阳能电池]: 最高至G12硅片尺寸"]},{"i":3701,"as":"西班牙塞维利亚大学研究人员开发出一种网络弹性框架，用于检测和识别公用事业级光伏电站中的虚假数据注入攻击（FDIA）。该框架采用EC-WLSE和EC-SHGME状态估计技术，能有效发现针对通信网络、传感器和控制系统的复杂测量数据篡改，从而提升光伏电站的网络安全性。","scd":null,"kp":["网络安全防御框架[光伏电站虚假数据注入攻击]: 采用EC-WLSE和EC-SHGME状态估计技术"]},{"i":3702,"as":"Enphase Energy宣布为下一代数据中心开发新型固态变压器技术（IQ SST），包括针对AI工作负载的800伏高压直流机架电源架构。该技术放弃大型集中式转换器，转而使用由342个小型转换器组成的分布式模型。公司计划最终将该分布式固态变压器模型扩展至公用事业规模的光伏、电池储能和高压电动汽车充电领域。","scd":null,"kp":["应用场景[固态变压器技术]: 分布式800 V直流数据中心、公用事业级太阳能、电池和高压电动汽车充电"]},{"i":3703,"as":"英国政府公布了第八轮差价合约（CfD）分配回合的管理价格上限和拍卖结构，并为太阳能和陆上风电增加了一个额外的交付年份。太阳能价格上限设定为每兆瓦时75英镑，与上一轮持平。各技术的负载因子保持不变，但要求申请者必须具备电网连接协议方可推进项目。","scd":null,"kp":["最大装机容量[英国光伏电站]: 373 MW (Cleve Hill光伏园区项目)","准入条件[参与太阳能和陆上风电拍卖]: 需具备电网连接协议"]},{"i":3704,"as":"日本东北大学和印度印多尔理工学院的科学家联合开发出一种新型原子级铜纳米团簇催化剂。该催化剂在电化学反应中通过精确控制铜原子，有效改变二氧化碳的转化路径，抑制甲酸盐等副产物的生成，从而在温和条件下高效、高选择性地将二氧化碳转化为甲醇，为清洁燃料合成提供新途径。","scd":null,"kp":["催化剂[电化学CO2还原制甲醇]: 原子级铜纳米簇","反应条件[CO2转化]: 温和条件","技术成效[催化反应]: 大幅减少不需要的副产物"]},{"i":3705,"as":"慕尼黑工业大学（TUM）研发出一款气动软机器人外骨骼手套，旨在帮助手部麻痹患者恢复握力。手套通过读取前臂肌肉电信号并结合机器学习预测用户动作意图，随后充气软垫辅助手指和手腕运动。内置的额外运动传感器能在搬运物体时保持稳固抓握，防止物品掉落，提升患者生活独立性。","scd":null,"kp":["控制信号[软机器人手套]: 前臂肌肉电信号结合机器学习","驱动方式[外骨骼手套]: 内部软气垫充气辅助手指和手腕运动"]},{"i":3706,"as":"清洁技术公司Altilium正领导一项名为“REMADE”的英国倡议，致力于回收废弃电池的石墨负极，以减少英国对进口电池石墨的依赖。传统回收通常只提取锂、镍、钴等正极材料，负极往往被填埋。该项目获得了英国政府4.52亿英镑电池创新计划的支持，旨在将废旧负极材料回收再利用。","scd":null,"kp":["回收目标物质[退役电池]: 石墨负极","技术痛点[当前电池回收工艺]: 高价值正极材料被回收，而石墨负极通常作为垃圾填埋或焚烧"]},{"i":3707,"as":"","scd":null,"kp":[]},{"i":3708,"as":"日本核聚变初创公司Helical Fusion已与建筑公司Hazama Ando签署谅解备忘录，计划在2030年代建设其名为Helix KANATA的试验工厂。Hazama Ando正式加入Helical的官方合作伙伴计划。此举标志着该公司在推进零碳排放的核聚变能源商业化进程中迈出了关键的基建一步。","scd":null,"kp":["建造节点[核聚变试验工厂Helix KANATA]: 2030年代"]},{"i":3709,"as":"麻省理工学院（MIT）和慕尼黑工业大学（TUM）的研究团队发现了固态电池中导致性能衰退的枝晶形成机制。研究发现，隐藏在电解质晶界处的电气不平衡阻碍了锂离子并困住电子。通过优化电解质处理工艺以减少电子泄漏，团队成功将材料的电流密度提升了300%以上，为开发充电更快、寿命更长的固态电池奠定基础。","scd":null,"kp":["充电提升[固态电池技术]: 300%","枝晶成因[固态电池]: 电解质晶粒交界处的隐藏电荷失衡","抑制策略[固态电池枝晶]: 调整电解质加工工艺以最小化电陷阱"]},{"i":3710,"as":"动作捕捉技术公司OptiTrack与卡内基梅隆大学（CMU）合作，为该校新建的机器人创新中心（RIC）配备高性能动作捕捉摄像机。该系统能够在受控室内外环境中为自主系统、无人机和机器人开发提供精确的3D追踪与运动分析。此举旨在支持机器人和物理AI领域的新一代研究、测试和验证。","scd":null,"kp":["核心功能[OptiTrack动作捕捉系统]: 为自主系统、无人机和机器人提供精确的3D追踪"]},{"i":3711,"as":"美国海军授予HII公司Lionfish小型无人潜航器（SUUV）的期权年份生产合同。该潜航器基于商用REMUS 300平台开发，具备执行水雷对抗、情报侦察、反潜战和电子战等多种任务的能力。该合同为五年期项目的一部分，彰显了商业技术向军事应用的快速转化，预计最终将交付多达200套系统。","scd":null,"kp":["研发基础[Lionfish小型无人水下航行器]: 基于HII商业化开发的REMUS 300平台","任务能力[Lionfish无人水下航行器]: 反水雷、情报监视侦察(ISR)、反潜战和电子战"]},{"i":3712,"as":"由于现代军事行动对低成本喷气动力无人机需求不断增长，Kratos防务与安全解决方案公司正将其在俄克拉荷马城的制造工厂面积扩大超过106,000平方英尺。扩建后的设施将提升XQ-58A女武神协同作战飞机、Firejet靶机和Mighty Hornet IV等无人系统的产量，反映国防采购向大规模、低成本消耗型平台转变的趋势。","scd":null,"kp":["扩建面积[提升无人机制造产能]: 增加106,000平方英尺","核心产品[喷气动力无人机系统]: XQ-58A Valkyrie协同作战飞机、Firejet靶机、Mighty Hornet IV"]},{"i":3713,"as":"波士顿动力公司的人形机器人Atlas在2026年国际足联世界杯期间亮相，在挪威对阵巴西的八分之一决赛中场休息时登场。该机器人重现了包括哈兰德在内的知名球星的进球庆祝动作。在此前的练习视频中，Atlas展示了分析足球比赛录像，并准确完成控球和传球的动作，这是其在大型全球活动中的重要技术展示。","scd":null,"kp":[]},{"i":3714,"as":"亚利桑那州立大学与范德比尔特大学的联合研究证实，童年时期的苦难经历会在生物体内留下伴随一生的表观遗传痕迹。研究人员通过对野外恒河猴从出生起的生命史记录及12种成年组织的基因组数据进行分析，发现早期生活逆境会显著改变控制基因激活的表观基因组，从而深刻影响个体的衰老过程及成年后的系统健康。","scd":null,"kp":[]},{"i":3715,"as":"科学家发现肾脏保水机制存在除血管加压素之外的新途径。发表在《临床研究杂志》上的这项新研究是在研究多囊肾病（PKD）时意外发现的，由梅奥诊所肾脏病学家Fouad Chebib领导。这一发现改变了传统生理学关于身体如何调节水分平衡的科学认知。","scd":null,"kp":[]},{"i":3716,"as":"多机构研究人员发现，冠状病毒蛋白中单个氨基酸的改变能显著改变病毒与蝙蝠和人类免疫系统的相互作用。发表的这一发现为揭示原本无害的动物病毒如何进化为威胁人类的病毒（如COVID-19）提供了新见解。","scd":null,"kp":[]},{"i":3717,"as":"《营养学前沿》发表的一篇新观点论文指出，目前公共卫生指南中关于运动和蛋白质摄入的建议仅足以预防健康缺陷。为了在衰老过程中保持力量、独立性、心理敏锐度，作者建议成人的蛋白质摄入和运动量应超过目前的最低推荐标准。","scd":null,"kp":[]},{"i":3718,"as":"南卡罗来纳医科大学（MUSC）研究人员开发出一种实验性干细胞疗法，通过重编程免疫系统使其停止攻击胰岛细胞，成功在小鼠模型中逆转了新发1型糖尿病。这项发表在《分子治疗》上的研究针对疾病根源进行治疗，而非仅仅替代胰岛素。","scd":null,"kp":[]},{"i":3719,"as":"《分子生物学与进化》发表的一项最新研究揭示了杂交果蝇雄性不育的百年之谜。Whitehead研究所成员Yukiko Yamashita领导的研究团队发现，杂交雄性果蝇由于无法正常进行遗传处理（细胞缺陷）而无法产生精子，这解释了不育现象往往最先影响雄性的原因。","scd":null,"kp":[]},{"i":3720,"as":"研究人员在加拿大西北地区发现了一个极其丰富的化石遗址。这些埃迪卡拉生物群的化石表明，动物生命的关键特征（包括运动和有性生殖）的进化时间比此前认为的要早得多。这一发现填补了复杂生命早期进化关键阶段的化石记录空白。","scd":null,"kp":[]},{"i":3721,"as":"QIMR Berghofer的研究人员完成了世界上最大的痣遗传学研究，发现了250多个与黑色素瘤风险相关的基因。这些基因通路不仅涉及无法调节细胞生长的免疫系统机制，还与乳腺、前列腺和脑癌等异常细胞增殖有关，为黑色素瘤的预防、治疗提供了新靶点。","scd":null,"kp":[]},{"i":3722,"as":"德国亥姆霍兹柏林材料与能源研究中心等机构的科学家结合铜铟镓硒（CIGS）半导体层与钙钛矿，研制出面积1.081平方厘米的串联太阳能电池。通过引入优化的氧化镍与自组装单分子层空穴传输材料及改进电子选择性接触工艺，该电池经认证的光电转换效率创纪录地达到25.5%。内部测试效率已达27.5%。","scd":null,"kp":["转换效率[CIGS与钙钛矿串联太阳能电池]: 25.5%","电池面积[CIGS与钙钛矿串联太阳能电池]: 1.081平方厘米","钝化层厚度[电子选择性接触工艺]: 1纳米 (超薄氟化锂)","内部测试效率[类似架构串联太阳能电池]: 27.5%","空穴传输材料[提升器件稳定性]: 多种镍氧化物与自组装单分子层的最优组合"]},{"i":3723,"as":"南昌大学周浪团队提出一种无种子层铜电镀金属化方法，成功应用于硅异质结（SHJ）太阳电池。通过在2V电压下对ITO薄膜进行60秒电化学改性，增强了铜电极的附着力。该方法在G12半片硅片上实现了25.94%的批量转换效率，较传统丝网印刷银电极绝对效率提升0.24%，降低了设备投资与工艺成本。","scd":null,"kp":["转换效率[无种子层电镀铜SHJ电池]: 25.94%","效率提升[无种子层电镀铜对比银电极]: 绝对效率提升0.24%","电化学改性处理[ITO薄膜表面粗化]: 2 V，60 s","衬底规格[无种子层电镀铜SHJ电池]: 商业化尺寸G12半片硅片"]},{"i":3724,"as":"国家能源局发布60号文，明确非公共电网可再生能源发电项目（包括工厂屋顶光伏、离网光伏、绿电直连等）可申请绿证核发。其中，上网电量对应可交易绿证，自发自用电量对应不可交易绿证。此举配合发改委第42号令的强制性可再生能源消费考核要求，打通了非公共电网项目的绿证供给通道。","scd":null,"kp":["绿证类型[非公共电网上网电量]: 可交易绿证","绿证类型[非公共电网自发自用电量]: 不可交易绿证","实施时间[可再生能源电力消纳责任权重制度]: 2026年8月1日"]},{"i":3725,"as":"","scd":null,"kp":[]},{"i":3726,"as":"北京正考虑采取措施，限制海外获取中国顶尖的人工智能（AI）模型。","scd":null,"kp":[]},{"i":3727,"as":"TeraWulf 公司股价大幅飙升，原因在于该公司与人工智能公司 Anthropic 达成了一项价值190亿美元的人类数据中心（data center）建设交易。","scd":null,"kp":["交易金额[Anthropic数据中心交易]: 190亿美元"]},{"i":3728,"as":"","scd":null,"kp":[]},{"i":3729,"as":"美科公司（Mercor）的年化总收入已突破20亿美元。","scd":null,"kp":["年总收入[Mercor公司]: 突破20亿美元"]},{"i":3730,"as":"随着人工智能能力的发展和智能体系统的普及，IT领导者正面临投资风险。文章指出，回归AI架构的基础元素（即大规模部署和管理可靠、集成的AI系统所需的结构框架）是关键。这种架构能够支持AI智能体在跨系统环境中检索信息、做出决策并执行复杂工作流程。","scd":null,"kp":[]},{"i":3731,"as":"加州奶农采用由湿木片、碎石和红蚯蚓组成的生物过滤系统来处理奶牛每天产生的大量粪便。这个面积达六个足球场大小的天然系统可以有效减少甲烷、一氧化二氮等温室气体排放以及水污染，使蠕虫和微生物作为粪便污染的生态解决方案正在获得关注与应用。","scd":null,"kp":[]},{"i":3732,"as":"德国RPTU大学Marius Kloft教授领导的机器学习团队正在研究利用AI技术提前识别化学过程中的错误和临界状态，并已成功开发了异常检测方法。德国科学基金会（DFG）已批准该项目的第二期资助，总额约450万欧元，重点研发自适应AI方法。","scd":null,"kp":["技术应用[化学过程AI监测]: 利用深度学习在稀疏化学过程数据上早期识别错误和临界状态"]},{"i":3733,"as":"","scd":null,"kp":[]},{"i":3734,"as":"由Goshe Energy Storage开发的德克萨斯州Bexar BESS电池储能项目于3月12日获得ERCOT批准投入商业运营，并于3月20日完成NERC注册。由于该设施规模超过75 MVA阈值，注册为NERC类别1发电所有者。Radian Generation协助验证了工程技术控制、网络安全合规性及系统设计。","scd":null,"kp":["容量阈值[NERC Category 1发电所有者注册]: >75 MVA","商运时间[Bexar BESS储能项目]: 3月12日"]},{"i":3735,"as":"爱尔兰电网规模储能市场持续增长。自2018年以来，爱尔兰已安装超过800兆瓦的电网级电池储能系统。根据相关报告，增加2吉瓦的储能容量每年可为爱尔兰和北爱尔兰的消费者节省高达1.02亿欧元的成本。到2030年代初建成2吉瓦储能系统具有强有力的经济效益。","scd":null,"kp":["电网规模储能容量[爱尔兰截至当前]: 800MW","电网规模储能容量[爱尔兰在建]: 2.3GW","额外储能装机[爱尔兰及北爱尔兰消费者年节省]: 102亿欧元"]},{"i":3736,"as":"美国独立发电商Kearsarge Energy完成了位于美国东北部的独立电池储能、地面光伏及光储一体化项目组合。该项目于2025年部署，覆盖马萨诸塞州等多个州，利用垃圾填埋场、停车场和屋顶等多种场地。该公司自主运营资产，并计划于2026年将业务扩展至明尼苏达州等更多地区。","scd":null,"kp":["项目部署[美国东北部2025年BESS与光伏组合]: 覆盖马萨诸塞州、佛蒙特州、纽约州、马里兰州和新罕布什尔州"]},{"i":3737,"as":"巴西10年能源扩展计划（PDE 2035）预测，随着技术成本下降，用户侧电池储能将快速增长。预计到2035年，巴西用户侧电池储能容量将达到7吉瓦，约占全国电力容量的2%。此外，分布式发电容量预计将达到78.1吉瓦，主要驱动力为屋顶及其他分布式光伏安装。","scd":null,"kp":["用户侧电池存储容量[巴西2035年预测]: 7GW","占比[巴西2035年电池存储占全国电力容量]: 约2%"]},{"i":3738,"as":"澳大利亚迪肯大学的研究表明，社区级电池储能系统是解决屋顶光伏和电动汽车等分布式能源并网挑战的最可行且最具成本效益的方案。澳大利亚屋顶光伏普及率领先全球，约430万户家庭安装了光伏系统。分布式能源渗透率的提高增加了电网功率的波动性，社区储能相比家庭系统更具优势。","scd":null,"kp":["屋顶光伏渗透量[澳大利亚家庭安装量]: 约430万户","装机容量[澳大利亚屋顶光伏]: 28.3GW","储能系统[应对分布式能源电网挑战]: 社区级电池储能系统最具可行性与成本效益"]},{"i":3739,"as":"蒂森克虏伯nucera与印度BHEL正式签署电解槽合作协议，旨在降低电解水制氢项目的风险，共同推进氢能产业的发展。","scd":null,"kp":["电解槽制氢[印度本土化合作]: 蒂森克虏伯nucera与BHEL签署合作协议"]},{"i":3740,"as":"强制性国家标准《电动汽车用动力蓄电池安全要求》（GB 38031-2025）将于2026年7月1日实施。新国标包含7项单体测试和17项系统测试，收紧了安全标准。热扩散测试要求调整为不起火、不爆炸。新标准还新增了底部撞击测试和快充循环后安全测试，要求300次快充后进行外部短路测试时不起火、不爆炸。","scd":null,"kp":["实施时间[动力电池新国标GB 38031-2025]: 2026年7月1日","测试要求[新国标单体测试]: 7项","测试要求[新国标电池包或系统测试]: 17项","热扩散测试[新国标安全技术要求]: 不起火、不爆炸，烟气不对乘员造成伤害","快充循环测试[新国标新增安全测试]: 15分钟内20%充至80%的电池在300次快充循环后进行短路测试不起火不爆炸"]},{"i":3741,"as":"今年上半年，江苏沿海最大的渔光互补滩涂光伏发电项目（启东吕四“光伏海”）一期累计发电2.61亿千瓦时，可满足约51万居民一年的用电需求。该项目利用5850亩潮间带滩涂，布置121个光伏单元，采用“水上发电、水下养殖”模式。全容量投运后预计年减排二氧化碳约49万吨。","scd":null,"kp":["发电量[启东吕四光伏海一期上半年]: 2.61亿千瓦时","覆盖面积[滩涂光伏项目利用潮间带]: 5850亩","阵列规模[光伏单元布置数量]: 121个","年减排量[全容量投运后预期二氧化碳减排]: 约49万吨","居民用电[一期发电满足能力]: 约51万居民一年用电需求"]},{"i":3742,"as":"甘肃烛龙科技有限公司发布了全新自主品牌“千纪源天枢碳-14核电池”及碳化硅换能器。相较于前代工程样机，该核电池实现五大技术突破。其放射源比活度提升1.5倍，用量降至22%；短路电流提升至2.5倍，最大输出功率达2.6倍；有效体积缩减至17%，体积功率密度提升15.5倍，实现了小型化与低成本制备。","scd":null,"kp":["核心突破[千纪源碳-14核电池]: 全新放射源适配体系、高效换能技术、三维叠层封装结构、智能储能电源管理系统、高精度传感与无线传输","应用场景[碳-14核电池]: 空天探测、极地科考、特种装备、无人值守"]},{"i":3743,"as":"粤港澳大湾区正从“制造工厂”向“创新现场”转型。深圳极壳科技研发了一款重约2公斤的消费级外骨骼产品，能在0.31秒内识别步态并提供助力，使使用者心率最高降低42%。该产品结合了微型动力和AI算法，已在全球70多个国家和地区销售，并成功登顶珠峰完成极高海拔验证。","scd":null,"kp":["全球机器人开发选品选型服务中心[深圳启用时间]: 2026年4月8日","设备特征[极壳科技消费级外骨骼]: 设有松紧卡扣并提供无形助力（重量极轻）"]},{"i":3744,"as":"美国北卡罗来纳大学教堂山分校研究指出，AI撰写小说依赖套路，导致角色缺乏神秘感。研究团队开发了CASPER工具评估故事。结果显示，AI塑造的角色偏保守，多采用封闭式结局；而人类作家常留有悬念。此外，更强大的AI模型未表现出比小模型更高的角色多样性，说明模型规模并非决定故事质量的唯一因素。","scd":null,"kp":["角色塑造[AI生成小说特点]: 倾向于依赖熟悉套路，缺乏神秘感，多采用封闭式结局","评估工具[AI故事角色分析]: CASPER系统"]},{"i":3745,"as":"杭州机器人学校正式开学，首批30台机器人接受“职业技能”培训。国内已兴建50多所机器人学校，旨在解决机器人在复杂实际工况中抗干扰能力差、频繁失效的问题。学校通过搭建多工况实训场地强化机器人自适应能力，并规模化采集高质量实操数据，未来还将逐步建立机器人能力分级评价标准。","scd":null,"kp":["[机器人学校首批学生]: 30台机器人","[国内已兴建机器人学校数量]: 过去一两年超50所","[真实工况核心干扰特征]: 光照突变、镜头遮挡、温湿度浮动、人员随机穿行等多重干扰","[实际场景失效表现]: 视觉传感器成像失真、运动轨迹偏移"]},{"i":3746,"as":"受AI基础设施需求扩张影响，高带宽内存（HBM）需求激增，主要存储芯片企业将产能转向AI配套，导致消费级DRAM和NAND供给紧张。据测算，2025年全球DRAM和NAND现货价格分别上涨386%和207%。苹果和微软等厂商被迫上调硬件售价。预计2027年全球PC和智能手机厂商将面临严重的芯片短缺。","scd":null,"kp":["[苹果硬件全球提价幅度]: 约20%","[存储芯片供应危机恶化节点]: 2025年下半年","[高端AI芯片标配]: 高带宽内存（HBM）","[产能调整方向]: 主要存储企业将大量先进晶圆产能转向AI配套存储"]},{"i":3747,"as":"阿根廷AlmaSADI电池储能系统（BESS）招标已授予总容量为700.5兆瓦的储能项目合同。","scd":null,"kp":["中标合同规模[AlmaSADI BESS招标]: 700.5 MW"]},{"i":3748,"as":"荷兰液流电池公司Elestor与Zeewolde风电场计划合作开展一项分阶段建设的长期储能项目。","scd":null,"kp":["[项目开发模式]: 分阶段长期储能项目"]},{"i":3749,"as":"浙江省经信厅发布《浙江省工业领域光伏开发建设指导意见(征求意见稿)》，要求按照“能装尽装”原则推进工业光伏建设。“十五五”期间，全省新建厂房可利用屋顶光伏安装比例达100%，新增工业光伏装机目标1000万千瓦。意见强调推行容缺受理、优先选用高效组件，并利用微电网技术实现源网荷储协同。","scd":null,"kp":["安装比例[十五五期间全省新建工业厂房可利用建筑屋顶]: 100%","新增装机目标[十五五期间全省新增工业光伏]: 1000万千瓦","[开发原则]: 能装尽装、自用优先、结余上网"]},{"i":3750,"as":"截至2026年6月30日，山东省风电与光伏发电装机总容量达1.3056亿千瓦，占全省电力总装机比重达50.18%，历史性突破50%。全省非化石能源装机占比达55.85%。山东光伏装机连续8年全国第一，海上风电跃居全国第三。为消纳绿电，山东已建成国内最大的省域交直流混联大电网。","scd":null,"kp":["装机占比[山东风电与光伏发电占全省电力总装机]: 50.18%","装机总容量[山东风电与光伏发电]: 1.3056亿千瓦","装机占比[山东非化石能源]: 55.85%","煤电装机占比[2024年底]: 45.0%"]},{"i":3751,"as":"阿特斯发布第三代TOPCon组件，实现结构设计升级。该组件功率可达约670W，最高效率约24.8%，预计2026年8月起实现全球规模化交付。新产品提升了双面发电能力与长期可靠性，有助于降低度电成本。阿特斯表示行业产能依然过剩，公司正聚焦高效产品研发与降本增效技术导入。","scd":null,"kp":["产品功率[TOPCon第三代组件]: 约670W","组件效率[TOPCon第三代组件]: 最高约24.8%","规模化交付时间[TOPCon第三代组件]: 2026年8月"]},{"i":3752,"as":"安徽霍邱县启动北部片区集中式光伏及新型储能项目合作单位比选。项目包含约120MW集中式光伏和新型储能，其中光伏项目由合作方与政府平台成立项目公司负责全流程建设运营；新型储能项目由政府投资，合作单位负责20年兜底运营，旨在优化能源结构并提升电力调节能力。","scd":null,"kp":["建设规模[霍邱县集中式光伏项目]: 约120MW","运营期[新型储能项目]: 20年"]},{"i":3753,"as":"南宁市宾阳邹圩150MW光伏项目一期工程进行环评公示。该项目总投资6亿元，占地127.17公顷，施工期6个月。项目将安装270,348片720Wp单晶硅N型双面组件，建设单位为阳光新能源全资孙公司宾阳县天照新能源科技有限公司。","scd":null,"kp":["装机容量[宾阳邹圩光伏项目一期工程]: 150MW","总投资[宾阳邹圩光伏项目一期工程]: 6亿元","占地面积[宾阳邹圩光伏项目一期工程]: 127.17h㎡","安装组件[宾阳邹圩光伏项目一期工程]: 720Wp单晶硅N型双面太阳能组件"]},{"i":3754,"as":"中广核与TCL中环合资公司启动宁夏灵武500MW光伏复合项目二标段EPC招标。项目配套建设100MW/400MWh储能设施，规划安装142个光伏子方阵，通过35kV集电线路接入新建330kV升压站。项目总投资约12.5亿元，计划工期152日，目标于2026年12月30日全容量并网。","scd":null,"kp":["建设规模[中环灵武光伏复合项目]: 500MW","配套储能规模[中环灵武光伏复合项目]: 100MW/400MWh","总投资[中环灵武光伏复合项目]: 约12.5亿元","EPC总工期[中环灵武光伏复合项目]: 152日","计划全容量并网时间[中环灵武光伏复合项目]: 2026年12月30日"]},{"i":3755,"as":"杭州市发改委公示了该市2026年第二季度的分布式光伏可开放容量信息。","scd":null,"kp":[]},{"i":3756,"as":"四川省发改委发布新能源资源市场化配置管理办法征求意见稿，明确集中式风电、光伏及光热项目实行市场化配置。规定了不同接入条件下的项目最低装机规模，严禁拆分水风光一体化基地项目。为防止圈而不建，规定光伏和风电须分别在3个月和12个月内完成核准或备案，违规将收回开发权并限制企业3至5年内参与配置。","scd":null,"kp":["准入装机容量[接入新建汇集站集中式风电]: 不得低于10万千瓦","准入装机容量[接入新建汇集站集中式光伏]: 不得低于50万千瓦","准入装机容量[接入现有汇集站集中式风电]: 不低于5万千瓦","准入装机容量[接入现有汇集站集中式光伏]: 不低于10万千瓦","管理模式[工业园区220千伏并网光伏项目]: 按照集中式进行备案管理"]},{"i":3757,"as":"","scd":null,"kp":[]},{"i":3758,"as":"","scd":null,"kp":[]},{"i":3759,"as":"小鹏汽车宣布MONA L03首搭驾驶员失能辅助系统。在高速路辅助驾驶时，若驾驶员失去驾驶能力，车辆可自动靠边停车并呼叫救援。该功能未来将通过OTA升级，支持在普通道路实现全链路自主救援。MONA L03预售价14.38万元起，提供纯电与增程双动力，搭载1500TOPS算力图灵芯片与第二代VLA智驾系统。","scd":null,"kp":["车辆预售价[小鹏MONA L03]: 14.38万元起","智驾算力[图灵芯片]: 1500TOPS","失能辅助系统[高速路辅助驾驶时驾驶员失能]: 车辆自动靠边并呼叫救援","动力形式[小鹏MONA L03]: 纯电+增程双动力"]},{"i":3760,"as":"据知情人士透露，DeepSeek正在研发面向AI推理场景的自有AI芯片，以减少对英伟达和华为的依赖。该项目约在一年前启动，目前正处于早期阶段，公司正与芯片设计企业、晶圆代工厂及存储厂商展开洽谈，并持续招募芯片设计工程师。分析师指出，除非获得最先进制造工艺，否则该芯片主要面向国内市场。","scd":null,"kp":["研发方向[DeepSeek自研AI芯片]: 主要面向AI推理场景"]},{"i":3761,"as":"三星官方预热全新形态新品，预计为Galaxy Z Fold8阔折叠手机。该产品将搭载第五代骁龙8至尊版定制版芯片。据此前曝光信息，新机展开厚度4.5mm，重201g，内屏为7.6英寸，外屏为5.5英寸横向宽屏，配备12GB内存，最高提供1TB存储。该机有望于7月22日正式发布。","scd":null,"kp":["核心芯片[三星Galaxy Z Fold8]: 第五代骁龙8至尊版定制版","机身厚度[三星Galaxy Z Fold8展开状态]: 4.5mm","机身厚度[三星Galaxy Z Fold8折叠状态]: 9.7mm","整机重量[三星Galaxy Z Fold8]: 201g","内屏尺寸[三星Galaxy Z Fold8]: 7.6英寸"]},{"i":3762,"as":"","scd":null,"kp":[]},{"i":3763,"as":"","scd":null,"kp":[]},{"i":3764,"as":"","scd":null,"kp":[]},{"i":3765,"as":"","scd":null,"kp":[]},{"i":3766,"as":"针对乾崑智驾累计辅助驾驶里程数断网后仍滚动上涨的争议，华为官方回应称，前端展示数据基于真实里程动态展示，为避免网络传输时延导致数据卡顿，页面展示时做了平滑处理。若网络波动或中断，页面会基于已获取的最新数据继续连续滚动展示，直至逐步停止。截至发文，乾崑智驾累计辅助驾驶里程已超125亿公里。","scd":null,"kp":["累计里程[乾崑智驾辅助驾驶]: 超过125亿公里","数据展示技术[前端里程数据]: 采用平滑处理并以连续滚动方式呈现"]},{"i":3767,"as":"","scd":null,"kp":[]},{"i":3768,"as":"据曝光信息，小米增程车计划于7月底举办技术发布会，8月中下旬正式上市，并准备超1万台现车实现上市即交付。工信部公告显示小米汽车已增加增程式电动乘用车产品品种。首款增程SUV内部代号“昆仑N3”，归属于独立子品牌“寻天”，提供可升降车顶，预计可作为房车使用。","scd":null,"kp":["生产准备[小米汽车工厂]: 增加增程式电动乘用车产品品种","上市规划[小米首款增程式SUV]: 计划于2026年下半年推向市场"]},{"i":3769,"as":"","scd":null,"kp":[]},{"i":3770,"as":"","scd":null,"kp":[]},{"i":3771,"as":"","scd":null,"kp":[]},{"i":3772,"as":"华硕上架ProArt B850-Creator WiFi Neo主板，售价2399元。该主板采用ATX板型与8层PCB，支持AMD锐龙9000/8000/7000系列处理器，配备14+2+1相80A DrMOS供电。主板提供双5GbE有线网口与Wi-Fi 7网卡，拥有4条PCIe插槽和3个M.2盘位，支持最高9000+ MT/s内存超频，并预留雷电4/USB4接针。","scd":null,"kp":["主板价格[华硕ProArt B850-Creator WiFi Neo]: 2399元","高速有线网口[华硕ProArt B850主板]: 提供2个5GbE RJ45网口","CPU支持[华硕ProArt B850主板]: 支持AMD锐龙9000/8000/7000和霄龙4005处理器","内存支持[华硕ProArt B850主板]: 支持最高9000+ MT/s频率超频","无线网络[华硕ProArt B850主板]: 搭载Wi-Fi 7无线网卡"]},{"i":3773,"as":"","scd":null,"kp":[]},{"i":3774,"as":"","scd":null,"kp":[]},{"i":3775,"as":"","scd":null,"kp":[]},{"i":3776,"as":"德国聚变能源企业Proxima Fusion完成4.11亿欧元融资，公司估值达27亿美元，谷歌作为战略投资方参与其中。Proxima Fusion正致力于研发仿星器技术，计划在21世纪30年代初建成聚变示范装置，并在30年代后半段落地欧洲首座商用聚变电站。本轮融资将专门用于扩大高温超导线缆与超导磁体的产能，并建立仿星器全套工程与制造体系。","scd":null,"kp":["融资金额[Proxima Fusion]: 4.11亿欧元","公司估值[Proxima Fusion]: 27亿美元","战略目标[Proxima Fusion]: 打造欧洲首座商用核聚变发电站"]},{"i":3777,"as":"蔚来汽车计划今年下半年在上海嘉定区安亭镇建设新的电池技术研发中心。该设施将专注于下一代电池技术的研发，建成后将包含31个电池测试实验室、一条锂离子电池中试线以及一条电池包生产线。通过该项目，蔚来旨在进一步扩大其现有的电池研发规模。","scd":null,"kp":["研发重点[蔚来上海电池研究中心]: 下一代电池与锂离子电池中试线","测试配套[蔚来上海电池研究中心]: 包含31个测试实验室"]},{"i":3778,"as":"特斯拉在德国格伦海德超级工厂启动了名为“Cell Giga Challenge”的电池生产创新计划。该计划面向初创企业，重点招募改进电芯制造质量、效率、速度、成本、安全性和可扩展性的技术方案，涵盖材料、设备、制造工艺、自动化和人工智能等领域。初创企业将有机会在超级工厂直接测试其技术，助力电池产能提升至每年18吉瓦时。","scd":null,"kp":["产能目标[格伦海德电芯生产]: 18 GWh/年"]},{"i":3779,"as":"拆解网站iFixit探访了位于中国惠州的一家iPhone电池代工厂。制造过程显示，生产锂聚合物电池单元需要借助高度专业化的制造设备，并经过许多复杂的工艺步骤和严格的质量控制。这一过程表明，智能手机电池的制造难度与工艺复杂性远超大众预期。","scd":null,"kp":[]},{"i":3780,"as":"代理型人工智能技术正被应用于增强电动汽车供应链中的电池可追溯性。当前，供应链可视性要求已从一级供应商按时交付延伸至正负极材料、锂化合物、前驱体化学品乃至采矿环节。在监管要求、供应链风险和质量预期的共同推动下，AI技术正实现规模化的电池供应链追溯，以确保合规性并提升整体网络韧性。","scd":null,"kp":[]},{"i":3781,"as":"便携式发电站已成为离网露营和应对夏季停电等场景的可靠电源方案。随着锂离子电池在消费电子产品中的广泛普及，原本沉重且不可靠的备用电源产品得到了彻底革新。这些采用锂离子电芯的便携式储能设备正在取代传统嘈杂的汽油发电机，满足大众更广泛的用电需求。","scd":null,"kp":[]},{"i":3782,"as":"Alsym公司推出了一款无锂的钠离子电池储能系统（BESS），专为电网级存储设计。该电池采用钠、铁和硬碳等地球储量丰富的材料制造，具有不可燃的化学特性，从根源上消除了热失控风险。系统可在零下40摄氏度至60摄氏度的极端温度下仅依靠被动冷却运行。可再生能源开发商Juniper Energy计划在加州部署500兆瓦时的该储能系统。","scd":null,"kp":["部署规模[加州电网级储能]: 500 MWh","化学体系[无锂钠离子电池]: 钠、铁、硬碳（无钴、镍、锰）","安全性[不可燃钠离子电池]: 采用非易燃的磷酸焦磷酸铁钠化学体系，无热失控风险"]},{"i":3783,"as":"","scd":null,"kp":[]},{"i":3784,"as":"","scd":null,"kp":[]},{"i":3785,"as":"比亚迪在欧洲和英国市场推出其首款皮卡车型“Shark（鲨鱼）”，起售价约为63,000美元。该车搭载超级混合动力插电系统，纯电续航里程达56英里，性能表现远超传统柴油皮卡，目前已在全球多个市场销售。比亚迪高管表示，插电式混合动力皮卡市场正在迅速扩张。","scd":null,"kp":["起售价[英国市场]: 约 63,000 美元","纯电续航里程[比亚迪Shark皮卡]: 56 英里"]},{"i":3786,"as":"Waymo在拉斯维加斯正式启动了全无人驾驶网约车服务，车内不再配备人类安全员。此外，丹佛、圣地亚哥和坦帕也将陆续投入无人驾驶运营。此次新增四个全无人驾驶服务市场，是Waymo为实现到2026年底每周提供100万次付费出行目标的重要扩张举措。","scd":null,"kp":["运营状态[拉斯维加斯]: 实现全无人驾驶（无安全员）商业运营","商业目标[2026年底付费乘车量]: 100万次/周"]},{"i":3787,"as":"特斯拉在得克萨斯州奥斯汀的奥斯汀山商业中心租下了一栋面积达68.2万平方英尺的工业建筑。该建筑由Sansone Group开发，位于Decker Lake路，预计将于2027年1月竣工。目前尚不清楚特斯拉对该空间的具体用途，但这进一步扩大了其在得州中部庞大的地产版图。整个商业中心完工后总面积将达到140万平方英尺。","scd":null,"kp":["租赁面积[特斯拉奥斯汀]: 682,000 平方英尺","预计交付时间[工业大楼二期]: 2027年1月"]},{"i":3788,"as":"特斯拉推出了名为“特斯拉之家”的家庭能源管理平台。该平台由人工智能引擎Opticaster驱动，每天做出数百次决策来控制家庭电池、太阳能板、壁挂式连接器和智能断路器，从而优化电力消耗并降低电费。该系统作为Powerwall的标准配置，现有用户无需额外硬件即可使用，旨在将特斯拉的能源产品整合到统一界面中。","scd":null,"kp":["系统能力[Opticaster AI引擎]: 每天做出数百项电力存储与使用的优化决策"]},{"i":3789,"as":"Ariel Rider开放了新款MUDD 72V高性能两轮车的预售。该车被定位为仅供越野和封闭场地使用的私人财产车。车辆搭载72V系统，配备3500W额定功率的油冷后轮毂电机，峰值功率可达8000W，扭矩高达330牛·米。该车的最高时速可超过65英里（约105公里），是同级轮毂电机驱动车型中速度最快的机器之一。","scd":null,"kp":["最高时速[MUDD 72V自行车]: 65 英里/小时"]},{"i":3790,"as":"Unigrid推出了名为Na+Casa的钠离子住宅储能系统，目前已完成欧洲的初步安装，并计划于2026年在美国上市。该系统容量为9.25千瓦时，采用其专有的铬酸钠（NaCrO₂）阴极技术。与锂离子电池相比，该系统具备10000次的循环寿命、更宽的温度耐受范围以及更高的安全性，支持壁挂式安装。","scd":null,"kp":["循环寿命[钠离子住宅储能系统]: 10000次","正极技术[Na+Casa钠离子电池]: NaCrO₂","系统容量[壁挂式储能系统]: 9.25 kWh","安全性与温度耐受[对比锂离子电池]: 更宽的温度耐受与更高的安全性"]},{"i":3791,"as":"评级机构ICRA指出，由于输电基础设施建设滞后，印度约三分之一近期投产的可再生能源产能正面临电网限制削减的问题。在总计54.8吉瓦的新增可再生能源产能中，约33%受到弃电影响，且在太阳能发电时段的削减最为严重。持续的输电项目延期将阻碍印度可再生能源产能的进一步扩张。","scd":null,"kp":["产能面临削减比例[印度新增可再生能源]: 约三分之一"]},{"i":3792,"as":"阿尔及利亚政府设定了到2035年部署15吉瓦太阳能的目标。行业专家在网络研讨会上指出，为实现这一目标，阿尔及利亚需要向国际参与者开放能源市场，并建立明确吸引私营部门参与和国际投资的框架。目前，一项3.2吉瓦的太阳能开发计划已在推进中。","scd":null,"kp":["太阳能目标[阿尔及利亚2035年]: 15吉瓦","发展需求[阿尔及利亚太阳能市场]: 需加强私营部门参与、明确投资框架及国际合作"]},{"i":3793,"as":"南非国家能源监管机构（NERSA）向四个太阳能项目颁发了许可证，总装机容量超过1吉瓦，合同总容量达890兆瓦。这是南非可再生能源采购计划第七轮投标窗口的第三次增补。项目包括由Red Rocket SA在姆普马兰加省开发的278兆瓦Sculptor Energy太阳能项目等。","scd":null,"kp":["合同容量[南非四个太阳能项目]: 890 MW","总装机容量[南非四个太阳能项目]: 超过1 GW"]},{"i":3794,"as":"德国政府计划削减“联邦高效建筑资助计划（BEG）”中对住宅热泵安装的补贴额度。符合条件的成本上限将从3万欧元降至2.8万欧元，此后每六个月进一步减少750欧元，直至2030年下半年降至2.2万欧元。此外，新的规则将引入基于收入的更强有力支持，并计划为热泵生产推出“欧洲制造”的激励措施。","scd":null,"kp":["补贴政策变化[德国BEG高效建筑补贴计划]: 计划降低资金上限并引入基于收入的支持","原产地激励措施[热泵生产]: 计划引入“欧洲制造”奖励"]},{"i":3795,"as":"美国宾夕法尼亚州的一名首席电工在兰卡斯特职业与技术中心部署了一套6.4千瓦的太阳能加储能实训系统。该项目的特色是允许学生每年对太阳能电池板和支架进行拆卸和重建，旨在为未来劳动力提供亲自动手的实践培训。该项目得到了当地电力公司和职业技术基金会的资助支持。","scd":null,"kp":["系统规模[培训用太阳能储能系统]: 6.4 kW","[可重建太阳能阵列]: 支持学生每年拆解与重建以进行实操培训"]},{"i":3796,"as":"欧洲气候中和观察站（ECNO）发布报告指出，欧洲电网扩张、电力存储、灵活性及需求侧电气化进程未能跟上可再生能源增长的步伐。数据显示，2025年太阳能和风能等可变可再生能源占欧盟总发电量的30%，但在2020年至2025年期间，其份额增长速度过于缓慢。","scd":null,"kp":["基础设施现状[欧洲可再生能源规模扩大]: 电网扩张、储能及灵活性建设速度滞后"]},{"i":3797,"as":"国际研究团队研发出一种用于废旧光伏组件的高压水射流分层回收技术。该技术首先将玻璃与组件其他部分分离，随后对剩余物质进行处理，并在试验规模下成功回收了高纯度的银、铜、硅以及玻璃和聚合物成分。数据显示，该技术提取的银纯度高达97%。","scd":null,"kp":["提纯度[水射流分层回收获得的银]: 97%","[废旧光伏组件回收]: 采用高压水射流分层技术（先分离玻璃再处理剩余部分）"]},{"i":3798,"as":"TÜV NORD的研究团队通过模拟对比了背接触（BC）与TOPCon太阳能组件在局部阴影下的性能。结果表明，在温和阴影条件下（特别是当组件内不同子串上有3个或以下电池被遮挡时），BC组件性能优于TOPCon组件。但当被遮挡电池超过4个时，BC组件的性能优势消失，两者的功率损失均达到50%左右。","scd":null,"kp":["发电性能优势[背接触(BC)组件对比TOPCon组件]: 仅在温和局部阴影（不同子串中遮挡不超过3片电池）下表现更好","功率损失[遮挡超过4片电池时BC与TOPCon组件]: 约50%"]},{"i":3799,"as":"海尔针对商业应用推出了一款新型整体式空气-水热泵系列。该热泵系统采用R290（丙烷）作为制冷剂，提供26 kW、30 kW、35 kW和40 kW四种供热容量版本。该产品专为办公楼、小型商业设施以及需要高温供水改造的商业建筑项目而设计。","scd":null,"kp":["输出功率范围[丙烷工质商用空气-水热泵]: 26 kW至40 kW","制冷剂[海尔商用热泵]: 丙烷"]},{"i":3800,"as":"美国国防公司NUBURU与意大利国防公司Tekne合作，对其新型激光眩目器反无人机技术进行了测试。在受控的室内环境中，定向能系统成功实现了对无人机光电传感器的致盲饱和与光学干扰。测试记录了多种配置下的成功数据，为该技术的产品开发及未来系统集成提供了支持。","scd":null,"kp":["[激光眩目器反无人机测试]: 成功实现对无人机光电传感器的饱和与干扰"]},{"i":3801,"as":"法国机器人公司UMA在巴黎展会上发布了首款搭载实时学习AI架构的人形机器人。该架构允许机器人通过人类演示学习新任务，从而替代繁琐的手动编程，缩短部署时间。该机器人具备人体比例，主要面向制造业和物流业，首发市场为欧洲。","scd":null,"kp":["[人形机器人AI架构]: 支持通过人类演示进行实时学习的新型AI架构"]},{"i":3802,"as":"麻省理工学院（MIT）发布了一项可行性研究，提出利用卫星传感器系统探测在轨卫星中隐藏的核武器。此举旨在应对日益增长的太空核武器威胁，例如在约1200英里高空运行的俄罗斯Cosmos 2553卫星。若太空核武被引爆，释放的高能电子将摧毁GPS、蜂窝基站和数千颗在轨卫星。","scd":null,"kp":["轨道高度[俄罗斯Cosmos 2553卫星]: 约1200英里"]},{"i":3803,"as":"瑞典初创公司Nordic Air Defense（NAD）推出了一款名为K100XR的“智能”拦截无人机。在公开演示中，该无人机成功实时探测并拦截了目标无人机。K100XR的最高时速可达219英里/小时，旨在以更低的单次击杀成本替代昂贵的传统防空导弹，高效应对短程空中威胁。","scd":null,"kp":["最高时速[K100XR智能拦截无人机]: 219英里/小时"]},{"i":3804,"as":"美国橡树岭国家实验室的科研人员设计出一种新型分段式电机驱动架构，专为大型电动推进系统设计。模拟数据显示，该架构能将中性点电压波动降低90%，电容器电流应力下降43%。结构优化有效减少了内部热应力并延缓了机械退化，提升了高功率应用下的运行可靠性。","scd":null,"kp":["电压波动降低率[新型电传架构]: 90%","电流应力降低率[电容器]: 43%"]},{"i":3805,"as":"中国西北师范大学和甘肃烛龙科技的研究人员利用碳-14同位素和碳化硅换能器，自主研发出新一代核电池。与上一代相比，新电池在容量上实现了重大突破。放射性同位素的半衰期极长，使得该电池具有数十年甚至上百年的超长使用寿命，非常适合应用于航天器和远程环境传感器等领域。","scd":null,"kp":["核心材料[新一代核电池]: 碳-14同位素与碳化硅(SiC)换能器"]},{"i":3806,"as":"美国国防科技公司AZAK展示了一台重约227公斤的微型无人地面车辆（UGV）。在技术演示中，该微型机器人在携带1000磅（约453公斤）弹药的同时，成功拖动了重达24040公斤的美军重型后勤卡车。该机器人拖拽的总重量超过了其自身重量的100倍，展现了卓越的牵引能力。","scd":null,"kp":["自重[微型无人地面车辆]: 约227公斤","牵引能力[微型无人地面车辆]: 牵引24040公斤军用卡车","载重[微型无人地面车辆]: 1000磅弹药"]},{"i":3807,"as":"美国AMPERA公司获得了Adelphi Technology公司高产额中子发生器系统的独家使用权，用于加速其亚临界微型核反应堆平台的开发。该协议使AMPERA能够将外部中子源直接集成到其专有的反应堆架构中。与依赖自持链式反应的传统反应堆不同，其亚临界设计无法维持裂变过程，需依靠外部中子源启动和控制。","scd":null,"kp":["[亚临界微核反应堆架构]: 集成专用外部高产量中子源以启动和控制非常规裂变过程"]},{"i":3808,"as":"吉利汽车的新型短刀磷酸铁锂（LFP）电池在中国国家认证测试中创造了电动汽车充电新纪录。中国汽车技术研究中心确认，该电池的峰值充电功率达到1,093千瓦。在应对兆瓦级充电带来的热管理挑战中，该电池在最大功率充电时的峰值温度控制在64摄氏度，符合中国相关法规中电池温度须低于65摄氏度的要求。","scd":null,"kp":["充电峰值[吉利短刀磷酸铁锂(LFP)电池]: 1093千瓦"]},{"i":3809,"as":"德国基尔大学的研究团队开发出一种“会说话的电池”，能够无需额外数据线，直接通过电池内部的标准电源端子传输测量数据。该技术复用了充放电电子元件，能持续提供电池内部的健康更新状态。由于现代电池包通常仅在电池外部安装温度传感器，这种无缆内部通信技术能更好地防范过热风险，降低约35%的监控成本。","scd":null,"kp":["监控成本降低率[电动汽车“会说话的电池”]: 35%","[“会说话的电池”通信机制]: 利用标准电源端子而非单独的数据线缆传输内部测量数据"]},{"i":3810,"as":"科学家开发出一种名为OLE的实验性分子，能够通过协助大脑免疫细胞再次抑制有毒蛋白质沉积，恢复大脑对抗阿尔茨海默病的天然防御能力。发表在《Cell Death and Disease》上的动物研究结果表明，该分子成功减少了有害的β-淀粉样蛋白斑块，并有效改善了动物的记忆能力。","scd":null,"kp":["[实验分子(OLE)]: 恢复大脑天然防御能力，帮助免疫细胞抑制毒性蛋白沉积并改善记忆力"]},{"i":3811,"as":"物理学家通过操纵被限制在一维空间中的超冷铯原子，成功创造出一种被称为“分数费米海”的全新量子状态。这项发表在《物理评论快报》的研究证实，该状态可以通过周期性地反复改变原子间的相互作用强度被人为制造，揭示了超越传统理论框架的全新物质相及其隐藏秩序。","scd":null,"kp":["[量子态(分数费米海)]: 可人工诱导并揭示出超越传统理论的物质新相及隐藏有序态"]},{"i":3812,"as":"科学界长期对水被挤压进纳米级空间时的化学反应性存在争议。最新研究解开了这一数十年之谜，揭示了决定纳米空间内水分裂成水合氢离子和氢氧根离子的关键因素是压力而非仅仅是空间限制。这一发现对理解纳米孔、薄膜以及生物通道内的水化学性质具有重要意义。","scd":null,"kp":["[受限纳米空间]: 压力(而非微小空间本身)是决定水化学行为特征的核心因素"]},{"i":3813,"as":"","scd":null,"kp":[]},{"i":3814,"as":"","scd":null,"kp":[]},{"i":3815,"as":"","scd":null,"kp":[]},{"i":3816,"as":"","scd":null,"kp":[]},{"i":3817,"as":"马萨诸塞大学阿默斯特分校的研究人员开发出一种控制聚合物中原子振动的新方法，能够在不增加重量、不降低强度和不影响制造的前提下，更有效地阻挡热量传递和火灾。传统隔热材料依赖被困空气，但这会降低塑料的强度和耐用性。该技术通过在原子水平上改变热量在材料中的传递方式，突破了这一制造瓶颈。","scd":null,"kp":["[聚合物材料]: 通过调节原子振动路径，实现高效隔热且不损失强度、不增加重量及制造难度"]},{"i":3818,"as":"剑桥大学的研究团队与初创公司GlitterinTech合作，开发出一种结构紧凑、成本低廉的卷积光谱仪，成本仅需10美元。这种全新的光学设备能够提供实验室级别的精度，且体积小巧，足以集成到便携式和可穿戴电子产品中。该技术可应用于工业质量控制、无创健康监测、血糖检测和脱水识别等多种化学分析场景。","scd":null,"kp":["[紧凑型卷积光谱仪]: 成本低至10美元且具备实验室级精度，可实现非侵入式健康监测及工业质量控制"]},{"i":3819,"as":"","scd":null,"kp":[]},{"i":3820,"as":"万创科技在北京举办“能源AI边缘智能技术沙龙”，聚焦AI在电力、煤炭等能源领域的边缘智能落地路径。在新能源装机突破50%的背景下，AI边缘计算通过数据预处理、实时分析和预测性维护应对能源间歇性挑战。目前，万创科技已推出0.5Tops至150Tops的边缘算力产品矩阵及自主研发的VantronOS系统，并在储能、风电等领域实现国产化替代应用。","scd":null,"kp":["新能源装机占比[中国电力系统]: 超过50%","非化石能源发电量[中国电力系统]: 达50%","巡检缺陷识别率[电网无人机巡检]: 超过80%","缺陷识别种类[电网无人机巡检]: 46种"]},{"i":3821,"as":"蓝色起源计划以1300亿美元的估值筹集100亿美元的资金。","scd":null,"kp":["目标融资额[蓝色起源]: 100亿美元","公司估值[蓝色起源]: 1300亿美元"]},{"i":3822,"as":"中国人工智能公司MiniMax计划推出一款拥有2.7万亿参数的大型AI模型。","scd":null,"kp":["模型参数规模[MiniMax待发布大模型]: 2.7万亿"]},{"i":3823,"as":"OpenAI计划于周四正式公开发布其GPT-5.6系列人工智能模型。","scd":null,"kp":[]},{"i":3824,"as":"英伟达与人工智能芯片公司D-Matrix联合宣布推出一款全新的AI芯片系统。","scd":null,"kp":["[联合AI芯片系统]: Nvidia与D-Matrix共同研发"]},{"i":3825,"as":"亚马逊云服务（AWS）前政府销售主管已宣布加入人工智能初创公司Anthropic。","scd":null,"kp":[]},{"i":3826,"as":"SpaceXAI计划最快于周三推出一款带有Cursor功能的新人工智能模型。","scd":null,"kp":["[AI模型发布计划]: 计划最快周三推出带有Cursor的新模型"]},{"i":3827,"as":"SpaceX正式跻身纳斯达克100指数，但其股价在加入该指数后下跌了近7%。","scd":null,"kp":["[股价波动]: 下跌近7%","[市场动态]: 跻身纳斯达克100指数"]},{"i":3828,"as":"慕尼黑市启动了一个全新的智能配送区试点项目，对市中心的配送区域进行数字化改造。该项目旨在改善城市物流并减少交通拥堵，可为商业运输企业及其他用户群体提供实时的配送区信息。","scd":null,"kp":["[城市物流优化]: 推出智能配送区以改善城市物流并减少交通"]},{"i":3829,"as":"","scd":null,"kp":[]},{"i":3830,"as":"Pexapark报告显示，2026年上半年德国电池储能系统（BESS）采购量比2025年全年高出7%。其中，固定价格协议（FPA）容量从2025年的254MW激增153%至642MW。这一增长主要由首批共址BESS结构进入市场以及债务融资在BESS领域日益增长的作用驱动，贷款方要求电池资产拥有更高比例的固定收入。","scd":null,"kp":["BESS采购量增幅[德国上半年]: 较2025年全年增长7%","固定价格协议(FPA)规模[2026上半年]: 642 MW","FPA规模增幅[2026上半年较2025年]: 增长153%","市场驱动因素[德国BSS]: 共址BESS结构进入市场"]},{"i":3831,"as":"印度Serentica Renewables公司与SECI签署了一项太阳能结合储能项目的购电协议。该项目容量为600 MW并配备2,400 MWh储能，是在SECI的FDRE VII招标中获得的最大份额。根据协议，该项目将在非太阳能时段通过共址太阳能和BESS设施，每天提供600 MW连续4小时的2400 MWh保证峰值电力，直接解决用电高峰需求。","scd":null,"kp":["项目规模[印度太阳能+储能]: 600 MW / 2,400 MWh","招标要求[SECI FDRE VII]: 4,800 MWh (1,200 MW × 4小时)"]},{"i":3832,"as":"爱沙尼亚Hertz 2电池储能系统于7月7日开始运营，使其与姊妹设施Hertz 1的合计总容量达到200 MW/400 MWh。这两个项目总投资1.7亿欧元且未获政府补贴。该储能设施接入Elering电网，将提供频率调节服务，并参与日前和日内电力市场交易。","scd":null,"kp":["总储能规模[Hertz项目(爱沙尼亚)]: 200 MW / 400 MWh","投资金额[Hertz项目]: 1.939亿美元 (约1.7亿欧元)"]},{"i":3833,"as":"美国波特维尔联合学区与ForeFront Power合作，将建设集成太阳能、电池储能、可孤岛运行微电网和电动车队充电系统的综合设施。该项目包括分布在停车场的763 kW太阳能阵列，以及408 kW/1,632 kWh的锂离子电池储能系统。通过专用微网控制器，该系统可使学校与当地电网断开，实现孤岛运行，旨在提升电网韧性并推进车队电气化。","scd":null,"kp":["光伏阵列规模[PUSD微电网]: 763 kW","[系统部署特点]: 集成太阳能、电池储能、可孤岛微电网和电动车队充电系统"]},{"i":3834,"as":"伊泰普水电站正在开发一个与浮动太阳能电站相连的电池储能系统（BESS）试点项目，以评估电池如何改善太阳能与水电的整合。该示范项目目前处于规划阶段，其装机容量、存储时长、电池技术及投资金额等具体细节尚未确定。该项目旨在通过评估能源转移和运营灵活性，生成技术数据以支持未来的投资决策。","scd":null,"kp":["[项目阶段(伊泰普水电站)]: 处于规划阶段，装机容量等技术参数尚未确定","[系统架构特点]: 计划开发电池储能系统并联动漂浮式光伏进行整合评估"]},{"i":3835,"as":"OX2公司从BNRG Leeson手中收购了位于维多利亚州的晚期Corop太阳能农场和电池项目。该混合项目占地近1100公顷，包括230 MW的太阳能发电设施和容量为290 MW/1,160 MWh（4小时储能）的电池储能系统。项目已获得政府合同并取得关键开发审批，计划通过现有220 kV输电线路并网，为维多利亚州提供清洁电力并提升电网可靠性。","scd":null,"kp":["光伏装机规模[Corop太阳能项目]: 230 MW","电池储能规模[Corop项目]: 290 MW / 1,160 MWh","储能时长[Corop项目]: 最长4小时","[项目物理足迹]: 占地约1,100公顷"]},{"i":3836,"as":"Sungrow Renewables与ID Energy Group正在西班牙推进三个总规模为171.5兆瓦/726.4兆瓦时的电池储能系统项目。这些项目位于卡斯特利翁省的220千伏变电站附近。其中两个正在环评阶段的项目总容量为116兆瓦/506兆瓦时，配备184个电池集装箱，占地约2万平方米。第三个项目容量为55兆瓦/220兆瓦时。","scd":null,"kp":[]},{"i":3837,"as":"博世已开始大规模生产其燃料电池动力模块。同时，RAG Austria和安德里茨已为一座12.5兆瓦的绿色氢工厂破土动工。","scd":null,"kp":["工厂规模[绿色氢工厂]: 12.5兆瓦"]},{"i":3838,"as":"《电动汽车用动力蓄电池安全要求》新国标正式实施，动力电池产业竞争核心由价格转向安全。新国标从源头预防理念出发，设定了更严格的安全底线，引导企业将创新资源投入热管理、电芯设计及智能监测等领域。新增的快充循环后安全测试，紧跟超快充技术趋势，要求企业重点提升热扩散防控、底部防护和电池健康监测等全生命周期管理能力。","scd":null,"kp":["实施时间[动力蓄电池安全要求新国标]: 7月1日起正式实施（GB 38031-2025）","安全理念[动力蓄电池新国标]: 从事故发生后的预警转向事故源头的预防"]},{"i":3839,"as":"碳蕴能源科技（扬州）有限公司研制出我国首台超临界CO₂车载空调。实测数据显示，其原型机制冷能效比为3.05，制热能效比达3.25，较传统空调提升40%以上。该技术解决了传统氟利昂空调低温制热效率低和电动车冬季续航衰减的问题，未来可拓展至化工、核电及储能等多个领域。","scd":null,"kp":["制冷能效比[超临界CO₂车载空调原型机]: 3.05","制热能效比[超临界CO₂车载空调原型机]: 3.25（较传统空调提升40%以上）","适用规模[超临界CO₂换热装备延伸储能产品]: 百千瓦到百兆瓦级"]},{"i":3840,"as":"合肥综合性科学中心环境研究院成功实现生物炭高效规模化制备。项目团队发明了生物质催化转化干法一步法制备生物炭技术，突破了传统技术收率低、能耗高等瓶颈，单台高压炭化装置年产量超5万吨。成果总体达国际先进水平，已开发出应用于储能、催化等领域的生物碳基新材料，并在多地推广。","scd":null,"kp":["单台年产量[高压炭化装置制备生物炭]: 5万吨以上","工艺特点[生物炭制备]: 生物质催化转化干法一步法"]},{"i":3841,"as":"西南石油大学科研团队研发出小尺寸超高效叠层太阳能电池，光电转换效率接近35%，突破了常规电池理论极限。团队采用硅基异质结技术，将宽带隙钙钛矿顶电池与窄带隙晶硅异质结底电池串联，利用两者对不同波长光线的互补吸收特性提升效率。目前已有12项相关成果在企业转化落地。","scd":null,"kp":["光电转换效率[小尺寸超高效叠层太阳能电池]: 接近35%","光电转换效率极限[晶硅电池]: 29.4%","实际转化效率[钙钛矿单结电池]: 28%左右","理论效率[钙钛矿单结电池]: 33%","叠层技术[硅基异质结]: 结合晶体硅与非晶硅，作为晶硅与钙钛矿叠层的理想底层技术"]},{"i":3842,"as":"在人工智能快速迭代下，预计今年我国人形机器人整机产量将突破10万台。目前规上工业企业人工智能应用普及率已超30%。产业界已研制近200项关键标准，开源社区注册用户超1100万，国家人工智能产业投资基金正加大支持力度。即将举办的2026世界人工智能大会展览面积超10万平方米，超300款产品将全球首发。","scd":null,"kp":["整机产量[我国人形机器人全年预期]: 突破10万台","应用普及率[我国规上工业企业人工智能]: 超过30%","开源规模[AtomGit开源社区]: 注册用户超1100万"]},{"i":3843,"as":"国家发改委披露了我国人工智能产业“十五五”期间的五大工作思路：一是加快模型、算力、数据等关键技术自主创新；二是强化应用牵引，开放高价值场景；三是深化软硬件适配与产学研生态协同；四是坚持开放共赢，开展国际合作与开源普惠；五是确保安全可控，统筹发展与安全，加快推进人工智能立法并防范数据风险。","scd":null,"kp":[]},{"i":3844,"as":"赛迪顾问提出加快建设农业强县以筑牢农业强国基石。农业强县统筹推进科技、绿色、质量、品牌“四个农业”建设，全链条升级现代农业体系。具体经验包括：深耕良田良种，推进高标准农田建设与优质品种推广以保障粮食安全；加强科技创新，引入物联网与大数据搭建智慧农业管控体系，实现生产精准化与化肥农药减量增效。","scd":null,"kp":[]},{"i":3845,"as":"在北京市海淀区龙徽1910文化创意产业园举行的2026“食”光奇遇季活动中，展示了人形机器人斗舞、机器狗互动等多项科技产品，吸引了众多市民的关注与互动。","scd":null,"kp":[]},{"i":3846,"as":"中国科学院分子植物科学卓越创新中心致力于植物基础研究“从0到1”的前沿创新。林鸿宣院士团队历时8年成功克隆首个水稻耐热QTL基因TT1，为极端高温下的水稻稳产和粮食安全提供理论基础。中心为青年科研人员提供5年专项启动经费及跨学科交流平台，保障其深耕长期基础研究。","scd":null,"kp":["研发成果[水稻抗逆和高产基因挖掘]: 成功克隆首个水稻耐热QTL基因TT1"]},{"i":3847,"as":"受半导体超级周期及技术竞争力回升提振，韩国三星电子今年第二季度营业利润达89.4万亿韩元（约合3989亿元人民币），同比增长超1810%。该公司单季营业利润已超过去年全年总额的两倍，创下历史新高。","scd":null,"kp":["营业利润[三星电子二季度]: 89.4万亿韩元","同比增长率[三星电子二季度营业利润]: 超过1810%","人民币折算[三星电子二季度营业利润]: 约3989亿元"]},{"i":3848,"as":"我国正大力推进城市地下管网数智化升级，目前管网总长度近390万公里。成都采用智慧排水综合管控平台集成物联感知与数字孪生系统，并运用CCTV检测机器人、隧道积水监测机器人与非开挖修复机器人，实现管网智能巡检与精准修复，保障城市排水系统安全运行。","scd":null,"kp":["管网总长度[中国已建成管网]: 近390万公里","排水管网管护规模[成都中心城区]: 近8000公里","报警阈值[下穿隧道积水监测]: 超过30厘米"]},{"i":3849,"as":"基础科研成果在走向临床应用过程中常面临周期长、投入大、失败率高的“死亡谷”困境。中国科学院生物与化学交叉研究中心致力于跨越这一鸿沟，通过提供制度、资金和平台支持，构建完善的成果转化体系，帮助科研人员将原创性基础发现转化为实际临床药物。","scd":null,"kp":[]},{"i":3850,"as":"2026世界人工智能大会将于7月在上海召开，展览面积超10万平方米，超300款AI产品将全球首发，涵盖华为Atlas 950超节点、MiniMax大模型、阶跃Agent操作系统及多款人形机器人等。我国人工智能产业规模已破万亿元。大会首设学术会议，并深入探讨人工智能全球治理议题。","scd":null,"kp":["首发产品数量[2026世界人工智能大会]: 超300款","展览总面积[2026世界人工智能大会]: 突破10万平方米","意向合作金额[2026世界人工智能大会]: 162亿元","核心场景落地数[2026世界人工智能大会]: 57个","参展企业规模[2026世界人工智能大会]: 1100余家"]},{"i":3851,"as":"","scd":null,"kp":[]},{"i":3852,"as":"拓展智能经济需以场景应用为牵引，将AI技术深度融入制造业等实体经济全流程。通过部署工业大模型、数字孪生和机器人集群，打造全流程智能闭环的“灯塔工厂”场景。同时，在产业集群层面培育“产业大脑”赋能场景，实现数据互通与生产资源最优配置，破解传统产业效率瓶颈。","scd":null,"kp":["发展理念[场景应用牵引]: 围绕场景配技术、开放场景育产业、依托场景促治理","核心特征[智能经济场景应用]: 需求挖掘—协同创新—规模推广闭环链条"]},{"i":3853,"as":"伴随《人工智能拟人化互动服务管理暂行办法》正式施行，豆包与千问平台于7月15日同步下线智能体功能。智能体具备任务规划、工具调用、长期记忆与角色设定能力，易产生持续性情感互动风险。新规严禁模拟自然人人格特征与情感互动服务，重点对平台责任与相关服务划定监管红线。","scd":null,"kp":["功能下线时间[豆包及千问智能体]: 7月15日","生效时间[《人工智能拟人化互动服务管理暂行办法》]: 7月15日","核心特征[智能体]: 以大模型为核心，能够理解任务、调用工具并在一定权限内完成任务闭环","技术区别[智能体与普通AI]: 普通AI为顾问式问答，智能体为被赋予权限的数字员工"]},{"i":3854,"as":"随着AI从大模型向智能体跃迁，其自主决策与工具调用能力引发新型安全风险。智能体攻击呈现出自主感知、集群协同与持续进化的特征，能在极短时间内从多入口并发，传统信任与防御机制面临失效。专家建议通过核心技术攻关、制度规则建设及标准体系引领，筑牢智能体发展与安全防线。","scd":null,"kp":["技术跃迁阶段[人工智能]: 从大模型向智能体跃迁","安全风险演变[智能体时代]: 从被动执行的技术故障扩展为自主决策失控","渗透领域[智能体]: 制造、金融、能源等关键领域"]},{"i":3855,"as":"根据欧洲气候观察报告（ECNO），欧盟目前在其气候中和转型进程中偏离了预定正轨。","scd":null,"kp":["[欧盟现状]: 气候中和转型方面偏离正轨"]},{"i":3856,"as":"英国政府正式批准了装机容量为740兆瓦（MW）的One Earth太阳能项目。","scd":null,"kp":["项目装机容量[One Earth太阳能项目]: 740兆瓦"]},{"i":3857,"as":"Aream公司出售了位于西班牙的太阳能发电场投资组合，该投资组合的总装机容量为26.3兆瓦峰值（MWp）。","scd":null,"kp":["装机容量[西班牙太阳能发电场投资组合]: 26.3 MWp"]},{"i":3858,"as":"阿特斯阳光电力旗下全球电站开发主体Recurrent Energy完成管理层更迭。原阿特斯首席运营官（COO）Dylan Marx卸任原职，接替Ismael Guerrero出任该子公司首席执行官。Guerrero将以非执行顾问身份留任至2026年12月31日以保障业务平稳过渡。阿特斯集团表示将依托Marx的运营经验持续赋能子公司业务拓展。","scd":null,"kp":[]},{"i":3859,"as":"大唐平利县100MW（交流侧）/112.46MWp（直流侧）光伏项目环评受理公示。该项目位于安康市平利县，总投资4.2亿元，规划永久占地7078平方米，工期12个月。项目采用“茶光互补”模式，将安装17.3万块650Wp的N型单晶双面双玻组件。建设单位为大唐富平热电有限公司，控股股东为大唐陕西发电有限公司。","scd":null,"kp":["装机容量[大唐平利县光伏项目交流侧]: 100MW","装机容量[大唐平利县光伏项目直流侧]: 112.46MWp","投资金额[大唐平利县光伏项目]: 42000万元","占地面积[大唐平利县光伏项目]: 7078㎡","施工工期[大唐平利县光伏项目]: 12个月"]},{"i":3860,"as":"昆明市发改委发布通知，对部分分布式新能源项目全容量并网时间认定异议项目进行更正并再次公示。此前昆明曾公示2025年6月至2026年5月的分布式新能源项目全容量并网时间清单，部分业主对清单提出异议。经昆明供电局核查确认异议属实，为确保认定结果公平，相关部门对存在异议的项目信息予以更正并重新公示。","scd":null,"kp":[]},{"i":3861,"as":"受土地成本、限电及交易电价不确定性影响，光伏投资热度大幅降温。2026年前5个月，国内光伏新增装机同比下降70%，多地企业甚至放弃已获指标项目的建设。在市场萎缩下，光伏设备企业陷入价格战，浙能2.52GW组件集采中标最低价跌至0.685元/W，低于行业全成本价，反内卷工作难以落实。","scd":null,"kp":["装机变化[2026年前5个月国内光伏新增装机]: 同比下降70%","中标价格[浙能2.52GW光伏组件集采最低价]: 0.685元/W","组件平均全成本[CPIA测算银价20元/g时]: 0.824元/W"]},{"i":3862,"as":"越南光伏组件年产能突破30GW，但面临严重的国内电网消纳限制和美国加征的反倾销/反补贴关税。超80%的产能集中在其北部三省，主要服务于美国市场。2022年美国指控中国光伏企业借越南设厂规避关税，并于2023年终裁征税。尽管曾设两年豁免期，但到期后关税全面恢复，叠加全球组件价格暴跌40%，导致越南光伏制造业面临买家流失的产能过剩危机。","scd":null,"kp":["产能占比[越南光伏组件产能占全球需求]: 约10%","价格跌幅[2024-2025年全球光伏组件价格]: 约40%","产能集中度[越南北部三省光伏制造产能]: 超过80%","产能规模[越南北江省光伏产业集群组件产能]: 超过15GW"]},{"i":3863,"as":"","scd":null,"kp":[]},{"i":3864,"as":"","scd":null,"kp":[]},{"i":3865,"as":"","scd":null,"kp":[]},{"i":3866,"as":"小米总裁卢伟冰在REDMI Note 17系列（定档7月14日发布）预热时指出，近期手机行业成本暴涨对千元机冲击最大，导致OLED屏、满级防水等配置锐减。Note 17系列主打品质、续航和服务，坚持“升配不升档”，通过顶级电池材料与空间架构优化达成REDMI机型最大电量。爆料显示该系列搭载骁龙6系低功耗芯片、1.5K直屏、9K级单电芯电池以及满级防水防摔。","scd":null,"kp":["电池技术[小米REDMI Note 17系列]: 9K级大容量单电芯电池","芯片规格[小米REDMI Note 17系列]: 骁龙6系低功耗芯片"]},{"i":3867,"as":"吉利汽车宣布旗下2026款吉利银河A7 EM车型以2608.360公里的成绩，创下吉尼斯世界纪录，成为驾驶插混量产轿车零补能行驶最远距离的车型。该车限时先享价8.98万元起，轴距2845mm，拥有235km纯电续航和2150km综合续航，馈电油耗低至2L级。车辆配备14.6英寸2K中控屏、Flyme Auto 2座舱及千里浩瀚H3辅助驾驶方案。","scd":null,"kp":["续航里程[吉利银河A7 EM零补能行驶]: 2608.360km","轴距[吉利银河A7 EM]: 2845mm","纯电续航[吉利银河A7 EM]: 235km","综合续航[吉利银河A7 EM]: 2150km","馈电油耗[吉利银河A7 EM]: 2L级"]},{"i":3868,"as":"王成善院士团队领衔的“松辽盆地国际大陆科学钻探工程”获2025年度国家科技进步一等奖。该项目历时近二十年，成功钻取白垩纪地层，创下国际大陆科学钻探最深钻孔、最长连续岩芯和超高取芯率（95%以上）三项世界纪录。项目团队自主构建全流程钻探技术体系，钻获超8000米连续岩芯，为研究地球典型温室气候时期提供了科学数据，标志着我国在该领域跻身世界前列。","scd":null,"kp":["钻探深度[松科二井]: 8000多米","取芯率[松科二井]: 95%以上","技术成就[松科二井项目]: 国际大陆科学钻探最深钻孔、最长连续岩芯和超高取芯率三项世界纪录"]},{"i":3869,"as":"腾达正式上架3000M WiFi路由放大器A33 V2.0，售价169元。该设备专为90-100平方米户型设计，采用白色外观，搭载双核1.2GHz处理器与2颗外置FEM，支持Wi-Fi 6网络。机身配备1个千兆网口，提供信号扩大、路由、Mesh组网及AP有线中继四种工作模式，满足不同家庭网络扩展需求。","scd":null,"kp":["无线速率[腾达A33 V2.0路由器]: 3000M","处理器[腾达A33 V2.0路由器]: 双核1.2GHz","覆盖面积[腾达A33 V2.0路由器]: 90-100平方米","网络支持[腾达A33 V2.0路由器]: Wi-Fi 6"]},{"i":3870,"as":"针对网传“暴雷跑路、管理层停薪”等传闻，湖南汽车经销商兰天集团发布声明予以否认，强调相关言论均不实，目前集团整体经营稳定向好，员工薪资按时发放。数据显示，兰天集团成立于1997年，拥有88家4S店，2025年整车销量近8万台，营业收入156.7亿元，位列中国汽车经销商集团百强第36名。","scd":null,"kp":[]},{"i":3871,"as":"因第15轮劳资谈判破裂，韩国现代汽车工会宣布将于7月13日至15日实施每天两小时的部分罢工。资方最新方案提出基本工资上调8.9万韩元及1000万韩元奖金，但被工会认为低于预期。同属韩国三大车企的通用和起亚工会也正计划采取强硬措施。车企强劲的业绩表现是工会要求增加营业利润分红及延长退休年龄的主要谈判背景。","scd":null,"kp":["罢工时长[现代汽车工会部分罢工]: 每天2小时","基本工资上调[资方新提案]: 8.9万韩元","绩效奖金[资方新提案]: 基本工资的350%外加1000万韩元","库存股发放[资方新提案]: 15股"]},{"i":3872,"as":"苹果宣布macOS 28将彻底停止支持旧版“Mac OS 扩展（日志式，加密）”文件系统格式。自macOS 26起，系统在检测到该格式外置磁盘时将发出兼容性警告。苹果推荐用户使用“磁盘工具”将其转换为APFS加密格式。APFS是苹果自2017年推出的新一代文件系统，具备原生加密、空间共享与优化SSD性能等优势，现已成为启动盘的唯一指定格式。","scd":null,"kp":["文件系统支持[macOS 28]: 取消“Mac OS 扩展（日志式，加密）”格式","文件系统格式预警[macOS 26]: 检测到加密扩展外置磁盘时发出提醒"]},{"i":3873,"as":"","scd":null,"kp":[]},{"i":3874,"as":"","scd":null,"kp":[]},{"i":3875,"as":"大疆发布行业应用首款无人机降落伞DJI AP100，适配Matrice 400无人机，售价7488元。该设备重约935克，具备IP55防护等级，支持自动与手动触发，可在600毫秒内完成旋翼停转与开伞。AP100内置独立飞控与IMU传感器形成双链路冗余，断电下独立续航1小时。该设备满足欧盟及英国多项适航安全要求，且不影响无人机电池更换。","scd":null,"kp":["适配机型[DJI AP100无人机降落伞]: Matrice 400","产品售价[DJI AP100无人机降落伞]: 7488元","设备重量[DJI AP100]: 约935克","防护等级[DJI AP100]: IP55","工作温度[DJI AP100]: -20°C至50°C"]},{"i":3876,"as":"","scd":null,"kp":[]},{"i":3877,"as":"研究发现噬菌体T8的门静脉蛋白Gp8能够通过结合RelA和SpoT，抑制其合酶活性，从而减少警报素积聚，对抗宿主的严紧反应限制。破坏该相互作用的门蛋白突变会导致警报素水平持续升高、裂解延迟并损害噬菌体复制。这一机制揭示了噬菌体克服宿主生理限制的途径。","scd":null,"kp":["自动驾驶架构[尊界S800 Grand Design典藏大观]: 面向L3+高阶设计","车辆起售价[尊界S800 Grand Design典藏大观]: 138.8万元","前脸设计[尊界SUV测试车]: 沿用V800设计"]},{"i":3878,"as":"","scd":null,"kp":[]},{"i":3879,"as":"","scd":null,"kp":[]},{"i":3880,"as":"","scd":null,"kp":[]},{"i":3881,"as":"","scd":null,"kp":[]},{"i":3882,"as":"字节跳动发布多模态图像创作模型Seedream 5.0 Pro。相比以往版本，该模型在图文匹配、结构合理性、文字渲染与画面美感上全面提升。具备复杂信息可视化、交互式精准编辑（支持点选、圈选、图层分离等）、真实质感还原能力，并支持十余种常用语言的直接输入与高质量渲染。该模型现已上线火山方舟体验中心，并将陆续在豆包及即梦上线。","scd":null,"kp":["多语言直接输入与渲染[Seedream 5.0 Pro]: 支持十余种世界常用语言","复杂信息可视化[Seedream 5.0 Pro]: 将数据、概念与密集文字准确转化为专业排版","交互式精准编辑[Seedream 5.0 Pro]: 支持点选、圈选、草图渲染等空间与区域语义可控编辑"]},{"i":3883,"as":"AESC已开始为其新型46120圆柱形电池进行量产，首批将供应宝马全电动BMW iX5，该车计划于2026年底或2027年初上市。这款新型圆柱电池直径46毫米，高120毫米。与以往格式相比，其单体可用能量增加了近30%，同时减少了电池包所需的电芯和组件数量，简化了系统集成并提升了汽车设计的灵活性。","scd":null,"kp":["电池型号[AESC量产新型电池]: 46120圆柱形电池","电池尺寸[AESC 46120]: 直径46mm，高度120mm","首发搭载车型[AESC 46120]: 全新纯电BMW iX5","量产状态[AESC 46120]: 已开始批量生产"]},{"i":3884,"as":"基尔大学的研究人员为电池开发了一种新型通信系统，无需额外的数据线即可传输电池内部的传感器数据。该系统利用现有的电源连接，通过负责控制电池充放电过程的电力电子设备来传输测量数据。这项技术省去了电池内部额外的通信电缆，简化了设计，使电池管理系统更具成本效益且更加安全。","scd":null,"kp":["数据传输机制[基尔大学新型电池通信系统]: 无需额外数据线即可传输电池内部传感器数据"]},{"i":3885,"as":"固态电池在能量密度、安全性和性能上具有巨大潜力，被视为能源存储的未来。随着该领域逐渐成熟，研究人员和制造商正面临能量密度、界面稳定性、堆叠压力与成本之间复杂的相互作用与权衡。当前的关注点已从固态电池是否具有潜力，转向确定其具体的性能极限及其背后的化学选择如何影响能量密度与可扩展性。","scd":null,"kp":[]},{"i":3886,"as":"","scd":null,"kp":[]},{"i":3887,"as":"","scd":null,"kp":[]},{"i":3888,"as":"","scd":null,"kp":[]},{"i":3889,"as":"","scd":null,"kp":[]},{"i":3890,"as":"比亚迪子品牌腾势在古德伍德速度节上展示了全新电动跑车Denza Z。该车型拥有超过1500匹马力，并支持5分钟闪充。比亚迪将其定位为“全球首款智能超级跑车”，起售价接近20万美元，主要竞争欧洲顶级豪华车企。Denza Z将提供Coupe、Spider和Racing三种版本，标志着比亚迪在高性能豪华电动汽车领域的进一步拓展。","scd":null,"kp":["车辆马力[比亚迪腾势Z]: 超过1500 hp","充电时间[比亚迪腾势Z]: 最快5分钟","车辆起售价[比亚迪腾势Z]: 近20万美元"]},{"i":3891,"as":"Trek推出全新Borrego+胖胎电动自行车，以进军快速增长的油门控胖胎细分市场。标准版Borrego+被定义为2级电动自行车，配备750W后轮毂电机，扭矩90牛·米，搭配续航可达97公里的720Wh可拆卸电池。此外，Trek还为允许3级电动自行车的市场提供了速度更快的Borrego+ S版本，融合了冒险性能与通勤实用性。","scd":null,"kp":["产品定位[Trek Borrego+]: Class 2胖胎电动自行车"]},{"i":3892,"as":"小米官方澄清，Sky Nomad（小米鹏程）并非独立子品牌，而是小米汽车旗下的第二个产品系列。小米同时发布了该系列首款车型的清晰预告图，这是一款硬朗方正的增程式SUV。小米CEO雷军表示，SU7/YU7系列与Sky Nomad系列将根据不同的使用场景进行划分。这一宣布终结了此前关于Sky Nomad将作为独立新品牌运作的传闻。","scd":null,"kp":["品牌属性[小米Sky Nomad]: 小米汽车旗下的第二个产品系列，非独立子品牌","首款车型定位[小米Sky Nomad]: 硬派、方正的增程式SUV"]},{"i":3893,"as":"中国制造商AlphaESS推出专为工商业应用设计的Storion-LC-TB150液冷电池储能系统。该系统额定功率150kW，储能容量313kWh，采用全液冷架构和超低噪音设计（低于60 dB(A)），非常适合对噪音敏感的商业和城市环境。产品提供标准版和超能版，循环寿命分别可达8000次和12000次。","scd":null,"kp":["系统额定功率[工商业储能系统Storion-LC-TB150]: 150 kW","系统容量[工商业储能系统Storion-LC-TB150]: 313 kWh","系统循环寿命[液冷电池储能系统标准版]: 最高8000次","系统循环寿命[液冷电池储能系统Ultra版]: 最高12000次","热管理技术[Storion-LC-TB150电池储能系统]: 液冷"]},{"i":3894,"as":"乌克兰国家能源和公用事业监管委员会批准了针对居民、小型企业和能源合作社太阳能装置的新上网电价补贴（FiT）。这项被称为“绿色电价”的补贴政策，确保将可再生能源装置的多余电力出售给国家电网的用户能获得国家担保付款。新的居民太阳能装置规模限制在30kW以内，新电价政策将持续实施至2029年底。","scd":null,"kp":["政策有效期限[乌克兰太阳能上网电价补贴]: 至2029年底","补贴覆盖范围[乌克兰太阳能上网电价补贴]: 居民、小型企业和能源合作社"]},{"i":3895,"as":"奥地利在唐纳斯基兴启用了首个专为铁路电网供电的追踪式农光互补设施。这座6.6兆瓦的设施采用单轴跟踪支架，将产生的太阳能电力直接输送至奥地利16.7赫兹的铁路电网。奥地利联邦铁路公司（ÖBB）通过其铁路电网直接接收太阳能电力，同时Esterhavy Betriebe AG在同一地点继续进行有机农业耕作，实现了可再生能源发电、有机农业与生物多样性的结合。","scd":null,"kp":["设施装机容量[奥地利Donnerskirchen牵引供电追踪式农业光伏]: 6.6 MW","系统功能[奥地利首个追踪式农业光伏系统]: 结合可再生能源发电、有机农业和生物多样性措施并直接馈入铁路电网"]},{"i":3896,"as":"意大利环境与能源安全部已批准566个自用光伏项目的申请进入评估阶段。该批项目位于意大利南部地区，申请的激励总价值约为5900万欧元。此项支持计划总预算为2.62亿欧元，目前仍有超过2亿欧元的资金尚未分配。","scd":null,"kp":["补贴总预算[意大利南方企业自用光伏项目激励计划]: 2.62亿欧元","资金未分配额度[意大利南方企业自用光伏项目激励计划]: 超过2亿欧元","批准申请数[意大利南方企业自用光伏项目激励计划]: 566个"]},{"i":3897,"as":"印度太阳能电池和组件制造商Premier Energies在特伦甘纳邦启用了一座产能为5.6吉瓦的太阳能组件制造工厂。该工厂配备了先进的G12R TOPCon组件生产线和印度首个零主栅制造单元。随着该工厂投产，该公司的组件总产能已达到11.1吉瓦。此外，该公司还动工建设一座6吉瓦时的电池储能系统工厂及年产1.8万吨的铝边框制造厂。","scd":null,"kp":["制造产能[印度Premier Energies太阳能组件工厂]: 5.6 GW","制造产能[印度Premier Energies电池储能系统(BESS)工厂]: 6 GWh","制造产能[印度Premier Energies铝边框工厂]: 18,000公吨/年"]},{"i":3898,"as":"慕尼黑工业大学和奥地利供热专家iDM Energiesysteme对德国南部761套住宅空气源热泵的运行情况进行了分析。研究结果表明，即使在冬季用电高峰期，这些热泵系统也极少在最大技术容量下运行。通过智能控制和储热策略，住宅热泵在极端寒冷天气下仍具有显著的操作灵活性，能够实现电网负荷的优化转移并降低用电峰值需求。","scd":null,"kp":["运行特性[住宅空气源热泵(极寒条件)]: 极少以满负荷运行，保留显著的运行灵活性","系统策略[住宅热泵智能控制与储热]: 可实现电网友好型负荷转移并降低峰值电力需求"]},{"i":3899,"as":"法国生态与团结过渡部在2021-2026年期间的第十二轮工商业屋顶光伏系统招标（针对500千瓦以上项目）中，共分配了300.2兆瓦的容量。本次招标共选出326个项目，平均最终价格为0.082欧元/千瓦时，确认了该细分市场成本的下降趋势。此次招标吸引了广泛关注，共提交了1159份申请，总申请容量达1560兆瓦，超过最终分配容量的五倍。","scd":null,"kp":["分配容量[法国工商业屋顶光伏招标(第12轮)]: 300.2 MW","中标项目数[法国工商业屋顶光伏招标(第12轮)]: 326个","平均最终中标价格[法国工商业屋顶光伏招标(第12轮)]: 0.082欧元/kWh","项目准入门槛[法国工商业屋顶光伏招标(第12轮)]: 装机容量大于500 kW"]},{"i":3900,"as":"阿根廷能源秘书处正式授予了AlmaSADI电池储能招标项目，在阿根廷互联系统（SADI）的关键节点分配了总计700.5兆瓦的电池储能系统（BESS）项目。这些项目位于布宜诺斯艾利斯大都市区之外，旨在加强国家电网。共有五家开发商中标20个项目，估计投资额为7亿美元。其中，Genneia获得了7个项目。","scd":null,"kp":["总分配容量[阿根廷AlmaSADI电池储能招标]: 700.5 MW","中标项目数[阿根廷AlmaSADI电池储能招标]: 20个","预估投资额[阿根廷AlmaSADI电池储能招标]: 7亿美元"]},{"i":3901,"as":"西班牙推出了首个国家农业光伏项目地图，旨在通过经过验证的地理定位数据库追踪正在运行和计划中的安装项目。该举措是AURA平台的核心支柱，由西班牙农业、渔业和食品部提供资金支持。其目的是提高透明度、支持系统规划并提供标准化数据，从而促进农业光伏系统在农村地区的有效部署，并协助西班牙完善相关监管框架。","scd":null,"kp":["项目功能[西班牙国家农业光伏项目地图]: 通过经验证的地理定位数据库追踪运营中和计划中的安装项目，以提高透明度并支持监管框架发展"]},{"i":3902,"as":"中国制造商隆基在其位于陕西西咸的生产基地开始生产21吉瓦的背接触（BC）太阳能电池。该项目首次在吉瓦级规模上部署了其无银合金接触矩阵（ACM）金属化技术。这种基于铜的金属化工艺旨在替代传统的银导电浆料，目标是降低制造成本、提升BC电池的市场竞争力，并推动背接触组件的更广泛工业化应用。","scd":null,"kp":["制造产能[隆基铜金属化背接触太阳能电池工厂]: 21 GW","核心技术[隆基背接触电池(BC)大规模生产]: 无银合金接触矩阵(ACM)金属化技术(基于铜的工艺)"]},{"i":3903,"as":"英国已将位于萨福克郡的塞兹韦尔B（Sizewell B）核电站的运营期限延长20年，确保其能运行至2055年，持续为约250万户家庭提供低碳电力。该核电站是英国目前唯一运行的压水反应堆，自1995年开始发电。此次延寿决定预计将在英国核能“黄金时代”的背景下创造900个熟练技术工作岗位。","scd":null,"kp":["运行寿命延长[塞兹韦尔 B 核电站]: 20年","供电规模[塞兹韦尔 B 核电站]: 约250万户家庭","运行截止年份[塞兹韦尔 B 核电站]: 2055年","提供就业岗位[塞兹韦尔 B 核电站延寿项目]: 900个高技能岗位"]},{"i":3904,"as":"能源项目促进机构GridMarket与核技术开发商Deployable Energy达成一项为期40年的商业协议，计划在美国部署模块化微反应堆（核电池）。该合作预计总投资额达1450亿美元，目标是在2035年前安装超过3吉瓦的电力容量。项目将重点为数据中心、云基础设施和工业制造厂提供持续可靠的电力。此前，Deployable Energy的Unity原型核电池系统已成功实现临界状态。","scd":null,"kp":["合同总价值[美国模块化微反应堆部署协议]: 1450亿美元","合同期限[美国模块化微反应堆部署协议]: 40年","部署电力容量目标[美国微反应堆项目]: 3000兆瓦 (>3吉瓦)","实现年份[微反应堆部署电力容量目标]: 2035年","主要应用方向[模块化微反应堆]: 数据中心、云基础设施及工业制造厂"]},{"i":3905,"as":"德国柏林亥姆霍兹中心（HZB）的研究人员利用钙钛矿材料成功研发出一款高效的三结太阳能电池。该新型电池结构类似汉堡，通过分层堆叠实现光电转换效率高达27.3%。同时，该电池组件展现出极佳的稳定性，在连续运行770小时后未出现任何性能衰减。这一成果打破了现有的效率和稳定性纪录。","scd":null,"kp":["光电转换效率[钙钛矿三结太阳能电池]: 27.3%","稳定运行时长[钙钛矿三结太阳能电池无衰减]: 770小时","电池架构[三结太阳能电池]: 钙钛矿叠层结构"]},{"i":3906,"as":"美国开发商Peak Energy将在加利福尼亚州北部萨克拉门托建设美国首家完全专注于电网级钠离子储能系统制造的工厂。该工厂占地18.3万平方英尺，年产能达4吉瓦时，足以满足近400万户家庭的用电需求。工厂将配备被动冷却钠离子电池系统，据称该技术能将储能成本降低20%，旨在为公用事业公司提供大规模高容量设备。","scd":null,"kp":["年产能[美国钠离子电网存储工厂]: 4吉瓦时 (GWh)","设施面积[美国钠离子电网存储工厂]: 183,000平方英尺","供电覆盖规模[4GWh钠离子储能系统]: 近400万户家庭","技术路线[首个美国电网级储能工厂]: 纯钠离子电池"]},{"i":3907,"as":"莱斯大学与NASA联合推出了全球首个开源动态仿真平台“iMETRO动态仿真系统”，专为开发和测试用于航天器内部的机器人而设计。该平台创建了NASA约翰逊航天中心iMETRO研究设施的高保真数字孪生体，使全球研究人员能够在虚拟环境中开发、验证和优化航天器内机器人系统，加速未来载人航天任务的技术创新。","scd":null,"kp":["平台属性[空间机器人研发测试]: 世界首个开源动态模拟平台","核心技术[iMETRO动态模拟平台]: 创建NASA iMETRO设施的高保真数字孪生","应用场景[开源动态模拟平台]: 航天器及空间站舱内机器人系统开发与验证"]},{"i":3908,"as":"苏黎世联邦理工学院的研究团队成功研发出一种新型量子计算机芯片。该芯片摒弃了传统的电磁量子存储器，转而采用微小的机械谐振器，利用微观结构的机械振动来存储量子数据。这种受现代数字计算机启发、将处理与内存分离的架构，被视为克服当前量子计算领域最大挑战之一的创新方案。","scd":null,"kp":["存储机制[新型量子计算机芯片]: 微型机械谐振器振动","核心器件尺寸[振动量子存储器]: 0.3英寸计算机芯片","技术特点[量子存储器架构]: 采用受传统数字计算机启发的架构"]},{"i":3909,"as":"美国初创公司Longshot于2026年7月8日宣布加入美国空军新成立的AEDC速度联盟（AEDC Velocity Alliance）。该联盟由阿诺德工程发展综合体和空军测试中心创建，旨在提升美国高超音速和国防技术的测试基础设施。Longshot的发射器加速技术将为全尺寸高超音速系统的测试提供更具成本效益的解决方案。","scd":null,"kp":["行业联盟[美国高超音速测试]: AEDC Velocity Alliance","技术阶段[Longshot高超音速发射器]: 反复发射与测试","应用目标[高超音速发射器现代化]: 现代化美国高超音速测试基础设施"]},{"i":3910,"as":"德国卡尔斯鲁厄理工学院（KIT）的研究表明，铁粉末可作为化学能的有效载体，用于安全和低成本的全球可再生能源运输。研究团队探索了一种零碳排放的循环过程：铁粉末充当可运输的能源载体将风能和太阳能从偏远地区转移至需求地，燃烧后的产物可通过循环再次转化为铁粉末。该方案旨在解决太阳能和风能难以长距离大规模运输和储存的挑战。","scd":null,"kp":["化学储能载体[可再生能源运输]: 铁粉","循环特性[铁粉能量载体系统]: 零碳排放无环境破坏的碳中和循环","应用场景[铁粉储能运输]: 沿海风能与沙漠太阳能的移动载体"]},{"i":3911,"as":"中国交付了迄今为止起重能力最大的半潜式起重船“四航永盛”号。该船长110米，宽43.8米，甲板面积达4800平方米，配备了一台起重高度达566英尺的全旋转变幅起重机。该船具备重吊和海上运输双重功能，将主要用于支持跨海大桥、港口、海上风电场、海洋牧场以及深海资源勘探等大型海上工程的建设。","scd":null,"kp":["起重高度[四航永胜号半潜式起重船]: 566英尺","船舶地位[中国半潜式起重船]: 国内起重能力最大","工程应用[巨型半潜式起重船]: 跨海大桥、港口、海上风电场及深海资源勘探建设"]},{"i":3912,"as":"","scd":null,"kp":[]},{"i":3913,"as":"","scd":null,"kp":[]},{"i":3914,"as":"瑞典乌普萨拉大学的研究团队正在开发一种更环保的替代材料，以应对电动汽车、风力涡轮机和国防系统关键部件——稀土磁体供应链过于集中、环境代价高及地缘政治紧张等问题。目前中国在稀土加工和磁体生产领域占据主导地位。该研究旨在打破这一垄断，为全球清洁能源转型提供不受地缘政治制约的关键材料解决方案。","scd":null,"kp":["研发方向[替代稀土磁体]: 更环保的清洁替代材料","应对挑战[稀土磁体供应链]: 打破集中垄断并减少环境强度与地缘政治脆弱性","应用终端[稀土磁体]: 电动汽车、海上风电、智能手机及先进防御系统"]},{"i":3915,"as":"","scd":null,"kp":[]},{"i":3916,"as":"","scd":null,"kp":[]},{"i":3917,"as":"","scd":null,"kp":[]},{"i":3918,"as":"","scd":null,"kp":[]},{"i":3919,"as":"","scd":null,"kp":[]},{"i":3920,"as":"悉尼科技大学的研究人员发现，通过扭曲超薄六方氮化硼层，可以精确控制微小的量子光源。这种旋转堆叠材料层的方法能够有效调谐量子光发射体的行为，使其能够产生单光子。对量子发射体行为的精确控制是推动量子计算、安全通信和超灵敏传感器发展的关键一步。","scd":null,"kp":["[量子光源控制]: 扭转六方氮化硼超薄层叠层结构可精确调控量子光行为"]},{"i":3921,"as":"","scd":null,"kp":[]},{"i":3922,"as":"","scd":null,"kp":[]},{"i":3923,"as":"Open AI Infra社区在北京正式启动国内首个NPO光互连多源协议（MSA）及OPEN NPO项目。该项目由中国移动、百度、华为等数十家产业链代表共同发起，涵盖用户、算力设备、光电芯片等关键环节。此举填补了国内近封装光学开放标准的空白，旨在推动高速光电互连技术创新与跨厂商兼容，为AI时代高端算力基础设施演进提供支撑。","scd":null,"kp":["[近封装光学互连标准]: 国内首个NPO光互连MSA协议启动，填补产业空白","光电互连技术焦点[超节点近封装]: 聚焦核心领域共建开放标准"]},{"i":3924,"as":"西南石油大学科研团队研发出小尺寸超高效叠层太阳能电池，光电转换效率接近35%，远超常规极限。该成果基于硅基异质结技术，突破了纳晶硅氧薄膜和铜互联等核心技术。团队在校园和凉山州金阳县成功落地光伏发电项目，并有12项科研成果在相关企业实现商业化量产转化，有力推动了光伏产业技术创新。","scd":null,"kp":["转换效率[小尺寸超高效叠层太阳能电池]: 接近35%","核心技术[硅基异质结]: 采用纳晶硅氧薄膜及铜互联技术达到国际领先水平"]},{"i":3925,"as":"2026年7月全国电网代理购电价格呈现显著结构性变化。受浙江新版分时电价政策影响，该省尖谷价差同比下降21.45%；全国多地系统运行费翻倍上涨，压缩了工商业储能套利空间。地域分化加剧，西北地区电价大幅探底，而广东、上海等东南部地区峰谷价差依然坚挺，直接影响各地光储项目的收益评估。","scd":null,"kp":["尖峰-低谷价差[浙江2026年7月新政实测]: 0.7867元/千瓦时 (同比下降21.45%)","系统运行费[安徽]: 0.1478元/千瓦时 (同比上涨118%)","系统运行费[青海]: 同比上涨881%","代购电价[新疆]: 0.116元/千瓦时 (全国最低，同比下降55.33%)","峰谷价差[广东珠三角]: 高达1.2968元/千瓦时"]},{"i":3926,"as":"人工智能公司Anthropic针对来自中国的“后门”安全警告作出了官方回应。","scd":null,"kp":[]},{"i":3927,"as":"","scd":null,"kp":[]},{"i":3928,"as":"美国银行向人工智能研究公司OpenAI提供了一笔金额为5.2亿美元的贷款。","scd":null,"kp":["贷款金额[OpenAI]: 5.2亿美元"]},{"i":3929,"as":"SpaceXAI与Cursor联合发布了Grok 4.5人工智能模型，并强调该模型的使用成本低于其市场竞争对手。","scd":null,"kp":["[模型发布]: SpaceXAI与Cursor推出Grok 4.5且成本低于竞争对手"]},{"i":3930,"as":"美国政府此前设定了在独立日前后实现三个新微型核反应堆达到临界状态的目标。最终，有四家公司的反应堆按期达到这一能够维持链式反应的技术里程碑。这标志着美国新兴无排放核技术在增加电力供应和应对气候变化需求方面取得了积极进展，但距离正式并网发电仍需后续工作。","scd":null,"kp":["临界状态[美国新型微反应堆]: 达到临界（可维持链式反应）的数量为4个"]},{"i":3931,"as":"FZI信息技术研究中心与德国人工智能研究中心（DFKI）正式启动MoIn-LaMAS研究项目，致力于开发危机情况下的弹性通信新方法。该项目受德国网络局委托，重点研究危机环境下的自主机器人通信技术，旨在提升极端条件下的通信网络抗毁性和可靠性。","scd":null,"kp":[]},{"i":3932,"as":"慕尼黑工业大学创业实验室与Durst集团宣布在工业生产的机器人和人工智能领域建立多年合作伙伴关系。作为TUM网络的首个意大利合作伙伴，Durst将结合其在工业数字印刷与自动化方面的优势，与TUM的初创团队共同致力于解决数据驱动和工业自动化生产中的实际应用问题。","scd":null,"kp":["[工业生产应用]: TUM Venture Labs与Durst在机器人、AI和自动化领域开展多年合作"]},{"i":3933,"as":"Peak Energy公司将投资约7100万美元在加州萨克拉门托建设一座占地18.3万平方英尺的电网级钠离子电池储能工厂。该工厂年产能高达4 GWh，预计于2027年第一季度开始生产和出货。目前公司已获得超6 GWh的客户订单承诺，该项目的建设将创造数百个就业岗位。","scd":null,"kp":["年产能[加州电网级钠离子BESS工厂]: 4 GWh","建设成本[加州电网级钠离子BESS工厂]: 约7100万美元","客户承诺量[至2030年]: 超6 GWh","[加州工厂]: 预计2027年第一季度投产并出货"]},{"i":3934,"as":"西班牙可再生能源公司Grenergy通过其子公司在智利启动了一项反向拍卖，旨在采购1.5 TWh的年度可再生电力供应。其中包含夜间交付的960 GWh电池储能电力和日间供应的540 GWh太阳能发电。拍卖面向发电商和大型电力消费者，合同期可选6至15年，计划于2028年第二至第三季度开始交付。","scd":null,"kp":["夜间电池放电供应量[智利年度拍卖]: 960 GWh/年","日间太阳能发电供应量[智利年度拍卖]: 540 GWh/年","[智利反向拍卖]: 计划于2028年第二至第三季度开始交付"]},{"i":3935,"as":"天合光能计划在2026年向意大利交付1.4至1.6 GWh的电池储能系统（BESS）容量。意大利是天合光能仅次于英国的第二大BESS市场。目前公司正等待意大利MACSE储能容量拍卖结果，并预计今年在意大利供应约2 GW的太阳能组件，在当地的BESS和光伏组件市场份额均达到15%至20%。","scd":null,"kp":["BESS计划交付容量[2026年意大利市场]: 1.4 GWh至1.6 GWh","BESS市场排名[天合光能]: 意大利是其仅次于英国的第二大市场"]},{"i":3936,"as":"澳大利亚大维多利亚沙漠偏远社区安装了一套19 kW/61.4 kWh的偏远地区供电系统（RAPS），以替代老旧且高耗能的柴油发电系统。该系统核心为单相Victron MultiPlus-II逆变器/充电器，可提供15 kVA功率并支持未来扩容，由阿德莱德的MyEnergy Engineering公司设计，旨在满足当地原住民社区的大部分日常用电需求。","scd":null,"kp":["系统规模[澳大利亚偏远地区离网供电系统]: 19 kW/61.4 kWh"]},{"i":3937,"as":"正泰太阳能欧洲公司达成协议，向Flower基础设施技术公司出售位于德国五个联邦州的七个电池储能（BESS）项目。项目总容量为112兆瓦，单体容量介于6至48兆瓦之间，储能时长3至4小时。所有项目均已获批并网，计划于2027年内陆续投运。Flower将负责资产的所有权、融资及运营，正泰将提供EPC及长期运维服务。","scd":null,"kp":["单个项目容量范围[德国BESS项目组合]: 6 MW至48 MW","储能时长[德国BESS项目组合]: 3至4小时","[德国BESS项目组合]: 计划于2027年内逐步投运"]},{"i":3938,"as":"欧洲气候中和观察站（ECNO）报告指出，欧洲电网扩建、储能及灵活性建设未能跟上可再生能源的增长步伐。2025年太阳能和风能占欧盟发电量30%，但增速过慢，难以实现2030年58%的目标。报告强调，弃风弃光和电网灵活性限制是导致可再生能源份额增长缓慢的关键原因。","scd":null,"kp":["风光发电占比[2025年欧盟发电量]: 30%","[欧洲能源转型]: 电网扩张、储能和灵活性进展未能跟上可再生能源的增长步伐"]},{"i":3939,"as":"Polaris可再生能源公司与墨西哥联邦电力委员会（CFE）签署混合投资协议，共同开发三个光储一体化项目。项目总装机包括249兆瓦太阳能和61.6兆瓦/192兆瓦时储能，预计投资2.17亿美元。协议确立了30年联合开发及运营框架。其中最大的项目位于金塔纳罗奥州，包含132.57兆瓦光伏及33兆瓦/101.5兆瓦时储能。","scd":null,"kp":["太阳能装机容量[墨西哥光储项目组合]: 249 MW","电池储能容量[墨西哥光储项目组合]: 61.6 MW/192 MWh","预估投资额[墨西哥光储项目组合]: 2.17亿美元"]},{"i":3940,"as":"天津华电海晶1000兆瓦“盐光互补”光伏项目顺利完成全周期后评价。该项目于2023年底全容量并网，打造了“水上发电、水面产盐、水下养殖”立体发展模式。项目年均发电量约15亿千瓦时，每年节约标准煤超50万吨。其绿电市场化交易占比超95%，累计申报专利38项，是华电集团装机突破2亿千瓦的标志性工程。","scd":null,"kp":["装机容量[天津华电海晶盐光互补项目]: 1000兆瓦","年均发电量[天津华电海晶盐光互补项目]: 约15亿千瓦时","标准煤节约量[天津华电海晶盐光互补项目]: 每年超50万吨","绿电市场化交易占比[天津华电海晶盐光互补项目]: 超95%","专利申报数[天津华电海晶盐光互补项目]: 38项"]},{"i":3941,"as":"加拿大康考迪亚大学研发出“复合材料4D打印”新工艺，利用扁平碳纤维复合面板制造垂直风力涡轮机叶片。该工艺通过逆向设计推导材料排列，使材料在冷却时自然变形为所需弯曲形状。制成的叶片形状符合商用标准，重量比铝制叶片锐减80%，且使涡轮机转速显著提升，有效降低了制造成本、重量与周期。","scd":null,"kp":["重量减轻比例[新型复合材料涡轮叶片]: 相较铝叶片锐减80%","叶片成型工艺[新型风力涡轮机]: 复合材料4D打印结合逆向设计程序","[新型复合材料涡轮叶片]: 扁平碳纤维/环氧树脂层压板固化冷却后自然变形为所需弯曲形状，转速明显快于传统涡轮机"]},{"i":3942,"as":"南京大学周豪慎教授团队研发出一种引入“靶向配位反溶剂”的新型电解液，有效解决了锂金属电池充电时电解液不可逆分解的问题，抑制了锂枝晶的产生。测试数据显示，在450瓦时/千克和605瓦时/千克的高能量密度下，电池分别能稳定循环超过750次和150次。该成果提升了电池能量密度并显著延长寿命。","scd":null,"kp":["[锂金属电池]: 引入靶向配位反溶剂的新型电解液，主动捕捉正极释放的锂离子以保护溶剂化结构不被拆散","[新型电解液效果]: 显著提升能量密度并延长循环寿命，有效抑制锂枝晶生长和不可逆分解"]},{"i":3943,"as":"国家科学技术奖励大会、两院院士大会及中国科协第十次全国代表大会隆重召开。会议强调，党中央将科技创新摆在现代化建设突出位置，推动科技事业取得历史性成就。中国正加速从全球科技参与者向引领者转变，成为全球创新力上升最快的国家之一，向着高水平科技自立自强和科技强国目标坚定迈进。","scd":null,"kp":[]},{"i":3944,"as":"该情报聚焦于利用人工智能技术煎煮中药的创新模式。通过引入AI算法，重构并优化了传统中药的煎煮工艺，旨在将现代数字技术与传统古法相结合，提升中药煎煮的标准化与效率。","scd":null,"kp":[]},{"i":3945,"as":"荣耀终端股份有限公司机器人首席技术架构师严斌在国新办记者见面会上表示，未来几年将是人形机器人技术落地的重要时期。他期待联合产业界与学术界，将实验室中的人形机器人技术真正落地应用到实际的生产与生活场景中，从而助力国内人形机器人产业稳步向前发展。","scd":null,"kp":[]},{"i":3946,"as":"人工智能技术正加速在千行百业中落地应用。除基础的文字处理外，AI已被广泛应用于电助力自行车、外骨骼机器人、无人配送车和无人机等实体硬件中。这些应用不仅将人类从重复枯燥的流水线劳动中解放出来，大幅提升快递物流等环节的效率，还极大拓展了人类的身体能力边界。","scd":null,"kp":[]},{"i":3947,"as":"南京大学科研团队开发出新型电解液，通过引入“靶向配位反溶剂”，在充电时主动捕获正极释放的锂离子，阻止原有溶剂化结构被破坏，从而显著提升了锂金属电池的能量密度并延长循环寿命。在605瓦时/千克的超高能量密度下，电池仍能稳定循环150次。该成果为高能电池实用化提供了新思路。","scd":null,"kp":["电解液[锂金属电池]: 引入“靶向配位反溶剂”的新型局部高浓度电解液","电池寿命延寿机制[锂枝晶抑制]: 反溶剂在电极表面主动“接手”正极释放的锂离子，阻止其拆散原有溶剂化结构","应用潜力[下一代电子设备/新能源汽车]: 提升能量密度并显著延长循环寿命，有望推动实用化"]},{"i":3948,"as":"近年来中国科技创新跑出“中国速度”，高水平成果竞相涌现。文中列举了包括“神舟”“嫦娥”“天问”等深空探测任务，国产“人造太阳”创下“亿度千秒”世界纪录，105比特超导量子计算原型机“祖冲之三号”打破世界纪录，以及算力网纳入国家战略布局等里程碑事件，彰显了中国科技自立自强的步伐。","scd":null,"kp":[]},{"i":3949,"as":"受AI算力需求爆发驱动，2026年上半年全球存储芯片行业迎来超级景气周期，DRAM与NAND闪存价格大幅上涨并传导至消费端。长鑫科技与长江存储两大国内存储龙头实现业绩与市值攀升，产业集群加速成型。AI服务器单机内存搭载量激增，推动存储芯片从传统元器件转变为算力核心稀缺资源，当前供需紧张格局预计将延续。","scd":null,"kp":["价格涨幅[16GB DDR5内存终端]: 较2025年同期涨幅超130%","价格涨幅[1TB固态硬盘终端]: 较2025年同期涨幅超130%","行业周期[全球存储芯片]: 处于十五年一遇的AI算力需求驱动超级景气周期"]},{"i":3950,"as":"依托AI智能体和无代码工具，“一人公司”（OPC）模式迅速崛起。截至2025年6月，全国一人有限责任公司数量已超1600万家，占企业总量27.4%。凭借独立法人资格与AI协同，单人即可完成设计、运营等全链路商业闭环，极大降低了创业门槛与成本，推动企业组织形态发生深刻变革。","scd":null,"kp":["商业成本对比[OPC一人公司模式]: 1元AI成本等效于72元人力成本"]},{"i":3951,"as":"算力网已被纳入国家“六张网”战略性基础设施阵列，成为智能经济的关键底座。算力网旨在将分散的计算资源连成统一调度的“全国一张网”，流动的是计算任务与数据，以满足AI大模型训练、自动驾驶等多元场景需求。该建设开启了万亿级投资周期，有效带动了人工智能及工业互联网产业链的整体升级。","scd":null,"kp":[]},{"i":3952,"as":"人社部等四部门联合印发《关于加快推进“人工智能＋人社”应用发展的实施意见》。文件提出2027年普及一批人社大模型与智能体，探索50个高价值应用场景。计划于2026年建成应用基础设施及20个场景，到2030年实现AI在人社领域的普遍应用，并围绕就业、社保等6个方面规划了67个细分场景。","scd":null,"kp":["发展目标[2027年人社领域AI应用]: 普及应用一批大模型和智能体，探索50个左右高价值应用场景","建设目标[2026年人社领域基础设施]: 打造20个基于行业大模型的应用场景及相应高质量数据集"]},{"i":3953,"as":"随着AI技术发展，互联网正从信息互联向智能体互联演进，新一代网络基座加速成型。网络连接主体由人机物拓展至智能体，内容由字节升级为字节加词元（Token）。5G-A、6G等关键技术研发处于全球第一阵营，超大带宽与低时延需求正倒逼互联网架构全面转型，以适配海量智能体的高效交互。","scd":null,"kp":["网络架构跃迁[新一代网络基座]: 从信息互联向智能体互联转变","核心机制[网络算力融合]: 通信、计算和人工智能深度融合，实现Token“入网即入算”","技术研发进度[5G-A/6G]: 关键技术研发与国际标准研制均处于全球第一阵营"]},{"i":3954,"as":"Peak公司宣布将在美国萨克拉门托建设一座产能为4吉瓦时（GWh）的钠离子电池超级工厂。该举措将扩大其钠离子电池的制造规模，满足不断增长的新型储能市场需求。","scd":null,"kp":["产能规划[萨克拉门托钠离子电池工厂]: 4 GWh"]},{"i":3955,"as":"Metlen与Tsakos正式成立合资公司，共同开发位于希腊的252兆瓦太阳能及储能项目。该举措将推进当地可再生能源基础设施的建设与落地。","scd":null,"kp":["装机规模[希腊太阳能及储能合资项目]: 252 MW"]},{"i":3956,"as":"山东省能源局等部门联合印发《关于加强和规范绿电直连发展的通知》，提出优化管理方式、加大政策支持和规范实施程序三方面共11项具体措施。重点将源网荷储一体化、绿电产业园就地就近消纳模式统一按绿电直连模式管理。在电网无开放容量地区，允许通过分布式自发自用模式建设，投资主体需加装适当规模储能，确保不发生重过载及电压谐波越限。","scd":null,"kp":["实施时间[山东多用户绿电直连政策]: 2026年6月26日","[分布式集中汇流]: 参与多用户绿电直连"]},{"i":3957,"as":"本周国内多晶硅成交活跃度偏低，价格跌幅收窄并在低位小幅下探。行业库存高企且下游仅维持刚需采购，企业让价换量压制价格。因价格触及全行业现金成本区间，继续降价空间有限。供应端在产企业维持16家，前期复产产能放量预计推升产量。下游硅片开工率提升平缓，采购以刚需补库为主，市场延续小幅累库。新国标政策效应正强化落后产能出清预期。","scd":null,"kp":["价格跌幅[多晶硅市场]: 继续在低位区间小幅下探（跌幅有所收窄）","[行业现金成本]: 基本已触及全行业在产企业现金成本区间","[市场趋势]: 相对落后产能出清的预期不断强化"]},{"i":3958,"as":"云南省普洱市生态环境局公示华能澜沧江八十村茶光互补光伏发电项目环评。该项目总投资10.12亿元，选址景东县漫湾镇，占地351.96公顷。项目交流侧额定容量230MW，直流侧安装容量283.4832MWp，容配比1:1.2320。将安装660Wp单晶硅双面双玻组件429,520块，建设65个光伏方阵，施工工期为18个月。","scd":null,"kp":["总投资[华能云南八十村光伏项目]: 10.12亿元","额定容量[交流侧]: 230 MW","安装容量[直流侧]: 283.4832 MWp","容配比[八十村光伏项目]: 1:1.2320","组件规格[单晶硅双面双玻组件]: 峰值功率660 Wp"]},{"i":3959,"as":"隆基绿能ACM（纳米合金矩阵式接触）电池项目在西咸生产基地正式规模化量产。经认证，该电池效率达27.6%，组件功率达672瓦。量产导入使转换效率提升0.2%-0.3%，组件功率提升3-5瓦，已完成吉瓦级量产导入。围绕该技术，隆基已搭建涵盖核心材料、工艺与设备的全链条知识产权体系。多基地联动使新材料工厂产能爬坡周期缩短20天。","scd":null,"kp":["电池效率[隆基ACM电池]: 27.6%","组件功率[隆基ACM组件]: 672瓦","量产效率提升[ACM技术导入]: 0.2%-0.3%","组件功率提升[ACM技术导入]: 3-5瓦","研发周期[隆基ACM电池]: 近十年"]},{"i":3960,"as":"2025年全球多晶硅总产能约365万吨/年，同比增加7.5%；产量约148.5万吨，同比降低24.1%，其中太阳能级块状硅占比78.2%。中国多晶硅总产能347.9万吨/年，产量约136.7万吨，全球占比92.1%，连续15年居首。前十企业总产量占全球89.2%，世界前七企业均在中国。中国多晶硅进口量降至1.61万吨，进口依赖度降至1.2%。此外，海外太阳能级多晶硅产能已于2025年在中东等地启动建设。","scd":null,"kp":["总产能[2025年全球多晶硅]: 约365.0万吨/年","总产量[2025年全球多晶硅]: 约148.5万吨","产量[2025年全球电子级多晶硅]: 约5.5万吨（占比3.7%）","产量[2025年全球太阳能级块状硅]: 约116.1万吨（占比78.2%）","产量[2025年全球颗粒硅]: 约26.9万吨（占比18.1%）"]},{"i":3961,"as":"大全能源目前主营高纯多晶硅，具备年产30.5万吨高质量、低能耗的高纯多晶硅产能。受行业周期影响，公司目前产能利用率约50%，一季度产量4.3万吨，销量0.45万吨，期末存货19.5亿元。公司采取“锁量不锁价”长单模式与审慎销售策略以保障现金流安全。单晶硅片用料产量占总产量比例稳定在90%以上。公司正向AIDC配电领域延伸，以分散光伏行业周期波动带来的经营风险。","scd":null,"kp":["产能利用率[大全能源多晶硅]: 约50%","产量[大全能源一季度多晶硅]: 4.3万吨","销量[大全能源报告期内多晶硅]: 0.45万吨","存货[大全能源报告期末]: 19.5亿元"]},{"i":3962,"as":"国务院印发《“十五五”碳达峰行动方案》，部署5方面重点任务及多项重点工程。提出到2030年，单位GDP二氧化碳排放比2025年降低17%，非化石能源消费占比达25%。重点任务涵盖加快能源结构调整优化、推进产业绿色低碳转型、深化重点领域转型、强化支撑保障及凝聚各方合力。方案明确推进非化石能源开发、煤炭消费清洁替代与零碳园区建设，确保如期实现碳达峰目标。","scd":null,"kp":[]},{"i":3963,"as":"宁夏固原市彭阳县公示2025年农村公共机构分布式光伏电站收购价格，共涉及总装机规模7731.74kW的电站，审定收购总额约2072.33万元。该收购工作依据《彭阳县2025年农村公共机构分布式光伏电站公开收购工作方案》进行，经县分布式光伏收购工作领导小组会议审议通过。公示时间为2026年7月8日至10日。","scd":null,"kp":["收购规模[彭阳县农村公共机构光伏电站]: 7731.74 kW","收购总额[彭阳县光伏电站]: 约2072.33万元"]},{"i":3964,"as":"国家能源局河南监管办公室发布集中式新能源发电企业集中报价实施方案征求意见稿。方案明确，多个已注册的集中式风电、光伏发电企业可在同一固定场所参与电力中长期及现货交易集中报价。集中后总装机规模不应超过河南电力市场单个最大燃煤电厂装机规模。原则上仅允许同集团省内企业集中报价，禁止跨集团或跨省集中报价。企业参与集中报价不改变其独立市场地位、调度及结算关系。","scd":null,"kp":["适用范围[河南省集中报价方案]: 集中式新能源（风电、光伏）发电企业","[集中报价]: 多个集中式新能源发电企业在同一固定场所参与电能量集中交易和现货交易报价"]},{"i":3965,"as":"安徽庐江县发改委与县供电公司联合发布长期在途分布式光伏项目清理公告，拟对全县接入系统方案答复超一年且未开工的354个项目进行清理。项目涵盖非自然人户用、一般工商业及自然人户用，规模多在15kW至80kW之间。公示期为2026年7月7日至8月6日。如需继续建设，相关方须提交书面申请，并在申请后15日内开工，以现场安装逆变器或10%及以上光伏组件为开工标志。","scd":null,"kp":["清理项目数量[庐江县分布式光伏在途项目]: 354个","开工建设标志[分布式光伏项目]: 现场安装逆变器或安装10%及以上光伏组件","项目规模区间[庐江县清理项目]: 15 kW至80 kW"]},{"i":3966,"as":"为规范企业投资项目备案管理，当地针对备案后2年内未开工建设且未报告说明的项目进行清理公示。公示期为2026年7月1日至3日。此次共涉及204个光伏项目。公示期满后，若相关项目仍未向备案机关作出相应说明，将面临项目信息失效处理，其备案信息将被直接移除。","scd":null,"kp":["项目信息失效条件[备案类光伏项目]: 自备案后2年内未开工建设且未向备案机关作出说明","清理公示期[2年未开工光伏项目]: 2026年7月1日至2026年7月3日（3日）"]},{"i":3967,"as":"特斯拉第三代擎天柱人形机器人已初步定型，并下发具体零件采购指引。马斯克要求供应链在今年9月将产能提至1000台/周，年底提升至2000-2500台/周。目前供应商已收到8月数百台订单，据此估算年底将具备每年10万台零部件供应能力。弗里蒙特工厂已改造为机器人生产线。马斯克在高管会上要求年底达成产能目标，否则解雇整个采购团队，并指出初期生产将极其缓慢，高产量生产将在2027年展开。","scd":null,"kp":["Optimus Gen 3研发状态[特斯拉三代擎天柱人形机器人]: 研发三年多后初步定型，将走出实验室","零件采购产能目标[Optimus供应商今年9月]: 1000台/周","零件采购产能目标[Optimus供应商今年年底]: 2000-2500台/周","年供应能力目标[Optimus供应商今年年底]: 10万台Optimus零部件"]},{"i":3968,"as":"","scd":null,"kp":[]},{"i":3969,"as":"SpaceX及AI公司创纪录的IPO带来的财富效应，显著推动了私人航空需求增长。SpaceX IPO筹集857亿美元，为投资人及早期员工创造了巨大财富，直接带动科技新贵购买私人飞机热潮。一家航空法律公司业务量因此跃升25%。数据显示，2026年前五个月，全球私人飞机共享航班量同比增长11.8%，机主运营航班量增长13.4%，私人航空成为AI热潮的早期受益行业。","scd":null,"kp":["筹集资金[SpaceX首次公开招股]: 857亿美元"]},{"i":3970,"as":"","scd":null,"kp":[]},{"i":3971,"as":"安全公司Jamf披露，黑客伪造了苹果macOS平台剪贴板管理工具Maccy的官网，并通过搜索引擎竞价排名诱导用户下载带有恶意木马PamStealer的安装包。用户运行后，软件内置的AppleScript脚本会调用系统PAM认证机制骗取管理员密码，随后下载Rust编写的PamStealer木马。该木马伪装成系统访达，搜集浏览器数据、加密货币钱包及剪贴板等敏感信息，加密后上传至黑客服务器用于勒索。","scd":null,"kp":["攻击触发机制[PamStealer恶意木马]: 唤出系统原生管理员密码输入窗口，要求用户输入管理员密码","木马特性[PamStealer恶意木马]: 使用Rust编写，伪装成访达（Finder），搜集浏览器数据、加密货币钱包、剪贴板等敏感信息并加密上传","传播机制[PamStealer恶意木马]: 搭建仿冒Maccy官网并利用搜索引擎竞价排名刊载广告诱骗下载"]},{"i":3972,"as":"美国加州大学圣迭戈分校团队利用两台宇树G1人形机器人，成功完成两例大型非灵长类哺乳动物活体胆囊切除手术。手术均由外科医生通过控制台远程操控机器人实施。相比重达1800磅的传统专用手术系统，人形机器人体积小巧且可移动，适用于偏远医疗匮乏地区。但目前技术仍需解决手术中多次重新校准导致耗时长，以及远程操控带来的控制延迟等问题。研究成果已发表于《Nature》。","scd":null,"kp":["系统重量[专用手术系统]: 约816.5千克（1800磅）","远程手术应用[宇树G1人形机器人]: 成功完成两例大型非灵长类哺乳动物活体胆囊切除手术","当前缺陷[远程操控人形机器人手术]: 过程需多次重新校准，耗费时间长，存在控制延迟"]},{"i":3973,"as":"","scd":null,"kp":[]},{"i":3974,"as":"Meta正式向开发者开放Muse Spark AI模型API，并发布升级版Muse Spark 1.1。该模型在真实世界编程和AI智能体任务方面能力最强，具备操作软件、调用外部工具及理解文本、图片和视频等多模态内容的能力。开发者注册可获得20美元免费额度，正式按量付费标准为每百万输入Token收费1.25美元，每百万输出Token收费4.25美元。此举标志Meta正式加入AI模型商业化竞争。","scd":null,"kp":["核心能力[Muse Spark 1.1 AI模型]: 操作软件及调用外部工具、理解文本图片视频内容、更少人工干预完成复杂多步骤任务"]},{"i":3975,"as":"马斯克表示，SpaceX创纪录的估值及上市已让公司数千名生产线员工成为百万富翁。SpaceX在6月上市后市值约达2万亿美元，马斯克个人财富一度突破1万亿美元。公司秉持员工持股理念，并在每年两次的私募流动性交易中允许员工出售持股套现。上市前机构预测此次IPO将创造约4400名百万富翁及400多名身家过亿美元的富豪。","scd":null,"kp":["市值[SpaceX上市]: 约2万亿美元","持股价值[SpaceX早期加入的生产线员工]: 超过100万美元（跻身百万富翁）"]},{"i":3976,"as":"索尼发布黑卡RX10V长焦相机，国行售价15199元，8月初上市。该机搭载2010万像素1英寸堆栈式传感器和双BIONZ XR处理器，配备等效24-600mm镜头。采用重新设计的机身，配备368万点EVF和162万点LCD屏幕，接口升级为USB-C 10Gbps。支持每秒30张连拍和AI智能主体识别对焦，可拍摄无裁切4K 60p视频。电池升级为NP-FZ100，支持5GHz双频Wi-Fi。","scd":null,"kp":[]},{"i":3977,"as":"","scd":null,"kp":[]},{"i":3978,"as":"AMD首席技术官确认，将于7月22日至23日在旧金山举行的Advancing AI 2026活动上推出基于“Zen 6”微架构的新一代处理器。AMD自2017年推出Zen架构以来已迈入第六代，新一代产品将延续x86 CPU的领先地位，并针对传统的独立x86工作负载进行优化设计。","scd":null,"kp":["发布时间[AMD Zen 6微架构处理器]: 2026年7月22日-23日","设计理念[Zen 6微架构处理器]: 针对独立的传统x86工作负载进行了优化"]},{"i":3979,"as":"","scd":null,"kp":[]},{"i":3980,"as":"京东快递宣布CBD商务寄件服务全面升级，推出行业首创的寄文件证照赠送千元保价服务。文件类快件采用专用信封箱单独封装，并配备短信验证码及派件身份验证。京东为一线员工100%签订劳动合同并缴纳五险一金，目前已投入超20万个信封中转箱专项适配文件证照类快件，保障寄递安全。","scd":null,"kp":["保价服务[京东快递文件证照类]: 免费赠送千元保价","中转箱投入量[京东快递CBD服务升级]: 超20万个信封中转箱","用工规范[京东物流一线员工]: 100%签订劳动合同、100%交齐五险一金、100%正式员工福利"]},{"i":3981,"as":"印度政府宣布取消部分手机及电子设备零部件的进口关税，免除此前5%至7.5%的税率。免税产品涵盖手机无线充电模块、医疗设备、汽车显示屏及锂离子电芯等关键零部件，政策持续至2029年3月底。此举旨在降低苹果、小米等企业的制造成本，提升印度电子制造业本土化水平及竞争力。","scd":null,"kp":["进口关税免除[印度手机及电子设备零部件]: 免除7.5%和5%的税率","免税政策期限[印度手机及电子设备零部件]: 持续至2029年3月31日","产业规模目标[印度2030财年电子制造业]: 5000亿美元","智能手机产值[印度2024/25财年]: 5.45万亿卢比（约3902.96亿元人民币）"]},{"i":3982,"as":"华硕发布全新三模显示器ROG绝神27 PLUS。该显示器采用27英寸Fast IPS LCD面板，支持三档智能像素增强技术，可在UHD 240Hz、QHD 400Hz和FHD 488Hz三种模式间切换。产品配备动态准星及动态阴影增强等游戏辅助技术，并提供DisplayPort 1.4、HDMI 2.1及USB-C接口。","scd":null,"kp":["显示器面板[ROG绝神27PLUS]: 27英寸 Fast IPS LCD","刷新率[UHD模式]: 240Hz","刷新率[QHD模式]: 400Hz","刷新率[FHD模式]: 488Hz","接口配置[ROG绝神27PLUS]: DisplayPort 1.4、HDMI 2.1、USB-C"]},{"i":3983,"as":"","scd":null,"kp":[]},{"i":3984,"as":"","scd":null,"kp":[]},{"i":3985,"as":"","scd":null,"kp":[]},{"i":3986,"as":"三星电子正研发基于4nm制程的AI PC芯片“Gaia”，目标于明年量产，以期时隔10余年重返PC芯片市场。该芯片采用优化的NPU架构，专为AI计算设计。目前工程样片已交付全球各大PC制造商进行性能验证。此举旨在抢占AI PC及物理AI市场，弥补2012年Exynos芯片在Chromebook上失败的业务空白。","scd":null,"kp":["[三星AI PC芯片]: 代号Gaia，采用优化的NPU架构，计划明年量产并时隔10余年重返PC芯片市场","[研发状态]: 已交付工程样片给全球各大PC制造商进行性能验证"]},{"i":3987,"as":"韩国媒体报道，LG新能源正准备在其中国南京工厂投产新的圆柱形电池生产线，以增加对特斯拉的电池供应。两条新生产线将于今年下半年投产，单线年产能约2GWh，后续总产能有望达两位数GWh。此次扩产主要是为满足特斯拉，特别是Model Y日益增长的电动车需求。","scd":null,"kp":["单线产能[LG新能源南京工厂圆柱电池产线]: 约2 GWh/年","投产计划[新增产线]: 今年下半年投产"]},{"i":3988,"as":"由余海军和谢英豪带领的中国广东邦普循环科技研究团队，荣获欧洲专利局（EPO）2026年欧洲发明家奖。该团队开发的“智能电池回收”技术能够从废旧锂离子电池中再生高质量的阴极材料。此外，该团队还获得了由公众和陪审团投票选出的“大众奖”。","scd":null,"kp":["[技术荣誉]: 中国“智能电池回收”技术荣获2026年欧洲专利局（EPO）欧洲发明者创新奖"]},{"i":3989,"as":"Wendy McMillan被任命为Trafigura旗下Nyrstar澳大利亚业务的首席执行官，于7月6日正式上任。McMillan在领导复杂资产密集型组织方面经验丰富，曾担任轨道交通运输制造商Bombardier Transportation及铁路技术公司Wabtec Corporation的高级区域领导职务，并曾出任维多利亚州交通署轨道交通部门首席执行官。","scd":null,"kp":[]},{"i":3990,"as":"Clarios宣布其位于德国茨维考的工厂成功下线第1亿块AGM电池。该工厂拥有120年历史，自2002年开始生产AGM电池，目前是Clarios最大的AGM电池生产工厂。为纪念这一里程碑，萨克森州州长与Clarios EMEA总裁共同为这块具有象征意义的电池签名。","scd":null,"kp":["生产里程碑[德国茨维考工厂AGM电池]: 累计产量达1亿个"]},{"i":3991,"as":"铅电池制造商Eternity Technologies宣布，其位于印度维杰亚瓦达的新工厂已开始向客户交付首批电池。该公司于2025年2月收购该工厂，旨在满足印度及东南亚地区电动叉车和储能设备日益增长的需求。随着产能逐步提升，公司已按计划开始向当地及东南亚市场出货。","scd":null,"kp":["[业务动态]: Eternity Technologies开始从其印度新工厂（维杰亚瓦达）交付首批铅电池"]},{"i":3992,"as":"古巴迎来首家电池储能系统（BESS）初创测试阶段，以应对美国能源封锁导致的严重停电问题。国有电力公司在哈瓦那El Cotorro变电站成功启动首个50MW BESS单元测试。该项目属于国家BESS-太阳能计划的一部分，计划安装另外三套类似储能系统，总贡献达200MW，为古巴提供能源保障。","scd":null,"kp":["储能规模[古巴哈瓦那BESS项目]: 200MW","[项目状态]: 已进入测试启动阶段以应对能源封锁和停电问题"]},{"i":3993,"as":"Sicona Battery Technologies获得澳大利亚可再生能源署最高4500万澳元资金支持，用于在新南威尔士州建设先进硅碳电池负极材料的商业规模制造工厂。该硅碳负极材料采用机械工艺生产，相较于硅烷工艺更具安全性、可扩展性及成本优势，其能量密度是传统材料的4.5倍以上。","scd":null,"kp":["资金支持[澳大利亚硅碳电池负极材料制造演示]: 高达4500万澳元（约3100万美元）"]},{"i":3994,"as":"意大利能源巨头埃尼集团投资2.25亿美元，获得智利“黑色巨人”锂项目的少数股权。该项目计划前两期实现年产5.25万吨碳酸锂产能，有望成为全球最大的锂生产商之一。作为回报，埃尼将获得该项目未来约25%的锂产量权益。开发商EnergyX已落实多项战略承购协议。","scd":null,"kp":["投资金额[埃尼投资智利锂项目Project Black Giant]: 2.25亿美元（收购少数股权）","产能规划[前两期碳酸锂生产]: 每年高达52,500吨"]},{"i":3995,"as":"DHL发布了《DHL贸易地图集》，探讨重塑物流行业的趋势以及领导者需要应对的准备。全球贸易和物流在面临持续中断的同时，采用新工具提升韧性，贸易路线被重写。该地图集汇总全球数据，在当前地缘政治气候下为供应链提供至关重要的战略图谱参考。","scd":null,"kp":[]},{"i":3996,"as":"丰田旗下雷克萨斯正在研发全电动LFA跑车概念车，该车与丰田GR GT和GR GT3赛车共享大多数结构组件，并将V8发动机替换为纯电动动力系统。丰田尚未公布具体细节，但雷克萨斯LFA预计将成为首款搭载丰田固态电池的车型。固态电池技术承诺提供更高的性能表现。","scd":null,"kp":[]},{"i":3997,"as":"澳大利亚电动汽车销量创历史新高。2026年6月数据显示，首次有7款电动汽车单月销量突破1000辆，且这7款车型全部为中国品牌或中国制造。其中，上海生产的特斯拉Model Y位居榜首，比亚迪Sealion 7紧随其后，另有五款中国新车型进入榜单前列。特斯拉Model 3则滑落至第12位。","scd":null,"kp":[]},{"i":3998,"as":"比亚迪储能成功拿下阿布扎比马斯达尔“全天候”(RTC)项目的11.275 GWh电池储能订单，这是史上规模最大的单一储能采购合同之一。该项目配套5.2吉瓦太阳能阵列和总容量19 GWh的电池系统，建成后将跻身全球最大的太阳能加储能综合体，旨在实现吉瓦级别的全天候24小时清洁能源稳定供应。","scd":null,"kp":["电池订单容量[比亚迪供应阿布扎比RTC项目]: 11.275 GWh","总储能规模[全球最大太阳能+储能项目]: 19 GWh","光伏装机容量[RTC项目配套]: 5.2 GW"]},{"i":3999,"as":"雅马哈正式在印度市场推出运动型Aerox-E电动踏板车。新车延续燃油版的运动外观与肌肉线条，搭载全新的纯电驱动系统。其配备峰值功率9.4千瓦的电机，最大扭矩达48牛·米，主打高端性能市场。新车舍弃了极致的低价策略，转而提供高端配置，使其成为该国市场上售价最高的踏板车之一。","scd":null,"kp":[]}]);